## 1) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var icon: String
    var colorHex: String
    var createdAt: Date
    var completionDates: [Date]

    init(id: UUID = UUID(),
         name: String,
         icon: String = "checkmark.circle",
         colorHex: String = "#4CAF50",
         createdAt: Date = Date(),
         completionDates: [Date] = []) {
        self.id = id
        self.name = name
        self.icon = icon
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var streak: Int {
        let sortedDates = completionDates
            .map { Calendar.current.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            guard let expectedPrevious = Calendar.current.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            if Calendar.current.isDate(date, inSameDayAs: expectedPrevious) {
                streakCount += 1
                currentDate = date
            } else {
                break
            }
        }

        return streakCount
    }

    func completedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }
}
```

