## 1) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var streak: Int
    var completions: [Date]

    init(id: UUID = UUID(), name: String, streak: Int = 0, completions: [Date] = []) {
        self.id = id
        self.name = name
        self.streak = streak
        self.completions = completions
    }

    mutating func markCompletedToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let lastCompletion = completions.last {
            let lastDay = Calendar.current.startOfDay(for: lastCompletion)
            if lastDay == today { return }

            let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: today)!
            if lastDay == yesterday {
                streak += 1
            } else {
                streak = 1
            }
        } else {
            streak = 1
        }

        completions.append(Date())
    }

    var didCompleteToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.startOfDay(for: $0) == today }
    }
}
```

