## 1) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    var id: UUID = UUID()
    var name: String
    var icon: String
    var colorHex: String
    var createdAt: Date = Date()
    var completionDates: [Date] = []

    mutating func markCompletedToday() {
        let today = Calendar.current.startOfDay(for: Date())
        let alreadyCompleted = completionDates.contains {
            Calendar.current.isDate($0, inSameDayAs: today)
        }
        if !alreadyCompleted {
            completionDates.append(Date())
        }
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains {
            Calendar.current.isDate($0, inSameDayAs: today)
        }
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var currentStreak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: expectedDate) {
                currentStreak += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previousDay
            } else if date < expectedDate {
                break
            }
        }

        return currentStreak
    }
}
```

