### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var title: String
    var details: String
    var createdAt: Date

    // Track completion dates
    var completionDates: [Date]

    init(title: String, details: String = "") {
        self.id = UUID()
        self.title = title
        self.details = details
        self.createdAt = Date()
        self.completionDates = []
    }

    func completeToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        let alreadyCompletedToday = completionDates.contains {
            calendar.isDate($0, inSameDayAs: today)
        }

        if !alreadyCompletedToday {
            completionDates.append(Date())
        }
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDate($0, inSameDayAs: Date()) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 1
        var currentDate = sortedDates[0]

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }
}
