### `Habit.swift`
```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var emoji: String
    var colorHex: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        emoji: String = "✅",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.emoji = emoji
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        Calendar.current.isDate(completedDates.first ?? .distantPast, inSameDayAs: date) ||
        completedDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: date) })
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        if let index = completedDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(date)
        }
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var count = 0
        var currentDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)
            if calendar.isDate(day, inSameDayAs: currentDate) {
                count += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previousDay
            } else if day < currentDate {
                break
            }
        }

        return count
    }
}
```

