import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var iconName: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        iconName: String = "checkmark.circle",
        createdAt: Date = .now,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.iconName = iconName
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    func markCompletedToday() {
        let today = Calendar.current.startOfDay(for: Date())
        if !completionDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completionDates.append(today)
        }
    }

    func isCompletedToday() -> Bool {
        let today = Date()
        return completionDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) })
    }

    func totalCompletions() -> Int {
        completionDates.count
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            guard let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
                  calendar.isDate(date, inSameDayAs: expected) else {
                break
            }
            streak += 1
            currentDate = date
        }

