## 2) `Models/Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var emoji: String
    var createdAt: Date
    var completions: Set<String> // YYYY-MM-DD strings

    init(id: UUID = UUID(),
         name: String,
         emoji: String = "✅",
         createdAt: Date = Date(),
         completions: Set<String> = []) {
        self.id = id
        self.name = name
        self.emoji = emoji
        self.createdAt = createdAt
        self.completions = completions
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        completions.contains(Self.dayKey(from: date))
    }

    static func dayKey(from date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }

    func currentStreak() -> Int {
        let calendar = Calendar.current
        var streak = 0
        var currentDate = Date()

        while true {
            let key = Self.dayKey(from: currentDate)
            if completions.contains(key) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previous
            } else {
                break
            }
        }

        return streak
    }
}
```

