## 2) Data model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var habitDescription: String
    var createdAt: Date
    var isArchived: Bool
    var completions: [HabitCompletion]

    init(name: String, habitDescription: String = "") {
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.isArchived = false
        self.completions = []
    }
}

@Model
final class HabitCompletion {
    var date: Date
    var habit: Habit?

    init(date: Date = Date(), habit: Habit? = nil) {
        self.date = date
        self.habit = habit
    }
}
```

