## 5) Habit row

### `HabitRowView.swift`
```swift
import SwiftUI

struct HabitRowView: View {
    let habit: Habit

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completions.contains {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }
    }

    var body: some View {
        HStack {
            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)

                if !habit.habitDescription.isEmpty {
                    Text(habit.habitDescription)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }

                Text("Streak: \(habitStreak(habit))")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Image(systemName: completedToday ? "checkmark.circle.fill" : "circle")
                .foregroundStyle(completedToday ? .green : .gray)
        }
        .padding(.vertical, 4)
    }

    private func habitStreak(_ habit: Habit) -> Int {
        let calendar = Calendar.current
        let sortedDates = habit.completions.map(\.date).sorted(by: >)

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let completionDay = calendar.startOfDay(for: date)

            if completionDay == currentDay {
                streak += 1
                currentDay = calendar.date(byAdding: .day, value: -1, to: currentDay)!
            } else if completionDay < currentDay {
                break
            }
        }

        return streak
    }
}
```

