## 7) Habit detail view

### `HabitDetailView.swift`
```swift
import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completions.contains {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }
    }

    var body: some View {
        Form {
            Section("Habit") {
                TextField("Name", text: $habit.name)
                TextField("Description", text: $habit.habitDescription, axis: .vertical)
                    .lineLimit(3...6)
            }

            Section("Today") {
                Button {
                    toggleTodayCompletion()
                } label: {
                    HStack {
                        Text(completedToday ? "Mark as incomplete" : "Mark as complete")
                        Spacer()
                        Image(systemName: completedToday ? "checkmark.circle.fill" : "circle")
                            .foregroundStyle(completedToday ? .green : .gray)
                    }
                }
            }

            Section("Stats") {
                LabeledContent("Created", value: habit.createdAt.formatted(date: .abbreviated, time: .omitted))
                LabeledContent("Total Completions", value: "\(habit.completions.count)")
                LabeledContent("Current Streak", value: "\(streak())")
            }

            Section("Completions") {
                if habit.completions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(habit.completions.sorted(by: { $0.date > $1.date }), id: \.date) { completion in
                        Text(completion.date.formatted(date: .abbreviated, time: .omitted))
                    }
                }
            }
        }
        .navigationTitle(habit.name)
    }

    private func toggleTodayCompletion() {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            habit.completions.append(completion)
            modelContext.insert(completion)
        }
    }

    private func streak() -> Int {
        let calendar = Calendar.current
        let sortedDates = habit.completions.map(\.date).sorted(by: >)

        var streak = 0
        var currentDay = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let completionDay = calendar.startOfDay(for: date)

            if completionDay == currentDay {
                streak += 1
                currentDay = calendar.date(byAdding: .day, value: -1, to: currentDay)!
            } else if completionDay < currentDay {
                break
            }
        }

        return streak
    }
}
```

