### `ContentView.swift`
```swift
import SwiftUI

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var isCompletedToday: Bool
}

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let saveKey = "saved_habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String) {
        let habit = Habit(id: UUID(), name: name, isCompletedToday: false)
        habits.append(habit)
    }

    func toggleCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index].isCompletedToday.toggle()
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    private func saveHabits() {
        guard let encoded = try? JSONEncoder().encode(habits) else { return }
        UserDefaults.standard.set(encoded, forKey: saveKey)
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: saveKey),
              let decoded = try? JSONDecoder().decode([Habit].self, from: data) else {
            return
        }
        habits = decoded
    }
}

struct ContentView: View {
    @StateObject private var store = HabitStore()
    @State private var newHabitName = ""
    @State private var showingAddHabit = false

    var body: some View {
        NavigationView {
            List {
                ForEach(store.habits) { habit in
                    HStack {
                        Button(action: {
                            store.toggleCompletion(for: habit)
                        }) {
                            Image(systemName: habit.isCompletedToday ? "checkmark.circle.fill" : "circle")
                                .foregroundColor(habit.isCompletedToday ? .green : .gray)
                        }
                        .buttonStyle(BorderlessButtonStyle())

                        Text(habit.name)
                            .strikethrough(habit.isCompletedToday, color: .gray)

                        Spacer()
                    }
                }
                .onDelete(perform: store.deleteHabits)
            }
            .navigationTitle("Habit Tracker")
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button {
                        showingAddHabit = true
                    } label: {
                        Image(systemName: "plus")
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView(newHabitName: $newHabitName) { name in
                    store.addHabit(name: name)
                    newHabitName = ""
                    showingAddHabit = false
                }
            }
        }
    }
}

struct AddHabitView: View {
    @Binding var newHabitName: String
    let onAdd: (String) -> Void

    var body: some View {
        NavigationView {
            Form {
                TextField("Habit name", text: $newHabitName)
            }
            .navigationTitle("New Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        newHabitName = ""
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Add") {
                        let trimmed = newHabitName.trimmingCharacters(in: .whitespacesAndNewlines)
                        guard !trimmed.isEmpty else { return }
                        onAdd(trimmed)
                    }
                }
            }
        }
    }
}
```

