```kotlin
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.launch

class BankingViewModel(
    private val repo: BankingRepository
) : ViewModel() {

    var loginState: String = "Logged out"
        private set

    var accounts: List<Account> = emptyList()
        private set

    var transactions: List<Transaction> = emptyList()
        private set

    fun login(username: String, password: String, onResult: (Boolean) -> Unit) {
        viewModelScope.launch {
            try {
                val success = repo.login(username, password)
                loginState = if (success) "Logged in" else "Login failed"
                onResult(success)
            } catch (e: Exception) {
                loginState = "Login failed: ${e.message}"
                onResult(false)
            }
        }
    }

    fun loadAccounts() {
        viewModelScope.launch {
            accounts = repo.getAccounts()
        }
    }

    fun loadTransactions(accountId: String) {
        viewModelScope.launch {
            transactions = repo.getTransactions(accountId)
        }
    }
}
