```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.model.TransactionType
import com.example.bankapp.data.model.TransferRequest
import kotlinx.coroutines.delay

class FakeBankRepository : BankRepository {

    private val accounts = listOf(
        Account(id = "1", name = "Everyday Checking", balance = 5420.75),
        Account(id = "2", name = "Savings", balance = 18240.12)
    )

    private val transactions = listOf(
        Transaction("t1", "Coffee Shop", "Card purchase", -5.75, TransactionType.DEBIT, System.currentTimeMillis()),
        Transaction("t2", "Payroll", "Salary deposit", 5200.00, TransactionType.CREDIT, System.currentTimeMillis() - 86400000),
        Transaction("t3", "Electric Bill", "Utility payment", -120.40, TransactionType.DEBIT, System.currentTimeMillis() - 172800000)
    )

    override suspend fun login(username: String, password: String): Boolean {
        delay(800)
        return username.isNotBlank() && password.isNotBlank()
    }

    override suspend fun getAccounts(): List<Account> {
        delay(500)
        return accounts
    }

    override suspend fun getRecentTransactions(): List<Transaction> {
        delay(500)
        return transactions
    }

    override suspend fun transferFunds(request: TransferRequest): Result<Unit> {
        delay(1000)
        return if (request.amount > 0) {
            Result.success(Unit)
        } else {
            Result.failure(IllegalArgumentException("Amount must be greater than zero"))
        }
    }

    override suspend fun logout() {
        delay(200)
    }
}
