package com.example.bankapp.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.model.TransferRequest
import com.example.bankapp.data.repository.BankRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

data class TransferUiState(
    val isLoading: Boolean = false,
    val successMessage: String? = null,
    val errorMessage: String? = null
)

class TransferViewModel(
    private val repository: BankRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(TransferUiState())
    val uiState: StateFlow<TransferUiState> = _uiState

    fun submitTransfer(fromAccountId: String, toAccountNumber: String, amount: Double, note: String) {
        viewModelScope.launch {
            _uiState.value = TransferUiState(isLoading = true)
            try {
                val result = repository.transferFunds(
                    TransferRequest(
                        fromAccountId = fromAccountId,
                        toAccountNumber = toAccountNumber,
                        amount = amount,
                        note = note
                    )
                )
                _uiState.value = if (result.isSuccess) {
                    TransferUiState(successMessage = "Transfer submitted successfully")
                } else {
                    TransferUiState(errorMessage = result.exceptionOrNull()?.message ?: "Transfer failed")
                }
            } catch (e: Exception) {
                _uiState.value = TransferUiState(errorMessage = e.message ?: "Transfer failed")
            }
        }
    }
}
