# 6) Navigation

## `BankNavGraph.kt`
```kotlin
package com.example.bankapp.navigation

import androidx.compose.runtime.Composable
import androidx.navigation.NavHostController
import androidx.navigation.compose.*
import com.example.bankapp.ui.screens.DashboardScreen
import com.example.bankapp.ui.screens.LoginScreen
import com.example.bankapp.ui.screens.TransferScreen
import com.example.bankapp.viewmodel.AuthViewModel
import com.example.bankapp.viewmodel.DashboardViewModel
import com.example.bankapp.viewmodel.TransferViewModel

@Composable
fun BankNavGraph(
    navController: NavHostController,
    authViewModel: AuthViewModel,
    dashboardViewModel: DashboardViewModel,
    transferViewModel: TransferViewModel
) {
    val authState = authViewModel.uiState.collectAsState().value
    val dashboardState = dashboardViewModel.uiState.collectAsState().value
    val transferState = transferViewModel.uiState.collectAsState().value

    NavHost(navController = navController, startDestination = "login") {
        composable("login") {
            LoginScreen(
                isLoading = authState.isLoading,
                errorMessage = authState.errorMessage,
                onLogin = { username, password ->
                    authViewModel.login(username, password)
                }
            )

            LaunchedEffect(authState.isLoggedIn) {
                if (authState.isLoggedIn) {
                    dashboardViewModel.loadDashboard()
                    navController.navigate("dashboard") {
                        popUpTo("login") { inclusive = true }
                    }
                }
            }
        }

        composable("dashboard") {
            DashboardScreen(
                isLoading = dashboardState.isLoading,
                accounts = dashboardState.accounts,
                transactions = dashboardState.transactions,
                errorMessage = dashboardState.errorMessage,
                onTransferClick = { navController.navigate("transfer") }
            )
        }

        composable("transfer") {
            TransferScreen(
                isLoading = transferState.isLoading,
                successMessage = transferState.successMessage,
                errorMessage = transferState.errorMessage,
                onSubmit = { fromId, toAcc, amt, note ->
                    transferViewModel.submitTransfer(fromId, toAcc, amt, note)
                }
            )
        }
    }
}
