```kotlin
package com.example.minibank

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.foundation.text.KeyboardOptions
import java.text.NumberFormat
import java.util.Locale

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme {
                BankingApp()
            }
        }
    }
}

data class Transaction(
    val type: String,
    val amount: Double,
    val balanceAfter: Double
)

@Composable
fun BankingApp() {
    var balance by remember { mutableStateOf(1000.0) }
    var amountText by remember { mutableStateOf("") }
    var transactions by remember { mutableStateOf(listOf<Transaction>()) }
    var message by remember { mutableStateOf("Welcome to MiniBank") }

    val formatter = remember {
        NumberFormat.getCurrencyInstance(Locale.US)
    }

    fun parsedAmount(): Double? = amountText.toDoubleOrNull()?.takeIf { it > 0 }

    fun recordTransaction(type: String, amount: Double, newBalance: Double) {
        transactions = listOf(
            Transaction(type, amount, newBalance)
        ) + transactions
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(20.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        Text("MiniBank", style = MaterialTheme.typography.headlineMedium)
        Text("Balance: ${formatter.format(balance)}", style = MaterialTheme.typography.headlineSmall)
        Text(message, style = MaterialTheme.typography.bodyLarge)

        OutlinedTextField(
            value = amountText,
            onValueChange = { amountText = it },
            label = { Text("Amount") },
            keyboardOptions = KeyboardOptions(
                keyboardType = KeyboardType.Decimal,
                imeAction = ImeAction.Done
            ),
            singleLine = true,
            modifier = Modifier.fillMaxWidth()
        )

        Row(
            horizontalArrangement = Arrangement.spacedBy(12.dp),
            modifier = Modifier.fillMaxWidth()
        ) {
            Button(
                onClick = {
                    val amount = parsedAmount()
                    if (amount == null) {
                        message = "Enter a valid amount."
                    } else {
                        balance += amount
                        recordTransaction("Deposit", amount, balance)
                        message = "Deposited ${formatter.format(amount)}"
                        amountText = ""
                    }
                },
                modifier = Modifier.weight(1f)
            ) {
                Text("Deposit")
            }

            Button(
                onClick = {
                    val amount = parsedAmount()
                    if (amount == null) {
                        message = "Enter a valid amount."
                    } else if (amount > balance) {
                        message = "Insufficient funds."
                    } else {
                        balance -= amount
                        recordTransaction("Withdraw", amount, balance)
                        message = "Withdrew ${formatter.format(amount)}"
                        amountText = ""
                    }
                },
                modifier = Modifier.weight(1f)
            ) {
                Text("Withdraw")
            }
        }

        Divider()

        Text("Transactions", style = MaterialTheme.typography.titleMedium)

        if (transactions.isEmpty()) {
            Text("No transactions yet.")
        } else {
            LazyColumn(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(transactions) { tx ->
                    Card(modifier = Modifier.fillMaxWidth()) {
                        Column(modifier = Modifier.padding(12.dp)) {
                            Text("${tx.type}: ${formatter.format(tx.amount)}")
                            Text("Balance after: ${formatter.format(tx.balanceAfter)}")
                        }
                    }
                }
            }
        }
    }
}
