@Composable
fun BankApp() {
    var balance by remember { mutableStateOf(1000.0) }
    var amountText by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("Welcome to MiniBank") }

    val formatter = remember {
        NumberFormat.getCurrencyInstance(Locale.US)
    }

    fun parseAmount(): Double? {
        return amountText.toDoubleOrNull()?.takeIf { it > 0 }
    }

    fun deposit() {
        val amount = parseAmount()
        if (amount == null) {
            message = "Enter a valid positive amount."
            return
        }
        balance += amount
        message = "Deposited ${formatter.format(amount)}"
        amountText = ""
    }

    fun withdraw() {
        val amount = parseAmount()
        if (amount == null) {
            message = "Enter a valid positive amount."
            return
        }
        if (amount > balance) {
            message = "Insufficient funds."
            return
        }
        balance -= amount
        message = "Withdrew ${formatter.format(amount)}"
        amountText = ""
    }

    Scaffold(
        topBar = {
            TopAppBar(title = { Text("MiniBank") })
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .padding(24.dp)
                .fillMaxSize(),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text("Current Balance", style = MaterialTheme.typography.titleMedium)
            Text(
                text = formatter.format(balance),
                style = MaterialTheme.typography.displaySmall
            )

            OutlinedTextField(
                value = amountText,
                onValueChange = { amountText = it },
                label = { Text("Amount") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                singleLine = true
            )

            Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                Button(onClick = { deposit() }) {
                    Text("Deposit")
                }
                Button(
                    onClick = { withdraw() },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = MaterialTheme.colorScheme.secondary
                    )
                ) {
                    Text("Withdraw")
                }
            }

            Text(message, style = MaterialTheme.typography.bodyMedium)
        }
    }
}
