import androidx.room.*

@Dao
interface SurveyRecordDao {

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(record: SurveyRecordEntity)

    @Query("SELECT * FROM survey_records WHERE syncStatus != 'SYNCED' ORDER BY createdAt ASC")
    suspend fun getPendingRecords(): List<SurveyRecordEntity>

    @Query("UPDATE survey_records SET syncStatus = :status WHERE id = :id")
    suspend fun updateSyncStatus(id: String, status: String)

    @Query("SELECT * FROM survey_records ORDER BY createdAt DESC")
    suspend fun getAllRecords(): List<SurveyRecordEntity>
}
