## Repository

```kotlin
class SurveyRepository(
    private val dao: SurveyRecordDao,
    private val api: SurveyApi
) {

    suspend fun saveLocally(record: SurveyRecord) {
        dao.insert(record.toEntity())
    }

    suspend fun syncPendingRecords() {
        val pending = dao.getPendingRecords()

        for (entity in pending) {
            try {
                val response = api.submitSurvey(entity.toDto())
                if (response.success) {
                    dao.updateSyncStatus(entity.id, SyncStatus.SYNCED.name)
                } else {
                    dao.updateSyncStatus(entity.id, SyncStatus.FAILED.name)
                }
            } catch (e: Exception) {
                // Keep as pending or mark failed depending on retry strategy
                dao.updateSyncStatus(entity.id, SyncStatus.PENDING.name)
            }
        }
    }

    suspend fun getAllLocalRecords(): List<SurveyRecord> {
        return dao.getAllRecords().map { it.toDomain() }
    }
}
```

