## 1) Data model

```dart
class SurveyRecord {
  final String id;
  final String fieldAgentId;
  final Map<String, dynamic> answers;
  final DateTime createdAt;
  final bool synced;

  SurveyRecord({
    required this.id,
    required this.fieldAgentId,
    required this.answers,
    required this.createdAt,
    required this.synced,
  });

  SurveyRecord copyWith({
    String? id,
    String? fieldAgentId,
    Map<String, dynamic>? answers,
    DateTime? createdAt,
    bool? synced,
  }) {
    return SurveyRecord(
      id: id ?? this.id,
      fieldAgentId: fieldAgentId ?? this.fieldAgentId,
      answers: answers ?? this.answers,
      createdAt: createdAt ?? this.createdAt,
      synced: synced ?? this.synced,
    );
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'fieldAgentId': fieldAgentId,
        'answers': answers,
        'createdAt': createdAt.toIso8601String(),
        'synced': synced,
      };

  factory SurveyRecord.fromJson(Map<String, dynamic> json) {
    return SurveyRecord(
      id: json['id'],
      fieldAgentId: json['fieldAgentId'],
      answers: Map<String, dynamic>.from(json['answers']),
      createdAt: DateTime.parse(json['createdAt']),
      synced: json['synced'] ?? false,
    );
  }
}
```

