## 2) Local storage service

```dart
import 'dart:convert';
import 'package:hive/hive.dart';

class SurveyLocalStore {
  static const String boxName = 'survey_box';

  Future<Box> _openBox() async {
    return await Hive.openBox(boxName);
  }

  Future<void> saveSurvey(SurveyRecord survey) async {
    final box = await _openBox();
    await box.put(survey.id, jsonEncode(survey.toJson()));
  }

  Future<List<SurveyRecord>> getAllSurveys() async {
    final box = await _openBox();
    return box.values
        .map((value) => SurveyRecord.fromJson(jsonDecode(value)))
        .toList();
  }

  Future<List<SurveyRecord>> getUnsyncedSurveys() async {
    final all = await getAllSurveys();
    return all.where((record) => !record.synced).toList();
  }

  Future<void> markSynced(String id) async {
    final box = await _openBox();
    final raw = box.get(id);
    if (raw == null) return;

    final survey = SurveyRecord.fromJson(jsonDecode(raw));
    final updated = survey.copyWith(synced: true);
    await box.put(id, jsonEncode(updated.toJson()));
  }

  Future<void> deleteSurvey(String id) async {
    final box = await _openBox();
    await box.delete(id);
  }
}
```

