## 3) API client for syncing

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;

class SurveyApiClient {
  final String baseUrl;

  SurveyApiClient({required this.baseUrl});

  Future<void> uploadSurvey(SurveyRecord survey) async {
    final response = await http.post(
      Uri.parse('$baseUrl/surveys'),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(survey.toJson()),
    );

    if (response.statusCode != 200 && response.statusCode != 201) {
      throw Exception('Failed to upload survey: ${response.body}');
    }
  }

  Future<List<SurveyRecord>> downloadUpdatedSurveys(DateTime since) async {
    final response = await http.get(
      Uri.parse('$baseUrl/surveys?since=${since.toIso8601String()}'),
      headers: {'Content-Type': 'application/json'},
    );

    if (response.statusCode != 200) {
      throw Exception('Failed to fetch surveys: ${response.body}');
    }

    final List<dynamic> data = jsonDecode(response.body);
    return data.map((e) => SurveyRecord.fromJson(e)).toList();
  }
}
