```ts
// db.ts
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Survey } from './types';

const SURVEYS_KEY = 'surveys';

export async function getSurveys(): Promise<Survey[]> {
  const raw = await AsyncStorage.getItem(SURVEYS_KEY);
  return raw ? JSON.parse(raw) : [];
}

export async function saveSurveys(surveys: Survey[]): Promise<void> {
  await AsyncStorage.setItem(SURVEYS_KEY, JSON.stringify(surveys));
}

export async function addSurvey(survey: Survey): Promise<void> {
  const surveys = await getSurveys();
  surveys.push(survey);
  await saveSurveys(surveys);
}

export async function updateSurvey(updated: Survey): Promise<void> {
  const surveys = await getSurveys();
  const next = surveys.map(s => (s.id === updated.id ? updated : s));
  await saveSurveys(next);
}
```

