export async function createSurvey(input: Omit<Survey, 'id' | 'createdAt' | 'updatedAt' | 'synced'>) {
  const now = new Date().toISOString();

  const survey: Survey = {
    id: uuidv4(),
    ...input,
    createdAt: now,
    updatedAt: now,
    synced: false,
  };

  await addSurvey(survey);
  return survey;
}

export async function markSurveySynced(id: string) {
  const surveys = await getSurveys();
  const next = surveys.map(s =>
    s.id === id ? { ...s, synced: true, updatedAt: new Date().toISOString() } : s
  );
  await saveSurveys(next);
}
