## Sync service

This pushes unsynced surveys to the backend when online.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { getSurveys, saveSurveys } from './db';
import { Survey } from './types';

const API_URL = 'https://your-api.example.com';

async function pushSurvey(survey: Survey): Promise<boolean> {
  const res = await fetch(`${API_URL}/surveys`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(survey),
  });

  return res.ok;
}

export async function syncPendingSurveys() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  const surveys = await getSurveys();
  const unsynced = surveys.filter(s => !s.synced);

  if (unsynced.length === 0) return;

  const next = [...surveys];

  for (const survey of unsynced) {
    try {
      const ok = await pushSurvey(survey);
      if (ok) {
        const idx = next.findIndex(s => s.id === survey.id);
        if (idx >= 0) {
          next[idx] = { ...next[idx], synced: true, updatedAt: new Date().toISOString() };
        }
      }
    } catch (err) {
      // leave unsynced; try again later
      console.warn('Failed to sync survey', survey.id, err);
    }
  }

  await saveSurveys(next);
}
```

