## 4) Local database

**`src/db.ts`**

```ts
import * as SQLite from "expo-sqlite";
import { Survey } from "./types";

const db = SQLite.openDatabaseSync("survey.db");

export function initDb() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      serverId TEXT,
      name TEXT NOT NULL,
      location TEXT NOT NULL,
      notes TEXT NOT NULL,
      updatedAt INTEGER NOT NULL,
      syncStatus TEXT NOT NULL
    );
  `);
}

export function upsertSurvey(survey: Survey) {
  db.runSync(
    `
    INSERT INTO surveys (id, serverId, name, location, notes, updatedAt, syncStatus)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      serverId=excluded.serverId,
      name=excluded.name,
      location=excluded.location,
      notes=excluded.notes,
      updatedAt=excluded.updatedAt,
      syncStatus=excluded.syncStatus
    `,
    [
      survey.id,
      survey.serverId ?? null,
      survey.name,
      survey.location,
      survey.notes,
      survey.updatedAt,
      survey.syncStatus,
    ]
  );
}

export function getAllSurveys(): Survey[] {
  const result = db.getAllSync<any>(`SELECT * FROM surveys ORDER BY updatedAt DESC`);
  return result.map((row) => ({
    id: row.id,
    serverId: row.serverId ?? undefined,
    name: row.name,
    location: row.location,
    notes: row.notes,
    updatedAt: row.updatedAt,
    syncStatus: row.syncStatus,
  }));
}

export function getPendingSurveys(): Survey[] {
  const result = db.getAllSync<any>(
    `SELECT * FROM surveys WHERE syncStatus != 'synced' ORDER BY updatedAt ASC`
  );
  return result.map((row) => ({
    id: row.id,
    serverId: row.serverId ?? undefined,
    name: row.name,
    location: row.location,
    notes: row.notes,
    updatedAt: row.updatedAt,
    syncStatus: row.syncStatus,
  }));
}

export function markSurveySynced(localId: string, serverId: string) {
  db.runSync(
    `UPDATE surveys SET serverId = ?, syncStatus = 'synced' WHERE id = ?`,
    [serverId, localId]
  );
}

export function markSurveyConflict(localId: string) {
  db.runSync(`UPDATE surveys SET syncStatus = 'conflict' WHERE id = ?`, [localId]);
}
```

