## 6) Sync logic

**`src/sync.ts`**

```ts
import { getPendingSurveys, markSurveyConflict, markSurveySynced, upsertSurvey } from "./db";
import { pullSurveys, pushSurvey } from "./api";
import { Survey } from "./types";

let lastSyncAt = 0;

export async function syncNow() {
  // 1) Push local pending changes
  const pending = getPendingSurveys();

  for (const survey of pending) {
    try {
      const res = await pushSurvey({
        localId: survey.id,
        serverId: survey.serverId,
        name: survey.name,
        location: survey.location,
        notes: survey.notes,
        updatedAt: survey.updatedAt,
      });

      markSurveySynced(survey.id, res.serverId);
      lastSyncAt = Math.max(lastSyncAt, res.updatedAt);
    } catch (e) {
      // In real apps, inspect server response for conflict handling
      markSurveyConflict(survey.id);
    }
  }

  // 2) Pull server updates
  try {
    const remoteUpdates = await pullSurveys(lastSyncAt);

    for (const remote of remoteUpdates) {
      const local: Survey = {
        id: remote.serverId, // could map serverId->id or use separate lookup table
        serverId: remote.serverId,
        name: remote.name,
        location: remote.location,
        notes: remote.notes,
        updatedAt: remote.updatedAt,
        syncStatus: "synced",
      };

      upsertSurvey(local);
      lastSyncAt = Math.max(lastSyncAt, remote.updatedAt);
    }
  } catch (e) {
    // ignore pull failures for offline-first behavior
  }
}
```

