      <TextInput
        placeholder="Location"
        value={location}
        onChangeText={setLocation}
        style={{ borderWidth: 1, padding: 8, marginBottom: 8 }}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, padding: 8, marginBottom: 8 }}
      />

      <Button title="Save Survey Offline" onPress={addSurvey} />
      <View style={{ height: 8 }} />
      <Button title="Sync Now" onPress={manualSync} />

      <Text style={{ fontSize: 18, marginTop: 20, marginBottom: 8 }}>
