## 3) Survey repository

### `lib/data/survey_repository.dart`

```dart
import 'dart:convert';

import 'package:drift/drift.dart';
import 'package:uuid/uuid.dart';

import 'local_db.dart';

class SurveyRepository {
  final AppDatabase db;
  final _uuid = const Uuid();

  SurveyRepository(this.db);

  Stream<List<Survey>> watchSurveys() {
    return db.select(db.surveys).watch();
  }

  Future<void> createSurvey({
    required String title,
    String? location,
    String? notes,
  }) async {
    final now = DateTime.now();
    final id = _uuid.v4();

    await db.transaction(() async {
      await db.into(db.surveys).insert(
            SurveysCompanion.insert(
              id: id,
              title: title,
              location: Value(location),
              notes: Value(notes),
              createdAt: now,
              updatedAt: now,
              syncStatus: const Value('pending'),
            ),
          );

      await db.into(db.outbox).insert(
            OutboxCompanion.insert(
              entityType: 'survey',
              entityId: id,
              action: 'upsert',
              payloadJson: jsonEncode({
                'id': id,
                'title': title,
                'location': location,
                'notes': notes,
                'createdAt': now.toIso8601String(),
                'updatedAt': now.toIso8601String(),
              }),
              createdAt: now,
            ),
          );
    });
  }

  Future<void> updateSurvey({
    required String id,
    required String title,
    String? location,
    String? notes,
  }) async {
    final now = DateTime.now();

    await db.transaction(() async {
      await (db.update(db.surveys)..where((t) => t.id.equals(id))).write(
        SurveysCompanion(
          title: Value(title),
          location: Value(location),
          notes: Value(notes),
          updatedAt: Value(now),
          syncStatus: const Value('pending'),
        ),
      );

      await db.into(db.outbox).insert(
            OutboxCompanion.insert(
              entityType: 'survey',
              entityId: id,
              action: 'upsert',
              payloadJson: jsonEncode({
                'id': id,
                'title': title,
                'location': location,
                'notes': notes,
                'updatedAt': now.toIso8601String(),
              }),
              createdAt: now,
            ),
          );
    });
  }

  Future<void> deleteSurvey(String id) async {
    final now = DateTime.now();

    await db.transaction(() async {
      await (db.delete(db.surveys)..where((t) => t.id.equals(id))).go();

      await db.into(db.outbox).insert(
            OutboxCompanion.insert(
              entityType: 'survey',
              entityId: id,
              action: 'delete',
              payloadJson: jsonEncode({'id': id}),
              createdAt: now,
            ),
          );
    });
  }
}
```

