## 4) Sync service

This example assumes a backend API like:

- `GET /surveys/changes?since=...`
- `POST /surveys/batch`

### `lib/sync/sync_service.dart`

```dart
import 'dart:convert';

import 'package:http/http.dart' as http;

import '../data/local_db.dart';

class SyncService {
  final AppDatabase db;
  final String baseUrl;
  final http.Client client;

  SyncService({
    required this.db,
    required this.baseUrl,
    http.Client? client,
  }) : client = client ?? http.Client();

  Future<void> syncNow() async {
    await _pushLocalChanges();
    await _pullRemoteChanges();
  }

  Future<void> _pushLocalChanges() async {
    final pending = await (db.select(db.outbox)
          ..orderBy([(t) => OrderingTerm.asc(t.createdAt)]))
        .get();

    for (final item in pending) {
      try {
        final response = await client.post(
          Uri.parse('$baseUrl/surveys/batch'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'action': item.action,
            'entityType': item.entityType,
            'entityId': item.entityId,
            'payload': jsonDecode(item.payloadJson),
          }),
        );

        if (response.statusCode >= 200 && response.statusCode < 300) {
          await db.transaction(() async {
            await (db.update(db.surveys)..where((t) => t.id.equals(item.entityId))).write(
              SurveysCompanion(
                syncedAt: Value(DateTime.now()),
                syncStatus: const Value('synced'),
              ),
            );

            await (db.delete(db.outbox)..where((t) => t.localId.equals(item.localId))).go();
          });
        } else {
          await _markOutboxError(item.localId, 'HTTP ${response.statusCode}');
        }
      } catch (e) {
        await _markOutboxError(item.localId, e.toString());
      }
    }
  }

  Future<void> _pullRemoteChanges() async {
    final response = await client.get(
      Uri.parse('$baseUrl/surveys/changes'),
      headers: {'Content-Type': 'application/json'},
    );

    if (response.statusCode != 200) {
      throw Exception('Failed to pull changes: ${response.statusCode}');
    }

    final data = jsonDecode(response.body) as Map<String, dynamic>;
    final changes = (data['changes'] as List<dynamic>?) ?? [];

    for (final c in changes) {
      final survey = c as Map<String, dynamic>;
      final id = survey['id'] as String;

      await db.transaction(() async {
        final existing = await (db.select(db.surveys)..where((t) => t.id.equals(id))).getSingleOrNull();

        final remoteUpdatedAt = DateTime.parse(survey['updatedAt'] as String);

        if (existing == null) {
          await db.into(db.surveys).insert(
                SurveysCompanion.insert(
                  id: id,
                  title: survey['title'] as String,
                  location: Value(survey['location'] as String?),
                  notes: Value(survey['notes'] as String?),
                  createdAt: DateTime.parse(survey['createdAt'] as String),
                  updatedAt: remoteUpdatedAt,
                  syncStatus: const Value('synced'),
                  syncedAt: Value(DateTime.now()),
                ),
              );
        } else {
          if (remoteUpdatedAt.isAfter(existing.updatedAt)) {
            await (db.update(db.surveys)..where((t) => t.id.equals(id))).write(
              SurveysCompanion(
                title: Value(survey['title'] as String),
                location: Value(survey['location'] as String?),
                notes: Value(survey['notes'] as String?),
                updatedAt: Value(remoteUpdatedAt),
                syncStatus: const Value('synced'),
                syncedAt: Value(DateTime.now()),
              ),
            );
          }
        }
      });
    }
  }

  Future<void> _markOutboxError(int localId, String error) async {
    await (db.update(db.outbox)..where((t) => t.localId.equals(localId))).write(
      OutboxCompanion(
        attempts: Value((await (db.select(db.outbox)..where((t) => t.localId.equals(localId))).getSingle()).attempts + 1),
        lastError: Value(error),
      ),
    );
  }
}
```

