# 8) Repository for local-first writes

## `lib/data/repository/survey_repository.dart`

```dart
import 'dart:convert';
import 'package:drift/drift.dart';
import '../../features/surveys/survey_model.dart';
import '../local/app_db.dart';

class SurveyRepository {
  final AppDb db;

  SurveyRepository(this.db);

  Future<List<SurveyModel>> getAllSurveys() async {
    final rows = await db.select(db.surveys).get();
    return rows.map(_toModel).toList();
  }

  Future<void> saveSurvey(SurveyModel survey, {required String actionType}) async {
    final now = DateTime.now();

    await db.transaction(() async {
      await db.into(db.surveys).insertOnConflictUpdate(
        SurveysCompanion.insert(
          id: survey.id,
          projectId: survey.projectId,
          siteName: survey.siteName,
          latitude: Value(survey.latitude),
          longitude: Value(survey.longitude),
          notes: Value(survey.notes),
          photoPaths: Value(jsonEncode(survey.photoPaths)),
          syncStatus: 'pending',
          version: Value(survey.version),
          createdAt: Value(survey.createdAt),
          updatedAt: Value(now),
        ),
      );

      await db.into(db.outbox).insert(
        OutboxCompanion.insert(
          actionId: DateTime.now().microsecondsSinceEpoch.toString(),
          entityId: survey.id,
          entityType: 'survey',
          actionType: actionType,
          payload: jsonEncode({
            'id': survey.id,
            'projectId': survey.projectId,
            'siteName': survey.siteName,
            'latitude': survey.latitude,
            'longitude': survey.longitude,
            'notes': survey.notes,
            'photoPaths': survey.photoPaths,
            'version': survey.version,
            'updatedAt': now.toIso8601String(),
          }),
          createdAt: now,
        ),
      );
    });
  }

  Future<void> markSynced(String surveyId, int serverVersion) async {
    await (db.update(db.surveys)..where((t) => t.id.equals(surveyId))).write(
      SurveysCompanion(
        syncStatus: const Value('synced'),
        version: Value(serverVersion),
        updatedAt: Value(DateTime.now()),
      ),
    );
  }

  Future<void> markSyncFailed(String surveyId) async {
    await (db.update(db.surveys)..where((t) => t.id.equals(surveyId))).write(
      const SurveysCompanion(syncStatus: Value('failed')),
    );
  }

  SurveyModel _toModel(Survey survey) {
    return SurveyModel(
      id: survey.id,
      projectId: survey.projectId,
      siteName: survey.siteName,
      latitude: survey.latitude,
      longitude: survey.longitude,
      notes: survey.notes,
      photoPaths: survey.photoPaths == null
          ? []
          : List<String>.from(jsonDecode(survey.photoPaths!)),
      syncStatus: survey.syncStatus,
      version: survey.version,
      createdAt: survey.createdAt,
      updatedAt: survey.updatedAt,
    );
  }
}
