# 10) Sync service

This pulls pending outbox actions and flushes them to the server.

## `lib/data/sync/sync_service.dart`

```dart
import 'dart:convert';
import '../local/app_db.dart';
import '../remote/api_client.dart';

class SyncService {
  final AppDb db;
  final ApiClient api;

  SyncService(this.db, this.api);

  Future<void> syncPendingActions() async {
    final pending = await db.select(db.outbox).get();

    if (pending.isEmpty) return;

    final actions = pending.map((a) {
      return {
        'actionId': a.actionId,
        'entityId': a.entityId,
        'entityType': a.entityType,
        'actionType': a.actionType,
        'payload': jsonDecode(a.payload),
      };
    }).toList();

    try {
      final results = await api.syncOutbox(actions);

      for (final item in results) {
        final entityId = item['entityId'] as String;
        final serverVersion = item['serverVersion'] as int? ?? 1;

        await (db.delete(db.outbox)..where((t) => t.entityId.equals(entityId))).go();
        await (db.update(db.surveys)..where((t) => t.id.equals(entityId))).write(
          SurveysCompanion(
            syncStatus: const Value('synced'),
            version: Value(serverVersion),
          ),
        );
      }
    } catch (e) {
      // Keep outbox records for retry
      final failed = await db.select(db.outbox).get();
      for (final item in failed) {
        await (db.update(db.outbox)..where((t) => t.actionId.equals(item.actionId))).write(
          OutboxCompanion(
            retryCount: Value(item.retryCount + 1),
            lastError: Value(e.toString()),
          ),
        );
      }
      rethrow;
    }
  }
}
```

