class _SurveyListPageState extends State<SurveyListPage> {
  late Future<List<SurveyModel>> _future;

  @override
  void initState() {
    super.initState();
    _reload();
  }

  void _reload() {
    _future = widget.repository.getAllSurveys();
  }

  Future<void> _sync() async {
    try {
      await widget.syncService.syncPendingActions();
      setState(() => _reload());
    } catch (_) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sync failed. Will retry later.')),
      );
    }
