# 4) Local database service

## `lib/services/local_db.dart`

```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import '../models/survey.dart';

class LocalDb {
  static final LocalDb instance = LocalDb._internal();
  static Database? _db;

  LocalDb._internal();

  Future<Database> get db async {
    _db ??= await _initDb();
    return _db!;
  }

  Future<Database> _initDb() async {
    final databasesPath = await getDatabasesPath();
    final path = join(databasesPath, 'field_survey.db');

    return openDatabase(
      path,
      version: 1,
      onCreate: (database, version) async {
        await database.execute('''
          CREATE TABLE surveys(
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            notes TEXT NOT NULL,
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            created_at INTEGER NOT NULL,
            synced INTEGER NOT NULL DEFAULT 0,
            sync_attempts INTEGER NOT NULL DEFAULT 0
          )
        ''');
      },
    );
  }

  Future<void> insertSurvey(Survey survey) async {
    final database = await db;
    await database.insert(
      'surveys',
      survey.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  Future<List<Survey>> getAllSurveys() async {
    final database = await db;
    final rows = await database.query('surveys', orderBy: 'created_at DESC');
    return rows.map((row) => Survey.fromMap(row)).toList();
  }

  Future<List<Survey>> getPendingSurveys() async {
    final database = await db;
    final rows = await database.query(
      'surveys',
      where: 'synced = ?',
      whereArgs: [0],
      orderBy: 'created_at ASC',
    );
    return rows.map((row) => Survey.fromMap(row)).toList();
  }

  Future<void> markSurveySynced(String id) async {
    final database = await db;
    await database.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  Future<void> incrementSyncAttempts(String id) async {
    final database = await db;
    await database.rawUpdate(
      'UPDATE surveys SET sync_attempts = sync_attempts + 1 WHERE id = ?',
      [id],
    );
  }
}
