# 6) Sync service

## `lib/services/sync_service.dart`

```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import '../services/local_db.dart';
import '../services/api_service.dart';

class SyncService {
  final LocalDb localDb;
  final ApiService apiService;

  SyncService({
    required this.localDb,
    required this.apiService,
  });

  Future<void> syncPendingSurveys() async {
    final connectivity = await Connectivity().checkConnectivity();
    if (connectivity == ConnectivityResult.none) {
      return;
    }

    final pending = await localDb.getPendingSurveys();

    for (final survey in pending) {
      try {
        await apiService.sendSurvey(survey);
        await localDb.markSurveySynced(survey.id);
      } catch (_) {
        await localDb.incrementSyncAttempts(survey.id);
      }
    }
  }
}
