# 3) Local SQLite database

```dart
// lib/services/local_db.dart
import 'dart:convert';
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import '../models/survey.dart';
import '../models/sync_op.dart';

class LocalDb {
  static final LocalDb instance = LocalDb._internal();
  static Database? _db;

  LocalDb._internal();

  Future<Database> get database async {
    if (_db != null) return _db!;
    _db = await _initDb();
    return _db!;
  }

  Future<Database> _initDb() async {
    final dbPath = await getDatabasePath();
    final path = join(dbPath, 'survey_app.db');

    return openDatabase(
      path,
      version: 1,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE surveys (
            id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            notes TEXT NOT NULL,
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            updatedAt INTEGER NOT NULL,
            version INTEGER NOT NULL,
            isDirty INTEGER NOT NULL DEFAULT 0
          )
        ''');

        await db.execute('''
          CREATE TABLE sync_queue (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            entityId TEXT NOT NULL,
            operation TEXT NOT NULL,
            payload TEXT NOT NULL,
            createdAt INTEGER NOT NULL
          )
        ''');
      },
    );
  }

  Future<void> upsertSurvey(Survey survey) async {
    final db = await database;
    await db.insert(
      'surveys',
      survey.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  Future<List<Survey>> getAllSurveys() async {
    final db = await database;
    final rows = await db.query('surveys', orderBy: 'updatedAt DESC');
    return rows.map((r) => Survey.fromMap(r)).toList();
  }

  Future<List<Survey>> getDirtySurveys() async {
    final db = await database;
    final rows = await db.query('surveys', where: 'isDirty = ?', whereArgs: [1]);
    return rows.map((r) => Survey.fromMap(r)).toList();
  }

  Future<void> markSurveyClean(String id, int newVersion) async {
    final db = await database;
    await db.update(
      'surveys',
      {'isDirty': 0, 'version': newVersion},
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  Future<void> addSyncOp(SyncOp op) async {
    final db = await database;
    await db.insert('sync_queue', op.toMap());
  }

  Future<List<SyncOp>> getSyncQueue() async {
    final db = await database;
    final rows = await db.query('sync_queue', orderBy: 'createdAt ASC');
    return rows.map((r) => SyncOp.fromMap(r)).toList();
  }

  Future<void> deleteSyncOp(int id) async {
    final db = await database;
    await db.delete('sync_queue', where: 'id = ?', whereArgs: [id]);
  }

  Future<void> saveSurveyWithQueue({
    required Survey survey,
    required String operation,
  }) async {
    await upsertSurvey(survey.copyWith(isDirty: true));
    await addSyncOp(
      SyncOp(
        entityId: survey.id,
        operation: operation,
        payload: jsonEncode(survey.toMap()),
        createdAt: DateTime.now().millisecondsSinceEpoch,
      ),
    );
  }
}
```

