# 4) API client

```dart
// lib/services/api_client.dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models/survey.dart';

class ApiClient {
  final String baseUrl;
  ApiClient(this.baseUrl);

  Future<List<Map<String, dynamic>>> fetchSurveys() async {
    final res = await http.get(Uri.parse('$baseUrl/surveys'));
    if (res.statusCode != 200) {
      throw Exception('Failed to fetch surveys');
    }
    final decoded = jsonDecode(res.body) as List;
    return decoded.cast<Map<String, dynamic>>();
  }

  Future<Map<String, dynamic>> pushSurvey(Survey survey) async {
    final res = await http.post(
      Uri.parse('$baseUrl/surveys/sync'),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(survey.toMap()),
    );

    if (res.statusCode != 200) {
      throw Exception('Failed to sync survey');
    }

    return jsonDecode(res.body) as Map<String, dynamic>;
  }
}
