# 5) Sync service

```dart
// lib/services/sync_service.dart
import '../models/survey.dart';
import 'api_client.dart';
import 'local_db.dart';

class SyncService {
  final LocalDb db;
  final ApiClient api;

  SyncService({required this.db, required this.api});

  Future<void> sync() async {
    final queue = await db.getSyncQueue();

    for (final op in queue) {
      try {
        final surveyMap = Map<String, dynamic>.from(
          // payload is JSON string stored in queue
          (await Future.value(op.payload)),
        );

        final survey = Survey.fromMap(surveyMap);

        final result = await api.pushSurvey(survey);

        final syncedVersion = result['version'] ?? survey.version + 1;
        await db.markSurveyClean(survey.id, syncedVersion);

        if (op.id != null) {
          await db.deleteSyncOp(op.id!);
        }
      } catch (_) {
        // Stop sync on first failure to avoid inconsistent state
        break;
      }
    }
  }
}
```

