  @override
  void initState() {
    super.initState();
    _future = widget.db.getAllSurveys();
  }

  Future<void> _reload() async {
    setState(() {
      _future = widget.db.getAllSurveys();
    });
  }

  Future<void> _syncNow() async {
    await widget.syncService.sync();
    await _reload();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Surveys'),
        actions: [
