# 6) Local repository layer

Below is an in-memory-style repository for clarity. In a real app, replace the internals with SQLite calls.

## `src/db/surveyRepository.ts`

```ts
import { SurveyRecord } from '../types/survey';

const surveyStore: SurveyRecord[] = [];

export const surveyRepository = {
  async save(record: SurveyRecord): Promise<void> {
    const idx = surveyStore.findIndex(r => r.id === record.id);
    if (idx >= 0) {
      surveyStore[idx] = record;
    } else {
      surveyStore.push(record);
    }
  },

  async getAll(): Promise<SurveyRecord[]> {
    return [...surveyStore];
  },

  async getById(id: string): Promise<SurveyRecord | undefined> {
    return surveyStore.find(r => r.id === id);
  },

  async markSynced(id: string): Promise<void> {
    const record = surveyStore.find(r => r.id === id);
    if (record) {
      record.syncStatus = 'synced';
      record.updatedAt = new Date().toISOString();
    }
  },

  async markPending(id: string): Promise<void> {
    const record = surveyStore.find(r => r.id === id);
    if (record) {
      record.syncStatus = 'pending';
      record.updatedAt = new Date().toISOString();
    }
  }
};
```

## `src/db/outboxRepository.ts`

```ts
import { OutboxItem } from '../types/survey';

const outboxStore: OutboxItem[] = [];

export const outboxRepository = {
  async add(item: OutboxItem): Promise<void> {
    outboxStore.push(item);
  },

  async getAll(): Promise<OutboxItem[]> {
    return [...outboxStore];
  },

  async remove(id: string): Promise<void> {
    const idx = outboxStore.findIndex(i => i.id === id);
    if (idx >= 0) outboxStore.splice(idx, 1);
  },

  async incrementRetry(id: string): Promise<void> {
    const item = outboxStore.find(i => i.id === id);
    if (item) item.retryCount += 1;
  }
};
```

