# 7) Create survey locally and queue for sync

## `src/db/database.ts`

```ts
import { surveyRepository } from './surveyRepository';
import { outboxRepository } from './outboxRepository';
import { SurveyRecord, OutboxItem } from '../types/survey';

export async function createSurvey(recordData: Omit<SurveyRecord, 'syncStatus'>): Promise<SurveyRecord> {
  const record: SurveyRecord = {
    ...recordData,
    syncStatus: 'pending'
  };

  await surveyRepository.save(record);

  const outboxItem: OutboxItem = {
    id: crypto.randomUUID(),
    type: 'CREATE',
    entity: 'surveyRecord',
    entityId: record.id,
    payload: record,
    createdAt: new Date().toISOString(),
    retryCount: 0
  };

  await outboxRepository.add(outboxItem);

  return record;
}
```

