import { OutboxItem, SurveyRecord } from '../types/survey';

const BASE_URL = 'https://your-api.example.com';

export async function pushOutboxItem(item: OutboxItem): Promise<void> {
  const response = await fetch(`${BASE_URL}/sync`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(item)
  });

  if (!response.ok) {
    throw new Error(`Sync failed with status ${response.status}`);
  }
}

export async function fetchServerSurveys(since?: string): Promise<SurveyRecord[]> {
  const url = since
    ? `${BASE_URL}/surveys?since=${encodeURIComponent(since)}`
    : `${BASE_URL}/surveys`;

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Failed to fetch surveys`);
  }

  return response.json();
}
