# 9) Sync service

This service processes queued changes when online.

## `src/sync/syncService.ts`

```ts
import { outboxRepository } from '../db/outboxRepository';
import { surveyRepository } from '../db/surveyRepository';
import { pushOutboxItem, fetchServerSurveys } from '../api/syncApi';

export async function syncNow(): Promise<void> {
  const outboxItems = await outboxRepository.getAll();

  for (const item of outboxItems) {
    try {
      await pushOutboxItem(item);
      await outboxRepository.remove(item.id);
      await surveyRepository.markSynced(item.entityId);
    } catch (err) {
      console.error(`Failed to sync item ${item.id}`, err);
      await outboxRepository.incrementRetry(item.id);
      await surveyRepository.markPending(item.entityId);
    }
  }

  // Pull latest server changes after pushing local changes
  try {
    const serverSurveys = await fetchServerSurveys();
    for (const survey of serverSurveys) {
      await surveyRepository.save({
        ...survey,
        syncStatus: 'synced'
      });
    }
  } catch (err) {
    console.error('Failed to pull updates', err);
  }
}
```

