# 13) Minimal backend example

This is a simple Node/Express server for sync.

## `server/index.ts`

```ts
import express from 'express';

const app = express();
app.use(express.json());

const surveys: any[] = [];

app.post('/sync', (req, res) => {
  const item = req.body;

  if (item.type === 'CREATE') {
    surveys.push(item.payload);
  }

  if (item.type === 'UPDATE') {
    const idx = surveys.findIndex(s => s.id === item.entityId);
    if (idx >= 0) surveys[idx] = { ...surveys[idx], ...item.payload };
  }

  if (item.type === 'DELETE') {
    const idx = surveys.findIndex(s => s.id === item.entityId);
    if (idx >= 0) surveys[idx].deleted = true;
  }

  res.json({ ok: true });
});

app.get('/surveys', (_req, res) => {
  res.json(surveys.filter(s => !s.deleted));
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

