## 6) DAO layer

### `lib/data/survey_dao.dart`
```dart
import 'package:sqflite/sqflite.dart';
import '../models/survey_record.dart';
import 'local_database.dart';

class SurveyDao {
  Future<void> upsert(SurveyRecord record) async {
    final db = await LocalDatabase.instance.database;
    await db.insert(
      'survey_records',
      record.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  Future<List<SurveyRecord>> getAll() async {
    final db = await LocalDatabase.instance.database;
    final rows = await db.query('survey_records', orderBy: 'createdAt DESC');
    return rows.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<List<SurveyRecord>> getPending() async {
    final db = await LocalDatabase.instance.database;
    final rows = await db.query(
      'survey_records',
      where: 'syncStatus = ?',
      whereArgs: ['pending'],
      orderBy: 'createdAt ASC',
    );
    return rows.map((e) => SurveyRecord.fromMap(e)).toList();
  }

  Future<void> markSynced(String id, String remoteId) async {
    final db = await LocalDatabase.instance.database;
    await db.update(
      'survey_records',
      {
        'remoteId': remoteId,
        'syncStatus': 'synced',
        'lastSyncError': null,
        'updatedAt': DateTime.now().toIso8601String(),
      },
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  Future<void> markFailed(String id, String error) async {
    final db = await LocalDatabase.instance.database;
    await db.update(
      'survey_records',
      {
        'syncStatus': 'failed',
        'lastSyncError': error,
        'updatedAt': DateTime.now().toIso8601String(),
      },
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}
```

