## 7) API client

### `lib/data/api_client.dart`
```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models/survey_record.dart';

class ApiClient {
  final String baseUrl;
  ApiClient({required this.baseUrl});

  Future<String> pushSurvey(SurveyRecord record) async {
    final response = await http.post(
      Uri.parse('$baseUrl/surveys'),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode({
        'clientId': record.id,
        'fieldAgentId': record.fieldAgentId,
        'surveyType': record.surveyType,
        'latitude': record.latitude,
        'longitude': record.longitude,
        'notes': record.notes,
        'photoPath': record.photoPath, // ideally upload separately
        'createdAt': record.createdAt.toIso8601String(),
        'updatedAt': record.updatedAt.toIso8601String(),
      }),
    );

    if (response.statusCode == 201) {
      final data = jsonDecode(response.body);
      return data['remoteId'] as String;
    } else {
      throw Exception('Sync failed: ${response.statusCode} ${response.body}');
    }
  }
}
```

