## 8) Sync service

### `lib/data/sync_service.dart`
```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'api_client.dart';
import 'survey_dao.dart';

class SyncService {
  final SurveyDao dao;
  final ApiClient apiClient;

  SyncService({required this.dao, required this.apiClient});

  Future<void> syncPending() async {
    final connectivity = await Connectivity().checkConnectivity();
    if (connectivity == ConnectivityResult.none) return;

    final pending = await dao.getPending();

    for (final record in pending) {
      try {
        final remoteId = await apiClient.pushSurvey(record);
        await dao.markSynced(record.id, remoteId);
      } catch (e) {
        await dao.markFailed(record.id, e.toString());
      }
    }
  }
}
```

