  StyleSheet,
  Alert,
  SafeAreaView,
} from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import NetInfo from "@react-native-community/netinfo";

type SurveyRecord = {
  id: string;
  siteName: string;
  notes: string;
  createdAt: string;
  synced: boolean;
};

const STORAGE_KEY = "survey_records_v1";

export default function App() {
  const [siteName, setSiteName] = useState("");
  const [notes, setNotes] = useState("");
  const [records, setRecords] = useState<SurveyRecord[]>([]);
  const [isOnline, setIsOnline] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    loadRecords();

    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!(state.isConnected && state.isInternetReachable);
      setIsOnline(online);

      if (online) {
        syncPendingRecords();
      }
    });

    return () => unsubscribe();
  }, []);

  async function loadRecords() {
    const saved = await AsyncStorage.getItem(STORAGE_KEY);
    if (saved) {
      setRecords(JSON.parse(saved));
    }
  }

  async function saveRecords(nextRecords: SurveyRecord[]) {
    setRecords(nextRecords);
    await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(nextRecords));
  }

  async function addRecord() {
    if (!siteName.trim()) {
      Alert.alert("Validation", "Please enter a site name.");
      return;
    }

    const newRecord: SurveyRecord = {
      id: Date.now().toString(),
      siteName: siteName.trim(),
      notes: notes.trim(),
      createdAt: new Date().toISOString(),
      synced: false,
    };

    const nextRecords = [newRecord, ...records];
    await saveRecords(nextRecords);

    setSiteName("");
    setNotes("");

    if (isOnline) {
      syncPendingRecords(nextRecords);
    }
  }

  async function syncPendingRecords(currentRecords = records) {
    const pending = currentRecords.filter((r) => !r.synced);
    if (pending.length === 0) return;

    setSyncing(true);

    try {
      // Replace this with a real API call
      // Example:
      // await fetch("https://your-api.example.com/surveys", {
      //   method: "POST",
      //   headers: { "Content-Type": "application/json" },
      //   body: JSON.stringify(pending),
      // });

      await new Promise((resolve) => setTimeout(resolve, 1000)); // mock network delay

      const updated = currentRecords.map((r) =>
        !r.synced ? { ...r, synced: true } : r
      );

      await saveRecords(updated);
      Alert.alert("Sync complete", `${pending.length} record(s) synced.`);
    } catch (error) {
      Alert.alert("Sync failed", "Records remain saved locally.");
    } finally {
      setSyncing(false);
    }
  }

  const unsyncedCount = records.filter((r) => !r.synced).length;

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>

      <Text style={isOnline ? styles.online : styles.offline}>
        {isOnline ? "Online" : "Offline"}
      </Text>

      <Text style={styles.status}>
        Pending sync: {unsyncedCount} {syncing ? "(syncing...)" : ""}
      </Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Site name"
          value={siteName}
          onChangeText={setSiteName}
        />
        <TextInput
          style={styles.input}
          placeholder="Notes"
          value={notes}
          onChangeText={setNotes}
        />
        <Button title="Save Survey" onPress={addRecord} />
        <View style={{ height: 10 }} />
        <Button
          title="Sync Now"
          onPress={() => syncPendingRecords()}
          disabled={!isOnline || syncing}
        />
      </View>

      <FlatList
        data={records}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.record}>
            <Text style={styles.recordTitle}>{item.siteName}</Text>
            <Text>{item.notes}</Text>
            <Text style={styles.meta}>
              {new Date(item.createdAt).toLocaleString()}
            </Text>
            <Text style={item.synced ? styles.synced : styles.pending}>
              {item.synced ? "Synced" : "Pending sync"}
            </Text>
          </View>
        )}
        ListEmptyComponent={<Text>No survey records yet.</Text>}
      />
    </SafeAreaView>
  );
}

