### `client/db.ts`

```ts
const DB_NAME = "offline-survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

export type Survey = {
  id: string;
  fieldAgent: string;
  location: string;
  notes: string;
  createdAt: string;
  synced: boolean;
};

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function saveSurvey(survey: Survey) {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function getSurveys(): Promise<Survey[]> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const request = tx.objectStore(STORE_NAME).getAll();

    request.onsuccess = () => resolve(request.result as Survey[]);
    request.onerror = () => reject(request.error);
  });
}

export async function markSynced(id: string) {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const getReq = store.get(id);

    getReq.onsuccess = () => {
      const survey = getReq.result as Survey | undefined;
      if (!survey) return resolve();

      store.put({ ...survey, synced: true });
    };

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function getPendingSurveys(): Promise<Survey[]> {
  const all = await getSurveys();
  return all.filter((s) => !s.synced);
}
```

