### `client/app.ts`

```ts
import { getSurveys, getPendingSurveys, markSynced, saveSurvey, type Survey } from "./db.ts";

const form = document.getElementById("surveyForm") as HTMLFormElement;
const statusEl = document.getElementById("status") as HTMLParagraphElement;
const listEl = document.getElementById("surveyList") as HTMLUListElement;

const API_URL = "http://localhost:3000/surveys";

function updateStatus() {
  statusEl.textContent = `Status: ${navigator.onLine ? "online" : "offline"}`;
}

async function renderList() {
  const surveys = await getSurveys();
  listEl.innerHTML = "";

  for (const s of surveys) {
    const li = document.createElement("li");
    li.textContent = `${s.fieldAgent} @ ${s.location} — ${s.synced ? "synced" : "pending"} `;
    listEl.appendChild(li);
  }
}

async function syncPending() {
  const pending = await getPendingSurveys();

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await markSynced(survey.id);
      }
    } catch {
      // still offline or server unavailable
    }
  }

  await renderList();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const fieldAgent = (document.getElementById("fieldAgent") as HTMLInputElement).value.trim();
  const location = (document.getElementById("location") as HTMLInputElement).value.trim();
  const notes = (document.getElementById("notes") as HTMLTextAreaElement).value.trim();

  const survey: Survey = {
    id: crypto.randomUUID(),
    fieldAgent,
    location,
    notes,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurvey(survey);
  form.reset();
  await renderList();

  if (navigator.onLine) {
    await syncPending();
  }
});

window.addEventListener("online", async () => {
  updateStatus();
  await syncPending();
});

window.addEventListener("offline", updateStatus);

async function init() {
  updateStatus();
  await renderList();

  if ("serviceWorker" in navigator) {
    await navigator.serviceWorker.register("./sw.js");
  }

  if (navigator.onLine) {
    await syncPending();
  }
}

init();
