## 4) `lib/db.dart`

```dart
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import 'model.dart';

class AppDb {
  static final AppDb instance = AppDb._();
  AppDb._();

  static Database? _db;

  Future<Database> get db async {
    if (_db != null) return _db!;
    _db = await _initDb();
    return _db!;
  }

  Future<Database> _initDb() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'survey_app.db');

    return openDatabase(
      path,
      version: 1,
      onCreate: (database, version) async {
        await database.execute('''
          CREATE TABLE surveys (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            respondentName TEXT NOT NULL,
            location TEXT NOT NULL,
            notes TEXT NOT NULL,
            createdAt INTEGER NOT NULL,
            synced INTEGER NOT NULL DEFAULT 0,
            serverId TEXT
          )
        ''');
      },
    );
  }

  Future<int> insertSurvey(SurveyRecord record) async {
    final database = await db;
    return database.insert('surveys', record.toMap(),
        conflictAlgorithm: ConflictAlgorithm.replace);
  }

  Future<List<SurveyRecord>> getAllSurveys() async {
    final database = await db;
    final rows = await database.query('surveys', orderBy: 'createdAt DESC');
    return rows.map(SurveyRecord.fromMap).toList();
  }

  Future<List<SurveyRecord>> getUnsyncedSurveys() async {
    final database = await db;
    final rows = await database.query(
      'surveys',
      where: 'synced = ?',
      whereArgs: [0],
      orderBy: 'createdAt ASC',
    );
    return rows.map(SurveyRecord.fromMap).toList();
  }

  Future<void> markSynced(int localId, String serverId) async {
    final database = await db;
    await database.update(
      'surveys',
      {'synced': 1, 'serverId': serverId},
      where: 'id = ?',
      whereArgs: [localId],
    );
  }
}
```

