```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import 'db.dart';

class SyncService {
  SyncService._();
  static final instance = SyncService._();

  // Replace with your backend URL
  final String endpoint = 'https://example.com/api/surveys';

  Future<void> syncPending() async {
    final db = AppDb.instance;
    final pending = await db.getUnsyncedSurveys();

    for (final record in pending) {
      try {
        final response = await http.post(
          Uri.parse(endpoint),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'respondentName': record.respondentName,
            'location': record.location,
            'notes': record.notes,
            'createdAt': record.createdAt,
          }),
        );

        if (response.statusCode == 200 || response.statusCode == 201) {
          final data = jsonDecode(response.body) as Map<String, dynamic>;
          final serverId = data['id']?.toString() ?? 'server-${record.id}';
          await db.markSynced(record.id!, serverId);
        }
      } catch (_) {
        // Leave it unsynced. Will retry later.
      }
    }
  }
}
```

