class SurveyHomePage extends StatefulWidget {
  const SurveyHomePage({super.key});

  @override
  State<SurveyHomePage> createState() => _SurveyHomePageState();
}

class _SurveyHomePageState extends State<SurveyHomePage> {
  final _formKey = GlobalKey<FormState>();
  final _nameCtrl = TextEditingController();
  final _locationCtrl = TextEditingController();
  final _notesCtrl = TextEditingController();

  List<SurveyRecord> _records = [];
  StreamSubscription? _sub;

  @override
  void initState() {
    super.initState();
    _loadRecords();
    _listenConnectivity();
  }

  Future<void> _loadRecords() async {
    final records = await AppDb.instance.getAllSurveys();
    setState(() => _records = records);
  }

  void _listenConnectivity() {
    _sub = Connectivity().onConnectivityChanged.listen((result) async {
      if (result != ConnectivityResult.none) {
        await SyncService.instance.syncPending();
        await _loadRecords();
      }
    });
  }

  Future<void> _saveSurvey() async {
    if (!_formKey.currentState!.validate()) return;

    final record = SurveyRecord(
      respondentName: _nameCtrl.text.trim(),
      location: _locationCtrl.text.trim(),
      notes: _notesCtrl.text.trim(),
      createdAt: DateTime.now().millisecondsSinceEpoch,
      synced: 0,
    );

    await AppDb.instance.insertSurvey(record);

    _nameCtrl.clear();
    _locationCtrl.clear();
    _notesCtrl.clear();

    await _loadRecords();
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Survey saved locally')),
      );
    }
  }

  Future<void> _forceSync() async {
    await SyncService.instance.syncPending();
    await _loadRecords();
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sync attempted')),
      );
    }
  }

  @override
  void dispose() {
    _sub?.cancel();
    _nameCtrl.dispose();
    _locationCtrl.dispose();
    _notesCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final syncedCount = _records.where((r) => r.synced == 1).length;
    final pendingCount = _records.length - syncedCount;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Survey App'),
        actions: [
          IconButton(
            icon: const Icon(Icons.sync),
            onPressed: _forceSync,
            tooltip: 'Sync now',
          )
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            Card(
              child: ListTile(
                title: Text('Saved: ${_records.length}'),
                subtitle: Text('Synced: $syncedCount | Pending: $pendingCount'),
              ),
            ),
            const SizedBox(height: 12),
            Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _nameCtrl,
                    decoration: const InputDecoration(labelText: 'Respondent name'),
                    validator: (v) =>
                        (v == null || v.trim().isEmpty) ? 'Required' : null,
                  ),
                  TextFormField(
                    controller: _locationCtrl,
                    decoration: const InputDecoration(labelText: 'Location'),
                    validator: (v) =>
                        (v == null || v.trim().isEmpty) ? 'Required' : null,
                  ),
                  TextFormField(
                    controller: _notesCtrl,
                    decoration: const InputDecoration(labelText: 'Notes'),
                    maxLines: 3,
                    validator: (v) =>
                        (v == null || v.trim().isEmpty) ? 'Required' : null,
                  ),
                  const SizedBox(height: 12),
                  Row(
                    children: [
                      Expanded(
                        child: ElevatedButton(
                          onPressed: _saveSurvey,
                          child: const Text('Save Offline'),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            const Divider(),
            Expanded(
              child: RefreshIndicator(
                onRefresh: _loadRecords,
                child: ListView.builder(
                  itemCount: _records.length,
                  itemBuilder: (context, index) {
                    final r = _records[index];
                    return ListTile(
                      title: Text(r.respondentName),
                      subtitle: Text('${r.location}\n${r.notes}'),
                      isThreeLine: true,
                      trailing: Icon(
                        r.synced == 1 ? Icons.cloud_done : Icons.cloud_off,
                        color: r.synced == 1 ? Colors.green : Colors.orange,
                      ),
                    );
                  },
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
