import 'dart:async';
import 'package:flutter/material.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:uuid/uuid.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Hive.initFlutter();
  await Hive.openBox('surveys');
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Offline Survey App',
      theme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.green),
      home: const SurveyHomePage(),
      debugShowCheckedModeBanner: false,
    );
  }
}

class SurveyHomePage extends StatefulWidget {
  const SurveyHomePage({super.key});

  @override
  State<SurveyHomePage> createState() => _SurveyHomePageState();
}

class _SurveyHomePageState extends State<SurveyHomePage> {
  final _formKey = GlobalKey<FormState>();
  final _siteController = TextEditingController();
  final _latController = TextEditingController();
  final _lngController = TextEditingController();
  final _notesController = TextEditingController();

  final _box = Hive.box('surveys');
  final _uuid = const Uuid();
  StreamSubscription<List<ConnectivityResult>>? _subscription;
  bool _online = false;
  bool _syncing = false;

  @override
  void initState() {
    super.initState();
    _checkConnectivity();
    _subscription = Connectivity().onConnectivityChanged.listen((results) async {
      final connected = results.any((r) => r != ConnectivityResult.none);
      setState(() => _online = connected);
      if (connected) {
        await _syncPendingSurveys();
      }
    });
  }

  Future<void> _checkConnectivity() async {
    final results = await Connectivity().checkConnectivity();
    final connected = results.any((r) => r != ConnectivityResult.none);
    setState(() => _online = connected);
    if (connected) {
      await _syncPendingSurveys();
    }
  }

  Future<void> _saveSurvey() async {
    if (!_formKey.currentState!.validate()) return;

    final survey = {
      'id': _uuid.v4(),
      'site': _siteController.text.trim(),
      'lat': double.parse(_latController.text.trim()),
      'lng': double.parse(_lngController.text.trim()),
      'notes': _notesController.text.trim(),
      'createdAt': DateTime.now().toIso8601String(),
      'synced': false,
    };

    await _box.add(survey);

    _siteController.clear();
    _latController.clear();
    _lngController.clear();
    _notesController.clear();

    setState(() {});
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Survey saved locally')),
    );

    if (_online) {
      await _syncPendingSurveys();
    }
  }

  Future<void> _syncPendingSurveys() async {
    if (_syncing) return;
    setState(() => _syncing = true);

    try {
      for (int i = 0; i < _box.length; i++) {
        final item = _box.getAt(i);
        if (item is Map && item['synced'] == false) {
          // Mock network upload:
          await Future.delayed(const Duration(milliseconds: 500));

          // Mark as synced after successful upload
          item['synced'] = true;
          await _box.putAt(i, item);
        }
      }

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Pending surveys synced')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Sync failed: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _syncing = false);
    }
  }

  @override
  void dispose() {
    _subscription?.cancel();
    _siteController.dispose();
    _latController.dispose();
    _lngController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final surveys = _box.values.toList().reversed.toList();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Offline Survey App'),
        actions: [
          Center(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 12),
              child: Text(
                _online ? 'Online' : 'Offline',
                style: TextStyle(
                  color: _online ? Colors.green : Colors.red,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ),
          IconButton(
            onPressed: _syncing ? null : _syncPendingSurveys,
            icon: _syncing
                ? const SizedBox(
                    width: 18,
                    height: 18,
                    child: CircularProgressIndicator(strokeWidth: 2),
                  )
                : const Icon(Icons.sync),
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16),
            child: Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _siteController,
                    decoration: const InputDecoration(labelText: 'Site Name'),
                    validator: (v) =>
                        v == null || v.trim().isEmpty ? 'Required' : null,
                  ),
                  TextFormField(
                    controller: _latController,
                    decoration: const InputDecoration(labelText: 'Latitude'),
                    keyboardType: TextInputType.number,
                    validator: (v) =>
                        double.tryParse(v ?? '') == null ? 'Invalid number' : null,
                  ),
                  TextFormField(
                    controller: _lngController,
                    decoration: const InputDecoration(labelText: 'Longitude'),
                    keyboardType: TextInputType.number,
                    validator: (v) =>
                        double.tryParse(v ?? '') == null ? 'Invalid number' : null,
                  ),
                  TextFormField(
                    controller: _notesController,
                    decoration: const InputDecoration(labelText: 'Notes'),
                    maxLines: 2,
                  ),
                  const SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton(
                      onPressed: _saveSurvey,
                      child: const Text('Save Survey'),
                    ),
                  ),
                ],
              ),
            ),
          ),
          const Divider(height: 1),
          Expanded(
            child: surveys.isEmpty
                ? const Center(child: Text('No surveys saved yet'))
                : ListView.builder(
                    itemCount: surveys.length,
                    itemBuilder: (context, index) {
                      final survey = surveys[index] as Map;
                      return ListTile(
                        title: Text(survey['site'] ?? ''),
                        subtitle: Text(
                          '${survey['lat']}, ${survey['lng']}\n${survey['notes'] ?? ''}',
                        ),
                        isThreeLine: true,
                        trailing: Icon(
                          survey['synced'] == true
                              ? Icons.cloud_done
                              : Icons.cloud_off,
                          color: survey['synced'] == true
                              ? Colors.green
                              : Colors.orange,
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}
