### `lib/local_store.dart`

```dart
import 'dart:convert';
import 'package:hive/hive.dart';
import 'survey_record.dart';

class LocalStore {
  static const String boxName = 'survey_records';
  late Box<String> _box;

  Future<void> init() async {
    _box = await Hive.openBox<String>(boxName);
  }

  Future<void> saveRecord(SurveyRecord record) async {
    await _box.put(record.id, jsonEncode(record.toJson()));
  }

  List<SurveyRecord> getAllRecords() {
    return _box.values
        .map((value) => SurveyRecord.fromJson(jsonDecode(value)))
        .toList()
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
  }

  Future<List<SurveyRecord>> getUnsyncedRecords() async {
    return getAllRecords().where((record) => !record.synced).toList();
  }

  Future<void> markSynced(String id) async {
    final raw = _box.get(id);
    if (raw == null) return;

    final record = SurveyRecord.fromJson(jsonDecode(raw));
    final updated = record.copyWith(synced: true);
    await saveRecord(updated);
  }
}
```

