### `lib/sync_service.dart`

This example syncs to a fake endpoint. Replace it with your real backend later.

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import 'local_store.dart';

class SyncService {
  final LocalStore store;

  SyncService(this.store);

  Future<void> syncPending() async {
    final unsynced = await store.getUnsyncedRecords();

    for (final record in unsynced) {
      try {
        final response = await http.post(
          Uri.parse('https://example.com/api/surveys'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode(record.toJson()),
        );

        if (response.statusCode >= 200 && response.statusCode < 300) {
          await store.markSynced(record.id);
        }
      } catch (_) {
        // Keep record unsynced; will retry later
      }
    }
  }
}
```

