```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { Pool } from "pg";
import jwt from "jsonwebtoken";
import Stripe from "stripe";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

app.use(cors());
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "", {
  apiVersion: "2024-06-20"
});

const JWT_SECRET = process.env.JWT_SECRET || "dev-secret";

// --- Auth middleware ---
function authMiddleware(req: any, res: any, next: any) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    const token = auth.slice(7);
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

// --- Basic health check ---
app.get("/health", (_, res) => res.json({ ok: true }));

// --- Register/login demo endpoints ---
app.post("/auth/token", async (req, res) => {
  const { userId } = req.body;
  if (!userId) return res.status(400).json({ error: "userId required" });

  const token = jwt.sign({ userId }, JWT_SECRET, { expiresIn: "7d" });
  res.json({ token });
});

// --- Send message ---
app.post("/messages", authMiddleware, async (req: any, res) => {
  const { recipientId, content } = req.body;
  const senderId = req.user.userId;

  if (!recipientId || !content) {
    return res.status(400).json({ error: "recipientId and content required" });
  }

  const messageId = uuidv4();
  const createdAt = new Date().toISOString();

  await pool.query(
    `
    INSERT INTO messages (id, sender_id, recipient_id, content, created_at)
    VALUES ($1, $2, $3, $4, $5)
    `,
    [messageId, senderId, recipientId, content, createdAt]
  );

  // Real-time delivery
  io.to(`user:${recipientId}`).emit("message:new", {
    id: messageId,
    senderId,
    recipientId,
    content,
    createdAt
  });

  // Notification event
  io.to(`user:${recipientId}`).emit("notification:new", {
    type: "message",
    title: "New message",
    body: content.slice(0, 80)
  });

  res.json({ id: messageId, senderId, recipientId, content, createdAt });
});

// --- Fetch conversations ---
app.get("/messages/:otherUserId", authMiddleware, async (req: any, res) => {
  const userId = req.user.userId;
  const { otherUserId } = req.params;

  const result = await pool.query(
    `
    SELECT *
    FROM messages
    WHERE (sender_id = $1 AND recipient_id = $2)
       OR (sender_id = $2 AND recipient_id = $1)
    ORDER BY created_at ASC
    `,
    [userId, otherUserId]
  );

  res.json(result.rows);
});

// --- Monetization: create Stripe checkout session ---
app.post("/billing/create-checkout-session", authMiddleware, async (req: any, res) => {
  const userId = req.user.userId;
  const { priceId } = req.body;

  if (!priceId) return res.status(400).json({ error: "priceId required" });

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: "https://yourapp.com/success",
    cancel_url: "https://yourapp.com/cancel",
    client_reference_id: userId
  });

  res.json({ url: session.url });
});

// --- Webhook for Stripe events ---
app.post(
  "/billing/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"] as string;
    let event: Stripe.Event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET || ""
      );
    } catch (err: any) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object as Stripe.Checkout.Session;
      const userId = session.client_reference_id;

      if (userId) {
        await pool.query(
          `UPDATE users SET is_premium = TRUE WHERE id = $1`,
          [userId]
        );
      }
    }

    res.json({ received: true });
  }
);

// --- Socket.IO ---
io.use((socket, next) => {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error("Unauthorized"));

  try {
    const decoded = jwt.verify(token, JWT_SECRET) as any;
    socket.data.userId = decoded.userId;
    next();
  } catch {
    next(new Error("Unauthorized"));
  }
});

io.on("connection", (socket) => {
  const userId = socket.data.userId;
  socket.join(`user:${userId}`);

  socket.emit("connected", { userId });

  socket.on("typing:start", ({ toUserId }) => {
    io.to(`user:${toUserId}`).emit("typing:start", { fromUserId: userId });
  });

  socket.on("typing:stop", ({ toUserId }) => {
    io.to(`user:${toUserId}`).emit("typing:stop", { fromUserId: userId });
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

