## 7) `src/messages.ts`

```ts
import { Router } from "express";
import { prisma } from "./prisma";
import { AuthRequest, protect } from "./auth";

export const messagesRouter = Router();

messagesRouter.post("/conversations", protect, async (req: AuthRequest, res) => {
  const { participantIds } = req.body as { participantIds: string[] };

  if (!participantIds?.length) {
    return res.status(400).json({ error: "participantIds required" });
  }

  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: [
          { userId: req.user!.userId },
          ...participantIds.map((id) => ({ userId: id }))
        ]
      }
    },
    include: { members: true }
  });

  res.json(conversation);
});

messagesRouter.get("/conversations/:id/messages", protect, async (req, res) => {
  const { id } = req.params;

  const messages = await prisma.message.findMany({
    where: { conversationId: id },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

messagesRouter.post("/conversations/:id/messages", protect, async (req: AuthRequest, res) => {
  const { id } = req.params;
  const { text } = req.body as { text: string };

  if (!text?.trim()) {
    return res.status(400).json({ error: "text required" });
  }

  const message = await prisma.message.create({
    data: {
      text,
      senderId: req.user!.userId,
      conversationId: id
    }
  });

  const members = await prisma.membership.findMany({
    where: { conversationId: id }
  });

  const notificationTargets = members
    .map((m) => m.userId)
    .filter((uid) => uid !== req.user!.userId);

  await prisma.notification.createMany({
    data: notificationTargets.map((userId) => ({
      userId,
      type: "new_message",
      payload: JSON.stringify({ conversationId: id, messageId: message.id })
    }))
  });

  res.json(message);
});
```

