## 8) `src/payments.ts`

```ts
import { Router } from "express";
import Stripe from "stripe";
import { protect, AuthRequest } from "./auth";
import { prisma } from "./prisma";

export const paymentsRouter = Router();

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "sk_test_dummy", {
  apiVersion: "2024-06-20"
});

paymentsRouter.post("/create-checkout-session", protect, async (req: AuthRequest, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    line_items: [
      {
        price: process.env.STRIPE_PRICE_ID!,
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: {
      userId: req.user!.userId
    }
  });

  res.json({ url: session.url });
});

paymentsRouter.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"] as string;
  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET || "whsec_dummy"
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as Stripe.Checkout.Session;
    const userId = session.metadata?.userId;

    if (userId) {
      await prisma.subscription.upsert({
        where: { userId },
        create: {
          userId,
          status: "active",
          stripeCustomerId: session.customer as string | null,
          stripeSubscriptionId: session.subscription as string | null
        },
        update: {
          status: "active",
          stripeCustomerId: session.customer as string | null,
          stripeSubscriptionId: session.subscription as string | null
        }
      });
    }
  }

  res.json({ received: true });
});
```

