# 4) Real-time chat via Socket.IO

## `src/sockets/chat.ts`
```ts
import { Server, Socket } from "socket.io";
import { prisma } from "../prisma";

export function registerChatSockets(io: Server) {
  io.on("connection", (socket: Socket) => {
    console.log("connected", socket.id);

    socket.on("join_chat", async (chatId: string) => {
      socket.join(chatId);
    });

    socket.on("send_message", async (payload: { chatId: string; senderId: string; text: string }) => {
      const message = await prisma.message.create({
        data: {
          chatId: payload.chatId,
          senderId: payload.senderId,
          text: payload.text
        },
        include: { sender: true }
      });

      io.to(payload.chatId).emit("new_message", message);

      // Placeholder for notification fan-out
      io.to(payload.chatId).emit("notify_users", {
        chatId: payload.chatId,
        title: "New message",
        body: payload.text
      });
    });

    socket.on("disconnect", () => {
      console.log("disconnected", socket.id);
    });
  });
}
```

