  };

  const amount = priceMap[coins];
  if (!amount) return res.status(400).json({ error: "Invalid coin pack" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: "https://yourapp.com/success",
    cancel_url: "https://yourapp.com/cancel",
    line_items: [
      {
        quantity: 1,
        price_data: {
          currency: "usd",
          product_data: { name: `${coins} Coins` },
          unit_amount: amount
        }
      }
    ],
    metadata: { userId, coins: String(coins) }
  });

  res.json({ url: session.url });
});

