## `backend/src/routes.ts`

```ts
import { Router } from "express";
import { prisma } from "./prisma";
import { authMiddleware, comparePassword, hashPassword, signToken } from "./auth";
import { createCheckoutSession } from "./monetization";

const router = Router();

router.post("/auth/register", async (req, res) => {
  const { email, password, displayName } = req.body;

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) return res.status(400).json({ error: "User already exists" });

  const user = await prisma.user.create({
    data: {
      email,
      displayName,
      passwordHash: await hashPassword(password)
    }
  });

  const token = signToken(user.id);
  res.json({ token, user });
});

router.post("/auth/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });

  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await comparePassword(password, user.passwordHash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = signToken(user.id);
  res.json({ token, user });
});

router.get("/me", authMiddleware, async (req: any, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.userId },
    include: { subscriptions: true }
  });
  res.json(user);
});

router.get("/conversations/:id/messages", authMiddleware, async (req, res) => {
  const messages = await prisma.message.findMany({
    where: { conversationId: req.params.id },
    orderBy: { createdAt: "asc" }
  });
  res.json(messages);
});

router.post("/checkout", authMiddleware, async (req: any, res) => {
  const session = await createCheckoutSession(req.userId);
  res.json({ url: session.url });
});

export default router;
```

