import React, { useEffect, useState } from "react";
import { SafeAreaView, View, Text, TextInput, Button, FlatList } from "react-native";
import { io, Socket } from "socket.io-client";

const API_URL = "http://localhost:4000";
let socket: Socket | null = null;

export default function App() {
  const [token, setToken] = useState("");
  const [email, setEmail] = useState("demo@example.com");
  const [password, setPassword] = useState("password123");
  const [displayName, setDisplayName] = useState("Demo User");
  const [message, setMessage] = useState("");
  const [messages, setMessages] = useState<any[]>([]);

  useEffect(() => {
    if (!token) return;

    socket = io(API_URL, {
      auth: { token }
    });

    socket.on("newMessage", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (n) => {
      console.log("Notification:", n);
    });

    return () => {
      socket?.disconnect();
    };
  }, [token]);

  const register = async () => {
    const res = await fetch(`${API_URL}/api/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password, displayName })
    });
    const data = await res.json();
    setToken(data.token);
  };

  const login = async () => {
    const res = await fetch(`${API_URL}/api/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password })
    });
    const data = await res.json();
    setToken(data.token);
  };

  const sendMessage = () => {
    socket?.emit("sendMessage", {
      conversationId: "demo-conversation",
      text: message,
      recipientId: null
    });
    setMessage("");
  };

  const checkout = async () => {
    const res = await fetch(`${API_URL}/api/checkout`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`
      }
    });
    const data = await res.json();
    console.log("Stripe checkout URL:", data.url);
  };

  if (!token) {
    return (
      <SafeAreaView style={{ padding: 20 }}>
        <Text>Register / Login</Text>
        <TextInput value={displayName} onChangeText={setDisplayName} placeholder="Display name" />
        <TextInput value={email} onChangeText={setEmail} placeholder="Email" />
        <TextInput value={password} onChangeText={setPassword} placeholder="Password" secureTextEntry />
        <Button title="Register" onPress={register} />
        <Button title="Login" onPress={login} />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={{ flex: 1, padding: 20 }}>
      <Text>Messaging App</Text>
      <Button title="Upgrade / Monetize" onPress={checkout} />

      <FlatList
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <Text>{item.text}</Text>}
      />

      <View style={{ flexDirection: "row", gap: 8 }}>
