## 5.2 Message socket handlers

`backend/src/sockets/messageSocket.ts`

```ts
import { Server, Socket } from "socket.io";
import { prisma } from "../utils/prisma";

export const registerMessageHandlers = (io: Server, socket: Socket) => {
  const userId = socket.data.userId;

  socket.join(userId);

  socket.on("message:send", async (payload, ack) => {
    try {
      const { conversationId, content } = payload;

      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId: userId,
          content,
        },
      });

      const participants = await prisma.conversationParticipant.findMany({
        where: { conversationId },
        select: { userId: true },
      });

      participants.forEach((p) => {
        io.to(p.userId).emit("message:new", message);
      });

      if (ack) ack({ ok: true, message });
    } catch (err) {
      if (ack) ack({ ok: false, error: "Failed to send message" });
    }
  });

  socket.on("message:read", async ({ messageId, conversationId }) => {
    await prisma.message.update({
      where: { id: messageId },
      data: { readAt: new Date() },
    });

    await prisma.conversationParticipant.updateMany({
      where: { conversationId, userId },
      data: { lastReadAt: new Date() },
    });

    io.to(conversationId).emit("message:read", { messageId, userId });
  });
};
```

