# 6) Real-time messaging and notifications

## `src/sockets/index.ts`
```ts
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import Message from "../models/Message";
import Conversation from "../models/Conversation";
import Notification from "../models/Notification";

let io: Server;

export function initSocket(server: any) {
  io = new Server(server, {
    cors: { origin: process.env.CLIENT_URL, credentials: true }
  });

  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth.token;
      if (!token) return next(new Error("Unauthorized"));

      const decoded = jwt.verify(token, process.env.JWT_SECRET!) as any;
      socket.data.userId = decoded.sub;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("join_conversation", (conversationId) => {
      socket.join(conversationId);
    });

    socket.on("send_message", async ({ conversationId, text }) => {
      const senderId = socket.data.userId;

      const message = await Message.create({
        conversationId,
        senderId,
        text,
        readBy: [senderId]
      });

      await Conversation.findByIdAndUpdate(conversationId, { lastMessageAt: new Date() });

      const convo = await Conversation.findById(conversationId).populate("participants");
      if (convo) {
        for (const participant of convo.participants as any[]) {
          if (participant._id.toString() === senderId) continue;

          const notification = await Notification.create({
            userId: participant._id,
            type: "message",
            title: "New message",
            body: `You received a new message`
          });

          io.to(participant._id.toString()).emit("notification", notification);
          io.to(conversationId).emit("new_message", message);
        }
      }
    });

    socket.on("mark_read", async ({ messageId }) => {
      const userId = socket.data.userId;
      await Message.findByIdAndUpdate(messageId, { $addToSet: { readBy: userId } });
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });
}

export function getIO() {
  if (!io) throw new Error("Socket.IO not initialized");
  return io;
}
```

