import { useEffect, useState } from "react";
import { api } from "../api";

export function Chat({ socket, token }: any) {
  const [users, setUsers] = useState<any[]>([]);
  const [selectedUser, setSelectedUser] = useState<any>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api("/users", {}, token).then(setUsers);
  }, [token]);

  useEffect(() => {
    if (!socket) return;

    socket.on("message:received", (msg: any) => {
      if (selectedUser && msg.senderId === selectedUser.id) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => {
      socket.off("message:received");
    };
  }, [socket, selectedUser]);

  async function selectUser(u: any) {
    setSelectedUser(u);
    const msgs = await api(`/messages/${u.id}`, {}, token);
    setMessages(msgs);
  }

  async function send() {
    if (!selectedUser || !content.trim()) return;

    const msg = await api(
      "/messages",
      {
        method: "POST",
        body: JSON.stringify({ receiverId: selectedUser.id, content })
      },
      token
    );

    setMessages((prev) => [...prev, msg]);
    setContent("");
  }

  return (
    <div>
      <h2>Chat</h2>
      <div style={{ display: "flex", gap: 16 }}>
        <div style={{ width: 200 }}>
          {users.map((u) => (
            <div key={u.id}>
              <button onClick={() => selectUser(u)}>{u.displayName}</button>
            </div>
          ))}
        </div>

        <div style={{ flex: 1 }}>
          <div style={{ minHeight: 300, border: "1px solid #ccc", padding: 8 }}>
            {messages.map((m) => (
              <div key={m.id}>
                <b>{m.senderId === selectedUser?.id ? selectedUser.displayName : "You"}:</b> {m.content}
              </div>
            ))}
          </div>

          <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Type a message..." />
          <button onClick={send}>Send</button>
        </div>
      </div>
    </div>
  );
}
