```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import path from "path";

type Message = {
  id: number;
  user: string;
  text: string;
  timestamp: number;
};

type UserWallet = {
  coins: number;
};

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

const PORT = process.env.PORT || 3000;

app.use(express.static(path.join(__dirname, "../public")));

let messages: Message[] = [];
let messageId = 1;

// Minimal in-memory wallet store
const wallets = new Map<string, UserWallet>();

function getWallet(user: string): UserWallet {
  const existing = wallets.get(user);
  if (existing) return existing;
  const created = { coins: 0 };
  wallets.set(user, created);
  return created;
}

// Basic health route
app.get("/health", (_, res) => {
  res.json({ ok: true });
});

// Get messages
app.get("/api/messages", (_, res) => {
  res.json(messages);
});

// Get wallet balance
app.get("/api/wallet/:user", (req, res) => {
  const { user } = req.params;
  res.json({ user, coins: getWallet(user).coins });
});

// "Purchase" coins - mock monetization endpoint
app.post("/api/purchase", (req, res) => {
  const { user, amount } = req.body as { user: string; amount: number };

  if (!user || !amount || amount <= 0) {
    return res.status(400).json({ error: "Invalid user or amount" });
  }

  const wallet = getWallet(user);
  wallet.coins += amount;

  io.emit("notification", {
    type: "purchase",
    user,
    message: `${user} purchased ${amount} coins`
  });

  return res.json({ user, coins: wallet.coins });
});

// Send message
app.post("/api/messages", (req, res) => {
  const { user, text } = req.body as { user: string; text: string };

  if (!user || !text) {
    return res.status(400).json({ error: "User and text are required" });
  }

  // Optional monetization rule:
  // each message costs 1 coin; if no coins, allow sending but mark as free.
  const wallet = getWallet(user);
  const paid = wallet.coins > 0;
  if (paid) wallet.coins -= 1;

  const message: Message = {
    id: messageId++,
    user,
    text,
    timestamp: Date.now()
  };

  messages.push(message);

  io.emit("message", message);
  io.emit("notification", {
    type: "message",
    user,
    message: `${user} sent a message${paid ? " (1 coin deducted)" : ""}`
  });

  res.json({
    ok: true,
    message,
    wallet: { coins: wallet.coins },
    paid
  });
});

io.on("connection", (socket) => {
  console.log("Socket connected:", socket.id);

  socket.emit("notification", {
    type: "system",
    message: "Connected to real-time server"
  });

  socket.on("disconnect", () => {
    console.log("Socket disconnected:", socket.id);
  });
});

app.get("/", (_, res) => {
  res.sendFile(path.join(__dirname, "../public/index.html"));
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

