      <input id="text" placeholder="Type a message..." />
      <button id="sendBtn">Send</button>
    </div>

    <div class="row">
      <input id="coins" type="number" placeholder="Coins to buy" value="5" />
      <button id="buyBtn">Buy Coins</button>
    </div>

    <p class="small">Wallet: <span id="wallet">0</span> coins</p>

    <h3>Notifications</h3>
    <div id="notifications"></div>

    <h3>Messages</h3>
    <div id="messages"></div>

    <script src="/socket.io/socket.io.js"></script>
    <script>
      const userInput = document.getElementById("user");
      const textInput = document.getElementById("text");
      const coinsInput = document.getElementById("coins");
      const walletEl = document.getElementById("wallet");
      const messagesEl = document.getElementById("messages");
      const notificationsEl = document.getElementById("notifications");
      const connectBtn = document.getElementById("connectBtn");
      const sendBtn = document.getElementById("sendBtn");
      const buyBtn = document.getElementById("buyBtn");

      let socket = null;

      function addMessage(m) {
        const div = document.createElement("div");
        div.className = "msg";
        div.textContent = `[${new Date(m.timestamp).toLocaleTimeString()}] ${m.user}: ${m.text}`;
        messagesEl.prepend(div);
      }

      function addNotification(n) {
        const div = document.createElement("div");
        div.className = "notif";
        div.textContent = n.message;
        notificationsEl.prepend(div);
      }

      async function refreshMessages() {
        const res = await fetch("/api/messages");
        const data = await res.json();
        messagesEl.innerHTML = "";
        data.slice().reverse().forEach(addMessage);
      }

      async function refreshWallet() {
        const user = userInput.value.trim();
        if (!user) return;
        const res = await fetch(`/api/wallet/${encodeURIComponent(user)}`);
        const data = await res.json();
        walletEl.textContent = data.coins;
      }

      connectBtn.onclick = async () => {
        if (socket) socket.disconnect();
        socket = io();

        socket.on("message", (m) => {
          addMessage(m);
        });

        socket.on("notification", (n) => {
          addNotification(n);
          refreshWallet();
        });

        await refreshMessages();
        await refreshWallet();
      };

      sendBtn.onclick = async () => {
        const user = userInput.value.trim();
        const text = textInput.value.trim();
        if (!user || !text) return alert("Enter username and message");

        const res = await fetch("/api/messages", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ user, text })
        });

        const data = await res.json();
        if (!res.ok) return alert(data.error || "Failed to send");
        textInput.value = "";
        walletEl.textContent = data.wallet.coins;
      };

      buyBtn.onclick = async () => {
        const user = userInput.value.trim();
        const amount = Number(coinsInput.value);
        if (!user || !amount) return alert("Enter username and coin amount");

        const res = await fetch("/api/purchase", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ user, amount })
        });

        const data = await res.json();
        if (!res.ok) return alert(data.error || "Purchase failed");
        walletEl.textContent = data.coins;
      };

      userInput.addEventListener("change", refreshWallet);
      refreshMessages();
      refreshWallet();
    </script>
  </body>
</html>
