### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { messages, users, type User } from "./store";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const PORT = process.env.PORT || 3001;

function getOrCreateUser(id: string, name?: string): User {
  if (!users[id]) {
    users[id] = {
      id,
      name: name || `User-${id.slice(0, 4)}`,
      coins: 10 // starter coins
    };
  } else if (name && users[id].name !== name) {
    users[id].name = name;
  }
  return users[id];
}

app.get("/api/health", (_req, res) => {
  res.json({ ok: true });
});

app.get("/api/messages", (_req, res) => {
  res.json(messages);
});

app.get("/api/users/:id", (req, res) => {
  const user = users[req.params.id];
  if (!user) return res.status(404).json({ error: "User not found" });
  res.json(user);
});

// Simulated in-app purchase: buy 20 coins for demo purposes
app.post("/api/purchase", (req, res) => {
  const { userId } = req.body as { userId?: string };

  if (!userId) {
    return res.status(400).json({ error: "userId is required" });
  }

  const user = getOrCreateUser(userId);
  user.coins += 20;

  io.to(userId).emit("notification", {
    type: "purchase",
    message: "Purchase successful: +20 coins"
  });

  res.json({ ok: true, coins: user.coins });
});

io.on("connection", (socket) => {
  const userId = socket.handshake.query.userId as string | undefined;
  const userName = socket.handshake.query.name as string | undefined;

  if (!userId) {
    socket.disconnect();
    return;
  }

  const user = getOrCreateUser(userId, userName);
  socket.join(userId);

  io.to(userId).emit("notification", {
    type: "system",
    message: `Welcome, ${user.name}! You have ${user.coins} coins.`
  });

  socket.emit("messages", messages);

  socket.on("send_message", (data: { text: string }) => {
    const text = data.text?.trim();
    if (!text) return;

    if (user.coins <= 0) {
      socket.emit("notification", {
        type: "error",
        message: "Not enough coins. Purchase more to continue messaging."
      });
      return;
    }

    user.coins -= 1;

    const message = {
      id: crypto.randomUUID(),
      from: user.name,
      text,
      timestamp: Date.now()
    };

    messages.push(message);
    io.emit("message", message);

    io.to(userId).emit("notification", {
      type: "coin",
      message: `Sent message. -1 coin. Balance: ${user.coins}`
    });
  });

  socket.on("disconnect", () => {
    // no-op for minimal demo
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

