```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type Message = {
  id: string;
  from: string;
  text: string;
  timestamp: number;
};

type Notification = {
  type: string;
  message: string;
};

const SERVER_URL = "http://localhost:3001";

export default function App() {
  const [userId, setUserId] = useState(() => localStorage.getItem("userId") || "");
  const [name, setName] = useState(() => localStorage.getItem("name") || "");
  const [connected, setConnected] = useState(false);
  const [socket, setSocket] = useState<Socket | null>(null);

  const [messages, setMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [text, setText] = useState("");
  const [coins, setCoins] = useState(10);

  const canConnect = useMemo(() => userId.trim().length > 0 && name.trim().length > 0, [userId, name]);

  useEffect(() => {
    if (!socket) return;

    socket.on("connect", () => setConnected(true));
    socket.on("disconnect", () => setConnected(false));
    socket.on("messages", (msgs: Message[]) => setMessages(msgs));
    socket.on("message", (msg: Message) => setMessages((prev) => [...prev, msg]));
    socket.on("notification", (n: Notification) => {
      setNotifications((prev) => [n, ...prev].slice(0, 5));
      if (n.message.includes("Balance:")) {
        const match = n.message.match(/Balance:\s(\d+)/);
        if (match) setCoins(Number(match[1]));
      }
    });

    return () => {
      socket.off("connect");
      socket.off("disconnect");
      socket.off("messages");
      socket.off("message");
      socket.off("notification");
    };
  }, [socket]);

  function connect() {
    localStorage.setItem("userId", userId);
    localStorage.setItem("name", name);

    const s = io(SERVER_URL, {
      query: { userId, name }
    });

    setSocket(s);
  }

  async function purchaseCoins() {
    const res = await fetch(`${SERVER_URL}/api/purchase`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId })
    });
    const data = await res.json();
    if (data.coins !== undefined) setCoins(data.coins);
  }

  function sendMessage() {
    if (!socket || !text.trim()) return;
    socket.emit("send_message", { text });
    setText("");
  }

  return (
    <div className="app">
      <h1>Social Messaging App</h1>

      <div className="card">
        <h2>Login</h2>
        <input
          placeholder="User ID"
          value={userId}
          onChange={(e) => setUserId(e.target.value)}
        />
        <input
          placeholder="Display name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <button onClick={connect} disabled={!canConnect}>
          Connect
        </button>
        <p>Status: {connected ? "Connected" : "Disconnected"}</p>
        <p>Coins: {coins}</p>
        <button onClick={purchaseCoins} disabled={!userId}>
          Buy 20 coins
        </button>
      </div>

      <div className="card">
        <h2>Send Message</h2>
        <textarea
          placeholder="Type a message..."
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <button onClick={sendMessage} disabled={!connected}>
          Send
        </button>
      </div>

      <div className="card">
        <h2>Notifications</h2>
        {notifications.map((n, i) => (
          <div key={i} className={`notice ${n.type}`}>
            {n.message}
          </div>
        ))}
      </div>

      <div className="card">
        <h2>Messages</h2>
        {messages.map((m) => (
          <div key={m.id} className="message">
            <strong>{m.from}:</strong> {m.text}
          </div>
        ))}
      </div>
    </div>
  );
}
