# 3) `server.ts`

```typescript
import express from "express";
import http from "http";
import { Server } from "socket.io";
import path from "path";

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

type UserState = {
  username: string;
  coins: number;
};

const users = new Map<string, UserState>(); // socket.id -> user
const history: { username: string; text: string; ts: number }[] = [];

io.on("connection", (socket) => {
  socket.on("join", ({ username }) => {
    const safeName = String(username || "Anonymous").slice(0, 20);
    users.set(socket.id, { username: safeName, coins: 0 });

    socket.emit("joined", {
      username: safeName,
      coins: 0,
      history
    });

    io.emit("notification", {
      text: `${safeName} joined the chat`
    });
  });

  socket.on("buyCoins", ({ amount }) => {
    const user = users.get(socket.id);
    if (!user) return;

    const coinsToAdd = Math.max(0, Math.min(Number(amount || 0), 1000));
    user.coins += coinsToAdd;

    socket.emit("walletUpdate", {
      coins: user.coins
    });

    socket.emit("notification", {
      text: `Purchased ${coinsToAdd} coins`
    });
  });

  socket.on("sendMessage", ({ text }) => {
    const user = users.get(socket.id);
    if (!user) return;

    const messageText = String(text || "").trim().slice(0, 500);
    if (!messageText) return;

    const message = {
      username: user.username,
      text: messageText,
      ts: Date.now()
    };

    history.push(message);
    if (history.length > 50) history.shift();

    io.emit("message", message);
    io.emit("notification", {
      text: `${user.username} sent a message`
    });
  });

  socket.on("disconnect", () => {
    const user = users.get(socket.id);
    if (user) {
      io.emit("notification", {
        text: `${user.username} left the chat`
      });
    }
    users.delete(socket.id);
  });
});

server.listen(3000, () => {
  console.log("Messaging app running on http://localhost:3000");
});
```

