  div.textContent = `[${new Date(msg.ts).toLocaleTimeString()}] ${msg.username}: ${msg.text}`;
  chatEl.appendChild(div);
  chatEl.scrollTop = chatEl.scrollHeight;
}

function addNotification(text) {
  const div = document.createElement("div");
  div.className = "notification";
  div.textContent = `• ${text}`;
  notificationsEl.appendChild(div);
  notificationsEl.scrollTop = notificationsEl.scrollHeight;
}

joinBtn.onclick = () => {
  const username = usernameEl.value.trim();
  if (!username) return alert("Enter a username");
  socket.emit("join", { username });
};

sendBtn.onclick = () => {
  if (!joined) return alert("Join first");
  const text = messageInput.value.trim();
  if (!text) return;
  socket.emit("sendMessage", { text });
  messageInput.value = "";
};

buyBtn.onclick = () => {
  if (!joined) return alert("Join first");
  const amount = Number(coinAmountEl.value || 0);
  socket.emit("buyCoins", { amount });
};

socket.on("joined", ({ username, coins, history }) => {
  joined = true;
  currentUserEl.textContent = username;
  coinsEl.textContent = coins;
  chatEl.innerHTML = "";
  notificationsEl.innerHTML = "";
  history.forEach(addMessage);
  addNotification(`Welcome, ${username}!`);
});

socket.on("message", (msg) => {
  addMessage(msg);
});

socket.on("notification", ({ text }) => {
  addNotification(text);
});

socket.on("walletUpdate", ({ coins }) => {
  coinsEl.textContent = coins;
});
