### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server as SocketIOServer } from "socket.io";
import { stripe } from "./stripe";

const app = express();
const server = http.createServer(app);
const io = new SocketIOServer(server, {
  cors: { origin: "*" }
});

app.use(cors());
app.use(express.json());
app.use(express.static("../public"));

type User = {
  id: string;
  name: string;
  premium: boolean;
};

const users = new Map<string, User>();

io.on("connection", (socket) => {
  socket.on("join", ({ userId, name }) => {
    const existing = users.get(userId) || { id: userId, name, premium: false };
    existing.name = name;
    users.set(userId, existing);
    socket.data.userId = userId;

    io.emit("user-status", {
      userId,
      name,
      premium: existing.premium,
      status: "joined"
    });
  });

  socket.on("message", ({ userId, text }) => {
    const user = users.get(userId);
    if (!user) return;

    const message = {
      id: crypto.randomUUID(),
      userId,
      name: user.name,
      premium: user.premium,
      text,
      timestamp: new Date().toISOString()
    };

    // Broadcast message in real time
    io.emit("message", message);

    // Broadcast notification event
    io.emit("notification", {
      title: "New Message",
      body: `${user.name}: ${text}`
    });
  });

  socket.on("disconnect", () => {
    const userId = socket.data.userId;
    if (userId) {
      const user = users.get(userId);
      if (user) {
        io.emit("user-status", {
          userId,
          name: user.name,
          premium: user.premium,
          status: "left"
        });
      }
    }
  });
});

// Create Stripe Checkout session
app.post("/create-checkout-session", async (req, res) => {
  const { userId } = req.body;

  try {
    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: "Premium Membership"
            },
            unit_amount: 499
          },
          quantity: 1
        }
      ],
      success_url: "http://localhost:3000?success=1",
      cancel_url: "http://localhost:3000?canceled=1",
      metadata: { userId }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: "Failed to create checkout session" });
  }
});

// Stripe webhook
app.post("/webhook", express.raw({ type: "application/json" }), (req, res) => {
  // In a real app, verify the webhook signature:
  // const sig = req.headers["stripe-signature"] as string;

  const event = req.body;

  if (event.type === "checkout.session.completed") {
    const userId = event.data.object.metadata?.userId;
    if (userId && users.has(userId)) {
      const user = users.get(userId)!;
      user.premium = true;
      users.set(userId, user);

      io.emit("premium-updated", {
        userId,
        premium: true
      });
    }
  }

  res.json({ received: true });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

> Note: `crypto.randomUUID()` works in modern Node versions.

