```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

type User = {
  id: string;
  username: string;
  coins: number;
};

type Message = {
  id: string;
  from: string;
  text: string;
  time: number;
};

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
  },
});

const users = new Map<string, User>();
const connectedSockets = new Map<string, string>(); // userId -> socketId
const messages: Message[] = [];

function makeId() {
  return Math.random().toString(36).slice(2, 10);
}

app.post("/login", (req, res) => {
  const { username } = req.body as { username?: string };

  if (!username || !username.trim()) {
    return res.status(400).json({ error: "Username is required" });
  }

  const clean = username.trim();
  const id = clean.toLowerCase();

  let user = users.get(id);
  if (!user) {
    user = { id, username: clean, coins: 0 };
    users.set(id, user);
  }

  return res.json(user);
});

app.get("/users", (_req, res) => {
  return res.json(Array.from(users.values()));
});

app.get("/messages", (_req, res) => {
  return res.json(messages.slice(-50));
});

app.post("/buy-coins", (req, res) => {
  const { userId, amount } = req.body as { userId?: string; amount?: number };

  if (!userId || typeof amount !== "number" || amount <= 0) {
    return res.status(400).json({ error: "Invalid request" });
  }

  const user = users.get(userId);
  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  // Minimal fake monetization
  user.coins += amount;

  // Real-time notification
  const socketId = connectedSockets.get(userId);
  if (socketId) {
    io.to(socketId).emit("notification", {
      type: "coins",
      message: `You purchased ${amount} coins. New balance: ${user.coins}`,
      coins: user.coins,
    });
  }

  return res.json(user);
});

io.on("connection", (socket) => {
  socket.on("register", (userId: string) => {
    connectedSockets.set(userId, socket.id);
  });

  socket.on("send_message", (payload: { userId: string; text: string }) => {
    const { userId, text } = payload;
    const user = users.get(userId);

    if (!user || !text.trim()) return;

    const msg: Message = {
      id: makeId(),
      from: user.username,
      text: text.trim(),
      time: Date.now(),
    };

    messages.push(msg);

    // Broadcast message to everyone
    io.emit("new_message", msg);

    // Broadcast notification to everyone except sender
    socket.broadcast.emit("notification", {
      type: "message",
      message: `${user.username} sent a new message`,
    });
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of connectedSockets.entries()) {
      if (socketId === socket.id) {
        connectedSockets.delete(userId);
      }
    }
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

