        if (data.error) {
          alert(data.error);
          return;
        }
        currentUser = data;
        renderUser();
        socket.emit("register", currentUser.id);
        await refreshUsers();
        await refreshMessages();
      };

      sendBtn.onclick = () => {
        if (!currentUser) return alert("Login first");
        const text = messageInput.value.trim();
        if (!text) return;

        socket.emit("send_message", {
          userId: currentUser.id,
          text
        });

        messageInput.value = "";
      };

      buyCoinsBtn.onclick = async () => {
        if (!currentUser) return alert("Login first");
        const res = await fetch(`${API}/buy-coins`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ userId: currentUser.id, amount: 10 })
        });
        const data = await res.json();
        if (data.error) {
          alert(data.error);
          return;
        }
        currentUser = data;
        renderUser();
        await refreshUsers();
      };

      socket.on("new_message", (msg) => {
        addMessage(msg);
      });

      socket.on("notification", (payload) => {
        addNotification(payload.message);
        if (payload.coins !== undefined && currentUser) {
          currentUser.coins = payload.coins;
          renderUser();
        }
      });

      refreshUsers();
      refreshMessages();
    </script>
