## 1) Backend (`server.ts`)

```ts
import express from "express";
import http from "http";
import { Server } from "socket.io";
import cors from "cors";

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"],
  },
});

app.use(cors());
app.use(express.json());

type DataPoint = {
  id: number;
  label: string;
  value: number;
  timestamp: string;
};

let data: DataPoint[] = [
  { id: 1, label: "A", value: 20, timestamp: new Date().toISOString() },
  { id: 2, label: "B", value: 35, timestamp: new Date().toISOString() },
  { id: 3, label: "C", value: 15, timestamp: new Date().toISOString() },
];

app.get("/api/data", (_req, res) => {
  res.json(data);
});

app.post("/api/data", (req, res) => {
  const { label, value } = req.body as { label?: string; value?: number };

  if (!label || typeof value !== "number") {
    return res.status(400).json({ error: "label and numeric value are required" });
  }

  const newPoint: DataPoint = {
    id: Date.now(),
    label,
    value,
    timestamp: new Date().toISOString(),
  };

  data = [...data, newPoint];

  io.emit("data:update", data);

  res.status(201).json(newPoint);
});

io.on("connection", (socket) => {
  socket.emit("data:update", data);

  socket.on("disconnect", () => {
    console.log("Client disconnected");
  });
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

