## 2) Frontend (`App.tsx`)

```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import { useForm } from "react-hook-form";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

type DataPoint = {
  id: number;
  label: string;
  value: number;
  timestamp: string;
};

type FormValues = {
  label: string;
  value: number;
};

const socket: Socket = io("http://localhost:3001");

export default function App() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [status, setStatus] = useState<string>("Connecting...");

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<FormValues>({
    defaultValues: {
      label: "",
      value: 0,
    },
  });

  useEffect(() => {
    socket.on("connect", () => setStatus("Connected"));
    socket.on("disconnect", () => setStatus("Disconnected"));
    socket.on("data:update", (incoming: DataPoint[]) => setData(incoming));

    return () => {
      socket.off("connect");
      socket.off("disconnect");
      socket.off("data:update");
    };
  }, []);

  const latestValue = useMemo(
    () => (data.length ? data[data.length - 1].value : 0),
    [data]
  );

  const onSubmit = async (values: FormValues) => {
    await fetch("http://localhost:3001/api/data", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        label: values.label,
        value: Number(values.value),
      }),
    });

    reset({ label: "", value: 0 });
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.title}>Real-Time Dashboard</h1>
      <p style={styles.status}>Status: {status}</p>

      <div style={styles.grid}>
        <section style={styles.card}>
          <h2>Live Chart</h2>
          <div style={{ width: "100%", height: 320 }}>
            <ResponsiveContainer>
              <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="label" />
                <YAxis />
                <Tooltip />
                <Line
                  type="monotone"
                  dataKey="value"
                  stroke="#4f46e5"
                  strokeWidth={3}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <div style={styles.metric}>
            Latest value: <strong>{latestValue}</strong>
          </div>
        </section>

        <section style={styles.card}>
          <h2>Add Data Point</h2>
          <form onSubmit={handleSubmit(onSubmit)} style={styles.form}>
            <label style={styles.label}>
              Label
              <input
                style={styles.input}
                {...register("label", { required: "Label is required" })}
                placeholder="Enter label"
              />
              {errors.label && (
                <span style={styles.error}>{errors.label.message}</span>
              )}
            </label>

            <label style={styles.label}>
              Value
              <input
                style={styles.input}
                type="number"
                {...register("value", {
                  required: "Value is required",
                  valueAsNumber: true,
                })}
              />
              {errors.value && (
                <span style={styles.error}>{errors.value.message}</span>
              )}
            </label>

            <button style={styles.button} disabled={isSubmitting} type="submit">
              {isSubmitting ? "Saving..." : "Add Point"}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  page: {
    fontFamily: "Arial, sans-serif",
    padding: "24px",
    background: "#f8fafc",
    minHeight: "100vh",
  },
  title: {
    marginBottom: "8px",
  },
  status: {
    marginBottom: "24px",
