  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');
    const activeUsersEl = document.getElementById('activeUsers');
    const requestsPerMinEl = document.getElementById('requestsPerMin');
    const errorCountEl = document.getElementById('errorCount');
    const eventTable = document.getElementById('eventTable');
    const eventForm = document.getElementById('eventForm');
    const resetBtn = document.getElementById('resetBtn');

    const labels = [];
    const usersData = [];
    const trafficData = [];
    const errorData = [];

    const MAX_POINTS = 12;

    function randomBetween(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function nowTime() {
      return new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
    }

    function pushEventRow(time, event, value) {
      if (eventTable.children.length === 1 && eventTable.children[0].textContent.includes('Waiting')) {
        eventTable.innerHTML = '';
      }

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${time}</td>
        <td>${event}</td>
        <td>${value}</td>
      `;
      eventTable.prepend(row);

      while (eventTable.children.length > 8) {
        eventTable.removeChild(eventTable.lastChild);
      }
    }

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [
          {
            label: 'Active Users',
            data: usersData,
            borderColor: '#38bdf8',
            backgroundColor: 'rgba(56, 189, 248, 0.15)',
            tension: 0.35,
            fill: false
          },
          {
            label: 'Requests / Min',
            data: trafficData,
            borderColor: '#22c55e',
            backgroundColor: 'rgba(34, 197, 94, 0.15)',
            tension: 0.35,
            fill: false
          },
          {
            label: 'Errors',
            data: errorData,
            borderColor: '#ef4444',
            backgroundColor: 'rgba(239, 68, 68, 0.15)',
            tension: 0.35,
            fill: false
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        }
      }
    });

    function updateMetrics(users, traffic, errors) {
      activeUsersEl.textContent = users;
      requestsPerMinEl.textContent = traffic;
      errorCountEl.textContent = errors;
    }

    function addDataPoint() {
      const users = randomBetween(80, 180);
      const traffic = randomBetween(1200, 2400);
      const errors = randomBetween(0, 12);

      const timeLabel = new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit'
      });

      labels.push(timeLabel);
      usersData.push(users);
      trafficData.push(traffic);
      errorData.push(errors);

      if (labels.length > MAX_POINTS) {
        labels.shift();
        usersData.shift();
        trafficData.shift();
        errorData.shift();
      }

      chart.update();
      updateMetrics(users, traffic, errors);
      pushEventRow(nowTime(), 'Auto update', `Users ${users}, Traffic ${traffic}, Errors ${errors}`);
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('eventName').value.trim();
      const type = document.getElementById('eventType').value;
      const value = Number(document.getElementById('eventValue').value);

      if (!name || Number.isNaN(value)) return;

      labels.push(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

      let users = usersData[usersData.length - 1] ?? 100;
      let traffic = trafficData[trafficData.length - 1] ?? 1500;
      let errors = errorData[errorData.length - 1] ?? 2;

      if (type === 'users') {
        users = value;
      } else if (type === 'traffic') {
        traffic = value;
      } else if (type === 'errors') {
        errors = value;
      }

      usersData.push(users);
      trafficData.push(traffic);
      errorData.push(errors);

      if (labels.length > MAX_POINTS) {
        labels.shift();
        usersData.shift();
        trafficData.shift();
        errorData.shift();
      }

      chart.update();
      updateMetrics(users, traffic, errors);
      pushEventRow(nowTime(), name, `${type}: ${value}`);
      eventForm.reset();
      document.getElementById('eventType').value = type;
    });

    resetBtn.addEventListener('click', () => {
      labels.length = 0;
      usersData.length = 0;
      trafficData.length = 0;
      errorData.length = 0;
      eventTable.innerHTML = `<tr><td colspan="3" class="small">Waiting for live data...</td></tr>`;
      activeUsersEl.textContent = '0';
      requestsPerMinEl.textContent = '0';
      errorCountEl.textContent = '0';
      chart.update();
    });

    // Initial fill
    for (let i = 0; i < 5; i++) {
      addDataPoint();
    }

    // Real-time simulation
    setInterval(addDataPoint, 1000);
  </script>
</body>
</html>
