<body>
  <div class="dashboard">
    <div class="header card">
      <div>
        <h1>Real-Time Analytics Dashboard</h1>
        <div class="subtitle">Interactive dashboard with live chart updates and form-driven data entry</div>
      </div>
      <div class="muted" id="clock"></div>
    </div>

    <section class="card">
      <div class="stats">
        <div class="stat">
          <div class="label">Total Records</div>
          <div class="value" id="totalRecords">0</div>
        </div>
        <div class="stat">
          <div class="label">Average Value</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Latest Value</div>
          <div class="value" id="latestValue">0</div>
        </div>
      </div>

      <h2 class="section-title">Live Data Visualization</h2>
      <div class="chart-wrap">
        <canvas id="liveChart"></canvas>
      </div>
    </section>

    <aside class="card">
      <h2 class="section-title">Add Data Point</h2>
      <form id="dataForm">
        <label>
          Label
          <input type="text" id="labelInput" placeholder="e.g., Sensor A" required />
        </label>

        <label>
          Value
          <input type="number" id="valueInput" placeholder="e.g., 42" required />
        </label>

        <label>
          Severity
          <select id="severityInput">
            <option value="low">Low</option>
            <option value="medium" selected>Medium</option>
            <option value="high">High</option>
          </select>
        </label>

        <button type="submit">Add Record</button>
      </form>

      <h2 class="section-title">Filter Records</h2>
      <div class="filters">
        <label>
          Search
          <input type="text" id="searchInput" placeholder="Filter by label..." />
        </label>

        <label>
          Severity
          <select id="severityFilter">
            <option value="all" selected>All</option>
            <option value="low">Low</option>
            <option value="medium">Medium</option>
            <option value="high">High</option>
          </select>
        </label>
      </div>

      <div class="data-list" id="dataList"></div>
    </aside>
  </div>

  <script>
    const ctx = document.getElementById("liveChart");
    const dataList = document.getElementById("dataList");
    const totalRecords = document.getElementById("totalRecords");
    const averageValue = document.getElementById("averageValue");
    const latestValue = document.getElementById("latestValue");
    const clock = document.getElementById("clock");

    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");
    const severityInput = document.getElementById("severityInput");
    const searchInput = document.getElementById("searchInput");
    const severityFilter = document.getElementById("severityFilter");
    const dataForm = document.getElementById("dataForm");

    let records = [
      { label: "Sensor A", value: 12, severity: "low", time: new Date() },
      { label: "Sensor B", value: 28, severity: "medium", time: new Date() },
      { label: "Sensor C", value: 65, severity: "high", time: new Date() }
    ];

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels: records.map(r => r.label),
        datasets: [{
          label: "Value",
          data: records.map(r => r.value),
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 5
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          y: {
            beginAtZero: true,
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          x: {
            grid: { color: "rgba(148, 163, 184, 0.08)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function severityClass(severity) {
      return severity === "high" ? "high" : severity === "medium" ? "medium" : "low";
    }

    function updateStats() {
      const total = records.length;
      const avg = total ? (records.reduce((sum, r) => sum + r.value, 0) / total) : 0;
      const latest = total ? records[records.length - 1].value : 0;

      totalRecords.textContent = total;
      averageValue.textContent = avg.toFixed(1);
      latestValue.textContent = latest;
    }

    function updateChart() {
      chart.data.labels = records.map(r => r.label);
      chart.data.datasets[0].data = records.map(r => r.value);
      chart.update();
    }

    function renderList() {
      const search = searchInput.value.trim().toLowerCase();
      const severity = severityFilter.value;

      const filtered = records.filter(r => {
        const matchesSearch = r.label.toLowerCase().includes(search);
        const matchesSeverity = severity === "all" || r.severity === severity;
        return matchesSearch && matchesSeverity;
      });

      dataList.innerHTML = filtered.length
        ? filtered.map(r => `
          <div class="row">
            <div>
              <div><strong>${r.label}</strong></div>
              <div class="muted">${r.time.toLocaleTimeString()}</div>
            </div>
            <div style="text-align:right">
              <div><strong>${r.value}</strong></div>
              <span class="badge ${severityClass(r.severity)}">${r.severity}</span>
            </div>
          </div>
        `).join("")
        : `<div class="muted">No matching records found.</div>`;
    }

    function refreshUI() {
      updateStats();
      updateChart();
      renderList();
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);
      const severity = severityInput.value;

      if (!label || Number.isNaN(value)) return;

      records.push({
        label,
        value,
        severity,
        time: new Date()
      });

      labelInput.value = "";
      valueInput.value = "";
      severityInput.value = "medium";

      refreshUI();
    });

    searchInput.addEventListener("input", renderList);
    severityFilter.addEventListener("change", renderList);

    function updateClock() {
      clock.textContent = new Date().toLocaleString();
    }

    updateClock();
    setInterval(updateClock, 1000);

    refreshUI();

    // Simulated real-time updates
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      const severities = ["low", "medium", "high"];
      const randomSeverity = severities[Math.floor(Math.random() * severities.length)];

      records.push({
        label: `Auto-${records.length + 1}`,
        value: randomValue,
        severity: randomSeverity,
        time: new Date()
      });

      // Keep list reasonably sized
      if (records.length > 25) {
        records.shift();
      }

      refreshUI();
    }, 5000);
  </script>
</body>
</html>
```

