import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

type MetricPoint = {
  time: string;
  value: number;
};

type FormState = {
  feedName: string;
  refreshRate: number;
  threshold: number;
};

export default function App() {
  const [data, setData] = useState<MetricPoint[]>([]);
  const [isRunning, setIsRunning] = useState(true);
  const [status, setStatus] = useState("Connected");
  const [form, setForm] = useState<FormState>({
    feedName: "Live Metrics",
    refreshRate: 1000,
    threshold: 70,
  });

  const intervalRef = useRef<number | null>(null);

  // Simulated real-time data feed
  useEffect(() => {
    if (!isRunning) return;

    intervalRef.current = window.setInterval(() => {
      const now = new Date();
      const nextValue = Math.round(40 + Math.random() * 60);

      setData((prev) => {
        const next = [...prev, { time: now.toLocaleTimeString(), value: nextValue }];
        return next.slice(-20); // keep last 20 points
      });

      setStatus(nextValue > form.threshold ? "Alert: threshold exceeded" : "Connected");
    }, form.refreshRate);

    return () => {
      if (intervalRef.current) window.clearInterval(intervalRef.current);
    };
  }, [isRunning, form.refreshRate, form.threshold]);

  const chartData = useMemo(
    () => ({
      labels: data.map((p) => p.time),
      datasets: [
        {
          label: form.feedName,
          data: data.map((p) => p.value),
          borderColor: "rgb(75, 192, 192)",
          backgroundColor: "rgba(75, 192, 192, 0.2)",
          fill: true,
          tension: 0.3,
        },
      ],
    }),
    [data, form.feedName]
  );

  const chartOptions = useMemo(
    () => ({
      responsive: true,
      animation: {
        duration: 300,
      },
      plugins: {
        legend: {
          display: true,
        },
        title: {
          display: true,
          text: "Real-Time Metric Stream",
        },
      },
      scales: {
        y: {
          suggestedMin: 0,
          suggestedMax: 100,
        },
      },
    }),
    []
  );

  function handleChange(
    e: React.ChangeEvent<HTMLInputElement>
  ) {
    const { name, value, type } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]:
        type === "number" ? Number(value) : value,
    }));
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setStatus("Settings updated");
  }

  return (
    <div style={styles.page}>
      <header style={styles.header}>
        <h1 style={styles.title}>Interactive Dashboard</h1>
        <div style={styles.status}>
          <strong>Status:</strong> {status}
        </div>
      </header>

      <main style={styles.grid}>
        <section style={styles.card}>
          <Line data={chartData} options={chartOptions} />
        </section>

        <section style={styles.card}>
          <h2>Controls</h2>
          <form onSubmit={handleSubmit} style={styles.form}>
            <label style={styles.label}>
              Feed name
              <input
                style={styles.input}
                type="text"
                name="feedName"
                value={form.feedName}
                onChange={handleChange}
              />
            </label>

            <label style={styles.label}>
              Refresh rate (ms)
              <input
                style={styles.input}
                type="number"
                name="refreshRate"
                value={form.refreshRate}
                onChange={handleChange}
                min={250}
                step={250}
              />
            </label>

            <label style={styles.label}>
              Threshold
              <input
                style={styles.input}
                type="number"
                name="threshold"
                value={form.threshold}
                onChange={handleChange}
                min={0}
                max={100}
              />
            </label>

            <div style={styles.buttonRow}>
              <button type="submit" style={styles.button}>
                Save settings
              </button>
              <button
                type="button"
                style={styles.buttonSecondary}
                onClick={() => setIsRunning((v) => !v)}
              >
                {isRunning ? "Pause feed" : "Resume feed"}
              </button>
            </div>
          </form>
        </section>

        <section style={styles.card}>
          <h2>Latest Data</h2>
          <ul style={styles.list}>
            {data.slice().reverse().map((p, idx) => (
              <li key={idx} style={styles.listItem}>
                <span>{p.time}</span>
                <strong>{p.value}</strong>
              </li>
            ))}
          </ul>
        </section>
      </main>
    </div>
  );
}

