import { useEffect, useMemo, useRef, useState } from 'react';
import DashboardChart from './components/DashboardChart';
import MetricCard from './components/MetricCard';
import DataForm, { FormState } from './components/DataForm';

type DataPoint = {
  timestamp: string;
  value: number;
};

type FeedSettings = {
  refreshMs: number;
  amplitude: number;
  baseline: number;
};

export default function App() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [settings, setSettings] = useState<FeedSettings>({
    refreshMs: 1500,
    amplitude: 20,
    baseline: 50,
  });

  const intervalRef = useRef<number | null>(null);

  const latestValue = data.length ? data[data.length - 1].value : 0;
  const averageValue = useMemo(() => {
    if (!data.length) return 0;
    return data.reduce((sum, d) => sum + d.value, 0) / data.length;
  }, [data]);

  const minValue = useMemo(() => {
    if (!data.length) return 0;
    return Math.min(...data.map((d) => d.value));
  }, [data]);

  const maxValue = useMemo(() => {
    if (!data.length) return 0;
    return Math.max(...data.map((d) => d.value));
  }, [data]);

  useEffect(() => {
    // seed initial data
    const now = new Date();
    const initial = Array.from({ length: 12 }, (_, i) => {
      const t = new Date(now.getTime() - (11 - i) * 1000);
      const v =
        settings.baseline +
        Math.sin(i / 2) * settings.amplitude +
        (Math.random() * 8 - 4);
      return {
        timestamp: t.toLocaleTimeString(),
        value: Math.round(v),
      };
    });
    setData(initial);
  }, []);

  useEffect(() => {
    if (intervalRef.current) {
      window.clearInterval(intervalRef.current);
    }

    intervalRef.current = window.setInterval(() => {
      setData((prev) => {
        const last = prev[prev.length - 1]?.value ?? settings.baseline;
        const next =
          last +
          (Math.random() * settings.amplitude - settings.amplitude / 2) * 0.35;

        const bounded = Math.max(
          0,
          Math.min(100, Math.round(next))
        );

        const updated = [
          ...prev.slice(-29),
          {
            timestamp: new Date().toLocaleTimeString(),
            value: bounded,
          },
        ];

        return updated;
      });
    }, settings.refreshMs);

    return () => {
      if (intervalRef.current) window.clearInterval(intervalRef.current);
    };
  }, [settings.refreshMs, settings.amplitude, settings.baseline]);

  function handleFormSubmit(form: FormState) {
    setSettings({
      refreshMs: Math.max(250, Number(form.refreshMs)),
      amplitude: Math.max(1, Number(form.amplitude)),
      baseline: Math.max(0, Math.min(100, Number(form.baseline))),
    });
  }

  function handleReset() {
    setSettings({
      refreshMs: 1500,
      amplitude: 20,
      baseline: 50,
    });
    setData([]);
  }

  return (
    <div className="app-shell">
      <header className="header">
        <div>
          <h1>Real-Time Dashboard</h1>
          <p>Interactive browser-based analytics with live updates and form controls.</p>
        </div>
        <button className="secondary-btn" onClick={handleReset}>
          Reset
        </button>
      </header>

      <main className="grid">
        <section className="panel chart-panel">
          <div className="panel-header">
            <h2>Live Signal</h2>
            <span className={`status ${latestValue > settings.baseline ? 'up' : 'down'}`}>
              {latestValue > settings.baseline ? 'Above baseline' : 'Below baseline'}
            </span>
          </div>

          <DashboardChart data={data} />
        </section>

        <aside className="side-column">
          <section className="panel metrics-panel">
            <h2>Metrics</h2>
            <div className="metrics-grid">
              <MetricCard label="Latest" value={latestValue} suffix="" />
              <MetricCard label="Average" value={Math.round(averageValue)} suffix="" />
              <MetricCard label="Min" value={minValue} suffix="" />
              <MetricCard label="Max" value={maxValue} suffix="" />
            </div>
          </section>

          <section className="panel form-panel">
            <h2>Feed Settings</h2>
            <DataForm onSubmit={handleFormSubmit} initialValues={settings} />
          </section>
        </aside>
      </main>
    </div>
  );
}
```

