import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend,
  Filler
);

type DataPoint = {
  timestamp: string;
  value: number;
};

export default function DashboardChart({ data }: { data: DataPoint[] }) {
  const chartData = {
    labels: data.map((d) => d.timestamp),
    datasets: [
      {
        label: 'Live Value',
        data: data.map((d) => d.value),
        borderColor: '#4f8cff',
        backgroundColor: 'rgba(79, 140, 255, 0.18)',
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: '#dbe3f0',
        },
      },
      tooltip: {
        enabled: true,
      },
    },
    scales: {
      x: {
        ticks: { color: '#9fb0c8' },
        grid: { color: 'rgba(255,255,255,0.06)' },
      },
      y: {
        beginAtZero: true,
        suggestedMax: 100,
        ticks: { color: '#9fb0c8' },
        grid: { color: 'rgba(255,255,255,0.06)' },
      },
    },
  } as const;

  return (
