```tsx
import { useState } from 'react';

export type FormState = {
  refreshMs: string;
  amplitude: string;
  baseline: string;
};

export default function DataForm({
  initialValues,
  onSubmit,
}: {
  initialValues: {
    refreshMs: number;
    amplitude: number;
    baseline: number;
  };
  onSubmit: (form: FormState) => void;
}) {
  const [form, setForm] = useState<FormState>({
    refreshMs: String(initialValues.refreshMs),
    amplitude: String(initialValues.amplitude),
    baseline: String(initialValues.baseline),
  });

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    onSubmit(form);
  }

  return (
    <form className="form" onSubmit={handleSubmit}>
      <label>
        Refresh Interval (ms)
        <input
          type="number"
          name="refreshMs"
          min="250"
          step="50"
          value={form.refreshMs}
          onChange={handleChange}
        />
      </label>

      <label>
        Amplitude
        <input
          type="number"
          name="amplitude"
          min="1"
          step="1"
          value={form.amplitude}
          onChange={handleChange}
        />
      </label>

      <label>
        Baseline
        <input
          type="number"
          name="baseline"
          min="0"
          max="100"
          step="1"
          value={form.baseline}
          onChange={handleChange}
        />
      </label>

      <button type="submit" className="primary-btn">
        Apply Settings
      </button>
    </form>
  );
}
