```tsx
import React, { useEffect, useMemo, useState } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import "./App.css";

type DataPoint = {
  time: string;
  value: number;
};

type FormState = {
  threshold: number;
  refreshRate: number;
  label: string;
};

export default function App() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [form, setForm] = useState<FormState>({
    threshold: 70,
    refreshRate: 1000,
    label: "Live Metric",
  });

  const [status, setStatus] = useState("Running");

  // Simulated real-time data feed
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date().toLocaleTimeString();
      const randomValue = Math.floor(Math.random() * 100);

      setData((prev) => {
        const next = [...prev, { time: now, value: randomValue }];
        return next.slice(-20); // keep last 20 points
      });
    }, form.refreshRate);

    return () => clearInterval(interval);
  }, [form.refreshRate]);

  const latestValue = data.length ? data[data.length - 1].value : 0;

  const alertState = useMemo(() => {
    if (latestValue >= form.threshold) return "High";
    if (latestValue >= form.threshold * 0.7) return "Moderate";
    return "Normal";
  }, [latestValue, form.threshold]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const { name, value } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: name === "label" ? value : Number(value),
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setStatus("Settings updated");
    setTimeout(() => setStatus("Running"), 1500);
  };

  return (
    <div className="dashboard">
      <header className="header">
        <h1>Interactive Dashboard</h1>
        <p>{status}</p>
      </header>

      <section className="cards">
        <div className="card">
          <h2>{form.label}</h2>
          <p className="metric">{latestValue}</p>
          <span className={`badge ${alertState.toLowerCase()}`}>
            {alertState}
          </span>
        </div>

        <div className="card">
          <h3>Threshold</h3>
          <p>{form.threshold}</p>
        </div>

        <div className="card">
          <h3>Refresh Rate</h3>
          <p>{form.refreshRate} ms</p>
        </div>
      </section>

      <section className="panel chart-panel">
        <h2>Real-time Visualization</h2>
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={data}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="time" hide />
            <YAxis />
            <Tooltip />
            <Line
              type="monotone"
              dataKey="value"
              stroke="#4f46e5"
              strokeWidth={2}
              dot={false}
            />
          </LineChart>
        </ResponsiveContainer>
      </section>

      <section className="panel form-panel">
        <h2>Controls</h2>
        <form onSubmit={handleSubmit} className="form">
          <label>
            Label
            <input
              type="text"
              name="label"
              value={form.label}
              onChange={handleChange}
            />
          </label>

          <label>
            Threshold
            <input
              type="number"
              name="threshold"
              min={0}
              max={100}
              value={form.threshold}
              onChange={handleChange}
            />
          </label>

          <label>
            Refresh Rate (ms)
            <input
              type="number"
              name="refreshRate"
              min={200}
              step={100}
              value={form.refreshRate}
              onChange={handleChange}
            />
          </label>

          <button type="submit">Apply Settings</button>
        </form>
      </section>
    </div>
  );
}
```

