## 3) `src/App.tsx`

```tsx
import React, { useEffect, useMemo, useState } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from "recharts";

type DataPoint = {
  time: string;
  value: number;
};

type AlertRule = {
  id: number;
  name: string;
  threshold: number;
  enabled: boolean;
};

export default function App() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [rules, setRules] = useState<AlertRule[]>([]);
  const [name, setName] = useState("");
  const [threshold, setThreshold] = useState<number>(50);
  const [enabled, setEnabled] = useState(true);
  const [currentValue, setCurrentValue] = useState(0);

  // Simulated real-time data feed
  useEffect(() => {
    const interval = setInterval(() => {
      const next = Math.floor(Math.random() * 100);
      const time = new Date().toLocaleTimeString();

      setCurrentValue(next);
      setData((prev) => {
        const updated = [...prev, { time, value: next }];
        return updated.slice(-20); // keep last 20 points
      });
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const activeRules = useMemo(
    () => rules.filter((rule) => rule.enabled),
    [rules]
  );

  const triggeredRules = useMemo(
    () => activeRules.filter((rule) => currentValue >= rule.threshold),
    [activeRules, currentValue]
  );

  const handleAddRule = (e: React.FormEvent) => {
    e.preventDefault();

    if (!name.trim()) return;

    const newRule: AlertRule = {
      id: Date.now(),
      name: name.trim(),
      threshold,
      enabled,
    };

    setRules((prev) => [newRule, ...prev]);
    setName("");
    setThreshold(50);
    setEnabled(true);
  };

  const toggleRule = (id: number) => {
    setRules((prev) =>
      prev.map((rule) =>
        rule.id === id ? { ...rule, enabled: !rule.enabled } : rule
      )
    );
  };

  const deleteRule = (id: number) => {
    setRules((prev) => prev.filter((rule) => rule.id !== id));
  };

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Real-Time Dashboard</h1>
          <p>Live data visualization and form handling</p>
        </div>
        <div className="status-card">
          <span className="status-label">Current Value</span>
          <strong className="status-value">{currentValue}</strong>
        </div>
      </header>

      <main className="grid">
        <section className="card chart-card">
          <div className="card-header">
            <h2>Live Data Stream</h2>
            <span className="live-indicator">● Live</span>
          </div>

          <div className="chart-wrapper">
            <ResponsiveContainer width="100%" height={320}>
              <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="time" tick={{ fontSize: 12 }} />
                <YAxis />
                <Tooltip />
                <Legend />
                <Line
                  type="monotone"
                  dataKey="value"
                  stroke="#4f46e5"
                  strokeWidth={3}
                  dot={false}
                  name="Metric"
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </section>

        <section className="card form-card">
          <h2>Add Alert Rule</h2>
          <form onSubmit={handleAddRule} className="form">
            <label>
              Rule Name
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. High CPU"
              />
            </label>

            <label>
              Threshold
              <input
                type="number"
                value={threshold}
                onChange={(e) => setThreshold(Number(e.target.value))}
                min={0}
                max={100}
              />
            </label>

            <label className="checkbox-row">
              <input
                type="checkbox"
                checked={enabled}
                onChange={(e) => setEnabled(e.target.checked)}
              />
              Enabled
            </label>

            <button type="submit">Add Rule</button>
          </form>
        </section>

        <section className="card">
          <h2>Alert Rules</h2>
          {rules.length === 0 ? (
            <p className="muted">No rules created yet.</p>
          ) : (
            <ul className="rule-list">
              {rules.map((rule) => (
                <li key={rule.id} className="rule-item">
                  <div>
                    <strong>{rule.name}</strong>
                    <div className="muted">Threshold: {rule.threshold}</div>
                    <div className={rule.enabled ? "enabled" : "disabled"}>
                      {rule.enabled ? "Enabled" : "Disabled"}
                    </div>
                  </div>
                  <div className="rule-actions">
                    <button onClick={() => toggleRule(rule.id)}>
                      {rule.enabled ? "Disable" : "Enable"}
                    </button>
                    <button onClick={() => deleteRule(rule.id)}>Delete</button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </section>

        <section className="card">
          <h2>Triggered Alerts</h2>
          {triggeredRules.length === 0 ? (
            <p className="muted">No active alerts at the moment.</p>
          ) : (
            <ul className="alert-list">
              {triggeredRules.map((rule) => (
                <li key={rule.id} className="alert-item">
                  <strong>{rule.name}</strong> triggered at value {currentValue}
                </li>
              ))}
            </ul>
          )}
        </section>
      </main>
    </div>
  );
}
```

