## 5) `src/components/Dashboard.tsx`

This component:
- simulates real-time incoming data
- stores data points in state
- includes a form to adjust filters/settings
- passes data to the chart

```tsx
import { useEffect, useMemo, useState } from "react";
import LiveChart from "./LiveChart";
import DataForm from "./DataForm";

type DataPoint = {
  time: string;
  value: number;
};

type Settings = {
  threshold: number;
  label: string;
};

export default function Dashboard() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [settings, setSettings] = useState<Settings>({
    threshold: 50,
    label: "Default Stream",
  });

  // Simulate real-time updates
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      const time = now.toLocaleTimeString();
      const value = Math.floor(Math.random() * 100);

      setData((prev) => {
        const next = [...prev, { time, value }];
        return next.slice(-20); // keep last 20 points
      });
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const average = useMemo(() => {
    if (data.length === 0) return 0;
    const sum = data.reduce((acc, item) => acc + item.value, 0);
    return Math.round(sum / data.length);
  }, [data]);

  const current = data[data.length - 1]?.value ?? 0;

  return (
    <div className="dashboard">
      <header className="dashboard__header">
        <h1>{settings.label}</h1>
        <p>Real-time dashboard with chart and form controls</p>
      </header>

      <section className="dashboard__stats">
        <div className="stat-card">
          <span className="stat-card__label">Current Value</span>
          <strong className="stat-card__value">{current}</strong>
        </div>
        <div className="stat-card">
          <span className="stat-card__label">Average Value</span>
          <strong className="stat-card__value">{average}</strong>
        </div>
        <div className="stat-card">
          <span className="stat-card__label">Threshold</span>
          <strong className="stat-card__value">{settings.threshold}</strong>
        </div>
      </section>

      <section className="dashboard__grid">
        <div className="dashboard__panel">
          <h2>Live Data</h2>
          <LiveChart data={data} threshold={settings.threshold} />
        </div>

        <div className="dashboard__panel">
          <h2>Settings</h2>
          <DataForm settings={settings} onChange={setSettings} />
        </div>
      </section>
    </div>
  );
}
```

