      <ResponsiveContainer>
        <LineChart data={data}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="time" />
          <YAxis domain={[0, 100]} />
          <Tooltip />
          <ReferenceLine
            y={threshold}
            stroke="#ff4d4f"
            strokeDasharray="4 4"
            label="Threshold"
          />
          <Line
            type="monotone"
            dataKey="value"
            stroke="#1677ff"
            strokeWidth={3}
            dot={false}
            isAnimationActive={true}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}
