import { useEffect, useMemo, useState } from "react";
import LiveChart from "./LiveChart";
import DataForm from "./DataForm";

type DataPoint = {
  timestamp: string;
  value: number;
};

type FormState = {
  dashboardName: string;
  threshold: number;
  refreshInterval: number;
};

const initialFormState: FormState = {
  dashboardName: "Real-Time Dashboard",
  threshold: 75,
  refreshInterval: 1000,
};

function getRandomValue() {
  return Math.floor(Math.random() * 100);
}

export default function Dashboard() {
  const [formState, setFormState] = useState<FormState>(initialFormState);
  const [data, setData] = useState<DataPoint[]>([]);
  const [running, setRunning] = useState(true);

  useEffect(() => {
    if (!running) return;

    const interval = setInterval(() => {
      const newPoint: DataPoint = {
        timestamp: new Date().toLocaleTimeString(),
        value: getRandomValue(),
      };

      setData((prev) => {
        const updated = [...prev, newPoint];
        return updated.slice(-20); // keep last 20 points
      });
    }, formState.refreshInterval);

    return () => clearInterval(interval);
  }, [running, formState.refreshInterval]);

  const latestValue = data.length > 0 ? data[data.length - 1].value : 0;

  const status = useMemo(() => {
    if (latestValue >= formState.threshold) return "High";
    if (latestValue >= formState.threshold * 0.6) return "Moderate";
    return "Normal";
  }, [latestValue, formState.threshold]);

  return (
    <div style={styles.page}>
      <header style={styles.header}>
        <h1>{formState.dashboardName}</h1>
        <button onClick={() => setRunning((r) => !r)} style={styles.button}>
          {running ? "Pause Updates" : "Resume Updates"}
        </button>
      </header>

      <section style={styles.grid}>
        <div style={styles.card}>
          <h2>Live Status</h2>
          <p>
            Latest Value: <strong>{latestValue}</strong>
          </p>
          <p>
            Threshold: <strong>{formState.threshold}</strong>
          </p>
          <p>
            Status: <strong>{status}</strong>
          </p>
        </div>

        <div style={styles.card}>
          <h2>Controls</h2>
          <DataForm formState={formState} setFormState={setFormState} />
        </div>

        <div style={{ ...styles.card, gridColumn: "1 / -1" }}>
          <h2>Real-Time Chart</h2>
          <LiveChart data={data} />
        </div>

        <div style={{ ...styles.card, gridColumn: "1 / -1" }}>
          <h2>Incoming Events</h2>
          <ul style={styles.list}>
            {[...data].reverse().map((point, idx) => (
              <li key={idx}>
                {point.timestamp} — <strong>{point.value}</strong>
              </li>
            ))}
          </ul>
        </div>
      </section>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  page: {
    fontFamily: "Arial, sans-serif",
    padding: "24px",
    background: "#f6f8fb",
    minHeight: "100vh",
    color: "#1f2937",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
