### `src/components/LiveChart.tsx`

```tsx
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend
);

type DataPoint = {
  timestamp: string;
  value: number;
};

type Props = {
  data: DataPoint[];
};

export default function LiveChart({ data }: Props) {
  const chartData = {
    labels: data.map((d) => d.timestamp),
    datasets: [
      {
        label: "Value",
        data: data.map((d) => d.value),
        borderColor: "#2563eb",
        backgroundColor: "rgba(37, 99, 235, 0.2)",
        tension: 0.3,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    animation: {
      duration: 300,
    },
    scales: {
      y: {
        beginAtZero: true,
        suggestedMax: 100,
      },
    },
  };

  return (
    <div style={{ height: "320px" }}>
      <Line data={chartData} options={options} />
    </div>
  );
}
```

