          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function renderTable(source = "auto") {
      tableBody.innerHTML = "";
      labels.slice(-10).reverse().forEach((label, i) => {
        const index = labels.length - 1 - i;
        const row = document.createElement("tr");
        row.innerHTML = `
          <td>${label}</td>
          <td>${values[index]}</td>
          <td>${source}</td>
        `;
        tableBody.appendChild(row);
      });
    }

    function updateChart() {
      chart.update();
      renderTable("manual/auto");
    }

    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const label = document.getElementById("labelInput").value.trim();
      const value = Number(document.getElementById("valueInput").value);

      if (!label || Number.isNaN(value)) {
        statusEl.textContent = "Please enter valid label and value.";
        return;
      }

      labels.push(label);
      values.push(value);

      chart.data.labels = labels;
      chart.data.datasets[0].data = values;
      chart.update();
      renderTable("manual");

      statusEl.textContent = `Added: ${label} = ${value}`;
      e.target.reset();
    });

    // Simulate real-time updates every 2 seconds
    setInterval(() => {
      const now = new Date().toLocaleTimeString();
      const randomValue = Math.floor(Math.random() * 30) + 5;

      labels.push(now);
      values.push(randomValue);

      // keep last 10 points
      if (labels.length > 10) {
        labels.shift();
        values.shift();
      }

      chart.data.labels = labels;
      chart.data.datasets[0].data = values;
      chart.update();

      renderTable("auto");
      statusEl.textContent = `Auto-updated at ${now}`;
    }, 2000);

    renderTable();
  </script>
</body>
</html>
```

