    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");
    const currentValueEl = document.getElementById("currentValue");
    const thresholdValueEl = document.getElementById("thresholdValue");
    const statusValueEl = document.getElementById("statusValue");
    const feedEl = document.getElementById("feed");
    const form = document.getElementById("dataForm");
    const nameInput = document.getElementById("name");
    const valueInput = document.getElementById("value");

    let threshold = 50;
    let label = "Metric";
    const data = Array.from({ length: 40 }, () => 40 + Math.random() * 20);

    function log(message) {
      const p = document.createElement("div");
      p.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      feedEl.prepend(p);
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 30;
      const w = canvas.width - padding * 2;
      const h = canvas.height - padding * 2;
      const max = Math.max(...data, threshold) + 10;
      const min = Math.min(...data, threshold) - 10;

      // threshold line
      const thresholdY = padding + h - ((threshold - min) / (max - min)) * h;
      ctx.strokeStyle = "#f97316";
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(padding, thresholdY);
      ctx.lineTo(padding + w, thresholdY);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = "#f97316";
      ctx.fillText(`Threshold: ${threshold}`, padding + 6, thresholdY - 6);

      // line chart
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 2;
      ctx.beginPath();
      data.forEach((value, i) => {
        const x = padding + (i / (data.length - 1)) * w;
        const y = padding + h - ((value - min) / (max - min)) * h;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // points
      data.forEach((value, i) => {
        const x = padding + (i / (data.length - 1)) * w;
        const y = padding + h - ((value - min) / (max - min)) * h;
        ctx.fillStyle = "#e2e8f0";
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      });

      // axis label
      ctx.fillStyle = "#cbd5e1";
      ctx.fillText(label, padding, 18);
    }

    function updateStats(value) {
      currentValueEl.textContent = value.toFixed(1);
      thresholdValueEl.textContent = threshold.toString();
      const status = value >= threshold ? "ALERT" : "OK";
      statusValueEl.textContent = status;
      statusValueEl.style.color = status === "ALERT" ? "#f97316" : "#22c55e";
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      label = nameInput.value.trim() || "Metric";
      threshold = Number(valueInput.value);
      log(`Form updated: label="${label}", threshold=${threshold}`);
      drawChart();
    });

    // Simulated real-time data stream
    setInterval(() => {
      const last = data[data.length - 1];
      const next = Math.max(0, last + (Math.random() - 0.5) * 12);

      data.push(next);
      if (data.length > 40) data.shift();

      updateStats(next);
      drawChart();
      log(`${label} value updated to ${next.toFixed(1)}`);
    }, 1000);

    // initial render
    valueInput.value = threshold;
    drawChart();
    updateStats(data[data.length - 1]);
    log("Dashboard started");
  </script>
</body>
