      const padding = 40;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      // Axes
      ctx.strokeStyle = "#cbd5e1";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, canvas.height - padding);
      ctx.lineTo(canvas.width - padding, canvas.height - padding);
      ctx.stroke();

      if (data.length < 2) return;

      const maxVal = 100;
      const stepX = chartWidth / (data.length - 1);

      // Line
      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((value, i) => {
        const x = padding + i * stepX;
        const y = padding + chartHeight - (value / maxVal) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#ef4444";
      data.forEach((value, i) => {
        const x = padding + i * stepX;
        const y = padding + chartHeight - (value / maxVal) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function updateStats() {
      latestValueEl.textContent = data[data.length - 1] ?? "--";
      pointCountEl.textContent = data.length;
      intervalValueEl.textContent = updateInterval;
    }

    function pushRandomPoint() {
      data.push(randomDataPoint());
      if (data.length > 20) data.shift();
      drawChart();
      updateStats();
    }

    function setIntervalTimer(ms) {
      if (timer) clearInterval(timer);
      timer = setInterval(pushRandomPoint, ms);
    }

    document.getElementById("intervalForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const ms = Number(intervalInput.value);
      if (!Number.isNaN(ms) && ms >= 100) {
        updateInterval = ms;
        setIntervalTimer(updateInterval);
        updateStats();
      }
    });

    document.getElementById("manualForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const value = Number(manualInput.value);
      if (!Number.isNaN(value)) {
        data.push(Math.max(0, Math.min(100, value)));
        if (data.length > 20) data.shift();
        manualInput.value = "";
        drawChart();
        updateStats();
      }
    });

    drawChart();
    updateStats();
    setIntervalTimer(updateInterval);
  </script>
</body>
</html>
```

