## `background.js`

This stores whether the extension is enabled and toggles rule enforcement.

```js
const DEFAULT_ENABLED = true;

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled } = await chrome.storage.sync.get({ enabled: DEFAULT_ENABLED });
  await setBlockingEnabled(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const { enabled } = await chrome.storage.sync.get({ enabled: DEFAULT_ENABLED });
  await setBlockingEnabled(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "setEnabled") {
    chrome.storage.sync.set({ enabled: message.enabled }, async () => {
      await setBlockingEnabled(message.enabled);
      sendResponse({ ok: true, enabled: message.enabled });
    });
    return true; // keep message channel open
  }

  if (message?.type === "getEnabled") {
    chrome.storage.sync.get({ enabled: DEFAULT_ENABLED }, (result) => {
      sendResponse({ ok: true, enabled: result.enabled });
    });
    return true;
  }
});
```

