## `content.js`

Removes known tracking script tags from pages after they load.

```js
const TRACKER_PATTERNS = [
  /google-analytics\.com/i,
  /googletagmanager\.com/i,
  /doubleclick\.net/i,
  /facebook\.net/i,
  /hotjar\.com/i
];

function isTrackerScript(node) {
  if (!node || node.tagName !== "SCRIPT") return false;

  const src = node.src || "";
  if (!src) return false;

  return TRACKER_PATTERNS.some((re) => re.test(src));
}

function removeTrackerScripts(root = document) {
  const scripts = root.querySelectorAll("script[src]");
  for (const script of scripts) {
    if (isTrackerScript(script)) {
      script.remove();
    }
  }
}

function observeMutations() {
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;

        if (isTrackerScript(node)) {
          node.remove();
          continue;
        }

        if (node.querySelectorAll) {
          removeTrackerScripts(node);
        }
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
}

function init() {
  removeTrackerScripts();
  observeMutations();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", init, { once: true });
} else {
  init();
}
