## `service-worker.js`

```js
const DEFAULT_BLOCKED_DOMAINS = [
  "googletagmanager.com",
  "google-analytics.com",
  "analytics.google.com",
  "doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "hotjar.com",
  "clarity.ms",
  "segment.com",
  "mixpanel.com",
  "amplitude.com"
];

const RULE_ID_START = 1;

async function loadBlockedDomains() {
  const saved = await chrome.storage.sync.get({ blockedDomains: DEFAULT_BLOCKED_DOMAINS });
  return Array.isArray(saved.blockedDomains) ? saved.blockedDomains : DEFAULT_BLOCKED_DOMAINS;
}

function buildRules(domains) {
  return domains.map((domain, index) => ({
    id: RULE_ID_START + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: domain,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "sub_frame",
        "image",
        "font",
        "stylesheet",
        "ping",
        "websocket"
      ]
    }
  }));
}

async function updateRules() {
  const domains = await loadBlockedDomains();
  const currentRuleIds = Array.from({ length: 5000 }, (_, i) => RULE_ID_START + i);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: currentRuleIds,
    addRules: buildRules(domains)
  });
}

chrome.runtime.onInstalled.addListener(updateRules);
chrome.runtime.onStartup.addListener(updateRules);

chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "sync" && changes.blockedDomains) {
    updateRules();
  }
});
```

