## `content-script.js`

This attempts to remove tracking script tags already present in the page and observes future additions.

```js
(() => {
  const TRACKER_PATTERNS = [
    /doubleclick\.net/i,
    /googletagmanager\.com/i,
    /google-analytics\.com/i,
    /googletagservices\.com/i,
    /facebook\.net/i,
    /analytics\.twitter\.com/i
  ];

  function isTrackingScript(node) {
    if (!node || node.tagName !== "SCRIPT") return false;

    const src = node.src || "";
    const text = node.textContent || "";

    return TRACKER_PATTERNS.some((re) => re.test(src) || re.test(text));
  }

  function removeTrackingScripts(root = document) {
    const scripts = root.querySelectorAll ? root.querySelectorAll("script") : [];
    for (const script of scripts) {
      if (isTrackingScript(script)) {
        script.remove();
      }
    }
  }

  // Initial cleanup
  removeTrackingScripts();

  // Watch for dynamically injected scripts
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const addedNode of mutation.addedNodes) {
        if (isTrackingScript(addedNode)) {
          addedNode.remove();
          continue;
        }

        if (addedNode.nodeType === Node.ELEMENT_NODE) {
          removeTrackingScripts(addedNode);
        }
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

