# 6) `content.js`

This runs at `document_start` and tries to stop tracking scripts from executing.

```js
(function () {
  const filters = window.PRIVACY_BLOCKER_FILTERS || {
    scriptSources: [],
    suspiciousAttributes: []
  };

  function isBlockedScript(script) {
    if (!script) return false;

    const src = script.src || "";
    return filters.scriptSources.some((re) => re.test(src));
  }

  function removeTrackingScripts() {
    const scripts = document.querySelectorAll("script");
    scripts.forEach((script) => {
      if (isBlockedScript(script)) {
        script.remove();
      }
    });
  }

  function removeTrackingIframes() {
    const iframes = document.querySelectorAll("iframe");
    iframes.forEach((iframe) => {
      const src = iframe.src || "";
      if (/doubleclick\.net|google\.com\/recaptcha|facebook\.com/i.test(src)) {
        iframe.remove();
      }
    });
  }

  function stripSuspiciousInlineHandlers() {
    document.querySelectorAll("*").forEach((el) => {
      for (const attr of filters.suspiciousAttributes) {
        if (el.hasAttribute(attr)) {
          el.removeAttribute(attr);
        }
      }
    });
  }

  function observeDom() {
    const observer = new MutationObserver(() => {
      removeTrackingScripts();
      removeTrackingIframes();
      stripSuspiciousInlineHandlers();
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true
    });
  }

  removeTrackingScripts();
  removeTrackingIframes();
  stripSuspiciousInlineHandlers();
  observeDom();
})();
```

