const DEFAULT_ENABLED = true;

chrome.runtime.onInstalled.addListener(async () => {
  const { privacyBlockerEnabled } = await chrome.storage.sync.get("privacyBlockerEnabled");

  if (typeof privacyBlockerEnabled === "undefined") {
    await chrome.storage.sync.set({ privacyBlockerEnabled: DEFAULT_ENABLED });
  }

  await updateRules();
});

chrome.storage.onChanged.addListener(() => {
  updateRules();
});

async function updateRules() {
  const { privacyBlockerEnabled } = await chrome.storage.sync.get("privacyBlockerEnabled");
  const enabled = privacyBlockerEnabled !== false;

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["dynamic_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["dynamic_rules"]
    });
  }
}
