## 2) Default blocklist rules

Chrome MV3 `declarativeNetRequest` works best with rule objects. Here’s a small starter set.

### `src/rules/default-blocklist.ts`

```ts
export const DEFAULT_BLOCKED_DOMAINS = [
  "googletagmanager.com",
  "google-analytics.com",
  "www.google-analytics.com",
  "analytics.google.com",
  "doubleclick.net",
  "connect.facebook.net",
  "facebook.com/tr"
];

export function buildDynamicRules(blockedDomains: string[], startingId = 1) {
  return blockedDomains.map((domain, index) => ({
    id: startingId + index,
    priority: 1,
    action: {
      type: "block" as const
    },
    condition: {
      urlFilter: domain,
      resourceTypes: ["script", "xmlhttprequest", "beacon", "image", "ping", "sub_frame"]
    }
  }));
}
```

