const CUSTOM_BLOCKLIST_KEY = "customBlocklist";
const ENABLED_KEY = "enabled";

export async function getEnabled(): Promise<boolean> {
  const result = await chrome.storage.sync.get(ENABLED_KEY);
  return result[ENABLED_KEY] ?? true;
}

export async function setEnabled(enabled: boolean): Promise<void> {
  await chrome.storage.sync.set({ [ENABLED_KEY]: enabled });
}

export async function getCustomBlocklist(): Promise<string[]> {
  const result = await chrome.storage.sync.get(CUSTOM_BLOCKLIST_KEY);
  return result[CUSTOM_BLOCKLIST_KEY] ?? [];
}

export async function setCustomBlocklist(domains: string[]): Promise<void> {
  await chrome.storage.sync.set({ [CUSTOM_BLOCKLIST_KEY]: domains });
}
