## 4) Background service worker

This loads the ruleset and updates dynamic rules when the custom list changes.

### `src/background.ts`

```ts
import { DEFAULT_BLOCKED_DOMAINS, buildDynamicRules } from "./rules/default-blocklist";
import { getEnabled, getCustomBlocklist } from "./shared/storage";

const BASE_RULE_START_ID = 1;

async function syncRules() {
  const enabled = await getEnabled();
  const customDomains = await getCustomBlocklist();

  const allDomains = [...new Set([...DEFAULT_BLOCKED_DOMAINS, ...customDomains])];

  const rules = enabled ? buildDynamicRules(allDomains, BASE_RULE_START_ID) : [];

  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existingRules.map((rule) => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: existingIds,
    addRules: rules
  });
}

chrome.runtime.onInstalled.addListener(() => {
  syncRules();
});

chrome.runtime.onStartup.addListener(() => {
  syncRules();
});

chrome.storage.onChanged.addListener((_changes, areaName) => {
  if (areaName === "sync") {
    syncRules();
  }
});

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message?.type === "SYNC_RULES") {
    syncRules().then(() => sendResponse({ ok: true }));
    return true;
  }
});
```

