### `src/options.ts`

```ts
import { getCustomBlocklist, setCustomBlocklist } from "./shared/storage";

const form = document.getElementById("addForm") as HTMLFormElement;
const input = document.getElementById("domainInput") as HTMLInputElement;
const list = document.getElementById("domainList") as HTMLUListElement;
const message = document.getElementById("message") as HTMLParagraphElement;

let domains: string[] = [];

function render() {
  list.innerHTML = "";

  for (const domain of domains) {
    const li = document.createElement("li");
    li.textContent = domain;

    const remove = document.createElement("button");
    remove.textContent = "Remove";
    remove.addEventListener("click", async () => {
      domains = domains.filter((d) => d !== domain);
      await setCustomBlocklist(domains);
      render();
      message.textContent = `Removed ${domain}`;
      await chrome.runtime.sendMessage({ type: "SYNC_RULES" });
    });

    li.appendChild(remove);
    list.appendChild(li);
  }
}

async function init() {
  domains = await getCustomBlocklist();
  render();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const domain = input.value.trim().toLowerCase();
  if (!domain) return;

  if (domains.includes(domain)) {
    message.textContent = "That domain is already in the list.";
    return;
  }

  domains.push(domain);
  await setCustomBlocklist(domains);
  input.value = "";
  render();
  message.textContent = `Added ${domain}`;
  await chrome.runtime.sendMessage({ type: "SYNC_RULES" });
});

init();
```

