## `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";

type StockCell = {
  symbol: string;
  sector: string;
  price: number;
  changePct: number;
  x: number;
  y: number;
};

type Viewport = {
  scale: number;
  offsetX: number;
  offsetY: number;
};

const SYMBOLS = [
  "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL", "META", "TSLA", "AMD",
  "NFLX", "INTC", "ORCL", "CRM", "ADBE", "QCOM", "AVGO", "BABA",
  "JPM", "BAC", "WFC", "C", "V", "MA", "PYPL", "SQ",
];

const SECTORS = [
  "Tech", "Finance", "Consumer", "Semis", "Cloud", "Internet"
];

function createInitialCells(): StockCell[] {
  return SYMBOLS.map((symbol, i) => ({
    symbol,
    sector: SECTORS[i % SECTORS.length],
    price: 100 + Math.random() * 900,
    changePct: (Math.random() - 0.5) * 8,
    x: i % 6,
    y: Math.floor(i / 6),
  }));
}

function clamp(v: number, min: number, max: number) {
  return Math.max(min, Math.min(max, v));
}

function colorForChange(changePct: number) {
  // Red for negative, green for positive, neutral around 0
  const maxAbs = 10;
  const t = clamp(changePct / maxAbs, -1, 1);

  if (t >= 0) {
    const g = Math.round(120 + 135 * t);
    const r = Math.round(40 + 40 * (1 - t));
    return `rgb(${r}, ${g}, 70)`;
  } else {
    const abs = Math.abs(t);
    const r = Math.round(180 + 60 * abs);
    const g = Math.round(60 + 50 * (1 - abs));
    return `rgb(${r}, ${g}, 60)`;
  }
}

function drawHeatmap(
  ctx: CanvasRenderingContext2D,
  cells: StockCell[],
  viewport: Viewport,
  width: number,
  height: number,
  hoveredSymbol: string | null
) {
  ctx.clearRect(0, 0, width, height);

  const cellW = 120;
  const cellH = 90;
  const gap = 10;

  // Background
  ctx.fillStyle = "#0b1020";
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.translate(viewport.offsetX, viewport.offsetY);
  ctx.scale(viewport.scale, viewport.scale);

  for (const cell of cells) {
    const x = cell.x * (cellW + gap);
    const y = cell.y * (cellH + gap);

    const isHovered = hoveredSymbol === cell.symbol;

    // Outer rounded rect
    const radius = 12;
    const color = colorForChange(cell.changePct);

    ctx.beginPath();
    roundRectPath(ctx, x, y, cellW, cellH, radius);
    ctx.fillStyle = color;
    ctx.fill();

    // Hover highlight
    if (isHovered) {
      ctx.lineWidth = 4 / viewport.scale;
      ctx.strokeStyle = "#ffffff";
      ctx.stroke();
    } else {
      ctx.lineWidth = 1 / viewport.scale;
      ctx.strokeStyle = "rgba(255,255,255,0.12)";
      ctx.stroke();
    }

    // Text
    ctx.fillStyle = "#ffffff";
    ctx.font = `bold ${16 / viewport.scale}px system-ui, sans-serif`;
    ctx.fillText(cell.symbol, x + 12, y + 24);

    ctx.font = `${13 / viewport.scale}px system-ui, sans-serif`;
    ctx.fillStyle = "rgba(255,255,255,0.92)";
    ctx.fillText(`$${cell.price.toFixed(2)}`, x + 12, y + 50);

    const changeText = `${cell.changePct >= 0 ? "+" : ""}${cell.changePct.toFixed(2)}%`;
    ctx.fillStyle = "rgba(255,255,255,0.9)";
    ctx.fillText(changeText, x + 12, y + 72);
  }

  ctx.restore();
}

function roundRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number
) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

export default function StockHeatmap() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const wrapperRef = useRef<HTMLDivElement | null>(null);

  const [cells, setCells] = useState<StockCell[]>(createInitialCells);
  const [viewport, setViewport] = useState<Viewport>({
    scale: 1,
    offsetX: 30,
    offsetY: 30,
  });
  const [hovered, setHovered] = useState<StockCell | null>(null);
  const [dragging, setDragging] = useState(false);

  const cellsBySymbol = useMemo(() => {
    const map = new Map<string, StockCell>();
    for (const c of cells) map.set(c.symbol, c);
    return map;
  }, [cells]);

  useEffect(() => {
    // Simulated real-time updates
    const interval = setInterval(() => {
      setCells((prev) =>
        prev.map((c) => {
          const drift = (Math.random() - 0.5) * 0.8;
          const updatedChange = clamp(c.changePct + drift, -15, 15);
          const updatedPrice = Math.max(1, c.price * (1 + drift / 500));
          return {
            ...c,
            price: updatedPrice,
            changePct: updatedChange,
          };
        })
      );
    }, 700);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const resize = () => {
      const parent = wrapperRef.current;
      if (!parent) return;

      const dpr = window.devicePixelRatio || 1;
      const rect = parent.getBoundingClientRect();

      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;

      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrapper = wrapperRef.current;
    if (!canvas || !wrapper) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const rect = wrapper.getBoundingClientRect();
    drawHeatmap(
      ctx,
      cells,
      viewport,
      rect.width,
      rect.height,
      hovered?.symbol ?? null
    );
  }, [cells, viewport, hovered]);

  const screenToWorld = (sx: number, sy: number) => {
    return {
      x: (sx - viewport.offsetX) / viewport.scale,
      y: (sy - viewport.offsetY) / viewport.scale,
    };
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
    const nextScale = clamp(viewport.scale * zoomFactor, 0.5, 3);

    const worldBefore = screenToWorld(mx, my);

    const nextOffsetX = mx - worldBefore.x * nextScale;
    const nextOffsetY = my - worldBefore.y * nextScale;

    setViewport({
      scale: nextScale,
      offsetX: nextOffsetX,
      offsetY: nextOffsetY,
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    if (dragging) {
      // handled in mouse drag logic
      return;
    }

    const p = screenToWorld(mx, my);
    const cellW = 120;
    const cellH = 90;
    const gap = 10;

    const found = cells.find((c) => {
      const x = c.x * (cellW + gap);
      const y = c.y * (cellH + gap);
      return p.x >= x && p.x <= x + cellW && p.y >= y && p.y <= y + cellH;
    });

    setHovered(found ?? null);
  };

  const dragState = useRef<{ x: number; y: number } | null>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    dragState.current = { x: e.clientX, y: e.clientY };
    setDragging(true);
  };

  const handleMouseUp = () => {
    dragState.current = null;
    setDragging(false);
  };

  const handleMouseDrag = (e: React.MouseEvent) => {
    if (!dragging || !dragState.current) return;

    const dx = e.clientX - dragState.current.x;
    const dy = e.clientY - dragState.current.y;

    dragState.current = { x: e.clientX, y: e.clientY };

    setViewport((v) => ({
      ...v,
      offsetX: v.offsetX + dx,
      offsetY: v.offsetY + dy,
    }));
  };

  const tooltip = hovered ? (
    <div
      style={{
        position: "absolute",
        left: 16,
        top: 16,
        background: "rgba(15, 20, 40, 0.95)",
        color: "white",
        border: "1px solid rgba(255,255,255,0.15)",
        borderRadius: 10,
        padding: "10px 12px",
        pointerEvents: "none",
        fontFamily: "system-ui, sans-serif",
        fontSize: 13,
        boxShadow: "0 8px 24px rgba(0,0,0,0.35)",
        minWidth: 160,
      }}
    >
      <div style={{ fontWeight: 700, fontSize: 15 }}>{hovered.symbol}</div>
      <div>Sector: {hovered.sector}</div>
      <div>Price: ${hovered.price.toFixed(2)}</div>
      <div
        style={{
          color: hovered.changePct >= 0 ? "#7CFC90" : "#ff7b7b",
          fontWeight: 600,
        }}
      >
        Change: {hovered.changePct >= 0 ? "+" : ""}
        {hovered.changePct.toFixed(2)}%
      </div>
    </div>
  ) : null;

  return (
    <div
      ref={wrapperRef}
      style={{
        position: "relative",
        width: "100%",
        height: "100vh",
        overflow: "hidden",
        background: "#0b1020",
        userSelect: "none",
        cursor: dragging ? "grabbing" : "grab",
      }}
      onWheel={handleWheel}
      onMouseMove={(e) => {
        handleMouseMove(e);
        handleMouseDrag(e);
      }}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => {
        setHovered(null);
        handleMouseUp();
      }}
    >
      <canvas ref={canvasRef} />

      <div
        style={{
          position: "absolute",
          right: 16,
          top: 16,
          color: "white",
          background: "rgba(15,20,40,0.8)",
          border: "1px solid rgba(255,255,255,0.12)",
          borderRadius: 10,
          padding: "10px 12px",
          fontFamily: "system-ui, sans-serif",
          fontSize: 13,
        }}
      >
        <div><strong>Stock Heatmap</strong></div>
        <div>Wheel: zoom</div>
        <div>Drag: pan</div>
        <div>Hover: details</div>
      </div>

      {tooltip}
    </div>
  );
}
```

