## `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { scaleLinear, scaleBand } from "d3-scale";
import { zoom as d3Zoom, zoomIdentity, ZoomTransform } from "d3-zoom";
import { select } from "d3-selection";

type Cell = {
  ticker: string;
  sector: string;
  price: number;
  changePct: number;
  volume: number;
};

type TooltipState = {
  visible: boolean;
  x: number;
  y: number;
  cell: Cell | null;
};

const TICKERS = [
  "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL",
  "META", "TSLA", "JPM", "V", "UNH",
  "XOM", "LLY", "AVGO", "MA", "COST",
  "AMD", "NFLX", "CRM", "ORCL", "INTC",
];

const SECTORS = [
  "Tech", "Finance", "Energy", "Healthcare", "Consumer",
];

function randomChoice<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function createInitialData(): Cell[] {
  return TICKERS.map((ticker) => ({
    ticker,
    sector: randomChoice(SECTORS),
    price: 50 + Math.random() * 500,
    changePct: (Math.random() - 0.5) * 8,
    volume: Math.floor(1_000_000 + Math.random() * 20_000_000),
  }));
}

function updateData(data: Cell[]): Cell[] {
  return data.map((c) => {
    const drift = (Math.random() - 0.5) * 1.5;
    const newChange = Math.max(-15, Math.min(15, c.changePct + drift));
    const newPrice = Math.max(1, c.price * (1 + drift / 100));
    return {
      ...c,
      price: newPrice,
      changePct: newChange,
      volume: Math.max(0, c.volume + Math.floor((Math.random() - 0.5) * 500_000)),
    };
  });
}

function colorForChange(changePct: number) {
  // Negative => red, Positive => green
  const t = Math.max(-10, Math.min(10, changePct)) / 10;
  // interpolate manually between red/gray/green
  if (t < 0) {
    const a = Math.abs(t);
    return `rgb(${220}, ${Math.round(220 - 120 * a)}, ${Math.round(220 - 120 * a)})`;
  } else {
    const a = t;
    return `rgb(${Math.round(220 - 120 * a)}, ${220}, ${Math.round(220 - 120 * a)})`;
  }
}

export default function StockHeatmap() {
  const [data, setData] = useState<Cell[]>(() => createInitialData());
  const [tooltip, setTooltip] = useState<TooltipState>({
    visible: false,
    x: 0,
    y: 0,
    cell: null,
  });

  const svgRef = useRef<SVGSVGElement | null>(null);
  const gRef = useRef<SVGGElement | null>(null);

  const [transform, setTransform] = useState<ZoomTransform>(zoomIdentity);

  // Simulated real-time updates
  useEffect(() => {
    const id = window.setInterval(() => {
      setData((prev) => updateData(prev));
    }, 1000);

    return () => window.clearInterval(id);
  }, []);

  // Zoom/pan behavior
  useEffect(() => {
    if (!svgRef.current) return;

    const svg = select(svgRef.current);

    const zoomBehavior = d3Zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 6])
      .on("zoom", (event) => {
        setTransform(event.transform);
      });

    svg.call(zoomBehavior as any);

    return () => {
      svg.on(".zoom", null);
    };
  }, []);

  const dimensions = { width: 1100, height: 650, padding: 24 };
  const cols = 5;
  const rows = Math.ceil(data.length / cols);

  const xScale = useMemo(() => {
    return scaleBand<string>()
      .domain(Array.from({ length: cols }, (_, i) => String(i)))
      .range([0, dimensions.width - dimensions.padding * 2])
      .padding(0.08);
  }, [cols, dimensions.width]);

  const yScale = useMemo(() => {
    return scaleBand<string>()
      .domain(Array.from({ length: rows }, (_, i) => String(i)))
      .range([0, dimensions.height - dimensions.padding * 2])
      .padding(0.08);
  }, [rows, dimensions.height]);

  const cells = data.map((cell, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    return {
      ...cell,
      x: xScale(String(col)) ?? 0,
      y: yScale(String(row)) ?? 0,
      w: xScale.bandwidth(),
      h: yScale.bandwidth(),
    };
  });

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#111" }}>
      <h2 style={{ marginBottom: 8 }}>Stock Price Heatmap</h2>
      <div style={{ marginBottom: 12, color: "#666" }}>
        Real-time updates • Zoom/pan with mouse/touch • Hover for details
      </div>

      <svg
        ref={svgRef}
        width={dimensions.width}
        height={dimensions.height}
        style={{
          border: "1px solid #ddd",
          background: "#fafafa",
          borderRadius: 12,
          touchAction: "none",
          display: "block",
        }}
      >
        <g
          ref={gRef}
          transform={`translate(${dimensions.padding},${dimensions.padding}) ${transform.toString()}`}
        >
          {cells.map((cell) => (
            <g
              key={cell.ticker}
              transform={`translate(${cell.x},${cell.y})`}
              onMouseEnter={(e) => {
                setTooltip({
                  visible: true,
                  x: e.clientX,
                  y: e.clientY,
                  cell,
                });
              }}
              onMouseMove={(e) => {
                setTooltip((prev) => ({
                  ...prev,
                  x: e.clientX,
                  y: e.clientY,
                }));
              }}
              onMouseLeave={() => {
                setTooltip((prev) => ({ ...prev, visible: false, cell: null }));
              }}
              style={{ cursor: "pointer" }}
            >
              <rect
                width={cell.w}
                height={cell.h}
                rx={10}
                ry={10}
                fill={colorForChange(cell.changePct)}
                stroke="#fff"
                strokeWidth={2}
              />
              <text
                x={cell.w / 2}
                y={cell.h / 2 - 8}
                textAnchor="middle"
                fontSize={16}
                fontWeight={700}
                fill="#111"
              >
                {cell.ticker}
              </text>
              <text
                x={cell.w / 2}
                y={cell.h / 2 + 14}
                textAnchor="middle"
                fontSize={13}
                fill="#111"
              >
                {cell.changePct >= 0 ? "+" : ""}
                {cell.changePct.toFixed(2)}%
              </text>
            </g>
          ))}
        </g>
      </svg>

      {tooltip.visible && tooltip.cell && (
        <div
          style={{
            position: "fixed",
            left: tooltip.x + 12,
            top: tooltip.y + 12,
            background: "rgba(20,20,20,0.95)",
            color: "white",
            padding: "10px 12px",
            borderRadius: 8,
            fontSize: 13,
            pointerEvents: "none",
            boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
            zIndex: 1000,
          }}
        >
          <div style={{ fontWeight: 700, marginBottom: 4 }}>{tooltip.cell.ticker}</div>
          <div>Sector: {tooltip.cell.sector}</div>
          <div>Price: ${tooltip.cell.price.toFixed(2)}</div>
          <div>
            Change:{" "}
            <span style={{ color: tooltip.cell.changePct >= 0 ? "#6ee787" : "#ff7b72" }}>
              {tooltip.cell.changePct >= 0 ? "+" : ""}
              {tooltip.cell.changePct.toFixed(2)}%
            </span>
          </div>
          <div>Volume: {tooltip.cell.volume.toLocaleString()}</div>
        </div>
      )}
    </div>
  );
}
