## 2) `main.ts`

```ts
import * as d3 from "d3";

type Stock = {
  symbol: string;
  sector: string;
  price: number;
  changePct: number;
  volume: number;
};

const svg = d3.select<SVGSVGElement, unknown>("#chart");
const tooltip = document.getElementById("tooltip") as HTMLDivElement;
const resetBtn = document.getElementById("resetZoom") as HTMLButtonElement;

const width = () => window.innerWidth;
const height = () => window.innerHeight;

const sectors = [
  "Technology",
  "Financials",
  "Healthcare",
  "Energy",
  "Consumer",
  "Industrials",
];

const symbols = [
  "AAPL", "MSFT", "NVDA", "GOOGL", "AMZN", "META", "TSLA", "AMD", "INTC",
  "JPM", "BAC", "WFC", "GS", "C", "MS", "V", "MA",
  "LLY", "JNJ", "PFE", "MRK", "UNH", "AMGN",
  "XOM", "CVX", "COP", "SLB",
  "WMT", "COST", "HD", "TGT", "KO", "PEP",
  "CAT", "BA", "GE", "MMM", "HON"
];

let stocks: Stock[] = symbols.map((symbol, i) => ({
  symbol,
  sector: sectors[i % sectors.length],
  price: 100 + Math.random() * 500,
  changePct: (Math.random() - 0.5) * 6,
  volume: Math.floor(1_000_000 + Math.random() * 20_000_000),
}));

const root = svg.append("g").attr("class", "root");
const gridLayer = root.append("g").attr("class", "grid-layer");
const heatLayer = root.append("g").attr("class", "heat-layer");
const labelLayer = root.append("g").attr("class", "label-layer");

const colorScale = d3.scaleLinear<string>()
  .domain([-6, 0, 6])
  .range(["#b91c1c", "#111827", "#047857"])
  .clamp(true);

const zoomBehavior = d3.zoom<SVGSVGElement, unknown>()
  .scaleExtent([0.6, 6])
  .on("zoom", (event) => {
    root.attr("transform", event.transform.toString());
  });

svg.call(zoomBehavior as any);

resetBtn.addEventListener("click", () => {
  svg.transition().duration(250).call(
    zoomBehavior.transform as any,
    d3.zoomIdentity
  );
});

function layoutStocks(data: Stock[]) {
  const n = data.length;
  const cols = Math.ceil(Math.sqrt(n));
  const rows = Math.ceil(n / cols);

  const pad = 8;
  const outerPad = 24;

  const w = width() - outerPad * 2;
  const h = height() - outerPad * 2;

  const cellW = Math.floor((w - (cols - 1) * pad) / cols);
  const cellH = Math.floor((h - (rows - 1) * pad) / rows);

  return data.map((d, i) => ({
    ...d,
    x: outerPad + (i % cols) * (cellW + pad),
    y: outerPad + Math.floor(i / cols) * (cellH + pad),
    w: cellW,
    h: cellH,
  }));
}

function render() {
  const data = layoutStocks(stocks);

  const cells = heatLayer.selectAll<SVGRectElement, any>("rect.cell")
    .data(data, (d: any) => d.symbol);

  cells.enter()
    .append("rect")
    .attr("class", "cell")
    .attr("x", (d) => d.x)
    .attr("y", (d) => d.y)
    .attr("width", (d) => d.w)
    .attr("height", (d) => d.h)
    .attr("fill", (d) => colorScale(d.changePct))
    .on("mousemove", (event, d) => {
      tooltip.style.opacity = "1";
      tooltip.style.left = `${event.clientX}px`;
      tooltip.style.top = `${event.clientY}px`;
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong><br/>
        Sector: ${d.sector}<br/>
        Price: $${d.price.toFixed(2)}<br/>
        Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%<br/>
        Volume: ${d.volume.toLocaleString()}
      `;
    })
    .on("mouseleave", () => {
      tooltip.style.opacity = "0";
    })
    .merge(cells as any)
    .transition()
    .duration(120)
    .attr("x", (d) => d.x)
    .attr("y", (d) => d.y)
    .attr("width", (d) => d.w)
    .attr("height", (d) => d.h)
    .attr("fill", (d) => colorScale(d.changePct));

  cells.exit().remove();

  const labels = labelLayer.selectAll<SVGGElement, any>("g.label-group")
    .data(data, (d: any) => d.symbol);

  const labelEnter = labels.enter()
    .append("g")
    .attr("class", "label-group");

  labelEnter.append("text")
    .attr("class", "label")
    .attr("text-anchor", "start")
    .attr("x", 10)
    .attr("y", 22)
    .text((d: any) => d.symbol);

  labelEnter.append("text")
    .attr("class", "subtext")
    .attr("text-anchor", "start")
    .attr("x", 10)
    .attr("y", 40)
    .text((d: any) => `$${d.price.toFixed(2)}  ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`);

  labelEnter.merge(labels as any)
    .transition()
    .duration(120)
    .attr("transform", (d: any) => `translate(${d.x},${d.y})`);

  labels.exit().remove();

  // Optional sector separators / grid visual
  const rowLines = gridLayer.selectAll<SVGLineElement, number>("line.row")
    .data(d3.range(Math.ceil(data.length / Math.ceil(Math.sqrt(data.length)))));

  rowLines.enter()
    .append("line")
    .attr("class", "grid-line row")
    .merge(rowLines as any)
    .attr("x1", 20)
    .attr("x2", width() - 20)
    .attr("y1", (d, i) => 20 + i * 10)
    .attr("y2", (d, i) => 20 + i * 10);

  rowLines.exit().remove();
}

function simulateTick() {
  stocks = stocks.map((s) => {
    const move = (Math.random() - 0.5) * 0.7;
    const nextChange = Math.max(-12, Math.min(12, s.changePct + move));
    const nextPrice = Math.max(1, s.price * (1 + move / 100));
    const nextVolume = Math.max(0, s.volume + Math.floor((Math.random() - 0.5) * 200_000));

    return {
      ...s,
      price: nextPrice,
      changePct: nextChange,
      volume: nextVolume,
    };
  });

  render();
}

window.addEventListener("resize", () => render());

render();
setInterval(simulateTick, 1000);
```

