```ts
import * as d3 from "https://cdn.jsdelivr.net/npm/d3@7/+esm";

type StockCell = {
  symbol: string;
  price: number;
  changePct: number;
  sector: string;
};

const sectors = [
  "Tech",
  "Finance",
  "Healthcare",
  "Energy",
  "Retail",
  "Industrial",
  "Utilities",
  "Telecom",
];

const symbols = [
  "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL", "META", "TSLA", "AMD",
  "JPM", "BAC", "GS", "C", "WFC", "V", "MA",
  "PFE", "UNH", "JNJ", "LLY", "MRK",
  "XOM", "CVX", "COP",
  "WMT", "TGT", "COST", "HD",
  "CAT", "BA", "GE",
  "NEE", "DUK", "SO",
  "T", "VZ", "TMUS"
];

let data: StockCell[] = symbols.map((symbol, i) => ({
  symbol,
  price: 50 + Math.random() * 450,
  changePct: (Math.random() - 0.5) * 10,
  sector: sectors[i % sectors.length],
}));

const chartWrap = document.getElementById("chartWrap") as HTMLDivElement;
const svg = d3.select<SVGSVGElement, unknown>("#chart");
const tooltip = document.getElementById("tooltip") as HTMLDivElement;
const statusEl = document.getElementById("status") as HTMLDivElement;

const margin = { top: 16, right: 16, bottom: 16, left: 16 };

let width = 0;
let height = 0;

const rootG = svg.append("g").attr("class", "root");
const cellsG = rootG.append("g").attr("class", "cells");
const labelsG = rootG.append("g").attr("class", "labels");

const colorScale = d3.scaleLinear<string>()
  .domain([-8, -2, 0, 2, 8])
  .range(["#7f1d1d", "#ef4444", "#f8fafc", "#22c55e", "#14532d"])
  .clamp(true);

const zoom = d3.zoom<SVGSVGElement, unknown>()
  .scaleExtent([0.8, 8])
  .on("zoom", (event) => {
    rootG.attr("transform", event.transform.toString());
  });

svg.call(zoom as any);

function render() {
  const wrapRect = chartWrap.getBoundingClientRect();
  width = wrapRect.width;
  height = wrapRect.height;

  svg.attr("viewBox", `0 0 ${width} ${height}`);

  const cols = Math.max(1, Math.floor(width / 130));
  const cellW = (width - margin.left - margin.right) / cols;
  const rows = Math.ceil(data.length / cols);
  const cellH = Math.max(72, (height - margin.top - margin.bottom) / Math.max(1, rows));

  const cellSize = Math.min(cellW, cellH);

  const positioned = data.map((d, i) => ({
    ...d,
    x: margin.left + (i % cols) * cellSize,
    y: margin.top + Math.floor(i / cols) * cellSize,
    w: cellSize - 4,
    h: cellSize - 4,
  }));

  const cells = cellsG.selectAll<SVGGElement, typeof positioned[number]>("g.cell")
    .data(positioned, d => d.symbol);

  const cellsEnter = cells.enter()
    .append("g")
    .attr("class", "cell")
    .style("cursor", "pointer")
    .on("mouseenter", (event, d) => showTooltip(event, d))
    .on("mousemove", (event, d) => showTooltip(event, d))
    .on("mouseleave", hideTooltip);

  cellsEnter.append("rect").attr("rx", 10).attr("ry", 10);
  cellsEnter.append("text")
    .attr("class", "symbol")
    .attr("fill", "#0f172a")
    .attr("font-weight", 700)
    .attr("font-size", 14);

  cellsEnter.append("text")
    .attr("class", "price")
    .attr("fill", "#0f172a")
    .attr("font-size", 12);

  cellsEnter.append("text")
    .attr("class", "change")
    .attr("fill", "#0f172a")
    .attr("font-size", 12);

  const merged = cellsEnter.merge(cells as any);

  merged.attr("transform", d => `translate(${d.x},${d.y})`);

  merged.select("rect")
    .transition()
    .duration(250)
    .attr("width", d => d.w)
    .attr("height", d => d.h)
    .attr("fill", d => colorScale(d.changePct));

  merged.select("text.symbol")
    .attr("x", 10)
    .attr("y", 22)
    .text(d => d.symbol);

  merged.select("text.price")
    .attr("x", 10)
    .attr("y", 42)
    .text(d => `$${d.price.toFixed(2)}`);

  merged.select("text.change")
    .attr("x", 10)
    .attr("y", 60)
    .text(d => `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`);

  cells.exit().remove();

  // Add a subtle sector label group in the background (optional)
  statusEl.textContent = `Live updates active • ${data.length} symbols • ${cols} cols`;
}

function showTooltip(event: MouseEvent, d: StockCell) {
  const [x, y] = d3.pointer(event, chartWrap);
  tooltip.style.opacity = "1";
  tooltip.style.left = `${x}px`;
  tooltip.style.top = `${y}px`;
  tooltip.innerHTML = `
    <div><strong>${d.symbol}</strong> (${d.sector})</div>
    <div>Price: $${d.price.toFixed(2)}</div>
    <div>Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%</div>
  `;
}

function hideTooltip() {
  tooltip.style.opacity = "0";
}

function updatePrices() {
  data = data.map((d) => {
    const drift = (Math.random() - 0.5) * 2.5;
    const newChange = Math.max(-10, Math.min(10, d.changePct + drift * 0.35));
    const newPrice = Math.max(1, d.price * (1 + drift / 100));
    return {
      ...d,
      price: newPrice,
      changePct: newChange,
    };
  });

  render();
}

// Resize observer for responsive layout
const ro = new ResizeObserver(() => render());
ro.observe(chartWrap);

// Initial render + real-time updates
render();
statusEl.textContent = "Connected • live simulated feed";

setInterval(updatePrices, 1000);

// Optional: double click to reset zoom
svg.on("dblclick", () => {
  svg.transition().duration(300).call(zoom.transform as any, d3.zoomIdentity);
});
```

