## 2) `src/App.tsx`

```tsx
import { useEffect, useMemo, useRef, useState } from "react";
import * as d3 from "d3";
import "./App.css";

type StockCell = {
  symbol: string;
  sector: string;
  price: number;
  prevPrice: number;
  changePct: number;
};

type TransformState = {
  x: number;
  y: number;
  k: number;
};

const sectors = [
  "Technology",
  "Finance",
  "Healthcare",
  "Energy",
  "Consumer",
  "Industrial",
];

const stockSymbols = [
  "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL", "META",
  "JPM", "BAC", "GS", "C", "WFC", "MS",
  "JNJ", "PFE", "MRK", "ABBV", "LLY", "UNH",
  "XOM", "CVX", "COP", "SLB", "EOG", "PSX",
  "KO", "PEP", "WMT", "TGT", "COST", "MCD",
  "CAT", "BA", "GE", "HON", "UPS", "DE",
];

function randomBetween(min: number, max: number) {
  return Math.random() * (max - min) + min;
}

function createInitialStocks(): StockCell[] {
  return stockSymbols.map((symbol, i) => {
    const base = randomBetween(20, 500);
    return {
      symbol,
      sector: sectors[i % sectors.length],
      price: base,
      prevPrice: base,
      changePct: 0,
    };
  });
}

function simulateTick(stocks: StockCell[]): StockCell[] {
  return stocks.map((s) => {
    const volatility = randomBetween(-0.03, 0.03);
    const prevPrice = s.price;
    const nextPrice = Math.max(1, prevPrice * (1 + volatility));
    const changePct = ((nextPrice - prevPrice) / prevPrice) * 100;

    return {
      ...s,
      prevPrice,
      price: nextPrice,
      changePct,
    };
  });
}

function colorForChange(changePct: number) {
  const scale = d3.scaleLinear<string>()
    .domain([-3, 0, 3])
    .range(["#d73027", "#f7f7f7", "#1a9850"])
    .clamp(true);

  return scale(changePct);
}

export default function App() {
  const [stocks, setStocks] = useState<StockCell[]>(createInitialStocks());
  const [transform, setTransform] = useState<TransformState>({ x: 0, y: 0, k: 1 });

  const svgRef = useRef<SVGSVGElement | null>(null);
  const zoomBehaviorRef = useRef<d3.ZoomBehavior<SVGSVGElement, unknown> | null>(null);

  // Group stocks by sector for layout
  const grouped = useMemo(() => {
    const map = new Map<string, StockCell[]>();
    for (const s of stocks) {
      if (!map.has(s.sector)) map.set(s.sector, []);
      map.get(s.sector)!.push(s);
    }
    return Array.from(map.entries());
  }, [stocks]);

  // Simulated real-time updates
  useEffect(() => {
    const interval = setInterval(() => {
      setStocks((prev) => simulateTick(prev));
    }, 1200);

    return () => clearInterval(interval);
  }, []);

  // D3 zoom setup
  useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 4])
      .on("zoom", (event) => {
        const { x, y, k } = event.transform;
        setTransform({ x, y, k });
      });

    zoomBehaviorRef.current = zoom;
    svg.call(zoom as any);

    return () => {
      svg.on(".zoom", null);
    };
  }, []);

  const cellWidth = 140;
  const cellHeight = 90;
  const gap = 10;
  const sectorHeaderHeight = 28;
  const leftPadding = 20;
  const topPadding = 20;

  let yCursor = topPadding;

  return (
    <div className="app">
      <header className="header">
        <h1>Stock Price Heatmap</h1>
        <p>Real-time updates with zoom/pan interaction</p>
      </header>

      <div className="toolbar">
        <button
          onClick={() => {
            if (!svgRef.current || !zoomBehaviorRef.current) return;
            d3.select(svgRef.current)
              .transition()
              .duration(300)
              .call(zoomBehaviorRef.current.transform as any, d3.zoomIdentity);
          }}
        >
          Reset View
        </button>
      </div>

      <div className="chartWrapper">
        <svg ref={svgRef} className="chart" viewBox="0 0 1200 800">
          <rect x="0" y="0" width="1200" height="800" fill="#0b1020" />

          <g transform={`translate(${transform.x},${transform.y}) scale(${transform.k})`}>
            {grouped.map(([sector, sectorStocks]) => {
              const rows = Math.ceil(sectorStocks.length / 3);
              const sectorWidth = 3 * cellWidth + 2 * gap;
              const sectorHeight = sectorHeaderHeight + rows * cellHeight + (rows - 1) * gap + 20;
              const sectorX = leftPadding;

              const currentY = yCursor;
              yCursor += sectorHeight + 16;

              return (
                <g key={sector} transform={`translate(${sectorX},${currentY})`}>
                  <rect
                    x="0"
                    y="0"
                    width={sectorWidth}
                    height={sectorHeight}
                    rx="14"
                    fill="#11182d"
                    stroke="#22304f"
                  />
                  <text
                    x="14"
                    y="20"
                    fill="#d9e2ff"
                    fontSize="14"
                    fontWeight="600"
                  >
                    {sector}
                  </text>

                  {sectorStocks.map((stock, idx) => {
                    const col = idx % 3;
                    const row = Math.floor(idx / 3);
                    const x = col * (cellWidth + gap);
                    const y = sectorHeaderHeight + row * (cellHeight + gap);

                    const bg = colorForChange(stock.changePct);

                    return (
                      <g key={stock.symbol} transform={`translate(${x},${y})`}>
                        <rect
                          width={cellWidth}
                          height={cellHeight}
                          rx="12"
                          fill={bg}
                          stroke="rgba(255,255,255,0.15)"
                        />
                        <text
                          x="14"
                          y="24"
                          fill="#102030"
                          fontSize="16"
                          fontWeight="700"
                        >
                          {stock.symbol}
                        </text>
                        <text
                          x="14"
                          y="47"
                          fill="#102030"
                          fontSize="12"
                        >
                          ${stock.price.toFixed(2)}
                        </text>
                        <text
                          x="14"
                          y="68"
                          fill="#102030"
                          fontSize="12"
                        >
                          {stock.changePct >= 0 ? "+" : ""}
                          {stock.changePct.toFixed(2)}%
                        </text>
                      </g>
                    );
                  })}
                </g>
              );
            })}
          </g>
        </svg>
      </div>

      <div className="legend">
        <span>Red = down</span>
        <span>Gray = flat</span>
        <span>Green = up</span>
      </div>
    </div>
  );
}
