### `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import * as d3 from "d3";

type StockPoint = {
  symbol: string;
  time: Date;
  price: number;
  changePct: number;
};

type StockHeatmapProps = {
  symbols?: string[];
  historyLength?: number;
};

const DEFAULT_SYMBOLS = [
  "AAPL",
  "MSFT",
  "NVDA",
  "AMZN",
  "GOOGL",
  "META",
  "TSLA",
  "AMD",
  "INTC",
  "NFLX",
];

const WIDTH = 1100;
const HEIGHT = 600;
const MARGIN = { top: 30, right: 20, bottom: 40, left: 90 };

export function StockHeatmap({
  symbols = DEFAULT_SYMBOLS,
  historyLength = 60,
}: StockHeatmapProps) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const [points, setPoints] = useState<StockPoint[]>([]);
  const [hovered, setHovered] = useState<StockPoint | null>(null);
  const [transform, setTransform] = useState<d3.ZoomTransform>(d3.zoomIdentity);

  // Seed initial data
  useEffect(() => {
    const now = new Date();
    const initial: StockPoint[] = [];

    for (const symbol of symbols) {
      let price = 100 + Math.random() * 100;
      for (let i = historyLength - 1; i >= 0; i--) {
        const time = new Date(now.getTime() - i * 60_000);
        price = Math.max(1, price + (Math.random() - 0.5) * 2);
        const prev = price - (Math.random() - 0.5) * 3;
        const changePct = ((price - prev) / prev) * 100;

        initial.push({ symbol, time, price, changePct });
      }
    }

    setPoints(initial);
  }, [symbols, historyLength]);

  // Mock real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setPoints((prev) => {
        const latestBySymbol = new Map<string, StockPoint>();
        for (const p of prev) latestBySymbol.set(p.symbol, p);

        const now = new Date();
        const next: StockPoint[] = [...prev];

        for (const symbol of symbols) {
          const last = latestBySymbol.get(symbol);
          const lastPrice = last?.price ?? 100 + Math.random() * 100;
          const newPrice = Math.max(1, lastPrice + (Math.random() - 0.5) * 3);
          const changePct = ((newPrice - lastPrice) / lastPrice) * 100;

          next.push({
            symbol,
            time: now,
            price: newPrice,
            changePct,
          });
        }

        // Keep only the latest historyLength points per symbol
        const grouped = d3.group(next, (d) => d.symbol);
        const trimmed: StockPoint[] = [];

        for (const [symbol, arr] of grouped) {
          trimmed.push(...arr.slice(-historyLength));
        }

        return trimmed;
      });
    }, 3000);

    return () => clearInterval(id);
  }, [symbols, historyLength]);

  const symbolsSorted = useMemo(() => [...symbols].sort(), [symbols]);

  const { xScale, yScale, colorScale, timeExtent, changeExtent } = useMemo(() => {
    const times = points.map((d) => d.time);
    const changes = points.map((d) => d.changePct);

    const timeExtent = d3.extent(times) as [Date, Date];
    const changeExtent = [
      Math.min(-5, d3.min(changes) ?? -5),
      Math.max(5, d3.max(changes) ?? 5),
    ] as [number, number];

    const xScale = d3
      .scaleTime()
      .domain(timeExtent)
      .range([MARGIN.left, WIDTH - MARGIN.right]);

    const yScale = d3
      .scaleBand<string>()
      .domain(symbolsSorted)
      .range([MARGIN.top, HEIGHT - MARGIN.bottom])
      .padding(0.12);

    const colorScale = d3
      .scaleSequential(d3.interpolateRdYlGn)
      .domain([changeExtent[0], changeExtent[1]]);

    return { xScale, yScale, colorScale, timeExtent, changeExtent };
  }, [points, symbolsSorted]);

  // Zoom/pan behavior
  useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);

    const zoomed = (event: d3.D3ZoomEvent<SVGSVGElement, unknown>) => {
      setTransform(event.transform);
    };

    const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([1, 12])
      .translateExtent([
        [MARGIN.left, MARGIN.top],
        [WIDTH - MARGIN.right, HEIGHT - MARGIN.bottom],
      ])
      .extent([
        [MARGIN.left, MARGIN.top],
        [WIDTH - MARGIN.right, HEIGHT - MARGIN.bottom],
      ])
      .on("zoom", zoomed);

    svg.call(zoom as any);

    return () => {
      svg.on(".zoom", null);
    };
  }, []);

  const xScaleZoomed = transform.rescaleX(xScale);

  return (
    <div style={{ fontFamily: "sans-serif", width: WIDTH }}>
      <div style={{ marginBottom: 8 }}>
        <strong>Stock Price Heatmap</strong>
        <span style={{ marginLeft: 12, color: "#666" }}>
          Real-time updates + zoom/pan
        </span>
      </div>

      {hovered && (
        <div
          style={{
            position: "absolute",
            pointerEvents: "none",
            background: "rgba(0,0,0,0.8)",
            color: "white",
            padding: "8px 10px",
            borderRadius: 6,
            fontSize: 12,
            transform: "translate(12px, 12px)",
          }}
        >
          <div><strong>{hovered.symbol}</strong></div>
          <div>Time: {hovered.time.toLocaleTimeString()}</div>
          <div>Price: ${hovered.price.toFixed(2)}</div>
          <div>Change: {hovered.changePct.toFixed(2)}%</div>
        </div>
      )}

      <svg ref={svgRef} width={WIDTH} height={HEIGHT} style={{ border: "1px solid #ddd", background: "#fff" }}>
        {/* Axes */}
        <g>
          {xScaleZoomed.ticks(8).map((tick) => (
            <g key={tick.toISOString()} transform={`translate(${xScaleZoomed(tick)},0)`}>
              <line
                y1={MARGIN.top}
                y2={HEIGHT - MARGIN.bottom}
                stroke="#eee"
              />
              <text
                y={HEIGHT - 10}
                textAnchor="middle"
                fontSize="11"
                fill="#666"
              >
                {d3.timeFormat("%H:%M")(tick)}
              </text>
            </g>
          ))}

          {symbolsSorted.map((symbol) => {
            const y = yScale(symbol);
            if (y == null) return null;
            return (
              <text
                key={symbol}
                x={MARGIN.left - 10}
                y={y + yScale.bandwidth() / 2}
                textAnchor="end"
                dominantBaseline="middle"
                fontSize="12"
                fill="#333"
              >
                {symbol}
              </text>
            );
          })}
        </g>

        {/* Heatmap cells */}
        <g>
          {points.map((d, idx) => {
            const y = yScale(d.symbol);
            if (y == null) return null;

            const x0 = xScaleZoomed(d.time);
            const nextTime =
              points
                .filter((p) => p.symbol === d.symbol && p.time > d.time)
                .sort((a, b) => a.time.getTime() - b.time.getTime())[0]?.time;

            const x1 = nextTime ? xScaleZoomed(nextTime) : x0 + 12;
            const cellWidth = Math.max(1, x1 - x0);

            return (
              <rect
                key={`${d.symbol}-${d.time.toISOString()}-${idx}`}
                x={x0}
                y={y}
                width={cellWidth}
                height={yScale.bandwidth()}
                fill={colorScale(d.changePct)}
                stroke="#fff"
                strokeWidth={1}
                onMouseEnter={() => setHovered(d)}
                onMouseLeave={() => setHovered(null)}
              >
                <title>
                  {d.symbol} | {d.time.toLocaleTimeString()} | ${d.price.toFixed(2)} | {d.changePct.toFixed(2)}%
                </title>
              </rect>
            );
          })}
        </g>

        {/* Overlay for pointer interactions */}
        <rect
          x={MARGIN.left}
          y={MARGIN.top}
          width={WIDTH - MARGIN.left - MARGIN.right}
          height={HEIGHT - MARGIN.top - MARGIN.bottom}
          fill="transparent"
          style={{ cursor: "grab" }}
        />
      </svg>

      <div style={{ marginTop: 10, fontSize: 12, color: "#666" }}>
        Time range:{" "}
        {timeExtent[0]?.toLocaleTimeString()} — {timeExtent[1]?.toLocaleTimeString()}
        {" | "}
        Color scale: {changeExtent[0].toFixed(2)}% to {changeExtent[1].toFixed(2)}%
      </div>
    </div>
  );
}
```

