  "AAPL", "MSFT", "GOOGL", "AMZN", "META", "NVDA", "TSLA", "NFLX",
  "JPM", "BAC", "GS", "WFC", "PFE", "JNJ", "UNH", "MRK",
  "XOM", "CVX", "COP", "SLB", "CAT", "BA", "GE", "HON"
];

const width = window.innerWidth;
const height = window.innerHeight;

const svg = d3
  .select("#app")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .style("display", "block")
  .style("background", "#0b1020");

const gRoot = svg.append("g").attr("class", "zoom-layer");
const heatmapLayer = gRoot.append("g").attr("class", "heatmap-layer");
const axisLayer = svg.append("g").attr("class", "ui-layer");
const tooltip = d3.select("#app").append("div").attr("class", "tooltip").style("opacity", "0");

const zoomBehavior = d3
  .zoom<SVGSVGElement, unknown>()
  .scaleExtent([0.5, 8])
  .translateExtent([
    [-500, -500],
    [width + 500, height + 500],
  ])
  .on("zoom", (event) => {
    gRoot.attr("transform", event.transform.toString());
    axisLayer.attr("transform", event.transform.toString());
  });

svg.call(zoomBehavior as any);

let data: StockCell[] = generateInitialData();

const colorScale = d3.scaleLinear<string>()
  .domain([-5, 0, 5])
  .range(["#ff4d4f", "#1f2937", "#22c55e"])
  .clamp(true);

const fontScale = d3.scaleLinear().domain([0, 1]).range([10, 18]);

function generateInitialData(): StockCell[] {
  const cols = 6;
  const rows = 4;
  const pad = 8;
  const cellW = 180;
  const cellH = 130;

  return symbols.map((symbol, i) => {
    const sector = sectors[i % sectors.length];
    const col = i % cols;
    const row = Math.floor(i / cols);

    return {
      symbol,
      sector,
      x: col * (cellW + pad),
      y: row * (cellH + pad),
      width: cellW,
      height: cellH,
      price: 50 + Math.random() * 450,
      changePct: (Math.random() - 0.5) * 10,
      volume: Math.floor(100000 + Math.random() * 5000000),
    };
  });
}

function updateHeatmap() {
  const cells = heatmapLayer.selectAll<SVGForeignObjectElement, StockCell>(".cell")
    .data(data, (d: any) => d.symbol);

  const cellsEnter = cells.enter()
    .append("g")
    .attr("class", "cell")
    .style("cursor", "pointer")
    .on("mouseover", (event, d) => {
      tooltip
        .style("opacity", "1")
        .html(`
          <div><strong>${d.symbol}</strong> <span>${d.sector}</span></div>
          <div>Price: $${d.price.toFixed(2)}</div>
          <div>Change: <span style="color:${d.changePct >= 0 ? '#4ade80' : '#f87171'}">
            ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
          </span></div>
          <div>Volume: ${d.volume.toLocaleString()}</div>
        `);
      d3.select(event.currentTarget).select("rect").attr("stroke", "#fff").attr("stroke-width", 2);
    })
    .on("mousemove", (event) => {
      tooltip
        .style("left", `${event.pageX + 15}px`)
        .style("top", `${event.pageY + 15}px`);
    })
    .on("mouseout", (event, d) => {
      tooltip.style("opacity", "0");
      d3.select(event.currentTarget).select("rect").attr("stroke", "rgba(255,255,255,0.12)").attr("stroke-width", 1);
    })
    .on("click", (_, d) => {
      console.log("Selected stock:", d.symbol, d);
    });

  cellsEnter.append("rect")
    .attr("rx", 12)
    .attr("ry", 12)
    .attr("fill", (d) => colorScale(d.changePct))
    .attr("stroke", "rgba(255,255,255,0.12)");

  cellsEnter.append("text")
    .attr("class", "symbol")
    .attr("fill", "white")
    .text((d) => d.symbol);

  cellsEnter.append("text")
    .attr("class", "price")
    .attr("fill", "rgba(255,255,255,0.85)")
    .text((d) => `$${d.price.toFixed(2)}`);

  cellsEnter.append("text")
    .attr("class", "change")
    .attr("fill", "rgba(255,255,255,0.75)")
    .text((d) => `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`);

  cells.merge(cellsEnter as any)
    .transition()
    .duration(350)
    .attr("transform", (d) => `translate(${d.x},${d.y})`);

  cells.merge(cellsEnter as any).select("rect")
    .transition()
    .duration(350)
    .attr("width", (d) => d.width)
    .attr("height", (d) => d.height)
    .attr("fill", (d) => colorScale(d.changePct));

  cells.merge(cellsEnter as any).select("text.symbol")
    .attr("x", 12)
    .attr("y", 24)
    .style("font-size", "18px")
    .style("font-weight", "700");

  cells.merge(cellsEnter as any).select("text.price")
    .attr("x", 12)
    .attr("y", 50)
    .style("font-size", "14px");

  cells.merge(cellsEnter as any).select("text.change")
    .attr("x", 12)
    .attr("y", 72)
    .style("font-size", "14px");

  cells.exit().remove();
}

function simulateRealtimeUpdates() {
  setInterval(() => {
    data = data.map((d) => {
      const drift = (Math.random() - 0.5) * 1.2;
      const newChange = Math.max(-15, Math.min(15, d.changePct + drift));
      const newPrice = Math.max(1, d.price * (1 + drift / 100));

      return {
        ...d,
        price: newPrice,
        changePct: newChange,
        volume: Math.max(1000, d.volume + Math.floor((Math.random() - 0.5) * 100000)),
      };
    });

    updateHeatmap();
  }, 1000);
}

function renderAxes() {
  axisLayer.selectAll("*").remove();

  axisLayer.append("text")
    .attr("x", 16)
    .attr("y", 28)
    .attr("fill", "#e5e7eb")
    .style("font-size", "22px")
    .style("font-weight", "700")
    .text("Stock Market Heatmap");

  axisLayer.append("text")
    .attr("x", 16)
    .attr("y", 52)
    .attr("fill", "#9ca3af")
    .style("font-size", "13px")
    .text("Zoom/pan with mouse or trackpad. Hover for details. Click a tile to select.");
}

renderAxes();
updateHeatmap();
simulateRealtimeUpdates();
```

