## 2) Main file: `src/App.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import "./App.css";

type StockCell = {
  symbol: string;
  sector: string;
  price: number;
  changePct: number;
  marketCap: number;
};

type ViewBox = {
  x: number;
  y: number;
  scale: number;
};

const sectors = [
  "Tech",
  "Finance",
  "Healthcare",
  "Energy",
  "Consumer",
  "Industrial",
  "Utilities",
  "Materials",
];

const symbols = [
  "AAPL", "MSFT", "NVDA", "GOOGL", "AMZN", "META", "TSLA", "JPM",
  "V", "MA", "UNH", "JNJ", "XOM", "CVX", "KO", "PEP",
  "BA", "CAT", "GS", "WMT", "HD", "PG", "MRK", "LLY",
];

function randomPrice() {
  return 20 + Math.random() * 480;
}

function randomChange() {
  return (Math.random() - 0.5) * 8; // -4% to +4%
}

function randomMarketCap() {
  return 10 + Math.random() * 2500;
}

function initialStocks(): StockCell[] {
  return symbols.map((symbol, i) => ({
    symbol,
    sector: sectors[i % sectors.length],
    price: Number(randomPrice().toFixed(2)),
    changePct: Number(randomChange().toFixed(2)),
    marketCap: Number(randomMarketCap().toFixed(0)),
  }));
}

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function colorForChange(changePct: number) {
  // Loss -> red, gain -> green, neutral -> gray
  const abs = Math.min(Math.abs(changePct), 4);
  const intensity = abs / 4;

  if (changePct > 0) {
    const green = Math.floor(120 + intensity * 135);
    return `rgb(20, ${green}, 70)`;
  }
  if (changePct < 0) {
    const red = Math.floor(120 + intensity * 135);
    return `rgb(${red}, 40, 50)`;
  }
  return "rgb(80, 80, 90)";
}

function textColorForBg(changePct: number) {
  return Math.abs(changePct) > 2 ? "#fff" : "#111";
}

export default function App() {
  const [stocks, setStocks] = useState<StockCell[]>(initialStocks);
  const [hovered, setHovered] = useState<StockCell | null>(null);
  const [view, setView] = useState<ViewBox>({ x: 0, y: 0, scale: 1 });

  const svgRef = useRef<SVGSVGElement | null>(null);
  const panState = useRef<{ dragging: boolean; startX: number; startY: number; originX: number; originY: number }>({
    dragging: false,
    startX: 0,
    startY: 0,
    originX: 0,
    originY: 0,
  });

  // Simulated real-time updates
  useEffect(() => {
    const id = window.setInterval(() => {
      setStocks((prev) =>
        prev.map((s) => {
          const delta = (Math.random() - 0.5) * 0.8; // small price change
          const newPrice = Math.max(1, s.price + delta);
          const pct = ((newPrice - s.price) / s.price) * 100;

          // Randomize a bit around previous change but keep it readable
          const newChange = clamp(s.changePct + (Math.random() - 0.5) * 0.4, -8, 8);

          return {
            ...s,
            price: Number(newPrice.toFixed(2)),
            changePct: Number(newChange.toFixed(2)),
          };
        })
      );
    }, 1000);

    return () => window.clearInterval(id);
  }, []);

  // Wheel zoom
  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;

    const onWheel = (e: WheelEvent) => {
      e.preventDefault();

      const zoomIntensity = 0.0015;
      const delta = -e.deltaY;
      const factor = Math.exp(delta * zoomIntensity);

      const rect = el.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      setView((v) => {
        const nextScale = clamp(v.scale * factor, 0.5, 4);

        const worldX = (mouseX - v.x) / v.scale;
        const worldY = (mouseY - v.y) / v.scale;

        const nextX = mouseX - worldX * nextScale;
        const nextY = mouseY - worldY * nextScale;

        return { x: nextX, y: nextY, scale: nextScale };
      });
    };

    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);

  const cellSize = 130;
  const gap = 10;
  const columns = 4;

  const cells = useMemo(() => {
    return stocks.map((s, index) => {
      const row = Math.floor(index / columns);
      const col = index % columns;
      return {
        ...s,
        x: col * (cellSize + gap),
        y: row * (cellSize + gap),
      };
    });
  }, [stocks]);

  const contentWidth = columns * cellSize + (columns - 1) * gap;
  const rows = Math.ceil(stocks.length / columns);
  const contentHeight = rows * cellSize + (rows - 1) * gap;

  const onPointerDown = (e: React.PointerEvent<SVGSVGElement>) => {
    if (e.button !== 0) return;

    panState.current.dragging = true;
    panState.current.startX = e.clientX;
    panState.current.startY = e.clientY;
    panState.current.originX = view.x;
    panState.current.originY = view.y;

    (e.currentTarget as SVGSVGElement).setPointerCapture(e.pointerId);
  };

  const onPointerMove = (e: React.PointerEvent<SVGSVGElement>) => {
    if (!panState.current.dragging) return;

    const dx = e.clientX - panState.current.startX;
    const dy = e.clientY - panState.current.startY;

    setView((v) => ({
      ...v,
      x: panState.current.originX + dx,
      y: panState.current.originY + dy,
    }));
  };

  const onPointerUp = (e: React.PointerEvent<SVGSVGElement>) => {
    panState.current.dragging = false;
    try {
      (e.currentTarget as SVGSVGElement).releasePointerCapture(e.pointerId);
    } catch {}
  };

  const resetView = () => setView({ x: 0, y: 0, scale: 1 });

  return (
    <div className="app">
      <div className="header">
        <div>
          <h1>Stock Heatmap</h1>
          <p>Real-time updates with zoom and pan</p>
        </div>

        <div className="controls">
          <button onClick={resetView}>Reset View</button>
        </div>
      </div>

      <div className="layout">
        <div className="chartPanel">
          <svg
            ref={svgRef}
            className="chart"
            viewBox={`0 0 ${contentWidth} ${contentHeight}`}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            style={{ cursor: panState.current.dragging ? "grabbing" : "grab" }}
          >
            <g transform={`translate(${view.x}, ${view.y}) scale(${view.scale})`}>
              {cells.map((cell) => (
                <g
                  key={cell.symbol}
                  transform={`translate(${cell.x}, ${cell.y})`}
                  onPointerEnter={() => setHovered(cell)}
                  onPointerLeave={() => setHovered(null)}
                >
                  <rect
                    width={cellSize}
                    height={cellSize}
                    rx={14}
                    fill={colorForChange(cell.changePct)}
                    stroke="rgba(255,255,255,0.14)"
                    strokeWidth={1}
                  />
                  <text x={14} y={28} fill={textColorForBg(cell.changePct)} className="symbol">
                    {cell.symbol}
                  </text>
                  <text x={14} y={52} fill={textColorForBg(cell.changePct)} className="price">
                    ${cell.price.toFixed(2)}
                  </text>
                  <text x={14} y={75} fill={textColorForBg(cell.changePct)} className="change">
                    {cell.changePct >= 0 ? "+" : ""}
                    {cell.changePct.toFixed(2)}%
                  </text>
                  <text x={14} y={100} fill={textColorForBg(cell.changePct)} className="sector">
                    {cell.sector}
                  </text>
                </g>
              ))}
            </g>
          </svg>
        </div>

        <div className="sidebar">
          <h2>Details</h2>
          {hovered ? (
            <div className="detailsCard">
              <div><strong>Symbol:</strong> {hovered.symbol}</div>
              <div><strong>Sector:</strong> {hovered.sector}</div>
              <div><strong>Price:</strong> ${hovered.price.toFixed(2)}</div>
              <div><strong>Change:</strong> {hovered.changePct >= 0 ? "+" : ""}{hovered.changePct.toFixed(2)}%</div>
              <div><strong>Market Cap:</strong> ${hovered.marketCap}B</div>
            </div>
          ) : (
            <div className="detailsCard muted">Hover over a stock</div>
          )}

          <div className="legend">
            <h3>Legend</h3>
            <div className="legendRow"><span className="swatch gain" /> Gainers</div>
            <div className="legendRow"><span className="swatch loss" /> Losers</div>
            <div className="legendRow"><span className="swatch neutral" /> Neutral</div>
          </div>
        </div>
      </div>
    </div>
  );
}
```

