## 6) `src/main.ts`
```ts
import * as d3 from "d3";
import "./styles.css";

type Stock = {
  symbol: string;
  sector: string;
  price: number;
  prevClose: number;
  changePct: number;
};

const sectors = [
  "Technology",
  "Finance",
  "Healthcare",
  "Energy",
  "Consumer",
  "Industrials",
  "Utilities",
  "Materials"
];

const symbols = [
  "AAPL", "MSFT", "NVDA", "GOOGL", "AMZN", "META", "TSLA", "AMD",
  "JPM", "BAC", "GS", "C", "WFC", "AXP",
  "LLY", "JNJ", "PFE", "UNH", "MRK",
  "XOM", "CVX", "COP", "SLB",
  "PG", "KO", "PEP", "MCD", "NKE",
  "CAT", "HON", "BA", "GE",
  "NEE", "DUK", "SO",
  "LIN", "APD", "ECL"
];

const container = document.createElement("div");
container.id = "app";
document.body.appendChild(container);

container.innerHTML = `
  <div class="header">
    <div>
      <div class="title">Interactive Stock Price Heatmap</div>
      <div class="subtle">Real-time updates • Zoom / pan with mouse wheel and drag</div>
    </div>
    <div class="subtle" id="status">Connecting…</div>
  </div>
  <div id="chart">
    <div class="tooltip" id="tooltip"></div>
  </div>
`;

const chartEl = document.getElementById("chart") as HTMLDivElement;
const tooltipEl = document.getElementById("tooltip") as HTMLDivElement;
const statusEl = document.getElementById("status") as HTMLDivElement;

const width = () => chartEl.clientWidth;
const height = () => chartEl.clientHeight;

const stocks: Stock[] = symbols.map((symbol, i) => {
  const prevClose = 50 + Math.random() * 450;
  const sector = sectors[i % sectors.length];
  const price = prevClose * (1 + (Math.random() - 0.5) * 0.05);
  return {
    symbol,
    sector,
    price,
    prevClose,
    changePct: ((price - prevClose) / prevClose) * 100
  };
});

const color = d3.scaleLinear<string>()
  .domain([-5, 0, 5])
  .range(["#d73027", "#2c344d", "#1a9850"])
  .interpolate(d3.interpolateRgb);

const svg = d3.select(chartEl)
  .append("svg")
  .attr("width", "100%")
  .attr("height", "100%");

const gRoot = svg.append("g");
const gCells = gRoot.append("g").attr("class", "cells");

const margin = { top: 16, right: 16, bottom: 16, left: 16 };

function layoutStocks(data: Stock[]) {
  const w = width() - margin.left - margin.right;
  const h = height() - margin.top - margin.bottom;

  const cols = Math.max(1, Math.floor(Math.sqrt(data.length * (w / h))));
  const rows = Math.ceil(data.length / cols);

  const cellW = w / cols;
  const cellH = h / rows;

  return data.map((d, i) => ({
    ...d,
    x: margin.left + (i % cols) * cellW,
    y: margin.top + Math.floor(i / cols) * cellH,
    cellW,
    cellH
  }));
}

let currentTransform = d3.zoomIdentity;

function render() {
  const laidOut = layoutStocks(stocks);

  const cells = gCells
    .selectAll<SVGGElement, any>("g.cell")
    .data(laidOut, (d: any) => d.symbol);

  const cellsEnter = cells.enter()
    .append("g")
    .attr("class", "cell")
    .style("cursor", "pointer");

  cellsEnter.append("rect")
    .attr("rx", 8)
    .attr("ry", 8);

  cellsEnter.append("text")
    .attr("class", "symbol")
    .attr("text-anchor", "middle")
    .attr("fill", "#fff")
    .style("font-weight", "700");

  cellsEnter.append("text")
    .attr("class", "price")
    .attr("text-anchor", "middle")
    .attr("fill", "rgba(255,255,255,0.85)");

  const merged = cellsEnter.merge(cells as any);

  merged.attr("transform", d => `translate(${d.x},${d.y})`);

  merged.select("rect")
    .attr("width", d => d.cellW - 8)
    .attr("height", d => d.cellH - 8)
    .attr("fill", d => color(d.changePct))
    .attr("stroke", "rgba(255,255,255,0.10)")
    .attr("stroke-width", 1);

  merged.select("text.symbol")
    .attr("x", d => (d.cellW - 8) / 2)
    .attr("y", d => Math.max(22, (d.cellH - 8) / 2 - 4))
    .style("font-size", d => `${Math.max(11, Math.min(20, d.cellW / 8))}px`)
    .text(d => d.symbol);

  merged.select("text.price")
    .attr("x", d => (d.cellW - 8) / 2)
    .attr("y", d => Math.max(40, (d.cellH - 8) / 2 + 14))
    .style("font-size", d => `${Math.max(10, Math.min(14, d.cellW / 12))}px`)
    .text(d => `${d.price.toFixed(2)} (${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%)`);

  merged
    .on("mousemove", (event, d) => {
      tooltipEl.style.opacity = "1";
      tooltipEl.style.left = `${event.offsetX}px`;
      tooltipEl.style.top = `${event.offsetY}px`;
      tooltipEl.innerHTML = `
        <div><strong>${d.symbol}</strong> · ${d.sector}</div>
        <div>Price: ${d.price.toFixed(2)}</div>
        <div>Prev Close: ${d.prevClose.toFixed(2)}</div>
        <div style="color:${d.changePct >= 0 ? "#2ecc71" : "#ff6b6b"}">
          Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
        </div>
      `;
    })
    .on("mouseleave", () => {
      tooltipEl.style.opacity = "0";
    });

  cells.exit().remove();

  gRoot.attr("transform", currentTransform.toString());
}

const zoom = d3.zoom<SVGSVGElement, unknown>()
  .scaleExtent([0.7, 8])
  .on("zoom", (event) => {
    currentTransform = event.transform;
    gRoot.attr("transform", currentTransform.toString());
  });

svg.call(zoom as any);

window.addEventListener("resize", () => render());

function randomTick() {
  for (const s of stocks) {
    const delta = (Math.random() - 0.5) * 2.2;
    s.price = Math.max(1, s.price + delta);
    s.changePct = ((s.price - s.prevClose) / s.prevClose) * 100;
  }
  render();
}

statusEl.textContent = "Live";

render();

// Simulated real-time updates
setInterval(() => {
  randomTick();
}, 1000);
```

