```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #0b1020;
      color: #e6e6e6;
      font-family: system-ui, sans-serif;
    }

    #toolbar {
      position: fixed;
      top: 10px;
      left: 10px;
      z-index: 10;
      background: rgba(20, 24, 40, 0.85);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 8px;
      padding: 8px 10px;
      backdrop-filter: blur(6px);
      font-size: 14px;
      line-height: 1.4;
    }

    canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .muted {
      color: #9aa4c7;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Stock Heatmap</strong></div>
    <div class="muted">Wheel: zoom • Drag: pan</div>
    <div id="status" class="muted">Loading...</div>
  </div>

  <canvas id="heatmap"></canvas>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");

    // ----- Data model -----
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","ADBE","QCOM","IBM","CSCO",
      "BA","DIS","JPM","V","PYPL","UBER","SHOP","SNAP"
    ];

    // Simple grid layout
    const cols = 6;
    const cellW = 160;
    const cellH = 100;
    const gap = 10;

    // Create positions and initial prices
    const stocks = symbols.map((symbol, i) => ({
      symbol,
      price: 100 + Math.random() * 250,
      change: 0,
      x: (i % cols) * (cellW + gap),
      y: Math.floor(i / cols) * (cellH + gap),
    }));

    // ----- View transform for pan/zoom -----
    let scale = 1;
    let panX = 20;
    let panY = 70;

    // ----- Interaction state -----
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(window.innerWidth * dpr);
      canvas.height = Math.floor(window.innerHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener("resize", resize);

    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX += e.clientX - lastX;
      panY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      // Zoom around cursor
      const beforeX = (mouseX - panX) / scale;
      const beforeY = (mouseY - panY) / scale;

      scale *= zoomFactor;
      scale = Math.max(0.5, Math.min(scale, 3));

      panX = mouseX - beforeX * scale;
      panY = mouseY - beforeY * scale;

      draw();
    }, { passive: false });

    // ----- Real-time updates (simulated) -----
    function tickPrices() {
      for (const s of stocks) {
        const prev = s.price;
        const delta = (Math.random() - 0.5) * 4; // small random movement
        s.price = Math.max(1, s.price + delta);
        s.change = ((s.price - prev) / prev) * 100;
      }
      statusEl.textContent = `Updated: ${new Date().toLocaleTimeString()}`;
      draw();
    }

    setInterval(tickPrices, 1000);

    // ----- Rendering -----
    function colorForChange(change) {
      // Red for negative, green for positive, neutral near 0
      const intensity = Math.min(1, Math.abs(change) / 3);
      const base = 40;
      if (change >= 0) {
        const g = Math.floor(base + intensity * 180);
        return `rgb(${base}, ${g}, ${base})`;
      } else {
        const r = Math.floor(base + intensity * 180);
        return `rgb(${r}, ${base}, ${base})`;
      }
    }

    function drawGridBackground() {
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, window.innerWidth, window.innerHeight);
    }

    function draw() {
      drawGridBackground();

      ctx.save();
      ctx.translate(panX, panY);
      ctx.scale(scale, scale);

      for (const s of stocks) {
        const x = s.x;
        const y = s.y;

        // Cell
        ctx.fillStyle = colorForChange(s.change);
        roundRect(ctx, x, y, cellW, cellH, 12);
        ctx.fill();

        // Border
        ctx.strokeStyle = "rgba(255,255,255,0.12)";
        ctx.lineWidth = 1;
        ctx.stroke();

        // Symbol
        ctx.fillStyle = "#fff";
        ctx.font = "bold 18px system-ui, sans-serif";
        ctx.fillText(s.symbol, x + 14, y + 28);

        // Price
        ctx.font = "15px system-ui, sans-serif";
        ctx.fillStyle = "rgba(255,255,255,0.92)";
        ctx.fillText(`$${s.price.toFixed(2)}`, x + 14, y + 54);

        // Change
        const sign = s.change >= 0 ? "+" : "";
        ctx.fillStyle = "rgba(255,255,255,0.82)";
        ctx.fillText(`${sign}${s.change.toFixed(2)}%`, x + 14, y + 78);
      }

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    // Initial render
    resize();
    tickPrices();
  </script>
</body>
</html>
