  </style>
</head>
<body>
  <div id="toolbar">
    <button id="resetBtn">Reset View</button>
    <div id="info">Wheel = zoom | Drag = pan | Real-time updates running</div>
  </div>
  <canvas id="c"></canvas>

  <script>
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');
    const resetBtn = document.getElementById('resetBtn');

    const dpr = Math.max(1, window.devicePixelRatio || 1);
    let w = 0, h = 0;

    // Demo data: grid of "stocks"
    const rows = 20;
    const cols = 30;
    const data = Array.from({ length: rows }, (_, r) =>
      Array.from({ length: cols }, (_, c) => ({
        symbol: `S${r}-${c}`,
        value: (Math.random() - 0.5) * 2 // -1..1
      }))
    );

    // View transform
    let scale = 1;
    let offsetX = 40;
    let offsetY = 80;

    const cellW = 90;
    const cellH = 48;
    const gap = 6;

    // Interaction state
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      w = window.innerWidth;
      h = window.innerHeight;
      canvas.width = Math.floor(w * dpr);
      canvas.height = Math.floor(h * dpr);
      canvas.style.width = w + 'px';
      canvas.style.height = h + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // v in roughly [-1,1]
      const x = clamp((v + 1) / 2, 0, 1);
      // red -> yellow -> green
      const r = x < 0.5 ? 255 : Math.round(255 * (1 - (x - 0.5) * 2));
      const g = x < 0.5 ? Math.round(255 * (x * 2)) : 255;
      const b = 70;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function drawGrid() {
      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      // Draw cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = c * (cellW + gap);
          const y = r * (cellH + gap);
          const cell = data[r][c];

          ctx.fillStyle = colorForValue(cell.value);
          roundRect(ctx, x, y, cellW, cellH, 10);
          ctx.fill();

          ctx.strokeStyle = 'rgba(255,255,255,0.12)';
          ctx.stroke();

          // Text
          ctx.fillStyle = '#111';
          ctx.font = '12px system-ui, sans-serif';
          ctx.fillText(cell.symbol, x + 10, y + 18);

          ctx.font = 'bold 14px system-ui, sans-serif';
          ctx.fillText((cell.value * 100).toFixed(1) + '%', x + 10, y + 38);
        }
      }

      ctx.restore();

      // HUD
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.font = '13px system-ui, sans-serif';
      ctx.fillText(`scale: ${scale.toFixed(2)}`, 16, h - 18);
    }

    function roundRect(ctx, x, y, width, height, radius) {
      const r = Math.min(radius, width / 2, height / 2);
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + width, y, x + width, y + height, r);
      ctx.arcTo(x + width, y + height, x, y + height, r);
      ctx.arcTo(x, y + height, x, y, r);
      ctx.arcTo(x, y, x + width, y, r);
      ctx.closePath();
    }

    function draw() {
      drawGrid();
    }

    // Real-time updates: randomly adjust values every 500ms
    setInterval(() => {
      for (let i = 0; i < 18; i++) {
        const r = Math.floor(Math.random() * rows);
        const c = Math.floor(Math.random() * cols);
        const cell = data[r][c];
        cell.value = clamp(cell.value + (Math.random() - 0.5) * 0.25, -1, 1);
      }
      draw();
    }, 500);

    // Zoom around mouse
    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const zoomFactor = Math.exp(-e.deltaY * 0.001);
      const newScale = clamp(scale * zoomFactor, 0.4, 3);

      // Keep point under cursor stable
      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      scale = newScale;
      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      draw();
    }, { passive: false });

    // Pan
    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      canvas.style.cursor = 'grabbing';
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      offsetX += e.clientX - lastX;
      offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      canvas.style.cursor = 'default';
    });

    // Reset view
    resetBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 40;
      offsetY = 80;
      draw();
    });

    window.addEventListener('resize', resize);

    resize();
  </script>
</body>
</html>
```

