import React, { useEffect, useMemo, useRef, useState } from "react";

type Cell = {
  symbol: string;
  value: number; // price change % e.g. -5 to +5
};

const ROWS = 10;
const COLS = 10;
const CELL_SIZE = 60;

const symbols = Array.from({ length: ROWS * COLS }, (_, i) => `STK${i + 1}`);

function randomDelta() {
  return (Math.random() - 0.5) * 0.8;
}

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function colorForValue(v: number) {
  // Red for negative, green for positive
  const t = clamp((v + 5) / 10, 0, 1);
  const r = Math.round(255 * (1 - t));
  const g = Math.round(255 * t);
  return `rgb(${r},${g},90)`;
}

export default function App() {
  const [cells, setCells] = useState<Cell[]>(
    symbols.map((s) => ({ symbol: s, value: (Math.random() - 0.5) * 10 }))
  );

  // View transform
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const dragging = useRef(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const offsetStart = useRef({ x: 0, y: 0 });

  // Real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setCells((prev) =>
        prev.map((c) => ({
          ...c,
          value: clamp(c.value + randomDelta(), -5, 5),
        }))
      );
    }, 1000);
    return () => clearInterval(id);
  }, []);

  const width = COLS * CELL_SIZE;
  const height = ROWS * CELL_SIZE;

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const delta = -e.deltaY * 0.001;
    setScale((s) => clamp(s + delta, 0.5, 3));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    dragging.current = true;
    dragStart.current = { x: e.clientX, y: e.clientY };
    offsetStart.current = { ...offset };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!dragging.current) return;
    const dx = e.clientX - dragStart.current.x;
    const dy = e.clientY - dragStart.current.y;
    setOffset({
      x: offsetStart.current.x + dx,
      y: offsetStart.current.y + dy,
    });
  };

  const handleMouseUp = () => {
    dragging.current = false;
  };

  return (
    <div
      style={{
        width: "100vw",
        height: "100vh",
        margin: 0,
        overflow: "hidden",
        background: "#111",
        color: "#fff",
        fontFamily: "system-ui, sans-serif",
      }}
      onWheel={handleWheel}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <div style={{ padding: 12 }}>
        <h3 style={{ margin: 0 }}>Stock Heatmap</h3>
        <p style={{ margin: "4px 0 0", color: "#bbb" }}>
          Drag to pan, scroll to zoom. Updates every second.
        </p>
      </div>

      <svg
        width="100%"
        height="calc(100% - 60px)"
        viewBox={`0 0 ${window.innerWidth} ${window.innerHeight - 60}`}
        onMouseDown={handleMouseDown}
        style={{ cursor: dragging.current ? "grabbing" : "grab" }}
      >
        <g transform={`translate(${offset.x},${offset.y}) scale(${scale})`}>
          {cells.map((cell, idx) => {
            const row = Math.floor(idx / COLS);
            const col = idx % COLS;
            return (
              <g key={cell.symbol} transform={`translate(${col * CELL_SIZE},${row * CELL_SIZE})`}>
                <rect
                  width={CELL_SIZE - 4}
                  height={CELL_SIZE - 4}
                  rx={8}
                  ry={8}
                  fill={colorForValue(cell.value)}
                  stroke="#222"
                />
                <text
                  x={CELL_SIZE / 2 - 2}
                  y={CELL_SIZE / 2 - 6}
                  textAnchor="middle"
                  fill="white"
                  fontSize="12"
                  fontWeight="600"
                >
                  {cell.symbol}
                </text>
                <text
                  x={CELL_SIZE / 2 - 2}
                  y={CELL_SIZE / 2 + 10}
                  textAnchor="middle"
                  fill="white"
                  fontSize="11"
                >
                  {cell.value.toFixed(1)}%
                </text>
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
}
```

