Below is a minimal working client-side example using **HTML + JavaScript + Canvas**. It simulates real-time stock price updates, renders a heatmap, and supports **mouse wheel zoom** and **drag pan**.

Save this as `index.html` and open it in a browser.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #111;
      color: #eee;
      font-family: sans-serif;
    }
    #toolbar {
      position: fixed;
      top: 12px;
      left: 12px;
      z-index: 10;
      background: rgba(0,0,0,0.5);
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 14px;
    }
    canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }
    canvas:active {
      cursor: grabbing;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    Wheel: zoom | Drag: pan
  </div>
  <canvas id="chart"></canvas>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const stocks = Array.from({ length: 80 }, (_, i) => ({
      symbol: `STK${String(i + 1).padStart(2, "0")}`,
      price: 50 + Math.random() * 50,
      change: 0
    }));

    let world = {
      x: 0,
      y: 0,
      scale: 1
    };

    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let worldStart = { x: 0, y: 0 };

    function resize() {
      canvas.width = window.innerWidth * devicePixelRatio;
      canvas.height = window.innerHeight * devicePixelRatio;
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      draw();
    }

    window.addEventListener("resize", resize);

    function simulateUpdate() {
      for (const s of stocks) {
        const delta = (Math.random() - 0.5) * 2.5;
        const old = s.price;
        s.price = Math.max(1, s.price + delta);
        s.change = s.price - old;
      }
      draw();
    }

    function priceToColor(change) {
      const maxChange = 3;
      const t = Math.max(-1, Math.min(1, change / maxChange));
      if (t >= 0) {
        const g = Math.floor(80 + 175 * t);
        return `rgb(${40},${g},${60})`; // green
      } else {
        const r = Math.floor(80 + 175 * -t);
        return `rgb(${r},${50},${50})`; // red
      }
    }

    function draw() {
      const w = window.innerWidth;
      const h = window.innerHeight;

      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = "#111";
      ctx.fillRect(0, 0, w, h);

      const cols = 8;
      const cellW = 120 * world.scale;
      const cellH = 80 * world.scale;
      const pad = 8 * world.scale;

      stocks.forEach((s, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;

        const x = world.x + col * (cellW + pad);
        const y = world.y + row * (cellH + pad);

        if (x + cellW < 0 || y + cellH < 0 || x > w || y > h) return;

        ctx.fillStyle = priceToColor(s.change);
        ctx.fillRect(x, y, cellW, cellH);

        ctx.strokeStyle = "rgba(255,255,255,0.15)";
        ctx.strokeRect(x, y, cellW, cellH);

        ctx.fillStyle = "#fff";
        ctx.font = `${Math.max(10, 14 * world.scale)}px sans-serif`;
        ctx.fillText(s.symbol, x + 10, y + 22);
        ctx.fillText(`$${s.price.toFixed(2)}`, x + 10, y + 42);
        ctx.fillText(`${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}`, x + 10, y + 62);
      });
    }

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const prevScale = world.scale;
      const nextScale = Math.max(0.4, Math.min(3, prevScale * zoomFactor));

      // Zoom around mouse position
      world.x = mouseX - (mouseX - world.x) * (nextScale / prevScale);
      world.y = mouseY - (mouseY - world.y) * (nextScale / prevScale);
      world.scale = nextScale;

      draw();
    }, { passive: false });

    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      worldStart = { x: world.x, y: world.y };
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      world.x = worldStart.x + (e.clientX - dragStart.x);
      world.y = worldStart.y + (e.clientY - dragStart.y);
      draw();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
    });

    // Initial setup
    resize();
    setInterval(simulateUpdate, 1000);
  </script>
</body>
</html>
```

### What it does
- **Simulates stock prices** every second.
- Colors cells **green for gains** and **red for losses**.
- Supports:
  - **Zoom** with mouse wheel
  - **Pan** by dragging

