## Minimal working example

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      font-family: system-ui, sans-serif;
      background: #0f172a;
      color: #e2e8f0;
    }

    #toolbar {
      position: fixed;
      top: 12px;
      left: 12px;
      z-index: 10;
      background: rgba(15, 23, 42, 0.85);
      padding: 10px 12px;
      border: 1px solid #334155;
      border-radius: 8px;
      backdrop-filter: blur(6px);
      display: flex;
      gap: 8px;
      align-items: center;
    }

    button {
      background: #1e293b;
      color: #e2e8f0;
      border: 1px solid #334155;
      border-radius: 6px;
      padding: 6px 10px;
      cursor: pointer;
    }

    button:hover {
      background: #334155;
    }

    #info {
      font-size: 12px;
      opacity: 0.85;
    }

    canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    #tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(2, 6, 23, 0.95);
      border: 1px solid #334155;
      color: #e2e8f0;
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 12px;
      display: none;
      z-index: 20;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <button id="reset">Reset View</button>
    <div id="info">Drag to pan • Mouse wheel to zoom • Hover to inspect</div>
  </div>
  <div id="tooltip"></div>
  <canvas id="c"></canvas>

  <script>
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('reset');

    const state = {
      dpr: window.devicePixelRatio || 1,
      width: 0,
      height: 0,
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      hovered: null,
      stocks: []
    };

    // Generate a grid of sample stock "tiles"
    const cols = 12;
    const rows = 8;
    const tileSize = 90;
    const gap = 10;
    const startX = 40;
    const startY = 40;

    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','INTC','NFLX','ORCL','IBM',
      'JPM','BAC','WFC','GS','C','UBER','CRM','NOW','ADBE','QCOM','SHOP','SNOW',
      'XOM','CVX','COP','PFE','JNJ','UNH','KO','PEP','MCD','NKE','DIS','SBUX',
      'BA','CAT','GE','HON','LMT','RTX','PLTR','SQ','PYPL','LIN','TMO','ABT',
      'V','MA','AXP','SPGI','BLK','GILD','MRNA','ISRG','TDOC','ZS','PANW','CRWD',
      'ETN','DE','MMM','INTU','AMD2','ABNB','DASH','F','GM','RIVN','SNAP','CHTR',
      'T','VZ','TMUS','CMCSA','CSCO','AAL','DAL','UAL','NOC','FSLR','ENPH','OKTA'
    ];

    function initStocks() {
      state.stocks = [];
      let i = 0;
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          state.stocks.push({
            symbol: symbols[i % symbols.length],
            x: startX + c * (tileSize + gap),
            y: startY + r * (tileSize + gap),
            size: tileSize,
            price: 50 + Math.random() * 450,
            change: (Math.random() - 0.5) * 10
          });
          i++;
        }
      }
    }

    function resize() {
      state.dpr = window.devicePixelRatio || 1;
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + 'px';
      canvas.style.height = state.height + 'px';
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // Map change to red -> neutral -> green
      const maxAbs = 10;
      const t = clamp((change + maxAbs) / (2 * maxAbs), 0, 1);
      const r = Math.round(220 * (1 - t) + 40 * t);
      const g = Math.round(50 + 180 * t);
      const b = Math.round(60 * (1 - t) + 60 * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function screenToWorld(sx, sy) {
      return {
        x: (sx - state.panX) / state.zoom,
        y: (sy - state.panY) / state.zoom
      };
    }

    function worldToScreen(wx, wy) {
      return {
        x: wx * state.zoom + state.panX,
        y: wy * state.zoom + state.panY
      };
    }

    function draw() {
      ctx.clearRect(0, 0, state.width, state.height);

      // Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, state.width, state.height);

      // Draw tiles
      for (const stock of state.stocks) {
        const s = worldToScreen(stock.x, stock.y);
        const size = stock.size * state.zoom;

        // Only draw if visible
        if (s.x + size < 0 || s.y + size < 0 || s.x > state.width || s.y > state.height) continue;

        ctx.fillStyle = colorForChange(stock.change);
        ctx.fillRect(s.x, s.y, size, size);

        ctx.strokeStyle = 'rgba(15, 23, 42, 0.7)';
        ctx.lineWidth = 1;
        ctx.strokeRect(s.x, s.y, size, size);

        ctx.fillStyle = '#f8fafc';
        ctx.font = `${Math.max(10, 14 * state.zoom)}px system-ui, sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        const centerX = s.x + size / 2;
        const centerY = s.y + size / 2;

        ctx.fillText(stock.symbol, centerX, centerY - 8 * state.zoom);
        ctx.font = `${Math.max(9, 12 * state.zoom)}px system-ui, sans-serif`;
        const sign = stock.change >= 0 ? '+' : '';
        ctx.fillText(`${sign}${stock.change.toFixed(2)}`, centerX, centerY + 10 * state.zoom);
      }

      // Highlight hovered tile
      if (state.hovered) {
        const s = worldToScreen(state.hovered.x, state.hovered.y);
        const size = state.hovered.size * state.zoom;
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(s.x, s.y, size, size);
      }
    }

    function updateTooltip(stock, mouseX, mouseY) {
      if (!stock) {
        tooltip.style.display = 'none';
        return;
      }
      const sign = stock.change >= 0 ? '+' : '';
      tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br/>
        Price: $${stock.price.toFixed(2)}<br/>
        Change: ${sign}${stock.change.toFixed(2)}
      `;
      tooltip.style.left = (mouseX + 12) + 'px';
      tooltip.style.top = (mouseY + 12) + 'px';
      tooltip.style.display = 'block';
    }

    function hitTest(mx, my) {
      const world = screenToWorld(mx, my);
      for (const stock of state.stocks) {
        if (
          world.x >= stock.x &&
          world.x <= stock.x + stock.size &&
          world.y >= stock.y &&
          world.y <= stock.y + stock.size
        ) {
          return stock;
        }
      }
      return null;
    }

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      if (state.dragging) {
        const dx = e.clientX - state.lastX;
        const dy = e.clientY - state.lastY;
        state.panX += dx;
        state.panY += dy;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
        draw();
      }

      state.hovered = hitTest(e.clientX, e.clientY);
      updateTooltip(state.hovered, e.clientX, e.clientY);
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const mouseX = e.clientX;
      const mouseY = e.clientY;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldZoom = state.zoom;
      const newZoom = clamp(oldZoom * zoomFactor, 0.4, 4);

      // Zoom around cursor
      const worldBefore = screenToWorld(mouseX, mouseY);
      state.zoom = newZoom;
      const screenAfter = worldToScreen(worldBefore.x, worldBefore.y);
      state.panX += mouseX - screenAfter.x;
      state.panY += mouseY - screenAfter.y;

      draw();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      state.zoom = 1;
      state.panX = 0;
      state.panY = 0;
      draw();
    });

    // Simulated real-time updates
    setInterval(() => {
      for (const stock of state.stocks) {
        // small random walk
        const delta = (Math.random() - 0.5) * 2;
        stock.change = clamp(stock.change + delta, -10, 10);
        stock.price = Math.max(1, stock.price + (Math.random() - 0.5) * 5);
      }
      draw();
    }, 500);

    window.addEventListener('resize', resize);

    initStocks();
    resize();
    state.panX = 0;
    state.panY = 0;
  </script>
</body>
</html>
```

