import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type BoardState = {
  todo: Task[];
  doing: Task[];
  done: Task[];
};

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

const initialBoard: BoardState = {
  todo: [
    { id: "t1", title: "Design app layout" },
    { id: "t2", title: "Set up auth flow" }
  ],
  doing: [
    { id: "t3", title: "Build drag-and-drop board" }
  ],
  done: [
    { id: "t4", title: "Define requirements" }
  ]
};

let board: BoardState = structuredClone(initialBoard);

app.get("/api/board", (_req, res) => {
  res.json(board);
});

app.post("/api/board/reset", (_req, res) => {
  board = structuredClone(initialBoard);
  io.emit("board:update", board);
  res.json({ ok: true, board });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:update", (payload: { taskId: string; from: keyof BoardState; to: keyof BoardState; index: number }) => {
    const { taskId, from, to, index } = payload;

    const sourceList = board[from];
    const targetList = board[to];

    const taskIndex = sourceList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceList.splice(taskIndex, 1);
    targetList.splice(index, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:add", (payload: { lane: keyof BoardState; title: string }) => {
    const { lane, title } = payload;
    const newTask: Task = {
      id: crypto.randomUUID(),
      title
    };
    board[lane].unshift(newTask);
    io.emit("board:update", board);
  });

  socket.on("task:remove", (payload: { taskId: string }) => {
    const { taskId } = payload;

    for (const lane of Object.keys(board) as (keyof BoardState)[]) {
      const idx = board[lane].findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        board[lane].splice(idx, 1);
        io.emit("board:update", board);
        return;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
