```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type BoardState = {
  todo: Task[];
  doing: Task[];
  done: Task[];
};

type Lane = keyof BoardState;

const socket: Socket = io("http://localhost:3001");

const laneLabels: Record<Lane, string> = {
  todo: "To Do",
  doing: "Doing",
  done: "Done"
};

export default function App() {
  const [board, setBoard] = useState<BoardState>({
    todo: [],
    doing: [],
    done: []
  });
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    socket.on("board:update", (nextBoard: BoardState) => {
      setBoard(nextBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const allTasksCount = useMemo(
    () => board.todo.length + board.doing.length + board.done.length,
    [board]
  );

  const handleDragStart = (e: React.DragEvent, taskId: string, from: Lane) => {
    e.dataTransfer.setData("taskId", taskId);
    e.dataTransfer.setData("from", from);
  };

  const handleDrop = (e: React.DragEvent, to: Lane, index: number) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("taskId");
    const from = e.dataTransfer.getData("from") as Lane;

    if (!taskId || !from) return;
    socket.emit("task:update", { taskId, from, to, index });
  };

  const handleAddTask = () => {
    const title = newTaskTitle.trim();
    if (!title) return;
    socket.emit("task:add", { lane: "todo", title });
    setNewTaskTitle("");
  };

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Project Board</h1>
          <p>{allTasksCount} tasks • real-time collaboration enabled</p>
        </div>

        <div className="add-task">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="Add a new task..."
            onKeyDown={(e) => {
              if (e.key === "Enter") handleAddTask();
            }}
          />
          <button onClick={handleAddTask}>Add</button>
        </div>
      </header>

      <main className="board">
        {(Object.keys(board) as Lane[]).map((lane) => (
          <section
            key={lane}
            className="lane"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => handleDrop(e, lane, board[lane].length)}
          >
            <h2>{laneLabels[lane]}</h2>

            <div className="task-list">
              {board[lane].map((task, index) => (
                <div
                  key={task.id}
                  className="task"
                  draggable
                  onDragStart={(e) => handleDragStart(e, task.id, lane)}
                  onDrop={(e) => handleDrop(e, lane, index)}
                  onDragOver={(e) => e.preventDefault()}
                >
                  <span>{task.title}</span>
                  <button
                    className="remove"
                    onClick={() => socket.emit("task:remove", { taskId: task.id })}
                  >
                    ×
                  </button>
                </div>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

