import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
};

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let board: BoardState = {
  tasks: {
    "task-1": { id: "task-1", title: "Design board layout" },
    "task-2": { id: "task-2", title: "Set up backend" },
    "task-3": { id: "task-3", title: "Add drag and drop" },
    "task-4": { id: "task-4", title: "Enable live updates" }
  },
  columns: {
    "todo": {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    "doing": {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    "done": {
      id: "done",
      title: "Done",
      taskIds: ["task-4"]
    }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/api/board", (_req, res) => {
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:state", board);

  socket.on("board:update", (nextBoard: BoardState) => {
    board = nextBoard;
    socket.broadcast.emit("board:state", board);
  });

  socket.on("task:create", (task: { title: string; description?: string; columnId: string }) => {
    const id = `task-${Date.now()}`;
    const newTask: Task = {
      id,
      title: task.title,
      description: task.description
    };

    board.tasks[id] = newTask;
    board.columns[task.columnId].taskIds.unshift(id);

    io.emit("board:state", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

app.get("/", (_req, res) => {
  res.send("Project board server running");
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

