## `client/src/Board.tsx`

```tsx
import { useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners
} from "@dnd-kit/core";
import { SortableContext, arrayMove, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { socket } from "./socket";
import type { BoardState } from "./App";

type Props = {
  board: BoardState;
  setBoard: React.Dispatch<React.SetStateAction<BoardState | null>>;
};

export default function Board({ board, setBoard }: Props) {
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 }
    })
  );

  const columns = useMemo(
    () => board.columnOrder.map((id) => board.columns[id]),
    [board]
  );

  function findColumnByTaskId(taskId: string) {
    return Object.values(board.columns).find((column) => column.taskIds.includes(taskId));
  }

  function handleDragStart(event: DragStartEvent) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragOver(event: DragOverEvent) {
    const { active, over } = event;
    if (!over) return;

    const activeId = String(active.id);
    const overId = String(over.id);

    const activeColumn = findColumnByTaskId(activeId);
    const overColumn = board.columns[overId] ?? findColumnByTaskId(overId);

    if (!activeColumn || !overColumn || activeColumn.id === overColumn.id) return;

    const next = structuredClone(board);

    next.columns[activeColumn.id].taskIds = next.columns[activeColumn.id].taskIds.filter(
      (id) => id !== activeId
    );

    const overTaskIndex = next.columns[overColumn.id].taskIds.indexOf(overId);
    if (overTaskIndex >= 0) {
      next.columns[overColumn.id].taskIds.splice(overTaskIndex, 0, activeId);
    } else {
      next.columns[overColumn.id].taskIds.unshift(activeId);
    }

    setBoard(next);
    socket.emit("board:update", next);
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveTaskId(null);

    const { active, over } = event;
    if (!over) return;

    const activeId = String(active.id);
    const overId = String(over.id);

    const activeColumn = findColumnByTaskId(activeId);
    const overColumn = board.columns[overId] ?? findColumnByTaskId(overId);

    if (!activeColumn || !overColumn) return;

    if (activeColumn.id === overColumn.id) {
      const oldIndex = activeColumn.taskIds.indexOf(activeId);
      const newIndex = activeColumn.taskIds.indexOf(overId);

      if (oldIndex !== newIndex && newIndex >= 0) {
        const next = structuredClone(board);
        next.columns[activeColumn.id].taskIds = arrayMove(
          next.columns[activeColumn.id].taskIds,
          oldIndex,
          newIndex
        );

        setBoard(next);
        socket.emit("board:update", next);
      }
      return;
    }
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDragEnd={handleDragEnd}
    >
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
        {columns.map((column) => (
          <div
            key={column.id}
            style={{
              width: 320,
              background: "#f4f5f7",
              borderRadius: 12,
              padding: 12,
              minHeight: 500
            }}
          >
            <h2 style={{ marginTop: 0 }}>{column.title}</h2>

            <SortableContext
              items={column.taskIds}
              strategy={verticalListSortingStrategy}
            >
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {column.taskIds.map((taskId) => {
                  const task = board.tasks[taskId];
                  if (!task) return null;

                  return (
                    <TaskCard key={task.id} id={task.id} title={task.title} />
                  );
                })}
              </div>
            </SortableContext>
          </div>
        ))}
      </div>
    </DndContext>
  );
}

import { useDraggable } from "@dnd-kit/core";

function TaskCard({ id, title }: { id: string; title: string }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id
  });

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      style={{
        transform: transform
          ? `translate3d(${transform.x}px, ${transform.y}px, 0)`
          : undefined,
        background: "white",
        padding: 12,
        borderRadius: 10,
        boxShadow: "0 1px 4px rgba(0,0,0,0.12)",
        cursor: "grab",
        opacity: isDragging ? 0.5 : 1
      }}
    >
      {title}
    </div>
  );
}
```

