### `server/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer, WebSocket } from "ws";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  columns: Column[];
  tasks: Record<string, Task>;
};

type ClientMessage =
  | { type: "task-move"; taskId: string; fromColumnId: string; toColumnId: string; toIndex: number }
  | { type: "task-create"; title: string; description?: string }
  | { type: "task-update"; taskId: string; title?: string; description?: string }
  | { type: "task-delete"; taskId: string };

type ServerMessage =
  | { type: "board-state"; state: BoardState }
  | { type: "board-update"; state: BoardState }
  | { type: "presence"; connectedUsers: number };

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

let state: BoardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
    { id: "doing", title: "In Progress", taskIds: ["task-3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Design app layout" },
    "task-2": { id: "task-2", title: "Set up WebSocket sync" },
    "task-3": { id: "task-3", title: "Implement drag and drop" }
  }
};

const clients = new Set<WebSocket>();

function broadcast(message: ServerMessage) {
  const data = JSON.stringify(message);
  for (const client of clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  }
}

function getConnectionCount() {
  return clients.size;
}

function sendBoardState(client: WebSocket) {
  const message: ServerMessage = { type: "board-state", state };
  client.send(JSON.stringify(message));
}

function moveTask(taskId: string, fromColumnId: string, toColumnId: string, toIndex: number) {
  const fromColumn = state.columns.find((c) => c.id === fromColumnId);
  const toColumn = state.columns.find((c) => c.id === toColumnId);
  if (!fromColumn || !toColumn) return;

  const fromIndex = fromColumn.taskIds.indexOf(taskId);
  if (fromIndex === -1) return;

  fromColumn.taskIds.splice(fromIndex, 1);

  const safeIndex = Math.max(0, Math.min(toIndex, toColumn.taskIds.length));
  toColumn.taskIds.splice(safeIndex, 0, taskId);
}

app.get("/health", (_req, res) => {
  res.json({ ok: true, users: getConnectionCount() });
});

wss.on("connection", (ws) => {
  clients.add(ws);
  sendBoardState(ws);
  broadcast({ type: "presence", connectedUsers: getConnectionCount() });

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString()) as ClientMessage;

      switch (msg.type) {
        case "task-create": {
          const id = `task-${cryptoRandomId()}`;
          state.tasks[id] = { id, title: msg.title, description: msg.description };
          const firstColumn = state.columns[0];
          firstColumn.taskIds.push(id);
          break;
        }

        case "task-update": {
          const task = state.tasks[msg.taskId];
          if (!task) break;
          if (msg.title !== undefined) task.title = msg.title;
          if (msg.description !== undefined) task.description = msg.description;
          break;
        }

        case "task-delete": {
          delete state.tasks[msg.taskId];
          for (const column of state.columns) {
            column.taskIds = column.taskIds.filter((id) => id !== msg.taskId);
          }
          break;
        }

        case "task-move": {
          moveTask(msg.taskId, msg.fromColumnId, msg.toColumnId, msg.toIndex);
          break;
        }
      }

      broadcast({ type: "board-update", state });
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });

  ws.on("close", () => {
    clients.delete(ws);
    broadcast({ type: "presence", connectedUsers: getConnectionCount() });
  });
});

function cryptoRandomId() {
  return Math.random().toString(36).slice(2, 10);
}

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

