### `client/main.ts`
```ts
type Task = {
  id: string;
  title: string;
  description?: string;
};

type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  columns: Column[];
  tasks: Record<string, Task>;
};

type ServerMessage =
  | { type: "board-state"; state: BoardState }
  | { type: "board-update"; state: BoardState }
  | { type: "presence"; connectedUsers: number };

type ClientMessage =
  | { type: "task-move"; taskId: string; fromColumnId: string; toColumnId: string; toIndex: number }
  | { type: "task-create"; title: string; description?: string };

const boardEl = document.getElementById("board") as HTMLDivElement;
const presenceEl = document.getElementById("presence") as HTMLDivElement;
const taskTitleInput = document.getElementById("taskTitle") as HTMLInputElement;
const addTaskBtn = document.getElementById("addTaskBtn") as HTMLButtonElement;

const ws = new WebSocket("ws://localhost:3001");
let state: BoardState | null = null;

let dragData: { taskId: string; fromColumnId: string } | null = null;

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data) as ServerMessage;

  if (msg.type === "board-state" || msg.type === "board-update") {
    state = msg.state;
    render();
  }

  if (msg.type === "presence") {
    presenceEl.textContent = `Connected users: ${msg.connectedUsers}`;
  }
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  if (!title) return;

  const msg: ClientMessage = { type: "task-create", title };
  ws.send(JSON.stringify(msg));
  taskTitleInput.value = "";
});

function render() {
  if (!state) return;

  boardEl.innerHTML = "";

  for (const column of state.columns) {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    columnEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!dragData) return;

      const msg: ClientMessage = {
        type: "task-move",
        taskId: dragData.taskId,
        fromColumnId: dragData.fromColumnId,
        toColumnId: column.id,
        toIndex: column.taskIds.length
      };
      ws.send(JSON.stringify(msg));
      dragData = null;
    });

    const h2 = document.createElement("h2");
    h2.textContent = column.title;
    columnEl.appendChild(h2);

    column.taskIds.forEach((taskId, index) => {
      const task = state!.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        dragData = { taskId: task.id, fromColumnId: column.id };
      });

      taskEl.addEventListener("dragover", (e) => {
        e.preventDefault();
      });

      taskEl.addEventListener("drop", (e) => {
        e.preventDefault();
        if (!dragData) return;

        const msg: ClientMessage = {
          type: "task-move",
          taskId: dragData.taskId,
          fromColumnId: dragData.fromColumnId,
          toColumnId: column.id,
          toIndex: index
        };
        ws.send(JSON.stringify(msg));
        dragData = null;
      });

      columnEl.appendChild(taskEl);
    });

    boardEl.appendChild(columnEl);
  }
}
