import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer, WebSocket } from "ws";

type Task = {
  id: string;
  title: string;
  boardId: string;
};

type Board = {
  id: string;
  title: string;
};

type State = {
  boards: Board[];
  tasks: Task[];
};

type ClientMessage =
  | { type: "move-task"; taskId: string; boardId: string }
  | { type: "add-task"; title: string; boardId: string };

type ServerMessage =
  | { type: "state"; state: State }
  | { type: "state-updated"; state: State };

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

let state: State = {
  boards: [
    { id: "todo", title: "Todo" },
    { id: "doing", title: "Doing" },
    { id: "done", title: "Done" }
  ],
  tasks: [
    { id: "1", title: "Design app layout", boardId: "todo" },
    { id: "2", title: "Set up WebSocket server", boardId: "doing" },
    { id: "3", title: "Build drag-and-drop", boardId: "done" }
  ]
};

function broadcast(message: ServerMessage) {
  const payload = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", state } satisfies ServerMessage));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString()) as ClientMessage;

      if (msg.type === "move-task") {
        state = {
          ...state,
          tasks: state.tasks.map((task) =>
            task.id === msg.taskId ? { ...task, boardId: msg.boardId } : task
          )
        };
      }

      if (msg.type === "add-task") {
        const newTask: Task = {
          id: crypto.randomUUID(),
          title: msg.title,
          boardId: msg.boardId
        };
        state = { ...state, tasks: [...state.tasks, newTask] };
      }

      broadcast({ type: "state-updated", state });
    } catch {
      // ignore malformed messages
    }
  });
});

app.get("/health", (_, res) => {
  res.json({ ok: true });
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
