```ts
type Task = {
  id: string;
  title: string;
  boardId: string;
};

type Board = {
  id: string;
  title: string;
};

type State = {
  boards: Board[];
  tasks: Task[];
};

type ServerMessage =
  | { type: "state"; state: State }
  | { type: "state-updated"; state: State };

const boardsEl = document.querySelector<HTMLDivElement>("#boards")!;
const form = document.querySelector<HTMLFormElement>("#new-task-form")!;
const titleInput = document.querySelector<HTMLInputElement>("#task-title")!;
const boardSelect = document.querySelector<HTMLSelectElement>("#task-board")!;

const ws = new WebSocket("ws://localhost:3000");

let currentState: State = {
  boards: [],
  tasks: []
};

function render() {
  boardsEl.innerHTML = "";

  for (const board of currentState.boards) {
    const boardTasks = currentState.tasks.filter((t) => t.boardId === board.id);

    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.dataset.boardId = board.id;

    boardEl.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-dropzone="${board.id}"></div>
    `;

    const taskList = boardEl.querySelector<HTMLDivElement>(".task-list")!;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      const taskId = e.dataTransfer?.getData("text/task-id");
      if (taskId) {
        ws.send(JSON.stringify({ type: "move-task", taskId, boardId: board.id }));
      }
    });

    for (const task of boardTasks) {
      const taskEl = document.createElement("article");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer?.setData("text/task-id", task.id);
      });

      taskList.appendChild(taskEl);
    }

    boardsEl.appendChild(boardEl);
  }
}

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data) as ServerMessage;
  currentState = msg.state;
  render();
});

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = titleInput.value.trim();
  const boardId = boardSelect.value;

  if (!title) return;

  ws.send(JSON.stringify({ type: "add-task", title, boardId }));
  titleInput.value = "";
});
```

