```ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";

type Status = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  status: Status;
  order: number;
};

type BoardState = {
  tasks: Task[];
};

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = {
  tasks: [
    { id: crypto.randomUUID(), title: "Set up project", status: "todo", order: 0 },
    { id: crypto.randomUUID(), title: "Design board layout", status: "doing", order: 0 },
    { id: crypto.randomUUID(), title: "Add real-time sync", status: "done", order: 0 }
  ]
};

function sortTasks(tasks: Task[]) {
  return [...tasks].sort((a, b) => a.order - b.order);
}

function normalizeBoardState(state: BoardState): BoardState {
  const grouped: Record<Status, Task[]> = {
    todo: [],
    doing: [],
    done: []
  };

  for (const task of state.tasks) grouped[task.status].push(task);

  const normalized: Task[] = [];
  (["todo", "doing", "done"] as Status[]).forEach((status) => {
    sortTasks(grouped[status]).forEach((task, index) => {
      normalized.push({ ...task, status, order: index });
    });
  });

  return { tasks: normalized };
}

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title } = req.body as { title?: string };
  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const newTask: Task = {
    id: crypto.randomUUID(),
    title: title.trim(),
    status: "todo",
    order: boardState.tasks.filter((t) => t.status === "todo").length
  };

  boardState = {
    tasks: [...boardState.tasks, newTask]
  };

  io.emit("board:update", boardState);
  res.status(201).json(newTask);
});

app.post("/api/tasks/move", (req, res) => {
  const { taskId, status, order } = req.body as {
    taskId?: string;
    status?: Status;
    order?: number;
  };

  if (!taskId || !status || order === undefined) {
    return res.status(400).json({ error: "taskId, status, and order are required" });
  }

  const taskIndex = boardState.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const updatedTasks = boardState.tasks.map((t) =>
    t.id === taskId ? { ...t, status, order } : t
  );

  boardState = normalizeBoardState({ tasks: updatedTasks });
  io.emit("board:update", boardState);

  res.json(boardState);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  const exists = boardState.tasks.some((t) => t.id === id);
  if (!exists) return res.status(404).json({ error: "Task not found" });

  boardState = normalizeBoardState({
    tasks: boardState.tasks.filter((t) => t.id !== id)
  });

  io.emit("board:update", boardState);
  res.status(204).send();
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);
  socket.emit("board:update", boardState);

  socket.on("board:sync", (incomingState: BoardState) => {
    boardState = normalizeBoardState(incomingState);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

app.get("/health", (_req, res) => res.json({ ok: true }));

const PORT = 3001;
httpServer.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

