### `client/src/main.ts`
```ts
import "./styles.css";
import { io, Socket } from "socket.io-client";

type Status = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  status: Status;
  order: number;
};

type BoardState = {
  tasks: Task[];
};

const SERVER_URL = "http://localhost:3001";

const socket: Socket = io(SERVER_URL);

let boardState: BoardState = { tasks: [] };
let draggingTaskId: string | null = null;

const app = document.querySelector<HTMLDivElement>("#app");
if (!app) throw new Error("App root not found");

function tasksByStatus(status: Status) {
  return boardState.tasks
    .filter((task) => task.status === status)
    .sort((a, b) => a.order - b.order);
}

function render() {
  app.innerHTML = `
    <div class="app">
      <div class="header">
        <h1>Project Board</h1>
        <form class="add-form" id="add-form">
          <input id="task-title" placeholder="Add a task..." />
          <button type="submit">Add Task</button>
        </form>
      </div>

      <div class="board">
        ${["todo", "doing", "done"]
          .map((status) => {
            const title =
              status === "todo" ? "To Do" : status === "doing" ? "Doing" : "Done";

            return `
              <section class="column" data-status="${status}">
                <h2>${title}</h2>
                <div class="dropzone" data-dropzone="${status}">
                  ${tasksByStatus(status as Status)
                    .map(
                      (task) => `
                        <div class="task" draggable="true" data-task-id="${task.id}">
                          <strong>${escapeHtml(task.title)}</strong>
                          <div class="task-actions">
                            <button data-move-left="${task.id}">←</button>
                            <button data-delete="${task.id}">Delete</button>
                            <button data-move-right="${task.id}">→</button>
                          </div>
                        </div>
                      `
                    )
                    .join("")}
                </div>
              </section>
            `;
          })
          .join("")}
      </div>
    </div>
  `;

  wireEvents();
}

function wireEvents() {
  document.querySelector<HTMLFormElement>("#add-form")?.addEventListener("submit", async (e) => {
    e.preventDefault();
    const input = document.querySelector<HTMLInputElement>("#task-title");
    const title = input?.value.trim();
    if (!title) return;

    await fetch(`${SERVER_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title })
    });

    if (input) input.value = "";
  });

  document.querySelectorAll<HTMLElement>(".task").forEach((taskEl) => {
    taskEl.addEventListener("dragstart", () => {
      draggingTaskId = taskEl.dataset.taskId ?? null;
    });
  });

  document.querySelectorAll<HTMLElement>(".dropzone").forEach((zone) => {
    zone.addEventListener("dragover", (e) => e.preventDefault());
    zone.addEventListener("drop", async (e) => {
      e.preventDefault();
      if (!draggingTaskId) return;

      const status = zone.dataset.dropzone as Status | undefined;
      if (!status) return;

      const tasks = tasksByStatus(status);
      const order = tasks.length;

      await fetch(`${SERVER_URL}/api/tasks/move`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ taskId: draggingTaskId, status, order })
      });

      draggingTaskId = null;
    });
  });

  document.querySelectorAll<HTMLButtonElement>("[data-delete]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.dataset.delete;
      if (!id) return;

      await fetch(`${SERVER_URL}/api/tasks/${id}`, {
        method: "DELETE"
      });
    });
  });

  document.querySelectorAll<HTMLButtonElement>("[data-move-left]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.dataset.moveLeft;
      if (!id) return;

      const task = boardState.tasks.find((t) => t.id === id);
      if (!task) return;

      const previous: Record<Status, Status | null> = {
        todo: null,
        doing: "todo",
        done: "doing"
      };

      const targetStatus = previous[task.status];
      if (!targetStatus) return;

      const order = tasksByStatus(targetStatus).length;

      await fetch(`${SERVER_URL}/api/tasks/move`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ taskId: id, status: targetStatus, order })
      });
    });
  });

  document.querySelectorAll<HTMLButtonElement>("[data-move-right]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.dataset.moveRight;
      if (!id) return;

      const task = boardState.tasks.find((t) => t.id === id);
      if (!task) return;

      const next: Record<Status, Status | null> = {
        todo: "doing",
        doing: "done",
        done: null
      };

      const targetStatus = next[task.status];
      if (!targetStatus) return;

      const order = tasksByStatus(targetStatus).length;

      await fetch(`${SERVER_URL}/api/tasks/move`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ taskId: id, status: targetStatus, order })
      });
    });
  });
}

socket.on("board:update", (state: BoardState) => {
  boardState = state;
  render();
});

fetch(`${SERVER_URL}/api/board`)
  .then((res) => res.json())
  .then((state: BoardState) => {
    boardState = state;
    render();
  });

function escapeHtml(str: string) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
