### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { BoardState, initialState } from "./state";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body as {
    title: string;
    description?: string;
    columnId?: string;
  };

  if (!title) {
    return res.status(400).json({ error: "title is required" });
  }

  const id = `task-${Date.now()}`;
  boardState.tasks[id] = { id, title, description };

  const targetColumnId = columnId || boardState.columnOrder[0];
  boardState.columns[targetColumnId].taskIds.push(id);

  io.emit("board:update", boardState);
  res.status(201).json(boardState.tasks[id]);
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on(
    "task:moved",
    (payload: {
      taskId: string;
      sourceColumnId: string;
      destinationColumnId: string;
      sourceIndex: number;
      destinationIndex: number;
    }) => {
      const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } =
        payload;

      const sourceColumn = boardState.columns[sourceColumnId];
      const destinationColumn = boardState.columns[destinationColumnId];

      if (!sourceColumn || !destinationColumn) return;

      sourceColumn.taskIds.splice(sourceIndex, 1);

      if (sourceColumnId === destinationColumnId) {
        sourceColumn.taskIds.splice(destinationIndex, 0, taskId);
      } else {
        destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
      }

      io.emit("board:update", boardState);
    }
  );
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

