### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { boardState, Task, TaskStatus } from "./state.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status = "todo" } = req.body as {
    title?: string;
    description?: string;
    status?: TaskStatus;
  };

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  const task: Task = {
    id: crypto.randomUUID(),
    title,
    description,
    status,
    updatedAt: Date.now()
  };

  boardState.tasks.push(task);
  io.emit("board:update", boardState);

  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks.find((t) => t.id === id);

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const { title, description, status } = req.body as Partial<Task>;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (status !== undefined) task.status = status;

  task.updatedAt = Date.now();
  io.emit("board:update", boardState);

  res.json(task);
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("task:move", (payload: { taskId: string; status: TaskStatus }) => {
    const task = boardState.tasks.find((t) => t.id === payload.taskId);
    if (!task) return;

    task.status = payload.status;
    task.updatedAt = Date.now();

    io.emit("board:update", boardState);
  });

  socket.on("task:create", (payload: { title: string; description?: string }) => {
    const task: Task = {
      id: crypto.randomUUID(),
      title: payload.title,
      description: payload.description,
      status: "todo",
      updatedAt: Date.now()
    };

    boardState.tasks.push(task);
    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
