```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type TaskStatus = "todo" | "doing" | "done";

interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  updatedAt: number;
}

interface BoardState {
  tasks: Task[];
}

const API_URL = "http://localhost:3001";
const socket: Socket = io(API_URL);

const columns: { id: TaskStatus; title: string }[] = [
  { id: "todo", title: "To Do" },
  { id: "doing", title: "In Progress" },
  { id: "done", title: "Done" }
];

export default function App() {
  const [board, setBoard] = useState<BoardState>({ tasks: [] });
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    socket.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const grouped = useMemo(() => {
    return Object.fromEntries(
      columns.map((col) => [
        col.id,
        board.tasks
          .filter((task) => task.status === col.id)
          .sort((a, b) => b.updatedAt - a.updatedAt)
      ])
    ) as Record<TaskStatus, Task[]>;
  }, [board.tasks]);

  function handleDragStart(taskId: string) {
    return (event: React.DragEvent<HTMLDivElement>) => {
      event.dataTransfer.setData("taskId", taskId);
    };
  }

  function handleDrop(status: TaskStatus) {
    return (event: React.DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      const taskId = event.dataTransfer.getData("taskId");
      if (!taskId) return;
      socket.emit("task:move", { taskId, status });
    };
  }

  async function createTask(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim()) return;

    socket.emit("task:create", {
      title: title.trim(),
      description: description.trim() || undefined
    });

    setTitle("");
    setDescription("");
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns and sync in real time.</p>

        <form className="new-task-form" onSubmit={createTask}>
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Task description"
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={handleDrop(column.id)}
          >
            <h2>{column.title}</h2>
            <div className="task-list">
              {grouped[column.id].map((task) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={handleDragStart(task.id)}
                >
                  <strong>{task.title}</strong>
                  {task.description && <p>{task.description}</p>}
                </div>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

