### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import { WebSocketServer } from "ws";
import { randomUUID } from "node:crypto";
import { state, type Task, type TaskStatus } from "./state.js";

const app = express();
app.use(cors());
app.use(express.json());

const PORT = 3001;

const server = app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});

const wss = new WebSocketServer({ server });

const clients = new Set<WebSocket>();

function broadcast() {
  const payload = JSON.stringify({
    type: "state",
    data: state
  });

  for (const client of clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  }
}

function normalizeOrders() {
  const grouped = {
    todo: state.tasks.filter((t) => t.status === "todo"),
    inprogress: state.tasks.filter((t) => t.status === "inprogress"),
    done: state.tasks.filter((t) => t.status === "done")
  };

  (Object.entries(grouped) as [TaskStatus, Task[]][]).forEach(([status, tasks]) => {
    tasks
      .sort((a, b) => a.order - b.order)
      .forEach((task, idx) => {
        task.status = status;
        task.order = idx;
      });
  });
}

app.get("/api/state", (_req, res) => {
  normalizeOrders();
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status } = req.body as {
    title?: string;
    description?: string;
    status?: TaskStatus;
  };

  if (!title?.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const taskStatus: TaskStatus = status ?? "todo";
  const sameColumn = state.tasks.filter((t) => t.status === taskStatus);
  const task: Task = {
    id: randomUUID(),
    title: title.trim(),
    description: description?.trim(),
    status: taskStatus,
    order: sameColumn.length,
    updatedAt: Date.now()
  };

  state.tasks.push(task);
  broadcast();
  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const task = state.tasks.find((t) => t.id === req.params.id);
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, status, order } = req.body as Partial<Task>;

  if (typeof title === "string") task.title = title;
  if (typeof description === "string") task.description = description;
  if (status) task.status = status;
  if (typeof order === "number") task.order = order;

  task.updatedAt = Date.now();
  normalizeOrders();
  broadcast();
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const idx = state.tasks.findIndex((t) => t.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: "Task not found" });

  state.tasks.splice(idx, 1);
  normalizeOrders();
  broadcast();
  res.status(204).send();
});

wss.on("connection", (ws) => {
  clients.add(ws);

  ws.send(JSON.stringify({ type: "state", data: state }));

  ws.on("close", () => {
    clients.delete(ws);
  });

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "move-task") {
        const { taskId, status, order } = msg.data as {
          taskId: string;
          status: TaskStatus;
          order: number;
        };

        const task = state.tasks.find((t) => t.id === taskId);
        if (!task) return;

        task.status = status;
        task.order = order;
        task.updatedAt = Date.now();
        normalizeOrders();
        broadcast();
      }
    } catch {
      // ignore invalid messages
    }
  });
});
```

