### `client/src/App.tsx`
```tsx
import React, { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  closestCorners,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { SortableContext, arrayMove, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { createTask, fetchState } from "./api";
import { createSocket } from "./ws";
import type { BoardState, Task, TaskStatus } from "./types";
import "./styles.css";

const columns: { id: TaskStatus; title: string }[] = [
  { id: "todo", title: "To Do" },
  { id: "inprogress", title: "In Progress" },
  { id: "done", title: "Done" }
];

export default function App() {
  const [state, setState] = useState<BoardState>({ tasks: [] });
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }));

  useEffect(() => {
    fetchState().then(setState).catch(console.error);

    const socket = createSocket((msg) => {
      if (msg.type === "state") setState(msg.data);
    });

    return () => socket.close();
  }, []);

  const grouped = useMemo(() => {
    const byStatus: Record<TaskStatus, Task[]> = {
      todo: [],
      inprogress: [],
      done: []
    };

    [...state.tasks]
      .sort((a, b) => a.order - b.order)
      .forEach((task) => byStatus[task.status].push(task));

    return byStatus;
  }, [state.tasks]);

  async function addTask(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim()) return;

    await createTask({ title, description, status: "todo" });
    setTitle("");
    setDescription("");
  }

  function findTask(id: string) {
    return state.tasks.find((t) => t.id === id);
  }

  function handleDragStart(event: DragStartEvent) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragOver(event: DragOverEvent) {
    // Optional preview logic can go here
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveTaskId(null);

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const targetId = String(over.id);

    const task = findTask(taskId);
    if (!task) return;

    const targetTask = findTask(targetId);
    const targetColumn = columns.find((c) => c.id === targetId as TaskStatus);

    if (targetTask) {
      const sourceTasks = grouped[task.status].filter((t) => t.id !== taskId);
      const destinationStatus = targetTask.status;

      const destinationTasks = grouped[destinationStatus].filter((t) => t.id !== taskId);
      const oldIndex = sourceTasks.findIndex((t) => t.id === taskId);
      const newIndex = destinationTasks.findIndex((t) => t.id === targetId);

      const movedTask: Task = { ...task, status: destinationStatus };
      const updatedDestination = arrayMove(
        [...grouped[destinationStatus]],
        oldIndex >= 0 ? oldIndex : 0,
        newIndex >= 0 ? newIndex : 0
      );

      const nextTasks = state.tasks.map((t) => {
        if (t.id === taskId) return movedTask;
        return t;
      });

      const reordered = nextTasks.map((t) => t);
      const merged: Task[] = [];

      (["todo", "inprogress", "done"] as TaskStatus[]).forEach((status) => {
        const items = status === destinationStatus ? updatedDestination : grouped[status];
        items.forEach((item, index) => {
          merged.push({ ...item, status, order: index });
        });
      });

      setState({ tasks: merged });
      void fetch("http://localhost:3001/api/tasks/" + taskId, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: destinationStatus, order: newIndex >= 0 ? newIndex : 0 })
      });
      return;
    }

    if (targetColumn) {
      const destinationStatus = targetColumn.id;
      setState((prev) => {
        const tasks = prev.tasks.map((t) =>
          t.id === taskId ? { ...t, status: destinationStatus } : t
        );
        return { tasks };
      });

      void fetch("http://localhost:3001/api/tasks/" + taskId, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: destinationStatus, order: grouped[destinationStatus].length })
      });
    }
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>

        <form className="new-task-form" onSubmit={addTask}>
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Description"
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {columns.map((column) => (
            <BoardColumn
              key={column.id}
              id={column.id}
              title={column.title}
              tasks={grouped[column.id]}
              activeTaskId={activeTaskId}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function BoardColumn({
  id,
  title,
  tasks,
  activeTaskId
}: {
  id: TaskStatus;
  title: string;
  tasks: Task[];
  activeTaskId: string | null;
}) {
  return (
    <div className="column" id={id}>
      <h2>{title}</h2>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" id={id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} active={task.id === activeTaskId} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function TaskCard({ task, active }: { task: Task; active: boolean }) {
  return (
    <div className={`task-card ${active ? "active" : ""}`}>
      <strong>{task.title}</strong>
      {task.description && <p>{task.description}</p>}
      <small>Updated {new Date(task.updatedAt).toLocaleTimeString()}</small>
    </div>
  );
}
