## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { boardState, resetBoard, Task } from "./state";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/reset", (_req, res) => {
  resetBoard();
  io.emit("board:update", boardState);
  res.json({ ok: true, board: boardState });
});

app.post("/api/tasks", (req, res) => {
  const { title, status } = req.body as { title?: string; status?: string };
  if (!title || !status) {
    return res.status(400).json({ error: "title and status required" });
  }

  const task: Task = {
    id: `task-${Date.now()}`,
    title,
    status
  };

  boardState.tasks.push(task);
  io.emit("board:update", boardState);
  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = boardState.tasks.find((t) => t.id === id);
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, status } = req.body as Partial<Task>;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (status !== undefined) task.status = status;

  io.emit("board:update", boardState);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const before = boardState.tasks.length;
  boardState.tasks = boardState.tasks.filter((t) => t.id !== id);

  if (boardState.tasks.length === before) {
    return res.status(404).json({ error: "Task not found" });
  }

  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("board:move-task", (payload: { taskId: string; status: string }) => {
    const task = boardState.tasks.find((t) => t.id === payload.taskId);
    if (!task) return;

    task.status = payload.status;
    io.emit("board:update", boardState);
  });

  socket.on("task:create", (payload: { title: string; status: string }) => {
    const task: Task = {
      id: `task-${Date.now()}`,
      title: payload.title,
      status: payload.status
    };

    boardState.tasks.push(task);
    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

