```tsx
import { useMemo, useState } from "react";
import type { Board as BoardType, Task } from "./types";
import { DndContext, DragEndEvent, useDroppable, useDraggable } from "@dnd-kit/core";

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id
  });

  const style: React.CSSProperties = {
    transform: transform ? `translate(${transform.x}px, ${transform.y}px)` : undefined,
    opacity: isDragging ? 0.5 : 1,
    background: "white",
    padding: "12px",
    marginBottom: "8px",
    borderRadius: "8px",
    boxShadow: "0 1px 5px rgba(0,0,0,0.12)",
    cursor: "grab"
  };

  return (
    <div ref={setNodeRef} style={style} {...listeners} {...attributes}>
      <strong>{task.title}</strong>
      {task.description ? <div>{task.description}</div> : null}
    </div>
  );
}

function Column({
  name,
  tasks
}: {
  name: string;
  tasks: Task[];
}) {
  const { setNodeRef, isOver } = useDroppable({
    id: name
  });

  return (
    <div
      ref={setNodeRef}
      style={{
        minWidth: 280,
        width: 280,
        background: isOver ? "#eef6ff" : "#f4f5f7",
        borderRadius: 12,
        padding: 12,
        marginRight: 12,
        minHeight: 500
      }}
    >
      <h3>{name}</h3>
      {tasks.map((task) => (
        <TaskCard key={task.id} task={task} />
      ))}
    </div>
  );
}

export function Board({
  board,
  onMoveTask
}: {
  board: BoardType;
  onMoveTask: (taskId: string, status: string) => void;
}) {
  const tasksByColumn = useMemo(() => {
    return Object.fromEntries(
      board.columns.map((col) => [col, board.tasks.filter((task) => task.status === col)])
    );
  }, [board]);

  function onDragEnd(event: DragEndEvent) {
    const taskId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId) return;
    if (!board.columns.includes(overId)) return;

    onMoveTask(taskId, overId);
  }

  return (
    <DndContext onDragEnd={onDragEnd}>
      <div style={{ display: "flex", alignItems: "flex-start", overflowX: "auto" }}>
        {board.columns.map((col) => (
          <Column key={col} name={col} tasks={tasksByColumn[col] ?? []} />
        ))}
      </div>
    </DndContext>
  );
}
