```tsx
import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import type { Board } from "./types";
import { Board as BoardView } from "./Board";
import { createTask, fetchBoard } from "./api";

const socket = io("http://localhost:3001");

export default function App() {
  const [board, setBoard] = useState<Board | null>(null);
  const [title, setTitle] = useState("");
  const [status, setStatus] = useState("Todo");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBoard()
      .then(setBoard)
      .catch((err) => setError(err.message));

    socket.on("board:update", (updatedBoard: Board) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  async function handleAddTask() {
    if (!title.trim()) return;

    try {
      await createTask(title, status);
      setTitle("");
      setStatus("Todo");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to add task");
    }
  }

  function handleMoveTask(taskId: string, newStatus: string) {
    socket.emit("board:move-task", { taskId, status: newStatus });
  }

  return (
    <div style={{ fontFamily: "Arial, sans-serif", padding: 20 }}>
      <h1>Project Manager</h1>

      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="New task title"
        />
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          {board?.columns.map((col) => (
            <option key={col} value={col}>
              {col}
            </option>
          ))}
        </select>
        <button onClick={handleAddTask}>Add Task</button>
      </div>

      {error ? <div style={{ color: "red" }}>{error}</div> : null}

      {board ? (
        <BoardView board={board} onMoveTask={handleMoveTask} />
      ) : (
        <div>Loading board...</div>
      )}
    </div>
  );
}
