### `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initialState, BoardState } from "./state.js";

const app = express();
app.use(cors());
app.use(express.json());

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { title, columnId } = req.body as { title: string; columnId: string };

  if (!title || !columnId || !boardState.columns[columnId]) {
    return res.status(400).json({ error: "Invalid task data" });
  }

  const id = `task-${Date.now()}`;
  const task = { id, title, columnId };

  boardState.tasks[id] = task;
  boardState.columns[columnId].taskIds.push(id);

  io.emit("board:update", boardState);
  res.status(201).json(task);
});

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*"
  }
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("board:move-task", (payload: {
    taskId: string;
    sourceColumnId: string;
    destinationColumnId: string;
    sourceIndex: number;
    destinationIndex: number;
  }) => {
    const { taskId, sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = payload;

    const sourceColumn = boardState.columns[sourceColumnId];
    const destColumn = boardState.columns[destinationColumnId];
    const task = boardState.tasks[taskId];

    if (!sourceColumn || !destColumn || !task) return;

    sourceColumn.taskIds.splice(sourceIndex, 1);

    if (sourceColumnId === destinationColumnId) {
      sourceColumn.taskIds.splice(destinationIndex, 0, taskId);
    } else {
      destColumn.taskIds.splice(destinationIndex, 0, taskId);
      task.columnId = destinationColumnId;
    }

    io.emit("board:update", boardState);
  });
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

