```tsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import type { BoardState } from "./types";

const socket = io("http://localhost:3001");

function App() {
  const [board, setBoard] = useState<BoardState | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    socket.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(useSensor(PointerSensor));

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => board.columns[columnId]);
  }, [board]);

  function handleDragEnd(event: DragEndEvent) {
    if (!board) return;

    const activeId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;

    if (!overId) return;

    const sourceColumnId = board.tasks[activeId]?.columnId;
    const destinationColumnId = board.columns[overId]
      ? overId
      : board.tasks[overId]?.columnId;

    if (!sourceColumnId || !destinationColumnId) return;

    const sourceColumn = board.columns[sourceColumnId];
    const destinationColumn = board.columns[destinationColumnId];

    const sourceIndex = sourceColumn.taskIds.indexOf(activeId);
    const destinationIndex = board.columns[overId]
      ? destinationColumn.taskIds.length
      : destinationColumn.taskIds.indexOf(overId);

    socket.emit("board:move-task", {
      taskId: activeId,
      sourceColumnId,
      destinationColumnId,
      sourceIndex,
      destinationIndex: destinationIndex < 0 ? destinationColumn.taskIds.length : destinationIndex
    });
  }

  async function createTask() {
    if (!newTaskTitle.trim()) return;

    await fetch("http://localhost:3001/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTaskTitle,
        columnId: "todo"
      })
    });

    setNewTaskTitle("");
  }

  if (!board) return <div style={{ padding: 24 }}>Loading board...</div>;

  return (
    <div style={{ padding: 24, fontFamily: "sans-serif" }}>
      <h1>Project Manager</h1>

      <div style={{ marginBottom: 16, display: "flex", gap: 8 }}>
        <input
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="New task title"
          style={{ padding: 8, width: 300 }}
        />
        <button onClick={createTask}>Add Task</button>
      </div>

      <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
        <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
          {columns.map((column) => (
            <ColumnView
              key={column.id}
              column={column}
              tasks={column.taskIds.map((taskId) => board.tasks[taskId])}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function ColumnView({
  column,
  tasks
}: {
  column: { id: string; title: string };
  tasks: { id: string; title: string }[];
}) {
  return (
    <div
      style={{
        minWidth: 280,
        background: "#f4f5f7",
        borderRadius: 8,
        padding: 12,
        minHeight: 400
      }}
    >
      <h2 style={{ marginTop: 0 }}>{column.title}</h2>

      <div
        id={column.id}
        style={{ display: "flex", flexDirection: "column", gap: 8 }}
      >
        {tasks.map((task) => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>
    </div>
  );
}

import { useDraggable } from "@dnd-kit/core";

function TaskCard({ task }: { task: { id: string; title: string } }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id
  });

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      style={{
        background: "white",
        borderRadius: 6,
        padding: 12,
        boxShadow: "0 1px 3px rgba(0,0,0,0.12)",
        cursor: "grab",
        opacity: isDragging ? 0.5 : 1,
        transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined
      }}
    >
      {task.title}
    </div>
  );
}

export default App;
```

