## 3) `server.js`

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static('public'));

let board = {
  todo: [
    { id: '1', text: 'Set up project' },
    { id: '2', text: 'Design UI' }
  ],
  doing: [
    { id: '3', text: 'Implement drag-and-drop' }
  ],
  done: [
    { id: '4', text: 'Create repo' }
  ]
};

function broadcast() {
  const message = JSON.stringify({ type: 'board-update', board });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on('connection', (ws) => {
  ws.send(JSON.stringify({ type: 'board-update', board }));

  ws.on('message', (data) => {
    try {
      const msg = JSON.parse(data);

      if (msg.type === 'move-task') {
        const { taskId, fromColumn, toColumn, toIndex } = msg;

        const taskIndex = board[fromColumn].findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = board[fromColumn].splice(taskIndex, 1);

        if (toIndex >= board[toColumn].length) {
          board[toColumn].push(task);
        } else {
          board[toColumn].splice(toIndex, 0, task);
        }

        broadcast();
      }

      if (msg.type === 'add-task') {
        const { column, text } = msg;
        const newTask = {
          id: Date.now().toString(),
          text
        };
        board[column].push(newTask);
        broadcast();
      }
    } catch (err) {
      console.error('Invalid message:', err);
    }
  });
});

server.listen(3000, () => {
  console.log('Server running at http://localhost:3000');
});
```

