## 6) `public/app.js`

```javascript
const boardEl = document.getElementById('board');
const ws = new WebSocket(`ws://${location.host}`);

let boardState = {};
let draggedTask = null;

const columns = ['todo', 'doing', 'done'];

function renderBoard() {
  boardEl.innerHTML = '';

  columns.forEach((columnName) => {
    const column = document.createElement('div');
    column.className = 'column';

    const title = document.createElement('h2');
    title.textContent = columnName;

    const form = document.createElement('div');
    form.className = 'add-task';

    const input = document.createElement('input');
    input.type = 'text';
    input.placeholder = `Add task to ${columnName}`;

    const button = document.createElement('button');
    button.textContent = 'Add';

    button.addEventListener('click', () => {
      const text = input.value.trim();
      if (!text) return;

      ws.send(JSON.stringify({
        type: 'add-task',
        column: columnName,
        text
      }));

      input.value = '';
    });

    form.appendChild(input);
    form.appendChild(button);

    const taskList = document.createElement('div');
    taskList.className = 'task-list';
    taskList.dataset.column = columnName;

    taskList.addEventListener('dragover', (e) => {
      e.preventDefault();
      taskList.classList.add('drag-over');
    });

    taskList.addEventListener('dragleave', () => {
      taskList.classList.remove('drag-over');
    });

    taskList.addEventListener('drop', (e) => {
      e.preventDefault();
      taskList.classList.remove('drag-over');

      if (!draggedTask) return;

      const targetColumn = columnName;
      const toIndex = boardState[targetColumn].length;

      ws.send(JSON.stringify({
        type: 'move-task',
        taskId: draggedTask.id,
        fromColumn: draggedTask.column,
        toColumn: targetColumn,
        toIndex
      }));

      draggedTask = null;
    });

    (boardState[columnName] || []).forEach((task) => {
      const taskEl = document.createElement('div');
      taskEl.className = 'task';
      taskEl.draggable = true;
      taskEl.textContent = task.text;

      taskEl.addEventListener('dragstart', () => {
        draggedTask = { id: task.id, column: columnName };
      });

      taskList.appendChild(taskEl);
    });

    column.appendChild(title);
    column.appendChild(form);
    column.appendChild(taskList);
    boardEl.appendChild(column);
  });
}

ws.addEventListener('open', () => {
  console.log('Connected to real-time server');
});

ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === 'board-update') {
    boardState = msg.board;
    renderBoard();
  }
});

ws.addEventListener('close', () => {
  console.log('WebSocket disconnected');
});
```

