# 2) Server: `server.js`

This uses Express and WebSocket.

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let board = {
  todo: [
    { id: "1", title: "Set up project" },
    { id: "2", title: "Design task board" }
  ],
  doing: [
    { id: "3", title: "Implement drag and drop" }
  ],
  done: [
    { id: "4", title: "Create UI layout" }
  ]
};

function broadcast() {
  const message = JSON.stringify({ type: "board-update", board });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "board-update", board }));

  ws.on("message", (data) => {
    try {
      const msg = JSON.parse(data.toString());

      if (msg.type === "move-task") {
        const { taskId, fromColumn, toColumn, toIndex } = msg;

        const sourceList = board[fromColumn];
        const targetList = board[toColumn];

        const taskIndex = sourceList.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = sourceList.splice(taskIndex, 1);

        if (typeof toIndex === "number") {
          targetList.splice(toIndex, 0, task);
        } else {
          targetList.push(task);
        }

        broadcast();
      }

      if (msg.type === "add-task") {
        const { column, title } = msg;
        if (!title || !board[column]) return;

        board[column].push({
          id: String(Date.now()),
          title
        });

        broadcast();
      }
    } catch (err) {
      console.error("Bad message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

