# 5) Frontend logic: `public/app.ts`

```ts
type ColumnId = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
};

type Board = Record<ColumnId, Task[]>;

const ws = new WebSocket(`ws://${location.host}`);

let board: Board = {
  todo: [],
  doing: [],
  done: []
};

const boardEl = document.getElementById("board") as HTMLElement;
const addTaskForm = document.getElementById("addTaskForm") as HTMLFormElement;
const taskTitleInput = document.getElementById("taskTitle") as HTMLInputElement;
const taskColumnSelect = document.getElementById("taskColumn") as HTMLSelectElement;

function renderBoard() {
  document.querySelectorAll(".column").forEach((columnEl) => {
    const columnId = columnEl.getAttribute("data-column") as ColumnId;
    const listEl = columnEl.querySelector(".task-list") as HTMLElement;

    listEl.innerHTML = "";

    board[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.column = columnId;
      taskEl.dataset.index = String(index);

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer?.setData("text/plain", JSON.stringify({
          taskId: task.id,
          fromColumn: columnId
        }));
      });

      listEl.appendChild(taskEl);
    });
  });
}

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === "board-update") {
    board = msg.board;
    renderBoard();
  }
});

ws.addEventListener("open", () => {
  console.log("Connected to collaboration server");
});

document.querySelectorAll(".column").forEach((columnEl) => {
  columnEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  columnEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  columnEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    const data = e.dataTransfer?.getData("text/plain");
    if (!data) return;

    const { taskId, fromColumn } = JSON.parse(data);
    const toColumn = columnEl.getAttribute("data-column") as ColumnId;

    ws.send(JSON.stringify({
      type: "move-task",
      taskId,
      fromColumn,
      toColumn
    }));
  });
});

addTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const column = taskColumnSelect.value as ColumnId;

  if (!title) return;

  ws.send(JSON.stringify({
    type: "add-task",
    title,
    column
  }));

  taskTitleInput.value = "";
});
```

