## 3. `server.js`

This serves the frontend and broadcasts task updates to all connected clients.

```js
import express from "express";
import http from "http";
import { WebSocketServer } from "ws";

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.static("public"));

// In-memory shared state
let board = {
  todo: [
    { id: "1", title: "Set up project" },
    { id: "2", title: "Design board UI" }
  ],
  doing: [
    { id: "3", title: "Build drag and drop" }
  ],
  done: []
};

function broadcastState() {
  const message = JSON.stringify({
    type: "state",
    board
  });

  for (const client of wss.clients) {
    if (client.readyState === client.OPEN) {
      client.send(message);
    }
  }
}

wss.on("connection", (ws) => {
  // Send current state on connect
  ws.send(JSON.stringify({ type: "state", board }));

  ws.on("message", (raw) => {
    let msg;
    try {
      msg = JSON.parse(raw.toString());
    } catch {
      return;
    }

    if (msg.type === "move-task") {
      const { taskId, from, to, toIndex } = msg;

      const fromList = board[from];
      const toList = board[to];
      if (!fromList || !toList) return;

      const taskIndex = fromList.findIndex((t) => t.id === taskId);
      if (taskIndex === -1) return;

      const [task] = fromList.splice(taskIndex, 1);
      const insertAt = Number.isInteger(toIndex) ? toIndex : toList.length;
      toList.splice(insertAt, 0, task);

      broadcastState();
    }

    if (msg.type === "add-task") {
      const { column, title } = msg;
      if (!board[column] || !title?.trim()) return;

      board[column].push({
        id: crypto.randomUUID(),
        title: title.trim()
      });

      broadcastState();
    }
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

