## 6. `public/app.js`

```js
const statusEl = document.getElementById("status");
const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

const ws = new WebSocket(`ws://${location.host}`);

let state = {
  todo: [],
  doing: [],
  done: []
};

const columns = [
  { key: "todo", label: "To Do" },
  { key: "doing", label: "Doing" },
  { key: "done", label: "Done" }
];

function render() {
  boardEl.innerHTML = "";

  for (const col of columns) {
    const clone = columnTemplate.content.cloneNode(true);
    const section = clone.querySelector(".column");
    const title = clone.querySelector("h2");
    const form = clone.querySelector(".add-form");
    const input = clone.querySelector("input");
    const taskList = clone.querySelector(".task-list");

    title.textContent = col.label;

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const value = input.value.trim();
      if (!value) return;

      ws.send(
        JSON.stringify({
          type: "add-task",
          column: col.key,
          title: value
        })
      );

      input.value = "";
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      const taskId = e.dataTransfer.getData("text/plain");
      const from = e.dataTransfer.getData("from-column");
      const to = col.key;

      if (!taskId || !from || !to) return;

      ws.send(
        JSON.stringify({
          type: "move-task",
          taskId,
          from,
          to
        })
      );
    });

    for (const task of state[col.key]) {
      const taskClone = taskTemplate.content.cloneNode(true);
      const taskEl = taskClone.querySelector(".task");
      taskEl.textContent = task.title;
      taskEl.dataset.id = task.id;
      taskEl.draggable = true;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", task.id);
        e.dataTransfer.setData("from-column", col.key);
      });

      taskList.appendChild(taskClone);
    }

    boardEl.appendChild(clone);
  }
}

ws.addEventListener("open", () => {
  statusEl.textContent = "Connected";
});

ws.addEventListener("close", () => {
  statusEl.textContent = "Disconnected";
});

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === "state") {
    state = msg.board;
    render();
  }
});
```

