```ts
export type Task = {
  id: string;
  title: string;
};

export type BoardState = {
  todo: Task[];
  doing: Task[];
  done: Task[];
};

export const initialBoard: BoardState = {
  todo: [],
  doing: [],
  done: []
};

export function moveTask(
  board: BoardState,
  taskId: string,
  from: keyof BoardState,
  to: keyof BoardState
): BoardState {
  if (from === to) return board;

  const task = board[from].find((t) => t.id === taskId);
  if (!task) return board;

  return {
    ...board,
    [from]: board[from].filter((t) => t.id !== taskId),
    [to]: [...board[to], task]
  };
