## 4) server.ts

```ts
import express from "express";
import http from "http";
import { WebSocketServer } from "ws";

type Status = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  status: Status;
};

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.static("public"));

let tasks: Task[] = [
  { id: "1", title: "Design board layout", status: "todo" },
  { id: "2", title: "Set up WebSocket sync", status: "doing" },
  { id: "3", title: "Add drag and drop", status: "done" }
];

function broadcast() {
  const message = JSON.stringify({ type: "state", tasks });
  wss.clients.forEach((client) => {
    if (client.readyState === client.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", tasks }));

  ws.on("message", (data) => {
    try {
      const msg = JSON.parse(data.toString());

      if (msg.type === "move-task") {
        const { taskId, status } = msg;
        const task = tasks.find((t) => t.id === taskId);
        if (task && (status === "todo" || status === "doing" || status === "done")) {
          task.status = status;
          broadcast();
        }
      }

      if (msg.type === "add-task") {
        const title = String(msg.title || "").trim();
        if (title) {
          tasks.push({
            id: crypto.randomUUID(),
            title,
            status: "todo"
          });
          broadcast();
        }
      }
    } catch {
      // ignore invalid messages
    }
  });
});

server.listen(3000, () => {
  console.log("Running on http://localhost:3000");
});
```

