## 7) public/client.ts

```ts
type Status = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  status: Status;
};

const ws = new WebSocket(`ws://${location.host}`);
const statusEl = document.getElementById("status")!;
const form = document.getElementById("task-form") as HTMLFormElement;
const input = document.getElementById("task-input") as HTMLInputElement;

const columns: Record<Status, HTMLElement> = {
  todo: document.getElementById("todo")!,
  doing: document.getElementById("doing")!,
  done: document.getElementById("done")!
};

let currentTasks: Task[] = [];

ws.addEventListener("open", () => {
  statusEl.textContent = "Connected";
});

ws.addEventListener("close", () => {
  statusEl.textContent = "Disconnected";
});

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === "state") {
    currentTasks = msg.tasks;
    render();
  }
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = input.value.trim();
  if (!title) return;

  ws.send(JSON.stringify({ type: "add-task", title }));
  input.value = "";
});

function render() {
  for (const key of Object.keys(columns) as Status[]) {
    columns[key].innerHTML = "";
  }

  for (const task of currentTasks) {
    const el = document.createElement("div");
    el.className = "task";
    el.draggable = true;
    el.textContent = task.title;
    el.dataset.id = task.id;

    el.addEventListener("dragstart", (e) => {
      e.dataTransfer?.setData("text/plain", task.id);
    });

    columns[task.status].appendChild(el);
  }
}

for (const column of document.querySelectorAll(".column")) {
  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("dragover");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("dragover");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("dragover");

    const taskId = e.dataTransfer?.getData("text/plain");
    const status = column.getAttribute("data-status") as Status;

    if (taskId && status) {
      ws.send(JSON.stringify({ type: "move-task", taskId, status }));
    }
  });
}
```

