package trading;

import java.util.Comparator;
import java.util.PriorityQueue;

public final class OrderBook {
    // Highest buy price first, then earlier timestamp
    private final PriorityQueue<Order> bids = new PriorityQueue<>(
            Comparator.<Order>comparingLong(o -> -o.limitPrice)
                    .thenComparingLong(o -> o.timestampNanos)
    );

    // Lowest sell price first, then earlier timestamp
    private final PriorityQueue<Order> asks = new PriorityQueue<>(
            Comparator.<Order>comparingLong(o -> o.limitPrice)
                    .thenComparingLong(o -> o.timestampNanos)
    );

    public PriorityQueue<Order> bids() {
        return bids;
    }

    public PriorityQueue<Order> asks() {
        return asks;
    }
}
