### `MatchingEngine.java`
```java
package trading;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public final class MatchingEngine {
    private final Map<String, OrderBook> books = new ConcurrentHashMap<>();
    private final ExecutionListener executionListener;
    private final InMemoryJournal journal;

    public MatchingEngine(ExecutionListener executionListener, InMemoryJournal journal) {
        this.executionListener = executionListener;
        this.journal = journal;
    }

    private OrderBook bookFor(String symbol) {
        return books.computeIfAbsent(symbol, s -> new OrderBook());
    }

    public void submit(Order order) {
        journal.append("ORDER_SUBMITTED " + order.id + " " + order.symbol);

        OrderBook book = bookFor(order.symbol);

        synchronized (book) {
            if (order.side == OrderSide.BUY) {
                matchBuy(order, book);
                if (order.quantity > 0 && order.type == OrderType.LIMIT) {
                    book.bids().add(orderWithRemaining(order));
                }
            } else {
                matchSell(order, book);
                if (order.quantity > 0 && order.type == OrderType.LIMIT) {
                    book.asks().add(orderWithRemaining(order));
                }
            }
        }
    }

    private void matchBuy(Order incoming, OrderBook book) {
        while (incoming.quantity > 0 && !book.asks().isEmpty()) {
            Order bestAsk = book.asks().peek();

            if (incoming.type == OrderType.LIMIT && bestAsk.limitPrice > incoming.limitPrice) {
                break;
            }

            long qty = Math.min(incoming.quantity, bestAsk.quantity);
            long tradePrice = bestAsk.limitPrice;

            Trade trade = new Trade(incoming.id, bestAsk.id, incoming.symbol, qty, tradePrice);
            executionListener.onTrade(trade);
            journal.append("TRADE " + trade.buyOrderId + " " + trade.sellOrderId + " " + trade.quantity + "@" + trade.price);

            reduceOrder(incoming, qty);
            reduceOrder(bestAsk, qty);

            if (bestAsk.quantity == 0) {
                book.asks().poll();
            }
        }
    }

    private void matchSell(Order incoming, OrderBook book) {
        while (incoming.quantity > 0 && !book.bids().isEmpty()) {
            Order bestBid = book.bids().peek();

            if (incoming.type == OrderType.LIMIT && bestBid.limitPrice < incoming.limitPrice) {
                break;
            }

            long qty = Math.min(incoming.quantity, bestBid.quantity);
            long tradePrice = bestBid.limitPrice;

            Trade trade = new Trade(bestBid.id, incoming.id, incoming.symbol, qty, tradePrice);
            executionListener.onTrade(trade);
            journal.append("TRADE " + trade.buyOrderId + " " + trade.sellOrderId + " " + trade.quantity + "@" + trade.price);

            reduceOrder(incoming, qty);
            reduceOrder(bestBid, qty);

            if (bestBid.quantity == 0) {
                book.bids().poll();
            }
        }
    }

    private void reduceOrder(Order order, long qty) {
        // Since Order is immutable in this simple example, you’d normally use a mutable order record/state object.
        // In production, replace Order with a mutable internal representation for remaining quantity.
    }

    private Order orderWithRemaining(Order order) {
        return order;
    }
}
```

