## Rust starter skeleton

```rust
use std::sync::mpsc::{channel, Sender, Receiver};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
pub struct MarketTick {
    pub symbol: String,
    pub bid: f64,
    pub ask: f64,
    pub ts: Instant,
}

#[derive(Debug, Clone)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
pub struct OrderRequest {
    pub symbol: String,
    pub side: Side,
    pub qty: u64,
    pub price: f64,
}

#[derive(Debug, Clone)]
pub struct OrderAck {
    pub order_id: u64,
    pub accepted: bool,
    pub reason: Option<String>,
}

#[derive(Debug, Clone)]
pub struct Position {
    pub symbol: String,
    pub qty: i64,
}

pub struct RiskManager {
    max_order_qty: u64,
    max_position: i64,
}

impl RiskManager {
    pub fn new(max_order_qty: u64, max_position: i64) -> Self {
        Self {
            max_order_qty,
            max_position,
        }
    }

    pub fn validate_order(&self, order: &OrderRequest, current_pos: i64) -> Result<(), String> {
        if order.qty == 0 {
            return Err("order qty must be > 0".into());
        }
        if order.qty > self.max_order_qty {
            return Err(format!("order qty exceeds limit: {}", self.max_order_qty));
        }

        let projected = match order.side {
            Side::Buy => current_pos.saturating_add(order.qty as i64),
            Side::Sell => current_pos.saturating_sub(order.qty as i64),
        };

        if projected.abs() > self.max_position {
            return Err(format!("projected position exceeds limit: {}", self.max_position));
        }

        Ok(())
    }
}

pub struct OrderManager {
    next_order_id: u64,
}

impl OrderManager {
    pub fn new() -> Self {
        Self { next_order_id: 1 }
    }

    pub fn submit(&mut self, order: OrderRequest) -> OrderAck {
        let id = self.next_order_id;
        self.next_order_id += 1;

        // In a real system this would hand off to an exchange adapter / gateway.
        OrderAck {
            order_id: id,
            accepted: true,
            reason: None,
        }
    }
}

pub trait Strategy: Send {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest>;
}

pub struct SimpleMeanReversionStrategy {
    symbol: String,
    fair_value: f64,
    threshold: f64,
    order_qty: u64,
}

impl SimpleMeanReversionStrategy {
    pub fn new(symbol: &str, fair_value: f64, threshold: f64, order_qty: u64) -> Self {
        Self {
            symbol: symbol.to_string(),
            fair_value,
            threshold,
            order_qty,
        }
    }
}

impl Strategy for SimpleMeanReversionStrategy {
    fn on_tick(&mut self, tick: &MarketTick) -> Option<OrderRequest> {
        if tick.symbol != self.symbol {
            return None;
        }

        let mid = (tick.bid + tick.ask) / 2.0;

        if mid < self.fair_value - self.threshold {
            Some(OrderRequest {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                price: tick.ask,
            })
        } else if mid > self.fair_value + self.threshold {
            Some(OrderRequest {
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: self.order_qty,
                price: tick.bid,
            })
        } else {
            None
        }
    }
}

pub struct Engine {
    market_rx: Receiver<MarketTick>,
    risk: RiskManager,
    order_manager: OrderManager,
    strategy: Box<dyn Strategy>,
    positions: std::collections::HashMap<String, i64>,
}

impl Engine {
    pub fn new(
        market_rx: Receiver<MarketTick>,
        strategy: Box<dyn Strategy>,
        risk: RiskManager,
        order_manager: OrderManager,
    ) -> Self {
        Self {
            market_rx,
            risk,
            order_manager,
            strategy,
            positions: std::collections::HashMap::new(),
        }
    }

    pub fn run(&mut self) {
        while let Ok(tick) = self.market_rx.recv() {
            if let Some(order) = self.strategy.on_tick(&tick) {
                let current_pos = *self.positions.get(&order.symbol).unwrap_or(&0);

                match self.risk.validate_order(&order, current_pos) {
                    Ok(_) => {
                        let ack = self.order_manager.submit(order.clone());
                        if ack.accepted {
                            let pos = self.positions.entry(order.symbol.clone()).or_insert(0);
                            match order.side {
                                Side::Buy => *pos += order.qty as i64,
                                Side::Sell => *pos -= order.qty as i64,
                            }
                        }
                        println!("order ack: {:?}", ack);
                    }
                    Err(reason) => {
                        println!("risk reject: {} | order={:?}", reason, order);
                    }
                }
            }
        }
    }
}

fn market_data_publisher(tx: Sender<MarketTick>) {
    thread::spawn(move || {
        let mut px = 100.0;
        loop {
            px += 0.1;
            let tick = MarketTick {
                symbol: "AAPL".to_string(),
                bid: px - 0.01,
                ask: px + 0.01,
                ts: Instant::now(),
            };

            if tx.send(tick).is_err() {
                break;
            }

            thread::sleep(Duration::from_millis(50));
        }
    });
}

fn main() {
    let (tx, rx) = channel::<MarketTick>();
    market_data_publisher(tx);

    let strategy = Box::new(SimpleMeanReversionStrategy::new("AAPL", 100.0, 0.20, 10));
    let risk = RiskManager::new(100, 500);
    let order_manager = OrderManager::new();

    let mut engine = Engine::new(rx, strategy, risk, order_manager);
    engine.run();
}
```

