```rust
mod bus;
mod execution;
mod market_data;
mod order_manager;
mod risk;
mod strategy;
mod types;

use tracing::{info, Level};
use tracing_subscriber::FmtSubscriber;

use crate::execution::ExecutionConnector;
use crate::market_data::MarketDataFeed;
use crate::risk::RiskManager;
use crate::strategy::Strategy;

fn now_ns() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn main() {
    let subscriber = FmtSubscriber::builder()
        .with_max_level(Level::INFO)
        .finish();
    let _ = tracing::subscriber::set_global_default(subscriber);

    let feed = MarketDataFeed::new();
    let mut strategy = Strategy::new();
    let risk = RiskManager::new(100);
    let exec = ExecutionConnector::new();
    let mut order_manager = crate::order_manager::OrderManager::new();

    let ticks = vec![
        feed.parse_tick(1, 1000, 1015, now_ns()),
        feed.parse_tick(1, 1001, 1005, now_ns()),
        feed.parse_tick(2, 2000, 2020, now_ns()),
    ];

    for tick in ticks {
        info!("tick received: {:?}", tick);

        if let Some(order) = strategy.on_tick(tick) {
            info!("strategy created order: {:?}", order);

            if risk.approve(&order) {
                order_manager.submit(order);

                let report = exec.send_order(order, now_ns());
                info!("execution report: {:?}", report);

                order_manager.on_execution(report);
            } else {
                info!("order rejected by risk");
            }
        }
    }

    info!("open orders: {}", order_manager.open_order_count());
}
```

