```rust
use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
struct Order {
    id: u64,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
}

#[derive(Debug)]
struct Trade {
    buy_order_id: u64,
    sell_order_id: u64,
    symbol: String,
    qty: u64,
    price: f64,
    timestamp_ms: u128,
}

struct OrderBook {
    buys: VecDeque<Order>,
    sells: VecDeque<Order>,
}

impl OrderBook {
    fn new() -> Self {
        Self {
            buys: VecDeque::new(),
            sells: VecDeque::new(),
        }
    }

    fn add_order(&mut self, order: Order) -> Vec<Trade> {
        let mut trades = Vec::new();

        match order.side {
            Side::Buy => {
                let mut incoming = order;
                while incoming.qty > 0 {
                    if let Some(mut best_sell) = self.sells.pop_front() {
                        if best_sell.symbol != incoming.symbol || best_sell.price > incoming.price {
                            self.sells.push_front(best_sell);
                            break;
                        }

                        let matched_qty = incoming.qty.min(best_sell.qty);
                        incoming.qty -= matched_qty;
                        best_sell.qty -= matched_qty;

                        trades.push(Trade {
                            buy_order_id: incoming.id,
                            sell_order_id: best_sell.id,
                            symbol: incoming.symbol.clone(),
                            qty: matched_qty,
                            price: best_sell.price,
                            timestamp_ms: Instant::now().elapsed().as_millis(),
                        });

                        if best_sell.qty > 0 {
                            self.sells.push_front(best_sell);
                        }
                    } else {
                        break;
                    }
                }

                if incoming.qty > 0 {
                    self.buys.push_back(incoming);
                }
            }
            Side::Sell => {
                let mut incoming = order;
                while incoming.qty > 0 {
                    if let Some(mut best_buy) = self.buys.pop_front() {
                        if best_buy.symbol != incoming.symbol || best_buy.price < incoming.price {
                            self.buys.push_front(best_buy);
                            break;
                        }

                        let matched_qty = incoming.qty.min(best_buy.qty);
                        incoming.qty -= matched_qty;
                        best_buy.qty -= matched_qty;

                        trades.push(Trade {
                            buy_order_id: best_buy.id,
                            sell_order_id: incoming.id,
                            symbol: incoming.symbol.clone(),
                            qty: matched_qty,
                            price: best_buy.price,
                            timestamp_ms: Instant::now().elapsed().as_millis(),
                        });

                        if best_buy.qty > 0 {
                            self.buys.push_front(best_buy);
                        }
                    } else {
                        break;
                    }
                }

                if incoming.qty > 0 {
                    self.sells.push_back(incoming);
                }
            }
        }

        trades
    }
}

struct Engine {
    book: Arc<Mutex<OrderBook>>,
}

impl Engine {
    fn new() -> Self {
        Self {
            book: Arc::new(Mutex::new(OrderBook::new())),
        }
    }

    fn submit_order(&self, order: Order) -> Vec<Trade> {
        let mut book = self.book.lock().unwrap();
        book.add_order(order)
    }
}

fn main() {
    let engine = Engine::new();

    let orders = vec![
        Order { id: 1, symbol: "XYZ".into(), side: Side::Buy, qty: 100, price: 10.50 },
        Order { id: 2, symbol: "XYZ".into(), side: Side::Sell, qty: 40, price: 10.40 },
        Order { id: 3, symbol: "XYZ".into(), side: Side::Sell, qty: 80, price: 10.55 },
        Order { id: 4, symbol: "XYZ".into(), side: Side::Buy, qty: 50, price: 10.60 },
    ];

    for order in orders {
        let trades = engine.submit_order(order.clone());
        println!("Submitted order: {:?}", order);
        for trade in trades {
            println!("Matched trade: {:?}", trade);
        }
    }

    thread::sleep(Duration::from_millis(10));
}
```

