## `risk/src/limits.rs`

```rust
use crate::checks::RiskError;
use common::types::{OrderRequest, Quantity};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Quantity,
    pub max_notional: i64,
    pub max_open_orders: usize,
}

#[derive(Debug)]
pub struct RiskState {
    pub open_orders: usize,
    pub current_notional: i64,
}

impl RiskState {
    pub fn new() -> Self {
        Self {
            open_orders: 0,
            current_notional: 0,
        }
    }
}

pub fn check_order(
    order: &OrderRequest,
    limits: &RiskLimits,
    state: &RiskState,
) -> Result<(), RiskError> {
    if order.qty <= 0 {
        return Err(RiskError::InvalidQuantity);
    }
    if order.qty > limits.max_order_qty {
        return Err(RiskError::OrderTooLarge);
    }

    let notional = order.price.saturating_mul(order.qty);
    if notional.abs() > limits.max_notional {
        return Err(RiskError::NotionalLimitExceeded);
    }

    if state.open_orders >= limits.max_open_orders {
        return Err(RiskError::TooManyOpenOrders);
    }

    Ok(())
}
```

