## `oms/src/state.rs`

```rust
use common::types::{FillEvent, OrderId, OrderRequest};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum OrderStatus {
    New,
    Sent,
    PartiallyFilled,
    Filled,
    Rejected,
    Cancelled,
}

#[derive(Debug, Clone)]
pub struct OrderState {
    pub request: OrderRequest,
    pub status: OrderStatus,
    pub filled_qty: i64,
}

pub struct OmsState {
    pub orders: HashMap<OrderId, OrderState>,
}

impl OmsState {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn register_order(&mut self, order: OrderRequest) {
        self.orders.insert(
            order.order_id,
            OrderState {
                request: order,
                status: OrderStatus::New,
                filled_qty: 0,
            },
        );
    }

    pub fn on_fill(&mut self, fill: FillEvent) {
        if let Some(order_state) = self.orders.get_mut(&fill.order_id) {
            order_state.filled_qty += fill.filled_qty;
            if order_state.filled_qty >= order_state.request.qty {
                order_state.status = OrderStatus::Filled;
            } else {
                order_state.status = OrderStatus::PartiallyFilled;
            }
        }
    }
}
```

