use common::types::{MarketDataEvent, OrderRequest};
use risk::{limits::{check_order, RiskLimits, RiskState}};
use strategy::example_strategy::ExampleStrategy;
use execution::gateway::ExecutionGateway;
use oms::state::OmsState;

pub struct TradingApp {
    strategy: ExampleStrategy,
    risk_limits: RiskLimits,
    risk_state: RiskState,
    gateway: ExecutionGateway,
    oms: OmsState,
    next_order_id: u64,
}

impl TradingApp {
    pub fn new() -> Self {
        Self {
            strategy: ExampleStrategy { threshold: 2 },
            risk_limits: RiskLimits {
                max_order_qty: 100,
                max_notional: 1_000_000,
                max_open_orders: 1000,
            },
            risk_state: RiskState::new(),
            gateway: ExecutionGateway::new(),
            oms: OmsState::new(),
            next_order_id: 1,
        }
    }

    pub fn on_market_data(&mut self, md: MarketDataEvent) {
        if let Some(signal) = self.strategy.on_market_data(&md) {
            let order = OrderRequest {
                order_id: self.next_order_id,
                instrument_id: signal.instrument_id,
                side: signal.side,
                price: signal.price,
                qty: signal.qty,
                ts_nanos: signal.ts_nanos,
            };
            self.next_order_id += 1;

            if let Err(e) = check_order(&order, &self.risk_limits, &self.risk_state) {
                eprintln!("risk rejected order {:?}: {:?}", order.order_id, e);
                return;
            }

            self.oms.register_order(order.clone());

            if let Err(e) = self.gateway.send_order(&order) {
                eprintln!("failed to send order {:?}: {}", order.order_id, e);
            }
        }
    }
}
