use crate::types::{OrderIntent, Side};

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
        }
    }

    pub fn validate(&self, order: &OrderIntent) -> bool {
        if order.qty <= 0.0 || order.qty > self.max_order_qty {
            return false;
        }

        let notional = order.qty * order.price;
        if notional > self.max_notional {
            return false;
        }

        match order.side {
            Side::Buy | Side::Sell => true,
        }
    }
}
