#[derive(Debug, thiserror::Error)]
pub enum RiskError {
    #[error("quantity exceeds limit")]
    QtyLimit,
    #[error("symbol not allowed")]
    SymbolNotAllowed,
    #[error("missing price for limit order")]
    MissingPrice,
}

pub struct RiskManager {
    config: Config,
}

impl RiskManager {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn check(&self, order: &Order) -> Result<(), RiskError> {
        if !self.config.allowed_symbols.iter().any(|s| s == &order.symbol) {
            return Err(RiskError::SymbolNotAllowed);
        }

        if order.quantity > self.config.max_order_qty {
            return Err(RiskError::QtyLimit);
        }

        if matches!(order.order_type, crate::model::OrderType::Limit) && order.price.is_none() {
            return Err(RiskError::MissingPrice);
        }

        Ok(())
    }
}
