```rust
use crate::model::{Fill, Order, OrderType, Side, MarketTick};

pub trait Exchange: Send + Sync {
    fn send_order(&self, order: &Order, tick: Option<&MarketTick>) -> Option<Fill>;
}

pub struct SimExchange;

impl Exchange for SimExchange {
    fn send_order(&self, order: &Order, tick: Option<&MarketTick>) -> Option<Fill> {
        match order.order_type {
            OrderType::Market => {
                let px = tick.map(|t| match order.side {
                    Side::Buy => t.ask,
                    Side::Sell => t.bid,
                })?;

                Some(Fill {
                    order_id: order.id,
                    symbol: order.symbol.clone(),
                    quantity: order.quantity,
                    price: px,
                })
            }
            OrderType::Limit => {
                let limit_px = order.price?;
                let tick = tick?;

                let executable = match order.side {
                    Side::Buy => tick.ask <= limit_px,
                    Side::Sell => tick.bid >= limit_px,
                };

                if executable {
                    let px = match order.side {
                        Side::Buy => tick.ask,
                        Side::Sell => tick.bid,
                    };

                    Some(Fill {
                        order_id: order.id,
                        symbol: order.symbol.clone(),
                        quantity: order.quantity,
                        price: px,
                    })
                } else {
                    None
                }
            }
        }
    }
}
