use std::collections::HashMap;

use crate::model::{MarketTick, Order};
use crate::risk::{RiskError, RiskManager};
use crate::exchange::Exchange;

#[derive(Debug, thiserror::Error)]
pub enum RouterError {
    #[error("risk rejected: {0}")]
    Risk(#[from] RiskError),
}

pub struct Router<E: Exchange> {
    risk: RiskManager,
    exchange: E,
    latest_ticks: HashMap<String, MarketTick>,
}

impl<E: Exchange> Router<E> {
    pub fn new(risk: RiskManager, exchange: E) -> Self {
        Self {
            risk,
            exchange,
            latest_ticks: HashMap::new(),
        }
    }

    pub fn on_tick(&mut self, tick: MarketTick) {
        self.latest_ticks.insert(tick.symbol.clone(), tick);
    }

    pub fn route(&self, order: &Order) -> Result<Option<crate::model::Fill>, RouterError> {
        self.risk.check(order)?;
        let tick = self.latest_ticks.get(&order.symbol);
        Ok(self.exchange.send_order(order, tick))
    }
}
