use crossbeam::channel::{Receiver, Sender};

use crate::model::{Fill, MarketTick, Order};
use crate::router::Router;

#[derive(Debug)]
pub enum EngineEvent {
    Tick(MarketTick),
    Order(Order),
}

#[derive(Debug)]
pub enum EngineOutput {
    Fill(Fill),
    Rejected(String),
}

pub struct Engine<E: crate::exchange::Exchange> {
    pub router: Router<E>,
    pub rx: Receiver<EngineEvent>,
    pub tx: Sender<EngineOutput>,
}

impl<E: crate::exchange::Exchange> Engine<E> {
    pub fn run(mut self) {
        while let Ok(event) = self.rx.recv() {
            match event {
                EngineEvent::Tick(tick) => self.router.on_tick(tick),
                EngineEvent::Order(order) => match self.router.route(&order) {
                    Ok(Some(fill)) => {
                        let _ = self.tx.send(EngineOutput::Fill(fill));
                    }
                    Ok(None) => {
                        let _ = self.tx.send(EngineOutput::Rejected(format!(
                            "not fillable now: order_id={}",
                            order.id
                        )));
                    }
                    Err(e) => {
                        let _ = self.tx.send(EngineOutput::Rejected(e.to_string()));
                    }
                },
            }
        }
    }
}
