use crossbeam_channel::{unbounded, Receiver, Sender};
use serde::{Deserialize, Serialize};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketTick {
    symbol: String,
    bid: f64,
    ask: f64,
    ts_nanos: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OrderRequest {
    symbol: String,
    side: Side,
    qty: u32,
    price: f64,
    ts_nanos: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OrderAck {
    order_id: u64,
    accepted: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OrderFill {
    order_id: u64,
    filled_qty: u32,
    fill_price: f64,
}

#[derive(Debug, Clone)]
enum Event {
    Tick(MarketTick),
    OrderIntent(OrderRequest),
    Ack(OrderAck),
    Fill(OrderFill),
    RiskReject(OrderRequest, String),
}

fn now_nanos() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

struct Strategy {
    threshold: f64,
}

impl Strategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderRequest> {
        let spread = tick.ask - tick.bid;

        // Simple example:
        // If spread is below threshold, place a buy order at bid.
        if spread < self.threshold {
            Some(OrderRequest {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 10,
                price: tick.bid,
                ts_nanos: now_nanos(),
            })
        } else {
            None
        }
    }
}

struct RiskManager {
    max_order_qty: u32,
}

impl RiskManager {
    fn check(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty > self.max_order_qty {
            Err(format!("qty {} exceeds max {}", order.qty, self.max_order_qty))
        } else {
            Ok(())
        }
    }
}

struct OrderManager {
    next_order_id: u64,
}

impl OrderManager {
    fn send_order(&mut self, order: &OrderRequest) -> OrderAck {
        self.next_order_id += 1;

        // In real life, this would call a broker/exchange adapter.
        OrderAck {
            order_id: self.next_order_id,
            accepted: true,
        }
    }
}

fn market_data_feed(tx: Sender<Event>) {
    let symbols = vec!["AAPL", "MSFT", "NVDA"];

    loop {
        for s in &symbols {
            let base = 100.0;
            let bid = base + rand_offset();
            let ask = bid + 0.01;

            let tick = MarketTick {
                symbol: s.to_string(),
                bid,
                ask,
                ts_nanos: now_nanos(),
            };

            tx.send(Event::Tick(tick)).unwrap();
        }

        thread::sleep(std::time::Duration::from_millis(50));
    }
}

fn rand_offset() -> f64 {
    // Simple placeholder. Replace with real market data input.
    let nanos = now_nanos() as u64;
    (nanos % 100) as f64 / 1000.0
}

fn event_loop(rx: Receiver<Event>, tx: Sender<Event>) {
    let strategy = Strategy { threshold: 0.02 };
    let risk = RiskManager { max_order_qty: 100 };
    let mut order_manager = OrderManager { next_order_id: 0 };

    while let Ok(event) = rx.recv() {
        match event {
            Event::Tick(tick) => {
                if let Some(order) = strategy.on_tick(&tick) {
                    match risk.check(&order) {
                        Ok(_) => {
                            let ack = order_manager.send_order(&order);
                            tx.send(Event::Ack(ack)).unwrap();
                        }
                        Err(reason) => {
                            tx.send(Event::RiskReject(order, reason)).unwrap();
                        }
                    }
                }
            }
            Event::Ack(ack) => {
                println!("Order ack: {:?}", ack);
            }
            Event::Fill(fill) => {
                println!("Order fill: {:?}", fill);
            }
            Event::OrderIntent(_) => {}
            Event::RiskReject(order, reason) => {
                println!("Risk reject: {:?} reason={}", order, reason);
            }
        }
    }
}

fn main() {
    env_logger::init();

    let (tx, rx) = unbounded::<Event>();

    let feed_tx = tx.clone();
    thread::spawn(move || market_data_feed(feed_tx));

    event_loop(rx, tx);
}
