## 7) Risk engine

### `src/risk.rs`
```rust
use crate::event::OrderIntent;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

#[derive(Debug, Clone)]
pub struct RiskEngine {
    limits: RiskLimits,
}

#[derive(Debug)]
pub enum RiskRejectReason {
    QtyTooLarge,
    NotionalTooLarge,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check(&self, order: &OrderIntent) -> Result<(), RiskRejectReason> {
        if order.qty > self.limits.max_order_qty {
            return Err(RiskRejectReason::QtyTooLarge);
        }

        let notional = order.qty * order.price;
        if notional > self.limits.max_notional {
            return Err(RiskRejectReason::NotionalTooLarge);
        }

        Ok(())
        }
}
