## 8) Strategy engine

This is a simple example: a spread-based mean-reversion style strategy that reacts to tick data.

### `src/strategy.rs`
```rust
use crate::event::{MarketTick, OrderIntent, Side};
use std::sync::atomic::{AtomicU64, Ordering};

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderIntent>;
}

pub struct SimpleSpreadStrategy {
    order_counter: AtomicU64,
    threshold: f64,
    order_qty: f64,
}

impl SimpleSpreadStrategy {
    pub fn new(threshold: f64, order_qty: f64) -> Self {
        Self {
            order_counter: AtomicU64::new(1),
            threshold,
            order_qty,
        }
    }

    fn next_id(&self) -> String {
        let id = self.order_counter.fetch_add(1, Ordering::Relaxed);
        format!("CID-{id}")
    }
}

impl Strategy for SimpleSpreadStrategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<OrderIntent> {
        let spread = tick.ask - tick.bid;

        if spread > self.threshold {
            let mid = (tick.ask + tick.bid) / 2.0;
            return Some(OrderIntent {
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                price: mid,
                client_order_id: self.next_id(),
            });
        }

        None
    }
}
```

