## 11) Engine orchestration

### `src/engine.rs`
```rust
use crate::{
    event::MarketTick,
    execution::ExecutionGateway,
    oms::OrderManager,
    risk::RiskEngine,
    strategy::Strategy,
};
use std::sync::Arc;

pub struct TradingEngine<S: Strategy> {
    strategy: Arc<S>,
    risk: RiskEngine,
    oms: Arc<OrderManager>,
    gateway: Arc<ExecutionGateway>,
}

impl<S: Strategy> TradingEngine<S> {
    pub fn new(strategy: S, risk: RiskEngine) -> Self {
        Self {
            strategy: Arc::new(strategy),
            risk,
            oms: Arc::new(OrderManager::new()),
            gateway: Arc::new(ExecutionGateway::new()),
        }
    }

    pub async fn on_tick(&self, tick: MarketTick) {
        if let Some(order) = self.strategy.on_tick(&tick) {
            match self.risk.check(&order) {
                Ok(_) => {
                    self.oms.submit(&order);
                    let ack = self.gateway.send_order(&order).await;
                    self.oms.on_ack(&ack);
                }
                Err(reason) => {
                    tracing::warn!("Risk rejected order {:?}: {:?}", order, reason);
                }
            }
        }
    }
}
```

