use axum::{
    extract::State,
    routing::{get, post},
    Json, Router,
};
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use std::{
    cmp::Ordering,
    collections::{BinaryHeap, HashMap},
    net::SocketAddr,
    sync::Arc,
};
use tracing::{info, warn};
use uuid::Uuid;

#[derive(Clone)]
struct AppState {
    engine: Arc<Mutex<MatchingEngine>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OrderRequest {
    symbol: String,
    side: Side,
    price: u64,   // price in cents
    qty: u64,     // quantity units
    client_id: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    id: Uuid,
    symbol: String,
    side: Side,
    price: u64,
    qty: u64,
    remaining: u64,
    client_id: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Trade {
    buy_order_id: Uuid,
    sell_order_id: Uuid,
    symbol: String,
    price: u64,
    qty: u64,
}

#[derive(Debug, Clone)]
struct BuyOrder(Order);

#[derive(Debug, Clone)]
struct SellOrder(Order);

// Highest buy price first
impl Ord for BuyOrder {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0
            .price
            .cmp(&other.0.price)
            .then_with(|| other.0.id.cmp(&self.0.id))
    }
}
impl PartialOrd for BuyOrder {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl PartialEq for BuyOrder {
    fn eq(&self, other: &Self) -> bool {
        self.0.id == other.0.id
    }
}
impl Eq for BuyOrder {}

// Lowest sell price first
impl Ord for SellOrder {
    fn cmp(&self, other: &Self) -> Ordering {
        other
            .0
            .price
            .cmp(&self.0.price)
            .then_with(|| other.0.id.cmp(&self.0.id))
    }
}
impl PartialOrd for SellOrder {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl PartialEq for SellOrder {
    fn eq(&self, other: &Self) -> bool {
        self.0.id == other.0.id
    }
}
impl Eq for SellOrder {}

struct MatchingEngine {
    buys: HashMap<String, BinaryHeap<BuyOrder>>,
    sells: HashMap<String, BinaryHeap<SellOrder>>,
    trades: Vec<Trade>,
}

impl MatchingEngine {
    fn new() -> Self {
        Self {
            buys: HashMap::new(),
            sells: HashMap::new(),
            trades: Vec::new(),
        }
    }

    fn place_order(&mut self, req: OrderRequest) -> Vec<Trade> {
        let mut incoming = Order {
            id: Uuid::new_v4(),
            symbol: req.symbol.clone(),
            side: req.side.clone(),
            price: req.price,
            qty: req.qty,
            remaining: req.qty,
            client_id: req.client_id,
        };

        let trades = match incoming.side {
            Side::Buy => self.match_buy(&mut incoming),
            Side::Sell => self.match_sell(&mut incoming),
        };

        // If not fully filled, store remaining order in book
        if incoming.remaining > 0 {
            match incoming.side {
                Side::Buy => {
                    self.buys
                        .entry(incoming.symbol.clone())
                        .or_default()
                        .push(BuyOrder(incoming));
                }
                Side::Sell => {
                    self.sells
                        .entry(incoming.symbol.clone())
                        .or_default()
                        .push(SellOrder(incoming));
                }
            }
        }

        trades
    }

    fn match_buy(&mut self, incoming: &mut Order) -> Vec<Trade> {
        let mut trades = Vec::new();
        let book = self.sells.entry(incoming.symbol.clone()).or_default();

        while incoming.remaining > 0 {
            let best_sell = match book.peek() {
                Some(s) if s.0.price <= incoming.price => s.0.clone(),
                _ => break,
            };

            let mut resting = book.pop().unwrap().0;
            let qty = incoming.remaining.min(resting.remaining);
            let trade_price = resting.price;

            incoming.remaining -= qty;
            resting.remaining -= qty;

            let trade = Trade {
                buy_order_id: incoming.id,
                sell_order_id: resting.id,
                symbol: incoming.symbol.clone(),
                price: trade_price,
                qty,
            };

            trades.push(trade.clone());
            self.trades.push(trade);

            if resting.remaining > 0 {
                book.push(SellOrder(resting));
            }
        }

        trades
    }

    fn match_sell(&mut self, incoming: &mut Order) -> Vec<Trade> {
        let mut trades = Vec::new();
        let book = self.buys.entry(incoming.symbol.clone()).or_default();

        while incoming.remaining > 0 {
            let best_buy = match book.peek() {
                Some(b) if b.0.price >= incoming.price => b.0.clone(),
                _ => break,
            };

            let mut resting = book.pop().unwrap().0;
            let qty = incoming.remaining.min(resting.remaining);
            let trade_price = resting.price;

            incoming.remaining -= qty;
            resting.remaining -= qty;

            let trade = Trade {
                buy_order_id: resting.id,
                sell_order_id: incoming.id,
                symbol: incoming.symbol.clone(),
                price: trade_price,
                qty,
            };

            trades.push(trade.clone());
            self.trades.push(trade);

            if resting.remaining > 0 {
                book.push(BuyOrder(resting));
            }
        }

        trades
    }
}

async fn health() -> &'static str {
    "ok"
}

async fn place_order(
    State(state): State<AppState>,
    Json(req): Json<OrderRequest>,
) -> Json<Vec<Trade>> {
    let mut engine = state.engine.lock();
    let trades = engine.place_order(req);

    if trades.is_empty() {
        info!("order accepted, no immediate match");
    } else {
        info!("trades executed: {}", trades.len());
    }

    Json(trades)
}

async fn book_snapshot(State(state): State<AppState>) -> Json<serde_json::Value> {
    let engine = state.engine.lock();

    let buy_count: usize = engine.buys.values().map(|b| b.len()).sum();
    let sell_count: usize = engine.sells.values().map(|s| s.len()).sum();
    let trade_count = engine.trades.len();

    Json(serde_json::json!({
        "buy_orders": buy_count,
        "sell_orders": sell_count,
        "trades": trade_count
    }))
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt::init();

    let state = AppState {
        engine: Arc::new(Mutex::new(MatchingEngine::new())),
    };

    let app = Router::new()
        .route("/health", get(health))
        .route("/order", post(place_order))
        .route("/snapshot", get(book_snapshot))
        .with_state(state);

    let addr = SocketAddr::from(([0, 0, 0, 0], 3000));
    info!("listening on {}", addr);

    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .expect("bind failed");

    axum::serve(listener, app).await.unwrap();
}
