```rust
use crossbeam_channel::{unbounded, Receiver, Sender};
use serde::{Deserialize, Serialize};
use std::thread;
use std::time::Duration;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketTick {
    symbol: String,
    price: f64,
    timestamp_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    symbol: String,
    side: Side,
    quantity: u64,
    price: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum TradeEvent {
    Tick(MarketTick),
    Order(Order),
    Fill {
        symbol: String,
        side: Side,
        quantity: u64,
        price: f64,
    },
    Reject {
        reason: String,
    },
}

struct RiskManager {
    max_order_qty: u64,
}

impl RiskManager {
    fn approve(&self, order: &Order) -> Result<(), String> {
        if order.quantity > self.max_order_qty {
            return Err(format!(
                "Order quantity {} exceeds limit {}",
                order.quantity, self.max_order_qty
            ));
        }
        Ok(())
    }
}

struct StrategyEngine {
    last_price: Option<f64>,
}

impl StrategyEngine {
    fn new() -> Self {
        Self { last_price: None }
    }

    fn on_tick(&mut self, tick: &MarketTick) -> Option<Order> {
        let previous = self.last_price;
        self.last_price = Some(tick.price);

        // Minimal example strategy:
        // Buy if price dropped more than 1% from the previous tick
        if let Some(prev) = previous {
            if tick.price < prev * 0.99 {
                return Some(Order {
                    symbol: tick.symbol.clone(),
                    side: Side::Buy,
                    quantity: 10,
                    price: tick.price,
                });
            }
        }

        None
    }
}

struct ExecutionEngine;

impl ExecutionEngine {
    fn execute(&self, order: &Order) -> TradeEvent {
        // Mock exchange fill
        TradeEvent::Fill {
            symbol: order.symbol.clone(),
            side: order.side.clone(),
            quantity: order.quantity,
            price: order.price,
        }
    }
}

fn market_data_feed(tx: Sender<TradeEvent>) {
    let ticks = vec![
        100.0, 100.2, 99.8, 99.0, 99.5, 98.7, 99.1, 98.0, 98.4,
    ];

    for price in ticks {
        let tick = MarketTick {
            symbol: "AAPL".to_string(),
            price,
            timestamp_ms: current_time_ms(),
        };

        tx.send(TradeEvent::Tick(tick)).unwrap();
        thread::sleep(Duration::from_millis(50));
    }
}

fn current_time_ms() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

fn main() {
    let (tx, rx): (Sender<TradeEvent>, Receiver<TradeEvent>) = unbounded();

    let feed_tx = tx.clone();
    thread::spawn(move || {
        market_data_feed(feed_tx);
    });

    let risk_manager = RiskManager { max_order_qty: 100 };
    let execution_engine = ExecutionEngine;
    let mut strategy_engine = StrategyEngine::new();

    println!("Trading platform started...");

    while let Ok(event) = rx.recv() {
        match event {
            TradeEvent::Tick(tick) => {
                println!("Received tick: {:?}", tick);

                if let Some(order) = strategy_engine.on_tick(&tick) {
                    println!("Strategy generated order: {:?}", order);

                    match risk_manager.approve(&order) {
                        Ok(_) => {
                            let fill_or_reject = execution_engine.execute(&order);
                            println!("Execution result: {:?}", fill_or_reject);
                        }
                        Err(reason) => {
                            println!("Order rejected by risk: {}", reason);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    println!("Trading platform stopped.");
}
```

