    side: Side,
    qty: u32,
    price: f64,
}

#[derive(Debug)]
struct Position {
    symbol: String,
    qty: i32,
}

fn now_ms() -> u128 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_millis()
}

fn market_data_feed(tx: Sender<MarketDataEvent>) {
    let mut price = 100.0;

    loop {
        // Simple simulated price movement
        price += if rand_bool() { 0.2 } else { -0.2 };

        let event = MarketDataEvent {
            symbol: "AAPL".to_string(),
            price,
            timestamp: now_ms(),
        };

        if tx.send(event).is_err() {
            break;
        }

        thread::sleep(Duration::from_millis(100));
    }
}

fn strategy_engine(
    md_rx: Receiver<MarketDataEvent>,
    order_tx: Sender<OrderEvent>,
) {
    let mut last_price: Option<f64> = None;

    while let Ok(md) = md_rx.recv() {
        if let Some(prev) = last_price {
            // Very simple mean-reversion style trigger
            if md.price < prev - 0.15 {
                let order = OrderEvent {
                    symbol: md.symbol.clone(),
                    side: Side::Buy,
                    qty: 10,
                    price: md.price,
                };
                let _ = order_tx.send(order);
            } else if md.price > prev + 0.15 {
                let order = OrderEvent {
                    symbol: md.symbol.clone(),
                    side: Side::Sell,
                    qty: 10,
                    price: md.price,
                };
                let _ = order_tx.send(order);
            }
        }

        last_price = Some(md.price);
    }
}

fn risk_check(order: &OrderEvent, position: &Position) -> bool {
    let max_abs_position = 100;

    match order.side {
        Side::Buy => position.qty + order.qty as i32 <= max_abs_position,
        Side::Sell => position.qty - order.qty as i32 >= -max_abs_position,
    }
}

fn order_manager(
    order_rx: Receiver<OrderEvent>,
    fill_tx: Sender<FillEvent>,
) {
    let mut position = Position {
        symbol: "AAPL".to_string(),
        qty: 0,
    };

    while let Ok(order) = order_rx.recv() {
        if !risk_check(&order, &position) {
            println!("RISK REJECT: {:?}", order);
            continue;
        }

        // Simulated execution fill
        let fill = FillEvent {
            symbol: order.symbol.clone(),
            side: order.side.clone(),
            qty: order.qty,
            price: order.price,
        };

        match fill.side {
            Side::Buy => position.qty += fill.qty as i32,
            Side::Sell => position.qty -= fill.qty as i32,
        }

        let _ = fill_tx.send(fill);
    }
}

fn fill_handler(fill_rx: Receiver<FillEvent>) {
    while let Ok(fill) = fill_rx.recv() {
        println!("FILL: {:?}", fill);
    }
}

fn rand_bool() -> bool {
    // Small deterministic-ish helper without extra dependencies
    now_ms() % 2 == 0
}

fn main() {
    let (md_tx, md_rx) = unbounded::<MarketDataEvent>();
    let (order_tx, order_rx) = unbounded::<OrderEvent>();
    let (fill_tx, fill_rx) = unbounded::<FillEvent>();

    let feed_thread = {
        let tx = md_tx.clone();
        thread::spawn(move || market_data_feed(tx))
    };

    let strategy_thread = {
        let rx = md_rx;
        let tx = order_tx.clone();
        thread::spawn(move || strategy_engine(rx, tx))
    };

    let oms_thread = {
        let rx = order_rx;
        let tx = fill_tx.clone();
        thread::spawn(move || order_manager(rx, tx))
    };

    let fill_thread = thread::spawn(move || fill_handler(fill_rx));

    // Run for a short demo period
    thread::sleep(Duration::from_secs(5));

    // In a real system, use graceful shutdown signals
    drop(md_tx);
    drop(order_tx);
    drop(fill_tx);

    let _ = feed_thread.join();
    let _ = strategy_thread.join();
    let _ = oms_thread.join();
    let _ = fill_thread.join();
}
