use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::sync::{mpsc, RwLock};
use tracing::{info, warn};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketTick {
    symbol: String,
    price: f64,
    ts_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    id: Uuid,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Fill {
    order_id: Uuid,
    symbol: String,
    side: Side,
    qty: u64,
    price: f64,
}

#[derive(Debug, Default)]
struct Portfolio {
    positions: HashMap<String, i64>,
    max_position_per_symbol: i64,
}

impl Portfolio {
    fn new(max_position_per_symbol: i64) -> Self {
        Self {
            positions: HashMap::new(),
            max_position_per_symbol,
        }
    }

    fn can_place(&self, symbol: &str, side: &Side, qty: u64) -> bool {
        let current = *self.positions.get(symbol).unwrap_or(&0);
        let delta = match side {
            Side::Buy => qty as i64,
            Side::Sell => -(qty as i64),
        };
        let next = current + delta;
        next.abs() <= self.max_position_per_symbol
    }

    fn apply_fill(&mut self, fill: &Fill) {
        let entry = self.positions.entry(fill.symbol.clone()).or_insert(0);
        *entry += match fill.side {
            Side::Buy => fill.qty as i64,
            Side::Sell => -(fill.qty as i64),
        };
    }
}

fn simple_strategy(tick: &MarketTick) -> Option<Order> {
    // Example: buy if price is below a threshold, sell if above.
    // Replace with real signal logic later.
    if tick.price < 100.0 {
        Some(Order {
            id: Uuid::new_v4(),
            symbol: tick.symbol.clone(),
            side: Side::Buy,
            qty: 1,
            price: tick.price,
        })
    } else if tick.price > 105.0 {
        Some(Order {
            id: Uuid::new_v4(),
            symbol: tick.symbol.clone(),
            side: Side::Sell,
            qty: 1,
            price: tick.price,
        })
    } else {
        None
    }
}

async fn execution_gateway(order: Order) -> Fill {
    // Mock execution. In real life this would talk to an exchange/broker adapter.
    Fill {
        order_id: order.id,
        symbol: order.symbol,
        side: order.side,
        qty: order.qty,
        price: order.price,
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (tick_tx, mut tick_rx) = mpsc::channel::<MarketTick>(1024);
    let (order_tx, mut order_rx) = mpsc::channel::<Order>(1024);
    let (fill_tx, mut fill_rx) = mpsc::channel::<Fill>(1024);

    let portfolio = RwLock::new(Portfolio::new(10));

    // Market data producer (mock)
    let producer = tokio::spawn(async move {
        let ticks = vec![
            MarketTick { symbol: "AAPL".into(), price: 99.5, ts_ms: 1 },
            MarketTick { symbol: "AAPL".into(), price: 100.2, ts_ms: 2 },
            MarketTick { symbol: "AAPL".into(), price: 106.1, ts_ms: 3 },
            MarketTick { symbol: "AAPL".into(), price: 104.0, ts_ms: 4 },
        ];

        for tick in ticks {
            if let Err(e) = tick_tx.send(tick).await {
                warn!("failed to send tick: {}", e);
                break;
            }
        }
    });

    // Strategy engine
    let strategy_engine = tokio::spawn(async move {
        while let Some(tick) = tick_rx.recv().await {
            info!("tick: {:?}", tick);
            if let Some(order) = simple_strategy(&tick) {
                if let Err(e) = order_tx.send(order).await {
                    warn!("failed to send order: {}", e);
                    break;
                }
            }
        }
    });

    // Risk + execution
    let portfolio_for_orders = &portfolio;
    let risk_and_exec = tokio::spawn(async move {
        while let Some(order) = order_rx.recv().await {
            let can_place = {
                let p = portfolio_for_orders.read().await;
                p.can_place(&order.symbol, &order.side, order.qty)
            };

            if !can_place {
                warn!("risk reject: {:?}", order);
                continue;
            }

            let fill = execution_gateway(order.clone()).await;
            if let Err(e) = fill_tx.send(fill).await {
                warn!("failed to send fill: {}", e);
                break;
            }
        }
    });

    // Portfolio updater
    let portfolio_updater = tokio::spawn(async move {
        while let Some(fill) = fill_rx.recv().await {
            {
                let mut p = portfolio.write().await;
                p.apply_fill(&fill);
                info!("fill applied: {:?}, positions: {:?}", fill, p.positions);
            }
        }
    });

    let _ = tokio::join!(producer, strategy_engine, risk_and_exec, portfolio_updater);
}
