```rust
use anyhow::Result;
use crossbeam_channel::{unbounded, Receiver, Sender};
use serde::{Deserialize, Serialize};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    ts_nanos: u128,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    id: u64,
    symbol: String,
    side: Side,
    qty: f64,
    price: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
enum OrderStatus {
    New,
    Rejected(String),
    Sent,
    Filled,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OrderEvent {
    order: Order,
    status: OrderStatus,
    ts_nanos: u128,
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn market_data_feed(tx: Sender<MarketData>) {
    let mut price = 100.0;

    loop {
        price += 0.01;
        let md = MarketData {
            symbol: "ABC".to_string(),
            price,
            ts_nanos: now_nanos(),
        };

        if tx.send(md).is_err() {
            break;
        }

        thread::sleep(Duration::from_millis(10));
    }
}

fn strategy_engine(rx: Receiver<MarketData>, tx: Sender<Order>) {
    let mut order_id = 1u64;

    for md in rx.iter() {
        // Very simple strategy:
        // Buy if price is below 100.50, sell if above 100.80
        let maybe_order = if md.price < 100.50 {
            Some(Order {
                id: order_id,
                symbol: md.symbol.clone(),
                side: Side::Buy,
                qty: 10.0,
                price: md.price,
            })
        } else if md.price > 100.80 {
            Some(Order {
                id: order_id,
                symbol: md.symbol.clone(),
                side: Side::Sell,
                qty: 10.0,
                price: md.price,
            })
        } else {
            None
        };

        if let Some(order) = maybe_order {
            if tx.send(order).is_err() {
                break;
            }
            order_id += 1;
        }
    }
}

fn risk_check(order: &Order) -> Result<()> {
    if order.qty <= 0.0 {
        anyhow::bail!("invalid qty");
    }
    if order.qty > 100.0 {
        anyhow::bail!("qty too large");
    }
    if order.price <= 0.0 {
        anyhow::bail!("invalid price");
    }
    Ok(())
}

fn execution_adapter(order: &Order) -> OrderStatus {
    // Mock execution
    let _ = order;
    OrderStatus::Filled
}

fn order_manager(rx: Receiver<Order>, tx: Sender<OrderEvent>) {
    for order in rx.iter() {
        let ts = now_nanos();

        let status = match risk_check(&order) {
            Ok(_) => {
                let exec_status = execution_adapter(&order);
                match exec_status {
                    OrderStatus::Filled => OrderStatus::Filled,
                    _ => OrderStatus::Sent,
                }
            }
            Err(e) => OrderStatus::Rejected(e.to_string()),
        };

        let evt = OrderEvent {
            order,
            status,
            ts_nanos: ts,
        };

        if tx.send(evt).is_err() {
            break;
        }
    }
}

fn logger(rx: Receiver<OrderEvent>) {
    for evt in rx.iter() {
        println!("{}", serde_json::to_string(&evt).unwrap());
    }
}

fn main() {
    let (md_tx, md_rx) = unbounded::<MarketData>();
    let (order_tx, order_rx) = unbounded::<Order>();
    let (evt_tx, evt_rx) = unbounded::<OrderEvent>();

    let md_thread = thread::spawn(move || market_data_feed(md_tx));
    let strat_thread = thread::spawn(move || strategy_engine(md_rx, order_tx));
    let om_thread = thread::spawn(move || order_manager(order_rx, evt_tx));
    let log_thread = thread::spawn(move || logger(evt_rx));

    let _ = md_thread.join();
    let _ = strat_thread.join();
    let _ = om_thread.join();
    let _ = log_thread.join();
}
```

