    min: f64,
    max: f64,
    avg: f64,
    vwap: f64,
    count: usize,
    last_price: f64,
}

#[derive(Debug, Clone)]
struct TickRecord {
    price: f64,
    volume: f64,
    ts: Instant,
}

struct RollingWindow {
    window: Duration,
    ticks: VecDeque<TickRecord>,
    sum_price: f64,
    sum_volume: f64,
    sum_px_vol: f64,
    min: f64,
    max: f64,
}

impl RollingWindow {
    fn new(window: Duration) -> Self {
        Self {
            window,
            ticks: VecDeque::new(),
            sum_price: 0.0,
            sum_volume: 0.0,
            sum_px_vol: 0.0,
            min: f64::INFINITY,
            max: f64::NEG_INFINITY,
        }
    }

    fn push(&mut self, tick: &Tick) {
        self.ticks.push_back(TickRecord {
            price: tick.price,
            volume: tick.volume,
            ts: tick.ts,
        });

        self.sum_price += tick.price;
        self.sum_volume += tick.volume;
        self.sum_px_vol += tick.price * tick.volume;

        if tick.price < self.min {
            self.min = tick.price;
        }
        if tick.price > self.max {
            self.max = tick.price;
        }

        self.evict_old(tick.ts);
    }

    fn evict_old(&mut self, now: Instant) {
        while let Some(front) = self.ticks.front() {
            if now.duration_since(front.ts) <= self.window {
                break;
            }

            let old = self.ticks.pop_front().unwrap();
            self.sum_price -= old.price;
            self.sum_volume -= old.volume;
            self.sum_px_vol -= old.price * old.volume;
        }

        // Recompute min/max if needed after evictions.
        if self.ticks.is_empty() {
            self.min = f64::INFINITY;
            self.max = f64::NEG_INFINITY;
        } else if !self.ticks.iter().any(|t| t.price == self.min || t.price == self.max) {
            self.min = self.ticks.iter().map(|t| t.price).fold(f64::INFINITY, f64::min);
            self.max = self.ticks.iter().map(|t| t.price).fold(f64::NEG_INFINITY, f64::max);
        }
    }

    fn aggregate(&self, symbol: &str) -> Option<Aggregate> {
        if self.ticks.is_empty() {
            return None;
        }

        let count = self.ticks.len();
        let avg = self.sum_price / count as f64;
        let vwap = if self.sum_volume > 0.0 {
            self.sum_px_vol / self.sum_volume
        } else {
            0.0
        };

        Some(Aggregate {
            symbol: symbol.to_string(),
            window_secs: self.window.as_secs(),
            min: self.min,
            max: self.max,
            avg,
            vwap,
            count,
            last_price: self.ticks.back().unwrap().price,
        })
    }
}

struct MarketDataProcessor {
    windows: HashMap<String, RollingWindow>,
    tx: broadcast::Sender<Aggregate>,
    window: Duration,
}

impl MarketDataProcessor {
    fn new(window: Duration) -> Self {
        let (tx, _) = broadcast::channel(1024);
        Self {
            windows: HashMap::new(),
            tx,
            window,
        }
    }

    fn subscribe(&self) -> broadcast::Receiver<Aggregate> {
        self.tx.subscribe()
    }

    fn process_tick(&mut self, tick: Tick) {
        let window = self
            .windows
            .entry(tick.symbol.clone())
            .or_insert_with(|| RollingWindow::new(self.window));

        window.push(&tick);

        if let Some(agg) = window.aggregate(&tick.symbol) {
            let _ = self.tx.send(agg);
        }
    }
}

#[tokio::main]
async fn main() {
    let mut processor = MarketDataProcessor::new(Duration::from_secs(10));

    let mut sub1 = processor.subscribe();
    let mut sub2 = processor.subscribe();

    tokio::spawn(async move {
        while let Ok(update) = sub1.recv().await {
            println!("[sub1] {:?}", update);
        }
    });

    tokio::spawn(async move {
        while let Ok(update) = sub2.recv().await {
            println!("[sub2] {:?}", update);
        }
    });

    let ticks = vec![
        Tick { symbol: "AAPL".into(), price: 190.10, volume: 100.0, ts: Instant::now() },
        Tick { symbol: "AAPL".into(), price: 190.25, volume: 120.0, ts: Instant::now() },
        Tick { symbol: "AAPL".into(), price: 190.05, volume: 80.0,  ts: Instant::now() },
        Tick { symbol: "MSFT".into(), price: 410.50, volume: 50.0,  ts: Instant::now() },
        Tick { symbol: "MSFT".into(), price: 411.00, volume: 70.0,  ts: Instant::now() },
    ];

    for tick in ticks {
        processor.process_tick(tick);
        sleep(Duration::from_millis(200)).await;
    }

    sleep(Duration::from_secs(1)).await;
}
