use dashmap::DashMap;
use futures::{FutureExt, StreamExt};
use rand::Rng;
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    convert::Infallible,
    sync::Arc,
    time::{Duration, Instant},
};
use tokio::sync::{broadcast, Mutex};
use warp::ws::{Message, WebSocket};
use warp::Filter;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Tick {
    symbol: String,
    price: f64,
    volume: f64,
    ts_ms: u64,
}

#[derive(Debug, Clone, Serialize)]
struct Aggregate {
    symbol: String,
    window_secs: u64,
    count: usize,
    min: f64,
    max: f64,
    vwap: f64,
    avg: f64,
    last: f64,
    updated_at_ms: u128,
}

#[derive(Debug, Clone)]
struct PricePoint {
    price: f64,
    volume: f64,
    time: Instant,
}

struct SymbolState {
    points: VecDeque<PricePoint>,
    last_price: f64,
}

impl SymbolState {
    fn new() -> Self {
        Self {
            points: VecDeque::new(),
            last_price: 0.0,
        }
    }
}

type SharedStates = Arc<DashMap<String, Mutex<SymbolState>>>;

#[tokio::main]
async fn main() {
    let states: SharedStates = Arc::new(DashMap::new());
    let (tx, _rx) = broadcast::channel::<String>(1024);

    // Simulated tick source
    {
        let states = states.clone();
        let tx = tx.clone();
        tokio::spawn(async move {
            let symbols = ["AAPL", "MSFT", "NVDA", "TSLA", "AMZN"];
            loop {
                let tick = {
                    let mut rng = rand::thread_rng();
                    let symbol = symbols[rng.gen_range(0..symbols.len())].to_string();
                    let price = 100.0 + rng.gen_range(-5.0..5.0);
                    let volume = rng.gen_range(1.0..500.0);
                    Tick {
                        symbol,
                        price,
                        volume,
                        ts_ms: current_time_ms(),
                    }
                };

                if let Some(agg) = process_tick(&states, &tick, 10).await {
                    if let Ok(msg) = serde_json::to_string(&agg) {
                        let _ = tx.send(msg);
                    }
                }

                tokio::time::sleep(Duration::from_millis(100)).await;
            }
        });
    }

    let states_filter = warp::any().map(move || states.clone());
    let tx_filter = warp::any().map(move || tx.clone());

    let ws_route = warp::path("ws")
        .and(warp::ws())
        .and(tx_filter)
        .and_then(handle_ws);

    let health_route = warp::path("health").map(|| "ok");

    let routes = ws_route.or(health_route);

    println!("Server running on 0.0.0.0:3030");
    warp::serve(routes).run(([0, 0, 0, 0], 3030)).await;
}

async fn process_tick(
    states: &SharedStates,
    tick: &Tick,
    window_secs: u64,
) -> Option<Aggregate> {
    let entry = states
        .entry(tick.symbol.clone())
        .or_insert_with(|| Mutex::new(SymbolState::new()));

    let mut state = entry.lock().await;
    let now = Instant::now();
    state.last_price = tick.price;

    state.points.push_back(PricePoint {
        price: tick.price,
        volume: tick.volume,
        time: now,
    });

    // Evict old points outside the rolling window
    let window = Duration::from_secs(window_secs);
    while let Some(front) = state.points.front() {
        if now.duration_since(front.time) > window {
            state.points.pop_front();
        } else {
            break;
        }
    }

    let count = state.points.len();
    if count == 0 {
        return None;
    }

    let mut min = f64::INFINITY;
    let mut max = f64::NEG_INFINITY;
    let mut sum = 0.0;
    let mut vol_sum = 0.0;
    let mut px_vol_sum = 0.0;

    for p in state.points.iter() {
        if p.price < min {
            min = p.price;
        }
        if p.price > max {
            max = p.price;
        }
        sum += p.price;
        vol_sum += p.volume;
        px_vol_sum += p.price * p.volume;
    }

    let avg = sum / count as f64;
    let vwap = if vol_sum > 0.0 { px_vol_sum / vol_sum } else { tick.price };

    Some(Aggregate {
        symbol: tick.symbol.clone(),
        window_secs,
        count,
        min,
        max,
        vwap,
        avg,
        last: state.last_price,
        updated_at_ms: current_time_ms() as u128,
    })
}

async fn handle_ws(
    ws: warp::ws::Ws,
    tx: broadcast::Sender<String>,
) -> Result<impl warp::Reply, Infallible> {
    Ok(ws.on_upgrade(move |socket| client_connection(socket, tx.subscribe())))
}

async fn client_connection(ws: WebSocket, mut rx: broadcast::Receiver<String>) {
    let (mut user_ws_tx, mut user_ws_rx) = ws.split();

    let send_task = tokio::spawn(async move {
        while let Ok(msg) = rx.recv().await {
            if user_ws_tx.send(Message::text(msg)).await.is_err() {
                break;
            }
        }
    });

    let recv_task = tokio::spawn(async move {
        while let Some(result) = user_ws_rx.next().await {
            match result {
                Ok(msg) if msg.is_text() => {
                    // In a real system, handle subscription commands here
                    // e.g. {"subscribe":["AAPL","MSFT"]}
                    let _ = msg.to_str();
                }
                Ok(msg) if msg.is_close() => break,
                Ok(_) => {}
                Err(_) => break,
            }
        }
    });

    let _ = futures::future::select(send_task.map(|_| ()), recv_task.map(|_| ())).await;
}

fn current_time_ms() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}
