use std::{
    collections::VecDeque,
    sync::Arc,
    time::{Duration, Instant},
};

use dashmap::DashMap;
use futures_util::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use tokio::sync::broadcast;
use warp::Filter;

#[derive(Debug, Clone, Deserialize)]
struct PriceTick {
    symbol: String,
    price: f64,
    ts_millis: u64,
}

#[derive(Debug, Clone, Serialize)]
struct PriceAggregate {
    symbol: String,
    window_secs: u64,
    count: usize,
    min: f64,
    max: f64,
    avg: f64,
    last: f64,
    updated_at_millis: u128,
}

#[derive(Debug)]
struct SymbolState {
    ticks: VecDeque<(Instant, f64)>,
    min: f64,
    max: f64,
    sum: f64,
    last: f64,
}

impl SymbolState {
    fn new() -> Self {
        Self {
            ticks: VecDeque::new(),
            min: f64::INFINITY,
            max: f64::NEG_INFINITY,
            sum: 0.0,
            last: 0.0,
        }
    }

    fn recompute_from_window(&mut self) {
        self.min = f64::INFINITY;
        self.max = f64::NEG_INFINITY;
        self.sum = 0.0;

        for &(_, price) in self.ticks.iter() {
            self.min = self.min.min(price);
            self.max = self.max.max(price);
            self.sum += price;
        }

        if self.ticks.is_empty() {
            self.min = 0.0;
            self.max = 0.0;
        }
    }
}

type SharedState = Arc<DashMap<String, SymbolState>>;

fn prune_old_ticks(state: &mut SymbolState, window: Duration) {
    let cutoff = Instant::now() - window;
    while let Some(&(ts, price)) = state.ticks.front() {
        if ts < cutoff {
            state.ticks.pop_front();
        } else {
            break;
        }
    }

    // Since values may have been removed, recompute aggregates for simplicity.
    state.recompute_from_window();
}

fn aggregate_for(symbol: &str, state: &SymbolState, window_secs: u64) -> PriceAggregate {
    let count = state.ticks.len();
    let avg = if count > 0 { state.sum / count as f64 } else { 0.0 };

    PriceAggregate {
        symbol: symbol.to_string(),
        window_secs,
        count,
        min: state.min,
        max: state.max,
        avg,
        last: state.last,
        updated_at_millis: Instant::now().elapsed().as_millis(),
    }
}

async fn process_tick(
    tick: PriceTick,
    shared: SharedState,
    tx: broadcast::Sender<String>,
    window: Duration,
) {
    let now = Instant::now();

    let mut entry = shared.entry(tick.symbol.clone()).or_insert_with(SymbolState::new);
    entry.ticks.push_back((now, tick.price));
    entry.last = tick.price;

    prune_old_ticks(&mut entry, window);

    let aggregate = aggregate_for(&tick.symbol, &entry, window.as_secs());

    if let Ok(json) = serde_json::to_string(&aggregate) {
        let _ = tx.send(json);
    }
}

async fn ws_handler(
    ws: warp::ws::Ws,
    mut rx: broadcast::Receiver<String>,
) -> Result<impl warp::Reply, warp::Rejection> {
    Ok(ws.on_upgrade(move |socket| async move {
        let (mut ws_tx, mut ws_rx) = socket.split();

        let send_task = tokio::spawn(async move {
            loop {
                match rx.recv().await {
                    Ok(msg) => {
                        if ws_tx.send(warp::ws::Message::text(msg)).await.is_err() {
                            break;
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => {
                        continue;
                    }
                    Err(_) => break,
                }
            }
        });

        let recv_task = tokio::spawn(async move {
            while let Some(_msg) = ws_rx.next().await {
                // Optional: handle subscriber messages (e.g., symbol filters)
            }
        });

        let _ = tokio::join!(send_task, recv_task);
    }))
}

#[tokio::main]
async fn main() {
    let shared_state: SharedState = Arc::new(DashMap::new());
    let (tx, _rx) = broadcast::channel::<String>(1024);

    // Simulated market data feed
    let state_clone = shared_state.clone();
    let tx_clone = tx.clone();
    tokio::spawn(async move {
        let window = Duration::from_secs(60);

        let symbols = ["AAPL", "MSFT", "GOOG", "AMZN"];
        let mut price = 100.0;

        loop {
            for symbol in symbols.iter() {
                price += 0.5 - rand::random::<f64>();
                let tick = PriceTick {
                    symbol: symbol.to_string(),
                    price,
                    ts_millis: 0,
                };

                process_tick(tick, state_clone.clone(), tx_clone.clone(), window).await;
            }

            tokio::time::sleep(Duration::from_millis(200)).await;
        }
    });

    // WebSocket route
    let tx_filter = warp::any().map(move || tx.subscribe());

    let ws_route = warp::path("ws")
        .and(warp::ws())
        .and(tx_filter)
        .and_then(ws_handler);

    println!("WebSocket server running on ws://127.0.0.1:3030/ws");
    warp::serve(ws_route).run(([127, 0, 0, 0], 3030)).await;
}
