Below is a solid **Java** implementation of a real-time market data processor that:

- ingests trade events,
- computes running price aggregates,
- and streams aggregate updates to subscribers.

It uses:
- `ConcurrentHashMap` for symbol state,
- `CopyOnWriteArrayList` for subscribers,
- a scheduled task to periodically publish snapshots,
- and a simple pub/sub interface.

```java
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;

/**
 * Real-time market data processor:
 * - accepts trade ticks
 * - computes aggregates per symbol
 * - streams aggregate snapshots to subscribers
 */
public class MarketDataProcessor implements AutoCloseable {

    // Aggregates are kept per symbol
    private final Map<String, SymbolAggregate> aggregates = new ConcurrentHashMap<>();

    // Subscribers receive aggregate snapshots
    private final CopyOnWriteArrayList<Consumer<AggregateSnapshot>> subscribers = new CopyOnWriteArrayList<>();

    // Background publisher
    private final ScheduledExecutorService publisher =
            Executors.newSingleThreadScheduledExecutor(r -> {
                Thread t = new Thread(r, "aggregate-publisher");
                t.setDaemon(true);
                return t;
            });

    // Publish frequency
    private final long publishPeriodMillis;

    public MarketDataProcessor(long publishPeriodMillis) {
        this.publishPeriodMillis = publishPeriodMillis;
        startPublishing();
    }

    public MarketDataProcessor() {
        this(1000); // default: publish every second
    }

    /**
     * Ingest a trade event.
     */
    public void onTrade(Trade trade) {
        aggregates.compute(trade.symbol(), (symbol, current) -> {
            if (current == null) {
                current = new SymbolAggregate(symbol);
            }
            current.update(trade.price(), trade.quantity(), trade.timestamp());
            return current;
        });
    }

    /**
     * Subscribe to aggregate snapshots.
     */
    public void subscribe(Consumer<AggregateSnapshot> subscriber) {
        subscribers.add(subscriber);
    }

    public void unsubscribe(Consumer<AggregateSnapshot> subscriber) {
        subscribers.remove(subscriber);
    }

    private void startPublishing() {
        publisher.scheduleAtFixedRate(() -> {
            try {
                publishSnapshots();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, publishPeriodMillis, publishPeriodMillis, TimeUnit.MILLISECONDS);
    }

    private void publishSnapshots() {
        long now = System.currentTimeMillis();

        for (SymbolAggregate agg : aggregates.values()) {
            AggregateSnapshot snapshot = agg.snapshot(now);
            for (Consumer<AggregateSnapshot> subscriber : subscribers) {
                try {
                    subscriber.accept(snapshot);
                } catch (Exception ignored) {
                    // isolate subscriber failures
                }
            }
        }
    }

    @Override
    public void close() {
        publisher.shutdownNow();
    }

    // -------- Data Types --------

    public record Trade(String symbol, BigDecimal price, long quantity, long timestamp) {}

    public record AggregateSnapshot(
            String symbol,
            BigDecimal lastPrice,
            long totalVolume,
            BigDecimal vwap,
            BigDecimal minPrice,
            BigDecimal maxPrice,
            long tradeCount,
            long timestamp
    ) {}

    /**
     * Thread-safe aggregate for a single symbol.
     * Updates are synchronized to keep calculations consistent.
     */
    static class SymbolAggregate {
        private final String symbol;

        private BigDecimal lastPrice = BigDecimal.ZERO;
        private BigDecimal minPrice = null;
        private BigDecimal maxPrice = null;
        private BigDecimal notional = BigDecimal.ZERO; // sum(price * qty)
        private long totalVolume = 0;
        private long tradeCount = 0;
        private long lastTimestamp = 0;

        SymbolAggregate(String symbol) {
            this.symbol = symbol;
        }

        public synchronized void update(BigDecimal price, long quantity, long timestamp) {
            lastPrice = price;
            lastTimestamp = timestamp;
            tradeCount++;
            totalVolume += quantity;

            if (minPrice == null || price.compareTo(minPrice) < 0) {
                minPrice = price;
            }
            if (maxPrice == null || price.compareTo(maxPrice) > 0) {
                maxPrice = price;
            }

            BigDecimal qty = BigDecimal.valueOf(quantity);
            notional = notional.add(price.multiply(qty));
        }

        public synchronized AggregateSnapshot snapshot(long now) {
            BigDecimal vwap = totalVolume == 0
                    ? BigDecimal.ZERO
                    : notional.divide(BigDecimal.valueOf(totalVolume), 8, RoundingMode.HALF_UP);

            return new AggregateSnapshot(
                    symbol,
                    lastPrice,
                    totalVolume,
                    vwap,
                    minPrice == null ? BigDecimal.ZERO : minPrice,
                    maxPrice == null ? BigDecimal.ZERO : maxPrice,
                    tradeCount,
                    now
            );
        }
    }

    // -------- Example Usage --------

    public static void main(String[] args) throws InterruptedException {
        try (MarketDataProcessor processor = new MarketDataProcessor(1000)) {

            processor.subscribe(snapshot -> {
                System.out.printf(
                        "[%s] %s last=%s min=%s max=%s vol=%d vwap=%s trades=%d%n",
                        Instant.ofEpochMilli(snapshot.timestamp()),
                        snapshot.symbol(),
                        snapshot.lastPrice(),
                        snapshot.minPrice(),
                        snapshot.maxPrice(),
                        snapshot.totalVolume(),
                        snapshot.vwap(),
                        snapshot.tradeCount()
                );
            });

            // Simulated trades
            processor.onTrade(new Trade("AAPL", new BigDecimal("190.10"), 100, System.currentTimeMillis()));
            processor.onTrade(new Trade("AAPL", new BigDecimal("190.25"), 150, System.currentTimeMillis()));
            processor.onTrade(new Trade("MSFT", new BigDecimal("412.50"), 50, System.currentTimeMillis()));
            processor.onTrade(new Trade("AAPL", new BigDecimal("189.90"), 200, System.currentTimeMillis()));

            Thread.sleep(2500);
        }
    }
}
