Below is a solid **Rust** implementation of a real-time market data processor that:

- accepts market ticks,
- computes simple aggregates per symbol,
- streams updates to subscribers via channels.

It uses `tokio` for async concurrency and `broadcast` channels for pub-sub.

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::sync::broadcast;
use tokio::time::{self, Duration, Instant};

#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
    volume: f64,
    timestamp: Instant,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    last_price: f64,
    min_price: f64,
    max_price: f64,
    vwap: f64,
    total_volume: f64,
    tick_count: u64,
    window_start: Instant,
}

impl Aggregate {
    fn new(symbol: String, first_tick: &Tick) -> Self {
        Self {
            symbol,
            last_price: first_tick.price,
            min_price: first_tick.price,
            max_price: first_tick.price,
            vwap: first_tick.price,
            total_volume: first_tick.volume,
            tick_count: 1,
            window_start: first_tick.timestamp,
        }
    }

    fn update(&mut self, tick: &Tick) {
        self.last_price = tick.price;
        self.min_price = self.min_price.min(tick.price);
        self.max_price = self.max_price.max(tick.price);
        self.total_volume += tick.volume;
        self.tick_count += 1;
        // Incremental VWAP
        let current_notional = self.vwap * (self.total_volume - tick.volume);
        let new_notional = current_notional + tick.price * tick.volume;
        self.vwap = new_notional / self.total_volume;
    }
}

#[derive(Debug, Clone)]
struct AggregateUpdate {
    symbol: String,
    aggregate: Aggregate,
}

struct MarketDataProcessor {
    aggregates: Arc<Mutex<HashMap<String, Aggregate>>>,
    update_tx: broadcast::Sender<AggregateUpdate>,
}

impl MarketDataProcessor {
    fn new() -> Self {
        let (update_tx, _) = broadcast::channel(1024);
        Self {
            aggregates: Arc::new(Mutex::new(HashMap::new())),
            update_tx,
        }
    }

    fn subscribe(&self) -> broadcast::Receiver<AggregateUpdate> {
        self.update_tx.subscribe()
    }

    fn process_tick(&self, tick: Tick) {
        let mut map = self.aggregates.lock().unwrap();

        let entry = map.entry(tick.symbol.clone());
        let aggregate = entry.or_insert_with(|| Aggregate::new(tick.symbol.clone(), &tick));
        if aggregate.tick_count > 1 || aggregate.last_price != tick.price {
            aggregate.update(&tick);
        }

        let _ = self.update_tx.send(AggregateUpdate {
            symbol: tick.symbol,
            aggregate: aggregate.clone(),
        });
    }
}

