use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::sync::broadcast;
use tokio::time::{sleep, Duration};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Tick {
    symbol: String,
    price: f64,
    quantity: f64,
    timestamp_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Aggregate {
    symbol: String,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
    volume: f64,
    vwap: f64,
    tick_count: u64,
    last_timestamp_ms: u64,
}

impl Aggregate {
    fn new(tick: &Tick) -> Self {
        Self {
            symbol: tick.symbol.clone(),
            open: tick.price,
            high: tick.price,
            low: tick.price,
            close: tick.price,
            volume: tick.quantity,
            vwap: tick.price,
            tick_count: 1,
            last_timestamp_ms: tick.timestamp_ms,
        }
    }

    fn update(&mut self, tick: &Tick) {
        self.high = self.high.max(tick.price);
        self.low = self.low.min(tick.price);
        self.close = tick.price;
        self.volume += tick.quantity;

        // Simple VWAP update using running price * qty / qty sum
        let previous_notional = self.vwap * (self.volume - tick.quantity);
        let new_notional = previous_notional + (tick.price * tick.quantity);
        self.vwap = if self.volume > 0.0 {
            new_notional / self.volume
        } else {
            tick.price
        };

        self.tick_count += 1;
        self.last_timestamp_ms = tick.timestamp_ms;
    }
}

struct MarketDataProcessor {
    aggregates: HashMap<String, Aggregate>,
    tx: broadcast::Sender<Aggregate>,
}

impl MarketDataProcessor {
    fn new(tx: broadcast::Sender<Aggregate>) -> Self {
        Self {
            aggregates: HashMap::new(),
            tx,
        }
    }

    fn process_tick(&mut self, tick: Tick) {
        let entry = self
            .aggregates
            .entry(tick.symbol.clone())
            .or_insert_with(|| Aggregate::new(&tick));

        if entry.tick_count == 1 && entry.open == tick.price && entry.close == tick.price {
            // already initialized by Aggregate::new
        } else {
            entry.update(&tick);
        }

        // Broadcast updated aggregate to all subscribers
        let _ = self.tx.send(entry.clone());
    }
}

