        match rx.recv().await {
            Ok(agg) => {
                println!(
                    "[{}] {} => O:{:.2} H:{:.2} L:{:.2} C:{:.2} V:{:.2} VWAP:{:.4} ticks:{} ts:{}",
                    name,
