use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::sync::broadcast;
use tokio::time::{self, Duration};

#[derive(Debug, Clone)]
pub struct MarketTick {
    pub symbol: String,
    pub price: f64,
    pub volume: u64,
    pub timestamp_ms: u64,
}

#[derive(Debug, Clone)]
pub struct PriceAggregate {
    pub symbol: String,
    pub last_price: f64,
    pub count: u64,
    pub sum: f64,
    pub min_price: f64,
    pub max_price: f64,
    pub average_price: f64,
    pub total_volume: u64,
    pub timestamp_ms: u64,
}

impl PriceAggregate {
    pub fn new(symbol: String, price: f64, volume: u64, timestamp_ms: u64) -> Self {
        Self {
            symbol,
            last_price: price,
            count: 1,
            sum: price,
            min_price: price,
            max_price: price,
            average_price: price,
            total_volume: volume,
            timestamp_ms,
        }
    }

    pub fn update(&mut self, price: f64, volume: u64, timestamp_ms: u64) {
        self.last_price = price;
        self.count += 1;
        self.sum += price;
        self.min_price = self.min_price.min(price);
        self.max_price = self.max_price.max(price);
        self.average_price = self.sum / self.count as f64;
        self.total_volume += volume;
        self.timestamp_ms = timestamp_ms;
    }
}

pub struct MarketDataProcessor {
    aggregates: Arc<Mutex<HashMap<String, PriceAggregate>>>,
    broadcaster: broadcast::Sender<PriceAggregate>,
}

impl MarketDataProcessor {
    pub fn new(buffer_size: usize) -> Self {
        let (broadcaster, _) = broadcast::channel(buffer_size);
        Self {
            aggregates: Arc::new(Mutex::new(HashMap::new())),
            broadcaster,
        }
    }

    pub fn subscribe(&self) -> broadcast::Receiver<PriceAggregate> {
        self.broadcaster.subscribe()
    }

    pub fn ingest_tick(&self, tick: MarketTick) {
        let mut aggregates = self.aggregates.lock().unwrap();

        let updated = if let Some(agg) = aggregates.get_mut(&tick.symbol) {
            agg.update(tick.price, tick.volume, tick.timestamp_ms);
            agg.clone()
        } else {
            let agg = PriceAggregate::new(
                tick.symbol.clone(),
                tick.price,
                tick.volume,
                tick.timestamp_ms,
            );
            aggregates.insert(tick.symbol.clone(), agg.clone());
            agg
        };

        let _ = self.broadcaster.send(updated);
    }

    pub fn get_aggregate(&self, symbol: &str) -> Option<PriceAggregate> {
        let aggregates = self.aggregates.lock().unwrap();
        aggregates.get(symbol).cloned()
    }
}

