## Rust implementation

```rust
use std::collections::{HashMap, VecDeque};
use std::sync::{
    Arc, Mutex,
    mpsc::{self, Receiver, Sender},
};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone)]
struct PriceTick {
    symbol: String,
    price: f64,
    timestamp_ms: u64,
}

#[derive(Debug, Clone)]
struct AggregateUpdate {
    symbol: String,
    window_ms: u64,
    count: usize,
    min: f64,
    max: f64,
    avg: f64,
    last_price: f64,
    timestamp_ms: u64,
}

#[derive(Debug)]
struct RollingWindow {
    window_ms: u64,
    samples: VecDeque<PriceTick>,
    sum: f64,
    min: f64,
    max: f64,
}

impl RollingWindow {
    fn new(window_ms: u64) -> Self {
        Self {
            window_ms,
            samples: VecDeque::new(),
            sum: 0.0,
            min: f64::INFINITY,
            max: f64::NEG_INFINITY,
        }
    }

    fn insert(&mut self, tick: PriceTick) -> AggregateUpdate {
        self.sum += tick.price;
        self.min = self.min.min(tick.price);
        self.max = self.max.max(tick.price);
        self.samples.push_back(tick.clone());

        self.evict_old(tick.timestamp_ms);

        self.recompute_min_max_if_needed();

        let count = self.samples.len();
        let avg = if count > 0 { self.sum / count as f64 } else { 0.0 };
        let last_price = tick.price;

        AggregateUpdate {
            symbol: tick.symbol,
            window_ms: self.window_ms,
            count,
            min: if count > 0 { self.min } else { 0.0 },
            max: if count > 0 { self.max } else { 0.0 },
            avg,
            last_price,
            timestamp_ms: tick.timestamp_ms,
        }
    }

    fn evict_old(&mut self, now_ms: u64) {
        while let Some(front) = self.samples.front() {
            if now_ms.saturating_sub(front.timestamp_ms) > self.window_ms {
                let removed = self.samples.pop_front().unwrap();
                self.sum -= removed.price;
            } else {
                break;
            }
        }
    }

    fn recompute_min_max_if_needed(&mut self) {
        if self.samples.is_empty() {
            self.min = f64::INFINITY;
            self.max = f64::NEG_INFINITY;
            return;
        }

        // Recompute min/max after eviction. Simpler initial approach; can optimize later.
        let mut min_v = f64::INFINITY;
        let mut max_v = f64::NEG_INFINITY;
        for s in self.samples.iter() {
            min_v = min_v.min(s.price);
            max_v = max_v.max(s.price);
        }
        self.min = min_v;
        self.max = max_v;
    }
}

struct MarketDataProcessor {
    window_ms: u64,
    input_rx: Receiver<PriceTick>,
    subscribers: Arc<Mutex<Vec<Sender<AggregateUpdate>>>>,
}

impl MarketDataProcessor {
    fn new(window_ms: u64, input_rx: Receiver<PriceTick>) -> Self {
        Self {
            window_ms,
            input_rx,
            subscribers: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn subscribe(&self) -> Receiver<AggregateUpdate> {
        let (tx, rx) = mpsc::channel();
        self.subscribers.lock().unwrap().push(tx);
        rx
    }

    fn start(self) -> thread::JoinHandle<()> {
        let subscribers = self.subscribers.clone();
        let window_ms = self.window_ms;

        thread::spawn(move || {
            let mut state: HashMap<String, RollingWindow> = HashMap::new();

            while let Ok(tick) = self.input_rx.recv() {
                let symbol = tick.symbol.clone();

                let window = state
                    .entry(symbol.clone())
                    .or_insert_with(|| RollingWindow::new(window_ms));

                let update = window.insert(tick);

                // Broadcast to all subscribers, removing dead ones
                let mut subs = subscribers.lock().unwrap();
                subs.retain(|sub| sub.send(update.clone()).is_ok());
            }
        })
    }
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::ZERO)
        .as_millis() as u64
}

fn main() {
    let (tx, rx) = mpsc::channel::<PriceTick>();

    let processor = MarketDataProcessor::new(5_000, rx);

    // Subscriber 1
    let sub1 = processor.subscribe();
    thread::spawn(move || {
        while let Ok(update) = sub1.recv() {
            println!("[SUB1] {:?}", update);
        }
    });

    // Subscriber 2
    let sub2 = processor.subscribe();
    thread::spawn(move || {
        while let Ok(update) = sub2.recv() {
            println!("[SUB2] {:?}", update);
        }
    });

    let _processor_handle = processor.start();

    // Simulated market data feed
    let symbols = vec!["AAPL", "MSFT", "GOOG"];

    for i in 0..20 {
        let symbol = symbols[i % symbols.len()].to_string();
        let price = 100.0 + (i as f64 * 0.5);

