```rust
use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};

use tokio::sync::{broadcast, mpsc};

#[derive(Debug, Clone)]
pub struct MarketTick {
    pub symbol: String,
    pub price: f64,
    pub timestamp_ms: u64,
}

#[derive(Debug, Clone)]
pub struct PriceAggregate {
    pub symbol: String,
    pub count: u64,
    pub min: f64,
    pub max: f64,
    pub sum: f64,
    pub avg: f64,
    pub last_price: f64,
    pub updated_at_ms: u64,
}

impl PriceAggregate {
    pub fn new(symbol: String, price: f64, timestamp_ms: u64) -> Self {
        Self {
            symbol,
            count: 1,
            min: price,
            max: price,
            sum: price,
            avg: price,
            last_price: price,
            updated_at_ms: timestamp_ms,
        }
    }

    pub fn update(&mut self, price: f64, timestamp_ms: u64) {
        self.count += 1;
        self.min = self.min.min(price);
        self.max = self.max.max(price);
        self.sum += price;
        self.avg = self.sum / self.count as f64;
        self.last_price = price;
        self.updated_at_ms = timestamp_ms;
    }
}

pub struct MarketDataProcessor {
    input_tx: mpsc::Sender<MarketTick>,
    aggregate_tx: broadcast::Sender<PriceAggregate>,
}

impl MarketDataProcessor {
    pub fn new(buffer_size: usize) -> (Self, mpsc::Receiver<MarketTick>) {
        let (input_tx, input_rx) = mpsc::channel(buffer_size);
        let (aggregate_tx, _) = broadcast::channel(buffer_size);

        (
            Self {
                input_tx,
                aggregate_tx,
            },
            input_rx,
        )
    }

    pub fn input_sender(&self) -> mpsc::Sender<MarketTick> {
        self.input_tx.clone()
    }

    pub fn subscribe(&self) -> broadcast::Receiver<PriceAggregate> {
        self.aggregate_tx.subscribe()
    }

    pub async fn run(
        mut input_rx: mpsc::Receiver<MarketTick>,
        aggregate_tx: broadcast::Sender<PriceAggregate>,
    ) {
        let mut state: HashMap<String, PriceAggregate> = HashMap::new();

        while let Some(tick) = input_rx.recv().await {
            let agg = state.entry(tick.symbol.clone()).or_insert_with(|| {
                PriceAggregate::new(tick.symbol.clone(), tick.price, tick.timestamp_ms)
            });

            // If this is the first update, the entry already contains the tick.
            // Otherwise, apply an update.
            if agg.count > 1 || agg.last_price != tick.price || agg.updated_at_ms != tick.timestamp_ms {
                agg.update(tick.price, tick.timestamp_ms);
            }

            // Ignore send errors if there are no active subscribers.
            let _ = aggregate_tx.send(agg.clone());
        }
    }
}

// Helper to generate timestamps in milliseconds
pub fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}
```

