use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::sync::broadcast;
use tokio::time::{self, Duration};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Tick {
    pub symbol: String,
    pub price: f64,
    pub size: f64,
    pub ts: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PriceAggregate {
    pub symbol: String,
    pub window_id: u64,
    pub window_start: DateTime<Utc>,
    pub window_end: DateTime<Utc>,
    pub open: f64,
    pub high: f64,
    pub low: f64,
    pub close: f64,
    pub volume: f64,
    pub vwap: f64,
    pub trade_count: u64,
}

#[derive(Debug, Clone)]
struct AggregateState {
    window_id: u64,
    window_start: DateTime<Utc>,
    window_end: DateTime<Utc>,
    open: Option<f64>,
    high: f64,
    low: f64,
    close: Option<f64>,
    volume: f64,
    notional: f64,
    trade_count: u64,
}

impl AggregateState {
    fn new(window_id: u64, window_start: DateTime<Utc>, window_end: DateTime<Utc>) -> Self {
        Self {
            window_id,
            window_start,
            window_end,
            open: None,
            high: f64::MIN,
            low: f64::MAX,
            close: None,
            volume: 0.0,
            notional: 0.0,
            trade_count: 0,
        }
    }

    fn update(&mut self, tick: &Tick) {
        if self.open.is_none() {
            self.open = Some(tick.price);
        }
        self.high = self.high.max(tick.price);
        self.low = self.low.min(tick.price);
        self.close = Some(tick.price);
        self.volume += tick.size;
        self.notional += tick.price * tick.size;
        self.trade_count += 1;
    }

    fn finalize(&self, symbol: String) -> Option<PriceAggregate> {
        let open = self.open?;
        let close = self.close?;
        let vwap = if self.volume > 0.0 {
            self.notional / self.volume
        } else {
            0.0
        };

        Some(PriceAggregate {
            symbol,
            window_id: self.window_id,
            window_start: self.window_start,
            window_end: self.window_end,
            open,
            high: self.high,
            low: self.low,
            close,
            volume: self.volume,
            vwap,
            trade_count: self.trade_count,
        })
    }
}

pub struct MarketDataProcessor {
    tick_tx: tokio::sync::mpsc::Sender<Tick>,
    aggregate_tx: broadcast::Sender<PriceAggregate>,
}

impl MarketDataProcessor {
    pub fn new(window_size_secs: u64) -> Self {
        let (tick_tx, mut tick_rx) = tokio::sync::mpsc::channel::<Tick>(10_000);
        let (aggregate_tx, _) = broadcast::channel::<PriceAggregate>(10_000);

        let aggregate_tx_clone = aggregate_tx.clone();

        tokio::spawn(async move {
            let mut states: HashMap<String, AggregateState> = HashMap::new();
            let mut ticker = time::interval(Duration::from_secs(window_size_secs));
            let mut window_id: u64 = 0;

            loop {
                tokio::select! {
                    maybe_tick = tick_rx.recv() => {
                        match maybe_tick {
                            Some(tick) => {
                                let entry = states.entry(tick.symbol.clone()).or_insert_with(|| {
                                    let now = Utc::now();
                                    AggregateState::new(
                                        window_id,
                                        now,
                                        now + chrono::Duration::seconds(window_size_secs as i64),
                                    )
                                });

                                // If tick belongs to next window, finalize current one and reset.
                                if tick.ts >= entry.window_end {
                                    if let Some(agg) = entry.finalize(tick.symbol.clone()) {
                                        let _ = aggregate_tx_clone.send(agg);
                                    }

                                    window_id += 1;
                                    let now = tick.ts;
                                    *entry = AggregateState::new(
                                        window_id,
                                        now,
                                        now + chrono::Duration::seconds(window_size_secs as i64),
                                    );
                                }

                                entry.update(&tick);
                            }
                            None => break,
                        }
                    }

                    _ = ticker.tick() => {
                        // Periodically flush all current aggregates
                        let mut finalized = Vec::new();
                        for (symbol, state) in states.iter() {
                            if let Some(agg) = state.finalize(symbol.clone()) {
                                finalized.push(agg);
                            }
                        }

                        for agg in finalized {
                            let _ = aggregate_tx_clone.send(agg);
                        }

                        states.clear();
                        window_id += 1;
                    }
                }
            }
        });

        Self {
            tick_tx,
            aggregate_tx,
        }
    }

    pub async fn ingest_tick(&self, tick: Tick) -> Result<(), tokio::sync::mpsc::error::SendError<Tick>> {
        self.tick_tx.send(tick).await
    }

    pub fn subscribe(&self) -> broadcast::Receiver<PriceAggregate> {
        self.aggregate_tx.subscribe()
    }
}

#[tokio::main]
async fn main() {
    let processor = MarketDataProcessor::new(5);

    // Subscriber 1
    let mut sub1 = processor.subscribe();
    tokio::spawn(async move {
        while let Ok(agg) = sub1.recv().await {
            println!("[SUB1] {:?}", agg);
        }
    });

    // Subscriber 2
    let mut sub2 = processor.subscribe();
    tokio::spawn(async move {
        while let Ok(agg) = sub2.recv().await {
            println!("[SUB2] {:?}", agg);
        }
    });

    // Simulate incoming ticks
    for i in 0..20 {
        let tick = Tick {
            symbol: if i % 2 == 0 { "AAPL".into() } else { "MSFT".into() },
            price: 100.0 + (i as f64) * 0.5,
            size: 10.0 + (i as f64),
            ts: Utc::now(),
        };

        if let Err(e) = processor.ingest_tick(tick).await {
            eprintln!("Failed to ingest tick: {}", e);
        }

        time::sleep(Duration::from_millis(300)).await;
    }

    time::sleep(Duration::from_secs(10)).await;
}
