use std::collections::HashMap;
use tokio::sync::{broadcast, mpsc};
use tokio::time::{self, Duration};

#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    last: f64,
    min: f64,
    max: f64,
    avg: f64,
    count: u64,
}

#[derive(Debug)]
struct AggregateState {
    last: f64,
    min: f64,
    max: f64,
    sum: f64,
    count: u64,
}

impl AggregateState {
    fn new(price: f64) -> Self {
        Self {
            last: price,
            min: price,
            max: price,
            sum: price,
            count: 1,
        }
    }

    fn update(&mut self, price: f64) {
        self.last = price;
        self.min = self.min.min(price);
        self.max = self.max.max(price);
        self.sum += price;
        self.count += 1;
    }

    fn to_aggregate(&self, symbol: String) -> Aggregate {
        Aggregate {
            symbol,
            last: self.last,
            min: self.min,
            max: self.max,
            avg: self.sum / self.count as f64,
            count: self.count,
        }
    }
}

async fn processor(
    mut tick_rx: mpsc::Receiver<Tick>,
    agg_tx: broadcast::Sender<Aggregate>,
) {
    let mut states: HashMap<String, AggregateState> = HashMap::new();

    while let Some(tick) = tick_rx.recv().await {
        let state = states
            .entry(tick.symbol.clone())
            .or_insert_with(|| AggregateState::new(tick.price));

        if state.count == 1 && state.last == tick.price {
            // first tick already initialized
        } else {
            state.update(tick.price);
        }

        let agg = state.to_aggregate(tick.symbol);
        let _ = agg_tx.send(agg);
    }
}

#[tokio::main]
async fn main() {
    let (tick_tx, tick_rx) = mpsc::channel::<Tick>(1024);
    let (agg_tx, _) = broadcast::channel::<Aggregate>(1024);

    // Start processor
    tokio::spawn(processor(tick_rx, agg_tx.clone()));

    // Subscriber 1
    {
        let mut sub = agg_tx.subscribe();
        tokio::spawn(async move {
            while let Ok(agg) = sub.recv().await {
                println!("[subscriber-1] {:?}", agg);
            }
        });
    }

    // Subscriber 2
    {
        let mut sub = agg_tx.subscribe();
        tokio::spawn(async move {
            while let Ok(agg) = sub.recv().await {
                println!("[subscriber-2] {:?}", agg);
            }
        });
    }

    // Simulate incoming market ticks
    tokio::spawn(async move {
        let symbols = ["AAPL", "MSFT", "GOOG"];
        let mut i = 0usize;

        loop {
            let symbol = symbols[i % symbols.len()].to_string();
            let price = 100.0 + ((i % 20) as f64) * 0.5;

            let tick = Tick { symbol, price };
            if tick_tx.send(tick).await.is_err() {
                break;
            }

            i += 1;
            time::sleep(Duration::from_millis(200)).await;
        }
    });

    // Keep running
    loop {
        time::sleep(Duration::from_secs(60)).await;
    }
}
