use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{broadcast, Mutex};
use tokio::time::{sleep, Duration};

#[derive(Debug, Clone)]
struct PriceUpdate {
    symbol: String,
    price: f64,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    count: u64,
    sum: f64,
    min: f64,
    max: f64,
    avg: f64,
}

#[derive(Debug)]
struct Stats {
    count: u64,
    sum: f64,
    min: f64,
    max: f64,
}

impl Stats {
    fn new(price: f64) -> Self {
        Self {
            count: 1,
            sum: price,
            min: price,
            max: price,
        }
    }

    fn update(&mut self, price: f64) {
        self.count += 1;
        self.sum += price;
        self.min = self.min.min(price);
        self.max = self.max.max(price);
    }

    fn to_aggregate(&self, symbol: String) -> Aggregate {
        Aggregate {
            symbol,
            count: self.count,
            sum: self.sum,
            min: self.min,
            max: self.max,
            avg: self.sum / self.count as f64,
        }
    }
}

#[tokio::main]
async fn main() {
    let (update_tx, mut update_rx) = broadcast::channel::<PriceUpdate>(1024);
    let (agg_tx, _) = broadcast::channel::<Aggregate>(1024);

    let state: Arc<Mutex<HashMap<String, Stats>>> = Arc::new(Mutex::new(HashMap::new()));

    // Processor task
    {
        let state = Arc::clone(&state);
        let agg_tx = agg_tx.clone();

        tokio::spawn(async move {
            while let Ok(update) = update_rx.recv().await {
                let mut state = state.lock().await;

                let stats = state
                    .entry(update.symbol.clone())
                    .and_modify(|s| s.update(update.price))
                    .or_insert_with(|| Stats::new(update.price));

                let aggregate = stats.to_aggregate(update.symbol.clone());
                let _ = agg_tx.send(aggregate);
            }
        });
    }

    // Subscriber 1
    {
        let mut sub = agg_tx.subscribe();
        tokio::spawn(async move {
            while let Ok(agg) = sub.recv().await {
