                    "[sub1] {} count={} sum={} min={} max={} avg={}",
                    agg.symbol, agg.count, agg.sum, agg.min, agg.max, agg.avg
                );
            }
        });
    }

    // Subscriber 2
    {
        let mut sub = agg_tx.subscribe();
        tokio::spawn(async move {
            while let Ok(agg) = sub.recv().await {
                println!("[sub2] {:?}", agg);
            }
        });
    }

    // Simulated market feed
    let feed = vec![
        PriceUpdate { symbol: "AAPL".into(), price: 190.0 },
        PriceUpdate { symbol: "AAPL".into(), price: 191.5 },
        PriceUpdate { symbol: "MSFT".into(), price: 400.0 },
        PriceUpdate { symbol: "AAPL".into(), price: 189.8 },
        PriceUpdate { symbol: "MSFT".into(), price: 402.2 },
    ];

    for update in feed {
        let _ = update_tx.send(update);
        sleep(Duration::from_millis(500)).await;
    }

