use std::collections::HashMap;
use std::sync::Arc;

use futures::StreamExt;
use serde::{Deserialize, Serialize};
use tokio::sync::{broadcast, Mutex};
use warp::Filter;

#[derive(Debug, Clone, Deserialize)]
struct Tick {
    symbol: String,
    price: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
struct Aggregate {
    symbol: String,
    count: u64,
    sum: f64,
    min: f64,
    max: f64,
    average: f64,
}

impl Aggregate {
    fn update(&mut self, price: f64) {
        if self.count == 0 {
            self.min = price;
            self.max = price;
        } else {
            if price < self.min {
                self.min = price;
            }
            if price > self.max {
                self.max = price;
            }
        }

        self.count += 1;
        self.sum += price;
        self.average = self.sum / self.count as f64;
    }
}

type Aggregates = Arc<Mutex<HashMap<String, Aggregate>>>;

#[tokio::main]
async fn main() {
    let aggregates: Aggregates = Arc::new(Mutex::new(HashMap::new()));
    let (tx, _rx) = broadcast::channel::<String>(1024);

    let agg_filter = warp::any().map({
        let aggregates = aggregates.clone();
        move || aggregates.clone()
    });

    let tx_filter = warp::any().map({
        let tx = tx.clone();
        move || tx.clone()
    });

    // POST /tick
    let tick_route = warp::path("tick")
        .and(warp::post())
        .and(warp::body::json())
        .and(agg_filter.clone())
        .and(tx_filter.clone())
        .and_then(handle_tick);

    // GET /subscribe
    let subscribe_route = warp::path("subscribe")
        .and(warp::get())
        .and(tx_filter.clone())
        .map(|tx: broadcast::Sender<String>| {
            let rx = tx.subscribe();
            warp::ws::Ws::from_upgrade(move |websocket| async move {
                use warp::ws::Message;

                let (mut ws_tx, mut ws_rx) = websocket.split();
                let mut rx = rx;

                let send_task = tokio::spawn(async move {
                    while let Ok(msg) = rx.recv().await {
                        if ws_tx.send(Message::text(msg)).await.is_err() {
                            break;
                        }
                    }
                });

                let recv_task = tokio::spawn(async move {
                    while ws_rx.next().await.is_some() {}
                });

                let _ = tokio::join!(send_task, recv_task);
            })
        });

    let routes = tick_route.or(subscribe_route);

    println!("Listening on http://127.0.0.1:3030");
    warp::serve(routes).run(([127, 0, 0, 1], 3030)).await;
}

async fn handle_tick(
    tick: Tick,
    aggregates: Aggregates,
    tx: broadcast::Sender<String>,
) -> Result<impl warp::Reply, warp::Rejection> {
    let mut map = aggregates.lock().await;

    let agg = map.entry(tick.symbol.clone()).or_insert_with(|| Aggregate {
        symbol: tick.symbol.clone(),
        ..Default::default()
    });

    agg.update(tick.price);

    let payload = serde_json::to_string(&agg).unwrap();
    let _ = tx.send(payload.clone());

    Ok(warp::reply::json(&agg))
}
```

