use std::collections::HashMap;
use tokio::sync::mpsc;
use tokio::time::{self, Duration};

#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
    volume: f64,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    tick_count: u64,
    total_volume: f64,
    vwap: f64,
}

struct Processor {
    state: HashMap<String, (u64, f64, f64)>, // symbol -> (tick_count, total_volume, total_price_x_volume)
    subscribers: Vec<mpsc::UnboundedSender<Aggregate>>,
}

impl Processor {
    fn new() -> Self {
        Self {
            state: HashMap::new(),
            subscribers: Vec::new(),
        }
    }

    fn subscribe(&mut self) -> mpsc::UnboundedReceiver<Aggregate> {
        let (tx, rx) = mpsc::unbounded_channel();
        self.subscribers.push(tx);
        rx
    }

    fn on_tick(&mut self, tick: Tick) {
        let entry = self.state.entry(tick.symbol.clone()).or_insert((0, 0.0, 0.0));

        entry.0 += 1;
        entry.1 += tick.volume;
        entry.2 += tick.price * tick.volume;

        let agg = Aggregate {
            symbol: tick.symbol,
            tick_count: entry.0,
            total_volume: entry.1,
            vwap: if entry.1 > 0.0 { entry.2 / entry.1 } else { 0.0 },
        };

        self.publish(agg);
    }

    fn publish(&mut self, agg: Aggregate) {
        self.subscribers.retain(|sub| sub.send(agg.clone()).is_ok());
    }
}

#[tokio::main]
async fn main() {
    let mut processor = Processor::new();

    // Subscriber 1
    let mut sub1 = processor.subscribe();
    tokio::spawn(async move {
        while let Some(agg) = sub1.recv().await {
            println!("[sub1] {:?}", agg);
        }
    });

    // Subscriber 2
    let mut sub2 = processor.subscribe();
    tokio::spawn(async move {
        while let Some(agg) = sub2.recv().await {
            println!("[sub2] {:?}", agg);
        }
    });

    // Simulated market data feed
    let mut interval = time::interval(Duration::from_millis(500));
    let ticks = vec![
        Tick { symbol: "AAPL".into(), price: 190.0, volume: 100.0 },
        Tick { symbol: "AAPL".into(), price: 191.0, volume: 120.0 },
        Tick { symbol: "MSFT".into(), price: 420.0, volume: 80.0 },
        Tick { symbol: "AAPL".into(), price: 189.5, volume: 90.0 },
        Tick { symbol: "MSFT".into(), price: 421.5, volume: 60.0 },
    ];

    for tick in ticks {
        interval.tick().await;
        processor.on_tick(tick);
    }

    // Give subscribers time to print
    time::sleep(Duration::from_secs(1)).await;
}
```

