## Go implementation

```go
package main

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

type Tick struct {
	Symbol string
	Price  float64
	Volume int
	Time   time.Time
}

type Aggregate struct {
	Symbol      string
	LastPrice   float64
	TotalVolume int
	AvgPrice    float64
	HighPrice   float64
	LowPrice    float64
	UpdatedAt   time.Time
}

type Subscriber chan Aggregate

type Processor struct {
	mu          sync.Mutex
	state       map[string]*aggState
	subscribers []Subscriber
}

type aggState struct {
	lastPrice   float64
	totalVolume int
	totalValue  float64
	highPrice   float64
	lowPrice    float64
}

func NewProcessor() *Processor {
	return &Processor{
		state: make(map[string]*aggState),
	}
}

func (p *Processor) Subscribe() Subscriber {
	ch := make(Subscriber, 16)
	p.mu.Lock()
	p.subscribers = append(p.subscribers, ch)
	p.mu.Unlock()
	return ch
}

func (p *Processor) ProcessTick(t Tick) {
	p.mu.Lock()

	s, ok := p.state[t.Symbol]
	if !ok {
		s = &aggState{
			highPrice: t.Price,
			lowPrice:  t.Price,
		}
		p.state[t.Symbol] = s
	}

	s.lastPrice = t.Price
	s.totalVolume += t.Volume
	s.totalValue += t.Price * float64(t.Volume)

	if t.Price > s.highPrice {
		s.highPrice = t.Price
	}
	if t.Price < s.lowPrice {
		s.lowPrice = t.Price
	}

	agg := Aggregate{
		Symbol:      t.Symbol,
		LastPrice:   s.lastPrice,
		TotalVolume: s.totalVolume,
		AvgPrice:    s.totalValue / float64(s.totalVolume),
		HighPrice:   s.highPrice,
		LowPrice:    s.lowPrice,
		UpdatedAt:   time.Now(),
	}

	// Copy subscribers so we don't hold the lock while sending.
	subs := append([]Subscriber(nil), p.subscribers...)
	p.mu.Unlock()

	for _, sub := range subs {
		select {
		case sub <- agg:
		default:
			// Drop if subscriber is slow to keep processor real-time.
		}
	}
}

func main() {
	rand.Seed(time.Now().UnixNano())

	processor := NewProcessor()

	// Subscriber 1
	sub1 := processor.Subscribe()
	go func() {
		for agg := range sub1 {
			fmt.Printf("[sub1] %s price=%.2f avg=%.2f vol=%d high=%.2f low=%.2f\n",
				agg.Symbol, agg.LastPrice, agg.AvgPrice, agg.TotalVolume, agg.HighPrice, agg.LowPrice)
		}
	}()

	// Subscriber 2
	sub2 := processor.Subscribe()
	go func() {
		for agg := range sub2 {
			fmt.Printf("[sub2] %s updated at %s\n", agg.Symbol, agg.UpdatedAt.Format(time.RFC3339Nano))
		}
	}()

	symbols := []string{"AAPL", "MSFT", "GOOG"}

	// Simulated market data feed
	for i := 0; i < 20; i++ {
		tick := Tick{
			Symbol: symbols[rand.Intn(len(symbols))],
			Price:  100 + rand.Float64()*20,
			Volume: 1 + rand.Intn(100),
			Time:   time.Now(),
		}

		processor.ProcessTick(tick)
		time.Sleep(200 * time.Millisecond)
	}

	// Give goroutines time to print before exit
	time.Sleep(1 * time.Second)
}
