```rust
use crossbeam_channel::{bounded, Receiver, Sender, TryRecvError, TrySendError};
use dashmap::DashMap;
use parking_lot::Mutex;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    route_key: u32,
    created_at: Instant,
    payload: Arc<[u8]>,
}

#[derive(Default)]
struct Metrics {
    routed: AtomicU64,
    dropped: AtomicU64,
    processed: AtomicU64,
    total_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn record_routed(&self) {
        self.routed.fetch_add(1, Ordering::Relaxed);
    }

    fn record_dropped(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }

    fn record_processed(&self, latency: Duration) {
        self.processed.fetch_add(1, Ordering::Relaxed);

        let ns = latency.as_nanos() as u64;
        self.total_latency_ns.fetch_add(ns, Ordering::Relaxed);

        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(prev) => current = prev,
            }
        }
    }

    fn snapshot(&self) -> (u64, u64, u64, u64, u64) {
        (
            self.routed.load(Ordering::Relaxed),
            self.dropped.load(Ordering::Relaxed),
            self.processed.load(Ordering::Relaxed),
            self.total_latency_ns.load(Ordering::Relaxed),
            self.max_latency_ns.load(Ordering::Relaxed),
        )
    }
}

struct Router {
    partitions: Vec<Sender<Message>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(partitions: Vec<Sender<Message>>, metrics: Arc<Metrics>) -> Self {
        Self { partitions, metrics }
    }

    fn route(&self, msg: Message) {
        let idx = (msg.route_key as usize) % self.partitions.len();
        match self.partitions[idx].try_send(msg) {
            Ok(_) => self.metrics.record_routed(),
            Err(TrySendError::Full(_)) => self.metrics.record_dropped(),
            Err(TrySendError::Disconnected(_)) => self.metrics.record_dropped(),
        }
    }
}

fn worker_loop(
    id: usize,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        match rx.try_recv() {
            Ok(msg) => {
                // Simulate message handling work
                let latency = msg.created_at.elapsed();
                metrics.record_processed(latency);

                // Example: decode / transform / forward / persist
                // Keep this path extremely lean in real use.
                if msg.id % 10_000_000 == 0 {
                    println!("worker {} processed message {}", id, msg.id);
                }
            }
            Err(TryRecvError::Empty) => {
                thread::yield_now();
            }
            Err(TryRecvError::Disconnected) => break,
        }
    }
}

fn metrics_loop(metrics: Arc<Metrics>, running: Arc<AtomicBool>) {
    let mut last = Instant::now();
    let mut last_processed = 0;

    while running.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let now = Instant::now();
        let (routed, dropped, processed, total_ns, max_ns) = metrics.snapshot();

        let elapsed = now.duration_since(last).as_secs_f64();
        let processed_delta = processed - last_processed;
        let throughput = (processed_delta as f64 / elapsed) as u64;

        let avg_latency_ns = if processed > 0 {
            total_ns / processed
        } else {
            0
        };

        println!(
            "[metrics] throughput={} msg/s routed={} dropped={} processed={} avg_latency={}us max_latency={}us",
            throughput,
            routed,
            dropped,
            processed,
            avg_latency_ns / 1_000,
            max_ns / 1_000
        );

        last = now;
        last_processed = processed;
    }
}

fn producer_loop(router: Arc<Router>, running: Arc<AtomicBool>) {
    let mut id = 0u64;

    while running.load(Ordering::Relaxed) {
        // In a real system, payloads would come from network / Kafka / IPC / etc.
        // Keep allocations minimal. Arc<[u8]> is used to allow cheap cloning.
        let payload: Arc<[u8]> = Arc::from(vec![0u8; 128].into_boxed_slice());

        let msg = Message {
            id,
            route_key: (id % 1024) as u32,
            created_at: Instant::now(),
            payload,
        };

        router.route(msg);
        id += 1;
    }
}

fn main() {
    let partitions = 8;
    let queue_size = 65_536;

    let metrics = Arc::new(Metrics::default());
    let running = Arc::new(AtomicBool::new(true));

    let mut senders = Vec::with_capacity(partitions);
    let mut receivers = Vec::with_capacity(partitions);

    for _ in 0..partitions {
        let (tx, rx) = bounded::<Message>(queue_size);
        senders.push(tx);
        receivers.push(rx);
    }

    let router = Arc::new(Router::new(senders, metrics.clone()));

    // Spawn workers
    let mut handles = Vec::new();
    for (i, rx) in receivers.into_iter().enumerate() {
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || worker_loop(i, rx, metrics, running)));
    }

    // Metrics thread
    {
        let metrics = metrics.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || metrics_loop(metrics, running)));
    }

    // Producer thread
    {
        let router = router.clone();
        let running = running.clone();
        handles.push(thread::spawn(move || producer_loop(router, running)));
    }

    // Run for a while
    thread::sleep(Duration::from_secs(10));
    running.store(false, Ordering::Relaxed);

    for h in handles {
        let _ = h.join();
    }

    let (routed, dropped, processed, total_ns, max_ns) = metrics.snapshot();
    let avg_latency_ns = if processed > 0 { total_ns / processed } else { 0 };

    println!("--- final ---");
    println!("routed:   {}", routed);
    println!("dropped:  {}", dropped);
    println!("processed: {}", processed);
    println!("avg latency: {} us", avg_latency_ns / 1_000);
    println!("max latency: {} us", max_ns / 1_000);
}
```

