```rust
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

use crossbeam_channel::{bounded, Receiver, Sender};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    created_at: Instant,
    payload: Arc<[u8]>,
}

#[derive(Debug)]
struct LatencyStats {
    count: AtomicU64,
    total_ns: AtomicU64,
    max_ns: AtomicU64,
}

impl LatencyStats {
    fn new() -> Self {
        Self {
            count: AtomicU64::new(0),
            total_ns: AtomicU64::new(0),
            max_ns: AtomicU64::new(0),
        }
    }

    fn record(&self, latency: Duration) {
        let ns = latency.as_nanos() as u64;
        self.count.fetch_add(1, Ordering::Relaxed);
        self.total_ns.fetch_add(ns, Ordering::Relaxed);

        // relaxed max update
        let mut current = self.max_ns.load(Ordering::Relaxed);
        while ns > current {
            match self.max_ns.compare_exchange_weak(
                current,
                ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn snapshot(&self) -> (u64, u64, u64) {
        let count = self.count.load(Ordering::Relaxed);
        let total = self.total_ns.load(Ordering::Relaxed);
        let max = self.max_ns.load(Ordering::Relaxed);
        (count, total, max)
    }
}

struct Router {
    workers: Vec<Sender<Message>>,
    next: AtomicU64,
}

impl Router {
    fn new(workers: Vec<Sender<Message>>) -> Self {
        Self {
            workers,
            next: AtomicU64::new(0),
        }
    }

    fn route(&self, msg: Message) {
        let idx = self.next.fetch_add(1, Ordering::Relaxed) as usize % self.workers.len();
        // If channel is full, drop or handle backpressure; here we use send with blocking behavior.
        let _ = self.workers[idx].send(msg);
    }
}

fn worker_loop(id: usize, rx: Receiver<Message>, stats: Arc<LatencyStats>) {
    let mut batch = Vec::with_capacity(1024);

    loop {
        match rx.recv() {
            Ok(msg) => {
                batch.push(msg);

                // Drain more messages quickly to improve throughput
                while batch.len() < 1024 {
                    match rx.try_recv() {
                        Ok(m) => batch.push(m),
                        Err(_) => break,
                    }
                }

                // Process batch
                for msg in batch.drain(..) {
                    // Simulate routing / handling logic
                    // In a real system: parse, dispatch, enrich, forward.
                    let latency = msg.created_at.elapsed();
                    stats.record(latency);

                    // Example: do work with payload
                    let _payload_len = msg.payload.len();
                    let _msg_id = msg.id;
                }
            }
            Err(_) => {
                eprintln!("Worker {id} shutting down");
                break;
            }
        }
    }
}

fn metrics_loop(stats: Arc<LatencyStats>) {
    loop {
        thread::sleep(Duration::from_secs(1));
        let (count, total, max) = stats.snapshot();

        if count > 0 {
            let avg_ns = total / count;
            eprintln!(
                "msgs={}, avg_latency={}us, max_latency={}us",
                count,
                avg_ns / 1_000,
                max / 1_000
            );
        } else {
            eprintln!("msgs=0");
        }
    }
}

fn main() {
    let worker_count = 4;
    let queue_size = 65_536;

    let stats = Arc::new(LatencyStats::new());
    let mut senders = Vec::with_capacity(worker_count);

    for i in 0..worker_count {
        let (tx, rx) = bounded::<Message>(queue_size);
        senders.push(tx);

        let stats_clone = Arc::clone(&stats);
        thread::spawn(move || worker_loop(i, rx, stats_clone));
    }

    let router = Arc::new(Router::new(senders));

    {
        let stats_clone = Arc::clone(&stats);
        thread::spawn(move || metrics_loop(stats_clone));
    }

    // Simulated producer
    let router_clone = Arc::clone(&router);
    thread::spawn(move || {
        let mut id = 0u64;
        loop {
            // In a real high-frequency system, avoid allocating on every message.
            // Prefer reusable buffers / slabs / pools.
            let payload = Arc::<[u8]>::from(vec![0u8; 128].into_boxed_slice());

            let msg = Message {
                id,
                created_at: Instant::now(),
                payload,
            };

            router_clone.route(msg);
            id += 1;
        }
    });

    // Keep main alive
    loop {
        thread::sleep(Duration::from_secs(60));
    }
}
