This is a **skeleton / starting point** rather than a production-ready million-msg/sec system, but it shows the structure you’d use.

```rust
use std::sync::{
    atomic::{AtomicU64, Ordering},
    mpsc,
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    key: u64,
    created_at: Instant,
    payload: Vec<u8>,
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    processed: AtomicU64,
    dropped: AtomicU64,
    latency_sum_ns: AtomicU64,
    latency_count: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn record_latency(&self, latency: Duration) {
        let ns = latency.as_nanos() as u64;
        self.latency_sum_ns.fetch_add(ns, Ordering::Relaxed);
        self.latency_count.fetch_add(1, Ordering::Relaxed);

        // Simple max update
        let mut current = self.max_latency_ns.load(Ordering::Relaxed);
        while ns > current {
            match self.max_latency_ns.compare_exchange_weak(
                current,
                ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn snapshot(&self) -> (u64, u64, u64, u64, u64, u64) {
        (
            self.received.load(Ordering::Relaxed),
            self.routed.load(Ordering::Relaxed),
            self.processed.load(Ordering::Relaxed),
            self.dropped.load(Ordering::Relaxed),
            self.latency_sum_ns.load(Ordering::Relaxed),
            self.latency_count.load(Ordering::Relaxed),
        )
    }
}

fn worker_loop(
    worker_id: usize,
    rx: mpsc::Receiver<Message>,
    metrics: Arc<Metrics>,
) {
    while let Ok(msg) = rx.recv() {
        // Simulate message handling / routing work
        let _target_partition = (msg.key as usize) % 16;

        let latency = msg.created_at.elapsed();
        metrics.processed.fetch_add(1, Ordering::Relaxed);
        metrics.record_latency(latency);

        // Example "processing"
        if worker_id == 0 && msg.id % 1_000_000 == 0 {
            println!(
                "worker={} processed message id={} latency={}us",
                worker_id,
                msg.id,
                latency.as_micros()
            );
        }
    }
}

fn main() {
    const WORKERS: usize = 8;
    const TOTAL_MESSAGES: u64 = 5_000_000;

    let metrics = Arc::new(Metrics::default());

    // One channel per worker for partitioned routing
    let mut worker_senders = Vec::with_capacity(WORKERS);
    let mut worker_handles = Vec::with_capacity(WORKERS);

    for i in 0..WORKERS {
        let (tx, rx) = mpsc::channel::<Message>();
        worker_senders.push(tx);

        let m = metrics.clone();
        let handle = thread::spawn(move || worker_loop(i, rx, m));
        worker_handles.push(handle);
    }

    // Metrics reporter
    let metrics_for_reporter = metrics.clone();
    let reporter = thread::spawn(move || {
        loop {
            thread::sleep(Duration::from_secs(1));
            let (received, routed, processed, dropped, latency_sum_ns, latency_count) =
                metrics_for_reporter.snapshot();

            let avg_latency_us = if latency_count > 0 {
                (latency_sum_ns / latency_count) as f64 / 1_000.0
            } else {
                0.0
            };

            println!(
                "[metrics] received={} routed={} processed={} dropped={} avg_latency_us={:.2}",
                received, routed, processed, dropped, avg_latency_us
            );

            if processed >= TOTAL_MESSAGES {
                break;
            }
        }
    });

    // Simulated producer
    let start = Instant::now();

    for i in 0..TOTAL_MESSAGES {
        metrics.received.fetch_add(1, Ordering::Relaxed);

        let msg = Message {
            id: i,
            key: i % 1024,
            created_at: Instant::now(),
            payload: vec![0u8; 64],
        };

        let target = (msg.key as usize) % WORKERS;

        match worker_senders[target].send(msg) {
            Ok(_) => {
                metrics.routed.fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {
                metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    drop(worker_senders);

    for handle in worker_handles {
        let _ = handle.join();
    }

    let _ = reporter.join();

    let elapsed = start.elapsed();
    println!(
        "Finished processing {} messages in {:.2?} ({:.2} msg/sec)",
        TOTAL_MESSAGES,
        elapsed,
        TOTAL_MESSAGES as f64 / elapsed.as_secs_f64()
    );
}
```

### Notes on this implementation
- It measures **end-to-end queueing + processing latency** using `Instant::now()` at creation time.
- It uses **partitioned routing** so messages with the same key go to the same worker.
- Metrics are intentionally simple; for production you’d want:
  - histogram-based latency tracking
  - percentiles (p50/p95/p99/p99.9)
  - lock-free queues
  - backpressure
  - batching
  - async I/O or kernel bypass if truly extreme throughput is needed

### Production-grade improvements
If you want this to approach real “millions per second” workloads, I’d recommend:
- replacing `std::sync::mpsc` with a faster MPSC queue such as `crossbeam::channel` or a lock-free ring buffer
- batching sends/receives
- preallocating payload buffers
- using shard-based routing
- adding histogram metrics with `hdrhistogram`
- avoiding per-message heap allocation
- pinning threads / CPU affinity for lower jitter

