use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
struct Message {
    id: u64,
    topic: u32,
    payload: Vec<u8>,
    enqueue_ns: u64,
}

#[derive(Default)]
struct SharedStats {
    routed: AtomicU64,
    dropped: AtomicU64,
}

fn now_ns(start: Instant) -> u64 {
    start.elapsed().as_nanos() as u64
}

fn router_thread(
    rx_in: Receiver<Message>,
    tx_out: Sender<Message>,
    stats: Arc<SharedStats>,
) {
    while let Ok(msg) = rx_in.recv() {
        // Simple routing logic by topic.
        // In a real system, this would likely route to per-partition queues / shards.
        if tx_out.try_send(msg).is_ok() {
            stats.routed.fetch_add(1, Ordering::Relaxed);
        } else {
            stats.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn worker_thread(
    rx_out: Receiver<Message>,
    stats: Arc<SharedStats>,
    latency_hist: Arc<Mutex<Histogram<u64>>>,
    start: Instant,
) {
    while let Ok(msg) = rx_out.recv() {
        let end_ns = now_ns(start);
        let latency_ns = end_ns.saturating_sub(msg.enqueue_ns);

        {
            let mut hist = latency_hist.lock().unwrap();
            let _ = hist.record(latency_ns);
        }

        // Simulate processing
        // In real code, do actual message handling here.
        let _ = msg.id;
        let _ = msg.topic;
        let _ = msg.payload;

        stats.routed.fetch_add(1, Ordering::Relaxed);
    }
}

fn metrics_thread(
    stats: Arc<SharedStats>,
    latency_hist: Arc<Mutex<Histogram<u64>>>,
    start: Instant,
) {
    let mut last_routed = 0u64;
    let mut last_time = Instant::now();

    loop {
        thread::sleep(Duration::from_secs(1));

        let elapsed = last_time.elapsed().as_secs_f64();
        last_time = Instant::now();

        let routed = stats.routed.load(Ordering::Relaxed);
        let dropped = stats.dropped.load(Ordering::Relaxed);

        let delta = routed.saturating_sub(last_routed);
        last_routed = routed;

        let throughput = (delta as f64 / elapsed) as u64;

        let hist = latency_hist.lock().unwrap();
        let p50 = hist.value_at_quantile(0.50);
        let p95 = hist.value_at_quantile(0.95);
        let p99 = hist.value_at_quantile(0.99);
        let max = hist.max();

        println!(
            "[+{:>6}s] throughput={} msg/s routed={} dropped={} latency_ns: p50={} p95={} p99={} max={}",
            start.elapsed().as_secs(),
            throughput,
            routed,
            dropped,
            p50,
            p95,
            p99,
            max
        );
    }
}

fn producer_thread(tx_in: Sender<Message>, start: Instant, rate_per_sec: u64) {
    let mut id = 0u64;
    let interval_ns = if rate_per_sec == 0 {
        0
    } else {
        1_000_000_000u64 / rate_per_sec
    };

    let mut next_send = start;

    loop {
        let now = Instant::now();
        if now < next_send {
            thread::sleep(next_send - now);
        }

        let msg = Message {
            id,
            topic: (id % 16) as u32,
            payload: vec![0u8; 128],
            enqueue_ns: now_ns(start),
        };

        if tx_in.try_send(msg).is_err() {
            // Backpressure: drop when the queue is full.
            // Alternatives: block, retry, or route to spillover.
        }

        id += 1;

        if interval_ns > 0 {
            next_send += Duration::from_nanos(interval_ns);
        }
    }
}

fn main() {
    let start = Instant::now();

    // Bounded queues to apply backpressure and control memory usage.
    let (tx_in, rx_in) = bounded::<Message>(1_000_000);
    let (tx_out, rx_out) = bounded::<Message>(1_000_000);

    let stats = Arc::new(SharedStats::default());

    let latency_hist = Arc::new(Mutex::new(
        Histogram::<u64>::new(3).expect("failed to create histogram"),
    ));

    let producer_rate = 2_000_000; // target messages/sec for the producer
    let worker_count = 4;

    // Producer
    {
        let tx_in = tx_in.clone();
        thread::spawn(move || producer_thread(tx_in, start, producer_rate));
    }

    // Router
    {
        let stats = stats.clone();
        let tx_out = tx_out.clone();
        thread::spawn(move || router_thread(rx_in, tx_out, stats));
    }

    // Workers
    for _ in 0..worker_count {
        let rx_out = rx_out.clone();
        let stats = stats.clone();
        let latency_hist = latency_hist.clone();

        thread::spawn(move || worker_thread(rx_out, stats, latency_hist, start));
    }

    // Metrics
    {
        let stats = stats.clone();
        let latency_hist = latency_hist.clone();
        thread::spawn(move || metrics_thread(stats, latency_hist, start));
    }

    // Keep main alive
    loop {
        thread::sleep(Duration::from_secs(60));
    }
}
