## Example Rust implementation

This is a simplified in-process router with latency monitoring. It demonstrates the core ideas without pulling in a full network stack.

```rust
use std::{
    collections::HashMap,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    thread,
    time::{Duration, Instant},
};

use crossbeam::channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use parking_lot::Mutex;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: u32,
    created_at: Instant,
    payload: Arc<[u8]>,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    histogram: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            histogram: Mutex::new(Histogram::<u64>::new(3).unwrap()),
        }
    }

    fn inc_received(&self) {
        self.received.fetch_add(1, Ordering::Relaxed);
    }

    fn inc_routed(&self) {
        self.routed.fetch_add(1, Ordering::Relaxed);
    }

    fn inc_dropped(&self) {
        self.dropped.fetch_add(1, Ordering::Relaxed);
    }

    fn record_latency_ns(&self, latency: u64) {
        let mut h = self.histogram.lock();
        let _ = h.record(latency);
    }

    fn snapshot(&self) {
        let h = self.histogram.lock();
        println!(
            "received={}, routed={}, dropped={}, p50={}us, p95={}us, p99={}us",
            self.received.load(Ordering::Relaxed),
            self.routed.load(Ordering::Relaxed),
            self.dropped.load(Ordering::Relaxed),
            h.value_at_quantile(0.50) / 1_000,
            h.value_at_quantile(0.95) / 1_000,
            h.value_at_quantile(0.99) / 1_000,
        );
    }
}

struct Router {
    routes: HashMap<u32, Sender<Message>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn route(&self, msg: Message) {
        self.metrics.inc_received();

        if let Some(tx) = self.routes.get(&msg.topic) {
            if tx.try_send(msg).is_ok() {
                self.metrics.inc_routed();
            } else {
                self.metrics.inc_dropped();
            }
        } else {
            self.metrics.inc_dropped();
        }
    }
}

fn spawn_consumer(
    topic: u32,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        loop {
            // Batch a few messages to reduce overhead
            let mut batch = Vec::with_capacity(1024);

            match rx.recv() {
                Ok(msg) => batch.push(msg),
                Err(_) => break,
            }

            while let Ok(msg) = rx.try_recv() {
                batch.push(msg);
                if batch.len() >= 1024 {
                    break;
                }
            }

            for msg in batch {
                // Simulate processing / outbound send
                let latency = msg.created_at.elapsed().as_nanos() as u64;
                metrics.record_latency_ns(latency);

                // Example "delivery" action
                // In a real system this would write to a socket / broker / peer.
                let _ = (topic, msg.id, msg.payload.len());
            }
        }
    })
}

fn main() {
    let metrics = Arc::new(Metrics::new());

    // Create topic-specific queues
    let mut routes = HashMap::new();
    let mut workers = Vec::new();

    for topic in 0..8u32 {
        let (tx, rx) = bounded::<Message>(100_000);
        routes.insert(topic, tx);
        workers.push(spawn_consumer(topic, rx, metrics.clone()));
    }

    let router = Router {
        routes,
        metrics: metrics.clone(),
    };

    // Simulate high-rate producers
    let producer_threads = 4;
    let messages_per_thread = 500_000;

    let mut producers = Vec::new();
    for p in 0..producer_threads {
        let router_ref = router.routes.clone();
        let metrics_ref = metrics.clone();

        producers.push(thread::spawn(move || {
            for i in 0..messages_per_thread {
                let topic = (i % 8) as u32;
                let msg = Message {
                    id: (p as u64) << 32 | i as u64,
                    topic,
                    created_at: Instant::now(),
                    payload: Arc::from(vec![0u8; 128].into_boxed_slice()),
                };

                metrics_ref.inc_received();

                if let Some(tx) = router_ref.get(&topic) {
                    if tx.try_send(msg).is_ok() {
                        metrics_ref.inc_routed();
                    } else {
                        metrics_ref.inc_dropped();
                    }
                } else {
                    metrics_ref.inc_dropped();
                }
            }
        }));
    }

    // Metrics reporter
    let metrics_reporter = {
        let metrics = metrics.clone();
        thread::spawn(move || {
            loop {
                thread::sleep(Duration::from_secs(1));
                metrics.snapshot();
            }
        })
    };

    for p in producers {
        let _ = p.join();
    }

    // Let consumers drain
    thread::sleep(Duration::from_secs(3));

    metrics.snapshot();

    // Prevent unused warning
    let _ = metrics_reporter;
    let _ = workers;
}
