use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: u32,
    created_at: Instant,
    payload: Vec<u8>,
}

struct Metrics {
    received: AtomicU64,
    routed: AtomicU64,
    dropped: AtomicU64,
    routing_errors: AtomicU64,
    shutdown: AtomicBool,
    latency_histogram: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            routing_errors: AtomicU64::new(0),
            shutdown: AtomicBool::new(false),
            latency_histogram: Mutex::new(Histogram::<u64>::new(3).unwrap()),
        }
    }

    fn record_latency(&self, nanos: u64) {
        let mut hist = self.latency_histogram.lock();
        let _ = hist.record(nanos);
    }

    fn snapshot(&self) {
        let hist = self.latency_histogram.lock();
        println!("=== Metrics Snapshot ===");
        println!("received: {}", self.received.load(Ordering::Relaxed));
        println!("routed: {}", self.routed.load(Ordering::Relaxed));
        println!("dropped: {}", self.dropped.load(Ordering::Relaxed));
        println!(
            "routing_errors: {}",
            self.routing_errors.load(Ordering::Relaxed)
        );

        if hist.len() > 0 {
            println!("latency p50: {} ns", hist.value_at_quantile(0.50));
            println!("latency p95: {} ns", hist.value_at_quantile(0.95));
            println!("latency p99: {} ns", hist.value_at_quantile(0.99));
            println!("latency max: {} ns", hist.max());
            println!("samples: {}", hist.len());
        } else {
            println!("latency histogram empty");
        }
        println!("========================");
    }
}

struct Router {
    routes: DashMap<u32, Sender<Message>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(metrics: Arc<Metrics>) -> Self {
        Self {
            routes: DashMap::new(),
            metrics,
        }
    }

    fn register_route(&self, topic: u32, tx: Sender<Message>) {
        self.routes.insert(topic, tx);
    }

    fn route(&self, msg: Message) {
        self.metrics.received.fetch_add(1, Ordering::Relaxed);

        if let Some(route) = self.routes.get(&msg.topic) {
            if route.try_send(msg).is_ok() {
                self.metrics.routed.fetch_add(1, Ordering::Relaxed);
            } else {
                self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
            }
        } else {
            self.metrics.routing_errors.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn start_consumer(
    topic: u32,
    rx: Receiver<Message>,
    metrics: Arc<Metrics>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        while !metrics.shutdown.load(Ordering::Relaxed) {
            match rx.recv_timeout(Duration::from_millis(100)) {
                Ok(msg) => {
                    let latency_ns = msg.created_at.elapsed().as_nanos() as u64;
                    metrics.record_latency(latency_ns);

                    // Simulate processing work
                    let _ = msg.payload.len();

                    // In real systems, avoid println! in hot path.
                    if msg.id % 1_000_000 == 0 {
                        println!("Topic {} processed message {}", topic, msg.id);
                    }
                }
                Err(_) => {
                    continue;
                }
            }
        }
    })
}

fn main() {
    let metrics = Arc::new(Metrics::new());
    let router = Arc::new(Router::new(metrics.clone()));

    // Create a few topic consumers
    let topics = [1_u32, 2, 3, 4];
    let mut consumer_handles = Vec::new();

    for topic in topics {
        let (tx, rx) = bounded::<Message>(100_000);
        router.register_route(topic, tx);
        consumer_handles.push(start_consumer(topic, rx, metrics.clone()));
    }

    // Producer threads
    let producer_threads = 4;
    let messages_per_producer = 1_000_000;
    let mut producer_handles = Vec::new();

    for producer_id in 0..producer_threads {
        let router = router.clone();
        let handle = thread::spawn(move || {
            for i in 0..messages_per_producer {
                let id = (producer_id as u64) * 1_000_000_000 + i as u64;
                let topic = match id % 4 {
                    0 => 1,
                    1 => 2,
                    2 => 3,
                    _ => 4,
                };

                let msg = Message {
                    id,
                    topic,
                    created_at: Instant::now(),
                    payload: vec![0_u8; 128],
                };

                router.route(msg);
            }
        });
        producer_handles.push(handle);
    }

    // Metrics reporter
    let metrics_clone = metrics.clone();
    let reporter = thread::spawn(move || {
        while !metrics_clone.shutdown.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));
            metrics_clone.snapshot();
        }
    });

    // Wait for producers
    for handle in producer_handles {
        handle.join().unwrap();
    }

    // Let consumers drain remaining messages
    thread::sleep(Duration::from_secs(2));
    metrics.shutdown.store(true, Ordering::Relaxed);

    reporter.join().unwrap();

    for handle in consumer_handles {
        let _ = handle.join();
    }

    metrics.snapshot();
}
