use bytes::Bytes;
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use hdrhistogram::Histogram;
use parking_lot::Mutex;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

type Topic = String;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: Topic,
    payload: Bytes,
    created_at: Instant,
}

#[derive(Clone)]
struct RoutedMessage {
    message: Message,
    routed_at: Instant,
}

struct Metrics {
    route_latency: Mutex<Histogram<u64>>,
    end_to_end_latency: Mutex<Histogram<u64>>,
    dropped_messages: Mutex<u64>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            route_latency: Mutex::new(Histogram::new(3).expect("hist")),
            end_to_end_latency: Mutex::new(Histogram::new(3).expect("hist")),
            dropped_messages: Mutex::new(0),
        }
    }

    fn record_route_latency(&self, dur: Duration) {
        self.route_latency
            .lock()
            .record(dur.as_nanos() as u64)
            .ok();
    }

    fn record_end_to_end_latency(&self, dur: Duration) {
        self.end_to_end_latency
            .lock()
            .record(dur.as_nanos() as u64)
            .ok();
    }

    fn inc_dropped(&self) {
        *self.dropped_messages.lock() += 1;
    }

    fn snapshot(&self) -> MetricsSnapshot {
        let route = self.route_latency.lock();
        let e2e = self.end_to_end_latency.lock();
        let dropped = *self.dropped_messages.lock();

        MetricsSnapshot {
            route_p50_ns: route.value_at_quantile(0.50),
            route_p95_ns: route.value_at_quantile(0.95),
            route_p99_ns: route.value_at_quantile(0.99),
            e2e_p50_ns: e2e.value_at_quantile(0.50),
            e2e_p95_ns: e2e.value_at_quantile(0.95),
            e2e_p99_ns: e2e.value_at_quantile(0.99),
            dropped,
        }
    }
}

struct MetricsSnapshot {
    route_p50_ns: u64,
    route_p95_ns: u64,
    route_p99_ns: u64,
    e2e_p50_ns: u64,
    e2e_p95_ns: u64,
    e2e_p99_ns: u64,
    dropped: u64,
}

struct Broker {
    ingest_tx: Sender<Message>,
    ingest_rx: Receiver<Message>,
    route_queues: DashMap<Topic, Sender<RoutedMessage>>,
    metrics: Arc<Metrics>,
}

impl Broker {
    fn new(buffer_size: usize) -> Self {
        let (ingest_tx, ingest_rx) = bounded(buffer_size);

        Self {
            ingest_tx,
            ingest_rx,
            route_queues: DashMap::new(),
            metrics: Arc::new(Metrics::new()),
        }
    }

    fn producer(&self) -> Producer {
        Producer {
            tx: self.ingest_tx.clone(),
            metrics: Arc::clone(&self.metrics),
        }
    }

    fn register_topic(&self, topic: &str, buffer_size: usize) -> Receiver<RoutedMessage> {
        let (tx, rx) = bounded(buffer_size);
        self.route_queues.insert(topic.to_string(), tx);
        rx
    }

    fn start_router(&self) {
        let rx = self.ingest_rx.clone();
        let route_queues = self.route_queues.clone();
        let metrics = Arc::clone(&self.metrics);

        thread::spawn(move || {
            while let Ok(msg) = rx.recv() {
                let routed_at = Instant::now();
                let route_latency = routed_at.duration_since(msg.created_at);
                metrics.record_route_latency(route_latency);

                let routed = RoutedMessage {
                    message: msg.clone(),
                    routed_at,
                };

                if let Some(entry) = route_queues.get(&msg.topic) {
                    if entry.send(routed).is_err() {
                        metrics.inc_dropped();
                    }
                } else {
                    metrics.inc_dropped();
                }
            }
        });
    }

    fn metrics(&self) -> Arc<Metrics> {
        Arc::clone(&self.metrics)
    }
}

struct Producer {
    tx: Sender<Message>,
    metrics: Arc<Metrics>,
}

impl Producer {
    fn send(&self, id: u64, topic: impl Into<String>, payload: impl Into<Bytes>) {
        let message = Message {
            id,
            topic: topic.into(),
            payload: payload.into(),
            created_at: Instant::now(),
        };

        if self.tx.try_send(message).is_err() {
            self.metrics.inc_dropped();
        }
    }
}

fn start_consumer(rx: Receiver<RoutedMessage>, metrics: Arc<Metrics>) {
    thread::spawn(move || {
        while let Ok(routed) = rx.recv() {
            let now = Instant::now();
            let e2e = now.duration_since(routed.message.created_at);
            metrics.record_end_to_end_latency(e2e);

            // Simulate processing path
            let _id = routed.message.id;
            let _payload_len = routed.message.payload.len();
            let _routed_latency = routed.routed_at.duration_since(routed.message.created_at);

            // In a real system, forward, persist, or dispatch here.
        }
    });
}

fn main() {
    let broker = Broker::new(1_000_000);

    let topic_a_rx = broker.register_topic("topic-a", 1_000_000);
    let topic_b_rx = broker.register_topic("topic-b", 1_000_000);

    broker.start_router();

    let metrics = broker.metrics();
    start_consumer(topic_a_rx, Arc::clone(&metrics));
    start_consumer(topic_b_rx, Arc::clone(&metrics));

    let producer = broker.producer();

    // Example producer loop
    let producer_handle = thread::spawn(move || {
        for i in 0..10_000_000u64 {
            let topic = if i % 2 == 0 { "topic-a" } else { "topic-b" };
            producer.send(i, topic, Bytes::from_static(b"hello-world"));
        }
    });

    // Periodic metrics reporting
    let metrics_handle = {
        let metrics = broker.metrics();
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(1));
            let snap = metrics.snapshot();
            println!(
                "route p50={}ns p95={}ns p99={}ns | e2e p50={}ns p95={}ns p99={}ns | dropped={}",
                snap.route_p50_ns,
                snap.route_p95_ns,
                snap.route_p99_ns,
                snap.e2e_p50_ns,
                snap.e2e_p95_ns,
                snap.e2e_p99_ns,
                snap.dropped
            );
        })
    };

    producer_handle.join().unwrap();
    let _ = metrics_handle.join();
}
