use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: u32,
    created_at: Instant,
    payload: Arc<[u8]>,
}

impl Message {
    fn new(id: u64, topic: u32, payload: Vec<u8>) -> Self {
        Self {
            id,
            topic,
            created_at: Instant::now(),
            payload: payload.into(),
        }
    }
}

struct TopicRouter {
    routes: HashMap<u32, Sender<Message>>,
}

impl TopicRouter {
    fn new() -> Self {
        Self {
            routes: HashMap::new(),
        }
    }

    fn add_route(&mut self, topic: u32, sender: Sender<Message>) {
        self.routes.insert(topic, sender);
    }

    fn route(&self, message: Message) {
        if let Some(tx) = self.routes.get(&message.topic) {
            let _ = tx.try_send(message);
        } else {
            // Unknown topic; drop or handle as needed
        }
    }
}

struct LatencyMonitor {
    histogram: Mutex<Histogram<u64>>,
}

impl LatencyMonitor {
    fn new() -> Self {
        Self {
            histogram: Mutex::new(Histogram::<u64>::new(3).unwrap()),
        }
    }

    fn record(&self, latency: Duration) {
        let micros = latency.as_micros();
        if micros > 0 {
            self.histogram.lock().record(micros as u64).ok();
        } else {
            self.histogram.lock().record(1).ok();
        }
    }

    fn snapshot(&self) {
        let hist = self.histogram.lock();
        if hist.len() == 0 {
            println!("No latency samples yet.");
            return;
        }

        println!("Latency summary:");
        println!("  count: {}", hist.len());
        println!("  p50:   {} µs", hist.value_at_quantile(0.50));
        println!("  p95:   {} µs", hist.value_at_quantile(0.95));
        println!("  p99:   {} µs", hist.value_at_quantile(0.99));
        println!("  max:   {} µs", hist.max());
    }
}

fn consumer_loop(rx: Receiver<Message>, monitor: Arc<LatencyMonitor>, stop: Arc<AtomicBool>) {
    while !stop.load(Ordering::Relaxed) {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(msg) => {
                let latency = msg.created_at.elapsed();
                monitor.record(latency);

                // Simulate processing
                let _processed = msg.payload.len();
                let _id = msg.id;
            }
            Err(_) => {}
        }
    }
}

fn producer_loop(
    router: Arc<TopicRouter>,
    stop: Arc<AtomicBool>,
    topics: u32,
) {
    let mut id = 0u64;

    while !stop.load(Ordering::Relaxed) {
        let topic = (id % topics as u64) as u32;
        let payload = vec![0u8; 128];
        let msg = Message::new(id, topic, payload);

        router.route(msg);
        id = id.wrapping_add(1);
