use bytes::Bytes;
use dashmap::DashMap;
use hdrhistogram::Histogram;
use std::{
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc, Mutex,
    },
    time::{Duration, Instant},
};
use tokio::sync::mpsc;
use tracing::{info, warn};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: String,
    payload: Bytes,
    created_at: Instant,
}

#[derive(Clone)]
struct Subscriber {
    id: u64,
    tx: mpsc::Sender<Message>,
}

struct Metrics {
    published: AtomicU64,
    routed: AtomicU64,
    delivered: AtomicU64,
    dropped: AtomicU64,

    // Protect histogram with a mutex; recording is cheap but not lock-free.
    pub_latency_us: Mutex<Histogram<u64>>,
    route_latency_us: Mutex<Histogram<u64>>,
    delivery_latency_us: Mutex<Histogram<u64>>,
}

impl Metrics {
    fn new() -> Self {
        Self {
            published: AtomicU64::new(0),
            routed: AtomicU64::new(0),
            delivered: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
            pub_latency_us: Mutex::new(Histogram::new(3).unwrap()),
            route_latency_us: Mutex::new(Histogram::new(3).unwrap()),
            delivery_latency_us: Mutex::new(Histogram::new(3).unwrap()),
        }
    }

    fn record_publish_latency(&self, us: u64) {
        let mut h = self.pub_latency_us.lock().unwrap();
        let _ = h.record(us);
    }

    fn record_route_latency(&self, us: u64) {
        let mut h = self.route_latency_us.lock().unwrap();
        let _ = h.record(us);
    }

    fn record_delivery_latency(&self, us: u64) {
        let mut h = self.delivery_latency_us.lock().unwrap();
        let _ = h.record(us);
    }
}

struct Router {
    // topic -> subscribers
    topics: DashMap<String, Vec<Subscriber>>,
    metrics: Arc<Metrics>,
}

impl Router {
    fn new(metrics: Arc<Metrics>) -> Self {
        Self {
            topics: DashMap::new(),
            metrics,
        }
    }

    fn subscribe(&self, topic: impl Into<String>, subscriber: Subscriber) {
        let topic = topic.into();
        self.topics
            .entry(topic)
            .and_modify(|subs| subs.push(subscriber.clone()))
            .or_insert_with(|| vec![subscriber]);
    }

    async fn publish(&self, msg: Message) {
        let route_start = Instant::now();
        self.metrics.published.fetch_add(1, Ordering::Relaxed);

        if let Some(subs) = self.topics.get(&msg.topic) {
            self.metrics
                .record_publish_latency(route_start.duration_since(msg.created_at).as_micros() as u64);

            for sub in subs.iter() {
                // Clone only the minimal message if needed; Bytes is cheap to clone.
                let routed_msg = msg.clone();
                match sub.tx.try_send(routed_msg) {
                    Ok(_) => {
                        self.metrics.routed.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(_e) => {
                        self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
        } else {
            self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }

        self.metrics
            .record_route_latency(route_start.elapsed().as_micros() as u64);
    }
}

async fn subscriber_task(
    id: u64,
    mut rx: mpsc::Receiver<Message>,
    metrics: Arc<Metrics>,
) {
    while let Some(msg) = rx.recv().await {
        let now = Instant::now();
        let delivery_us = now.duration_since(msg.created_at).as_micros() as u64;
        metrics.record_delivery_latency(delivery_us);
        metrics.delivered.fetch_add(1, Ordering::Relaxed);

        // Simulate processing
        if msg.id % 1_000_000 == 0 {
            info!("subscriber={} received msg_id={} topic={}", id, msg.id, msg.topic);
        }
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let metrics = Arc::new(Metrics::new());
    let router = Arc::new(Router::new(metrics.clone()));

    // Create subscribers
    let topics = vec!["orders", "quotes", "alerts"];
    for topic in &topics {
        for sub_id in 0..8 {
            let (tx, rx) = mpsc::channel::<Message>(1024);
            let subscriber = Subscriber {
                id: sub_id,
                tx,
            };
            router.subscribe((*topic).to_string(), subscriber);

            let metrics_clone = metrics.clone();
            tokio::spawn(subscriber_task(sub_id, rx, metrics_clone));
        }
    }

    // Producer loop
    let router_clone = router.clone();
    let producer = tokio::spawn(async move {
        let mut id: u64 = 0;
        loop {
            id += 1;
            let topic = match id % 3 {
                0 => "orders",
                1 => "quotes",
                _ => "alerts",
            };

            let msg = Message {
                id,
                topic: topic.to_string(),
                payload: Bytes::from_static(b"hello-world"),
                created_at: Instant::now(),
            };

            router_clone.publish(msg).await;

            // For stress testing, remove sleep entirely.
            // tokio::task::yield_now().await;
        }
    });

    // Metrics reporting loop
    let metrics_clone = metrics.clone();
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(Duration::from_secs(1)).await;

            let published = metrics_clone.published.load(Ordering::Relaxed);
            let routed = metrics_clone.routed.load(Ordering::Relaxed);
            let delivered = metrics_clone.delivered.load(Ordering::Relaxed);
            let dropped = metrics_clone.dropped.load(Ordering::Relaxed);

            let pub_p50 = metrics_clone.pub_latency_us.lock().unwrap().value_at_quantile(0.50);
            let pub_p99 = metrics_clone.pub_latency_us.lock().unwrap().value_at_quantile(0.99);
            let route_p50 = metrics_clone.route_latency_us.lock().unwrap().value_at_quantile(0.50);
            let route_p99 = metrics_clone.route_latency_us.lock().unwrap().value_at_quantile(0.99);
            let del_p50 = metrics_clone.delivery_latency_us.lock().unwrap().value_at_quantile(0.50);
            let del_p99 = metrics_clone.delivery_latency_us.lock().unwrap().value_at_quantile(0.99);

            info!(
                "metrics published={} routed={} delivered={} dropped={} \
                 pub_us(p50={}, p99={}) route_us(p50={}, p99={}) delivery_us(p50={}, p99={})",
                published, routed, delivered, dropped,
                pub_p50, pub_p99,
                route_p50, route_p99,
                del_p50, del_p99
            );
        }
    });

    let _ = producer.await;
}
```

