use dashmap::DashMap;
use hdrhistogram::Histogram;
use rand::Rng;
use std::{
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use tokio::{
    sync::mpsc,
    task,
    time::{interval, sleep},
};
use tracing::{info, warn};

#[derive(Debug, Clone)]
struct Message {
    id: u64,
    topic: u32,
    created_at: Instant,
    payload: Vec<u8>,
}

#[derive(Default)]
struct ThroughputCounter {
    total: AtomicU64,
    per_sec: AtomicU64,
}

impl ThroughputCounter {
    fn incr(&self) {
        self.total.fetch_add(1, Ordering::Relaxed);
        self.per_sec.fetch_add(1, Ordering::Relaxed);
    }

    fn snapshot_and_reset(&self) -> u64 {
        self.per_sec.swap(0, Ordering::Relaxed)
    }

    fn total(&self) -> u64 {
        self.total.load(Ordering::Relaxed)
    }
}

struct LatencyMetrics {
    // one histogram per consumer shard/topic/etc. (or a single one)
    histogram: parking_lot::Mutex<Histogram<u64>>,
}

impl LatencyMetrics {
    fn new() -> Self {
        Self {
            histogram: parking_lot::Mutex::new(
                Histogram::<u64>::new(3).expect("histogram init"),
            ),
        }
    }

    fn record(&self, latency_us: u64) {
        let mut h = self.histogram.lock();
        let _ = h.record(latency_us);
    }

    fn snapshot(&self) -> (u64, u64, u64, u64, u64) {
        let mut h = self.histogram.lock();
        let count = h.len();
        let p50 = h.value_at_quantile(0.50);
        let p95 = h.value_at_quantile(0.95);
        let p99 = h.value_at_quantile(0.99);
        let max = h.max();
        h.reset();
        (count, p50, p95, p99, max)
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .compact()
        .init();

    let topics: u32 = 64;
    let producer_count = 4;
    let consumer_count = 8;
    let messages_per_producer_per_sec = 250_000; // increase as hardware allows

    let throughput = Arc::new(ThroughputCounter::default());
    let metrics = Arc::new(LatencyMetrics::new());

    // Router input
    let (router_tx, mut router_rx) = mpsc::channel::<Message>(100_000);

    // Consumer queues by shard
    let mut consumer_txs = Vec::new();
    let mut consumer_rxs = Vec::new();
    for _ in 0..consumer_count {
        let (tx, rx) = mpsc::channel::<Message>(100_000);
        consumer_txs.push(tx);
        consumer_rxs.push(rx);
    }

    // Spawn consumers
    for (i, mut rx) in consumer_rxs.into_iter().enumerate() {
        let throughput = throughput.clone();
        let metrics = metrics.clone();

        task::spawn(async move {
            while let Some(msg) = rx.recv().await {
                // Simulate minimal processing
                let latency_us = msg.created_at.elapsed().as_micros() as u64;
                throughput.incr();
                metrics.record(latency_us);

                // Optional: inspect payload/topic here
                if msg.id % 10_000_000 == 0 {
                    info!("consumer={} handled msg id={}", i, msg.id);
                }
            }
        });
    }

    // Spawn router
    {
        let consumer_txs = consumer_txs.clone();
        task::spawn(async move {
            while let Some(msg) = router_rx.recv().await {
                let shard = (msg.topic as usize) % consumer_txs.len();
                if let Err(_e) = consumer_txs[shard].send(msg).await {
                    warn!("consumer shard closed");
                }
            }
        });
    }

    // Spawn producers
    for producer_id in 0..producer_count {
        let router_tx = router_tx.clone();
        task::spawn(async move {
            let mut id = producer_id as u64 * 1_000_000_000;
            let mut rng = rand::thread_rng();
            let mut ticker = interval(Duration::from_secs(1));

            loop {
                ticker.tick().await;

                let start = Instant::now();
                let mut sent = 0u64;

                while start.elapsed() < Duration::from_secs(1) {
                    let topic = rng.gen_range(0..topics);
                    let msg = Message {
                        id,
                        topic,
                        created_at: Instant::now(),
                        payload: vec![0u8; 128], // keep small for throughput
                    };

                    if router_tx.try_send(msg).is_ok() {
                        sent += 1;
                        id += 1;
                    } else {
                        // Backpressure: if full, yield briefly
                        tokio::task::yield_now().await;
                    }
                }

                info!(
                    "producer={} sent={} msgs/s",
                    producer_id,
                    sent
                );
            }
        });
    }

    // Metrics reporter
    {
        let throughput = throughput.clone();
        let metrics = metrics.clone();
        task::spawn(async move {
            let mut tick = interval(Duration::from_secs(1));
            loop {
                tick.tick().await;

                let per_sec = throughput.snapshot_and_reset();
                let total = throughput.total();
                let (count, p50, p95, p99, max) = metrics.snapshot();

                info!(
                    "throughput={} msg/s total={} latency_count={} p50={}us p95={}us p99={}us max={}us",
                    per_sec, total, count, p50, p95, p99, max
                );
            }
        });
    }

    // Keep running
    loop {
        sleep(Duration::from_secs(3600)).await;
    }
}
