use crossbeam::channel::{bounded, Receiver, Sender};
use std::thread;
use std::time::{Duration, Instant};

const MESSAGE_COUNT: usize = 5_000_000;
const CHANNEL_CAPACITY: usize = 65_536;

#[derive(Clone, Copy)]
struct Message {
    id: u64,
    created_at: Instant,
    payload: u64,
}

fn producer(tx: Sender<Message>) {
    for i in 0..MESSAGE_COUNT as u64 {
        let msg = Message {
            id: i,
            created_at: Instant::now(),
            payload: i ^ 0xDEADBEEF,
        };
        tx.send(msg).unwrap();
    }
}

fn router(rx: Receiver<Message>, tx: Sender<Message>) {
    while let Ok(msg) = rx.recv() {
        // Minimal routing logic.
        // In a real system this would inspect headers, destination, topic, etc.
        let routed = Message {
            id: msg.id,
            created_at: msg.created_at,
            payload: msg.payload,
        };
        tx.send(routed).unwrap();
    }
}

fn consumer(rx: Receiver<Message>) {
    let mut count: u64 = 0;
    let mut total_latency_ns: u128 = 0;
    let mut max_latency_ns: u128 = 0;

    // Simple reservoir of recent latencies to estimate p99.
    let mut samples: Vec<u128> = Vec::with_capacity(100_000);

    while let Ok(msg) = rx.recv() {
        let latency = msg.created_at.elapsed().as_nanos();
        total_latency_ns += latency;
        if latency > max_latency_ns {
            max_latency_ns = latency;
        }
        if samples.len() < 100_000 {
            samples.push(latency);
        }

        // Simulate message handling.
        let _ = msg.payload.wrapping_mul(2);

        count += 1;
        if count == MESSAGE_COUNT as u64 {
            break;
        }
    }

    samples.sort_unstable();
    let p99_idx = ((samples.len() as f64) * 0.99).floor() as usize;
    let p99 = samples.get(p99_idx).copied().unwrap_or(0);

    let avg_latency_ns = total_latency_ns / count as u128;

    println!("messages: {}", count);
    println!("avg latency: {} ns", avg_latency_ns);
    println!("p99 latency: {} ns", p99);
    println!("max latency: {} ns", max_latency_ns);
}

fn main() {
    let (tx_in, rx_in) = bounded::<Message>(CHANNEL_CAPACITY);
    let (tx_out, rx_out) = bounded::<Message>(CHANNEL_CAPACITY);

    let p = thread::spawn(move || producer(tx_in));
    let r = thread::spawn(move || router(rx_in, tx_out));
    let c = thread::spawn(move || consumer(rx_out));

    let start = Instant::now();

    p.join().unwrap();
    r.join().unwrap();
    c.join().unwrap();

    let elapsed = start.elapsed();
    let throughput = MESSAGE_COUNT as f64 / elapsed.as_secs_f64();

    println!("total time: {:.3} s", elapsed.as_secs_f64());
    println!("throughput: {:.0} msg/s", throughput);
}
```

