use crossbeam_channel::{bounded, Receiver, Sender};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    created_at: Instant,
    payload: u64,
}

fn producer(tx: Sender<Message>, total: u64) {
    for i in 0..total {
        let msg = Message {
            id: i,
            created_at: Instant::now(),
            payload: i ^ 0xDEADBEEF,
        };

        if tx.send(msg).is_err() {
            break;
        }
    }
}

fn router(rx: Receiver<Message>, tx: Sender<Message>) {
    while let Ok(msg) = rx.recv() {
        // Minimal routing logic; in a real system this could hash, shard, filter, etc.
        if tx.send(msg).is_err() {
            break;
        }
    }
}

fn consumer(rx: Receiver<Message>, latency_tx: Sender<u128>) {
    while let Ok(msg) = rx.recv() {
        // Simulate processing and measure end-to-end latency
        let latency_ns = msg.created_at.elapsed().as_nanos();
        let _ = msg.payload; // prevent unused warning
        let _ = msg.id;

        if latency_tx.send(latency_ns).is_err() {
            break;
        }
    }
}

fn monitor(latency_rx: Receiver<u128>) {
    let mut samples: Vec<u128> = Vec::with_capacity(100_000);
    let mut last_print = Instant::now();

    loop {
        // Collect samples for 1 second intervals
        while let Ok(lat) = latency_rx.try_recv() {
            samples.push(lat);
        }

        if last_print.elapsed() >= Duration::from_secs(1) {
            if !samples.is_empty() {
                samples.sort_unstable();

                let count = samples.len();
                let p50 = samples[count / 2];
                let p95 = samples[(count * 95 / 100).min(count - 1)];
                let p99 = samples[(count * 99 / 100).min(count - 1)];
                let avg = samples.iter().sum::<u128>() / count as u128;

                println!(
                    "messages={} avg={}ns p50={}ns p95={}ns p99={}ns",
                    count, avg, p50, p95, p99
                );

                samples.clear();
            }

            last_print = Instant::now();
        }

        // Small sleep to avoid busy spinning in this demo
        thread::sleep(Duration::from_millis(10));
    }
}

fn main() {
    let total_messages = 1_000_000u64;

    // Bounded channels reduce memory growth and make backpressure explicit
    let (producer_tx, router_rx) = bounded::<Message>(100_000);
    let (router_tx, consumer_rx) = bounded::<Message>(100_000);
    let (latency_tx, latency_rx) = bounded::<u128>(100_000);

    let p = thread::spawn(move || producer(producer_tx, total_messages));
    let r = thread::spawn(move || router(router_rx, router_tx));
    let c = thread::spawn(move || consumer(consumer_rx, latency_tx));
    let m = thread::spawn(move || monitor(latency_rx));

    p.join().unwrap();
    r.join().unwrap();
    c.join().unwrap();

    // In this demo the monitor runs forever, so you would normally
    // add shutdown signaling. For simplicity, we just detach it.
    let _ = m;
}
