import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.LongAdder;

public class HighFrequencyMessagingSystem {

    // Message model
    static class Message {
        final long createdNanos;
        final int routingKey;
        final String payload;

        Message(int routingKey, String payload) {
            this.createdNanos = System.nanoTime();
            this.routingKey = routingKey;
            this.payload = payload;
        }
    }

    // Simple latency monitor
    static class LatencyMonitor {
        private final LongAdder count = new LongAdder();
        private final LongAdder totalNanos = new LongAdder();
        private volatile long minNanos = Long.MAX_VALUE;
        private volatile long maxNanos = Long.MIN_VALUE;

        synchronized void record(long latencyNanos) {
            count.increment();
            totalNanos.add(latencyNanos);
            if (latencyNanos < minNanos) minNanos = latencyNanos;
            if (latencyNanos > maxNanos) maxNanos = latencyNanos;
        }

        void printStats() {
            long c = count.sum();
            long avg = c == 0 ? 0 : totalNanos.sum() / c;
            System.out.println("Messages processed: " + c);
            System.out.println("Avg latency (ns): " + avg);
            System.out.println("Min latency (ns): " + minNanos);
            System.out.println("Max latency (ns): " + maxNanos);
        }
    }

    // Router/dispatcher
    static class Router implements Runnable {
        private final BlockingQueue<Message> queue;
        private final LatencyMonitor monitor;
        private volatile boolean running = true;

        Router(BlockingQueue<Message> queue, LatencyMonitor monitor) {
            this.queue = queue;
            this.monitor = monitor;
        }

        public void stop() {
            running = false;
        }

        @Override
        public void run() {
            while (running || !queue.isEmpty()) {
                try {
                    Message msg = queue.take();

                    // Simulated routing decision
                    route(msg);

                    long latency = System.nanoTime() - msg.createdNanos;
                    monitor.record(latency);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }

        private void route(Message msg) {
            // Minimal routing logic
            // Example: route by key
            if ((msg.routingKey & 1) == 0) {
                // route to destination A
            } else {
                // route to destination B
            }
        }
    }

    public static void main(String[] args) throws Exception {
        final int queueSize = 1 << 16;
        final int messageCount = 1_000_000;

        BlockingQueue<Message> queue = new ArrayBlockingQueue<>(queueSize);
        LatencyMonitor monitor = new LatencyMonitor();
        Router router = new Router(queue, monitor);

        Thread routerThread = new Thread(router, "router-thread");
        routerThread.start();

        long start = System.nanoTime();

        // Producer loop
        for (int i = 0; i < messageCount; i++) {
            queue.put(new Message(i, "msg-" + i));
        }

        // Wait for all messages to be processed
        while (!queue.isEmpty()) {
            Thread.sleep(1);
        }

        router.stop();
        routerThread.join();

        long elapsed = System.nanoTime() - start;
        double seconds = elapsed / 1_000_000_000.0;
        double throughput = messageCount / seconds;

        System.out.printf("Throughput: %.2f messages/sec%n", throughput);
        monitor.printStats();
    }
}
