use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy)]
struct Message {
    created_at: Instant,
    payload: u64,
}

fn producer(id: usize, tx: Sender<Message>, count: usize) {
    for i in 0..count {
        let msg = Message {
            created_at: Instant::now(),
            payload: (id as u64) << 32 | i as u64,
        };

        // Backpressure-aware send
        if tx.send(msg).is_err() {
            break;
        }
    }
}

fn router(rx: Receiver<Message>) {
    let mut histogram = Histogram::<u64>::new(3).expect("histogram");
    let mut received: u64 = 0;
    let start = Instant::now();
    let mut last_report = Instant::now();

    while let Ok(msg) = rx.recv() {
        // Route message (minimal placeholder)
        let _route_key = msg.payload % 1024;

        // Measure end-to-end latency in microseconds
        let latency_us = msg.created_at.elapsed().as_micros() as u64;
        let _ = histogram.record(latency_us);

        received += 1;

        // Report every second
        if last_report.elapsed() >= Duration::from_secs(1) {
            let elapsed = start.elapsed().as_secs_f64();
            let throughput = received as f64 / elapsed;

            println!(
                "msgs={} throughput={:.0}/s p50={}us p95={}us p99={}us max={}us",
                received,
                throughput,
                histogram.value_at_quantile(0.50),
                histogram.value_at_quantile(0.95),
                histogram.value_at_quantile(0.99),
                histogram.max(),
            );

            last_report = Instant::now();
        }
    }
}

fn main() {
    let producer_threads = 4;
    let messages_per_thread = 1_000_000;

    // Bounded channel to keep memory under control and apply backpressure
    let (tx, rx) = bounded::<Message>(1_000_000);

    // Start router
    let router_handle = thread::spawn(move || router(rx));

    // Start producers
    let mut handles = Vec::new();
    for id in 0..producer_threads {
        let tx_clone = tx.clone();
        handles.push(thread::spawn(move || {
            producer(id, tx_clone, messages_per_thread);
        }));
    }

    drop(tx); // close channel when all producers finish

    for h in handles {
        h.join().unwrap();
    }

    router_handle.join().unwrap();
}
