```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use std::hash::{Hash, Hasher};
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: String,
    created_ns: u64,
    payload: Vec<u8>,
}

#[derive(Debug)]
struct RoutedMessage {
    message: Message,
    routed_ns: u64,
}

struct Metrics {
    total_messages: AtomicU64,
    total_latency_ns: AtomicU64,
    min_latency_ns: AtomicU64,
    max_latency_ns: AtomicU64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            total_messages: AtomicU64::new(0),
            total_latency_ns: AtomicU64::new(0),
            min_latency_ns: AtomicU64::new(u64::MAX),
            max_latency_ns: AtomicU64::new(0),
        }
    }

    fn record(&self, latency_ns: u64) {
        self.total_messages.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(latency_ns, Ordering::Relaxed);

        // Update max
        let mut current_max = self.max_latency_ns.load(Ordering::Relaxed);
        while latency_ns > current_max {
            match self.max_latency_ns.compare_exchange(
                current_max,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(old) => current_max = old,
            }
        }

        // Update min
        let mut current_min = self.min_latency_ns.load(Ordering::Relaxed);
        while latency_ns < current_min {
            match self.min_latency_ns.compare_exchange(
                current_min,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(old) => current_min = old,
            }
        }
    }
}

fn now_ns(start: Instant) -> u64 {
    start.elapsed().as_nanos() as u64
}

fn hash_topic(topic: &str) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    topic.hash(&mut hasher);
    hasher.finish()
}

fn producer(tx: Sender<Message>, stop: Arc<AtomicBool>, start: Instant) {
    let mut id = 0u64;
    let payload = vec![0u8; 64];

    while !stop.load(Ordering::Relaxed) {
        let msg = Message {
            id,
            topic: format!("topic-{}", id % 128),
            created_ns: now_ns(start),
            payload: payload.clone(),
        };

        if tx.send(msg).is_err() {
            break;
        }

        id += 1;
    }
}

fn router_worker(
    rx: Receiver<Message>,
    partitions: Vec<Sender<RoutedMessage>>,
    metrics: Arc<Metrics>,
    stop: Arc<AtomicBool>,
    start: Instant,
) {
    while !stop.load(Ordering::Relaxed) {
        match rx.recv() {
            Ok(msg) => {
                let partition_idx = (hash_topic(&msg.topic) as usize) % partitions.len();

                let routed = RoutedMessage {
                    message: msg,
                    routed_ns: now_ns(start),
                };

                let latency_ns = routed.routed_ns - routed.message.created_ns;
                metrics.record(latency_ns);

                // Simulate routing by forwarding to output partition
                let _ = partitions[partition_idx].send(routed);
            }
            Err(_) => break,
        }
    }
}

fn sink_worker(rx: Receiver<RoutedMessage>, stop: Arc<AtomicBool>) {
    while !stop.load(Ordering::Relaxed) {
        match rx.recv() {
            Ok(_msg) => {
                // In a real system, this would publish to downstream consumers.
                // Here we just consume it.
            }
            Err(_) => break,
        }
    }
}

fn metrics_reporter(metrics: Arc<Metrics>, stop: Arc<AtomicBool>) {
    let mut last_count = 0u64;
    let mut last_total_latency = 0u64;
    let mut last_time = Instant::now();

    while !stop.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_secs(1));

        let now = Instant::now();
        let elapsed = now.duration_since(last_time).as_secs_f64();
        last_time = now;

        let count = metrics.total_messages.load(Ordering::Relaxed);
        let total_latency = metrics.total_latency_ns.load(Ordering::Relaxed);

        let delta_count = count - last_count;
        let delta_latency = total_latency - last_total_latency;

        last_count = count;
        last_total_latency = total_latency;

        let msg_per_sec = delta_count as f64 / elapsed;
        let avg_latency = if delta_count > 0 {
            delta_latency as f64 / delta_count as f64
        } else {
            0.0
        };

        let min_latency = metrics.min_latency_ns.load(Ordering::Relaxed);
        let max_latency = metrics.max_latency_ns.load(Ordering::Relaxed);

        println!(
            "throughput={:.0} msg/s avg_latency={:.2} ns min={} ns max={} ns total={}",
            msg_per_sec,
            avg_latency,
            if min_latency == u64::MAX { 0 } else { min_latency },
            max_latency,
            count
        );
    }
}

fn main() {
    let start = Instant::now();
    let stop = Arc::new(AtomicBool::new(false));
    let metrics = Arc::new(Metrics::new());

    // Main ingress queue
    let (tx, rx) = bounded::<Message>(1_000_000);

    // Output partitions
    let mut partitions = Vec::new();
    let mut sink_threads = Vec::new();
    for _ in 0..8 {
        let (ptx, prx) = bounded::<RoutedMessage>(100_000);
        partitions.push(ptx);

        let stop_clone = stop.clone();
        sink_threads.push(thread::spawn(move || sink_worker(prx, stop_clone)));
    }

    // Producer
    let stop_clone = stop.clone();
    let tx_clone = tx.clone();
    let producer_thread = thread::spawn(move || producer(tx_clone, stop_clone, start));

    // Router worker
    let stop_clone = stop.clone();
    let metrics_clone = metrics.clone();
    let router_thread = thread::spawn(move || router_worker(rx, partitions, metrics_clone, stop_clone, start));

    // Metrics
    let stop_clone = stop.clone();
    let metrics_clone = metrics.clone();
    let metrics_thread = thread::spawn(move || metrics_reporter(metrics_clone, stop_clone));

    // Run for 10 seconds
    thread::sleep(Duration::from_secs(10));
    stop.store(true, Ordering::Relaxed);

    let _ = producer_thread.join();
    let _ = router_thread.join();
    let _ = metrics_thread.join();
    for t in sink_threads {
        let _ = t.join();
    }

    println!("done");
}
