use anyhow::{Context, Result};
use pnet::datalink::{self, Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::Packet;
use std::env;
use std::net::Ipv4Addr;
use std::time::Duration;

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .context(format!("interface '{}' not found", name))
}

fn should_forward(eth: &EthernetPacket) -> bool {
    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                match ipv4.get_next_level_protocol() {
                    IpNextHeaderProtocols::Tcp => {
                        if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                            let dst = tcp.get_destination();
                            // Example filter: forward only HTTP/HTTPS traffic
                            dst == 80 || dst == 443
                        } else {
                            false
                        }
                    }
                    _ => false,
                }
            } else {
                false
            }
        }
        _ => false,
    }
}

fn rewrite_and_forward(
    tx: &mut dyn datalink::DataLinkSender,
    frame: &[u8],
) -> Result<()> {
    // This example simply forwards the frame unchanged.
    // In real setups, you may need to rewrite MAC addresses.
    tx.send_to(frame, None)
        .context("failed to send frame")?
        .ok_or_else(|| anyhow::anyhow!("send_to returned None"))?;
    Ok(())
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <input_iface> <output_iface>", args[0]);
        std::process::exit(1);
    }

    let in_iface = find_interface(&args[1])?;
    let out_iface = find_interface(&args[2])?;

    let mut rx_cfg = Config::default();
    rx_cfg.read_timeout = Some(Duration::from_millis(10));

    let mut tx_cfg = Config::default();

    let (_, mut rx) = match datalink::channel(&in_iface, rx_cfg)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unhandled channel type on input"),
    };

    let (mut tx, _) = match datalink::channel(&out_iface, tx_cfg)? {
        Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unhandled channel type on output"),
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(eth) = EthernetPacket::new(packet) {
                    if should_forward(&eth) {
                        rewrite_and_forward(&mut tx, packet)?;
                    }
                }
            }
            Err(_) => {
                // timeout or transient read error; continue
                continue;
            }
        }
    }
}
