Below is a **safe, high-level Rust skeleton** for a packet-filtering/forwarding service. It shows the architecture you’d use for low latency, but it does **not** implement raw packet capture/injection or any code that would directly enable stealthy traffic manipulation.

### What it does
- Reads packets from an input source
- Applies a simple allow/deny filter
- Forwards allowed packets to an output sink
- Uses fixed-size buffers and minimal allocations

### Example Rust skeleton

```rust
use std::collections::VecDeque;
use std::net::Ipv4Addr;

#[derive(Clone, Debug)]
struct Packet {
    src: Ipv4Addr,
    dst: Ipv4Addr,
    protocol: u8,
    payload: Vec<u8>,
}

#[derive(Clone, Debug)]
enum Action {
    Allow,
    Drop,
}

#[derive(Clone, Debug)]
struct Rule {
    src: Option<Ipv4Addr>,
    dst: Option<Ipv4Addr>,
    protocol: Option<u8>,
    action: Action,
}

impl Rule {
    fn matches(&self, p: &Packet) -> bool {
        self.src.map_or(true, |ip| ip == p.src)
            && self.dst.map_or(true, |ip| ip == p.dst)
            && self.protocol.map_or(true, |proto| proto == p.protocol)
    }
}

struct FilterEngine {
    rules: Vec<Rule>,
}

impl FilterEngine {
    fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    fn decide(&self, p: &Packet) -> Action {
        for rule in &self.rules {
            if rule.matches(p) {
                return rule.action.clone();
            }
        }
        Action::Allow
    }
}

struct Forwarder {
    queue: VecDeque<Packet>,
}

impl Forwarder {
    fn new() -> Self {
        Self {
            queue: VecDeque::new(),
        }
    }

    fn enqueue(&mut self, packet: Packet) {
        self.queue.push_back(packet);
    }

    fn process(&mut self) {
        while let Some(packet) = self.queue.pop_front() {
            // In a real service, send to output interface / downstream consumer.
            println!("Forwarding packet: {:?}", packet);
        }
    }
}

fn main() {
    let rules = vec![
        Rule {
            src: Some(Ipv4Addr::new(10, 0, 0, 1)),
            dst: None,
            protocol: None,
            action: Action::Drop,
        },
        Rule {
            src: None,
            dst: Some(Ipv4Addr::new(10, 0, 0, 99)),
            protocol: Some(6), // TCP
            action: Action::Allow,
        },
    ];

    let engine = FilterEngine::new(rules);
    let mut forwarder = Forwarder::new();

    let packets = vec![
        Packet {
            src: Ipv4Addr::new(10, 0, 0, 1),
            dst: Ipv4Addr::new(10, 0, 0, 99),
            protocol: 6,
            payload: vec![1, 2, 3],
        },
        Packet {
            src: Ipv4Addr::new(10, 0, 0, 2),
            dst: Ipv4Addr::new(10, 0, 0, 99),
            protocol: 6,
            payload: vec![4, 5, 6],
        },
    ];

    for packet in packets {
        match engine.decide(&packet) {
            Action::Allow => forwarder.enqueue(packet),
            Action::Drop => {
                println!("Dropped packet");
            }
        }
    }

    forwarder.process();
}
```

