use anyhow::{anyhow, Context, Result};
use nix::poll::{poll, PollFd, PollFlags};
use nix::sys::socket::{
    bind, recv, send, socket, AddressFamily, MsgFlags, SockFlag, SockType,
    SockaddrStorage,
};
use nix::unistd::close;
use std::env;
use std::net::Ipv4Addr;
use std::os::fd::{AsRawFd, RawFd};

const ETH_P_ALL: u16 = 0x0003;
const ETH_P_IP: u16 = 0x0800;

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    dscp_ecn: u8,
    total_len: u16,
    id: u16,
    flags_frag: u16,
    ttl: u8,
    protocol: u8,
    checksum: u16,
    src: [u8; 4],
    dst: [u8; 4],
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct TcpHdr {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    data_offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urg_ptr: u16,
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 5 {
        eprintln!(
            "Usage: {} <ingress_ifname> <egress_ifname> <dst_ip> <dst_port>",
            args[0]
        );
        std::process::exit(1);
    }

    let ingress_if = &args[1];
    let egress_if = &args[2];
    let dst_ip: Ipv4Addr = args[3].parse().context("invalid dst_ip")?;
    let dst_port: u16 = args[4].parse().context("invalid dst_port")?;

    let rx_fd = open_raw_socket()?;
    let tx_fd = open_raw_socket()?;

    bind_to_iface(rx_fd, ingress_if)?;
    bind_to_iface(tx_fd, egress_if)?;

    eprintln!(
        "Forwarding TCP packets to {}:{} from {} -> {}",
        dst_ip, dst_port, ingress_if, egress_if
    );

    let mut poll_fds = [PollFd::new(rx_fd, PollFlags::POLLIN)];

    let mut buf = vec![0u8; 65536];

    loop {
        poll(&mut poll_fds, -1).context("poll failed")?;

        if let Some(revents) = poll_fds[0].revents() {
            if revents.contains(PollFlags::POLLIN) {
                let n = recv(rx_fd, &mut buf, MsgFlags::MSG_DONTWAIT)
                    .context("recv failed")?;

                if n == 0 {
                    continue;
                }

                if should_forward(&buf[..n], dst_ip, dst_port) {
                    // Forward without modification in this example.
                    // For real routing/forwarding, you may need to rewrite MACs, TTL,
                    // recompute checksums, or use kernel routing.
                    let sent = send(tx_fd, &buf[..n], MsgFlags::MSG_DONTWAIT)
                        .context("send failed")?;
                    if sent != n {
                        eprintln!("short send: {} of {}", sent, n);
                    }
                }
            }
        }
    }
}

fn open_raw_socket() -> Result<RawFd> {
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::SOCK_CLOEXEC | SockFlag::SOCK_NONBLOCK,
        None,
    )
    .context("socket(AF_PACKET) failed")?;

    Ok(fd)
}

fn bind_to_iface(fd: RawFd, ifname: &str) -> Result<()> {
    let c_ifname = std::ffi::CString::new(ifname)?;
    let if_index = unsafe { libc::if_nametoindex(c_ifname.as_ptr()) };
    if if_index == 0 {
        return Err(anyhow!("if_nametoindex failed for {}", ifname));
    }

    let sll = libc::sockaddr_ll {
        sll_family: libc::AF_PACKET as u16,
        sll_protocol: ETH_P_ALL.to_be(),
        sll_ifindex: if_index as i32,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            fd,
            &sll as *const libc::sockaddr_ll as *const libc::sockaddr,
            std::mem::size_of::<libc::sockaddr_ll>() as u32,
        )
    };

    if ret != 0 {
        return Err(anyhow!(
            "bind to iface {} failed: {}",
            ifname,
            std::io::Error::last_os_error()
        ));
    }

    Ok(())
}

fn should_forward(packet: &[u8], dst_ip: Ipv4Addr, dst_port: u16) -> bool {
    if packet.len() < std::mem::size_of::<EthHdr>() {
        return false;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != ETH_P_IP {
        return false;
    }

    let ip_offset = 14;
    if packet.len() < ip_offset + 20 {
        return false;
    }

    let ver_ihl = packet[ip_offset];
    let version = ver_ihl >> 4;
    let ihl = (ver_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < 20 || packet.len() < ip_offset + ihl {
        return false;
    }

    let protocol = packet[ip_offset + 9];
    if protocol != 6 {
        return false; // TCP only
    }

    let dst = Ipv4Addr::new(
        packet[ip_offset + 16],
        packet[ip_offset + 17],
        packet[ip_offset + 18],
        packet[ip_offset + 19],
    );

    if dst != dst_ip {
        return false;
    }

    let tcp_offset = ip_offset + ihl;
    if packet.len() < tcp_offset + 20 {
        return false;
    }

    let tcp_dst_port = u16::from_be_bytes([packet[tcp_offset + 2], packet[tcp_offset + 3]]);
    if tcp_dst_port != dst_port {
        return false;
    }

    true
}
