```rust
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

#[derive(Clone, Debug)]
struct Packet {
    src: String,
    dst: String,
    protocol: u8,
    payload_len: usize,
}

#[derive(Debug, Clone, Copy)]
enum Action {
    Allow,
    Drop,
    Forward,
}

trait Filter: Send + Sync {
    fn evaluate(&self, pkt: &Packet) -> Action;
}

struct SimpleFilter;

impl Filter for SimpleFilter {
    fn evaluate(&self, pkt: &Packet) -> Action {
        // Example policy:
        // - Drop empty payloads
        // - Forward UDP-like traffic
        // - Allow everything else
        if pkt.payload_len == 0 {
            Action::Drop
        } else if pkt.protocol == 17 {
            Action::Forward
        } else {
            Action::Allow
        }
    }
}

struct Pipeline {
    filters: Vec<Box<dyn Filter>>,
}

impl Pipeline {
    fn new() -> Self {
        Self { filters: Vec::new() }
    }

    fn add_filter<F: Filter + 'static>(&mut self, f: F) {
        self.filters.push(Box::new(f));
    }

    fn process(&self, pkt: &Packet) -> Action {
        for f in &self.filters {
            match f.evaluate(pkt) {
                Action::Allow => continue,
                other => return other,
            }
        }
        Action::Allow
    }
}

fn worker_thread(pipeline: Arc<Mutex<Pipeline>>) {
    // Simulated packet stream
    let packets = vec![
        Packet { src: "10.0.0.1".into(), dst: "10.0.0.2".into(), protocol: 17, payload_len: 128 },
        Packet { src: "10.0.0.3".into(), dst: "10.0.0.4".into(), protocol: 6, payload_len: 0 },
        Packet { src: "10.0.0.5".into(), dst: "10.0.0.6".into(), protocol: 1, payload_len: 64 },
    ];

    for pkt in packets {
        let action = {
            let guard = pipeline.lock().unwrap();
            guard.process(&pkt)
        };

        match action {
            Action::Allow => println!("ALLOW {:?}", pkt),
            Action::Drop => println!("DROP  {:?}", pkt),
            Action::Forward => println!("FWD   {:?}", pkt),
        }

        thread::sleep(Duration::from_millis(10));
    }
}

fn main() {
    let mut p = Pipeline::new();
    p.add_filter(SimpleFilter);

    let pipeline = Arc::new(Mutex::new(p));
    let t = {
        let pipeline = Arc::clone(&pipeline);
        thread::spawn(move || worker_thread(pipeline))
    };

    t.join().unwrap();
}
