#[derive(Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    tos: u8,
    total_len: u16,
    id: u16,
    frag_off: u16,
    ttl: u8,
    protocol: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

fn htons(x: u16) -> u16 {
    x.to_be()
}

fn open_packet_socket(ifindex: i32) -> io::Result<RawFd> {
    let fd = unsafe { libc::socket(AF_PACKET, libc::SOCK_RAW, i32::from(htons(ETH_P_ALL as u16))) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }

    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL as u16),
        sll_ifindex: ifindex,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        let err = io::Error::last_os_error();
        unsafe { libc::close(fd) };
        return Err(err);
    }

    Ok(fd)
}

fn set_socket_options(fd: RawFd) -> io::Result<()> {
    let version: i32 = 1;
    let ret = unsafe {
        libc::setsockopt(
            fd,
            libc::SOL_PACKET,
            PACKET_VERSION,
            &version as *const i32 as *const c_void,
            mem::size_of::<i32>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    Ok(())
}

fn allow_packet(buf: &[u8]) -> bool {
    if buf.len() < mem::size_of::<EthHdr>() {
        return false;
    }

    let eth = unsafe { &*(buf.as_ptr() as *const EthHdr) };
    let ethertype = u16::from_be(eth.ethertype);

    // Allow only IPv4 packets for now
    ethertype == 0x0800
}

fn inspect_ipv4(buf: &[u8]) {
    if buf.len() < mem::size_of::<EthHdr>() + mem::size_of::<Ipv4Hdr>() {
        return;
    }

    let ip = unsafe {
        &*(buf[mem::size_of::<EthHdr>()..].as_ptr() as *const Ipv4Hdr)
    };

    let proto = ip.protocol;
    let src = u32::from_be(ip.src);
    let dst = u32::from_be(ip.dst);

    // Placeholder for fast-path telemetry/logging
    let _ = (proto, src, dst);
}

fn forward_packet(tx_fd: RawFd, buf: &[u8]) -> io::Result<()> {
    let ret = unsafe { libc::send(tx_fd, buf.as_ptr() as *const c_void, buf.len(), 0) };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn main() -> io::Result<()> {
    // Replace with your actual interface indexes
    let rx_ifindex = 2;
    let tx_ifindex = 3;

    let rx_fd = open_packet_socket(rx_ifindex)?;
    let tx_fd = open_packet_socket(tx_ifindex)?;

    set_socket_options(rx_fd)?;
    set_socket_options(tx_fd)?;

    // Simple fixed-size packet buffer
    let mut packet_buf = vec![0u8; 2048];

    println!("Starting packet forwarder...");

    while RUNNING.load(Ordering::Relaxed) {
        let ret = unsafe {
            libc::recv(
                rx_fd,
                packet_buf.as_mut_ptr() as *mut c_void,
                packet_buf.len(),
                0,
            )
        };

        if ret < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            eprintln!("recv error: {}", err);
            break;
        }

        let len = ret as usize;
        let pkt = &packet_buf[..len];

        if allow_packet(pkt) {
            inspect_ipv4(pkt);
            if let Err(e) = forward_packet(tx_fd, pkt) {
                eprintln!("forward error: {}", e);
            }
        }
    }

    unsafe {
        libc::close(rx_fd);
        libc::close(tx_fd);
    }

    Ok(())
}
