use crossbeam::channel::{bounded, Receiver, Sender};
use pnet_datalink::{self, Channel::Ethernet};
use pnet_packet::ethernet::{EtherTypes, EthernetPacket};
use pnet_packet::ip::IpNextHeaderProtocols;
use pnet_packet::ipv4::Ipv4Packet;
use pnet_packet::udp::UdpPacket;
use pnet_packet::Packet;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Clone, Debug)]
struct PacketDecision {
    forward: bool,
    out_iface: Option<String>,
}

#[derive(Clone, Debug)]
struct FilterRule {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol_udp: Option<bool>,
    forward_to: Option<String>,
}

impl FilterRule {
    fn matches_ipv4_udp(&self, src_ip: Ipv4Addr, dst_ip: Ipv4Addr, src_port: u16, dst_port: u16) -> bool {
        if let Some(rule_src) = self.src_ip {
            if rule_src != src_ip {
                return false;
            }
        }
        if let Some(rule_dst) = self.dst_ip {
            if rule_dst != dst_ip {
                return false;
            }
        }
        if let Some(rule_src_port) = self.src_port {
            if rule_src_port != src_port {
                return false;
            }
        }
        if let Some(rule_dst_port) = self.dst_port {
            if rule_dst_port != dst_port {
                return false;
            }
        }
        if let Some(udp_only) = self.protocol_udp {
            if !udp_only {
                return false;
            }
        }
        true
    }
}

#[derive(Clone)]
struct PacketFilterEngine {
    rules: Arc<Vec<FilterRule>>,
    default_forward_iface: Option<String>,
}

impl PacketFilterEngine {
    fn new(rules: Vec<FilterRule>, default_forward_iface: Option<String>) -> Self {
        Self {
            rules: Arc::new(rules),
            default_forward_iface,
        }
    }

    fn evaluate(&self, frame: &[u8]) -> PacketDecision {
        let eth_pkt = match EthernetPacket::new(frame) {
            Some(pkt) => pkt,
            None => return PacketDecision { forward: false, out_iface: None },
        };

        match eth_pkt.get_ethertype() {
            EtherTypes::Ipv4 => {
                let ipv4_pkt = match Ipv4Packet::new(eth_pkt.payload()) {
                    Some(pkt) => pkt,
                    None => return PacketDecision { forward: false, out_iface: None },
                };

                if ipv4_pkt.get_next_level_protocol() != IpNextHeaderProtocols::Udp {
                    return PacketDecision { forward: false, out_iface: None };
                }

                let udp_pkt = match UdpPacket::new(ipv4_pkt.payload()) {
                    Some(pkt) => pkt,
                    None => return PacketDecision { forward: false, out_iface: None },
                };

                let src_ip = ipv4_pkt.get_source();
                let dst_ip = ipv4_pkt.get_destination();
                let src_port = udp_pkt.get_source();
                let dst_port = udp_pkt.get_destination();

                for rule in self.rules.iter() {
                    if rule.matches_ipv4_udp(src_ip, dst_ip, src_port, dst_port) {
                        return PacketDecision {
                            forward: true,
                            out_iface: rule.forward_to.clone().or(self.default_forward_iface.clone()),
                        };
                    }
                }

                PacketDecision {
                    forward: false,
                    out_iface: None,
                }
            }
            _ => PacketDecision {
                forward: false,
                out_iface: None,
            },
        }
    }
}

fn spawn_rx_loop(
    iface_name: String,
    tx: Sender<Vec<u8>>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let interfaces = pnet_datalink::interfaces();
        let iface = interfaces
            .into_iter()
            .find(|i| i.name == iface_name)
            .expect("Interface not found");

        let config = pnet_datalink::Config {
            read_timeout: Some(Duration::from_millis(1)),
            ..Default::default()
        };

        let channel = pnet_datalink::channel(&iface, config)
            .expect("Failed to open datalink channel");

        let mut rx = match channel {
            Ethernet(_, rx) => rx,
            _ => panic!("Unhandled channel type"),
        };

        loop {
            match rx.next() {
                Ok(packet) => {
                    // Copying here is not ideal for ultra-low-latency.
                    // Replace with zero-copy ring buffers or DPDK mbufs in production.
                    let mut buf = Vec::with_capacity(packet.len());
                    buf.extend_from_slice(packet);

                    if tx.send(buf).is_err() {
                        break;
                    }
                }
                Err(_) => {
                    continue;
                }
            }
        }
    })
}

fn spawn_forward_loop(
    iface_name: String,
    rx: Receiver<Vec<u8>>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let interfaces = pnet_datalink::interfaces();
        let iface = interfaces
            .into_iter()
            .find(|i| i.name == iface_name)
            .expect("Interface not found");

        let config = pnet_datalink::Config::default();
        let channel = pnet_datalink::channel(&iface, config)
            .expect("Failed to open datalink channel");

        let mut tx = match channel {
            Ethernet(tx, _) => tx,
            _ => panic!("Unhandled channel type"),
        };

        while let Ok(packet) = rx.recv() {
            let _ = tx.send_to(&packet, None);
        }
    })
}

fn main() {
    // Example rules: forward UDP traffic matching these tuples
    let rules = vec![
        FilterRule {
            src_ip: Some("10.0.0.10".parse().unwrap()),
            dst_ip: Some("10.0.0.20".parse().unwrap()),
            src_port: Some(12345),
            dst_port: Some(8080),
            protocol_udp: Some(true),
            forward_to: Some("eth1".to_string()),
        },
    ];

    let engine = PacketFilterEngine::new(rules, Some("eth1".to_string()));

    let (tx_rx, rx_rx) = bounded::<Vec<u8>>(1024);
    let (tx_fw, rx_fw) = bounded::<Vec<u8>>(1024);

    // Single ingress interface
    let ingress_iface = "eth0".to_string();
    let egress_iface = "eth1".to_string();

    let _rx_handle = spawn_rx_loop(ingress_iface, tx_rx);
    let _fw_handle = spawn_forward_loop(egress_iface, rx_fw);

    // Processing loop
    loop {
        match rx_rx.recv() {
            Ok(packet) => {
                let decision = engine.evaluate(&packet);

                if decision.forward {
                    let _ = tx_fw.send(packet);
                }
            }
            Err(_) => break,
        }
    }
}
