## 3. Packet representation

### `src/packet.rs`
```rust
use std::net::Ipv4Addr;

#[derive(Clone, Debug)]
pub struct Packet {
    pub data: Vec<u8>,
}

#[derive(Clone, Copy, Debug)]
pub struct EthernetHeader {
    pub dst: [u8; 6],
    pub src: [u8; 6],
    pub ethertype: u16,
}

#[derive(Clone, Copy, Debug)]
pub struct Ipv4Header {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub protocol: u8,
    pub ttl: u8,
}

#[derive(Clone, Copy, Debug)]
pub struct TcpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Clone, Copy, Debug)]
pub struct UdpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

impl Packet {
    pub fn new(data: Vec<u8>) -> Self {
        Self { data }
    }

    pub fn ipv4_tcp(
        dst_mac: [u8; 6],
        src_mac: [u8; 6],
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        payload: Vec<u8>,
    ) -> Self {
        let mut data = Vec::with_capacity(14 + 20 + 20 + payload.len());

        // Ethernet
        data.extend_from_slice(&dst_mac);
        data.extend_from_slice(&src_mac);
        data.extend_from_slice(&0x0800u16.to_be_bytes());

        // IPv4 header (minimal, not checksum-complete in this starter)
        data.push(0x45); // version/IHL
        data.push(0); // DSCP/ECN
        let total_len = (20 + 20 + payload.len()) as u16;
        data.extend_from_slice(&total_len.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes()); // identification
        data.extend_from_slice(&0u16.to_be_bytes()); // flags/fragment
        data.push(64); // TTL
        data.push(6); // TCP
        data.extend_from_slice(&0u16.to_be_bytes()); // checksum placeholder
        data.extend_from_slice(&src_ip.octets());
        data.extend_from_slice(&dst_ip.octets());

        // TCP header (very minimal)
        data.extend_from_slice(&src_port.to_be_bytes());
        data.extend_from_slice(&dst_port.to_be_bytes());
        data.extend_from_slice(&0u32.to_be_bytes()); // seq
        data.extend_from_slice(&0u32.to_be_bytes()); // ack
        data.push(0x50); // data offset
        data.push(0x18); // flags
        data.extend_from_slice(&64240u16.to_be_bytes()); // window
        data.extend_from_slice(&0u16.to_be_bytes()); // checksum
        data.extend_from_slice(&0u16.to_be_bytes()); // urgent

        data.extend_from_slice(&payload);

        Self { data }
    }

    pub fn ipv4_udp(
        dst_mac: [u8; 6],
        src_mac: [u8; 6],
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        payload: Vec<u8>,
    ) -> Self {
        let mut data = Vec::with_capacity(14 + 20 + 8 + payload.len());

        // Ethernet
        data.extend_from_slice(&dst_mac);
        data.extend_from_slice(&src_mac);
        data.extend_from_slice(&0x0800u16.to_be_bytes());

        // IPv4 header
        data.push(0x45);
        data.push(0);
        let total_len = (20 + 8 + payload.len()) as u16;
        data.extend_from_slice(&total_len.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.push(64);
        data.push(17); // UDP
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&src_ip.octets());
        data.extend_from_slice(&dst_ip.octets());

        // UDP header
        data.extend_from_slice(&src_port.to_be_bytes());
        data.extend_from_slice(&dst_port.to_be_bytes());
        data.extend_from_slice(&((8 + payload.len()) as u16).to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());

        data.extend_from_slice(&payload);

        Self { data }
    }

    pub fn parse_ipv4(&self) -> Option<Ipv4Header> {
        if self.data.len() < 14 + 20 {
            return None;
        }
        let ethertype = u16::from_be_bytes([self.data[12], self.data[13]]);
        if ethertype != 0x0800 {
            return None;
        }

        let ip = &self.data[14..];
        let protocol = ip[9];
        let ttl = ip[8];
        let src = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
        let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

        Some(Ipv4Header { src, dst, protocol, ttl })
    }

    pub fn parse_l4_ports(&self) -> Option<(u8, u16, u16)> {
        let ip = self.parse_ipv4()?;
        let ihl = ((self.data[14] & 0x0f) as usize) * 4;
        let l4_off = 14 + ihl;
        if self.data.len() < l4_off + 4 {
            return None;
        }

        let src_port = u16::from_be_bytes([self.data[l4_off], self.data[l4_off + 1]]);
        let dst_port = u16::from_be_bytes([self.data[l4_off + 2], self.data[l4_off + 3]]);
        Some((ip.protocol, src_port, dst_port))
    }
}
