use std::net::Ipv4Addr;

use crate::packet::Packet;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Action {
    Forward(u16), // output port
    Drop,
}

#[derive(Clone, Debug)]
pub enum Rule {
    DropSrcIp { network: u32, mask: u32 },
    DropDstPort(u16),
    ForwardAll,
}

#[derive(Clone, Debug)]
pub struct RuleSet {
    pub rules: Vec<Rule>,
}

impl RuleSet {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    pub fn evaluate(&self, pkt: &Packet) -> Action {
        let ip = match pkt.parse_ipv4() {
            Some(ip) => ip,
            None => return Action::Drop,
        };

        for rule in &self.rules {
            match rule {
                Rule::DropSrcIp { network, mask } => {
                    let src = ipv4_to_u32(ip.src);
                    if (src & mask) == *network {
                        return Action::Drop;
                    }
                }
                Rule::DropDstPort(port) => {
                    if let Some((_, _, dst_port)) = pkt.parse_l4_ports() {
                        if dst_port == *port {
                            return Action::Drop;
                        }
                    }
                }
                Rule::ForwardAll => {
                    return Action::Forward(0);
                }
            }
        }

        Action::Drop
    }
}

impl Rule {
    pub fn drop_src_ip(addr: Ipv4Addr, prefix_len: u8) -> Self {
        let ip = ipv4_to_u32(addr);
        let mask = if prefix_len == 0 {
            0
        } else {
            u32::MAX << (32 - prefix_len)
        };
        Self::DropSrcIp {
            network: ip & mask,
            mask,
        }
    }

    pub fn drop_dst_port(port: u16) -> Self {
        Self::DropDstPort(port)
    }

    pub fn forward_all() -> Self {
        Self::ForwardAll
    }
}

fn ipv4_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from_be_bytes(ip.octets())
}
