use etherparse::{Ethernet2HeaderSlice, Ipv4HeaderSlice, TcpHeaderSlice, UdpHeaderSlice};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TransportProto {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketView<'a> {
    pub data: &'a [u8],
    pub ethertype: Option<u16>,
    pub src_ip: Option<[u8; 4]>,
    pub dst_ip: Option<[u8; 4]>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: TransportProto,
}

impl<'a> PacketView<'a> {
    pub fn parse(data: &'a [u8]) -> Self {
        let mut view = PacketView {
            data,
            ethertype: None,
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
            proto: TransportProto::Other(0),
        };

        if let Ok(eth) = Ethernet2HeaderSlice::from_slice(data) {
            view.ethertype = Some(eth.ether_type().0);
            let payload = eth.payload();

            if let Ok(ipv4) = Ipv4HeaderSlice::from_slice(payload) {
                view.src_ip = Some(ipv4.source_addr().octets());
                view.dst_ip = Some(ipv4.destination_addr().octets());
                let ip_payload = ipv4.payload();

                match ipv4.protocol() {
                    6 => {
                        view.proto = TransportProto::Tcp;
                        if let Ok(tcp) = TcpHeaderSlice::from_slice(ip_payload) {
                            view.src_port = Some(tcp.source_port());
                            view.dst_port = Some(tcp.destination_port());
                        }
                    }
                    17 => {
                        view.proto = TransportProto::Udp;
                        if let Ok(udp) = UdpHeaderSlice::from_slice(ip_payload) {
                            view.src_port = Some(udp.source_port());
                            view.dst_port = Some(udp.destination_port());
                        }
                    }
                    x => {
                        view.proto = TransportProto::Other(x);
                    }
                }
            }
        }

        view
    }
}
```

