use crate::packet::{PacketView, TransportProto};

#[derive(Debug, Clone)]
pub struct FilterRule {
    pub allow: bool,
    pub proto: Option<TransportProto>,
    pub src_ip_prefix: Option<([u8; 4], u8)>, // prefix + length
    pub dst_ip_prefix: Option<([u8; 4], u8)>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

impl FilterRule {
    pub fn matches(&self, p: &PacketView<'_>) -> bool {
        if let Some(proto) = self.proto {
            if p.proto != proto {
                return false;
            }
        }

        if let Some((prefix, bits)) = self.src_ip_prefix {
            if !matches_ipv4_prefix(p.src_ip, prefix, bits) {
                return false;
            }
        }

        if let Some((prefix, bits)) = self.dst_ip_prefix {
            if !matches_ipv4_prefix(p.dst_ip, prefix, bits) {
                return false;
            }
        }

        if let Some(port) = self.src_port {
            if p.src_port != Some(port) {
                return false;
            }
        }

        if let Some(port) = self.dst_port {
            if p.dst_port != Some(port) {
                return false;
            }
        }

        true
    }
}

fn matches_ipv4_prefix(addr: Option<[u8; 4]>, prefix: [u8; 4], bits: u8) -> bool {
    let Some(addr) = addr else { return false };

    let addr_u32 = u32::from_be_bytes(addr);
    let prefix_u32 = u32::from_be_bytes(prefix);

    let mask = if bits == 0 {
        0
    } else {
        u32::MAX << (32 - bits)
    };

    (addr_u32 & mask) == (prefix_u32 & mask)
}

#[derive(Debug)]
pub struct PacketFilter {
    rules: Vec<FilterRule>,
    default_allow: bool,
}

impl PacketFilter {
    pub fn new(default_allow: bool) -> Self {
        Self {
            rules: Vec::new(),
            default_allow,
        }
    }

    pub fn add_rule(&mut self, rule: FilterRule) {
        self.rules.push(rule);
    }

    pub fn should_forward(&self, p: &PacketView<'_>) -> bool {
        for rule in &self.rules {
            if rule.matches(p) {
                return rule.allow;
            }
        }
        self.default_allow
    }
}
