```rust
use anyhow::{Context, Result};
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::udp::UdpPacket;
use pnet::packet::{MutablePacket, Packet};
use std::env;
use std::net::IpAddr;

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 5 {
        eprintln!(
            "Usage: {} <src_if> <dst_if> <allowed_dst_udp_port> <forward_dst_mac>",
            args[0]
        );
        std::process::exit(1);
    }

    let src_if_name = &args[1];
    let dst_if_name = &args[2];
    let allowed_port: u16 = args[3].parse().context("invalid UDP port")?;
    let forward_dst_mac = parse_mac(&args[4]).context("invalid MAC address")?;

    let interfaces = datalink::interfaces();

    let src_iface = interfaces
        .iter()
        .find(|iface| &iface.name == src_if_name)
        .context("source interface not found")?
        .clone();

    let dst_iface = interfaces
        .iter()
        .find(|iface| &iface.name == dst_if_name)
        .context("destination interface not found")?
        .clone();

    let tx_config = datalink::Config {
        write_buffer_size: 4096,
        ..Default::default()
    };

    let rx_config = datalink::Config {
        read_buffer_size: 4096,
        ..Default::default()
    };

    let mut rx = match datalink::channel(&src_iface, rx_config)? {
        Ethernet(_tx, rx) => rx,
        _ => anyhow::bail!("unsupported source channel type"),
    };

    let mut tx = match datalink::channel(&dst_iface, tx_config)? {
        Ethernet(tx, _rx) => tx,
        _ => anyhow::bail!("unsupported destination channel type"),
    };

    println!(
        "Forwarding UDP packets with dst port {} from {} -> {}",
        allowed_port, src_if_name, dst_if_name
    );

    loop {
        match rx.next() {
            Ok(packet) => {
                if should_forward(packet, allowed_port) {
                    forward_packet(&mut tx, packet, forward_dst_mac)?;
                }
            }
            Err(e) => {
                eprintln!("receive error: {}", e);
            }
        }
    }
}

fn should_forward(packet: &[u8], allowed_port: u16) -> bool {
    let eth = match EthernetPacket::new(packet) {
        Some(pkt) => pkt,
        None => return false,
    };

    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return false;
    }

    let ipv4 = match Ipv4Packet::new(eth.payload()) {
        Some(pkt) => pkt,
        None => return false,
    };

    if ipv4.get_next_level_protocol() != IpNextHeaderProtocols::Udp {
        return false;
    }

    let udp = match UdpPacket::new(ipv4.payload()) {
        Some(pkt) => pkt,
        None => return false,
    };

    udp.get_destination() == allowed_port
}

fn forward_packet(
    tx: &mut impl datalink::DataLinkSender,
    packet: &[u8],
    dst_mac: [u8; 6],
) -> Result<()> {
    let mut buf = vec![0u8; packet.len()];
    buf.copy_from_slice(packet);

    let mut eth = MutableEthernetPacket::new(&mut buf)
        .context("failed to create mutable ethernet packet")?;

    eth.set_destination(pnet::util::MacAddr::new(
        dst_mac[0], dst_mac[1], dst_mac[2], dst_mac[3], dst_mac[4], dst_mac[5],
    ));

    match tx.send_to(eth.packet(), None) {
        Some(Ok(())) => Ok(()),
        Some(Err(e)) => Err(e.into()),
        None => anyhow::bail!("failed to send packet"),
    }
}

fn parse_mac(s: &str) -> Result<[u8; 6]> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() != 6 {
        anyhow::bail!("MAC must have 6 octets");
    }

    let mut mac = [0u8; 6];
    for (i, part) in parts.iter().enumerate() {
        mac[i] = u8::from_str_radix(part, 16).context("invalid MAC octet")?;
    }
    Ok(mac)
}
```

