## `src/main.rs`
```rust
use libc::{
    bind, close, if_nametoindex, recv, sendto, socket, sockaddr, sockaddr_ll, AF_PACKET, ETH_P_ALL,
    ETH_P_IP, SOCK_RAW,
};
use std::env;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::unix::io::RawFd;
use std::ptr;

fn htons(u: u16) -> u16 {
    u.to_be()
}

fn open_packet_socket(iface: &str) -> io::Result<RawFd> {
    unsafe {
        let fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL as u16) as i32);
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let ifindex = if_nametoindex(iface.as_ptr() as *const i8);
        if ifindex == 0 {
            close(fd);
            return Err(io::Error::last_os_error());
        }

        let mut addr: sockaddr_ll = mem::zeroed();
        addr.sll_family = AF_PACKET as u16;
        addr.sll_protocol = htons(ETH_P_ALL as u16);
        addr.sll_ifindex = ifindex as i32;

        let ret = bind(
            fd,
            &addr as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        );
        if ret < 0 {
            close(fd);
            return Err(io::Error::last_os_error());
        }

        Ok(fd)
    }
}

fn forward_packet(fd: RawFd, out_ifindex: i32, packet: &[u8]) -> io::Result<usize> {
    unsafe {
        let mut addr: sockaddr_ll = mem::zeroed();
        addr.sll_family = AF_PACKET as u16;
        addr.sll_ifindex = out_ifindex;
        addr.sll_halen = 6;

        let sent = sendto(
            fd,
            packet.as_ptr() as *const _,
            packet.len(),
            0,
            &addr as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        );

        if sent < 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(sent as usize)
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("usage: {} <in_iface> <out_iface> <ipv4_prefix>", args[0]);
        eprintln!("example: {} eth0 eth1 10.0.0.0/8", args[0]);
        std::process::exit(1);
    }

    let in_iface = &args[1];
    let out_iface = &args[2];
    let prefix = &args[3];

    let (prefix_ip, prefix_len) = parse_cidr(prefix)?;
    let in_fd = open_packet_socket(in_iface)?;
    let out_fd = open_packet_socket(out_iface)?;

    let out_ifindex = unsafe {
        let idx = if_nametoindex(out_iface.as_ptr() as *const i8);
        if idx == 0 {
            close(in_fd);
            close(out_fd);
            return Err(io::Error::last_os_error());
        }
        idx as i32
    };

    let mut buf = vec![0u8; 2048];

    loop {
        let n = unsafe { recv(in_fd, buf.as_mut_ptr() as *mut _, buf.len(), 0) };
        if n < 0 {
            let err = io::Error::last_os_error();
            eprintln!("recv error: {}", err);
            continue;
        }

        let packet = &buf[..n as usize];
        if let Some(ipv4) = extract_ipv4_dst(packet) {
            if cidr_match(ipv4, prefix_ip, prefix_len) {
                let _ = forward_packet(out_fd, out_ifindex, packet);
            }
        }
    }
}

fn parse_cidr(s: &str) -> io::Result<(u32, u8)> {
    let parts: Vec<&str> = s.split('/').collect();
    if parts.len() != 2 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "bad CIDR"));
    }
    let ip: Ipv4Addr = parts[0]
        .parse()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "bad IP"))?;
    let prefix_len: u8 = parts[1]
        .parse()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "bad prefix"))?;
    if prefix_len > 32 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "prefix > 32"));
    }
    Ok((u32::from(ip), prefix_len))
}

fn cidr_match(ip: Ipv4Addr, prefix_ip: u32, prefix_len: u8) -> bool {
    let ip_u32 = u32::from(ip);
    let mask = if prefix_len == 0 {
        0
    } else {
        u32::MAX << (32 - prefix_len)
    };
    (ip_u32 & mask) == (prefix_ip & mask)
}

fn extract_ipv4_dst(packet: &[u8]) -> Option<Ipv4Addr> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != ETH_P_IP as u16 {
        return None;
    }

    if packet.len() < 34 {
        return None;
    }

    // IPv4 destination address at bytes 30..34 in a standard Ethernet+IPv4 packet
    Some(Ipv4Addr::new(packet[30], packet[31], packet[32], packet[33]))
}
```

