## Code: `packet_forwarder.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <net/if.h>
#include <netinet/if_ether.h>
#include <netpacket/packet.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#define BUF_SIZE 2048

static volatile sig_atomic_t running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int bind_raw_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex(ifname);
    if (sll.sll_ifindex == 0) {
        fprintf(stderr, "if_nametoindex(%s) failed\n", ifname);
        close(fd);
        return -1;
    }

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    return fd;
}

static int send_raw_socket(const char *ifname) {
    return bind_raw_socket(ifname);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_if> <output_if>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    int in_fd = bind_raw_socket(in_if);
    if (in_fd < 0) return 1;

    int out_fd = send_raw_socket(out_if);
    if (out_fd < 0) {
        close(in_fd);
        return 1;
    }

    unsigned char buf[BUF_SIZE];

    while (running) {
        ssize_t n = recv(in_fd, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        if (n < (ssize_t)sizeof(struct ethhdr)) {
            continue;
        }

        struct ethhdr *eth = (struct ethhdr *)buf;
        uint16_t proto = ntohs(eth->h_proto);

        // Example filter: forward only IPv4 packets
        if (proto != ETH_P_IP) {
            continue;
        }

        ssize_t sent = send(out_fd, buf, (size_t)n, 0);
        if (sent < 0) {
            perror("send");
            break;
        }
    }

    close(in_fd);
    close(out_fd);
    return 0;
}
```

