## Minimal C implementation

```c
// packet_forwarder.c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <net/if.h>
#include <netinet/ip.h>
#include <netpacket/packet.h>
#include <poll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define BUF_SIZE 2048

static int get_ifindex_and_mac(const char *ifname, int *ifindex, unsigned char mac[6]) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        close(fd);
        return -1;
    }
    *ifindex = ifr.ifr_ifindex;

    if (ioctl(fd, SIOCGIFHWADDR, &ifr) < 0) {
        close(fd);
        return -1;
    }
    memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);

    close(fd);
    return 0;
}

// Simple filter example:
// Drop IPv4 packets with protocol 1 (ICMP), forward everything else.
static int packet_allowed(const unsigned char *buf, ssize_t len) {
    if (len < (ssize_t)(sizeof(struct ethhdr))) return 0;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return 1; // allow non-IPv4
    }

    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return 0;

    const struct iphdr *ip = (const struct iphdr *)(buf + sizeof(struct ethhdr));
    if (ip->protocol == IPPROTO_ICMP) {
        return 0; // drop ICMP
    }

    return 1;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_if> <output_if>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    int in_ifindex, out_ifindex;
    unsigned char out_mac[6];

    if (get_ifindex_and_mac(in_if, &in_ifindex, NULL) < 0) {
        perror("get input interface info");
        return 1;
    }

    if (get_ifindex_and_mac(out_if, &out_ifindex, out_mac) < 0) {
        perror("get output interface info");
        return 1;
    }

    int rx = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (rx < 0) {
        perror("socket rx");
        return 1;
    }

    int tx = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx < 0) {
        perror("socket tx");
        close(rx);
        return 1;
    }

    struct sockaddr_ll rx_addr = {0};
    rx_addr.sll_family = AF_PACKET;
    rx_addr.sll_protocol = htons(ETH_P_ALL);
    rx_addr.sll_ifindex = if_nametoindex(in_if);

    if (bind(rx, (struct sockaddr *)&rx_addr, sizeof(rx_addr)) < 0) {
        perror("bind rx");
        close(rx);
        close(tx);
        return 1;
    }

    struct sockaddr_ll tx_addr = {0};
    tx_addr.sll_family = AF_PACKET;
    tx_addr.sll_ifindex = if_nametoindex(out_if);
    tx_addr.sll_halen = ETH_ALEN;
    memcpy(tx_addr.sll_addr, out_mac, 6);

    unsigned char buf[BUF_SIZE];

    while (1) {
        ssize_t n = recv(rx, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        if (!packet_allowed(buf, n)) {
            continue;
        }

        // Forward packet as-is to output interface.
        // For real forwarding, you would usually rewrite Ethernet
        // addresses and possibly TTL/checksum fields.
        ssize_t sent = sendto(tx, buf, n, 0,
                              (struct sockaddr *)&tx_addr, sizeof(tx_addr));
        if (sent < 0) {
            perror("sendto");
            break;
        }
    }

    close(rx);
    close(tx);
    return 0;
}
```

