use std::fs::File;
use std::io::{self, BufRead, BufReader};

#[derive(Debug)]
struct Record<'a> {
    timestamp: &'a [u8],
    event_type: &'a [u8],
    value: &'a [u8],
}

fn parse_line<'a>(line: &'a [u8]) -> Option<Record<'a>> {
    let first = line.iter().position(|&b| b == b',')?;
    let second = line[first + 1..].iter().position(|&b| b == b',')? + first + 1;

    let timestamp = &line[..first];
    let event_type = &line[first + 1..second];
    let value = &line[second + 1..].trim_ascii_end();

    Some(Record {
        timestamp,
        event_type,
        value,
    })
}

fn process_record(record: &Record) {
    println!("{:?}", record);
}

fn parse_stream<R: BufRead>(mut reader: R) -> io::Result<()> {
    let mut buffer = Vec::new();

    loop {
        buffer.clear();
        let bytes_read = reader.read_until(b'\n', &mut buffer)?;
        if bytes_read == 0 {
            break;
        }

        if let Some(record) = parse_line(&buffer) {
            process_record(&record);
        } else {
            eprintln!("Skipping malformed line");
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let file = File::open("input.csv")?;
    let reader = BufReader::with_capacity(8 * 1024 * 1024, file);

    parse_stream(reader)
}
