```rust
use std::io::{self, Read};

const BUF_SIZE: usize = 64 * 1024;

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut handle = stdin.lock();

    let mut buf = [0u8; BUF_SIZE];
