pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buffer: String,
}

impl<R: Read> StreamingParser<R> {
    /// Create a new parser from any Read source.
    pub fn new(reader: R) -> Self {
        Self {
            reader: BufReader::with_capacity(8 * 1024 * 1024, reader), // 8 MB buffer
            buffer: String::new(),
        }
    }

    /// Process each line with the provided callback.
    /// Returns the first I/O error encountered, if any.
    pub fn for_each_line<F>(&mut self, mut f: F) -> io::Result<()>
    where
        F: FnMut(&str),
    {
        loop {
            self.buffer.clear();
            let bytes_read = self.reader.read_line(&mut self.buffer)?;

            if bytes_read == 0 {
