```rust
use std::io::{self, Read, BufRead, BufReader};

/// A streaming parser for newline-delimited, comma-separated records.
/// 
/// Example input:
///   alpha,beta,gamma\n
///   one,two,three\n
pub struct StreamingParser<R: Read> {
    reader: BufReader<R>,
    buffer: Vec<u8>,
    leftover: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct Record {
    pub fields: Vec<String>,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader: BufReader::with_capacity(64 * 1024, reader),
            buffer: vec![0; 64 * 1024],
            leftover: Vec::with_capacity(1024),
        }
    }

    /// Parse the next record if available.
    /// Returns:
    /// - Ok(Some(record)) for a parsed record
    /// - Ok(None) at EOF
    /// - Err(...) on I/O or parse error
    pub fn next_record(&mut self) -> io::Result<Option<Record>> {
        loop {
            // Read a chunk
            let n = self.reader.read(&mut self.buffer)?;
            if n == 0 {
                if self.leftover.is_empty() {
                    return Ok(None);
                } else {
                    // Parse final partial line at EOF
                    let line = std::mem::take(&mut self.leftover);
                    return Ok(Some(self.parse_line(&line)));
                }
            }

            self.leftover.extend_from_slice(&self.buffer[..n]);

            // Look for newline-delimited records
            if let Some(pos) = self.leftover.iter().position(|&b| b == b'\n') {
                let mut line = self.leftover.split_off(pos + 1);
                std::mem::swap(&mut line, &mut self.leftover);
                let line = &line[..pos]; // strip trailing '\n'
                return Ok(Some(self.parse_line(line)));
            }
        }
    }

    fn parse_line(&self, line: &[u8]) -> Record {
        let fields = line
            .split(|&b| b == b',')
            .map(|field| String::from_utf8_lossy(field).into_owned())
            .collect();

        Record { fields }
    }
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut parser = StreamingParser::new(stdin.lock());

    while let Some(record) = parser.next_record()? {
        println!("{:?}", record);
    }

    Ok(())
}
```

