#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define BUFFER_SIZE (1 << 20)   // 1 MiB chunk size; tune as needed

typedef struct {
    char *buf;
    size_t len;
    size_t cap;
} Buffer;

static void buffer_init(Buffer *b, size_t cap) {
    b->buf = (char *)malloc(cap);
    if (!b->buf) {
        fprintf(stderr, "Failed to allocate buffer\n");
        exit(EXIT_FAILURE);
    }
    b->len = 0;
    b->cap = cap;
}

static void buffer_free(Buffer *b) {
    free(b->buf);
    b->buf = NULL;
    b->len = 0;
    b->cap = 0;
}

/*
 * Process a single field without allocating.
 * Replace this with your actual field handling logic.
 */
static void handle_field(const char *start, size_t len) {
    // Example: just write to stderr for demonstration (avoid in hot path in real code)
    // fwrite(start, 1, len, stderr);
    // fputc('\n', stderr);

    (void)start;
    (void)len;
}

/*
 * Process a complete line (record) in-place.
 * Fields are comma-separated.
 */
static void process_line(char *line, size_t line_len) {
    size_t field_start = 0;

    for (size_t i = 0; i <= line_len; i++) {
        if (i == line_len || line[i] == ',') {
            handle_field(line + field_start, i - field_start);
            field_start = i + 1;
        }
    }
}

/*
 * Parse streaming input from fp.
 * Handles records split across chunk boundaries.
 */
static void parse_stream(FILE *fp) {
    Buffer b;
    buffer_init(&b, BUFFER_SIZE);

    size_t start = 0; // start index of unprocessed data in buffer

    for (;;) {
        // If buffer is full of unprocessed data, grow or compact.
        if (start > 0) {
            size_t remaining = b.len - start;
            memmove(b.buf, b.buf + start, remaining);
            b.len = remaining;
            start = 0;
        }

        if (b.len == b.cap) {
            // In this simple version, the buffer should not fill fully unless a record is huge.
            // Grow it to handle very long lines.
            size_t new_cap = b.cap * 2;
            char *new_buf = (char *)realloc(b.buf, new_cap);
            if (!new_buf) {
                fprintf(stderr, "Failed to grow buffer\n");
                buffer_free(&b);
                exit(EXIT_FAILURE);
            }
            b.buf = new_buf;
            b.cap = new_cap;
        }

        size_t n = fread(b.buf + b.len, 1, b.cap - b.len, fp);
        if (n == 0 && ferror(fp)) {
            perror("fread");
            buffer_free(&b);
            exit(EXIT_FAILURE);
        }
        b.len += n;

        size_t line_start = 0;
        for (size_t i = 0; i < b.len; i++) {
            if (b.buf[i] == '\n') {
                size_t line_len = i - line_start;

                // Handle optional '\r' before '\n'
                if (line_len > 0 && b.buf[i - 1] == '\r') {
                    line_len--;
                }

                process_line(b.buf + line_start, line_len);
                line_start = i + 1;
            }
        }

        // Preserve partial line at end of buffer
        if (line_start > 0) {
            size_t remaining = b.len - line_start;
            memmove(b.buf, b.buf + line_start, remaining);
            b.len = remaining;
        }

        if (n == 0) {
            break; // EOF
        }
    }

    // Process final unterminated line, if any
    if (b.len > 0) {
        process_line(b.buf, b.len);
    }

    buffer_free(&b);
}

int main(int argc, char **argv) {
    FILE *fp = stdin;

    if (argc > 1) {
        fp = fopen(argv[1], "rb");
        if (!fp) {
            perror("fopen");
            return EXIT_FAILURE;
        }
    }

    parse_stream(fp);

    if (argc > 1) {
        fclose(fp);
    }

    return EXIT_SUCCESS;
}
```

