/// A parsed record. Keep this small and avoid owned Strings if possible.
#[derive(Debug)]
struct Record<'a> {
    timestamp: &'a str,
    level: &'a str,
    message: &'a str,
}

/// Streaming parser state.
struct Parser<R: BufRead> {
    reader: R,
    line_buf: String,
}

impl<R: BufRead> Parser<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            line_buf: String::with_capacity(8 * 1024),
        }
    }

    /// Parse the next record from the stream.
    /// Returns:
    /// - Ok(Some(record)) for a parsed line
    /// - Ok(None) on EOF
    /// - Err(_) on I/O or parse error
    fn next_record<'a>(&'a mut self) -> io::Result<Option<Record<'a>>> {
        self.line_buf.clear();

        let bytes_read = self.reader.read_line(&mut self.line_buf)?;
        if bytes_read == 0 {
            return Ok(None); // EOF
        }

        // Trim trailing newline(s) without allocating.
        let line = self.line_buf.trim_end_matches(['\n', '\r']);

        // Example format:
        // timestamp|level|message
        // e.g. 2026-01-01T12:00:00Z|INFO|Service started
        let mut parts = line.splitn(3, '|');

        let timestamp = parts.next().unwrap_or("");
        let level = parts.next().unwrap_or("");
        let message = parts.next().unwrap_or("");

        if timestamp.is_empty() || level.is_empty() || message.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "invalid record: expected 3 pipe-delimited fields",
            ));
        }

        Ok(Some(Record {
            timestamp,
            level,
            message,
        }))
    }
}

/// Process a single record.
/// Replace this with your downstream logic.
fn handle_record(record: &Record<'_>) {
    // Example: fast path processing
    println!(
        "ts={} level={} msg={}",
        record.timestamp, record.level, record.message
    );
}

/// Parse a file in a streaming manner.
fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(64 * 1024, file);
    let mut parser = Parser::new(reader);

    while let Some(record) = parser.next_record()? {
        handle_record(&record);
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");

    parse_file(path)
}
```

