## More robust high-throughput version: byte-oriented parser

If you want even less overhead, switch from `String` to raw bytes and parse with `&[u8]`:

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

#[derive(Debug)]
struct Record<'a> {
    timestamp: &'a [u8],
    level: &'a [u8],
    message: &'a [u8],
}

struct Parser<R: BufRead> {
    reader: R,
    buf: Vec<u8>,
}

impl<R: BufRead> Parser<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buf: Vec::with_capacity(8 * 1024),
        }
    }

    fn next_record<'a>(&'a mut self) -> io::Result<Option<Record<'a>>> {
        self.buf.clear();

        let bytes_read = self.reader.read_until(b'\n', &mut self.buf)?;
        if bytes_read == 0 {
            return Ok(None);
        }

        while self.buf.last() == Some(&b'\n') || self.buf.last() == Some(&b'\r') {
            self.buf.pop();
        }

        let mut first = None;
        let mut second = None;

        for (i, &b) in self.buf.iter().enumerate() {
            if b == b'|' {
                if first.is_none() {
                    first = Some(i);
                } else {
                    second = Some(i);
                    break;
                }
            }
        }

        let (i1, i2) = match (first, second) {
            (Some(a), Some(b)) => (a, b),
            _ => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "invalid record: expected 3 pipe-delimited fields",
                ));
            }
        };

        Ok(Some(Record {
            timestamp: &self.buf[..i1],
            level: &self.buf[i1 + 1..i2],
            message: &self.buf[i2 + 1..],
        }))
    }
}

fn handle_record(record: &Record<'_>) {
    // Avoid converting to String unless needed
    println!(
        "ts={} level={} msg={}",
        String::from_utf8_lossy(record.timestamp),
        String::from_utf8_lossy(record.level),
        String::from_utf8_lossy(record.message),
    );
}

fn parse_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
    let reader = BufReader::with_capacity(64 * 1024, file);
    let mut parser = Parser::new(reader);

    while let Some(record) = parser.next_record()? {
        handle_record(&record);
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let path = std::env::args()
        .nth(1)
        .expect("usage: parser <input-file>");

    parse_file(path)
}
