use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut reader = stdin.lock();

    let mut buf = Vec::with_capacity(8 * 1024);
    let mut line_count: u64 = 0;
    let mut byte_count: u64 = 0;

    loop {
        buf.clear();
        let bytes_read = reader.read_until(b'\n', &mut buf).unwrap();

        if bytes_read == 0 {
            break; // EOF
        }

        line_count += 1;
        byte_count += bytes_read as u64;

        // Process the line in-place without copying.
        // Trim trailing newline if needed:
        let line = if buf.ends_with(&[b'\n']) {
            &buf[..buf.len() - 1]
        } else {
            &buf[..]
        };

        // Example: search for a delimiter without allocating
        if let Some(pos) = line.iter().position(|&b| b == b',') {
            let first_field = &line[..pos];
            let second_field = &line[pos + 1..];

            // Do something with fields
            let _ = (first_field, second_field);
        }
    }

    println!("lines={}", line_count);
    println!("bytes={}", byte_count);
}
```

