use std::io::{self, Read, BufReader};

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut reader = BufReader::new(stdin.lock());

    // Fixed-size buffer: low memory overhead
    let mut buffer = [0u8; 64 * 1024];

    let mut total_bytes: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut leftover: Vec<u8> = Vec::new();

    loop {
        let n = reader.read(&mut buffer)?;
        if n == 0 {
            break;
        }

        total_bytes += n as u64;

        // Combine previous partial line with new chunk only if needed
        let mut start = 0;
        for i in 0..n {
            if buffer[i] == b'\n' {
                total_lines += 1;
                start = i + 1;
            }
        }

        // Handle the case where the chunk ends without a newline
        if start < n {
            leftover.extend_from_slice(&buffer[start..n]);
        }

        // If we saw complete lines, clear leftover because this demo
        // only counts lines and doesn't need to preserve partial content.
        if total_lines > 0 && leftover.len() > 1024 {
            leftover.clear();
        }
    }

    // Count final partial line if any
    if !leftover.is_empty() {
        total_lines += 1;
    }

    println!("bytes={}", total_bytes);
    println!("lines={}", total_lines);

    Ok(())
}
