Below is a small **Rust** implementation of a memory-conscious log rotation daemon skeleton. It aims to keep allocations low by:

- avoiding loading whole files into memory
- using buffered streaming copies
- renaming files instead of reading them into RAM
- limiting the number of rotated files
- avoiding background caches or large data structures

It rotates a log when the active file exceeds a size threshold.

```rust
use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, SystemTime};

const DEFAULT_MAX_BYTES: u64 = 10 * 1024 * 1024; // 10 MiB
const DEFAULT_POLL_MS: u64 = 1000;
const DEFAULT_MAX_ROTATIONS: usize = 5;
const COPY_BUF_SIZE: usize = 8 * 1024;

#[derive(Debug, Clone)]
struct Config {
    log_path: PathBuf,
    max_bytes: u64,
    poll_ms: u64,
    max_rotations: usize,
}

fn parse_args() -> io::Result<Config> {
    let mut args = env::args().skip(1);

    let log_path = args
        .next()
        .map(PathBuf::from)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "missing log path"))?;

    let max_bytes = args
        .next()
        .map(|s| s.parse::<u64>())
        .transpose()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid max_bytes"))?
        .unwrap_or(DEFAULT_MAX_BYTES);

    let poll_ms = args
        .next()
        .map(|s| s.parse::<u64>())
        .transpose()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid poll_ms"))?
        .unwrap_or(DEFAULT_POLL_MS);

    let max_rotations = args
        .next()
        .map(|s| s.parse::<usize>())
        .transpose()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid max_rotations"))?
        .unwrap_or(DEFAULT_MAX_ROTATIONS);

    Ok(Config {
        log_path,
        max_bytes,
        poll_ms,
        max_rotations,
    })
}

fn file_size(path: &Path) -> io::Result<u64> {
    Ok(fs::metadata(path)?.len())
}

fn rotated_path(base: &Path, idx: usize) -> PathBuf {
    let mut s = base.as_os_str().to_owned();
    s.push(format!(".{}", idx));
    PathBuf::from(s)
}

fn rotate_logs(base: &Path, max_rotations: usize) -> io::Result<()> {
    // Remove the oldest rotation if it exists.
    let oldest = rotated_path(base, max_rotations);
    if oldest.exists() {
        let _ = fs::remove_file(&oldest);
    }

    // Shift older files upward.
    for i in (1..=max_rotations.saturating_sub(1)).rev() {
        let src = rotated_path(base, i);
        let dst = rotated_path(base, i + 1);
        if src.exists() {
            let _ = fs::rename(&src, &dst);
        }
    }

    // Move current active log to .1 if it exists.
    if base.exists() {
        let first = rotated_path(base, 1);
        let _ = fs::rename(base, first);
    }

    Ok(())
}

fn reopen_log(path: &Path) -> io::Result<File> {
    OpenOptions::new()
        .create(true)
        .write(true)
        .append(true)
        .open(path)
}

fn main() -> io::Result<()> {
    let cfg = parse_args()?;

    // Ensure the log file exists.
    let mut log_file = reopen_log(&cfg.log_path)?;

    loop {
        let size = file_size(&cfg.log_path).unwrap_or(0);

        if size >= cfg.max_bytes {
            // Close current handle before renaming on some platforms.
            drop(log_file);

            rotate_logs(&cfg.log_path, cfg.max_rotations)?;

            // Recreate the active log file.
            log_file = reopen_log(&cfg.log_path)?;
        }

        thread::sleep(Duration::from_millis(cfg.poll_ms));
    }
}
```

