Below is a small, low-memory **Rust** daemon that watches one log file and rotates it when it exceeds a size limit. It avoids large in-memory buffers and uses streaming I/O with a fixed-size buffer.

### What it does
- Polls a target log file periodically
- If the file exceeds a configured size, it:
  1. Renames existing rotated files upward (`app.log.3` → `app.log.4`, etc.)
  2. Renames `app.log` to `app.log.1`
  3. Creates a new empty `app.log`
- Uses a small fixed buffer for copying, so memory usage stays low

---

## Rust implementation

```rust
use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

const DEFAULT_POLL_SECS: u64 = 5;
const DEFAULT_MAX_SIZE: u64 = 10 * 1024 * 1024; // 10 MiB
const DEFAULT_ROTATIONS: usize = 5;
const COPY_BUF_SIZE: usize = 8 * 1024; // 8 KiB

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!(
            "Usage: {} <logfile> [max_size_bytes] [rotations] [poll_secs]",
            args.get(0).map(String::as_str).unwrap_or("logd")
        );
        std::process::exit(1);
    }

    let log_path = PathBuf::from(&args[1]);
    let max_size = args.get(2)
        .and_then(|s| s.parse::<u64>().ok())
        .unwrap_or(DEFAULT_MAX_SIZE);

    let rotations = args.get(3)
        .and_then(|s| s.parse::<usize>().ok())
        .unwrap_or(DEFAULT_ROTATIONS);

    let poll_secs = args.get(4)
        .and_then(|s| s.parse::<u64>().ok())
        .unwrap_or(DEFAULT_POLL_SECS);

    eprintln!(
        "Watching {} (max_size={} bytes, rotations={}, poll={}s)",
        log_path.display(),
        max_size,
        rotations,
        poll_secs
    );

    loop {
        if let Ok(meta) = fs::metadata(&log_path) {
            if meta.len() >= max_size {
                if let Err(e) = rotate(&log_path, rotations) {
                    eprintln!("rotation failed: {}", e);
                } else {
                    eprintln!("rotated {}", log_path.display());
                }
            }
        }

        thread::sleep(Duration::from_secs(poll_secs));
    }
}

fn rotate(base: &Path, rotations: usize) -> io::Result<()> {
    if rotations == 0 {
        return Ok(());
    }

    // Shift old logs upward: .4 -> .5, ... .1 -> .2
    for i in (1..=rotations).rev() {
        let src = rotated_name(base, i);
        let dst = rotated_name(base, i + 1);

        if src.exists() {
            // Best effort remove destination first.
            let _ = fs::remove_file(&dst);
            fs::rename(&src, &dst)?;
        }
    }

    // Move current log to .1
    let first_rotated = rotated_name(base, 1);
    if first_rotated.exists() {
        let _ = fs::remove_file(&first_rotated);
    }
    fs::rename(base, &first_rotated)?;

    // Create a fresh empty log file.
    let _ = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(base)?;

    Ok(())
}

fn rotated_name(base: &Path, idx: usize) -> PathBuf {
    let mut s = base.as_os_str().to_owned();
    s.push(format!(".{}", idx));
    PathBuf::from(s)
}
