Below is a small, memory-conscious log rotation daemon in <language>C</language>. It avoids large dynamic allocations, uses fixed-size buffers, and polls a single log file on a timer.

It:
- watches one log file
- rotates when size exceeds a threshold
- keeps a limited number of rotated copies
- uses `rename()` and `truncate()`-style behavior via reopen/replace
- stays simple and low-memory

## C implementation

```c
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int safe_rename(const char *oldpath, const char *newpath) {
    if (rename(oldpath, newpath) != 0) {
        return -1;
    }
    return 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int rotate_logs(const char *logfile, int max_rotations) {
    char src[PATH_MAX];
    char dst[PATH_MAX];

    // Delete oldest
    snprintf(src, sizeof(src), "%s.%d", logfile, max_rotations);
    unlink(src);

    // Shift: logfile.(n-1) -> logfile.n
    for (int i = max_rotations - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", logfile, i);
        if (!file_exists(src)) continue;

        snprintf(dst, sizeof(dst), "%s.%d", logfile, i + 1);
        if (rename(src, dst) != 0) {
            perror("rename");
            return -1;
        }
    }

    // Current logfile -> logfile.1
    snprintf(dst, sizeof(dst), "%s.1", logfile);
    if (file_exists(logfile)) {
        if (rename(logfile, dst) != 0) {
            perror("rename current");
            return -1;
        }
    }

    // Recreate empty logfile with restrictive perms
    int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0640);
    if (fd < 0) {
        perror("recreate logfile");
        return -1;
    }
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s <logfile> <max_bytes> <max_rotations> <poll_ms>\n"
            "Example: %s /var/log/app.log 10485760 5 1000\n",
            prog, prog);
}

int main(int argc, char **argv) {
    if (argc != 5) {
        usage(argv[0]);
        return 2;
    }

    const char *logfile = argv[1];
    unsigned long long max_bytes = strtoull(argv[2], NULL, 10);
    int max_rotations = atoi(argv[3]);
    int poll_ms = atoi(argv[4]);

    if (max_bytes == 0 || max_rotations < 1 || poll_ms < 1) {
        fprintf(stderr, "Invalid arguments.\n");
        return 2;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Ensure logfile exists
    int fd = open(logfile, O_WRONLY | O_CREAT, 0640);
    if (fd < 0) {
        perror("open logfile");
        return 1;
    }
    close(fd);

    while (!g_stop) {
        off_t sz = file_size(logfile);
        if (sz < 0) {
            perror("stat logfile");
        } else if ((unsigned long long)sz >= max_bytes) {
            if (rotate_logs(logfile, max_rotations) != 0) {
                fprintf(stderr, "Rotation failed.\n");
            }
        }

        usleep((useconds_t)poll_ms * 1000);
    }

    return 0;
}
