Below is a **small, low-allocation C implementation** of a log rotation daemon suitable for tight memory constraints. It avoids heap allocation in the main loop, uses fixed-size buffers, and performs simple size-based rotation.

It is intentionally minimal and should be adapted for your environment, error handling, and security requirements.

```c
/*
 * logrotate_daemon.c
 *
 * Minimal memory-constrained log rotation daemon.
 *
 * Features:
 * - Monitors a single log file
 * - Rotates when file size exceeds a threshold
 * - Uses no dynamic allocation in the main loop
 * - Designed for low memory usage
 *
 * Build:
 *   cc -O2 -Wall -Wextra -o logrotate_daemon logrotate_daemon.c
 *
 * Example:
 *   ./logrotate_daemon /var/log/app.log 10485760 5
 *
 * Arguments:
 *   argv[1] = logfile path
 *   argv[2] = max bytes before rotation
 *   argv[3] = number of rotated copies to keep
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void log_err(const char *msg) {
    /* Minimal stderr logging */
    write(STDERR_FILENO, msg, strlen(msg));
    write(STDERR_FILENO, "\n", 1);
}

static int copy_file(const char *src, const char *dst) {
    int in_fd = -1, out_fd = -1;
    int rc = -1;
    char buf[8192];

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) {
        return -1;
    }

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        goto cleanup;
    }

    for (;;) {
        ssize_t r = read(in_fd, buf, sizeof(buf));
        if (r == 0) {
            rc = 0;
            break;
        }
        if (r < 0) {
            if (errno == EINTR) continue;
            goto cleanup;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                goto cleanup;
            }
            off += w;
        }
    }

cleanup:
    if (in_fd >= 0) close(in_fd);
    if (out_fd >= 0) close(out_fd);
    return rc;
}

static int rotate_logs(const char *logfile, unsigned keep) {
    char src[PATH_MAX];
    char dst[PATH_MAX];

    if (keep == 0) {
        /* Truncate current logfile */
        int fd = open(logfile, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    /* Delete oldest */
    if (snprintf(dst, sizeof(dst), "%s.%u", logfile, keep) >= (int)sizeof(dst)) {
        errno = ENAMETOOLONG;
        return -1;
    }
    unlink(dst);

    /* Shift rotations: logfile.(keep-1) -> logfile.keep, ... */
    for (unsigned i = keep; i > 1; --i) {
        if (snprintf(src, sizeof(src), "%s.%u", logfile, i - 1) >= (int)sizeof(src) ||
            snprintf(dst, sizeof(dst), "%s.%u", logfile, i) >= (int)sizeof(dst)) {
            errno = ENAMETOOLONG;
            return -1;
        }
        rename(src, dst);
    }

    /* Rotate current logfile -> logfile.1 */
    if (snprintf(dst, sizeof(dst), "%s.1", logfile) >= (int)sizeof(dst)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    /* Use rename if possible; if cross-device or other issues, copy/truncate fallback */
    if (rename(logfile, dst) == 0) {
        return 0;
    }

    if (errno == EXDEV) {
        if (copy_file(logfile, dst) != 0) {
            return -1;
        }
        int fd = open(logfile, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        close(fd);
        return 0;
    }

    return -1;
}

static int64_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return (int64_t)st.st_size;
}

static void usage(const char *argv0) {
    dprintf(STDERR_FILENO,
            "Usage: %s <logfile> <max_bytes> <keep>\n"
            "  logfile   Path to the log file to rotate\n"
            "  max_bytes  Rotate when file size >= this value\n"
            "  keep      Number of rotated files to keep\n",
            argv0);
}

int main(int argc, char **argv) {
    const char *logfile;
    uint64_t max_bytes;
    unsigned keep;
    struct sigaction sa;

    if (argc != 4) {
        usage(argv[0]);
        return 2;
    }

    logfile = argv[1];
    max_bytes = strtoull(argv[2], NULL, 10);
    keep = (unsigned)strtoul(argv[3], NULL, 10);

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (;;) {
        if (g_stop) {
            break;
        }

        int64_t sz = file_size(logfile);
        if (sz < 0) {
            /* File may not exist yet; wait and retry */
            sleep(1);
            continue;
        }

        if ((uint64_t)sz >= max_bytes) {
            if (rotate_logs(logfile, keep) != 0) {
                log_err("rotation failed");
            }
        }

        sleep(1);
    }

    return 0;
}
```

