Below is a small **C** implementation of a log rotation daemon designed to stay memory-light and avoid dynamic allocation in the hot path. It:

- watches one log file by polling
- rotates when the file exceeds a size threshold
- keeps a fixed number of rotated backups
- uses only stack buffers and small fixed-size arrays
- avoids heap allocation

This is a practical starting point for a memory-constrained environment.

```c
// logrotate_daemon.c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#define MAX_PATH_LEN 512
#define MAX_BACKUPS   9

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int path_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int filesize(const char *path, off_t *out_size) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *out_size = st.st_size;
    return 0;
}

static int rename_if_exists(const char *src, const char *dst) {
    if (!path_exists(src)) return 0;
    if (rename(src, dst) != 0) return -1;
    return 0;
}

static int rotate_logs(const char *log_path, int backups) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    if (backups < 1) backups = 1;
    if (backups > MAX_BACKUPS) backups = MAX_BACKUPS;

    // Delete oldest backup: log.N -> removed by overwriting chain
    // Shift: log.(N-1) -> log.N, ... log.1 -> log.2
    for (int i = backups - 1; i >= 1; --i) {
        if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", log_path, i) != 0)
            return -1;
        if (safe_snprintf(new_path, sizeof(new_path), "%s.%d", log_path, i + 1) != 0)
            return -1;
        if (rename_if_exists(old_path, new_path) != 0) {
            // If a file is missing, continue; otherwise fail.
            if (errno != ENOENT) return -1;
        }
    }

    // Current log -> log.1
    if (safe_snprintf(new_path, sizeof(new_path), "%s.1", log_path) != 0)
        return -1;
    if (rename_if_exists(log_path, new_path) != 0) {
        if (errno != ENOENT) return -1;
    }

    // Recreate the active log file so writers can continue.
    int fd = open(log_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    umask(022);
    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <logfile> <max_size_bytes> <backup_count> <poll_ms> [--daemon]\n"
        "Example: %s /var/log/myapp.log 10485760 5 1000 --daemon\n",
        prog, prog);
}

int main(int argc, char **argv) {
    if (argc < 5) {
        usage(argv[0]);
        return 2;
    }

    const char *log_path = argv[1];
    long long max_size = atoll(argv[2]);
    int backups = atoi(argv[3]);
    int poll_ms = atoi(argv[4]);
    bool run_as_daemon = false;

    if (argc >= 6 && strcmp(argv[5], "--daemon") == 0) {
        run_as_daemon = true;
    }

    if (strlen(log_path) >= MAX_PATH_LEN) {
        fprintf(stderr, "log path too long\n");
        return 2;
    }
    if (max_size <= 0 || backups <= 0 || poll_ms <= 0) {
        fprintf(stderr, "invalid arguments\n");
        return 2;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (run_as_daemon) {
        if (daemonize() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    // Ensure file exists at startup.
    if (!path_exists(log_path)) {
        int fd = open(log_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
        if (fd < 0) {
            perror("open log file");
            return 1;
        }
        close(fd);
    }

    while (g_running) {
        off_t sz = 0;
        if (filesize(log_path, &sz) == 0 && sz >= (off_t)max_size) {
            if (rotate_logs(log_path, backups) != 0) {
                perror("rotate_logs");
            }
        }

        struct timespec ts;
        ts.tv_sec = poll_ms / 1000;
        ts.tv_nsec = (long)(poll_ms % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    return 0;
}
