#include <signal.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define DEFAULT_INTERVAL_SEC 5
#define DEFAULT_MAX_RETAIN 5
#define DEFAULT_MAX_SIZE_BYTES (10 * 1024 * 1024)

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int rename_with_overwrite(const char *from, const char *to) {
    if (file_exists(to)) {
        if (unlink(to) != 0) return -1;
    }
    return rename(from, to);
}

static int rotate_logs(const char *log_path, int max_retain) {
    char src[512];
    char dst[512];

    for (int i = max_retain - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", log_path, i);
        snprintf(dst, sizeof(dst), "%s.%d", log_path, i + 1);

        if (file_exists(src)) {
            if (rename_with_overwrite(src, dst) != 0) {
                perror("rename rotated file");
                return -1;
            }
        }
    }

    snprintf(dst, sizeof(dst), "%s.1", log_path);
    if (file_exists(log_path)) {
        if (rename_with_overwrite(log_path, dst) != 0) {
            perror("rotate current log");
            return -1;
        }
    }

    return 0;
}

static int ensure_log_file(const char *log_path) {
    int fd = open(log_path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) {
        perror("open log file");
        return -1;
    }
    close(fd);
    return 0;
}

static void daemonize_if_requested(int foreground) {
    if (foreground) return;

    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);

    pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(0);
    chdir("/");

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-f] [-i interval_sec] [-s max_size_bytes] [-n max_retain] log_file\n"
        "  -f                Run in foreground\n"
        "  -i interval_sec    Check interval (default %d)\n"
        "  -s max_size_bytes  Rotate when log exceeds this size (default %d)\n"
        "  -n max_retain      Number of rotated logs to keep (default %d)\n",
        prog, DEFAULT_INTERVAL_SEC, DEFAULT_MAX_SIZE_BYTES, DEFAULT_MAX_RETAIN);
}

int main(int argc, char *argv[]) {
    int foreground = 0;
    int interval_sec = DEFAULT_INTERVAL_SEC;
    int max_retain = DEFAULT_MAX_RETAIN;
    off_t max_size_bytes = DEFAULT_MAX_SIZE_BYTES;

    int opt;
    while ((opt = getopt(argc, argv, "fi:s:n:")) != -1) {
        switch (opt) {
            case 'f':
                foreground = 1;
                break;
            case 'i':
                interval_sec = atoi(optarg);
                if (interval_sec <= 0) interval_sec = DEFAULT_INTERVAL_SEC;
                break;
            case 's':
                max_size_bytes = atoll(optarg);
                if (max_size_bytes <= 0) max_size_bytes = DEFAULT_MAX_SIZE_BYTES;
                break;
            case 'n':
                max_retain = atoi(optarg);
                if (max_retain < 1) max_retain = DEFAULT_MAX_RETAIN;
                break;
            default:
                usage(argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_path = argv[optind];

    if (ensure_log_file(log_path) != 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    daemonize_if_requested(foreground);

    while (g_running) {
        off_t sz = file_size(log_path);
        if (sz < 0) {
            perror("stat log file");
            sleep(interval_sec);
            continue;
        }

        if (sz >= max_size_bytes) {
            if (rotate_logs(log_path, max_retain) != 0) {
                fprintf(stderr, "log rotation failed\n");
            } else {
                if (ensure_log_file(log_path) != 0) {
                    fprintf(stderr, "failed to recreate log file\n");
                }
            }
        }

        sleep(interval_sec);
    }

    return EXIT_SUCCESS;
}
