## C implementation

```c
/*
 * logrotate_daemon.c
 *
 * Minimal memory-constrained log rotation daemon.
 * Build: cc -O2 -Wall -Wextra -std=c11 -o logrotate_daemon logrotate_daemon.c
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#define MAX_LINE        512
#define MAX_PATH        512
#define BUF_SIZE        4096

typedef enum {
    MODE_RENAME = 0,
    MODE_TRUNCATE = 1
} rotate_mode_t;

typedef struct {
    char log_dir[MAX_PATH];
    char log_file[128];
    size_t max_size;
    int max_files;
    int poll_interval;
    rotate_mode_t mode;
} config_t;

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void trim(char *s) {
    size_t n = strlen(s);
    while (n > 0 && (s[n - 1] == '\n' || s[n - 1] == '\r' || s[n - 1] == ' ' || s[n - 1] == '\t')) {
        s[--n] = '\0';
    }
    size_t i = 0;
    while (s[i] == ' ' || s[i] == '\t') i++;
    if (i > 0) memmove(s, s + i, n - i + 1);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int r = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (r < 0 || (size_t)r >= dstsz) return -1;
    return 0;
}

static int load_config(const char *path, config_t *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    strncpy(cfg->log_dir, "/var/log", sizeof(cfg->log_dir) - 1);
    strncpy(cfg->log_file, "app.log", sizeof(cfg->log_file) - 1);
    cfg->max_size = 10 * 1024 * 1024;
    cfg->max_files = 5;
    cfg->poll_interval = 5;
    cfg->mode = MODE_RENAME;

    FILE *f = fopen(path, "r");
    if (!f) return -1;

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), f)) {
        trim(line);
        if (line[0] == '\0' || line[0] == '#') continue;

        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = line;
        char *val = eq + 1;
        trim(key);
        trim(val);

        if (strcmp(key, "log_dir") == 0) {
            strncpy(cfg->log_dir, val, sizeof(cfg->log_dir) - 1);
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(cfg->log_file, val, sizeof(cfg->log_file) - 1);
        } else if (strcmp(key, "max_size") == 0) {
            cfg->max_size = (size_t)strtoull(val, NULL, 10);
        } else if (strcmp(key, "max_files") == 0) {
            cfg->max_files = atoi(val);
            if (cfg->max_files < 1) cfg->max_files = 1;
        } else if (strcmp(key, "poll_interval") == 0) {
            cfg->poll_interval = atoi(val);
            if (cfg->poll_interval < 1) cfg->poll_interval = 1;
        } else if (strcmp(key, "mode") == 0) {
            if (strcmp(val, "truncate") == 0) cfg->mode = MODE_TRUNCATE;
            else cfg->mode = MODE_RENAME;
        }
    }

    fclose(f);
    return 0;
}

static int build_log_path(char *out, size_t outsz, const config_t *cfg) {
    return safe_snprintf(out, outsz, "%s/%s", cfg->log_dir, cfg->log_file);
}

static int build_rotated_path(char *out, size_t outsz, const config_t *cfg, int index) {
    return safe_snprintf(out, outsz, "%s/%s.%d", cfg->log_dir, cfg->log_file, index);
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int copy_file(const char *src, const char *dst) {
    int in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    int out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    char buf[BUF_SIZE];
    ssize_t n;
    while ((n = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < n) {
            ssize_t w = write(out_fd, buf + off, (size_t)(n - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    close(in_fd);
    close(out_fd);
    return (n < 0) ? -1 : 0;
}

static int rotate_logs(const config_t *cfg) {
    char base[MAX_PATH];
    if (build_log_path(base, sizeof(base), cfg) != 0) return -1;

    // Remove oldest
    char oldpath[MAX_PATH];
    if (build_rotated_path(oldpath, sizeof(oldpath), cfg, cfg->max_files) != 0) return -1;
    unlink(oldpath);

    // Shift rotated files up
    for (int i = cfg->max_files - 1; i >= 1; --i) {
        char src[MAX_PATH], dst[MAX_PATH];
        if (build_rotated_path(src, sizeof(src), cfg, i) != 0) return -1;
        if (build_rotated_path(dst, sizeof(dst), cfg, i + 1) != 0) return -1;
        rename(src, dst);
    }

    // Rotate base
    char first[MAX_PATH];
    if (build_rotated_path(first, sizeof(first), cfg, 1) != 0) return -1;

    if (cfg->mode == MODE_RENAME) {
        if (rename(base, first) != 0) return -1;

        // Recreate empty log file
        int fd = open(base, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0) return -1;
        close(fd);
    } else {
        // Truncate mode: keep base name and copy current content to .1,
        // then truncate original.
        if (copy_file(base, first) != 0) return -1;
        int fd = open(base, O_WRONLY | O_TRUNC);
        if (fd < 0) return -1;
        close(fd);
    }

    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    umask(022);
    if (chdir("/") != 0) return -1;

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

int main(int argc, char **argv) {
    const char *config_path = "/etc/logrotate_daemon.conf";
    bool no_daemon = false;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--config") == 0 && i + 1 < argc) {
            config_path = argv[++i];
        } else if (strcmp(argv[i], "--foreground") == 0) {
            no_daemon = true;
        }
    }

    config_t cfg;
    if (load_config(config_path, &cfg) != 0) {
        fprintf(stderr, "Failed to load config: %s\n", config_path);
        return 1;
    }

    if (!no_daemon && daemonize() != 0) {
        perror("daemonize");
        return 1;
    }

    openlog("logrotate_daemon", LOG_PID | LOG_NDELAY, LOG_DAEMON);
    syslog(LOG_INFO, "started");

    signal(SIGTERM, on_signal);
    signal(SIGINT, on_signal);

    char base[MAX_PATH];
    if (build_log_path(base, sizeof(base), &cfg) != 0) {
        syslog(LOG_ERR, "path too long");
        return 1;
    }

    while (g_running) {
        off_t sz = file_size(base);
        if (sz >= 0 && (size_t)sz > cfg.max_size) {
            if (rotate_logs(&cfg) != 0) {
                syslog(LOG_ERR, "rotation failed: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "rotated log: %s", base);
            }
        }

        for (int i = 0; i < cfg.poll_interval && g_running; ++i) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "stopped");
    closelog();
    return 0;
}
