## `src/main.rs`

```rust
use std::env;
use std::ffi::OsStr;
use std::fs::{self, File, OpenOptions};
use std::io;
use std::os::unix::fs::{MetadataExt, OpenOptionsExt};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 5 {
        eprintln!(
            "Usage: {} <log_dir> <max_size_bytes> <keep> <poll_seconds>",
            args.get(0).map(|s| s.as_str()).unwrap_or("logrotator")
        );
        std::process::exit(1);
    }

    let log_dir = PathBuf::from(&args[1]);
    let max_size: u64 = args[2].parse().expect("invalid max_size_bytes");
    let keep: usize = args[3].parse().expect("invalid keep");
    let poll_seconds: u64 = args[4].parse().expect("invalid poll_seconds");

    if !log_dir.is_dir() {
        eprintln!("log_dir is not a directory: {}", log_dir.display());
        std::process::exit(1);
    }

    loop {
        if let Err(err) = rotate_if_needed(&log_dir, max_size, keep) {
            eprintln!("rotation error: {err}");
        }
        thread::sleep(Duration::from_secs(poll_seconds));
    }
}

fn rotate_if_needed(log_dir: &Path, max_size: u64, keep: usize) -> io::Result<()> {
    for entry in fs::read_dir(log_dir)? {
        let entry = entry?;
        let path = entry.path();

        if !is_log_file(&path) {
            continue;
        }

        let meta = match fs::metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if meta.len() > max_size {
            rotate_file(&path, keep)?;
        }
    }

    Ok(())
}

fn is_log_file(path: &Path) -> bool {
    path.extension() == Some(OsStr::new("log"))
}

fn rotate_file(path: &Path, keep: usize) -> io::Result<()> {
    let parent = path.parent().unwrap_or(Path::new("."));
    let base_name = path.file_name().unwrap().to_string_lossy().into_owned();

    // Remove the oldest archive if it exists
    if keep > 0 {
        let oldest = parent.join(format!("{base_name}.{}", keep));
        let _ = fs::remove_file(&oldest);
    }

    // Shift archives upward: .(keep-1) -> .keep, ... , .1 -> .2
    for i in (1..keep).rev() {
        let src = parent.join(format!("{base_name}.{}", i));
        let dst = parent.join(format!("{base_name}.{}", i + 1));
        if src.exists() {
            let _ = fs::rename(&src, &dst);
        }
    }

    // Move current log to .1
    let rotated = parent.join(format!("{base_name}.1"));
    fs::rename(path, &rotated)?;

    // Recreate empty log file with sane permissions
    let _new_file = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .mode(0o644)
        .open(path)?;

    Ok(())
}
```

