## `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_LOG_PATH   512
#define MAX_BACKUPS     9
#define CHECK_INTERVAL  5   // seconds

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_sleep(unsigned seconds) {
    while (seconds > 0 && !g_stop) {
        seconds = sleep(seconds);
    }
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *base_path, int max_backups) {
    char src[MAX_LOG_PATH];
    char dst[MAX_LOG_PATH];

    // Remove oldest backup
    snprintf(dst, sizeof(dst), "%s.%d", base_path, max_backups);
    unlink(dst);

    // Shift backups upward: log.8 -> log.9, ...
    for (int i = max_backups - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", base_path, i);
        snprintf(dst, sizeof(dst), "%s.%d", base_path, i + 1);

        if (file_exists(src)) {
            if (rename(src, dst) != 0) {
                return -1;
            }
        }
    }

    // Move current log to log.1
    snprintf(dst, sizeof(dst), "%s.1", base_path);
    if (rename(base_path, dst) != 0) {
        return -1;
    }

    return 0;
}

static int reopen_log_if_needed(const char *path, int *fd_out) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;

    if (*fd_out >= 0) close(*fd_out);
    *fd_out = fd;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> [max_backups]\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    long long max_size_ll = atoll(argv[2]);
    int max_backups = (argc >= 4) ? atoi(argv[3]) : MAX_BACKUPS;

    if (strlen(log_path) >= MAX_LOG_PATH) {
        fprintf(stderr, "Error: log path too long\n");
        return 1;
    }

    if (max_size_ll <= 0) {
        fprintf(stderr, "Error: max_size_bytes must be > 0\n");
        return 1;
    }

    if (max_backups < 1 || max_backups > 99) {
        fprintf(stderr, "Error: max_backups must be between 1 and 99\n");
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    int fd = -1;
    if (reopen_log_if_needed(log_path, &fd) != 0) {
        perror("open");
        return 1;
    }

    fprintf(stderr, "Watching %s, max size %lld bytes, backups %d\n",
            log_path, max_size_ll, max_backups);

    while (!g_stop) {
        off_t size = 0;

        if (get_file_size(log_path, &size) == 0 && size >= (off_t)max_size_ll) {
            // Close current FD before rotation if this daemon owns the file.
            if (fd >= 0) {
                close(fd);
                fd = -1;
            }

            if (rotate_logs(log_path, max_backups) != 0) {
                fprintf(stderr, "Rotation failed: %s\n", strerror(errno));
            } else {
                fprintf(stderr, "Rotated %s\n", log_path);
            }

            if (reopen_log_if_needed(log_path, &fd) != 0) {
                fprintf(stderr, "Reopen failed: %s\n", strerror(errno));
            }
        }

        safe_sleep(CHECK_INTERVAL);
    }

    if (fd >= 0) close(fd);
    fprintf(stderr, "Exiting\n");
    return 0;
}
