## Initial implementation

```c
// logrotate_daemon.c
#define _POSIX_C_SOURCE 200809L

#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PATH_LEN 4096
#define DEFAULT_CHECK_INTERVAL_SEC 5

typedef struct {
    char log_path[MAX_PATH_LEN];
    size_t max_size_bytes;
    int keep_files;
    unsigned check_interval_sec;
} config_t;

static int path_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int get_size(const char *path, off_t *out_size) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *out_size = st.st_size;
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    // Remove the oldest file if it exists.
    snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, cfg->keep_files);
    if (unlink(old_path) != 0 && errno != ENOENT) {
        perror("unlink oldest");
        return -1;
    }

    // Shift rotated files upward: .(n-1) -> .n
    for (int i = cfg->keep_files - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", cfg->log_path, i + 1);

        if (path_exists(old_path)) {
            if (rename(old_path, new_path) != 0) {
                perror("rename rotated");
                return -1;
            }
        }
    }

    // Rotate current log to .1
    snprintf(new_path, sizeof(new_path), "%s.1", cfg->log_path);
    if (rename(cfg->log_path, new_path) != 0) {
        perror("rename current");
        return -1;
    }

    // Recreate empty log file with safe permissions
    int fd = open(cfg->log_path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
    if (fd < 0) {
        perror("open new log");
        return -1;
    }
    close(fd);

    return 0;
}

static int ensure_log_file(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0640);
    if (fd < 0) {
        perror("open ensure log");
        return -1;
    }
    close(fd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <log_path> <max_size_bytes> <keep_files> [check_interval_sec]\n", prog);
}

int main(int argc, char **argv) {
    if (argc < 4) {
        usage(argv[0]);
        return 1;
    }

    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    snprintf(cfg.log_path, sizeof(cfg.log_path), "%s", argv[1]);
    cfg.max_size_bytes = (size_t)strtoull(argv[2], NULL, 10);
    cfg.keep_files = atoi(argv[3]);
    cfg.check_interval_sec = (argc >= 5) ? (unsigned)atoi(argv[4]) : DEFAULT_CHECK_INTERVAL_SEC;

    if (cfg.keep_files < 1) {
        fprintf(stderr, "keep_files must be >= 1\n");
        return 1;
    }

    if (cfg.max_size_bytes == 0) {
        fprintf(stderr, "max_size_bytes must be > 0\n");
        return 1;
    }

    if (ensure_log_file(cfg.log_path) != 0) {
        return 1;
    }

    for (;;) {
        off_t size = 0;
        if (get_size(cfg.log_path, &size) == 0) {
            if ((size_t)size >= cfg.max_size_bytes) {
                if (rotate_logs(&cfg) != 0) {
                    fprintf(stderr, "rotation failed\n");
                }
            }
        } else {
            // If log missing, recreate it.
            if (errno == ENOENT) {
                ensure_log_file(cfg.log_path);
            } else {
                perror("stat");
            }
        }

        sleep(cfg.check_interval_sec);
    }

    return 0;
}
