#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define LOG_PATH_MAX 256
#define BUF_SIZE 512

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static int safe_snprintf(char *dst, size_t dst_sz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dst_sz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dst_sz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *path, int keep) {
    char src[LOG_PATH_MAX];
    char dst[LOG_PATH_MAX];

    for (int i = keep - 1; i >= 1; --i) {
        if (safe_snprintf(src, sizeof(src), "%s.%d", path, i) < 0) return -1;
        if (safe_snprintf(dst, sizeof(dst), "%s.%d", path, i + 1) < 0) return -1;

        // Best-effort rename; ignore missing files.
        if (rename(src, dst) < 0 && errno != ENOENT) {
            return -1;
        }
    }

    if (safe_snprintf(dst, sizeof(dst), "%s.1", path) < 0) return -1;
    if (rename(path, dst) < 0 && errno != ENOENT) {
        return -1;
    }

    return 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0) {
        return -1;
    }
    return st.st_size;
}

static int ensure_log_file_exists(const char *path) {
    int fd = open(path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int reopen_log_fd(const char *path, int *fd_out) {
    int fd = open(path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) return -1;
    *fd_out = fd;
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path = "/tmp/example.log";
    off_t max_size = 1024 * 1024;   // 1 MiB default
    int keep = 3;                   // keep .1, .2, .3
    int interval_sec = 2;           // polling interval

    if (argc > 1) log_path = argv[1];
    if (argc > 2) max_size = (off_t)atoll(argv[2]);
    if (argc > 3) keep = atoi(argv[3]);
    if (argc > 4) interval_sec = atoi(argv[4]);

    if (keep < 1 || keep > 99 || interval_sec < 1) {
        log_stderr("Invalid arguments");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (ensure_log_file_exists(log_path) < 0) {
        perror("ensure_log_file_exists");
        return 1;
    }

    int fd = -1;
    if (reopen_log_fd(log_path, &fd) < 0) {
        perror("open");
        return 1;
    }

    char buf[BUF_SIZE];

    while (g_running) {
        off_t sz = file_size(log_path);
        if (sz < 0) {
            perror("stat");
            break;
        }

        if (sz >= max_size) {
            close(fd);
            fd = -1;

            if (rotate_logs(log_path, keep) < 0) {
                perror("rotate_logs");
                break;
            }

            if (reopen_log_fd(log_path, &fd) < 0) {
                perror("reopen_log_fd");
                break;
            }

            const char *msg = "log rotated\n";
            if (write(fd, msg, strlen(msg)) < 0) {
                perror("write");
                break;
            }
        }

        // Minimal daemon behavior: append a heartbeat line.
        // Replace this with your own log collection logic if needed.
        time_t now = time(NULL);
        struct tm tmv;
        localtime_r(&now, &tmv);
        int len = snprintf(buf, sizeof(buf),
                           "%04d-%02d-%02d %02d:%02d:%02d daemon heartbeat\n",
                           tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday,
                           tmv.tm_hour, tmv.tm_min, tmv.tm_sec);

        if (len > 0 && len < (int)sizeof(buf)) {
            if (write(fd, buf, (size_t)len) < 0) {
                perror("write");
                break;
            }
        }

        sleep((unsigned)interval_sec);
    }

    if (fd >= 0) close(fd);
    return 0;
}
