## `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 5
#define CHECK_INTERVAL_SEC 5

static int copy_file(const char *src, const char *dst) {
    int in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    int out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    char buf[8192];
    ssize_t r;
    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    close(in_fd);
    close(out_fd);
    return (r < 0) ? -1 : 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *logfile) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    for (int i = MAX_ROTATIONS - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", logfile, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", logfile, i + 1);

        if (access(old_path, F_OK) == 0) {
            rename(old_path, new_path);
        }
    }

    snprintf(new_path, sizeof(new_path), "%s.1", logfile);
    if (rename(logfile, new_path) < 0) {
        return -1;
    }

    return 0;
}

static int ensure_logfile(const char *logfile) {
    int fd = open(logfile, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s <logfile> <max_size_bytes>\n", argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    off_t max_size = (off_t)atoll(argv[2]);

    if (max_size <= 0) {
        fprintf(stderr, "invalid max_size_bytes\n");
        return 1;
    }

    if (ensure_logfile(logfile) < 0) {
        perror("ensure_logfile");
        return 1;
    }

    while (1) {
        off_t sz;
        if (file_size(logfile, &sz) == 0 && sz >= max_size) {
            if (rotate_logs(logfile) < 0) {
                perror("rotate_logs");
            } else {
                if (ensure_logfile(logfile) < 0) {
                    perror("recreate logfile");
                }
            }
        }

        sleep(CHECK_INTERVAL_SEC);
    }

    return 0;
}
