static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t limit_bytes;
    struct timespec ts;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <logfile> <size_limit_bytes>\n", argv[0]);
        return 1;
    }

    logfile = argv[1];
    limit_bytes = (off_t)atoll(argv[2]);

    ts.tv_sec = CHECK_INTERVAL_SEC;
    ts.tv_nsec = 0;

    for (;;) {
        off_t sz = file_size(logfile);
        if (sz < 0) {
            perror("stat");
            nanosleep(&ts, NULL);
            continue;
        }

        if (sz >= limit_bytes) {
            if (rotate_logs(logfile) == 0) {
                int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
                if (fd >= 0) close(fd);
            } else {
                perror("rotate");
            }
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}
