Below is a **minimal working C daemon** for log rotation that is designed to stay small and memory-conscious. It:

- runs in the background as a daemon
- watches a single log file
- rotates it when it exceeds a size threshold
- renames old rotations with a max count
- avoids large allocations and uses fixed-size buffers

## Notes

- This is intentionally minimal, not production-hardened.
- It assumes a POSIX-like system.
- It rotates by **renaming** the current log to `log.1`, shifting older files up to `log.N`.
- It does **not** compress logs or watch multiple files.
- It uses low memory and simple syscalls.

---

## `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_PATH_LEN 512
#define MAX_ROTATIONS 5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int write_all(int fd, const char *buf, size_t len) {
    while (len > 0) {
        ssize_t n = write(fd, buf, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        buf += (size_t)n;
        len -= (size_t)n;
    }
    return 0;
}

static void log_error(const char *msg) {
    int fd = STDERR_FILENO;
    (void)write_all(fd, msg, strlen(msg));
    (void)write_all(fd, "\n", 1);
}

static int rotate_logs(const char *path, int max_rotations) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    for (int i = max_rotations - 1; i >= 1; --i) {
        int a = snprintf(old_path, sizeof(old_path), "%s.%d", path, i);
        int b = snprintf(new_path, sizeof(new_path), "%s.%d", path, i + 1);

        if (a < 0 || b < 0 || (size_t)a >= sizeof(old_path) || (size_t)b >= sizeof(new_path)) {
            errno = ENAMETOOLONG;
            return -1;
        }

        if (access(old_path, F_OK) == 0) {
            if (rename(old_path, new_path) < 0) {
                return -1;
            }
        }
    }

    int base = snprintf(old_path, sizeof(old_path), "%s", path);
    int first = snprintf(new_path, sizeof(new_path), "%s.1", path);
    if (base < 0 || first < 0 || (size_t)base >= sizeof(old_path) || (size_t)first >= sizeof(new_path)) {
        errno = ENAMETOOLONG;
        return -1;
    }

    if (access(old_path, F_OK) == 0) {
        if (rename(old_path, new_path) < 0) {
            return -1;
        }
    }

    return 0;
}

static int reopen_log(const char *path, int *fd_out) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    *fd_out = fd;
    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static void daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) exit(EXIT_FAILURE);

    pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(027);
    chdir("/");

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > STDERR_FILENO) close(fd);
    }
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <logfile> <max_size_bytes> <poll_seconds>\n", prog);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_path = argv[1];
    long max_size = strtol(argv[2], NULL, 10);
    long poll_seconds = strtol(argv[3], NULL, 10);

    if (max_size <= 0 || poll_seconds <= 0) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGTERM, on_signal);
    signal(SIGINT, on_signal);

    daemonize();

    int log_fd = -1;
    if (reopen_log(log_path, &log_fd) < 0) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (!g_stop) {
        off_t size = 0;
        if (file_size(log_path, &size) == 0 && size >= (off_t)max_size) {
            close(log_fd);

            if (rotate_logs(log_path, MAX_ROTATIONS) < 0) {
                log_error("Log rotation failed");
                break;
            }

            if (reopen_log(log_path, &log_fd) < 0) {
                log_error("Failed to reopen log file");
                break;
            }
        }

        sleep((unsigned int)poll_seconds);
    }

    if (log_fd >= 0) close(log_fd);
    return EXIT_SUCCESS;
}
