## `logrotate_daemon.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_BACKUPS 5
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) {
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int rename_if_exists(const char *src, const char *dst) {
    if (access(src, F_OK) != 0) {
        return 0; // nothing to do
    }
    if (rename(src, dst) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *basepath) {
    char src[PATH_MAX];
    char dst[PATH_MAX];

    // Remove oldest
    snprintf(src, sizeof(src), "%s.%d", basepath, MAX_BACKUPS);
    unlink(src);

    // Shift backups upward
    for (int i = MAX_BACKUPS - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", basepath, i);
        snprintf(dst, sizeof(dst), "%s.%d", basepath, i + 1);

        if (access(src, F_OK) == 0) {
            if (rename(src, dst) != 0) {
                return -1;
            }
        }
    }

    // Rotate the main log
    snprintf(dst, sizeof(dst), "%s.1", basepath);
    if (access(basepath, F_OK) == 0) {
        if (rename(basepath, dst) != 0) {
            return -1;
        }
    }

    // Create fresh empty log file
    int fd = open(basepath, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    close(fd);

    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(0);

    if (chdir("/") != 0) return -1;

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) return -1;

    dup2(nullfd, STDIN_FILENO);
    dup2(nullfd, STDOUT_FILENO);
    dup2(nullfd, STDERR_FILENO);

    if (nullfd > STDERR_FILENO) close(nullfd);

    return 0;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <logfile> <max_bytes>\n", argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    off_t max_bytes = (off_t)strtoll(argv[2], NULL, 10);

    if (max_bytes <= 0) {
        fprintf(stderr, "max_bytes must be > 0\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    if (daemonize() != 0) {
        perror("daemonize");
        return 1;
    }

    // Ensure target log exists
    int fd = open(logfile, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) {
        return 1;
    }
    close(fd);

    while (g_running) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0 && sz > max_bytes) {
            if (rotate_logs(logfile) != 0) {
                // Keep running; try again next cycle
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    return 0;
}
