use anyhow::Result;
use serde::Deserialize;
use std::fs;
use std::time::Duration;
use sysinfo::{CpuExt, System, SystemExt};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    poll_interval_secs: u64,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    action_cooldown_secs: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_secs: 2,
            cpu_warn_threshold: 85.0,
            mem_warn_threshold: 90.0,
            action_cooldown_secs: 30,
        }
    }
}

struct DaemonState {
    last_action: std::time::Instant,
}

impl DaemonState {
    fn new() -> Self {
        Self {
            last_action: std::time::Instant::now() - Duration::from_secs(60),
        }
    }

    fn can_act(&self, cooldown: Duration) -> bool {
        self.last_action.elapsed() >= cooldown
    }

    fn mark_action(&mut self) {
        self.last_action = std::time::Instant::now();
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let config = load_config("daemon.toml").unwrap_or_else(|_| Config::default());
    info!("Starting resource daemon with config: {:?}", config);

    let mut system = System::new_all();
    let mut ticker = interval(Duration::from_secs(config.poll_interval_secs));
    let mut state = DaemonState::new();

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                system.refresh_cpu();
                system.refresh_memory();
                system.refresh_processes();

                let cpu_usage = average_cpu_usage(&system);
                let mem_usage = memory_usage_percent(&system);

                info!("cpu={:.1}% mem={:.1}%", cpu_usage, mem_usage);

                if cpu_usage >= config.cpu_warn_threshold || mem_usage >= config.mem_warn_threshold {
                    warn!(
                        "threshold exceeded: cpu={:.1}% mem={:.1}%",
                        cpu_usage, mem_usage
                    );

                    if state.can_act(Duration::from_secs(config.action_cooldown_secs)) {
                        manage_resources(&system, cpu_usage, mem_usage).await;
                        state.mark_action();
                    } else {
                        info!("action cooldown active; skipping management action");
                    }
                }
            }

            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("daemon stopped");
    Ok(())
}

fn load_config(path: &str) -> Result<Config> {
    let text = fs::read_to_string(path)?;
    let cfg: Config = toml::from_str(&text)?;
    Ok(cfg)
}

fn average_cpu_usage(system: &System) -> f32 {
    let cpus = system.cpus();
    if cpus.is_empty() {
        return 0.0;
    }
    let total: f32 = cpus.iter().map(|c| c.cpu_usage()).sum();
    total / cpus.len() as f32
}

fn memory_usage_percent(system: &System) -> f32 {
    let total = system.total_memory() as f32;
    if total <= 0.0 {
        return 0.0;
    }

    let used = system.used_memory() as f32;
    (used / total) * 100.0
}

async fn manage_resources(system: &System, cpu: f32, mem: f32) {
    // Placeholder for real management logic:
    // - lower service priority
    // - signal a worker pool to shed load
    // - cleanup temporary caches
    // - restart a misbehaving service
    // - write events to journald/syslog
    //
    // Be careful: process killing/restarting should be policy-driven and privileged
    // operations should be isolated and audited.

    if cpu > 95.0 {
        warn!("high CPU detected ({:.1}%), consider load shedding", cpu);
    }

    if mem > 95.0 {
        warn!("high memory detected ({:.1}%), consider cache cleanup or restart policy", mem);
    }

    // Example: inspect top memory processes
    let mut top: Vec<_> = system.processes().values().collect();
    top.sort_by(|a, b| b.memory().cmp(&a.memory()));

    for proc_ in top.into_iter().take(5) {
        info!(
            "top process: pid={} name={} mem={} KB cpu={:.1}%",
            proc_.pid(),
            proc_.name(),
            proc_.memory(),
            proc_.cpu_usage()
        );
    }
}
