use anyhow::Result;
use serde::Serialize;
use std::{
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::{signal, sync::RwLock, time};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    cpu_usage: f32,
    process_count: usize,
}

#[derive(Debug, Clone)]
struct DaemonConfig {
    sample_interval: Duration,
    cpu_warn_threshold: f32,
    memory_warn_threshold: f32,
}

impl Default for DaemonConfig {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(1),
            cpu_warn_threshold: 85.0,
            memory_warn_threshold: 90.0,
        }
    }
}

struct ResourceDaemon {
    sys: System,
    config: DaemonConfig,
    last_snapshot: Arc<RwLock<Option<ResourceSnapshot>>>,
    start_time: Instant,
}

impl ResourceDaemon {
    fn new(config: DaemonConfig) -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything());

        let mut sys = System::new_with_specifics(refresh);
        sys.refresh_all();

        Self {
            sys,
            config,
            last_snapshot: Arc::new(RwLock::new(None)),
            start_time: Instant::now(),
        }
    }

    fn collect_snapshot(&mut self) -> ResourceSnapshot {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.sys.refresh_processes();

        let total_memory = self.sys.total_memory();
        let used_memory = self.sys.used_memory();
        let total_swap = self.sys.total_swap();
        let used_swap = self.sys.used_swap();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();
        let process_count = self.sys.processes().len();

        ResourceSnapshot {
            timestamp_ms: self.start_time.elapsed().as_millis(),
            total_memory,
            used_memory,
            total_swap,
            used_swap,
            cpu_usage,
            process_count,
        }
    }

    async fn handle_snapshot(&self, snapshot: &ResourceSnapshot) {
        let mem_pct = if snapshot.total_memory == 0 {
            0.0
        } else {
            (snapshot.used_memory as f32 / snapshot.total_memory as f32) * 100.0
