use serde::Serialize;
use std::sync::{Arc, RwLock};
use std::time::Duration;
use sysinfo::{CpuRefreshKind, Disks, ProcessRefreshKind, RefreshKind, System};
use tokio::io::AsyncWriteExt;
use tokio::net::{TcpListener, TcpStream};
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    cpu_usage_percent: f32,
    memory_used_mb: u64,
    memory_total_mb: u64,
    swap_used_mb: u64,
    swap_total_mb: u64,
    disk_used_gb: u64,
    disk_total_gb: u64,
    process_count: usize,
}

fn collect_metrics(sys: &mut System) -> Metrics {
    sys.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything()),
    );

    let disks = Disks::new_with_refreshed_list();

    let cpu_usage_percent = sys.global_cpu_usage();

    let memory_used_mb = sys.used_memory() / 1024;
    let memory_total_mb = sys.total_memory() / 1024;
    let swap_used_mb = sys.used_swap() / 1024;
    let swap_total_mb = sys.total_swap() / 1024;

    let mut disk_used_bytes: u128 = 0;
    let mut disk_total_bytes: u128 = 0;
    for disk in disks.list() {
        let total = disk.total_space() as u128;
        let available = disk.available_space() as u128;
        disk_total_bytes += total;
        disk_used_bytes += total.saturating_sub(available);
    }

    let disk_used_gb = (disk_used_bytes / (1024 * 1024 * 1024)) as u64;
    let disk_total_gb = (disk_total_bytes / (1024 * 1024 * 1024)) as u64;

    let process_count = sys.processes().len();

    Metrics {
        cpu_usage_percent,
        memory_used_mb,
        memory_total_mb,
        swap_used_mb,
        swap_total_mb,
        disk_used_gb,
        disk_total_gb,
        process_count,
    }
}

async fn serve_client(mut stream: TcpStream, shared: Arc<RwLock<Metrics>>) {
    let snapshot = {
        let guard = shared.read().unwrap();
        guard.clone()
    };

    match serde_json::to_vec_pretty(&snapshot) {
        Ok(mut json) => {
            json.push(b'\n');
            if let Err(e) = stream.write_all(&json).await {
                warn!("failed to write metrics to client: {}", e);
            }
        }
        Err(e) => warn!("failed to serialize metrics: {}", e),
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let shared_metrics = Arc::new(RwLock::new(Metrics::default()));

    // Sampler task
    {
        let shared_metrics = Arc::clone(&shared_metrics);
        tokio::spawn(async move {
            let mut sys = System::new_with_specifics(
                RefreshKind::new()
                    .with_cpu(CpuRefreshKind::everything())
                    .with_memory()
                    .with_processes(ProcessRefreshKind::everything()),
            );

            let mut ticker = interval(Duration::from_secs(2));

            loop {
                ticker.tick().await;
                let metrics = collect_metrics(&mut sys);

                {
                    let mut guard = shared_metrics.write().unwrap();
                    *guard = metrics.clone();
                }

                info!(
                    "cpu={:.1}% mem={}/{}MB swap={}/{}MB disk={}/{}GB procs={}",
                    metrics.cpu_usage_percent,
                    metrics.memory_used_mb,
                    metrics.memory_total_mb,
                    metrics.swap_used_mb,
                    metrics.swap_total_mb,
                    metrics.disk_used_gb,
                    metrics.disk_total_gb,
                    metrics.process_count
                );
            }
        });
    }

    // Local metrics endpoint
    let listener = TcpListener::bind("127.0.0.1:7878").await?;
    info!("metrics endpoint listening on 127.0.0.1:7878");

    loop {
        let (stream, addr) = listener.accept().await?;
        info!("client connected: {}", addr);

        let shared = Arc::clone(&shared_metrics);
        tokio::spawn(async move {
            serve_client(stream, shared).await;
        });
    }
}
