use anyhow::{Context, Result};
use nix::unistd::Pid;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Clone)]
struct Config {
    poll_interval_secs: u64,
    cpu_alert_threshold: f32,
    memory_alert_threshold: f32,
    target_pid: Option<i32>,
    throttle_nice_value: i32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_secs: 5,
            cpu_alert_threshold: 85.0,
            memory_alert_threshold: 90.0,
            target_pid: None,
            throttle_nice_value: 10,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = Config::default();

    info!("starting resource daemon");
    run_daemon(config).await
}

async fn run_daemon(config: Config) -> Result<()> {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    let mut ticker = interval(Duration::from_secs(config.poll_interval_secs));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                if let Err(e) = sample_and_manage(&mut system, &config) {
                    warn!("monitoring cycle failed: {e:#}");
                }
            }
            _ = tokio::signal::ctrl_c() => {
                info!("shutdown requested");
                break;
            }
        }
    }

    Ok(())
}

fn sample_and_manage(system: &mut System, config: &Config) -> Result<()> {
    system.refresh_cpu();
    system.refresh_memory();

    let cpu_usage = system.global_cpu_info().cpu_usage();
    let used_mem = system.used_memory();
    let total_mem = system.total_memory();
    let mem_usage = if total_mem > 0 {
        (used_mem as f32 / total_mem as f32) * 100.0
    } else {
        0.0
    };

    info!(
        cpu_usage = cpu_usage,
        memory_used_mb = used_mem / 1024,
        memory_total_mb = total_mem / 1024,
        memory_usage_pct = mem_usage,
        "resource snapshot"
    );

    if cpu_usage >= config.cpu_alert_threshold {
        warn!("CPU threshold exceeded: {:.1}%", cpu_usage);
    }

    if mem_usage >= config.memory_alert_threshold {
        warn!("memory threshold exceeded: {:.1}%", mem_usage);
    }

    // Optional benign management action:
    // lower scheduling priority of a configured process.
    if let Some(pid) = config.target_pid {
        if cpu_usage >= config.cpu_alert_threshold {
            throttle_process(pid, config.throttle_nice_value)
                .with_context(|| format!("failed to throttle pid {pid}"))?;
        }
    }

    Ok(())
}

fn throttle_process(pid: i32, nice_value: i32) -> Result<()> {
    // "renice" behavior: increase niceness to lower priority.
    // Requires appropriate permissions depending on the target process.
    let pid = Pid::from_raw(pid);

    let status = std::process::Command::new("renice")
        .arg("-n")
        .arg(nice_value.to_string())
        .arg("-p")
        .arg(pid.as_raw().to_string())
        .status()
        .context("could not execute renice")?;

    if !status.success() {
        anyhow::bail!("renice exited with status {status}");
    }

    info!("throttled process pid={} nice={}", pid.as_raw(), nice_value);
    Ok(())
}
