use std::time::Duration;
use sysinfo::{CpuExt, System, SystemExt};
use tokio::time::interval;

struct DaemonConfig {
    poll_interval: Duration,
    high_memory_threshold_pct: f32,
    high_cpu_threshold_pct: f32,
}

#[derive(Debug)]
struct ResourceSnapshot {
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    cpu_usage: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
}

struct ResourceDaemon {
    system: System,
    config: DaemonConfig,
}

impl ResourceDaemon {
    fn new(config: DaemonConfig) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self { system, config }
    }

    fn collect_snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_memory();
        self.system.refresh_cpu();
        self.system.refresh_load_average();

        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let load_avg = System::load_average();

        ResourceSnapshot {
            total_memory,
            used_memory,
            total_swap,
            used_swap,
            cpu_usage,
            load_avg_one: load_avg.one,
            load_avg_five: load_avg.five,
            load_avg_fifteen: load_avg.fifteen,
        }
    }

    fn memory_usage_pct(&self, snap: &ResourceSnapshot) -> f32 {
        if snap.total_memory == 0 {
            0.0
        } else {
            (snap.used_memory as f32 / snap.total_memory as f32) * 100.0
        }
    }

    async fn handle_pressure(&self, snap: &ResourceSnapshot) {
        let mem_pct = self.memory_usage_pct(snap);

        if mem_pct >= self.config.high_memory_threshold_pct {
            eprintln!(
                "[WARN] High memory usage detected: {:.2}% (used {} / total {})",
                mem_pct, snap.used_memory, snap.total_memory
            );

            // Placeholder management action:
            // In a real daemon, you might:
            // - notify another subsystem
            // - invoke cgroup controls
            // - trigger cache reclamation
            // - lower service priority
            // - kill/evict noncritical tasks
            //
            // This example just logs the event.
        }

        if snap.cpu_usage >= self.config.high_cpu_threshold_pct {
            eprintln!(
                "[WARN] High CPU usage detected: {:.2}%",
                snap.cpu_usage
            );

            // Placeholder management action for CPU pressure.
        }
    }

    async fn run(&mut self) {
        let mut ticker = interval(self.config.poll_interval);

        loop {
            ticker.tick().await;

            let snapshot = self.collect_snapshot();
            self.report(&snapshot);
            self.handle_pressure(&snapshot).await;
        }
    }

    fn report(&self, snap: &ResourceSnapshot) {
        let mem_pct = if snap.total_memory == 0 {
            0.0
        } else {
            (snap.used_memory as f32 / snap.total_memory as f32) * 100.0
        };

        println!(
            "[INFO] CPU: {:.2}% | Mem: {:.2}% ({} / {}) | Swap: {} / {} | Load: {:.2}, {:.2}, {:.2}",
            snap.cpu_usage,
            mem_pct,
            snap.used_memory,
            snap.total_memory,
            snap.used_swap,
            snap.total_swap,
            snap.load_avg_one,
            snap.load_avg_five,
            snap.load_avg_fifteen
        );
    }
}

