use anyhow::Result;
use std::time::Duration;
use sysinfo::{CpuExt, System, SystemExt};
use tokio::signal;
use tokio::time;
use tracing::{debug, error, info, warn};

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    info!("starting os-daemon");

    let mut system = System::new_all();
    system.refresh_all();

    let monitor_interval = Duration::from_secs(2);

    let monitor_task = tokio::spawn(async move {
        monitor_loop(&mut system, monitor_interval).await;
    });

    let shutdown_result = wait_for_shutdown().await;
    info!("shutdown signal received: {:?}", shutdown_result);

    monitor_task.abort();
    let _ = monitor_task.await;

    info!("os-daemon stopped");
    Ok(())
}

fn init_logging() {
    let filter = std::env::var("RUST_LOG").unwrap_or_else(|_| "info".to_string());

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

async fn wait_for_shutdown() -> Result<()> {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal as unix_signal, SignalKind};

        let mut sigterm = unix_signal(SignalKind::terminate())?;
        let mut sigint = unix_signal(SignalKind::interrupt())?;

        tokio::select! {
            _ = sigterm.recv() => Ok(()),
            _ = sigint.recv() => Ok(()),
        }
    }

    #[cfg(not(unix))]
    {
        signal::ctrl_c().await?;
        Ok(())
    }
}

async fn monitor_loop(system: &mut System, interval: Duration) {
    let mut ticker = time::interval(interval);

    loop {
        ticker.tick().await;

        if let Err(e) = perform_monitoring_cycle(system).await {
            error!("monitoring cycle failed: {e:?}");
        }
    }
}

async fn perform_monitoring_cycle(system: &mut System) -> Result<()> {
    system.refresh_cpu();
    system.refresh_memory();
    system.refresh_processes();

    let total_memory = system.total_memory();
    let used_memory = system.used_memory();
    let memory_usage = if total_memory > 0 {
        (used_memory as f64 / total_memory as f64) * 100.0
    } else {
        0.0
    };

    let cpu_usage = system.global_cpu_info().cpu_usage();

    info!(
        cpu_usage = format!("{:.2}", cpu_usage),
        memory_usage = format!("{:.2}", memory_usage),
        used_memory_kib = used_memory,
        total_memory_kib = total_memory,
        "resource snapshot"
    );

    // Example management policy:
    // If memory exceeds 90%, log a warning and (later) trigger remediation.
    if memory_usage > 90.0 {
        warn!(
            memory_usage = format!("{:.2}", memory_usage),
            "high memory pressure detected"
        );

        // Placeholder for remediation logic:
        // - notify supervisor
        // - kill/renice low priority processes
        // - trigger cleanup hooks
        // - write to metrics/telemetry backend
    }

    // Example process inspection hook:
    let process_count = system.processes().len();
    debug!(process_count, "process inventory refreshed");

    Ok(())
}
