use anyhow::{Context, Result};
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use std::collections::HashSet;
use std::time::Duration;
use sysinfo::{LoadAvg, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};

const MONITOR_INTERVAL_SECS: u64 = 5;

// Simple policy thresholds
const HIGH_CPU_THRESHOLD: f32 = 85.0;
const HIGH_MEMORY_THRESHOLD: f32 = 90.0;
const HIGH_LOAD_THRESHOLD: f64 = 4.0;

// Example: avoid repeatedly acting on the same PID
static mut PROCESSED_PIDS: Option<HashSet<i32>> = None;

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    info!("resource-daemon starting");

    let mut system = System::new_all();
    system.refresh_all();

    // Initialize action history
    unsafe {
        PROCESSED_PIDS = Some(HashSet::new());
    }

    let mut tick = interval(Duration::from_secs(MONITOR_INTERVAL_SECS));

    loop {
        tokio::select! {
            _ = tick.tick() => {
                if let Err(e) = monitor_once(&mut system).await {
                    error!("monitor cycle failed: {e:#}");
                }
            }
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("resource-daemon stopped");
    Ok(())
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .with_target(false)
        .init();
}

async fn monitor_once(system: &mut System) -> Result<()> {
    system.refresh_all();

    log_system_summary(system);

    if let Some((pid, cpu)) = find_hot_process(system) {
        warn!("high cpu process detected: pid={pid}, cpu={cpu:.1}%");
        maybe_manage_process(pid, cpu).await?;
    }

    if system.global_cpu_usage() > HIGH_CPU_THRESHOLD {
        warn!("system CPU is high: {:.1}%", system.global_cpu_usage());
    }

    if system.used_memory() as f64 / system.total_memory().max(1) as f64 * 100.0 > HIGH_MEMORY_THRESHOLD as f64 {
        warn!(
            "system memory is high: used={}MB total={}MB",
            system.used_memory() / 1024,
            system.total_memory() / 1024
        );
    }

    let LoadAvg { one, five, fifteen } = System::load_average();
    if one > HIGH_LOAD_THRESHOLD {
        warn!("high load average: 1m={one:.2}, 5m={five:.2}, 15m={fifteen:.2}");
    }

    Ok(())
}

fn log_system_summary(system: &System) {
    let cpu = system.global_cpu_usage();
    let used_mem_mb = system.used_memory() / 1024;
    let total_mem_mb = system.total_memory() / 1024;
    let used_swap_mb = system.used_swap() / 1024;
    let total_swap_mb = system.total_swap() / 1024;

    info!(
        "system summary: cpu={cpu:.1}% mem={used_mem_mb}/{total_mem_mb}MB swap={used_swap_mb}/{total_swap_mb}MB"
    );
}

fn find_hot_process(system: &System) -> Option<(i32, f32)> {
    let mut hottest: Option<(i32, f32)> = None;

    for (pid, process) in system.processes() {
        let cpu = process.cpu_usage();
        if cpu > HIGH_CPU_THRESHOLD {
            let pid_i32 = pid.as_u32() as i32;
            match hottest {
                Some((_, current_cpu)) if current_cpu >= cpu => {}
                _ => hottest = Some((pid_i32, cpu)),
            }
        }
    }

    hottest
}

async fn maybe_manage_process(pid: i32, cpu: f32) -> Result<()> {
    let should_skip = unsafe {
        match PROCESSED_PIDS.as_mut() {
            Some(set) => {
                if set.contains(&pid) {
                    true
                } else {
                    set.insert(pid);
                    false
                }
            }
            None => false,
        }
    };

    if should_skip {
        return Ok(());
    }

    // Initial management action:
    // send SIGTERM to a runaway process. In a real daemon, this should be policy-driven,
    // logged, audited, and likely restricted to known services or cgroups.
    warn!("sending SIGTERM to pid={pid} cpu={cpu:.1}%");
    kill(Pid::from_raw(pid), Signal::SIGTERM)
        .with_context(|| format!("failed to signal pid {pid}"))?;

    Ok(())
}
```

