use anyhow::Result;
use serde::Serialize;
use std::time::Duration;
use tokio::signal;
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Clone)]
struct Config {
    sample_interval: Duration,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    disk_warn_threshold: f32,
    load_warn_threshold: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(2),
            cpu_warn_threshold: 80.0,
            mem_warn_threshold: 85.0,
            disk_warn_threshold: 90.0,
            load_warn_threshold: 4.0,
        }
    }
}

#[derive(Debug, Serialize)]
struct Metrics {
    cpu_usage_percent: f32,
    memory_used_percent: f32,
    disk_used_percent: f32,
    load_avg_1m: f64,
}

struct Daemon {
    config: Config,
    sys: sysinfo::System,
}

impl Daemon {
    fn new(config: Config) -> Self {
        let mut sys = sysinfo::System::new_all();
        sys.refresh_all();

        Self { config, sys }
    }

    fn collect_metrics(&mut self) -> Metrics {
        // Refresh system state
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.sys.refresh_disks_list();
        self.sys.refresh_disks();

        let cpu_usage_percent = self.sys.global_cpu_info().cpu_usage();
        let total_memory = self.sys.total_memory() as f32;
        let used_memory = self.sys.used_memory() as f32;
        let memory_used_percent = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in self.sys.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(available);
        }

        let disk_used_percent = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        let load_avg_1m = sysinfo::System::load_average().one;

        Metrics {
            cpu_usage_percent,
            memory_used_percent,
            disk_used_percent,
            load_avg_1m,
        }
    }

    async fn handle_metrics(&self, metrics: &Metrics) -> Result<()> {
        info!(target: "sysd::metrics", json = %serde_json::to_string(metrics)?, "collected metrics");

        if metrics.cpu_usage_percent > self.config.cpu_warn_threshold {
            warn!(
                cpu = metrics.cpu_usage_percent,
                threshold = self.config.cpu_warn_threshold,
                "CPU usage above threshold"
            );
            self.take_action("cpu", metrics.cpu_usage_percent).await?;
        }

        if metrics.memory_used_percent > self.config.mem_warn_threshold {
            warn!(
                memory = metrics.memory_used_percent,
                threshold = self.config.mem_warn_threshold,
                "Memory usage above threshold"
            );
            self.take_action("memory", metrics.memory_used_percent).await?;
        }

        if metrics.disk_used_percent > self.config.disk_warn_threshold {
            warn!(
                disk = metrics.disk_used_percent,
                threshold = self.config.disk_warn_threshold,
                "Disk usage above threshold"
            );
            self.take_action("disk", metrics.disk_used_percent).await?;
        }

        if metrics.load_avg_1m > self.config.load_warn_threshold as f64 {
            warn!(
                load_avg_1m = metrics.load_avg_1m,
                threshold = self.config.load_warn_threshold,
                "Load average above threshold"
            );
            self.take_action("load", metrics.load_avg_1m).await?;
        }

        Ok(())
    }

    async fn take_action<T: std::fmt::Display>(&self, resource: &str, value: T) -> Result<()> {
        // Placeholder: replace with safe, policy-driven actions.
        // Examples:
        // - notify a controller over DBus/HTTP
        // - write to journald
        // - initiate cache cleanup
        // - adjust service priority
        // - isolate noisy processes
        info!(resource, value = %value, "management action triggered");

        Ok(())
    }

    async fn run(mut self) -> Result<()> {
        let mut ticker = interval(self.config.sample_interval);

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let metrics = self.collect_metrics();
                    self.handle_metrics(&metrics).await?;
                }
                _ = signal::ctrl_c() => {
                    info!("shutdown requested");
                    break;
                }
            }
        }

        Ok(())
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
