        let used_swap = self.system.used_swap();
        let cpu_usage = self.system.global_cpu_usage();
        let load_one = System::load_average().one;
        let process_count = self.system.processes().len();

        ResourceSnapshot {
            total_memory,
            used_memory,
            total_swap,
            used_swap,
            cpu_usage,
            load_one,
            process_count,
        }
    }

    fn log_snapshot(&self, s: &ResourceSnapshot) {
        let mem_pct = if s.total_memory > 0 {
            (s.used_memory as f64 / s.total_memory as f64) * 100.0
        } else {
            0.0
        };

        let swap_pct = if s.total_swap > 0 {
            (s.used_swap as f64 / s.total_swap as f64) * 100.0
        } else {
            0.0
        };

        info!(
            cpu_usage = format_args!("{:.1}%", s.cpu_usage),
            mem_usage = format_args!("{:.1}%", mem_pct),
            swap_usage = format_args!("{:.1}%", swap_pct),
            load_one = format_args!("{:.2}", s.load_one),
            processes = s.process_count,
            "resource snapshot"
        );
    }

    fn check_thresholds(&self, s: &ResourceSnapshot) {
        let mem_pct = if s.total_memory > 0 {
            (s.used_memory as f64 / s.total_memory as f64) * 100.0
        } else {
            0.0
        };

        if s.cpu_usage > self.config.cpu_warn_threshold {
            warn!(
                cpu_usage = format_args!("{:.1}%", s.cpu_usage),
                threshold = self.config.cpu_warn_threshold,
                "CPU usage high"
            );
        }

        if mem_pct > self.config.mem_warn_threshold as f64 {
            warn!(
                mem_usage = format_args!("{:.1}%", mem_pct),
                threshold = self.config.mem_warn_threshold,
                "memory usage high"
            );
        }

        if s.load_one > self.config.load_warn_threshold {
            warn!(
                load_one = format_args!("{:.2}", s.load_one),
                threshold = self.config.load_warn_threshold,
                "load average high"
            );
        }
    }

    fn manage_resources(&self, s: &ResourceSnapshot) {
        // Initial placeholder management policy:
        // - In a real daemon, this might:
        //   - lower priority of optional worker processes
        //   - reclaim caches via kernel interfaces
        //   - kill runaway children if it owns them
        //   - adjust cgroups
        //   - trigger autoscaling or alerts
        //
        // Here, we only log an action candidate.

        if s.cpu_usage > self.config.cpu_warn_threshold && s.load_one > self.config.load_warn_threshold {
            warn!(
                "management action candidate: system under sustained pressure; consider throttling non-critical workloads"
            );
        }

        debug!("resource management pass complete");
    }

    async fn run(&mut self) -> Result<()> {
        info!("daemon starting");

        let mut ticker = interval(self.config.poll_interval);

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.snapshot();
                    self.log_snapshot(&snapshot);
                    self.check_thresholds(&snapshot);
                    self.manage_resources(&snapshot);
                }

                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let config = Config::default();
    let mut daemon = Daemon::new(config);

    if let Err(e) = daemon.run().await {
        error!(error = %e, "daemon failed");
        return Err(e);
    }

    Ok(())
}
