fn main() {
    // Log file
    let log_file = match File::create("/tmp/sysdaemon.log") {
        Ok(file) => file,
        Err(e) => {
            eprintln!("Failed to create log file: {}", e);
            return;
        }
    };

    // Start daemon
    let daemonize = Daemonize::new()
        .pid_file("/tmp/sysdaemon.pid")
        .working_directory("/")
        .umask(0o027);

    match daemonize.start() {
        Ok(_) => {}
        Err(e) => {
            eprintln!("Daemonization failed: {}", e);
            return;
        }
    }

    // Initialize logging after daemonizing
    if let Err(e) = WriteLogger::init(LevelFilter::Info, Config::default(), log_file) {
        eprintln!("Logger init failed: {}", e);
        return;
    }

    info!("sysdaemon started");

    let mut system = System::new_all();

    loop {
        system.refresh_all();

        // CPU
        let cpu_usage = system.global_cpu_info().cpu_usage();

        // Memory
        let total_memory = system.total_memory();
        let used_memory = system.used_memory();
        let mem_percent = if total_memory > 0 {
            (used_memory as f64 / total_memory as f64) * 100.0
        } else {
            0.0
        };

        // Disk
        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in system.disks() {
            disk_total += disk.total_space();
            disk_used += disk.total_space() - disk.available_space();
        }

        let disk_percent = if disk_total > 0 {
            (disk_used as f64 / disk_total as f64) * 100.0
        } else {
            0.0
        };

        info!(
            "CPU: {:.2}% | Memory: {:.2}% ({} / {} KB) | Disk: {:.2}%",
            cpu_usage, mem_percent, used_memory, total_memory, disk_percent
        );

        // Simple management action
        if mem_percent > 80.0 {
            warn!("High memory usage detected: {:.2}%", mem_percent);
            // Placeholder for management actions:
            // - notify
            // - free caches (if appropriate and privileged)
            // - restart or throttle services
        }

        if cpu_usage > 90.0 {
            warn!("High CPU usage detected: {:.2}%", cpu_usage);
        }

        if disk_percent > 90.0 {
            warn!("High disk usage detected: {:.2}%", disk_percent);
        }

        thread::sleep(Duration::from_secs(5));
    }
}
