## `src/main.rs`

```rust
use anyhow::Result;
use std::{
    fs,
    io::{BufRead, BufReader},
    thread,
    time::{Duration, Instant},
};

#[derive(Debug, Clone)]
struct CpuSnapshot {
    idle: u64,
    total: u64,
}

fn read_cpu_snapshot() -> Result<CpuSnapshot> {
    let file = fs::File::open("/proc/stat")?;
    let mut reader = BufReader::new(file);
    let mut line = String::new();
    reader.read_line(&mut line)?;

    // Expected format:
    // cpu  user nice system idle iowait irq softirq steal guest guest_nice
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        anyhow::bail!("unexpected /proc/stat format");
    }

    let mut values = Vec::new();
    for p in &parts[1..] {
        values.push(p.parse::<u64>()?);
    }

    let idle = values[3] + values.get(4).copied().unwrap_or(0);
    let total: u64 = values.iter().sum();

    Ok(CpuSnapshot { idle, total })
}

fn compute_cpu_usage(prev: &CpuSnapshot, curr: &CpuSnapshot) -> f64 {
    let total_delta = curr.total.saturating_sub(prev.total) as f64;
    let idle_delta = curr.idle.saturating_sub(prev.idle) as f64;

    if total_delta == 0.0 {
        return 0.0;
    }

    ((total_delta - idle_delta) / total_delta) * 100.0
}

fn read_mem_usage() -> Result<(u64, u64, f64)> {
    let content = fs::read_to_string("/proc/meminfo")?;
    let mut total_kb = 0u64;
    let mut available_kb = 0u64;

    for line in content.lines() {
        if line.starts_with("MemTotal:") {
            total_kb = line
                .split_whitespace()
                .nth(1)
                .ok_or_else(|| anyhow::anyhow!("missing MemTotal value"))?
                .parse()?;
        } else if line.starts_with("MemAvailable:") {
            available_kb = line
                .split_whitespace()
                .nth(1)
                .ok_or_else(|| anyhow::anyhow!("missing MemAvailable value"))?
                .parse()?;
        }
    }

    if total_kb == 0 {
        anyhow::bail!("could not read total memory");
    }

    let used_kb = total_kb.saturating_sub(available_kb);
    let used_pct = (used_kb as f64 / total_kb as f64) * 100.0;

    Ok((used_kb, total_kb, used_pct))
}

fn main() -> Result<()> {
    println!("resource_daemon starting...");

    let mut poll_interval = Duration::from_secs(2);
    let high_cpu_threshold = 80.0;

    let mut prev = read_cpu_snapshot()?;

    loop {
        let start = Instant::now();

        thread::sleep(poll_interval);

        let curr = read_cpu_snapshot()?;
        let cpu = compute_cpu_usage(&prev, &curr);
        prev = curr;

        let (_used_kb, _total_kb, mem_pct) = read_mem_usage()?;

        println!(
            "[{:?}] CPU: {:.1}% | Mem: {:.1}% | Poll: {:?}",
            start.elapsed(),
            cpu,
            mem_pct,
            poll_interval
        );

        // Minimal "management" behavior:
        // back off polling if CPU is high, otherwise restore normal interval
        if cpu > high_cpu_threshold {
            poll_interval = Duration::from_secs(5);
            println!("High CPU detected; backing off polling interval.");
        } else {
            poll_interval = Duration::from_secs(2);
        }
    }
}
```

