// Fast hash
// -----------------------------
static inline uint64_t fnv1a64(const void* data, size_t len) {
    const uint8_t* p = static_cast<const uint8_t*>(data);
    uint64_t hash = 1469598103934665603ULL;
    for (size_t i = 0; i < len; ++i) {
        hash ^= p[i];
        hash *= 1099511628211ULL;
    }
    return hash;
}

// -----------------------------
// Flow key
// -----------------------------
struct FlowKey {
    uint32_t src_ip = 0;
    uint32_t dst_ip = 0;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;
    uint8_t  proto = 0;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        return static_cast<size_t>(fnv1a64(&k, sizeof(k)));
    }
};

// -----------------------------
// Flow stats
// -----------------------------
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

// -----------------------------
// Flow record
// -----------------------------
struct FlowRecord {
    FlowKey key;
    FlowStats stats;
};

// -----------------------------
// Sharded flow table
// -----------------------------
class FlowShard {
public:
    explicit FlowShard(size_t reserve_hint = 1 << 16) {
        table_.reserve(reserve_hint);
    }

    void update(const FlowKey& key, uint32_t packet_len, uint64_t now_ns) {
        auto it = table_.find(key);
        if (it == table_.end()) {
            FlowRecord rec;
            rec.key = key;
            rec.stats.packets = 1;
            rec.stats.bytes = packet_len;
            rec.stats.first_seen_ns = now_ns;
            rec.stats.last_seen_ns = now_ns;
            table_.emplace(key, rec);
        } else {
            it->second.stats.packets++;
            it->second.stats.bytes += packet_len;
            it->second.stats.last_seen_ns = now_ns;
        }
    }

    const std::unordered_map<FlowKey, FlowRecord, FlowKeyHash>& snapshot() const {
        return table_;
    }

private:
    std::unordered_map<FlowKey, FlowRecord, FlowKeyHash> table_;
};

class FlowTable {
public:
    static constexpr size_t kShards = 64;

    FlowTable() {
        for (auto& shard : shards_) {
            shard = std::make_unique<FlowShard>();
        }
    }

    void update(const FlowKey& key, uint32_t packet_len, uint64_t now_ns) {
        auto idx = shardIndex(key);
        shards_[idx]->update(key, packet_len, now_ns);
    }

private:
    std::array<std::unique_ptr<FlowShard>, kShards> shards_;

    static size_t shardIndex(const FlowKey& key) {
        uint64_t h = fnv1a64(&key, sizeof(key));
        return static_cast<size_t>(h % kShards);
    }
};

// -----------------------------
// Packet parsing
// -----------------------------
struct PacketView {
    const uint8_t* data = nullptr;
    size_t len = 0;
};

static inline uint64_t nowNs() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(
        steady_clock::now().time_since_epoch()
    ).count();
}

bool parseFlowKey(const PacketView& pkt, FlowKey& out) {
#if defined(__linux__)
    if (pkt.len < sizeof(ether_header)) return false;

    const ether_header* eth = reinterpret_cast<const ether_header*>(pkt.data);
    uint16_t eth_type = ntohs(eth->ether_type);

    if (eth_type != ETHERTYPE_IP) {
        return false; // IPv4 only in this skeleton
    }

    size_t offset = sizeof(ether_header);
    if (pkt.len < offset + sizeof(iphdr)) return false;

    const iphdr* ip = reinterpret_cast<const iphdr*>(pkt.data + offset);
    size_t ip_header_len = ip->ihl * 4;
    if (ip_header_len < sizeof(iphdr) || pkt.len < offset + ip_header_len) return false;

    out.src_ip = ntohl(ip->saddr);
    out.dst_ip = ntohl(ip->daddr);
    out.proto = ip->protocol;

    offset += ip_header_len;

    if (ip->protocol == IPPROTO_TCP) {
        if (pkt.len < offset + sizeof(tcphdr)) return false;
        const tcphdr* tcp = reinterpret_cast<const tcphdr*>(pkt.data + offset);
        out.src_port = ntohs(tcp->source);
        out.dst_port = ntohs(tcp->dest);
        return true;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (pkt.len < offset + sizeof(udphdr)) return false;
        const udphdr* udp = reinterpret_cast<const udphdr*>(pkt.data + offset);
        out.src_port = ntohs(udp->source);
        out.dst_port = ntohs(udp->dest);
        return true;
    }

    out.src_port = 0;
    out.dst_port = 0;
    return true;
#else
    (void)pkt;
    (void)out;
    return false;
#endif
}

// -----------------------------
// Analyzer
// -----------------------------
class FlowAnalyzer {
public:
    void processPacket(const PacketView& pkt) {
        FlowKey key{};
        if (!parseFlowKey(pkt, key)) return;

        uint64_t ts = nowNs();
        flows_.update(key, static_cast<uint32_t>(pkt.len), ts);
    }

private:
    FlowTable flows_;
};

// -----------------------------
// Demo driver
// -----------------------------
int main() {
    FlowAnalyzer analyzer;

    // In production, replace this with a real capture backend.
    std::vector<uint8_t> fakePacket(64, 0);

    // This is only a placeholder:
    // you'd normally feed actual captured frames here.
    PacketView pkt{fakePacket.data(), fakePacket.size()};

    for (size_t i = 0; i < 1000000; ++i) {
        analyzer.processPacket(pkt);
    }

    std::cout << "Processed packets.\n";
    return 0;
}
