```rust
use std::collections::HashMap;
use std::io::{self, BufRead};

#[derive(Debug, Clone, Hash, PartialEq, Eq)]
struct FlowKey {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
}

fn parse_line(line: &str) -> Option<(FlowKey, FlowStats)> {
    // Expected format:
    // src_ip,dst_ip,src_port,dst_port,proto,packets,bytes
    let parts: Vec<&str> = line.trim().split(',').collect();
    if parts.len() != 7 {
        return None;
    }

    Some((
        FlowKey {
            src_ip: parts[0].to_string(),
            dst_ip: parts[1].to_string(),
            src_port: parts[2].parse().ok()?,
            dst_port: parts[3].parse().ok()?,
            proto: parts[4].parse().ok()?,
        },
        FlowStats {
            packets: parts[5].parse().ok()?,
            bytes: parts[6].parse().ok()?,
        },
    ))
}

fn main() {
    let stdin = io::stdin();
    let mut agg: HashMap<FlowKey, FlowStats> = HashMap::new();

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };

        if let Some((key, stats)) = parse_line(&line) {
            let entry = agg.entry(key).or_default();
            entry.packets += stats.packets;
            entry.bytes += stats.bytes;
        }
    }

    let mut flows: Vec<_> = agg.into_iter().collect();
    flows.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));

    for (key, stats) in flows.iter().take(20) {
        println!(
            "{}:{} -> {}:{} proto={} packets={} bytes={}",
            key.src_ip, key.src_port, key.dst_ip, key.dst_port, key.proto, stats.packets, stats.bytes
        );
    }
}
