use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Hash, Eq, PartialEq, Debug)]
struct FlowKey {
    src: Ipv4Addr,
    dst: Ipv4Addr,
    proto: u8,
    src_port: u16,
    dst_port: u16,
}

#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Option<Instant>,
    last_seen: Option<Instant>,
}

impl FlowStats {
    fn update(&mut self, packet_len: usize, now: Instant) {
        self.packets += 1;
        self.bytes += packet_len as u64;
        if self.first_seen.is_none() {
            self.first_seen = Some(now);
        }
        self.last_seen = Some(now);
    }

    fn age(&self, now: Instant) -> Option<Duration> {
        self.first_seen.map(|t| now.duration_since(t))
    }
}

#[derive(Debug)]
struct NetworkFlowAnalyzer {
    flows: HashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
}

impl NetworkFlowAnalyzer {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity(1 << 16),
            idle_timeout,
        }
    }

    fn process_packet(
        &mut self,
        src: Ipv4Addr,
        dst: Ipv4Addr,
        proto: u8,
        src_port: u16,
        dst_port: u16,
        packet_len: usize,
        now: Instant,
    ) {
        let key = FlowKey {
            src,
            dst,
            proto,
            src_port,
            dst_port,
        };

        self.flows
            .entry(key)
            .or_default()
            .update(packet_len, now);
    }

    fn expire_idle_flows(&mut self, now: Instant) -> Vec<(FlowKey, FlowStats)> {
        let idle_timeout = self.idle_timeout;
        let mut expired = Vec::new();

        self.flows.retain(|key, stats| {
            let keep = match stats.last_seen {
                Some(last) => now.duration_since(last) <= idle_timeout,
                None => true,
            };

            if !keep {
                expired.push((*key, stats.clone()));
            }
            keep
        });

        expired
    }

    fn snapshot_top_flows_by_bytes(&self, n: usize) -> Vec<(FlowKey, FlowStats)> {
        let mut flows: Vec<_> = self.flows.iter().map(|(k, v)| (*k, v.clone())).collect();
        flows.sort_by(|a, b| b.1.bytes.cmp(&a.1.bytes));
        flows.truncate(n);
        flows
    }
}

fn main() {
    let mut analyzer = NetworkFlowAnalyzer::new(Duration::from_secs(30));

    // Example packet stream
    let now = Instant::now();
    analyzer.process_packet(
        Ipv4Addr::new(10, 0, 0, 1),
        Ipv4Addr::new(10, 0, 0, 2),
        6, // TCP
        12345,
        443,
        1500,
        now,
    );
    analyzer.process_packet(
        Ipv4Addr::new(10, 0, 0, 1),
        Ipv4Addr::new(10, 0, 0, 2),
        6,
        12345,
        443,
        900,
        now,
    );
    analyzer.process_packet(
        Ipv4Addr::new(10, 0, 0, 3),
        Ipv4Addr::new(10, 0, 0, 4),
        17, // UDP
        5353,
        5353,
        300,
        now,
    );

    let top = analyzer.snapshot_top_flows_by_bytes(10);
    for (flow, stats) in top {
        println!(
            "{:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={}",
            flow.src, flow.src_port, flow.dst, flow.dst_port, flow.proto, stats.packets, stats.bytes
        );
    }

    let expired = analyzer.expire_idle_flows(Instant::now() + Duration::from_secs(31));
    println!("Expired {} flow(s)", expired.len());
}
