## Rust flow analyser

```rust
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};
use dashmap::DashMap;
use parking_lot::RwLock;
use std::thread;

// =========================
// Flow key / stats
// =========================

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
enum FlowKey {
    V4 {
        src: Ipv4Addr,
        dst: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    },
    V6 {
        src: Ipv6Addr,
        dst: Ipv6Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
    }
}

#[derive(Debug, Default)]
struct FlowStats {
    packets: AtomicU64,
    bytes: AtomicU64,
    first_seen_ns: AtomicU64,
    last_seen_ns: AtomicU64,
}

impl FlowStats {
    fn update(&self, packet_len: u64, now_ns: u64) {
        self.packets.fetch_add(1, Ordering::Relaxed);
        self.bytes.fetch_add(packet_len, Ordering::Relaxed);

        let first = self.first_seen_ns.load(Ordering::Relaxed);
        if first == 0 {
            let _ = self.first_seen_ns.compare_exchange(
                0,
                now_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            );
        }
        self.last_seen_ns.store(now_ns, Ordering::Relaxed);
    }

    fn snapshot(&self) -> FlowSnapshot {
        FlowSnapshot {
            packets: self.packets.load(Ordering::Relaxed),
            bytes: self.bytes.load(Ordering::Relaxed),
            first_seen_ns: self.first_seen_ns.load(Ordering::Relaxed),
            last_seen_ns: self.last_seen_ns.load(Ordering::Relaxed),
        }
    }
}

#[derive(Debug, Clone)]
struct FlowSnapshot {
    packets: u64,
    bytes: u64,
    first_seen_ns: u64,
    last_seen_ns: u64,
}

// =========================
// Analyzer
// =========================

struct FlowAnalyzer {
    flows: DashMap<FlowKey, Arc<FlowStats>>,
    expired_after: Duration,
}

impl FlowAnalyzer {
    fn new(expired_after: Duration) -> Self {
        Self {
            flows: DashMap::new(),
            expired_after,
        }
    }

    #[inline]
    fn now_ns() -> u64 {
        let now = Instant::now();
        now.elapsed().as_nanos() as u64
    }

    fn process_packet(&self, pkt: &[u8]) {
        if let Some((key, len)) = parse_packet(pkt) {
            let now_ns = Self::now_ns();

            let stats = self.flows.entry(key).or_insert_with(|| {
                Arc::new(FlowStats::default())
            }).clone();

            stats.update(len as u64, now_ns);
        }
    }

    fn expire_old_flows(&self) {
        // In production: track wall-clock timestamps and remove stale flows efficiently.
        // This simple version periodically scans the map.
        let cutoff_ns = Self::now_ns().saturating_sub(self.expired_after.as_nanos() as u64);

        let to_remove: Vec<FlowKey> = self.flows
            .iter()
            .filter_map(|entry| {
                let stats = entry.value();
                let last = stats.last_seen_ns.load(Ordering::Relaxed);
                if last != 0 && last < cutoff_ns {
                    Some(entry.key().clone())
                } else {
                    None
                }
            })
            .collect();

        for k in to_remove {
            self.flows.remove(&k);
        }
    }

    fn snapshot_top_n(&self, n: usize) -> Vec<(FlowKey, FlowSnapshot)> {
        let mut v: Vec<_> = self.flows
            .iter()
            .map(|entry| (entry.key().clone(), entry.value().snapshot()))
            .collect();

        v.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));
        v.truncate(n);
        v
    }
}

// =========================
// Packet parsing
// =========================
//
// This parser assumes Ethernet + IPv4/IPv6 + TCP/UDP.
// For high-speed usage, avoid allocations and minimize bounds checks.
// This is intentionally simple and conservative.

fn parse_packet(pkt: &[u8]) -> Option<(FlowKey, usize)> {
    if pkt.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    match ethertype {
        0x0800 => parse_ipv4(pkt, 14),
        0x86DD => parse_ipv6(pkt, 14),
        _ => None,
    }
}

fn parse_ipv4(pkt: &[u8], mut off: usize) -> Option<(FlowKey, usize)> {
    if pkt.len() < off + 20 {
        return None;
    }

    let ver_ihl = pkt[off];
    if ver_ihl >> 4 != 4 {
        return None;
    }

    let ihl = ((ver_ihl & 0x0F) as usize) * 4;
    if ihl < 20 || pkt.len() < off + ihl {
        return None;
    }

    let proto = pkt[off + 9];
    let src = Ipv4Addr::new(pkt[off + 12], pkt[off + 13], pkt[off + 14], pkt[off + 15]);
    let dst = Ipv4Addr::new(pkt[off + 16], pkt[off + 17], pkt[off + 18], pkt[off + 19]);
    off += ihl;

    if pkt.len() < off + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt[off], pkt[off + 1]]);
    let dst_port = u16::from_be_bytes([pkt[off + 2], pkt[off + 3]]);

    Some((
        FlowKey::V4 {
            src,
            dst,
            src_port,
            dst_port,
            proto,
        },
        pkt.len(),
    ))
}

fn parse_ipv6(pkt: &[u8], mut off: usize) -> Option<(FlowKey, usize)> {
    if pkt.len() < off + 40 {
        return None;
    }

    let version = pkt[off] >> 4;
    if version != 6 {
        return None;
    }

    let next_header = pkt[off + 6];
    let src = Ipv6Addr::from(<[u8; 16]>::try_from(&pkt[off + 8..off + 24]).ok()?);
    let dst = Ipv6Addr::from(<[u8; 16]>::try_from(&pkt[off + 24..off + 40]).ok()?);
    off += 40;

    if pkt.len() < off + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([pkt[off], pkt[off + 1]]);
    let dst_port = u16::from_be_bytes([pkt[off + 2], pkt[off + 3]]);

    Some((
        FlowKey::V6 {
            src,
            dst,
            src_port,
            dst_port,
            proto: next_header,
        },
        pkt.len(),
    ))
}

// =========================
// Input source abstraction
// =========================

trait PacketSource: Send {
    fn next_packet(&mut self) -> Option<Vec<u8>>;
}

// Dummy source for testing
struct DummySource {
    counter: usize,
}

impl DummySource {
    fn new() -> Self {
        Self { counter: 0 }
    }
}

impl PacketSource for DummySource {
    fn next_packet(&mut self) -> Option<Vec<u8>> {
        self.counter += 1;
        if self.counter > 1_000_000 {
            return None;
        }

        // Fake Ethernet + IPv4 + TCP packet
        let mut pkt = vec![0u8; 14 + 20 + 20];
        pkt[12] = 0x08;
        pkt[13] = 0x00;

        // IPv4 header
        let ip_off = 14;
        pkt[ip_off] = 0x45; // version + IHL
        pkt[ip_off + 9] = 6; // TCP
        pkt[ip_off + 12..ip_off + 16].copy_from_slice(&[10, 0, 0, 1]);
        pkt[ip_off + 16..ip_off + 20].copy_from_slice(&[10, 0, 0, 2]);

        // TCP ports
        let tcp_off = 14 + 20;
        pkt[tcp_off..tcp_off + 2].copy_from_slice(&12345u16.to_be_bytes());
        pkt[tcp_off + 2..tcp_off + 4].copy_from_slice(&80u16.to_be_bytes());

        Some(pkt)
    }
}

// =========================
// Main loop
// =========================

fn main() {
    let analyzer = Arc::new(FlowAnalyzer::new(Duration::from_secs(60)));

    let analyzer_for_expiry = analyzer.clone();
    thread::spawn(move || {
        loop {
            thread::sleep(Duration::from_secs(5));
            analyzer_for_expiry.expire_old_flows();
        }
    });

    let mut source: Box<dyn PacketSource> = Box::new(DummySource::new());

    let start = Instant::now();
    let mut processed: u64 = 0;

    while let Some(pkt) = source.next_packet() {
        analyzer.process_packet(&pkt);
        processed += 1;

        if processed % 100_000 == 0 {
            let elapsed = start.elapsed().as_secs_f64();
            let pps = processed as f64 / elapsed.max(1e-9);
            println!("Processed: {processed}, rate: {pps:.2} pkt/s");

            let top = analyzer.snapshot_top_n(5);
            println!("Top flows:");
            for (k, s) in top {
                println!("{:?} => packets={}, bytes={}", k, s.packets, s.bytes);
            }
        }
    }

    println!("Done. Total packets processed: {processed}");
}
