use anyhow::{Context, Result};
use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use hashbrown::HashMap;
use pcap::{Capture, Device, Packet};
use std::collections::hash_map::RandomState;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Hash, PartialEq, Eq)]
enum FlowKey {
    V4 {
        src: Ipv4Addr,
        dst: Ipv4Addr,
        proto: u8,
        src_port: u16,
        dst_port: u16,
    },
    V6 {
        src: Ipv6Addr,
        dst: Ipv6Addr,
        proto: u8,
        src_port: u16,
        dst_port: u16,
    },
}

#[derive(Debug, Default)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, packet_len: usize, now: Instant) {
        self.packets += 1;
        self.bytes += packet_len as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct FlowRecord {
    key: FlowKey,
    stats: FlowStats,
}

fn main() -> Result<()> {
    let device = Device::lookup()
        .context("failed to lookup default capture device")?
        .context("no default capture device found")?;

    println!("Capturing on device: {}", device.name);

    let (tx, rx) = bounded::<Vec<u8>>(65_536);

    let capture_handle = {
        let tx = tx.clone();
        thread::spawn(move || {
            if let Err(e) = capture_loop(device, tx) {
                eprintln!("capture loop error: {:#}", e);
            }
        })
    };

    let processor_handle = thread::spawn(move || {
        if let Err(e) = processing_loop(rx) {
            eprintln!("processing loop error: {:#}", e);
        }
    });

    capture_handle.join().unwrap();
    processor_handle.join().unwrap();

    Ok(())
}

fn capture_loop(device: Device, tx: Sender<Vec<u8>>) -> Result<()> {
    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .snaplen(2048)
        .timeout(10)
        .open()
        .context("failed to open pcap capture")?;

    // Optional BPF filter for performance. Adjust as needed.
    // cap.filter("ip or ip6", true).ok();

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let data = packet.data.to_vec();
                if tx.send(data).is_err() {
                    break;
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => return Err(e.into()),
        }
    }

    Ok(())
}

fn processing_loop(rx: Receiver<Vec<u8>>) -> Result<()> {
    let mut flows: HashMap<FlowKey, FlowStats, RandomState> =
        HashMap::with_capacity_and_hasher(1 << 20, RandomState::new());

    let mut last_flush = Instant::now();
    let flush_interval = Duration::from_secs(10);
    let idle_timeout = Duration::from_secs(30);

    while let Ok(packet_bytes) = rx.recv() {
        let now = Instant::now();

        if let Ok(sliced) = SlicedPacket::from_ethernet(&packet_bytes) {
            if let Some(flow_key) = build_flow_key(&sliced) {
                let entry = flows.entry(flow_key).or_insert_with(|| FlowStats::new(now));
                entry.update(packet_bytes.len(), now);
            }
        }

        if last_flush.elapsed() >= flush_interval {
            flush_expired_flows(&mut flows, idle_timeout);
            last_flush = Instant::now();
        }
    }

    // Final flush
    flush_all_flows(&mut flows);

    Ok(())
}

fn build_flow_key(sliced: &SlicedPacket<'_>) -> Option<FlowKey> {
    let (src_ip, dst_ip, proto) = match sliced.ip {
        Some(InternetSlice::Ipv4(header, _)) => (
            Ipv4Addr::from(header.source()),
            Ipv4Addr::from(header.destination()),
            header.protocol(),
        ),
        Some(InternetSlice::Ipv6(header, _)) => (
            // handled below
            Ipv4Addr::UNSPECIFIED,
            Ipv4Addr::UNSPECIFIED,
            0,
        ),
        _ => return None,
    };

    let (src_port, dst_port) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
        Some(TransportSlice::Icmpv4(_)) => (0, 0),
        Some(TransportSlice::Icmpv6(_)) => (0, 0),
        _ => (0, 0),
    };

    match sliced.ip {
        Some(InternetSlice::Ipv4(_, _)) => Some(FlowKey::V4 {
            src: src_ip,
            dst: dst_ip,
            proto,
            src_port,
            dst_port,
        }),
        Some(InternetSlice::Ipv6(header, _)) => Some(FlowKey::V6 {
            src: Ipv6Addr::from(header.source()),
            dst: Ipv6Addr::from(header.destination()),
            proto: header.next_header(),
            src_port,
            dst_port,
        }),
        _ => None,
    }
}

fn flush_expired_flows(flows: &mut HashMap<FlowKey, FlowStats, RandomState>, idle_timeout: Duration) {
    let now = Instant::now();
    let expired_keys: Vec<FlowKey> = flows
        .iter()
        .filter_map(|(k, v)| {
            if now.duration_since(v.last_seen) >= idle_timeout {
                Some(k.clone())
            } else {
                None
            }
        })
        .collect();

    for key in expired_keys {
        if let Some(stats) = flows.remove(&key) {
            emit_flow(&key, &stats);
        }
    }
}

fn flush_all_flows(flows: &mut HashMap<FlowKey, FlowStats, RandomState>) {
    for (key, stats) in flows.drain() {
        emit_flow(&key, &stats);
    }
}

fn emit_flow(key: &FlowKey, stats: &FlowStats) {
    println!("{:?} packets={} bytes={} first_seen={:?} last_seen={:?}",
        key, stats.packets, stats.bytes, stats.first_seen, stats.last_seen);
}
```

