use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use parking_lot::Mutex;
use pnet::datalink::{self, Channel::Ethernet, Config};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::cmp::Reverse;
use std::collections::HashMap;
use std::env;
use std::net::IpAddr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum TransportProtocol {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: TransportProtocol,
}

#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, packet_len: usize, now: Instant) {
        self.packets += 1;
        self.bytes += packet_len as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct PacketEvent {
    flow: FlowKey,
    packet_len: usize,
    timestamp: Instant,
}

fn main() {
    let iface_name = env::args()
        .nth(1)
        .expect("Usage: flow_analyzer <interface>");

    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == iface_name)
        .expect("Interface not found");

    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(10));
    config.promiscuous = true;
    config.rx_queue_size = 4096;

    let (tx, rx) = bounded::<PacketEvent>(100_000);

    let aggregator_handle = thread::spawn(move || aggregator_loop(rx));

    let capture_handle = thread::spawn(move || capture_loop(interface, config, tx));

    capture_handle.join().expect("capture thread failed");
    aggregator_handle.join().expect("aggregator thread failed");
}

fn capture_loop(interface: datalink::NetworkInterface, config: Config, tx: Sender<PacketEvent>) {
    let channel = datalink::channel(&interface, config).expect("Failed to open datalink channel");

    let mut rx = match channel {
        Ethernet(_tx, rx) => rx,
        _ => panic!("Unhandled channel type"),
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(event) = parse_packet(packet) {
                    // If downstream is overloaded, drop rather than block capture.
                    let _ = tx.try_send(event);
                }
            }
            Err(_) => {
                // On timeout or transient read error, continue.
                continue;
            }
        }
    }
}

fn parse_packet(packet: &[u8]) -> Option<PacketEvent> {
    let now = Instant::now();
    let eth = EthernetPacket::new(packet)?;

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ipv4 = Ipv4Packet::new(eth.payload())?;
            let src_ip = IpAddr::V4(ipv4.get_source());
            let dst_ip = IpAddr::V4(ipv4.get_destination());
            let packet_len = ipv4.packet().len();

            match ipv4.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ipv4.payload())?;
                    Some(PacketEvent {
                        flow: FlowKey {
                            src_ip,
                            dst_ip,
                            src_port: tcp.get_source(),
                            dst_port: tcp.get_destination(),
                            proto: TransportProtocol::Tcp,
                        },
                        packet_len,
                        timestamp: now,
                    })
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ipv4.payload())?;
                    Some(PacketEvent {
                        flow: FlowKey {
                            src_ip,
                            dst_ip,
                            src_port: udp.get_source(),
                            dst_port: udp.get_destination(),
                            proto: TransportProtocol::Udp,
                        },
                        packet_len,
                        timestamp: now,
                    })
                }
                other => Some(PacketEvent {
                    flow: FlowKey {
                        src_ip,
                        dst_ip,
                        src_port: 0,
                        dst_port: 0,
                        proto: TransportProtocol::Other(other.0),
                    },
                    packet_len,
                    timestamp: now,
                }),
            }
        }
        EtherTypes::Ipv6 => {
            let ipv6 = Ipv6Packet::new(eth.payload())?;
            let src_ip = IpAddr::V6(ipv6.get_source());
            let dst_ip = IpAddr::V6(ipv6.get_destination());
            let packet_len = ipv6.packet().len();

            match ipv6.get_next_header() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ipv6.payload())?;
                    Some(PacketEvent {
                        flow: FlowKey {
                            src_ip,
                            dst_ip,
                            src_port: tcp.get_source(),
                            dst_port: tcp.get_destination(),
                            proto: TransportProtocol::Tcp,
                        },
                        packet_len,
                        timestamp: now,
                    })
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ipv6.payload())?;
                    Some(PacketEvent {
                        flow: FlowKey {
                            src_ip,
                            dst_ip,
                            src_port: udp.get_source(),
                            dst_port: udp.get_destination(),
                            proto: TransportProtocol::Udp,
                        },
                        packet_len,
                        timestamp: now,
                    })
                }
                other => Some(PacketEvent {
                    flow: FlowKey {
                        src_ip,
                        dst_ip,
                        src_port: 0,
                        dst_port: 0,
                        proto: TransportProtocol::Other(other.0),
                    },
                    packet_len,
                    timestamp: now,
                }),
            }
        }
        _ => None,
    }
}

fn aggregator_loop(rx: Receiver<PacketEvent>) {
    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1_000_000);
    let mut last_report = Instant::now();

    loop {
        // Drain a batch to reduce lock/contention and improve cache locality.
        for _ in 0..50_000 {
            match rx.try_recv() {
                Ok(event) => {
                    let entry = flows
                        .entry(event.flow)
                        .or_insert_with(|| FlowStats::new(event.timestamp));
                    entry.update(event.packet_len, event.timestamp);
                }
                Err(_) => break,
            }
        }

        if last_report.elapsed() >= Duration::from_secs(5) {
            report_top_flows(&flows, 20);
            expire_old_flows(&mut flows, Duration::from_secs(300));
            last_report = Instant::now();
        }

        // Avoid busy-spinning when idle.
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(event) => {
                let entry = flows
                    .entry(event.flow)
                    .or_insert_with(|| FlowStats::new(event.timestamp));
                entry.update(event.packet_len, event.timestamp);
            }
            Err(_) => {}
        }
    }
}

fn report_top_flows(flows: &HashMap<FlowKey, FlowStats>, limit: usize) {
    let mut top: Vec<_> = flows.iter().collect();
    top.sort_unstable_by_key(|(_, stats)| Reverse(stats.bytes));

    println!("=== Top {} flows by bytes ===", limit);
    for (i, (key, stats)) in top.into_iter().take(limit).enumerate() {
        println!(
            "#{:<3} {:?}:{:?} -> {:?}:{:?} proto={:?} packets={} bytes={}",
            i + 1,
            key.src_ip,
            key.src_port,
            key.dst_ip,
            key.dst_port,
            key.proto,
            stats.packets,
            stats.bytes
        );
    }
}

fn expire_old_flows(flows: &mut HashMap<FlowKey, FlowStats>, ttl: Duration) {
    let now = Instant::now();
    flows.retain(|_, stats| now.duration_since(stats.last_seen) <= ttl);
}
