#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

struct FlowTable {
    flows: HashMap<FlowKey, FlowStats, RandomState>,
    timeout: Duration,
}

impl FlowTable {
    fn new(timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_hasher(RandomState::new()),
            timeout,
        }
    }

    fn observe(&mut self, key: FlowKey, bytes: usize, now: Instant) {
        match self.flows.get_mut(&key) {
            Some(stats) => stats.update(now, bytes),
            None => {
                self.flows.insert(key, FlowStats::new(now, bytes));
            }
        }
    }

    fn expire_old(&mut self, now: Instant) {
        let timeout = self.timeout;
        self.flows.retain(|_, stats| now.duration_since(stats.last_seen) <= timeout);
    }

    fn print_snapshot(&self) {
        println!("--- active flows: {} ---", self.flows.len());
        for (k, v) in self.flows.iter().take(20) {
            println!(
                "{}:{} -> {}:{} proto={} packets={} bytes={} age_ms={}",
                k.src_ip,
                k.src_port,
                k.dst_ip,
                k.dst_port,
                k.protocol,
                v.packets,
                v.bytes,
                v.last_seen.duration_since(v.first_seen).as_millis()
            );
        }
    }
}

