            std::process::exit(1);
        });

    let config = datalink::Config {
        read_timeout: Some(Duration::from_millis(10)),
        ..Default::default()
    };

    let (tx, rx) = bounded::<Vec<u8>>(8192);

    // Capture thread
    let capture_handle = std::thread::spawn(move || {
        capture_packets(interface, config, tx);
    });

    // Analyzer thread
    let analyze_handle = std::thread::spawn(move || {
        analyze_loop(rx);
    });

    let _ = capture_handle.join();
    let _ = analyze_handle.join();
}

fn capture_packets(interface: datalink::NetworkInterface, config: datalink::Config, tx: Sender<Vec<u8>>) {
    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(_, rx)) => ((), rx),
        Ok(_) => {
            eprintln!("Unhandled channel type");
            return;
        }
        Err(e) => {
            eprintln!("Failed to open datalink channel: {}", e);
            return;
        }
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                // Copy packet bytes into owned buffer for transfer to analyzer thread.
                // For higher performance, replace this with a slab/buffer pool.
                if tx.send(packet.to_vec()).is_err() {
                    break;
                }
            }
            Err(_) => {
                // Ignore transient capture errors/timeouts.
            }
        }
    }
}

fn analyze_loop(rx: Receiver<Vec<u8>>) {
    let mut flow_table = FlowTable::new(Duration::from_secs(60));
    let mut last_expire = Instant::now();
    let mut last_report = Instant::now();

    loop {
        match rx.recv_timeout(Duration::from_millis(100)) {
            Ok(frame) => {
                let now = Instant::now();
                if let Some((key, size)) = parse_flow_key(&frame) {
                    flow_table.observe(key, size, now);
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }

        let now = Instant::now();

        if now.duration_since(last_expire) >= Duration::from_secs(1) {
            flow_table.expire_old(now);
            last_expire = now;
        }

        if now.duration_since(last_report) >= Duration::from_secs(5) {
            flow_table.print_snapshot();
            last_report = now;
        }
    }
}

fn parse_flow_key(frame: &[u8]) -> Option<(FlowKey, usize)> {
    let eth = EthernetPacket::new(frame)?;
    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return None;
    }

    let ipv4 = Ipv4Packet::new(eth.payload())?;
    let src_ip = ipv4.get_source();
    let dst_ip = ipv4.get_destination();
    let proto = ipv4.get_next_level_protocol();

    let (src_port, dst_port, protocol_u8) = match proto {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ipv4.payload())?;
            (
                tcp.get_source(),
                tcp.get_destination(),
                IpNextHeaderProtocols::Tcp.0,
            )
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ipv4.payload())?;
            (
                udp.get_source(),
                udp.get_destination(),
                IpNextHeaderProtocols::Udp.0,
            )
        }
        _ => return None,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol: protocol_u8,
    };

    Some((key, frame.len()))
}
