use anyhow::{Context, Result};
use etherparse::{SlicedPacket, TransportSlice};
use hashbrown::HashMap;
use pcap::{Capture, Device, PacketHeader};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u128,
    last_seen_ns: u128,
}

impl FlowStats {
    fn new(now_ns: u128, bytes: u64) -> Self {
        Self {
            packets: 1,
            bytes,
            first_seen_ns: now_ns,
            last_seen_ns: now_ns,
        }
    }

    fn update(&mut self, now_ns: u128, bytes: u64) {
        self.packets += 1;
        self.bytes += bytes;
        self.last_seen_ns = now_ns;
    }
}

fn now_ns() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos()
}

fn ipv4_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from_be_bytes(ip.octets())
}

fn parse_flow_key(packet_data: &[u8]) -> Option<(FlowKey, usize)> {
    let sliced = SlicedPacket::from_ethernet(packet_data).ok()?;

    let ether_len = sliced.link.as_ref().map(|l| l.consumed()).unwrap_or(0);
    let ip = sliced.ip?;
    let transport = sliced.transport?;

    let (src_ip, dst_ip) = match ip {
        etherparse::InternetSlice::Ipv4(header, _) => {
            let src = Ipv4Addr::from(header.source());
            let dst = Ipv4Addr::from(header.destination());
            (ipv4_to_u32(src), ipv4_to_u32(dst))
        }
        _ => return None, // IPv4 only for initial implementation
    };

    let (src_port, dst_port, proto) = match transport {
        TransportSlice::Tcp(tcp) => (tcp.source_port(), tcp.destination_port(), 6u8),
        TransportSlice::Udp(udp) => (udp.source_port(), udp.destination_port(), 17u8),
        _ => return None,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    Some((key, ether_len))
}

fn format_flow_key(key: &FlowKey) -> String {
    let src = Ipv4Addr::from(key.src_ip.to_be_bytes());
    let dst = Ipv4Addr::from(key.dst_ip.to_be_bytes());

    format!(
        "{}:{} -> {}:{} proto={}",
        src, key.src_port, dst, key.dst_port, key.proto
    )
}

fn print_top_flows(flows: &HashMap<FlowKey, FlowStats>, top_n: usize) {
    let mut items: Vec<_> = flows.iter().collect();
    items.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

    println!("=== Top {} flows by bytes ===", top_n);
    for (i, (key, stats)) in items.into_iter().take(top_n).enumerate() {
        println!(
            "{:>2}. {:<40} packets={:<12} bytes={:<12} first_seen_ns={} last_seen_ns={}",
            i + 1,
            format_flow_key(key),
            stats.packets,
            stats.bytes,
            stats.first_seen_ns,
            stats.last_seen_ns
        );
    }
}

fn main() -> Result<()> {
    let device_name = std::env::args()
        .nth(1)
        .unwrap_or_else(|| {
            Device::lookup()
                .ok()
                .flatten()
                .map(|d| d.name)
                .unwrap_or_else(|| "eth0".to_string())
        });

    println!("Using device: {}", device_name);

    let device = Device::list()?
        .into_iter()
        .find(|d| d.name == device_name)
        .with_context(|| format!("device {} not found", device_name))?;

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .timeout(10)
        .open()
        .context("failed to open capture")?;

    // BPF filter: only IPv4 TCP/UDP traffic
    cap.filter("ip and (tcp or udp)", true)
        .context("failed to apply filter")?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let report_every = Duration::from_secs(5);
    let mut last_report = Instant::now();

    println!("Capturing... press Ctrl-C to stop.");

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                process_packet(packet.header, packet.data, &mut flows);
            }
            Err(pcap::Error::TimeoutExpired) => {
                // periodic reporting still handled below
            }
            Err(e) => return Err(anyhow::anyhow!("capture error: {}", e)),
        }

        if last_report.elapsed() >= report_every {
            println!();
            println!("=== Report at {:?} ===", Instant::now());
            println!("Active flows: {}", flows.len());
            print_top_flows(&flows, 10);
            last_report = Instant::now();
        }
    }
}

fn process_packet(header: &PacketHeader, data: &[u8], flows: &mut HashMap<FlowKey, FlowStats>) {
    let captured_len = header.len as u64;
    let ts_ns = now_ns();

    if let Some((key, _offset)) = parse_flow_key(data) {
        use hashbrown::hash_map::Entry;
        match flows.entry(key) {
            Entry::Occupied(mut entry) => {
                entry.get_mut().update(ts_ns, captured_len);
            }
            Entry::Vacant(entry) => {
                entry.insert(FlowStats::new(ts_ns, captured_len));
            }
        }
    }
}
