use anyhow::Result;
use clap::Parser;
use dashmap::DashMap;
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::time::{Duration, Instant};

#[derive(Parser, Debug)]
struct Args {
    /// Interface to sniff on
    #[arg(short, long)]
    iface: String,

    /// Expire flows after this many seconds of inactivity
    #[arg(short = 't', long, default_value_t = 30)]
    timeout_secs: u64,
}

#[derive(Clone, Copy, Debug, Hash, PartialEq, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, bytes: usize, now: Instant) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

#[derive(Debug)]
struct FlowRecord {
    key: FlowKey,
    stats: FlowStats,
}

fn parse_flow(packet: &[u8]) -> Option<(FlowKey, usize)> {
    let eth = EthernetPacket::new(packet)?;
    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = Ipv4Packet::new(eth.payload())?;
            let src_ip = ip.get_source();
            let dst_ip = ip.get_destination();
            let proto = ip.get_next_level_protocol().0;

            match ip.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ip.payload())?;
                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port: tcp.get_source(),
                        dst_port: tcp.get_destination(),
                        proto,
                    };
                    Some((key, ip.packet().len()))
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ip.payload())?;
                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port: udp.get_source(),
                        dst_port: udp.get_destination(),
                        proto,
                    };
                    Some((key, ip.packet().len()))
                }
                _ => {
                    // For non-TCP/UDP IPv4 traffic, keep a proto-only pseudo-flow if desired.
                    None
                }
            }
        }
        _ => None,
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == args.iface)
        .expect("interface not found");

    let mut config = datalink::Config::default();
    config.read_timeout = Some(Duration::from_millis(10));
    config.promiscuous = true;
    config.read_buffer_size = 4 * 1024 * 1024;

    let channel = datalink::channel(&interface, config)?;
    let (_, mut rx) = match channel {
        Ethernet(tx, rx) => (tx, rx),
        _ => panic!("Unhandled channel type"),
    };

    let flows: Arc<DashMap<FlowKey, FlowStats>> = Arc::new(DashMap::new());
    let flows_for_reaper = flows.clone();
    let timeout = Duration::from_secs(args.timeout_secs);

    // Background expiration / reporting thread
    std::thread::spawn(move || {
        loop {
            std::thread::sleep(Duration::from_secs(5));
            let now = Instant::now();

            let mut expired = 0usize;
            let mut total_packets = 0u64;
            let mut total_bytes = 0u64;

            let keys: Vec<_> = flows_for_reaper.iter().map(|e| *e.key()).collect();
            for key in keys {
                if let Some(entry) = flows_for_reaper.get(&key) {
                    let stats = entry.value();
                    if now.duration_since(stats.last_seen) > timeout {
                        total_packets += stats.packets;
                        total_bytes += stats.bytes;
                        expired += 1;
                        drop(entry);
                        flows_for_reaper.remove(&key);
                    }
                }
            }

            eprintln!(
                "expired_flows={} active_flows={} exp_packets={} exp_bytes={}",
                expired,
                flows_for_reaper.len(),
                total_packets,
                total_bytes
            );
        }
    });

    let mut packet_count: u64 = 0;
    let mut byte_count: u64 = 0;
    let start = Instant::now();

    loop {
        match rx.next() {
            Ok(packet) => {
                packet_count += 1;
                byte_count += packet.len() as u64;

                let now = Instant::now();
                if let Some((key, len)) = parse_flow(packet) {
                    flows
                        .entry(key)
                        .and_modify(|s| s.update(len, now))
                        .or_insert_with(|| {
                            let mut s = FlowStats::new(now);
                            s.update(len, now);
                            s
                        });
                }

                if packet_count % 1_000_000 == 0 {
                    let secs = start.elapsed().as_secs_f64();
                    eprintln!(
                        "pkts={} bytes={} pps={:.2} bps={:.2} active_flows={}",
                        packet_count,
                        byte_count,
                        packet_count as f64 / secs,
                        (byte_count as f64 * 8.0) / secs,
                        flows.len()
                    );
                }
            }
            Err(_) => {
                // Timeout / transient read issue; continue.
                continue;
            }
        }
    }
}
