    proto: u8,
}

#[derive(Debug, Default)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Option<Instant>,
    last_seen: Option<Instant>,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Pick default capture device
    let device = Device::lookup()?
        .ok_or("No default capture device found")?;

    println!("Capturing on device: {}", device.name);

    // Open capture in promiscuous mode with a large buffer
    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .snaplen(65535)
        .buffer_size(64 * 1024 * 1024)
        .timeout(100)
        .open()?;

    // Optional: non-blocking mode if you want active polling
    // cap = cap.setnonblock()?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let mut last_report = Instant::now();

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                let data = packet.data;

                if let Ok(headers) = PacketHeaders::from_ethernet_slice(data) {
                    let (src, dst, proto) = match headers.ip {
                        Some(InternetSlice::Ipv4(ipv4)) => (
                            IpAddr::V4(ipv4.source_addr()),
                            IpAddr::V4(ipv4.destination_addr()),
                            ipv4.protocol(),
                        ),
                        Some(InternetSlice::Ipv6(ipv6)) => (
                            IpAddr::V6(ipv6.source_addr()),
                            IpAddr::V6(ipv6.destination_addr()),
                            ipv6.next_header(),
                        ),
                        _ => continue,
                    };

                    let (src_port, dst_port) = match headers.transport {
                        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
                        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
                        _ => (0, 0),
                    };

                    let key = FlowKey {
                        src,
                        dst,
                        src_port,
                        dst_port,
                        proto,
                    };

                    let stats = match flows.entry(key) {
                        Entry::Occupied(mut e) => e.get_mut(),
                        Entry::Vacant(e) => e.insert(FlowStats {
                            first_seen: Some(now),
                            ..Default::default()
                        }),
                    };

                    stats.packets += 1;
                    stats.bytes += packet.data.len() as u64;
                    stats.last_seen = Some(now);
                }
            }
            Err(_) => {
                // Ignore capture timeouts/errors in this minimal example
            }
        }

        // Periodic reporting
        if last_report.elapsed() >= Duration::from_secs(5) {
            report_top_flows(&flows);
            last_report = Instant::now();
        }
    }
}

fn report_top_flows(flows: &HashMap<FlowKey, FlowStats>) {
    println!("\n=== Flow summary: {} active flows ===", flows.len());

    // Minimal: print first few flows
    for (i, (k, v)) in flows.iter().take(10).enumerate() {
        println!(
            "#{:02} {:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={}",
            i + 1,
            k.src,
            k.src_port,
            k.dst,
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes
        );
    }
}
