## Code: `flow_analyzer.c`

```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <signal.h>
#include <netinet/if_ether.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#define HASH_SIZE 65536
#define MAX_FLOWS 1000000

typedef struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[HASH_SIZE];
static volatile sig_atomic_t stop = 0;

static void handle_sigint(int sig) {
    (void)sig;
    stop = 1;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = k->src_ip ^ k->dst_ip ^ ((uint32_t)k->src_port << 16) ^
                 k->dst_port ^ k->protocol;
    return h % HASH_SIZE;
}

static flow_entry_t *find_or_create_flow(const flow_key_t *key) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (memcmp(&e->key, key, sizeof(flow_key_t)) == 0) {
            return e;
        }
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) {
        perror("calloc");
        exit(1);
    }

    e->key = *key;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void print_flows(void) {
    printf("\n=== Flow summary ===\n");
    for (int i = 0; i < HASH_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            struct in_addr s, d;
            s.s_addr = e->key.src_ip;
            d.s_addr = e->key.dst_ip;

            printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu\n",
                   inet_ntoa(s),
                   ntohs(e->key.src_port),
                   inet_ntoa(d),
                   ntohs(e->key.dst_port),
                   e->key.protocol,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes);
            e = e->next;
        }
    }
}

static void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    if (h->caplen < sizeof(struct ether_header)) {
        return;
    }

    const struct ether_header *eth = (const struct ether_header *)bytes;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) {
        return;
    }

    const u_char *ip_ptr = bytes + sizeof(struct ether_header);
    if ((size_t)h->caplen < sizeof(struct ether_header) + sizeof(struct ip)) {
        return;
    }

    const struct ip *ip = (const struct ip *)ip_ptr;
    int ip_header_len = ip->ip_hl * 4;
    if (ip_header_len < 20) return;

    if ((size_t)h->caplen < sizeof(struct ether_header) + (size_t)ip_header_len) {
        return;
    }

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.protocol = ip->ip_p;

    const u_char *l4_ptr = ip_ptr + ip_header_len;

    if (ip->ip_p == IPPROTO_TCP) {
        if ((size_t)h->caplen < (size_t)(l4_ptr - bytes) + sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4_ptr;
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (ip->ip_p == IPPROTO_UDP) {
        if ((size_t)h->caplen < (size_t)(l4_ptr - bytes) + sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4_ptr;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    flow_entry_t *flow = find_or_create_flow(&key);
    flow->packets++;
    flow->bytes += h->len;
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *িফ = NULL;
    pcap_t *handle;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    const char *iface = argv[1];

    signal(SIGINT, handle_sigint);

    handle = pcap_open_live(iface, 65535, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }

    pcap_freecode(&fp);

    printf("Capturing on %s... press Ctrl-C to stop\n", iface);
    pcap_loop(handle, -1, packet_handler, NULL);

    pcap_close(handle);
    print_flows();
    return 0;
}
