## Code: `flow_analyzer.c`

```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <time.h>

#define FLOW_TABLE_SIZE 65536

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h ^= k->src_ip;   h *= 16777619u;
    h ^= k->dst_ip;   h *= 16777619u;
    h ^= k->src_port; h *= 16777619u;
    h ^= k->dst_port; h *= 16777619u;
    h ^= k->proto;    h *= 16777619u;
    return h % FLOW_TABLE_SIZE;
}

static int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static flow_entry_t *flow_get_or_create(const flow_key_t *key) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_key_equal(&e->key, key)) {
            return e;
        }
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->last_seen = time(NULL);
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void print_ip(uint32_t ip) {
    struct in_addr a;
    a.s_addr = ip;
    printf("%s", inet_ntoa(a));
}

static void handle_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *pkt) {
    (void)user;

    if (h->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)pkt;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ip_ptr = pkt + sizeof(struct ether_header);
    size_t ip_len = h->caplen - sizeof(struct ether_header);
    if (ip_len < sizeof(struct ip)) return;

    const struct ip *ip = (const struct ip *)ip_ptr;
    size_t ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < sizeof(struct ip) || ip_len < ip_hdr_len) return;

    flow_key_t key = {0};
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.proto = ip->ip_p;

    const u_char *l4_ptr = ip_ptr + ip_hdr_len;
    size_t l4_len = ip_len - ip_hdr_len;

    if (ip->ip_p == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4_ptr;
        key.src_port = ntohs(tcp->source);
        key.dst_port = ntohs(tcp->dest);
    } else if (ip->ip_p == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4_ptr;
        key.src_port = ntohs(udp->uh_sport);
        key.dst_port = ntohs(udp->uh_dport);
    } else {
        return;
    }

    flow_entry_t *e = flow_get_or_create(&key);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
    e->last_seen = time(NULL);
}

static void dump_flows(void) {
    printf("\n--- Flow table ---\n");
    for (int i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = flow_table[i];
        while (e) {
            print_ip(e->key.src_ip);
            printf(":%u -> ", e->key.src_port);
            print_ip(e->key.dst_ip);
            printf(":%u proto=%u packets=%llu bytes=%llu last_seen=%ld\n",
                   e->key.dst_port,
                   e->key.proto,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes,
                   (long)e->last_seen);
            e = e->next;
        }
    }
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *dev = NULL;

    if (argc > 1) {
        dev = argv[1];
    } else {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            fprintf(stderr, "No device found: %s\n", errbuf);
            return 1;
        }
    }

    pcap_t *handle = pcap_open_live(dev, 65535, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    printf("Listening on %s...\n", dev);

    while (1) {
        int rc = pcap_dispatch(handle, 1000, handle_packet, NULL);
        if (rc < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(handle));
            break;
        }
        dump_flows();
    }

    pcap_close(handle);
    return 0;
}
