```rust
use hashbrown::HashMap;
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::env;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Default, Debug)]
struct FlowStat {
    packets: u64,
    bytes: u64,
    last_seen: Instant,
}

fn main() {
    let iface_name = env::args().nth(1).expect("Usage: flow_analyzer <iface>");
    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == iface_name)
        .expect("Interface not found");

    let config = datalink::Config {
        read_timeout: Some(Duration::from_millis(10)),
        ..Default::default()
    };

    let (_, mut rx) = match datalink::channel(&interface, config) {
        Ok(Ethernet(_tx, rx)) => (_tx, rx),
        Ok(_) => panic!("Unhandled channel type"),
        Err(e) => panic!("Failed to open interface: {e}"),
    };

    let mut flows: HashMap<FlowKey, FlowStat> = HashMap::with_capacity(1 << 16);
    let mut last_print = Instant::now();

    loop {
        match rx.next() {
            Ok(frame) => {
                if let Some((key, len)) = parse_flow(frame) {
                    let entry = flows.entry(key).or_insert_with(|| FlowStat {
                        packets: 0,
                        bytes: 0,
                        last_seen: Instant::now(),
                    });
                    entry.packets += 1;
                    entry.bytes += len as u64;
                    entry.last_seen = Instant::now();
                }
            }
            Err(_) => {}
        }

        if last_print.elapsed() >= Duration::from_secs(5) {
            print_top_flows(&flows, 10);
            last_print = Instant::now();
            evict_stale_flows(&mut flows, Duration::from_secs(60));
        }
    }
}

fn parse_flow(frame: &[u8]) -> Option<(FlowKey, usize)> {
    let eth = EthernetPacket::new(frame)?;
    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ipv4 = Ipv4Packet::new(eth.payload())?;
            let proto = ipv4.get_next_level_protocol();
            let src_ip = ipv4.get_source();
            let dst_ip = ipv4.get_destination();

            match proto {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ipv4.payload())?;
                    Some((
                        FlowKey {
                            src_ip,
                            dst_ip,
                            src_port: tcp.get_source(),
                            dst_port: tcp.get_destination(),
                            proto: 6,
                        },
                        frame.len(),
                    ))
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ipv4.payload())?;
                    Some((
                        FlowKey {
                            src_ip,
                            dst_ip,
                            src_port: udp.get_source(),
                            dst_port: udp.get_destination(),
                            proto: 17,
                        },
                        frame.len(),
                    ))
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn print_top_flows(flows: &HashMap<FlowKey, FlowStat>, n: usize) {
    let mut top: Vec<_> = flows.iter().collect();
    top.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

    println!("=== Top {n} flows ===");
    for (i, (k, v)) in top.into_iter().take(n).enumerate() {
        println!(
            "#{:<2} {}:{} -> {}:{} proto={} packets={} bytes={}",
            i + 1,
            k.src_ip,
            k.src_port,
            k.dst_ip,
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes
        );
    }
}

fn evict_stale_flows(flows: &mut HashMap<FlowKey, FlowStat>, max_age: Duration) {
    let now = Instant::now();
    flows.retain(|_, stat| now.duration_since(stat.last_seen) <= max_age);
}
