## Example: minimal flow analyser in C

```c
// flow_analyzer.c
#define _GNU_SOURCE
#include <pcap/pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <netinet/if_ether.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define FLOW_TABLE_SIZE 1048576  // 1M entries, power of 2 for fast hashing
#define ETH_HDR_LEN 14

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    int used;
} flow_entry_t;

static flow_entry_t *flow_table;

static inline uint64_t hash_flow(const flow_key_t *k) {
    // Simple 64-bit mix
    uint64_t x = ((uint64_t)k->src_ip << 32) ^ k->dst_ip;
    x ^= ((uint64_t)k->src_port << 16) ^ k->dst_port;
    x ^= (uint64_t)k->proto;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline int key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static flow_entry_t *lookup_or_insert(const flow_key_t *k) {
    uint64_t idx = hash_flow(k) & (FLOW_TABLE_SIZE - 1);
    for (uint64_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flow_table[(idx + i) & (FLOW_TABLE_SIZE - 1)];

        if (!e->used) {
            e->used = 1;
            e->key = *k;
            e->packets = 0;
            e->bytes = 0;
            return e;
        }
        if (key_equal(&e->key, k)) {
            return e;
        }
    }
    return NULL; // table full
}

static void handle_packet(u_char *args, const struct pcap_pkthdr *hdr, const u_char *packet) {
    (void)args;

    if (hdr->caplen < ETH_HDR_LEN) return;

    const struct ether_header *eth = (const struct ether_header *)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const struct ip *ip = (const struct ip *)(packet + ETH_HDR_LEN);
    int ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < 20) return;

    if (hdr->caplen < ETH_HDR_LEN + (size_t)ip_hdr_len) return;

    flow_key_t k;
    memset(&k, 0, sizeof(k));
    k.src_ip = ip->ip_src.s_addr;
    k.dst_ip = ip->ip_dst.s_addr;
    k.proto = ip->ip_p;

    const u_char *l4 = packet + ETH_HDR_LEN + ip_hdr_len;

    if (k.proto == IPPROTO_TCP) {
        if (hdr->caplen < ETH_HDR_LEN + (size_t)ip_hdr_len + sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        k.src_port = ntohs(tcp->th_sport);
        k.dst_port = ntohs(tcp->th_dport);
    } else if (k.proto == IPPROTO_UDP) {
        if (hdr->caplen < ETH_HDR_LEN + (size_t)ip_hdr_len + sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        k.src_port = ntohs(udp->uh_sport);
        k.dst_port = ntohs(udp->uh_dport);
    } else {
        // Ignore non-TCP/UDP for this minimal example
        return;
    }

    flow_entry_t *e = lookup_or_insert(&k);
    if (!e) return;

    e->packets++;
    e->bytes += hdr->len;
}

static void print_stats(void) {
    uint64_t active = 0, total_packets = 0, total_bytes = 0;

    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        if (flow_table[i].used) {
            active++;
            total_packets += flow_table[i].packets;
            total_bytes += flow_table[i].bytes;
        }
    }

    printf("Active flows: %llu, packets: %llu, bytes: %llu\n",
           (unsigned long long)active,
           (unsigned long long)total_packets,
           (unsigned long long)total_bytes);
}

int main(int argc, char **argv) {
    const char *dev = (argc > 1) ? argv[1] : "eth0";
    char errbuf[PCAP_ERRBUF_SIZE];

    flow_table = calloc(FLOW_TABLE_SIZE, sizeof(flow_entry_t));
    if (!flow_table) {
        perror("calloc");
        return 1;
    }

    pcap_t *handle = pcap_open_live(dev, 65535, 1, 1, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live: %s\n", errbuf);
        free(flow_table);
        return 1;
    }

    // Capture only IP packets
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    printf("Capturing on %s...\n", dev);

    time_t last = time(NULL);
    while (1) {
        struct pcap_pkthdr *hdr;
        const u_char *packet;
        int rc = pcap_next_ex(handle, &hdr, &packet);
        if (rc == 1) {
            handle_packet(NULL, hdr, packet);
        } else if (rc == -1) {
            fprintf(stderr, "pcap_next_ex error: %s\n", pcap_geterr(handle));
            break;
        }

        time_t now = time(NULL);
        if (now - last >= 5) {
            print_stats();
            last = now;
        }
    }

    pcap_close(handle);
    free(flow_table);
    return 0;
}
