// -----------------------------------------------------------------------------
// Moving average filter
// -----------------------------------------------------------------------------
typedef struct {
    uint16_t samples[SAMPLE_WINDOW_SIZE];
    uint8_t index;
    uint32_t sum;
    bool filled;
} MovingAverageFilter;

void filter_init(MovingAverageFilter *f) {
    for (uint8_t i = 0; i < SAMPLE_WINDOW_SIZE; i++) {
        f->samples[i] = 0;
    }
    f->index = 0;
    f->sum = 0;
    f->filled = false;
}

uint16_t filter_add_sample(MovingAverageFilter *f, uint16_t sample) {
    f->sum -= f->samples[f->index];
    f->samples[f->index] = sample;
    f->sum += sample;

    f->index = (f->index + 1) % SAMPLE_WINDOW_SIZE;
    if (f->index == 0) {
        f->filled = true;
    }

    uint8_t divisor = f->filled ? SAMPLE_WINDOW_SIZE : f->index;
    if (divisor == 0) divisor = 1;

    return (uint16_t)(f->sum / divisor);
}

// -----------------------------------------------------------------------------
// Application logic
// -----------------------------------------------------------------------------
typedef enum {
    SENSOR_NORMAL = 0,
    SENSOR_HIGH,
    SENSOR_LOW
} SensorState;

SensorState evaluate_sensor(uint16_t value) {
    if (value > THRESHOLD_HIGH) {
        return SENSOR_HIGH;
    } else if (value < THRESHOLD_LOW) {
        return SENSOR_LOW;
    } else {
        return SENSOR_NORMAL;
    }
}

int main(void) {
    init_clock();
    init_gpio();
    init_adc();

    MovingAverageFilter sensor_filter;
    filter_init(&sensor_filter);

    log_event("Firmware started");

    while (1) {
        uint16_t raw = read_sensor_adc();
        uint16_t filtered = filter_add_sample(&sensor_filter, raw);
        SensorState state = evaluate_sensor(filtered);

        switch (state) {
            case SENSOR_HIGH:
                log_event("Sensor high");
                // Example: turn on warning LED, send alert, etc.
                break;

            case SENSOR_LOW:
                log_event("Sensor low");
                // Example: indicate low value, trigger calibration, etc.
                break;

            case SENSOR_NORMAL:
            default:
                // Normal operation
                break;
        }

        // Sample at 100 Hz
        delay_ms(10);
    }

    return 0;
}
