#define LOG_BUFFER_SIZE 128

/* =========================
 * Simple moving average filter
 * ========================= */

typedef struct {
    int32_t sum_x;
    int32_t sum_y;
    int32_t sum_z;
    int16_t samples[SAMPLE_COUNT][3];
    uint8_t index;
    uint8_t count;
} moving_average_t;

static void moving_average_init(moving_average_t *f)
{
    memset(f, 0, sizeof(*f));
}

static void moving_average_add(moving_average_t *f, int16_t x, int16_t y, int16_t z)
{
    if (f->count == SAMPLE_COUNT) {
        f->sum_x -= f->samples[f->index][0];
        f->sum_y -= f->samples[f->index][1];
        f->sum_z -= f->samples[f->index][2];
    } else {
        f->count++;
    }

    f->samples[f->index][0] = x;
    f->samples[f->index][1] = y;
    f->samples[f->index][2] = z;

    f->sum_x += x;
    f->sum_y += y;
    f->sum_z += z;

    f->index = (f->index + 1) % SAMPLE_COUNT;
}

static void moving_average_get(const moving_average_t *f, int16_t *x, int16_t *y, int16_t *z)
{
    if (f->count == 0) {
        *x = *y = *z = 0;
        return;
    }

    *x = (int16_t)(f->sum_x / f->count);
    *y = (int16_t)(f->sum_y / f->count);
    *z = (int16_t)(f->sum_z / f->count);
}

/* =========================
 * Sensor processing
 * ========================= */

static uint32_t calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    // Integer approximation: x^2 + y^2 + z^2
    // (avoid floating point to keep it lightweight)
    uint32_t ux = (uint32_t)(x * x);
    uint32_t uy = (uint32_t)(y * y);
    uint32_t uz = (uint32_t)(z * z);
    return ux + uy + uz;
}

static void format_sensor_message(char *buf, size_t len,
                                  int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                  int16_t filt_x, int16_t filt_y, int16_t filt_z,
                                  uint32_t magnitude)
{
    // snprintf may be heavy on some MCUs, but is fine for a first version
    // Replace with a lightweight formatter if needed
    (void)len;
    // NOTE: in production, use snprintf safely and ensure a proper implementation exists
    // Here we assume it's available
    extern int snprintf(char *str, size_t size, const char *format, ...);

    snprintf(buf, LOG_BUFFER_SIZE,
             "RAW: %d,%d,%d | FILT: %d,%d,%d | MAG2: %lu\r\n",
             raw_x, raw_y, raw_z,
             filt_x, filt_y, filt_z,
             (unsigned long)magnitude);
}

/* =========================
 * Main application
 * ========================= */

int main(void)
{
    char logbuf[LOG_BUFFER_SIZE];
    moving_average_t filter;
    int16_t raw_x, raw_y, raw_z;
    int16_t filt_x, filt_y, filt_z;
    uint32_t magnitude;

    platform_init();
    moving_average_init(&filter);

    platform_log("Firmware boot\r\n");

    if (!sensor_bus_init()) {
        platform_log("Sensor bus init failed\r\n");
        while (1) {
            platform_delay_ms(1000);
        }
    }

    platform_log("Sensor bus init OK\r\n");

    while (1) {
        if (sensor_read_raw(&raw_x, &raw_y, &raw_z)) {
            moving_average_add(&filter, raw_x, raw_y, raw_z);
            moving_average_get(&filter, &filt_x, &filt_y, &filt_z);

            magnitude = calculate_magnitude(filt_x, filt_y, filt_z);
            format_sensor_message(logbuf, sizeof(logbuf),
                                  raw_x, raw_y, raw_z,
                                  filt_x, filt_y, filt_z,
                                  magnitude);

            platform_log(logbuf);
        } else {
            platform_log("Sensor read failed\r\n");
        }

        platform_delay_ms(100);
    }
}
