    return std::max(minVal, std::min(value, maxVal));
}

// -----------------------------
// PID Controller
// -----------------------------
class PID {
public:
    PID(double kp, double ki, double kd, double outputMin, double outputMax)
        : kp_(kp), ki_(ki), kd_(kd),
          outputMin_(outputMin), outputMax_(outputMax) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;

        // Simple anti-windup
        integral_ = clamp(integral_, -integralLimit_, integralLimit_);

        double derivative = (dt > 0.0) ? (error - prevError_) / dt : 0.0;
        prevError_ = error;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        return clamp(output, outputMin_, outputMax_);
    }

    void reset() {
        integral_ = 0.0;
        prevError_ = 0.0;
    }

private:
    double kp_, ki_, kd_;
    double outputMin_, outputMax_;
    double integral_ = 0.0;
    double prevError_ = 0.0;
    double integralLimit_ = 100.0;
};

// -----------------------------
