// Fuses gyro + accel for angle estimate
// -----------------------------
class ComplementaryFilter {
public:
    explicit ComplementaryFilter(double alpha) : alpha_(alpha) {}

    double update(double gyroRate, double accelAngle, double dt) {
        // Predict with gyro, correct with accel
        angle_ = alpha_ * (angle_ + gyroRate * dt) + (1.0 - alpha_) * accelAngle;
        return angle_;
    }

    void setAngle(double angle) { angle_ = angle; }
    double getAngle() const { return angle_; }

private:
    double alpha_;   // e.g. 0.98
    double angle_ = 0.0;
};

