    constexpr double loopHz = 1000.0; // 1 kHz control loop
    constexpr auto loopPeriod = std::chrono::microseconds(1000); // 1 ms

    // Filter and controller
    ComplementaryFilter angleFilter(0.98);
    PID anglePID(
        /*kp=*/6.0,
        /*ki=*/1.5,
        /*kd=*/0.08,
        /*outputMin=*/-1.0,
        /*outputMax=*/1.0
    );

    // Desired angle / position
    double targetAngle = 0.0; // radians

    auto nextTick = clock::now();

    while (true) {
        auto loopStart = clock::now();

        // Compute dt
        static auto lastTime = loopStart;
        std::chrono::duration<double> elapsed = loopStart - lastTime;
        double dt = elapsed.count();
        lastTime = loopStart;

        if (dt <= 0.0 || dt > 0.1) {
            dt = 1.0 / loopHz; // fallback
        }

        // 1) Read sensors
        SensorData s = readSensors();

        // 2) Sensor fusion
        double fusedAngle = angleFilter.update(s.gyroRate, s.accelAngle, dt);

        // 3) Control law
        double motorCommand = anglePID.update(targetAngle, fusedAngle, dt);

        // 4) Motor output
        setMotorCommand(motorCommand);

        // Optional debug info
        std::cout << "dt=" << dt
                  << " fusedAngle=" << fusedAngle
                  << " encoderPos=" << s.encoderPos
                  << "\n";

        // 5) Maintain fixed loop rate
        nextTick += loopPeriod;
        std::this_thread::sleep_until(nextTick);
    }

    return 0;
}
