// -------------------------
// State estimation
// -------------------------
struct RobotState {
    double position = 0.0;
    double velocity = 0.0;
    double heading  = 0.0;
    double ang_vel  = 0.0;
};

class SensorFusion {
public:
    SensorFusion() = default;

    RobotState update(const SensorData& s, double dt) {
        // Complementary filter for heading:
        // integrate gyro, lightly correct with accelerometer-derived estimate
        double accel_heading_estimate = std::atan2(s.accel_x, 9.81); // simplistic placeholder

        state_.ang_vel = s.gyro_z;
        state_.heading = alpha_ * (state_.heading + s.gyro_z * dt)
                       + (1.0 - alpha_) * accel_heading_estimate;

        // Very simple encoder-based motion estimate
        state_.velocity = s.wheel_encoder;     // placeholder: assumes encoder gives velocity
        state_.position += state_.velocity * dt;

        return state_;
    }

private:
    RobotState state_;
    double alpha_ = 0.98;
};

// -------------------------
// Control
// -------------------------
struct ControlTarget {
    double desired_position = 0.0;
    double desired_heading  = 0.0;
};

class Controller {
public:
    MotorCommand compute(const RobotState& state, const ControlTarget& target, double dt) {
        // PD control for position and heading
        double pos_error = target.desired_position - state.position;
        double heading_error = target.desired_heading - state.heading;

        position_integral_ += pos_error * dt;
        heading_integral_  += heading_error * dt;

        double position_cmd = kp_pos_ * pos_error + kd_pos_ * (pos_error - prev_pos_error_) / dt;
        double heading_cmd  = kp_heading_ * heading_error + kd_heading_ * (heading_error - prev_heading_error_) / dt;

        prev_pos_error_ = pos_error;
        prev_heading_error_ = heading_error;

        // Differential drive mixing
        double left  = clamp(position_cmd - heading_cmd, -1.0, 1.0);
        double right = clamp(position_cmd + heading_cmd, -1.0, 1.0);

        return {left, right};
    }

private:
    static double clamp(double v, double lo, double hi) {
        return std::max(lo, std::min(v, hi));
    }

    double kp_pos_ = 1.2;
    double kd_pos_ = 0.10;

    double kp_heading_ = 2.0;
    double kd_heading_ = 0.05;

    double position_integral_ = 0.0;
    double heading_integral_ = 0.0;

    double prev_pos_error_ = 0.0;
    double prev_heading_error_ = 0.0;
};

