    const auto cycle = std::chrono::milliseconds(10); // 100 Hz loop

    auto next_tick = clock::now();

    std::cout << "Starting control loop...\n";

    for (int i = 0; i < 1000; ++i) {
        auto now = clock::now();
        double dt = std::chrono::duration<double>(cycle).count();

        // 1) Read sensors
        SensorData raw = sensors.read();

        // 2) Fuse sensor data into state estimate
        RobotState state = fusion.update(raw, dt);

        // 3) Compute motor command
        MotorCommand cmd = controller.compute(state, target, dt);

        // 4) Send command to motors
        motors.send(cmd);

        // Debug output
        std::cout << "State -> pos: " << state.position
                  << ", vel: " << state.velocity
                  << ", heading: " << state.heading << "\n";

        // Sleep until next cycle
        next_tick += cycle;
        std::this_thread::sleep_until(next_tick);
    }

