// -------------------------
// Simple sensor fusion
// -------------------------
class SensorFusion {
public:
    FusedState fuse(const IMUData& imu, const EncoderData& enc, const FusedState& prev, double dt) {
        FusedState state = prev;

        // Very simple integration / fusion placeholder
        double angular_velocity_z = imu.gyro_z;
        state.heading += angular_velocity_z * dt;

        double average_ticks = (enc.left_ticks + enc.right_ticks) * 0.5;
        state.velocity = average_ticks * 0.001; // arbitrary scale
        state.x += state.velocity * std::cos(state.heading) * dt;
        state.y += state.velocity * std::sin(state.heading) * dt;

        return state;
    }
};

