    void run(double loop_hz, double target_heading, double target_velocity, int iterations) {
        using namespace std::chrono;

        Duration loop_period(1.0 / loop_hz);

        TimePoint next_tick = Clock::now();

        for (int i = 0; i < iterations; ++i) {
            TimePoint start = Clock::now();

            // 1. Read sensors
            IMUData imu = imu_.read();
            EncoderData enc = enc_.read();

            // 2. Compute dt
            double dt = duration<double>(start - last_time_).count();
            if (last_time_ == TimePoint{}) {
                dt = 1.0 / loop_hz;
            }
            last_time_ = start;

            // 3. Fuse sensor data
            state_ = fusion_.fuse(imu, enc, state_, dt);

            // 4. Control law
            double heading_correction = pid_heading_.update(target_heading, state_.heading, dt);
            double velocity_correction = pid_velocity_.update(target_velocity, state_.velocity, dt);

            // Simple differential drive mapping
            double left_motor = velocity_correction - heading_correction;
            double right_motor = velocity_correction + heading_correction;

            // 5. Actuate motors
            motors_.setMotorSpeeds(left_motor, right_motor);

            // 6. Log state
            std::cout << "State -> x: " << state_.x
                      << " y: " << state_.y
                      << " heading: " << state_.heading
                      << " velocity: " << state_.velocity
                      << std::endl;

            // 7. Sleep until next tick
            next_tick += duration_cast<Clock::duration>(loop_period);
            std::this_thread::sleep_until(next_tick);
        }
    }

private:
    IMUSensor imu_;
    WheelEncoder enc_;
    SensorFusion fusion_;
    MotorController motors_;
    PIDController pid_heading_;
    PIDController pid_velocity_;
    FusedState state_;
    TimePoint last_time_{};
};

// -------------------------
// Main
// -------------------------
int main() {
    RobotControlLoop robot;

    // Run at 100 Hz, aiming for heading 0.0 rad and velocity 1.0 units
    robot.run(100.0, 0.0, 1.0, 200);

    return 0;
}
