class ComplementaryFilter {
public:
    explicit ComplementaryFilter(double alpha)
        : alpha_(alpha), angle_estimate_(0.0) {}

    double update(double accel_angle, double gyro_rate, double dt) {
        // Integrate gyro
        angle_estimate_ += gyro_rate * dt;

        // Blend with accel-based angle
        angle_estimate_ = alpha_ * angle_estimate_ + (1.0 - alpha_) * accel_angle;
        return angle_estimate_;
