public:
    PIDController(double kp, double ki, double kd, double output_min, double output_max)
        : kp_(kp), ki_(ki), kd_(kd),
          output_min_(output_min), output_max_(output_max),
          integral_(0.0), prev_error_(0.0), first_update_(true) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        integral_ += error * dt;

        double derivative = 0.0;
        if (!first_update_) {
            derivative = (error - prev_error_) / dt;
        } else {
            first_update_ = false;
        }

        prev_error_ = error;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;

        if (output > output_max_) output = output_max_;
        if (output < output_min_) output = output_min_;

        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
        first_update_ = true;
    }

private:
    double kp_, ki_, kd_;
    double output_min_, output_max_;
    double integral_;
    double prev_error_;
    bool first_update_;
};

