            // Sensor fusion
            double fused_heading = heading_filter_.update(
                raw.gyro_rate_z,
                raw.accel_angle_x,
                dt
            );

            // Simple state estimate
            estimate_.heading = fused_heading;
            estimate_.velocity = raw.wheel_encoder / std::max(dt, 1e-6);
            estimate_.position += estimate_.velocity * dt;

            // Control law
            double heading_correction = heading_pid_.update(target_heading, estimate_.heading, dt);
            double velocity_correction = velocity_pid_.update(target_velocity, estimate_.velocity, dt);

            // Differential drive mixing
            output_.left_motor  = clamp(velocity_correction - heading_correction, -1.0, 1.0);
            output_.right_motor = clamp(velocity_correction + heading_correction, -1.0, 1.0);

            // Apply outputs
            motor_.setPWM(output_.left_motor, output_.right_motor);

            // Basic diagnostics
            std::cout << "Heading: " << estimate_.heading
                      << " Velocity: " << estimate_.velocity
                      << " Position: " << estimate_.position << "\n";

            // Timing watchdog
            auto end = Clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
            if (elapsed > std::chrono::duration_cast<std::chrono::milliseconds>(loop_period)) {
                std::cerr << "[WARN] Control loop overrun: "
                          << elapsed.count() << " ms\n";
            }

            // Sleep until next tick
            next_tick += std::chrono::duration_cast<Clock::duration>(loop_period);
            std::this_thread::sleep_until(next_tick);
        }
    }

    void stop() { running_ = false; }

private:
    SensorInterface& sensor_;
    MotorInterface& motor_;
    ComplementaryFilter heading_filter_;
    PIDController heading_pid_;
    PIDController velocity_pid_;
    StateEstimate estimate_{};
    ControlOutput output_{};
    bool running_ = true;

    Clock::time_point last_time_;
    bool last_time_initialized_ = false;
};

int main() {
    MockSensor sensor;
    MockMotor motor;

    RoboticsController controller(sensor, motor);

    // Example: target heading = 0 rad, target velocity = 0.5 m/s, loop = 100 Hz
    controller.run(0.0, 0.5, 100.0);

    return 0;
}
```

