#include <chrono>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <thread>
#include <mutex>

// ============================
// Sensor data structures
// ============================
struct IMUReading {
    double accel_x;   // m/s^2
    double gyro_z;    // rad/s
    double timestamp; // seconds
};

struct EncoderReading {
    double position;  // radians
    double velocity;  // rad/s
    double timestamp; // seconds
};

struct FusedState {
    double angle;       // rad
    double angularVel;   // rad/s
    double timestamp;    // seconds
};

// ============================
// Simple PID controller
// ============================
class PIDController {
public:
    PIDController(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd), integral_(0.0), prevError_(0.0), firstRun_(true) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = 0.0;

        if (!firstRun_ && dt > 1e-9) {
            derivative = (error - prevError_) / dt;
        }

        prevError_ = error;
        firstRun_ = false;

        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

    void reset() {
        integral_ = 0.0;
        prevError_ = 0.0;
        firstRun_ = true;
    }

private:
    double kp_;
    double ki_;
    double kd_;
    double integral_;
    double prevError_;
    bool firstRun_;
};

// ============================
// Simple complementary/Kalman-like fusion
// ============================
// This is a simplified fusion model:
// - encoder provides position/velocity
// - gyro helps estimate angular velocity
// - accel is used as a weak correction source
class SensorFusion {
public:
    SensorFusion() : state_{0.0, 0.0, 0.0} {}

    FusedState update(const IMUReading& imu, const EncoderReading& enc, double dt) {
        // Predict
        double predictedAngle = state_.angle + imu.gyro_z * dt;
        double predictedVel = imu.gyro_z;

        // Encoder correction
        constexpr double alpha = 0.98; // mostly trust prediction/gyro
        double angleFromEncoder = enc.position;

        double fusedAngle = alpha * predictedAngle + (1.0 - alpha) * angleFromEncoder;

        // Blend velocity estimate from encoder and gyro
        constexpr double beta = 0.90;
        double fusedVel = beta * predictedVel + (1.0 - beta) * enc.velocity;

        // Very rough accel-based drift correction over time
        constexpr double accelGain = 0.01;
        fusedAngle += accelGain * imu.accel_x * dt * dt;

        state_.angle = fusedAngle;
        state_.angularVel = fusedVel;
        state_.timestamp = imu.timestamp;

        return state_;
    }

    FusedState getState() const {
        return state_;
    }

private:
    FusedState state_;
};

// ============================
// Motor interface abstraction
// ============================
class MotorDriver {
public:
    virtual ~MotorDriver() = default;
    virtual void setPWM(double command) = 0; // command in range [-1, 1]
};

// Dummy motor driver for testing
class ConsoleMotorDriver : public MotorDriver {
public:
    void setPWM(double command) override {
        if (command > 1.0) command = 1.0;
        if (command < -1.0) command = -1.0;
        std::cout << "[Motor] PWM command = " << command << std::endl;
    }
};

// ============================
// Mock sensor sources
// ============================
class MockSensors {
public:
    IMUReading readIMU(double t) {
        // Simulate motion with some noise
        IMUReading imu;
        imu.accel_x = 0.1 * std::sin(t) + noise(0.02);
        imu.gyro_z = 0.5 * std::cos(t) + noise(0.01);
        imu.timestamp = t;
        return imu;
    }

    EncoderReading readEncoder(double t) {
        EncoderReading enc;
        enc.position = 0.5 * std::sin(0.5 * t) + noise(0.005);
        enc.velocity = 0.25 * std::cos(0.5 * t) + noise(0.005);
        enc.timestamp = t;
        return enc;
    }

private:
    double noise(double amplitude) {
        // very simple pseudo-noise based on trig
        static double seed = 0.12345;
        seed += 0.01;
        return amplitude * std::sin(seed * 123.456);
    }
};

// ============================
// Main control loop
// ============================
int main() {
    using clock = std::chrono::steady_clock;

    SensorFusion fusion;
    PIDController pid(2.0, 0.5, 0.05);
    ConsoleMotorDriver motor;
    MockSensors sensors;

    const double targetAngle = 0.0; // desired angle (rad)
    const auto period = std::chrono::milliseconds(10); // 100 Hz loop

    auto nextTick = clock::now();
    auto start = clock::now();

    std::cout << "Starting robotics control loop...\n";

    for (int i = 0; i < 500; ++i) { // run for 5 seconds at 100 Hz
        nextTick += period;

        double t = std::chrono::duration<double>(clock::now() - start).count();
        double dt = 0.01; // nominal period; in real system measure actual dt

        // 1) Read sensors
        IMUReading imu = sensors.readIMU(t);
        EncoderReading enc = sensors.readEncoder(t);

        // 2) Fuse sensor data
        FusedState state = fusion.update(imu, enc, dt);

        // 3) Compute control command
        double control = pid.update(targetAngle, state.angle, dt);

        // 4) Apply motor command
        motor.setPWM(control / 10.0); // scale for example

        // 5) Debug output
        std::cout << "[t=" << t
                  << "] angle=" << state.angle
                  << " vel=" << state.angularVel
                  << " control=" << control
                  << std::endl;

        // 6) Sleep until next loop
        std::this_thread::sleep_until(nextTick);
    }

    std::cout << "Control loop finished.\n";
    return 0;
}
