static inline double clamp(double v, double lo, double hi) {
    return std::max(lo, std::min(v, hi));
}

// -----------------------------
// Sensor data
// -----------------------------
struct SensorData {
    double accel_angle_deg;   // e.g. from accelerometer
    double gyro_rate_dps;     // degrees per second
    double wheel_encoder_rps; // wheel rotational speed
};

// -----------------------------
// Fused state
// -----------------------------
struct FusedState {
    double angle_deg = 0.0;
    double angular_rate_dps = 0.0;
    double wheel_speed_rps = 0.0;
};

// -----------------------------
// Simple complementary filter
// -----------------------------
class SensorFusion {
public:
    explicit SensorFusion(double alpha = 0.98)
        : alpha_(alpha) {}

    FusedState update(const SensorData& s, double dt) {
        // Integrate gyro
        double gyro_angle = state_.angle_deg + s.gyro_rate_dps * dt;

        // Fuse accel + gyro
        state_.angle_deg = alpha_ * gyro_angle + (1.0 - alpha_) * s.accel_angle_deg;
        state_.angular_rate_dps = s.gyro_rate_dps;
        state_.wheel_speed_rps = s.wheel_encoder_rps;
        return state_;
    }

private:
    double alpha_;
    FusedState state_;
};

// -----------------------------
// PID controller
// -----------------------------
class PID {
public:
    PID(double kp, double ki, double kd, double out_min, double out_max)
        : kp_(kp), ki_(ki), kd_(kd), out_min_(out_min), out_max_(out_max) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        integral_ += error * dt;
        integral_ = clamp(integral_, -integral_limit_, integral_limit_);

        double derivative = (dt > 0.0) ? (error - prev_error_) / dt : 0.0;
        prev_error_ = error;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        return clamp(output, out_min_, out_max_);
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

    void setIntegralLimit(double limit) {
        integral_limit_ = std::abs(limit);
    }

private:
    double kp_, ki_, kd_;
    double out_min_, out_max_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
    double integral_limit_ = 1000.0;
};

// -----------------------------
// Motor command
// -----------------------------
struct MotorCommand {
    double pwm = 0.0; // -1.0 to +1.0
};

// -----------------------------
// Mock hardware interface
// Replace these with real drivers
// -----------------------------
class SensorInterface {
public:
    SensorData read() {
        // Placeholder sensor values
        // Replace with IMU + encoder reads
        sim_time_ += 0.01;

        SensorData s;
        s.accel_angle_deg = std::sin(sim_time_) * 5.0;     // fake tilt
        s.gyro_rate_dps = std::cos(sim_time_) * 5.0;       // fake angular velocity
        s.wheel_encoder_rps = 2.0 + 0.1 * std::sin(sim_time_);
        return s;
    }

private:
    double sim_time_ = 0.0;
};

class MotorInterface {
public:
    void write(const MotorCommand& cmd) {
        // Replace with PWM/ESC/motor driver output
        std::cout << "Motor PWM: " << cmd.pwm << "\n";
    }
};

// -----------------------------
// Main control loop
// -----------------------------
int main() {
    using clock = std::chrono::steady_clock;
    constexpr double loop_hz = 100.0;
    constexpr auto loop_period = std::chrono::duration<double>(1.0 / loop_hz);

    SensorInterface sensors;
    MotorInterface motors;
    SensorFusion fusion(0.98);

    // Example: control angle to 0 degrees
    PID angle_pid(0.05, 0.01, 0.002, -1.0, 1.0);
    angle_pid.setIntegralLimit(10.0);

    double target_angle_deg = 0.0;

    auto next_tick = clock::now();

    while (true) {
        auto start = clock::now();

        // Read sensors
        SensorData raw = sensors.read();

        // Compute dt
        static auto last_time = clock::now();
        auto now = clock::now();
        double dt = std::chrono::duration<double>(now - last_time).count();
        last_time = now;
        if (dt <= 0.0) dt = 1.0 / loop_hz;

        // Fuse
        FusedState state = fusion.update(raw, dt);

        // Control
        double motor_output = angle_pid.update(target_angle_deg, state.angle_deg, dt);

        // Map control output to motor command
        MotorCommand cmd;
        cmd.pwm = clamp(motor_output, -1.0, 1.0);

        // Actuate
        motors.write(cmd);

        // Debug
        std::cout << "Angle: " << state.angle_deg
                  << " deg, Gyro: " << state.angular_rate_dps
                  << " dps, Wheel: " << state.wheel_speed_rps
                  << " rps\n";

        // Maintain loop timing
        next_tick += std::chrono::duration_cast<clock::duration>(loop_period);
        std::this_thread::sleep_until(next_tick);
    }

    return 0;
}
