```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <random>

struct SensorData {
    double angle;
};

struct MotorCommand {
    double effort;
};

class SensorFusion {
public:
    // alpha near 1.0 trusts the fast sensor more; lower trusts the slow/stable sensor more
    double fuse(double fast_sensor, double slow_sensor) {
        const double alpha = 0.98;
        return alpha * fast_sensor + (1.0 - alpha) * slow_sensor;
    }
};

class PID {
public:
    PID(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd), prev_error_(0.0), integral_(0.0) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;
        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

private:
    double kp_, ki_, kd_;
    double prev_error_;
    double integral_;
};

class MotorController {
public:
    MotorCommand command(double control_effort) {
        // Clamp to a safe range
        if (control_effort > 1.0) control_effort = 1.0;
        if (control_effort < -1.0) control_effort = -1.0;
        return {control_effort};
    }
};

int main() {
    using clock = std::chrono::steady_clock;
    const auto loop_period = std::chrono::milliseconds(10); // 100 Hz
    const double setpoint = 1.0; // desired angle

    SensorFusion fusion;
    PID pid(2.0, 0.5, 0.1);
    MotorController motor;

    std::mt19937 rng(42);
    std::normal_distribution<double> noise_fast(0.0, 0.05);
    std::normal_distribution<double> noise_slow(0.0, 0.10);

    double true_angle = 0.0;
    double motor_effect = 0.0;

    auto next_tick = clock::now();

    while (true) {
        next_tick += loop_period;
        double dt = std::chrono::duration<double>(loop_period).count();

        // Simulated plant dynamics
        true_angle += motor_effect * dt;

        // Simulated sensors with noise
        double fast_sensor = true_angle + noise_fast(rng);
        double slow_sensor = true_angle + noise_slow(rng);

        // Sensor fusion
        double fused_angle = fusion.fuse(fast_sensor, slow_sensor);

        // Control
        double effort = pid.update(setpoint, fused_angle, dt);
        MotorCommand cmd = motor.command(effort);

        // Apply motor command
        motor_effect = cmd.effort;

        std::cout << "true=" << true_angle
                  << " fast=" << fast_sensor
                  << " slow=" << slow_sensor
                  << " fused=" << fused_angle
                  << " motor=" << cmd.effort
                  << std::endl;

        std::this_thread::sleep_until(next_tick);
    }

    return 0;
}
