    PID pid(2.0, 0.5, 0.1);
    Motor motor;

    double setpoint_angle = 0.0; // target angle
    auto next_time = clock::now();

    for (int i = 0; i < 500; ++i) {
        auto now = clock::now();
        double t = i * dt;

        // 1) Read sensors
        SensorData sensors = readSensors(t, dt);

        // 2) Sensor fusion
        double estimated_angle = fusion.update(sensors);

        // 3) Control law
        double control = pid.update(setpoint_angle, estimated_angle, dt);

        // 4) Output to motor
        motor.setCommand(control);

        std::cout << "t=" << t
                  << " fused_angle=" << estimated_angle
                  << " control=" << control
                  << std::endl;

        // 5) Maintain loop timing
        next_time += std::chrono::duration_cast<clock::duration>(loop_period);
        std::this_thread::sleep_until(next_time);
    }

    return 0;
}
```

### What this demonstrates
- **Sensor fusion**: complementary filter blending accel and gyro.
- **Control**: PID feedback to drive toward a target angle.
- **Real-time-style loop**: fixed-period execution with `sleep_until`.

