#include <chrono>
#include <cmath>
#include <iostream>
#include <thread>

// -------------------- Utilities --------------------

using Clock = std::chrono::steady_clock;
using ms = std::chrono::milliseconds;
using ns = std::chrono::nanoseconds;

double clamp(double x, double lo, double hi) {
    return (x < lo) ? lo : (x > hi) ? hi : x;
}

// -------------------- Simulated Sensors --------------------

struct SensorData {
    double accel_angle_deg;   // from accelerometer
    double gyro_rate_dps;     // degrees per second from gyroscope
    double encoder_pos;       // motor position feedback
};

SensorData read_sensors(double t_sec) {
    // Simulated motion + noise-free example
    SensorData s{};
    s.accel_angle_deg = 5.0 * std::sin(t_sec);      // pretend tilt angle
    s.gyro_rate_dps   = 5.0 * std::cos(t_sec);      // derivative of angle
    s.encoder_pos     = 100.0 * std::sin(0.5*t_sec); // arbitrary position feedback
    return s;
}

// -------------------- Sensor Fusion --------------------

class ComplementaryFilter {
public:
    explicit ComplementaryFilter(double alpha) : alpha_(alpha) {}

    double update(double accel_angle_deg, double gyro_rate_dps, double dt_sec) {
        // Integrate gyro, combine with accelerometer angle
        fused_angle_deg_ =
            alpha_ * (fused_angle_deg_ + gyro_rate_dps * dt_sec) +
            (1.0 - alpha_) * accel_angle_deg;
        return fused_angle_deg_;
    }

private:
    double alpha_;
    double fused_angle_deg_ = 0.0;
};

// -------------------- PID Controller --------------------

class PID {
public:
    PID(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd) {}

    double update(double setpoint, double measurement, double dt_sec) {
        double error = setpoint - measurement;
        integral_ += error * dt_sec;
        double derivative = (dt_sec > 0.0) ? (error - prev_error_) / dt_sec : 0.0;
        prev_error_ = error;

        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

private:
    double kp_, ki_, kd_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
};

// -------------------- Motor Driver (Mock) --------------------

void set_motor_pwm(double pwm) {
    // In real hardware this would write to a PWM register / motor driver
    std::cout << "Motor PWM command: " << pwm << '\n';
}

// -------------------- Main Control Loop --------------------

int main() {
    constexpr double control_hz = 100.0;
    constexpr double dt_sec = 1.0 / control_hz;
    constexpr auto loop_period = std::chrono::duration_cast<Clock::duration>(
        std::chrono::duration<double>(dt_sec)
    );

    ComplementaryFilter filter(0.98);
    PID pid(2.0, 0.1, 0.01);

    const double target_angle_deg = 0.0; // keep upright / level

    auto next_tick = Clock::now();

    for (int i = 0; i < 500; ++i) {
        auto now = Clock::now();
        double t_sec = std::chrono::duration<double>(now.time_since_epoch()).count();

        // 1) Read sensors
        SensorData s = read_sensors(t_sec);

        // 2) Fuse sensor data
        double fused_angle = filter.update(s.accel_angle_deg, s.gyro_rate_dps, dt_sec);

        // 3) Compute control effort
        double control = pid.update(target_angle_deg, fused_angle, dt_sec);

        // 4) Convert to motor command
        double pwm = clamp(control, -255.0, 255.0);

        // 5) Apply to motor
        set_motor_pwm(pwm);

        // 6) Debug output
        std::cout << "t=" << t_sec
                  << " accel=" << s.accel_angle_deg
                  << " gyro=" << s.gyro_rate_dps
                  << " fused=" << fused_angle
                  << " pwm=" << pwm
                  << '\n';

        // 7) Maintain control period
        next_tick += loop_period;
        std::this_thread::sleep_until(next_tick);
    }

    return 0;
}
