```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

using namespace std::chrono;

// ---------------------- PID Controller ----------------------
class PID {
public:
    PID(double kp, double ki, double kd)
        : kp(kp), ki(ki), kd(kd), integral(0.0), prev_error(0.0) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return kp * error + ki * integral + kd * derivative;
    }

private:
    double kp, ki, kd;
    double integral;
    double prev_error;
};

// ---------------------- Simple Sensor Fusion ----------------------
// Complementary filter for angle estimation
class ComplementaryFilter {
public:
    ComplementaryFilter(double alpha) : alpha(alpha), angle_estimate(0.0) {}

    double update(double gyro_rate, double accel_angle, double dt) {
        angle_estimate = alpha * (angle_estimate + gyro_rate * dt)
                       + (1.0 - alpha) * accel_angle;
        return angle_estimate;
    }

private:
    double alpha;
    double angle_estimate;
};

// ---------------------- Simulated Plant ----------------------
// Simple 1D motor + load model
class SimulatedRobot {
public:
    SimulatedRobot() : angle(0.0), angular_velocity(0.0) {}

    void applyMotorCommand(double command, double dt) {
        command = std::clamp(command, -1.0, 1.0);

        // Very simple dynamics:
        // torque ~ command, damping opposes motion
        double torque = 5.0 * command;
        double damping = 0.8 * angular_velocity;

        double angular_acceleration = torque - damping;
        angular_velocity += angular_acceleration * dt;
        angle += angular_velocity * dt;
    }

    double getTrueAngle() const { return angle; }
    double getTrueAngularVelocity() const { return angular_velocity; }

private:
    double angle;
    double angular_velocity;
};

// ---------------------- Main Control Loop ----------------------
int main() {
    PID pid(2.0, 0.1, 0.05);
    ComplementaryFilter filter(0.98);
    SimulatedRobot robot;

    const double target_angle = 1.0; // radians
    const double dt = 0.01;          // 100 Hz

    auto last = steady_clock::now();

    for (int i = 0; i < 1000; ++i) {
        // --- Simulate sensor readings with some simple noise-free measurements ---
        double true_angle = robot.getTrueAngle();
        double true_gyro = robot.getTrueAngularVelocity();

        // In a real robot, accel_angle would come from accelerometer / IMU
        // Here we approximate it with the true angle
        double accel_angle = true_angle;
        double gyro_rate = true_gyro;

        // --- Sensor fusion ---
        double fused_angle = filter.update(gyro_rate, accel_angle, dt);

        // --- Motor control ---
        double control_signal = pid.update(target_angle, fused_angle, dt);

        // Convert PID output to motor command
        double motor_command = std::clamp(control_signal / 10.0, -1.0, 1.0);

        robot.applyMotorCommand(motor_command, dt);

        // --- Logging ---
        std::cout << "Step " << i
                  << " | Target: " << target_angle
                  << " | Fused angle: " << fused_angle
                  << " | Motor cmd: " << motor_command
                  << std::endl;

        // --- Timing control ---
        auto now = steady_clock::now();
        auto elapsed = duration<double>(now - last).count();
        if (elapsed < dt) {
            std::this_thread::sleep_for(duration<double>(dt - elapsed));
        }
        last = steady_clock::now();
    }

    return 0;
}
```

### What this does
- **Complementary filter** combines gyro integration and angle measurement
- **PID** drives the robot toward a target angle
- **SimulatedRobot** is a toy motor/load model so the loop has something to control
- Loop runs at roughly **100 Hz**

