// -------------------- Simple PID Controller --------------------
class PID {
public:
    PID(double kp, double ki, double kd)
        : kp_(kp), ki_(ki), kd_(kd), prev_error_(0.0), integral_(0.0) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral_ += error * dt;
        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;
        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

private:
    double kp_, ki_, kd_;
    double prev_error_;
    double integral_;
};

// -------------------- Simulated Sensors --------------------
struct SensorData {
    double accel_angle;   // from accelerometer
    double gyro_rate;     // from gyroscope
    double encoder_pos;   // from motor encoder
};

class SimulatedSensors {
public:
    SensorData read() {
        // Very simple fake sensor values for demo purposes
        t_ += dt_;

        SensorData s;
        s.accel_angle = 10.0 * std::sin(t_);      // degrees
        s.gyro_rate   = 10.0 * std::cos(t_);      // deg/s
        s.encoder_pos = motor_position_;
        return s;
    }

    void set_motor_position(double pos) {
        motor_position_ = pos;
    }

private:
    double t_ = 0.0;
    double dt_ = 0.01;
    double motor_position_ = 0.0;
};

// -------------------- Simulated Motor --------------------
class Motor {
public:
    void set_command(double cmd) {
        // Clamp command to [-100, 100]
        if (cmd > 100.0) cmd = 100.0;
        if (cmd < -100.0) cmd = -100.0;
        command_ = cmd;
    }

    double command() const { return command_; }

    void update_physics(double dt) {
        // Very simple fake motor dynamics
        velocity_ = command_ * 0.1;
        position_ += velocity_ * dt;
    }

    double position() const { return position_; }

private:
    double command_ = 0.0;
    double velocity_ = 0.0;
    double position_ = 0.0;
};

// -------------------- Complementary Filter --------------------
class ComplementaryFilter {
public:
    double update(double accel_angle, double gyro_rate, double dt) {
        // Estimate angle from gyro integration + accel correction
        angle_ = alpha_ * (angle_ + gyro_rate * dt) + (1.0 - alpha_) * accel_angle;
        return angle_;
    }

private:
    double angle_ = 0.0;
    double alpha_ = 0.98;
};

// -------------------- Main Control Loop --------------------
int main() {
    using clock = std::chrono::steady_clock;
    const double dt = 0.01; // 10 ms control loop
    const auto loop_period = std::chrono::duration<double>(dt);

    SimulatedSensors sensors;
    Motor motor;
    ComplementaryFilter fusion;
    PID pid(5.0, 0.5, 0.1);

    const double target_angle = 0.0; // degrees

    auto next_tick = clock::now();

    for (int i = 0; i < 500; ++i) { // run for 5 seconds
        next_tick += std::chrono::duration_cast<clock::duration>(loop_period);

        // 1) Read sensors
        sensors.set_motor_position(motor.position());
        SensorData data = sensors.read();

        // 2) Sensor fusion
        double fused_angle = fusion.update(data.accel_angle, data.gyro_rate, dt);

        // 3) Control law
        double control = pid.update(target_angle, fused_angle, dt);

        // 4) Actuate motor
        motor.set_command(control);
        motor.update_physics(dt);

        // 5) Log
        std::cout << "Angle: " << fused_angle
                  << " deg, Motor cmd: " << motor.command()
                  << ", Motor pos: " << motor.position()
                  << std::endl;

        // 6) Sleep until next tick
        std::this_thread::sleep_until(next_tick);
    }

    return 0;
}
