```rust
// Embedded-style accelerometer anomaly detection pipeline.
// Designed to be simple, deterministic, and easy to adapt to no_std.
//
// Features:
// - 3-axis low-pass filter
// - Magnitude calculation
// - Rolling window mean/variance baseline
// - Z-score-like anomaly detection
//
// To adapt for no_std:
// - remove std import and any alloc usage
// - replace Vec/heap with fixed-size buffers (already done here)
//
// NOTE: This is a reference implementation; tune parameters for your sensor.

#![allow(dead_code)]

use core::f32::consts::SQRT_2;

#[derive(Debug, Clone, Copy)]
pub struct AccelSample {
    pub x: f32,
    pub y: f32,
    pub z: f32,
    pub timestamp_ms: u64,
}

#[derive(Debug, Clone, Copy)]
pub struct ProcessedSample {
    pub filtered_x: f32,
    pub filtered_y: f32,
    pub filtered_z: f32,
    pub magnitude: f32,
    pub is_anomaly: bool,
    pub score: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct LowPassFilter {
    alpha: f32,
    x: f32,
    y: f32,
    z: f32,
    initialized: bool,
}

impl LowPassFilter {
    pub fn new(alpha: f32) -> Self {
        Self {
            alpha,
            x: 0.0,
            y: 0.0,
            z: 0.0,
            initialized: false,
        }
    }

    pub fn apply(&mut self, sample: AccelSample) -> (f32, f32, f32) {
        if !self.initialized {
            self.x = sample.x;
            self.y = sample.y;
            self.z = sample.z;
            self.initialized = true;
            return (self.x, self.y, self.z);
        }

        self.x = self.alpha * sample.x + (1.0 - self.alpha) * self.x;
        self.y = self.alpha * sample.y + (1.0 - self.alpha) * self.y;
        self.z = self.alpha * sample.z + (1.0 - self.alpha) * self.z;

        (self.x, self.y, self.z)
    }
}

pub struct RollingStats<const N: usize> {
    buffer: [f32; N],
    count: usize,
    index: usize,
    sum: f32,
    sum_sq: f32,
}

impl<const N: usize> RollingStats<N> {
    pub const fn new() -> Self {
        Self {
            buffer: [0.0; N],
            count: 0,
            index: 0,
            sum: 0.0,
            sum_sq: 0.0,
        }
    }

    pub fn update(&mut self, value: f32) {
        if self.count < N {
            self.buffer[self.index] = value;
            self.sum += value;
            self.sum_sq += value * value;
            self.count += 1;
            self.index = (self.index + 1) % N;
        } else {
            let old = self.buffer[self.index];
            self.sum -= old;
            self.sum_sq -= old * old;

            self.buffer[self.index] = value;
            self.sum += value;
            self.sum_sq += value * value;

            self.index = (self.index + 1) % N;
        }
    }

    pub fn mean(&self) -> f32 {
        if self.count == 0 {
            0.0
        } else {
            self.sum / self.count as f32
        }
    }

    pub fn variance(&self) -> f32 {
        if self.count < 2 {
            0.0
        } else {
            let n = self.count as f32;
            let mean = self.mean();
            let var = (self.sum_sq / n) - (mean * mean);
            var.max(0.0)
        }
    }

    pub fn std_dev(&self) -> f32 {
        self.variance().sqrt()
    }

    pub fn is_ready(&self) -> bool {
        self.count >= N
    }
}

pub struct AnomalyDetector<const N: usize> {
    stats: RollingStats<N>,
    threshold_z: f32,
    min_std_dev: f32,
}

impl<const N: usize> AnomalyDetector<N> {
    pub fn new(threshold_z: f32, min_std_dev: f32) -> Self {
        Self {
            stats: RollingStats::new(),
            threshold_z,
            min_std_dev,
        }
    }

    pub fn observe(&mut self, value: f32) -> (bool, f32) {
        let mean = self.stats.mean();
        let std = self.stats.std_dev().max(self.min_std_dev);

        // Avoid flagging during warm-up
        let score = if self.stats.is_ready() {
            (value - mean).abs() / std
        } else {
            0.0
        };

        let is_anomaly = self.stats.is_ready() && score > self.threshold_z;

        self.stats.update(value);

        (is_anomaly, score)
    }
}

pub struct SensorPipeline<const N: usize> {
    lp_filter: LowPassFilter,
    detector: AnomalyDetector<N>,
}

impl<const N: usize> SensorPipeline<N> {
    pub fn new(alpha: f32, threshold_z: f32, min_std_dev: f32) -> Self {
        Self {
            lp_filter: LowPassFilter::new(alpha),
            detector: AnomalyDetector::new(threshold_z, min_std_dev),
        }
    }

    pub fn process(&mut self, sample: AccelSample) -> ProcessedSample {
        let (fx, fy, fz) = self.lp_filter.apply(sample);

        // Magnitude of filtered acceleration
        let magnitude = (fx * fx + fy * fy + fz * fz).sqrt();

        let (is_anomaly, score) = self.detector.observe(magnitude);

        ProcessedSample {
            filtered_x: fx,
            filtered_y: fy,
            filtered_z: fz,
            magnitude,
            is_anomaly,
            score,
        }
    }
}

// Example usage
fn main() {
    // Window size for rolling baseline
    const WINDOW: usize = 32;

    // alpha closer to 1.0 = less smoothing, closer to 0.0 = more smoothing
    let mut pipeline = SensorPipeline::<WINDOW>::new(
        0.2,  // low-pass alpha
        3.0,  // anomaly threshold in std devs
        0.0001, // minimum std dev to avoid divide-by-zero
    );

    // Simulated accelerometer stream
    let samples = [
        AccelSample { x: 0.01, y: 0.02, z: 1.00, timestamp_ms: 0 },
        AccelSample { x: 0.02, y: 0.01, z: 0.98, timestamp_ms: 10 },
        AccelSample { x: 0.03, y: 0.02, z: 1.01, timestamp_ms: 20 },
        AccelSample { x: 0.02, y: 0.02, z: 1.00, timestamp_ms: 30 },
        AccelSample { x: 2.50, y: 1.80, z: 3.00, timestamp_ms: 40 }, // anomaly
        AccelSample { x: 0.02, y: 0.01, z: 0.99, timestamp_ms: 50 },
    ];

    for s in samples {
        let out = pipeline.process(s);
        if out.is_anomaly {
            println!(
                "ANOMALY detected at {} ms | magnitude={:.3} score={:.2}",
                s.timestamp_ms, out.magnitude, out.score
            );
        } else {
            println!(
                "ok at {} ms | magnitude={:.3} score={:.2}",
                s.timestamp_ms, out.magnitude, out.score
            );
        }
    }
}
