#define WINDOW_SIZE 32
#define ANOMALY_Z_THRESHOLD 3.5f
#define MIN_VARIANCE_EPS 1e-6f

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} AccelSample;

typedef struct {
    AccelSample buffer[WINDOW_SIZE];
    uint8_t count;
    uint8_t index;
} RingBuffer;

typedef struct {
    RingBuffer samples;
    float mean_magnitude;
    float variance_magnitude;
} SensorPipeline;

typedef struct {
    bool is_anomaly;
    float magnitude;
    float z_score;
} AnomalyResult;

static float accel_magnitude(const AccelSample *s) {
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static void ringbuffer_init(RingBuffer *rb) {
    rb->count = 0;
    rb->index = 0;
}

static void ringbuffer_push(RingBuffer *rb, AccelSample sample) {
    rb->buffer[rb->index] = sample;
    rb->index = (uint8_t)((rb->index + 1) % WINDOW_SIZE);
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static void pipeline_init(SensorPipeline *p) {
    ringbuffer_init(&p->samples);
    p->mean_magnitude = 0.0f;
    p->variance_magnitude = 0.0f;
}

static void compute_stats(const RingBuffer *rb, float *mean_out, float *var_out) {
    if (rb->count == 0) {
        *mean_out = 0.0f;
        *var_out = 0.0f;
        return;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (uint8_t i = 0; i < rb->count; i++) {
        float mag = accel_magnitude(&rb->buffer[i]);
        sum += mag;
        sum_sq += mag * mag;
    }

    float mean = sum / (float)rb->count;
    float var = (sum_sq / (float)rb->count) - (mean * mean);

    if (var < 0.0f) {
        var = 0.0f;
    }

    *mean_out = mean;
    *var_out = var;
}

static AnomalyResult pipeline_process_sample(SensorPipeline *p, AccelSample sample) {
    AnomalyResult result = { false, 0.0f, 0.0f };

    float mag = accel_magnitude(&sample);

    // Update history first
    ringbuffer_push(&p->samples, sample);

    // Need enough data to make a meaningful decision
    if (p->samples.count < 8) {
        p->mean_magnitude = mag;
        p->variance_magnitude = 0.0f;
        result.magnitude = mag;
        return result;
    }

    compute_stats(&p->samples, &p->mean_magnitude, &p->variance_magnitude);

    float stddev = sqrtf(p->variance_magnitude + MIN_VARIANCE_EPS);
    float z = (mag - p->mean_magnitude) / stddev;

    result.magnitude = mag;
    result.z_score = z;
    result.is_anomaly = (fabsf(z) > ANOMALY_Z_THRESHOLD);

    return result;
}

/*
 * Example usage:
 * Call this every time a new accelerometer sample is available.
 */
void on_new_accel_sample(float x, float y, float z, uint32_t timestamp_ms) {
    static SensorPipeline pipeline;
    static bool initialized = false;

    if (!initialized) {
        pipeline_init(&pipeline);
        initialized = true;
    }

    AccelSample sample = { x, y, z, timestamp_ms };
    AnomalyResult r = pipeline_process_sample(&pipeline, sample);

    if (r.is_anomaly) {
        // Handle anomaly: log, raise interrupt flag, send telemetry, etc.
        // Example placeholder:
        // alert_anomaly(r.magnitude, r.z_score, timestamp_ms);
    }
}
```

