Below is a compact **C++ embedded-style pipeline** for accelerometer anomaly detection. It includes:

- sample ingestion
- simple high-pass detrending
- sliding-window feature extraction
- anomaly scoring using z-score against a rolling baseline
- a callback hook for alarm handling

You can adapt it for RTOS/MCU environments by replacing the standard library containers with fixed-size arrays if needed.

```cpp
#include <cmath>
#include <cstdint>
#include <array>
#include <iostream>
#include <functional>

struct AccelerometerSample {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
};

struct Features {
    float mean_mag;
    float std_mag;
    float peak_mag;
};

class HighPassFilter {
public:
    explicit HighPassFilter(float alpha = 0.95f)
        : alpha_(alpha), prev_input_{0, 0, 0}, prev_output_{0, 0, 0}, initialized_(false) {}

    AccelerometerSample process(const AccelerometerSample& s) {
        if (!initialized_) {
            prev_input_ = {s.x, s.y, s.z};
            prev_output_ = {0, 0, 0};
            initialized_ = true;
            return {0, 0, 0, s.timestamp_ms};
        }

        AccelerometerSample out;
        out.x = alpha_ * (prev_output_.x + s.x - prev_input_.x);
        out.y = alpha_ * (prev_output_.y + s.y - prev_input_.y);
        out.z = alpha_ * (prev_output_.z + s.z - prev_input_.z);
        out.timestamp_ms = s.timestamp_ms;

        prev_input_ = {s.x, s.y, s.z};
        prev_output_ = {out.x, out.y, out.z};
        return out;
    }

private:
    float alpha_;
    AccelerometerSample prev_input_;
    AccelerometerSample prev_output_;
    bool initialized_;
};

class SlidingWindowFeatures {
public:
    static constexpr size_t WINDOW_SIZE = 32;

    SlidingWindowFeatures() : index_(0), filled_(0) {
        mags_.fill(0.0f);
    }

    void add(const AccelerometerSample& s) {
        float mag = std::sqrt(s.x * s.x + s.y * s.y + s.z * s.z);
        mags_[index_] = mag;
        index_ = (index_ + 1) % WINDOW_SIZE;
        if (filled_ < WINDOW_SIZE) {
            ++filled_;
        }
    }

    bool ready() const {
        return filled_ == WINDOW_SIZE;
    }

    Features compute() const {
        Features f{0, 0, 0};
        if (!ready()) return f;

        float sum = 0.0f;
        float maxv = mags_[0];
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            sum += mags_[i];
            if (mags_[i] > maxv) maxv = mags_[i];
        }

        float mean = sum / WINDOW_SIZE;
        float var = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            float d = mags_[i] - mean;
            var += d * d;
        }
        var /= WINDOW_SIZE;

        f.mean_mag = mean;
        f.std_mag = std::sqrt(var);
        f.peak_mag = maxv;
        return f;
    }

private:
    std::array<float, WINDOW_SIZE> mags_;
    size_t index_;
    size_t filled_;
};

class RollingBaseline {
public:
    static constexpr size_t BASELINE_SIZE = 64;

    RollingBaseline() : index_(0), filled_(0) {
        values_.fill(0.0f);
    }

    void add(float value) {
        values_[index_] = value;
        index_ = (index_ + 1) % BASELINE_SIZE;
        if (filled_ < BASELINE_SIZE) {
            ++filled_;
        }
    }

    bool ready() const {
        return filled_ == BASELINE_SIZE;
    }

    float mean() const {
        float sum = 0.0f;
        for (size_t i = 0; i < filled_; ++i) sum += values_[i];
        return (filled_ > 0) ? sum / filled_ : 0.0f;
    }

    float stddev() const {
        if (filled_ < 2) return 0.0f;
        float m = mean();
        float var = 0.0f;
        for (size_t i = 0; i < filled_; ++i) {
            float d = values_[i] - m;
            var += d * d;
        }
        var /= filled_;
        return std::sqrt(var);
    }

private:
    std::array<float, BASELINE_SIZE> values_;
    size_t index_;
    size_t filled_;
};

class AnomalyDetector {
public:
    using AlarmCallback = std::function<void(const Features&, float score)>;

    explicit AnomalyDetector(float z_threshold = 3.0f)
        : z_threshold_(z_threshold) {}

    bool evaluate(const Features& f) {
        // Use peak magnitude as the primary anomaly signal here.
        float signal = f.peak_mag;

        if (!baseline_.ready()) {
            baseline_.add(signal);
            return false;
        }

        float mu = baseline_.mean();
        float sigma = baseline_.stddev();
        float score = 0.0f;

        if (sigma > 1e-6f) {
            score = (signal - mu) / sigma;
        }

        baseline_.add(signal);

        if (score > z_threshold_ || f.std_mag > 2.0f * mu) {
            if (callback_) callback_(f, score);
            return true;
        }

        return false;
    }

    void setCallback(AlarmCallback cb) {
        callback_ = cb;
    }

private:
    float z_threshold_;
    RollingBaseline baseline_;
    AlarmCallback callback_;
};

class SensorPipeline {
public:
    void ingest(const AccelerometerSample& raw) {
        auto filtered = hpf_.process(raw);
        window_.add(filtered);

        if (window_.ready()) {
            Features f = window_.compute();
            detector_.evaluate(f);
        }
    }

    void onAnomaly(AnomalyDetector::AlarmCallback cb) {
        detector_.setCallback(cb);
    }

private:
    HighPassFilter hpf_{0.95f};
    SlidingWindowFeatures window_;
    AnomalyDetector detector_{3.0f};
};

int main() {
    SensorPipeline pipeline;

    pipeline.onAnomaly([](const Features& f, float score) {
        std::cout << "ANOMALY DETECTED\n";
        std::cout << "mean_mag=" << f.mean_mag
                  << " std_mag=" << f.std_mag
                  << " peak_mag=" << f.peak_mag
                  << " score=" << score << "\n";
    });

    // Example stream: mostly normal, then anomaly spike
    for (uint32_t t = 0; t < 200; ++t) {
        AccelerometerSample s;
        s.timestamp_ms = t * 10;

        if (t < 150) {
            s.x = 0.02f * std::sin(t * 0.1f);
            s.y = 0.01f * std::cos(t * 0.1f);
            s.z = 1.0f + 0.02f * std::sin(t * 0.05f);
        } else {
            s.x = 2.5f;
            s.y = 1.8f;
            s.z = 3.2f;
        }

        pipeline.ingest(s);
    }

    return 0;
}
