Here’s a compact embedded-friendly **C** example for an accelerometer anomaly-detection pipeline. It:

- reads 3-axis samples
- applies a simple low-pass filter
- computes signal magnitude
- tracks a rolling mean and variance
- flags anomalies when magnitude deviates significantly

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stdio.h>

#define WINDOW_SIZE 32
#define ANOMALY_THRESHOLD 3.0f   // z-score threshold
#define ALPHA 0.1f               // low-pass filter coefficient

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;
    float window[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sumsq;
} SensorPipeline;

void pipeline_init(SensorPipeline *p) {
    p->filtered_x = 0.0f;
    p->filtered_y = 0.0f;
    p->filtered_z = 0.0f;
    p->index = 0;
    p->count = 0;
    p->sum = 0.0f;
    p->sumsq = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->window[i] = 0.0f;
    }
}

static float low_pass(float prev, float current, float alpha) {
    return alpha * current + (1.0f - alpha) * prev;
}

static float magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

static void rolling_stats_add(SensorPipeline *p, float value) {
    if (p->count < WINDOW_SIZE) {
        p->window[p->index] = value;
        p->sum += value;
        p->sumsq += value * value;
        p->count++;
    } else {
        float old = p->window[p->index];
        p->window[p->index] = value;
        p->sum += value - old;
        p->sumsq += value * value - old * old;
    }

    p->index = (p->index + 1) % WINDOW_SIZE;
}

static void rolling_stats_get(const SensorPipeline *p, float *mean, float *stddev) {
    if (p->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = p->sum / p->count;
    float var = (p->sumsq / p->count) - (*mean * *mean);
    if (var < 0.0f) var = 0.0f;
    *stddev = sqrtf(var);
}

bool pipeline_process(SensorPipeline *p, const AccelSample *raw, float *out_score) {
    // 1) Low-pass filter each axis
    p->filtered_x = low_pass(p->filtered_x, raw->x, ALPHA);
    p->filtered_y = low_pass(p->filtered_y, raw->y, ALPHA);
    p->filtered_z = low_pass(p->filtered_z, raw->z, ALPHA);

    AccelSample filtered = { p->filtered_x, p->filtered_y, p->filtered_z };

    // 2) Compute derived feature
    float mag = magnitude(&filtered);

    // 3) Update rolling baseline
    float mean, stddev;
    rolling_stats_get(p, &mean, &stddev);

    // Z-score anomaly score
    float score = 0.0f;
    if (stddev > 1e-6f) {
        score = (mag - mean) / stddev;
    }

    // 4) Add current value to history after scoring
    rolling_stats_add(p, mag);

    if (out_score) {
        *out_score = score;
    }

    return fabsf(score) > ANOMALY_THRESHOLD;
}

int main(void) {
    SensorPipeline pipeline;
    pipeline_init(&pipeline);

    // Example input stream
    AccelSample samples[] = {
        {0.02f, 0.01f, 1.00f},
        {0.03f, 0.00f, 0.99f},
        {0.01f, 0.02f, 1.01f},
        {0.02f, 0.01f, 1.00f},
        {2.50f, 2.00f, 3.20f},  // anomaly
        {0.02f, 0.01f, 1.00f},
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float score;
        bool anomaly = pipeline_process(&pipeline, &samples[i], &score);

        printf("Sample %d: score=%.3f anomaly=%s\n",
               i, score, anomaly ? "YES" : "NO");
    }

    return 0;
}
