    float alpha;              // Baseline smoothing factor [0..1]
    float threshold;          // Deviation threshold
    uint8_t min_anomaly_count; // Consecutive samples required to trigger anomaly

    float baseline_mag;       // Smoothed magnitude baseline
    uint8_t anomaly_count;    // Current consecutive anomaly counter
    uint8_t anomaly_active;   // Output flag
} anomaly_detector_t;

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

void anomaly_detector_init(anomaly_detector_t *detector,
                           float alpha,
                           float threshold,
                           uint8_t min_anomaly_count);

uint8_t anomaly_detector_process(anomaly_detector_t *detector,
                                 const accel_sample_t *sample,
                                 float *out_magnitude,
                                 float *out_deviation);

#ifdef __cplusplus
}
#endif

