## `anomaly_detector.c`

```c
#include "anomaly_detector.h"
#include <math.h>

static float vector_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

void anomaly_detector_init(anomaly_detector_t *detector,
                           float alpha,
                           float threshold,
                           uint8_t min_anomaly_count)
{
    if (!detector) return;

    detector->alpha = alpha;
    detector->threshold = threshold;
    detector->min_anomaly_count = min_anomaly_count;

    detector->baseline_mag = 0.0f;
    detector->anomaly_count = 0;
    detector->anomaly_active = 0;
}

uint8_t anomaly_detector_process(anomaly_detector_t *detector,
                                 const accel_sample_t *sample,
                                 float *out_magnitude,
                                 float *out_deviation)
{
    if (!detector || !sample) return 0;

    float mag = vector_magnitude(sample);

    // Initialize baseline on first sample
    if (detector->baseline_mag == 0.0f) {
        detector->baseline_mag = mag;
    } else {
        // Exponential moving average baseline
        detector->baseline_mag =
            detector->alpha * mag + (1.0f - detector->alpha) * detector->baseline_mag;
    }

    float deviation = fabsf(mag - detector->baseline_mag);

    if (out_magnitude) {
        *out_magnitude = mag;
    }

    if (out_deviation) {
        *out_deviation = deviation;
    }

    if (deviation > detector->threshold) {
        if (detector->anomaly_count < 255) {
            detector->anomaly_count++;
        }
    } else {
        detector->anomaly_count = 0;
    }

    detector->anomaly_active = (detector->anomaly_count >= detector->min_anomaly_count) ? 1 : 0;

    return detector->anomaly_active;
}
