## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef LPF_ALPHA
#define LPF_ALPHA 0.2f
#endif

#ifndef ANOMALY_Z_THRESHOLD
#define ANOMALY_Z_THRESHOLD 3.0f
#endif

#ifndef MIN_VARIANCE
#define MIN_VARIANCE 1e-6f
#endif

/* =========================
 * Types
 * ========================= */

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float lpf_value;
    bool initialized;
} lowpass_filter_t;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sumsq;
} rolling_stats_t;

typedef struct {
    lowpass_filter_t filter;
    rolling_stats_t stats;
    uint32_t anomaly_count;
} anomaly_detector_t;

/* =========================
 * Low-pass filter
 * ========================= */

static float lowpass_update(lowpass_filter_t *f, float input) {
    if (!f->initialized) {
        f->lpf_value = input;
        f->initialized = true;
        return input;
    }

    f->lpf_value = LPF_ALPHA * input + (1.0f - LPF_ALPHA) * f->lpf_value;
    return f->lpf_value;
}

/* =========================
 * Rolling statistics
 * ========================= */

static void rolling_stats_init(rolling_stats_t *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        s->buffer[i] = 0.0f;
    }
}

static void rolling_stats_push(rolling_stats_t *s, float value) {
    if (s->count < WINDOW_SIZE) {
        s->buffer[s->index] = value;
        s->sum += value;
        s->sumsq += value * value;
        s->count++;
        s->index = (s->index + 1) % WINDOW_SIZE;
    } else {
        float old = s->buffer[s->index];
        s->buffer[s->index] = value;

        s->sum += value - old;
        s->sumsq += (value * value) - (old * old);

        s->index = (s->index + 1) % WINDOW_SIZE;
    }
}

static void rolling_stats_get(const rolling_stats_t *s, float *mean, float *variance) {
    if (s->count == 0) {
        *mean = 0.0f;
        *variance = 0.0f;
        return;
    }

    *mean = s->sum / (float)s->count;

    float raw_var = (s->sumsq / (float)s->count) - (*mean * *mean);
    *variance = (raw_var > MIN_VARIANCE) ? raw_var : MIN_VARIANCE;
}

/* =========================
 * Detector
 * ========================= */

static float accel_magnitude(const accel_sample_t *sample) {
    return sqrtf(sample->x * sample->x +
                 sample->y * sample->y +
                 sample->z * sample->z);
}

void anomaly_detector_init(anomaly_detector_t *d) {
    d->filter.initialized = false;
    d->filter.lpf_value = 0.0f;
    rolling_stats_init(&d->stats);
    d->anomaly_count = 0;
}

/*
 * Returns true if anomaly detected.
 * The detector uses:
 *  - magnitude of acceleration
 *  - low-pass smoothing
 *  - rolling mean/std over recent samples
 */
bool anomaly_detector_process(anomaly_detector_t *d, const accel_sample_t *sample) {
    float mag = accel_magnitude(sample);
    float filtered = lowpass_update(&d->filter, mag);

    float mean, variance;
    rolling_stats_get(&d->stats, &mean, &variance);

    float stddev = sqrtf(variance);
    float z_score = (filtered - mean) / stddev;
    if (z_score < 0.0f) {
        z_score = -z_score;
    }

    bool anomaly = false;

    /* Warm-up period: collect baseline before evaluating */
    if (d->stats.count >= WINDOW_SIZE / 2) {
        if (z_score > ANOMALY_Z_THRESHOLD) {
            anomaly = true;
            d->anomaly_count++;
        }
    }

    rolling_stats_push(&d->stats, filtered);

    return anomaly;
}
```

