Below is a solid **initial embedded implementation** in **C** for an accelerometer anomaly-detection pipeline. It is designed to be:

- **small**
- **deterministic**
- **easy to port to MCUs**
- **streaming-friendly**
- **usable as a starting point**

It uses a simple but effective approach:

1. Read accelerometer samples `(ax, ay, az)`
2. Compute magnitude
3. Smooth with a moving average
4. Track baseline and variance with EWMA
5. Flag anomalies when the current signal deviates too far from baseline

---

## 1) Pipeline overview

**Data flow:**

`accelerometer sample -> magnitude -> moving average -> adaptive baseline -> anomaly score -> event flag`

### Detection logic
An anomaly is detected if:

- the filtered magnitude deviates from the baseline by more than a threshold, and/or
- variance spikes above a threshold

This is intentionally lightweight for embedded use.

---

## 2) C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration parameters
 * ========================= */
#define WINDOW_SIZE         8
#define ALPHA_BASELINE       0.02f   // EWMA baseline update rate
#define ALPHA_VARIANCE       0.02f   // EWMA variance update rate
#define ANOMALY_THRESHOLD    3.0f    // threshold in standard deviations
#define MIN_VARIANCE         1e-6f   // prevent divide-by-zero

/* =========================
 * Data structures
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float window[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} moving_average_t;

typedef struct {
    float baseline;
    float variance;
    bool initialized;
} anomaly_model_t;

typedef struct {
    moving_average_t ma;
    anomaly_model_t model;
} anomaly_pipeline_t;

/* =========================
 * Moving average
 * ========================= */
static void moving_average_init(moving_average_t *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        ma->window[i] = 0.0f;
    }
}

static float moving_average_update(moving_average_t *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->window[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->window[ma->index];
        ma->window[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / (float)ma->count;
}

/* =========================
 * Anomaly model
 * ========================= */
static void anomaly_model_init(anomaly_model_t *m) {
    m->baseline = 0.0f;
    m->variance = 1.0f;
    m->initialized = false;
}

static void anomaly_model_update(anomaly_model_t *m, float value) {
    if (!m->initialized) {
        m->baseline = value;
        m->variance = 1.0f;
        m->initialized = true;
        return;
    }

    float diff = value - m->baseline;

    // EWMA baseline
    m->baseline += ALPHA_BASELINE * diff;

    // EWMA variance estimate
    float residual = value - m->baseline;
    m->variance = (1.0f - ALPHA_VARIANCE) * m->variance +
                  ALPHA_VARIANCE * (residual * residual);

    if (m->variance < MIN_VARIANCE) {
        m->variance = MIN_VARIANCE;
    }
}

/* =========================
 * Pipeline functions
 * ========================= */
void anomaly_pipeline_init(anomaly_pipeline_t *p) {
    moving_average_init(&p->ma);
    anomaly_model_init(&p->model);
}

static float accel_magnitude(const accel_sample_t *s) {
    // For embedded targets without FPU, consider using an approximation.
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/*
 * Returns true if anomaly detected.
 * Provides anomaly score via out_score if non-NULL.
 */
bool anomaly_pipeline_process(anomaly_pipeline_t *p,
                              const accel_sample_t *sample,
                              float *out_score) {
    float mag = accel_magnitude(sample);
    float filtered = moving_average_update(&p->ma, mag);

    anomaly_model_update(&p->model, filtered);

    float stddev = sqrtf(p->model.variance);
    float deviation = fabsf(filtered - p->model.baseline);
    float score = deviation / stddev;

    if (out_score) {
        *out_score = score;
    }

    return (score > ANOMALY_THRESHOLD);
}
```

