Below is a solid **initial embedded implementation** in **C** for an accelerometer anomaly-detection pipeline. It is designed to be:

- lightweight,
- streaming-friendly,
- suitable for MCU use,
- easy to adapt to real hardware.

It does the following:
1. reads accelerometer samples,
2. computes a simple magnitude-based signal,
3. smooths it with an exponential moving average,
4. estimates a baseline and variance,
5. flags anomalies when the signal deviates too much.

You can replace the `read_accel_sample()` stub with your sensor driver.

---

## Initial C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define SAMPLE_RATE_HZ      100
#define EMA_ALPHA           0.05f
#define BASELINE_ALPHA      0.01f
#define VAR_ALPHA           0.01f
#define ANOMALY_THRESHOLD_Z 3.0f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float filtered_mag;
    float baseline;
    float variance;
    bool initialized;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

void anomaly_detector_init(anomaly_detector_t *detector) {
    detector->filtered_mag = 0.0f;
    detector->baseline = 0.0f;
    detector->variance = 1.0f;
    detector->initialized = false;
}

bool anomaly_detector_process(anomaly_detector_t *detector,
                              const accel_sample_t *sample,
                              bool *is_anomaly,
                              float *z_score_out)
{
    float mag = accel_magnitude(sample);

    if (!detector->initialized) {
        detector->filtered_mag = mag;
        detector->baseline = mag;
        detector->variance = 1.0f;
        detector->initialized = true;
        *is_anomaly = false;
        *z_score_out = 0.0f;
        return true;
    }

    // Smooth input
    detector->filtered_mag = (EMA_ALPHA * mag) +
                             ((1.0f - EMA_ALPHA) * detector->filtered_mag);

    // Update baseline
    float diff = detector->filtered_mag - detector->baseline;
    detector->baseline += BASELINE_ALPHA * diff;

    // Update variance (EWMA of squared error)
    float error = detector->filtered_mag - detector->baseline;
    float error_sq = error * error;
    detector->variance += VAR_ALPHA * (error_sq - detector->variance);

    // Avoid divide-by-zero
    float stddev = fast_sqrtf(detector->variance);
    if (stddev < 1e-6f) {
        stddev = 1e-6f;
    }

    float z_score = error / stddev;

    *z_score_out = z_score;
    *is_anomaly = (fabsf(z_score) >= ANOMALY_THRESHOLD_Z);

    return true;
}
```

