Below is a minimal embedded-style anomaly detector for accelerometer data in <language>C</language>. It uses:

- a rolling mean over the latest samples
- a simple magnitude-based anomaly score
- a threshold to flag anomalies

This is intentionally small and suitable as a starting point for an MCU pipeline.

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.5f

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    AccelSample window[WINDOW_SIZE];
    int count;
    int index;
} RollingBuffer;

static void buffer_init(RollingBuffer *buf) {
    buf->count = 0;
    buf->index = 0;
}

static void buffer_add(RollingBuffer *buf, AccelSample sample) {
    buf->window[buf->index] = sample;
    buf->index = (buf->index + 1) % WINDOW_SIZE;
    if (buf->count < WINDOW_SIZE) {
        buf->count++;
    }
}

static AccelSample buffer_mean(const RollingBuffer *buf) {
    AccelSample mean = {0.0f, 0.0f, 0.0f};

    for (int i = 0; i < buf->count; i++) {
        mean.x += buf->window[i].x;
        mean.y += buf->window[i].y;
        mean.z += buf->window[i].z;
    }

    if (buf->count > 0) {
        mean.x /= buf->count;
        mean.y /= buf->count;
        mean.z /= buf->count;
    }

    return mean;
}

static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static bool detect_anomaly(const RollingBuffer *buf, AccelSample current) {
    if (buf->count < WINDOW_SIZE) {
        return false; // wait until buffer is full
    }

    AccelSample mean = buffer_mean(buf);

    float current_mag = magnitude(current);
    float mean_mag = magnitude(mean);

    float deviation = fabsf(current_mag - mean_mag);

    return deviation > ANOMALY_THRESHOLD;
}

int main(void) {
    RollingBuffer buf;
    buffer_init(&buf);

    // Example accelerometer readings (x, y, z)
    AccelSample samples[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.00f},
        {0.02f, 0.01f, 0.98f},
        {0.01f, 0.00f, 1.02f},
        {0.00f, 0.02f, 1.00f},
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.00f, 1.00f},
        {0.02f, 0.01f, 1.01f},
        {0.01f, 0.02f, 0.99f},
        {0.00f, 0.01f, 1.00f},
        {0.01f, 0.00f, 1.00f},
        {0.02f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.01f},
        {2.50f, 1.80f, 3.20f}, // anomaly
        {0.01f, 0.01f, 1.00f}
    };

    int n = (int)(sizeof(samples) / sizeof(samples[0]));

    for (int i = 0; i < n; i++) {
        bool anomaly = detect_anomaly(&buf, samples[i]);

        buffer_add(&buf, samples[i]);

        printf("Sample %2d: (%.2f, %.2f, %.2f) -> %s\n",
               i,
               samples[i].x, samples[i].y, samples[i].z,
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

### How it works
- Samples are stored in a fixed-size ring buffer.
- Once the buffer is full, each new reading is compared to the recent average.
- If the magnitude changes too much, the sample is flagged as anomalous.

