#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 8
#define THRESHOLD 1.5f   // Tune based on your sensor and use case

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} MovingAverage;

void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

float ma_update(MovingAverage *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->buffer[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
        ma->buffer[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / (float)ma->count;
}

float accel_magnitude(float x, float y, float z) {
    return sqrtf(x*x + y*y + z*z);
}

bool is_anomaly(MovingAverage *ma, float magnitude) {
    float avg = ma_update(ma, magnitude);
    float diff = fabsf(magnitude - avg);
    return (ma->count >= WINDOW_SIZE) && (diff > THRESHOLD);
}

