        {0.00f, 0.01f, 1.00f},
        {2.00f, 2.00f, 2.00f},   // anomaly
        {0.01f, 0.02f, 1.00f}
    };

    MovingAverage ma;
    ma_init(&ma);

    int sample_count = sizeof(samples) / sizeof(samples[0]);
    for (int i = 0; i < sample_count; i++) {
        float x = samples[i][0];
        float y = samples[i][1];
