#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD  1.5f   // tune per sensor/noise profile

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float window[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} moving_avg_t;

static void moving_avg_init(moving_avg_t *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->window[i] = 0.0f;
    }
}

static float moving_avg_update(moving_avg_t *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->window[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->window[ma->index];
        ma->window[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / (float)ma->count;
}

static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

typedef struct {
    moving_avg_t baseline;
} anomaly_detector_t;

static void anomaly_detector_init(anomaly_detector_t *det) {
    moving_avg_init(&det->baseline);
}

static bool anomaly_detector_update(anomaly_detector_t *det, const accel_sample_t *sample) {
    float mag = accel_magnitude(sample);
    float avg = moving_avg_update(&det->baseline, mag);

    float deviation = fabsf(mag - avg);

    return (det->baseline.count >= WINDOW_SIZE) && (deviation > ANOMALY_THRESHOLD);
}
