        /* anomaly */
        {3.50f, 0.50f, 0.20f},
        {0.02f, 0.01f, 1.00f}
    };

    float window[WINDOW_SIZE] = {0};
    int idx = 0;
    int count = 0;

    for (int i = 0; i < (int)(sizeof(samples) / sizeof(samples[0])); i++) {
        float m = mag(samples[i]);

        // Compute baseline as moving average of previous samples
        float sum = 0.0f;
        for (int j = 0; j < count; j++) {
            sum += window[j];
        }
        float baseline = (count > 0) ? (sum / count) : m;

        float deviation = fabsf(m - baseline);
        bool anomaly = (count >= WINDOW_SIZE / 2) && (deviation > ANOMALY_THRESHOLD);

        printf("sample=%d mag=%.3f baseline=%.3f dev=%.3f %s\n",
               i, m, baseline, deviation, anomaly ? "ANOMALY" : "normal");

        // Update circular buffer
        window[idx] = m;
        idx = (idx + 1) % WINDOW_SIZE;
        if (count < WINDOW_SIZE) count++;
    }

    return 0;
}
