## Minimal working pipeline

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float alpha;   // smoothing factor for EMA
} BaselineEstimator;

typedef struct {
    float threshold;   // anomaly threshold in standard deviations
} AnomalyDetector;

static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static void baseline_init(BaselineEstimator *b, float alpha) {
    b->mean = 0.0f;
    b->variance = 0.0f;
    b->alpha = alpha;
}

static void baseline_update(BaselineEstimator *b, float value) {
    float delta = value - b->mean;
    b->mean += b->alpha * delta;
    b->variance = (1.0f - b->alpha) * (b->variance + b->alpha * delta * delta);
}

static bool detect_anomaly(const BaselineEstimator *b, const AnomalyDetector *d, float value) {
    float stddev = sqrtf(b->variance + 1e-6f);
    float z = fabsf(value - b->mean) / stddev;
    return z > d->threshold;
}

int main(void) {
    BaselineEstimator baseline;
    AnomalyDetector detector = { .threshold = 3.0f };

    baseline_init(&baseline, 0.05f);

    // Simulated accelerometer stream
    AccelSample samples[] = {
        {0.02f, 0.01f, 0.98f},
        {0.03f, 0.00f, 1.00f},
        {0.01f, 0.02f, 0.99f},
        {0.00f, 0.01f, 1.01f},
        {0.04f, 0.03f, 0.97f},
        {1.50f, 1.20f, 2.10f}, // anomaly
        {0.02f, 0.01f, 0.99f},
        {0.00f, 0.02f, 1.00f}
    };

    size_t n = sizeof(samples) / sizeof(samples[0]);

    for (size_t i = 0; i < n; i++) {
        float mag = magnitude(samples[i]);

        bool is_anomaly = detect_anomaly(&baseline, &detector, mag);

        printf("sample %zu: mag=%.3f %s\n",
               i, mag, is_anomaly ? "ANOMALY" : "normal");

        baseline_update(&baseline, mag);
    }

    return 0;
}
```

