    float alpha;
    float state;
    int initialized;
} LowPassFilter;

float filter_update(LowPassFilter *f, float input) {
    if (!f->initialized) {
        f->state = input;
        f->initialized = 1;
    } else {
        f->state = f->alpha * input + (1.0f - f->alpha) * f->state;
    }
    return f->state;
}

/* Simulated sensor read */
float read_sensor(void) {
    /* Replace with ADC/I2C/SPI read in real hardware */
    return (float)(rand() % 100);
}

/* Simulated actuator control */
void set_actuator(int on) {
    if (on) {
        printf("ACTUATOR ON\n");
    } else {
        printf("ACTUATOR OFF\n");
    }
}

int main(void) {
    LowPassFilter filter = {
        .alpha = 0.2f,
        .state = 0.0f,
        .initialized = 0
    };

    const float threshold = 50.0f;

    for (int i = 0; i < 20; i++) {
        float raw = read_sensor();
        float filtered = filter_update(&filter, raw);

        printf("raw=%.2f filtered=%.2f\n", raw, filtered);

        if (filtered > threshold) {
            set_actuator(1);
        } else {
            set_actuator(0);
        }
    }

    return 0;
}
```

