#include <stdio.h>
#include <stdint.h>

#define WINDOW_SIZE 4
#define ACTUATOR_ON_THRESHOLD  70
#define ACTUATOR_OFF_THRESHOLD 60

static int16_t samples[WINDOW_SIZE];
static uint8_t sample_index = 0;
static uint8_t sample_count = 0;
static int actuator_state = 0; // 0 = off, 1 = on

// Simulated sensor read
int16_t read_sensor(void) {
    static int16_t mock_values[] = {55, 58, 62, 66, 72, 75, 68, 64, 59, 57};
    static uint8_t i = 0;
    int16_t value = mock_values[i % (sizeof(mock_values) / sizeof(mock_values[0]))];
    i++;
    return value;
}

// Simple moving average filter
int16_t filtered_sensor_value(int16_t new_value) {
    samples[sample_index] = new_value;
    sample_index = (sample_index + 1) % WINDOW_SIZE;

    if (sample_count < WINDOW_SIZE) {
        sample_count++;
    }

    int32_t sum = 0;
    for (uint8_t i = 0; i < sample_count; i++) {
        sum += samples[i];
    }

    return (int16_t)(sum / sample_count);
}

// Actuator control with hysteresis
void update_actuator(int16_t filtered_value) {
    if (actuator_state == 0 && filtered_value >= ACTUATOR_ON_THRESHOLD) {
        actuator_state = 1;
        printf("Actuator ON (filtered=%d)\n", filtered_value);
    } else if (actuator_state == 1 && filtered_value <= ACTUATOR_OFF_THRESHOLD) {
        actuator_state = 0;
        printf("Actuator OFF (filtered=%d)\n", filtered_value);
    } else {
        printf("Actuator unchanged (%s, filtered=%d)\n",
               actuator_state ? "ON" : "OFF",
               filtered_value);
    }
}

int main(void) {
    for (int i = 0; i < 20; i++) {
        int16_t raw = read_sensor();
        int16_t filtered = filtered_sensor_value(raw);

        printf("Raw=%d, Filtered=%d -> ", raw, filtered);
        update_actuator(filtered);
    }

    return 0;
}
```

