    }
  </style>
</head>
<body>
  <div class="info">
    Controls: ← → to move, Space to jump
  </div>
  <canvas id="game" width="800" height="450"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const GRAVITY = 0.6;
    const FRICTION = 0.8;
    const MOVE_SPEED = 4;
    const JUMP_FORCE = -12;

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft" || e.key === "a") keys.left = true;
      if (e.key === "ArrowRight" || e.key === "d") keys.right = true;
      if (e.key === " " || e.key === "ArrowUp" || e.key === "w") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.key === "ArrowLeft" || e.key === "a") keys.left = false;
      if (e.key === "ArrowRight" || e.key === "d") keys.right = false;
      if (e.key === " " || e.key === "ArrowUp" || e.key === "w") keys.jump = false;
    });

    class Platform {
      constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
      }

      draw() {
        ctx.fillStyle = "#5b3a1e";
        ctx.fillRect(this.x, this.y, this.width, this.height);
        ctx.fillStyle = "#7c4f2a";
        ctx.fillRect(this.x, this.y, this.width, 8);
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 32;
        this.height = 48;
        this.vx = 0;
        this.vy = 0;
        this.onGround = false;
        this.facingRight = true;

        // Simple sprite animation frames (color-based)
        this.animFrame = 0;
        this.animTimer = 0;
        this.state = "idle"; // idle, run, jump
      }

      update() {
        // Horizontal movement
        if (keys.left) {
          this.vx = -MOVE_SPEED;
          this.facingRight = false;
          this.state = "run";
        } else if (keys.right) {
          this.vx = MOVE_SPEED;
          this.facingRight = true;
          this.state = "run";
        } else {
          this.vx *= FRICTION;
          if (Math.abs(this.vx) < 0.1) this.vx = 0;
          if (this.onGround) this.state = "idle";
        }

        // Jump
        if (keys.jump && this.onGround) {
          this.vy = JUMP_FORCE;
          this.onGround = false;
          this.state = "jump";
        }

        // Gravity
        this.vy += GRAVITY;

        // Apply movement
        this.x += this.vx;
        this.y += this.vy;

        // Screen bounds
        if (this.x < 0) this.x = 0;
        if (this.x + this.width > canvas.width) this.x = canvas.width - this.width;

        // Platform collisions
        this.onGround = false;
        for (const p of platforms) {
          if (
            this.x < p.x + p.width &&
            this.x + this.width > p.x &&
            this.y < p.y + p.height &&
            this.y + this.height > p.y
          ) {
            const prevBottom = this.y - this.vy + this.height;
            const prevTop = this.y - this.vy;

            // Landing on top
            if (prevBottom <= p.y + 8 && this.vy >= 0) {
              this.y = p.y - this.height;
              this.vy = 0;
              this.onGround = true;
              if (Math.abs(this.vx) > 0) this.state = "run";
              else this.state = "idle";
            }
            // Hitting from below
            else if (prevTop >= p.y + p.height - 8 && this.vy < 0) {
              this.y = p.y + p.height;
              this.vy = 0;
            }
          }
        }

        // Fall reset
        if (this.y > canvas.height + 100) {
          this.x = 100;
          this.y = 100;
          this.vx = 0;
          this.vy = 0;
        }

        // Animation update
        this.animTimer++;
        if (this.animTimer >= 10) {
          this.animFrame = (this.animFrame + 1) % 4;
          this.animTimer = 0;
        }
      }

      draw() {
        ctx.save();
        ctx.translate(this.x + this.width / 2, this.y + this.height / 2);
        if (!this.facingRight) ctx.scale(-1, 1);

        // Body colors per animation frame/state
        const colors = {
          idle: ["#ffcc66", "#ffd27f", "#ffcc66", "#ffd27f"],
          run: ["#66ccff", "#4db8ff", "#66ccff", "#4db8ff"],
          jump: ["#ff6666", "#ff8080", "#ff6666", "#ff8080"]
        };

        const color = colors[this.state][this.animFrame];

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.15)";
        ctx.beginPath();
        ctx.ellipse(0, this.height / 2 - 2, 14, 5, 0, 0, Math.PI * 2);
        ctx.fill();

        // Head
        ctx.fillStyle = color;
        ctx.fillRect(-10, -18, 20, 18);

        // Body
        ctx.fillRect(-12, 0, 24, 16);

        // Legs
        ctx.fillStyle = "#333";
        const legOffset = this.state === "run" ? (this.animFrame % 2 === 0 ? 4 : -4) : 0;
        ctx.fillRect(-10, 16, 8, 14 + legOffset);
        ctx.fillRect(2, 16, 8, 14 - legOffset);

        // Eyes
        ctx.fillStyle = "#000";
        ctx.fillRect(4, -12, 2, 2);
        ctx.fillRect(-2, -12, 2, 2);

        ctx.restore();
      }
    }

    const platforms = [
      new Platform(0, 400, 800, 50),      // ground
      new Platform(120, 320, 140, 20),
      new Platform(320, 270, 140, 20),
      new Platform(520, 220, 140, 20),
      new Platform(680, 150, 80, 20)
    ];

    const player = new Player(100, 100);

    function update() {
      player.update();
    }

    function drawBackground() {
      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 5; i++) {
        const x = (i * 180 + (Date.now() * 0.01)) % (canvas.width + 100) - 100;
        const y = 50 + (i % 3) * 30;
        ctx.beginPath();
        ctx.arc(x, y, 18, 0, Math.PI * 2);
        ctx.arc(x + 20, y - 10, 22, 0, Math.PI * 2);
        ctx.arc(x + 45, y, 18, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // platforms
      for (const p of platforms) p.draw();

      // player
      player.draw();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
