using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
using System;
using System.Collections.Generic;

namespace PlatformerGame
{
    public class Game1 : Game
    {
        private GraphicsDeviceManager _graphics;
        private SpriteBatch _spriteBatch;

        private Texture2D _playerTexture;
        private Texture2D _platformTexture;

        private Player _player;
        private List<Rectangle> _platforms;

        public Game1()
        {
            _graphics = new GraphicsDeviceManager(this);
            Content.RootDirectory = "Content";
            IsMouseVisible = true;
        }

        protected override void Initialize()
        {
            _platforms = new List<Rectangle>
            {
                new Rectangle(0, 420, 800, 60),   // ground
                new Rectangle(150, 330, 150, 20),
                new Rectangle(350, 250, 150, 20),
                new Rectangle(550, 180, 150, 20)
            };

            base.Initialize();
        }

        protected override void LoadContent()
        {
            _spriteBatch = new SpriteBatch(GraphicsDevice);

            _playerTexture = Content.Load<Texture2D>("player");
            _platformTexture = Content.Load<Texture2D>("platform");

            _player = new Player(_playerTexture, new Vector2(100, 300));
        }

        protected override void Update(GameTime gameTime)
        {
            if (Keyboard.GetState().IsKeyDown(Keys.Escape))
                Exit();

            _player.Update(gameTime, _platforms);

            base.Update(gameTime);
        }

        protected override void Draw(GameTime gameTime)
        {
            GraphicsDevice.Clear(Color.CornflowerBlue);

            _spriteBatch.Begin();

            foreach (var platform in _platforms)
            {
                _spriteBatch.Draw(_platformTexture, platform, Color.White);
            }

            _player.Draw(_spriteBatch);

            _spriteBatch.End();

            base.Draw(gameTime);
        }
    }

    public class Player
    {
        private Texture2D _texture;
        private Vector2 _position;
        private Vector2 _velocity;

        private const float MoveSpeed = 3.5f;
        private const float JumpPower = -10f;
        private const float Gravity = 0.4f;
        private const float MaxFallSpeed = 12f;

        private const int FrameWidth = 32;
        private const int FrameHeight = 32;
        private const int FrameCount = 4;
        private const float AnimationSpeed = 0.12f;

        private float _animationTimer;
        private int _currentFrame;

        private bool _isGrounded;
        private bool _facingRight = true;

        public Player(Texture2D texture, Vector2 startPosition)
        {
            _texture = texture;
            _position = startPosition;
        }

        public Rectangle Bounds =>
            new Rectangle((int)_position.X, (int)_position.Y, FrameWidth, FrameHeight);

        public void Update(GameTime gameTime, List<Rectangle> platforms)
        {
            KeyboardState state = Keyboard.GetState();

            float horizontalInput = 0f;

            if (state.IsKeyDown(Keys.Left) || state.IsKeyDown(Keys.A))
            {
                horizontalInput -= 1f;
                _facingRight = false;
            }

            if (state.IsKeyDown(Keys.Right) || state.IsKeyDown(Keys.D))
            {
                horizontalInput += 1f;
                _facingRight = true;
            }

            _velocity.X = horizontalInput * MoveSpeed;

            if (_isGrounded && (state.IsKeyDown(Keys.Space) || state.IsKeyDown(Keys.Up) || state.IsKeyDown(Keys.W)))
            {
                _velocity.Y = JumpPower;
                _isGrounded = false;
            }

            _velocity.Y += Gravity;
            if (_velocity.Y > MaxFallSpeed)
                _velocity.Y = MaxFallSpeed;

            // Move horizontally and resolve collisions
            _position.X += _velocity.X;
            Rectangle playerBounds = Bounds;

            foreach (var platform in platforms)
            {
                if (playerBounds.Intersects(platform))
                {
                    if (_velocity.X > 0)
                        _position.X = platform.Left - FrameWidth;
                    else if (_velocity.X < 0)
                        _position.X = platform.Right;

                    playerBounds = Bounds;
                }
            }

            // Move vertically and resolve collisions
            _position.Y += _velocity.Y;
            _isGrounded = false;
            playerBounds = Bounds;

            foreach (var platform in platforms)
            {
                if (playerBounds.Intersects(platform))
                {
                    if (_velocity.Y > 0)
                    {
                        _position.Y = platform.Top - FrameHeight;
                        _velocity.Y = 0;
                        _isGrounded = true;
                    }
                    else if (_velocity.Y < 0)
                    {
                        _position.Y = platform.Bottom;
                        _velocity.Y = 0;
                    }

                    playerBounds = Bounds;
                }
            }

            // Animation
            if (Math.Abs(_velocity.X) > 0.1f)
            {
                _animationTimer += (float)gameTime.ElapsedGameTime.TotalSeconds;
                if (_animationTimer >= AnimationSpeed)
                {
                    _animationTimer = 0f;
                    _currentFrame = (_currentFrame + 1) % FrameCount;
                }
            }
            else
            {
                _currentFrame = 0;
            }
        }

        public void Draw(SpriteBatch spriteBatch)
        {
            Rectangle sourceRect = new Rectangle(
                _currentFrame * FrameWidth,
                0,
                FrameWidth,
                FrameHeight
            );

            SpriteEffects effects = _facingRight ? SpriteEffects.None : SpriteEffects.FlipHorizontally;

            spriteBatch.Draw(_texture, _position, sourceRect, Color.White, 0f, Vector2.Zero, 1f, effects, 0f);
        }
    }
}
