```csharp
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
using System.Collections.Generic;

public class Player
{
    public Vector2 Position;
    public Vector2 Velocity;
    public Rectangle Bounds => new Rectangle((int)Position.X, (int)Position.Y, Width, Height);

    private const int Width = 32;
    private const int Height = 48;

    private const float MoveSpeed = 220f;
    private const float JumpSpeed = 520f;
    private const float Gravity = 1400f;
    private const float MaxFallSpeed = 900f;

    private bool isOnGround;
    private bool facingRight = true;

    private readonly Animation idleAnimation;
    private readonly Animation walkAnimation;
    private Animation currentAnimation;

    public Player(Texture2D idleTexture, List<Texture2D> walkFrames, Vector2 startPosition)
    {
        Position = startPosition;
        idleAnimation = new Animation(new List<Texture2D> { idleTexture }, 0.2f);
        walkAnimation = new Animation(walkFrames, 0.1f);
        currentAnimation = idleAnimation;
    }

    public void Update(GameTime gameTime, List<Rectangle> platforms)
    {
        KeyboardState ks = Keyboard.GetState();
        float dt = (float)gameTime.ElapsedGameTime.TotalSeconds;

        float moveInput = 0f;
        if (ks.IsKeyDown(Keys.Left) || ks.IsKeyDown(Keys.A))
            moveInput -= 1f;
        if (ks.IsKeyDown(Keys.Right) || ks.IsKeyDown(Keys.D))
            moveInput += 1f;

        Velocity.X = moveInput * MoveSpeed;

        if (moveInput != 0)
            facingRight = moveInput > 0;

        if ((ks.IsKeyDown(Keys.Space) || ks.IsKeyDown(Keys.Up) || ks.IsKeyDown(Keys.W)) && isOnGround)
        {
            Velocity.Y = -JumpSpeed;
            isOnGround = false;
        }

        Velocity.Y += Gravity * dt;
        if (Velocity.Y > MaxFallSpeed)
            Velocity.Y = MaxFallSpeed;

        // Horizontal movement
        Position.X += Velocity.X * dt;
        ResolveCollisions(platforms, horizontal: true);

        // Vertical movement
        Position.Y += Velocity.Y * dt;
        isOnGround = false;
        ResolveCollisions(platforms, horizontal: false);

        if (isOnGround && moveInput != 0)
            currentAnimation = walkAnimation;
        else
            currentAnimation = idleAnimation;

        currentAnimation.Update(gameTime);
    }

    private void ResolveCollisions(List<Rectangle> platforms, bool horizontal)
    {
        Rectangle playerRect = Bounds;

        foreach (var platform in platforms)
        {
            if (!playerRect.Intersects(platform))
                continue;

            if (horizontal)
            {
                if (Velocity.X > 0)
                    Position.X = platform.Left - Width;
                else if (Velocity.X < 0)
                    Position.X = platform.Right;

                Velocity.X = 0;
            }
            else
            {
                if (Velocity.Y > 0)
                {
                    Position.Y = platform.Top - Height;
                    isOnGround = true;
                }
                else if (Velocity.Y < 0)
                {
                    Position.Y = platform.Bottom;
                }

                Velocity.Y = 0;
            }

            playerRect = Bounds;
        }
    }

    public void Draw(SpriteBatch spriteBatch)
    {
        Texture2D texture = currentAnimation.CurrentFrame;
        SpriteEffects effects = facingRight ? SpriteEffects.None : SpriteEffects.FlipHorizontally;

        spriteBatch.Draw(texture, Bounds, null, Color.White, 0f, Vector2.Zero, effects, 0f);
    }
}
