```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const keys = {};
window.addEventListener("keydown", (e) => (keys[e.code] = true));
window.addEventListener("keyup", (e) => (keys[e.code] = false));

const GRAVITY = 0.6;
const MOVE_SPEED = 4;
const JUMP_FORCE = -12;

class Platform {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
  }

  draw(cameraX, cameraY) {
    ctx.fillStyle = "#4b8b3b";
    ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);
    ctx.fillStyle = "#2f5e25";
    ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, 8);
  }
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 40;
    this.h = 56;
    this.vx = 0;
    this.vy = 0;
    this.onGround = false;
    this.facing = 1; // 1 = right, -1 = left
    this.state = "idle";
    this.animFrame = 0;
    this.animTimer = 0;
  }

  update(platforms) {
    // Horizontal movement
    this.vx = 0;
    if (keys["ArrowLeft"] || keys["KeyA"]) {
      this.vx = -MOVE_SPEED;
      this.facing = -1;
    }
    if (keys["ArrowRight"] || keys["KeyD"]) {
      this.vx = MOVE_SPEED;
      this.facing = 1;
    }

    // Jump
    if ((keys["Space"] || keys["ArrowUp"] || keys["KeyW"]) && this.onGround) {
      this.vy = JUMP_FORCE;
      this.onGround = false;
    }

    // Gravity
    this.vy += GRAVITY;

    // Horizontal collision
    this.x += this.vx;
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vx > 0) this.x = p.x - this.w;
        if (this.vx < 0) this.x = p.x + p.w;
      }
    }

    // Vertical collision
    this.y += this.vy;
    this.onGround = false;
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }

    // Animation state
    if (!this.onGround) {
      this.state = "jump";
    } else if (Math.abs(this.vx) > 0) {
      this.state = "run";
    } else {
      this.state = "idle";
    }

    // Update animation frame
    this.animTimer++;
    const speed = this.state === "run" ? 8 : 15;
    if (this.animTimer >= speed) {
      this.animTimer = 0;
      this.animFrame = (this.animFrame + 1) % this.getFrameCount();
    }
  }

  getFrameCount() {
    if (this.state === "jump") return 1;
    if (this.state === "run") return 6;
    return 4;
  }

  intersects(p) {
    return (
      this.x < p.x + p.w &&
      this.x + this.w > p.x &&
      this.y < p.y + p.h &&
      this.y + this.h > p.y
    );
  }

  draw(cameraX, cameraY) {
    const drawX = this.x - cameraX;
    const drawY = this.y - cameraY;

    // Temporary rectangle player
    // Replace this with sprite-sheet rendering later
    ctx.save();
    ctx.translate(drawX + this.w / 2, drawY + this.h / 2);
    ctx.scale(this.facing, 1);

    if (this.state === "idle") ctx.fillStyle = "#f4c542";
    if (this.state === "run") ctx.fillStyle = "#ff9f1c";
    if (this.state === "jump") ctx.fillStyle = "#ff5d5d";

    ctx.fillRect(-this.w / 2, -this.h / 2, this.w, this.h);

    // simple face marker
    ctx.fillStyle = "#222";
    ctx.fillRect(8, -10, 6, 6);
    ctx.fillRect(18, -10, 6, 6);

    ctx.restore();
  }
}

// Simple level
const platforms = [
  new Platform(0, 500, 2000, 40),     // ground
  new Platform(220, 420, 120, 20),
  new Platform(420, 360, 120, 20),
  new Platform(620, 300, 120, 20),
  new Platform(820, 380, 160, 20),
  new Platform(1080, 450, 140, 20),
  new Platform(1280, 390, 160, 20),
  new Platform(1540, 340, 160, 20),
];

const player = new Player(100, 100);

let cameraX = 0;
let cameraY = 0;

function updateCamera() {
  cameraX = player.x + player.w / 2 - canvas.width / 2;
  cameraY = player.y + player.h / 2 - canvas.height / 2;

  cameraX = Math.max(0, cameraX);
  cameraY = Math.max(0, cameraY);
}

function drawBackground() {
  // clouds / parallax-ish shapes
  ctx.fillStyle = "rgba(255,255,255,0.5)";
  ctx.beginPath();
  ctx.arc(150 - cameraX * 0.2, 120, 30, 0, Math.PI * 2);
  ctx.arc(180 - cameraX * 0.2, 110, 40, 0, Math.PI * 2);
  ctx.arc(220 - cameraX * 0.2, 120, 30, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.arc(700 - cameraX * 0.1, 80, 25, 0, Math.PI * 2);
  ctx.arc(730 - cameraX * 0.1, 70, 35, 0, Math.PI * 2);
  ctx.arc(770 - cameraX * 0.1, 80, 25, 0, Math.PI * 2);
  ctx.fill();
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawBackground();

  // platforms
  for (const p of platforms) p.draw(cameraX, cameraY);

  // player
  player.draw(cameraX, cameraY);

  // HUD
  ctx.fillStyle = "#000";
  ctx.font = "16px monospace";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 20, 30);
}

function gameLoop() {
  player.update(platforms);
  updateCamera();
  draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();
