  gfx.clear();

  // Platform texture
  gfx.fillStyle(0x7c4d2e, 1);
  gfx.fillRect(0, 0, 64, 20);
  gfx.generateTexture('platform', 64, 20);
  gfx.destroy();
}

function create() {
  // Background
  this.cameras.main.setBackgroundColor('#87ceeb');

  // Platforms
  platforms = this.physics.add.staticGroup();

  platforms.create(400, 430, 'platform').setScale(13, 1).refreshBody();
  platforms.create(150, 320, 'platform');
  platforms.create(650, 260, 'platform');
  platforms.create(400, 180, 'platform');

  // Player
  player = this.physics.add.sprite(100, 350, 'player');
  player.setBounce(0.1);
  player.setCollideWorldBounds(true);

  // Simple "animation" effect: tint changes based on movement
  player.originalTint = 0x4cc9f0;

  // Collisions
  this.physics.add.collider(player, platforms);

  // Keyboard input
  cursors = this.input.keyboard.createCursorKeys();
  moveLeftKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A);
  moveRightKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D);
  jumpKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

  // Instructions
  const text = this.add.text(16, 16, 'Move: A/D or ←/→   Jump: SPACE', {
    fontFamily: 'Arial',
    fontSize: '20px',
    color: '#000'
  });
  text.setScrollFactor(0);
}

function update() {
  const speed = 200;

  const leftPressed = cursors.left.isDown || moveLeftKey.isDown;
  const rightPressed = cursors.right.isDown || moveRightKey.isDown;
  const jumpPressed = Phaser.Input.Keyboard.JustDown(jumpKey);

  if (leftPressed) {
    player.setVelocityX(-speed);
    player.setTint(0x00b4d8);
  } else if (rightPressed) {
    player.setVelocityX(speed);
    player.setTint(0xffb703);
  } else {
    player.setVelocityX(0);
    player.setTint(player.originalTint);
  }

  // Simple grounded check
  playerOnGround = player.body.blocked.down || player.body.touching.down;

  if (jumpPressed && playerOnGround) {
    player.setVelocityY(-450);
  }

  // Fake sprite animation:
  // slightly squash/stretch the player while moving and in air
  if (!playerOnGround) {
    player.setScale(1, 1.05);
  } else if (Math.abs(player.body.velocity.x) > 0) {
    player.setScale(1.05, 0.95);
  } else {
    player.setScale(1, 1);
  }
}
</script>
