## `Game1.cs`

```csharp
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
using System;

namespace MinimalPlatformer
{
    public class Game1 : Game
    {
        private GraphicsDeviceManager graphics;
        private SpriteBatch spriteBatch;

        private Texture2D playerTexture;
        private Texture2D platformTexture;

        private Vector2 playerPosition;
        private Vector2 playerVelocity;

        private const float MoveSpeed = 200f;
        private const float JumpSpeed = 450f;
        private const float Gravity = 1200f;

        private bool isGrounded;

        private Rectangle[] platforms;

        private int currentFrame = 0;
        private float animationTimer = 0f;
        private const float FrameTime = 0.1f;
        private const int FrameWidth = 32;
        private const int FrameHeight = 32;
        private const int FrameCount = 4;

        public Game1()
        {
            graphics = new GraphicsDeviceManager(this);
            Content.RootDirectory = "Content";
            IsMouseVisible = true;
        }

        protected override void Initialize()
        {
            playerPosition = new Vector2(100, 100);

            platforms = new Rectangle[]
            {
                new Rectangle(0, 400, 800, 32),
                new Rectangle(200, 300, 120, 20),
                new Rectangle(400, 240, 120, 20),
                new Rectangle(560, 180, 120, 20)
            };

            base.Initialize();
        }

        protected override void LoadContent()
        {
            spriteBatch = new SpriteBatch(GraphicsDevice);

            playerTexture = Content.Load<Texture2D>("player");
            platformTexture = Content.Load<Texture2D>("platform");
        }

        protected override void Update(GameTime gameTime)
        {
            var keyboard = Keyboard.GetState();
            float dt = (float)gameTime.ElapsedGameTime.TotalSeconds;

            // Horizontal input
            playerVelocity.X = 0;
            if (keyboard.IsKeyDown(Keys.Left) || keyboard.IsKeyDown(Keys.A))
                playerVelocity.X = -MoveSpeed;
            if (keyboard.IsKeyDown(Keys.Right) || keyboard.IsKeyDown(Keys.D))
                playerVelocity.X = MoveSpeed;

            // Jump
            if ((keyboard.IsKeyDown(Keys.Space) || keyboard.IsKeyDown(Keys.Up)) && isGrounded)
            {
                playerVelocity.Y = -JumpSpeed;
                isGrounded = false;
            }

            // Gravity
            playerVelocity.Y += Gravity * dt;

            // Move player
            playerPosition.X += playerVelocity.X * dt;
            ResolveHorizontalCollisions();

            playerPosition.Y += playerVelocity.Y * dt;
            isGrounded = false;
            ResolveVerticalCollisions();

            // Animation
            if (Math.Abs(playerVelocity.X) > 1)
            {
                animationTimer += dt;
                if (animationTimer >= FrameTime)
                {
                    animationTimer = 0f;
                    currentFrame = (currentFrame + 1) % FrameCount;
                }
            }
            else
            {
                currentFrame = 0;
            }

            // Restart if falling off-screen
            if (playerPosition.Y > 600)
                playerPosition = new Vector2(100, 100);

            if (keyboard.IsKeyDown(Keys.Escape))
                Exit();

            base.Update(gameTime);
        }

        private void ResolveHorizontalCollisions()
        {
            Rectangle playerRect = GetPlayerRectangle();

            foreach (var platform in platforms)
            {
                if (playerRect.Intersects(platform))
                {
                    if (playerVelocity.X > 0)
                        playerPosition.X = platform.Left - playerRect.Width;
                    else if (playerVelocity.X < 0)
                        playerPosition.X = platform.Right;

                    playerVelocity.X = 0;
                    playerRect = GetPlayerRectangle();
                }
            }
        }

        private void ResolveVerticalCollisions()
        {
            Rectangle playerRect = GetPlayerRectangle();

            foreach (var platform in platforms)
            {
                if (playerRect.Intersects(platform))
                {
                    if (playerVelocity.Y > 0)
                    {
                        playerPosition.Y = platform.Top - playerRect.Height;
                        isGrounded = true;
                    }
                    else if (playerVelocity.Y < 0)
                    {
                        playerPosition.Y = platform.Bottom;
                    }

                    playerVelocity.Y = 0;
                    playerRect = GetPlayerRectangle();
                }
            }
        }

        private Rectangle GetPlayerRectangle()
        {
            return new Rectangle((int)playerPosition.X, (int)playerPosition.Y, FrameWidth, FrameHeight);
        }

        protected override void Draw(GameTime gameTime)
        {
            GraphicsDevice.Clear(Color.CornflowerBlue);

            spriteBatch.Begin();

            // Draw platforms
            foreach (var platform in platforms)
            {
                spriteBatch.Draw(platformTexture, platform, Color.White);
            }

            // Draw player animation frame
            Rectangle sourceRect = new Rectangle(currentFrame * FrameWidth, 0, FrameWidth, FrameHeight);
            spriteBatch.Draw(playerTexture, playerPosition, sourceRect, Color.White);

            spriteBatch.End();

            base.Draw(gameTime);
        }
    }
}
