Here’s a compact **JavaScript + Three.js** example of a real-time 3D scene viewer with **dynamic lighting** and a **custom shader effect**. It renders a rotating object, moving point light, and a shader-driven visual look.

### `index.html`
```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.159.0/build/three.module.js";

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    document.body.appendChild(renderer.domElement);

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050510);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 5);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(1, 0.35, 200, 32);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x4cc9f0) },
        uColorB: { value: new THREE.Color(0xf72585) }
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vPosition = (modelMatrix * vec4(position, 1.0)).xyz;
          gl_Position = projectionMatrix * viewMatrix * vec4(vPosition, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(sin(uTime), 1.0, cos(uTime)));

          float diffuse = max(dot(n, lightDir), 0.0);
          float rim = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

          float bands = 0.5 + 0.5 * sin(uTime * 3.0 + vPosition.y * 8.0);
          vec3 base = mix(uColorA, uColorB, bands);

          vec3 color = base * (0.2 + 0.8 * diffuse) + rim * 0.35;
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Dynamic lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0xffffff, 2.0, 50);
    pointLight.position.set(3, 2, 3);
    scene.add(pointLight);

    const lightHelper = new THREE.PointLightHelper(pointLight, 0.2);
    scene.add(lightHelper);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      material.uniforms.uTime.value = t;

      // Object motion
      mesh.rotation.x = t * 0.35;
      mesh.rotation.y = t * 0.55;

      // Moving light
      pointLight.position.x = Math.sin(t) * 4.0;
      pointLight.position.y = 1.5 + Math.cos(t * 1.7) * 1.0;
      pointLight.position.z = Math.cos(t) * 4.0;

      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
