## 5) `src/main.ts`

```ts
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";

// Renderer
const app = document.getElementById("app");
if (!app) throw new Error("App container not found");

const renderer = new THREE.WebGLRenderer({
  antialias: true,
  alpha: false
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
app.appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(3.5, 2.2, 5.5);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 0.6, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
dirLight.position.set(4, 8, 3);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(2048, 2048);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x66aaff, 35, 12, 2);
pointLight.position.set(0, 2, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 1,
  metalness: 0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Custom shader material for the main object
const uniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x4fd1ff) },
  uColorB: { value: new THREE.Color(0x8b5cf6) }
};

const vertexShader = `
  varying vec3 vNormal;
  varying vec3 vPosition;

  void main() {
    vNormal = normalize(normalMatrix * normal);
    vec4 worldPos = modelMatrix * vec4(position, 1.0);
    vPosition = worldPos.xyz;
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const fragmentShader = `
  precision highp float;

  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;

  varying vec3 vNormal;
  varying vec3 vPosition;

  void main() {
    vec3 n = normalize(vNormal);

    // Fake dynamic lighting effect
    vec3 lightDir = normalize(vec3(sin(uTime * 0.9), 0.8, cos(uTime * 0.7)));
    float diff = max(dot(n, lightDir), 0.0);

    // Fresnel-style rim
    vec3 viewDir = normalize(cameraPosition - vPosition);
    float fresnel = pow(1.0 - max(dot(n, viewDir), 0.0), 3.0);

    // Subtle animated banding
    float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 4.0);

    vec3 base = mix(uColorA, uColorB, wave);
    vec3 color = base * (0.18 + 0.82 * diff) + fresnel * 0.7;

    gl_FragColor = vec4(color, 1.0);
  }
`;

const sphereGeo = new THREE.SphereGeometry(1, 64, 64);
const sphereMat = new THREE.ShaderMaterial({
  uniforms,
  vertexShader,
  fragmentShader
});

const sphere = new THREE.Mesh(sphereGeo, sphereMat);
sphere.position.y = 1.2;
sphere.castShadow = true;
scene.add(sphere);

// Additional geometry for depth/visual interest
const torus = new THREE.Mesh(
  new THREE.TorusGeometry(1.7, 0.08, 16, 120),
  new THREE.MeshStandardMaterial({
    color: 0x9ca3af,
    metalness: 0.8,
    roughness: 0.25
  })
);
torus.rotation.x = Math.PI / 2;
torus.position.y = 1.2;
torus.castShadow = true;
scene.add(torus);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  uniforms.uTime.value = elapsed;

  sphere.rotation.y = elapsed * 0.5;
  sphere.rotation.x = Math.sin(elapsed * 0.35) * 0.15;

  torus.rotation.z = elapsed * 0.7;

  pointLight.position.x = Math.sin(elapsed * 1.2) * 2.5;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 2.5;
  pointLight.position.y = 1.8 + Math.sin(elapsed * 2.0) * 0.5;

  dirLight.position.x = Math.cos(elapsed * 0.3) * 5;
  dirLight.position.z = Math.sin(elapsed * 0.3) * 5;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

