## 3) `main.js`

```javascript
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

let scene, camera, renderer, controls, mesh, clock;
let customMaterial;

init();
animate();

function init() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x101018);
  scene.fog = new THREE.Fog(0x101018, 10, 30);

  camera = new THREE.PerspectiveCamera(
    60,
    window.innerWidth / window.innerHeight,
    0.1,
    100
  );
  camera.position.set(0, 2, 6);

  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  document.body.appendChild(renderer.domElement);

  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.target.set(0, 1, 0);

  clock = new THREE.Clock();

  // Lights
  const ambient = new THREE.AmbientLight(0xffffff, 0.25);
  scene.add(ambient);

  const directional = new THREE.DirectionalLight(0xffffff, 2.0);
  directional.position.set(3, 5, 2);
  directional.castShadow = true;
  scene.add(directional);

  const pointLight = new THREE.PointLight(0x44aaff, 40, 20);
  pointLight.position.set(-3, 2, 2);
  scene.add(pointLight);

  const movingLight = new THREE.SpotLight(0xff8844, 60, 30, Math.PI / 6, 0.4, 1);
  movingLight.position.set(0, 6, 0);
  movingLight.castShadow = true;
  scene.add(movingLight);

  // Ground plane
  const floorGeo = new THREE.PlaneGeometry(30, 30);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x222233,
    roughness: 1.0,
    metalness: 0.0,
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Main object
  const geometry = new THREE.TorusKnotGeometry(1, 0.35, 220, 32);

  customMaterial = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uBaseColor: { value: new THREE.Color(0x66ccff) },
      uAccentColor: { value: new THREE.Color(0xff66cc) },
    },
    vertexShader: `
      varying vec3 vNormal;
      varying vec3 vWorldPos;

      void main() {
        vNormal = normalize(normalMatrix * normal);
        vec4 worldPos = modelMatrix * vec4(position, 1.0);
        vWorldPos = worldPos.xyz;
        gl_Position = projectionMatrix * viewMatrix * worldPos;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uBaseColor;
      uniform vec3 uAccentColor;

      varying vec3 vNormal;
      varying vec3 vWorldPos;

      void main() {
        vec3 N = normalize(vNormal);
        vec3 lightDir = normalize(vec3(0.6, 0.8, 0.4));
        float diff = max(dot(N, lightDir), 0.0);

        float fresnel = pow(1.0 - max(dot(N, normalize(-vWorldPos)), 0.0), 3.0);

        float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 4.0);
        vec3 base = mix(uBaseColor, uAccentColor, wave);

        vec3 color = base * (0.18 + diff * 0.95);
        color += fresnel * 0.6 * uAccentColor;

        gl_FragColor = vec4(color, 1.0);
      }
    `,
  });

  mesh = new THREE.Mesh(geometry, customMaterial);
  mesh.position.y = 1.5;
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);

  // Helper objects for visual interest
  const sphereGeo = new THREE.SphereGeometry(0.18, 24, 24);
  const sphereMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.2,
    roughness: 0.3,
  });

  for (let i = 0; i < 10; i++) {
    const s = new THREE.Mesh(sphereGeo, sphereMat);
    const angle = (i / 10) * Math.PI * 2;
    s.position.set(Math.cos(angle) * 3.5, 1.2 + Math.sin(i) * 0.4, Math.sin(angle) * 3.5);
    s.castShadow = true;
    scene.add(s);
  }

  window.addEventListener("resize", onWindowResize);
}

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  customMaterial.uniforms.uTime.value = t;

  mesh.rotation.y = t * 0.6;
  mesh.rotation.x = Math.sin(t * 0.3) * 0.2;

  // Animate lights
  scene.children.forEach((obj) => {
    if (obj.isPointLight) {
      obj.position.x = Math.cos(t * 0.8) * 4;
      obj.position.z = Math.sin(t * 0.8) * 4;
    }
    if (obj.isSpotLight) {
      obj.position.x = Math.sin(t * 0.7) * 2.5;
      obj.position.z = Math.cos(t * 0.7) * 2.5;
      obj.target.position.set(0, 1, 0);
      obj.target.updateMatrixWorld();
    }
  });

  controls.update();
  renderer.render(scene, camera);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}
```

