# 5) Custom shader effect

Create a shader named `DynamicLitShader.shader`:

```c
Shader "Custom/DynamicLitShader"
{
    Properties
    {
        _Color ("Main Color", Color) = (1,1,1,1)
        _Gloss ("Gloss", Range(0,1)) = 0.5
        _Metallic ("Metallic", Range(0,1)) = 0.0
        _WaveStrength ("Wave Strength", Range(0,0.5)) = 0.1
        _WaveSpeed ("Wave Speed", Range(0,10)) = 2.0
    }

    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 200

        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows vertex:vert

        #include "UnityCG.cginc"

        struct Input
        {
            float2 uv_MainTex;
        };

        fixed4 _Color;
        half _Gloss;
        half _Metallic;
        half _WaveStrength;
        half _WaveSpeed;

        void vert(inout appdata_full v)
        {
            float wave = sin((_Time.y * _WaveSpeed) + (v.vertex.x * 4.0) + (v.vertex.z * 4.0));
            v.vertex.y += wave * _WaveStrength;
        }

        void surf(Input IN, inout SurfaceOutputStandard o)
        {
            o.Albedo = _Color.rgb;
            o.Metallic = _Metallic;
            o.Smoothness = _Gloss;
            o.Alpha = _Color.a;
        }
        ENDCG
    }

    FallBack "Standard"
}
```

