# 4) Shader: dynamic lighting + effect

Below is a simple shader that reacts to lighting and adds a subtle animated emission-like wave effect.

Create a new shader file `DynamicLitWave.shader`:

```c
Shader "Custom/DynamicLitWave"
{
    Properties
    {
        _Color ("Color", Color) = (0.7, 0.8, 1.0, 1.0)
        _MainTex ("Albedo", 2D) = "white" {}
        _WaveStrength ("Wave Strength", Range(0, 1)) = 0.15
        _WaveSpeed ("Wave Speed", Range(0, 10)) = 2.0
        _Specular ("Specular", Range(0, 1)) = 0.5
        _Gloss ("Gloss", Range(8, 256)) = 64
    }

    SubShader
    {
        Tags { "RenderType"="Opaque" "Queue"="Geometry" }
        LOD 200

        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows

        sampler2D _MainTex;
        fixed4 _Color;
        half _WaveStrength;
        half _WaveSpeed;
        half _Specular;
        half _Gloss;

        struct Input
        {
            float2 uv_MainTex;
            float3 worldPos;
        };

        void surf (Input IN, inout SurfaceOutputStandard o)
        {
            fixed4 tex = tex2D(_MainTex, IN.uv_MainTex) * _Color;

            float wave = sin((IN.worldPos.x + IN.worldPos.z + _Time.y * _WaveSpeed) * 4.0);
            wave = wave * 0.5 + 0.5;

            o.Albedo = tex.rgb;
            o.Emission = tex.rgb * wave * _WaveStrength;
            o.Metallic = _Specular;
            o.Smoothness = saturate(_Gloss / 256.0);
            o.Alpha = tex.a;
        }
        ENDCG
    }

    FallBack "Diffuse"
}
```

