## 4) Shader code

### `shaders/scene.vert`
```glsl
#version 330 core

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;

uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

out vec3 FragPos;
out vec3 Normal;

void main()
{
    FragPos = vec3(model * vec4(aPos, 1.0));
    Normal = mat3(transpose(inverse(model))) * aNormal;
    gl_Position = projection * view * vec4(FragPos, 1.0);
}
```

### `shaders/scene.frag`
```glsl
#version 330 core

out vec4 FragColor;

in vec3 FragPos;
in vec3 Normal;

uniform vec3 lightPos;
uniform vec3 viewPos;
uniform float time;

void main()
{
    vec3 ambient = vec3(0.12, 0.12, 0.16);

    vec3 norm = normalize(Normal);
    vec3 lightDir = normalize(lightPos - FragPos);
    float diff = max(dot(norm, lightDir), 0.0);
    vec3 diffuse = diff * vec3(0.7, 0.75, 0.9);

    vec3 viewDir = normalize(viewPos - FragPos);
    vec3 reflectDir = reflect(-lightDir, norm);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
    vec3 specular = vec3(0.8) * spec;

    // Simple animated shader effect
    float pulse = 0.5 + 0.5 * sin(time * 2.0 + FragPos.x * 4.0 + FragPos.y * 4.0);
    vec3 effectColor = mix(vec3(0.2, 0.4, 0.9), vec3(0.9, 0.3, 0.6), pulse);

    vec3 color = ambient + diffuse + specular;
    color *= effectColor;

    FragColor = vec4(color, 1.0);
}
```

