## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x101018);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 4);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0xff8844, 2.0, 20);
    pointLight.position.set(2, 2, 2);
    scene.add(pointLight);

    const dirLight = new THREE.DirectionalLight(0x88ccff, 1.2);
    dirLight.position.set(-1, 1, 0.5);
    scene.add(dirLight);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(0.8, 0.28, 200, 32);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uLightPos: { value: pointLight.position.clone() }
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vNormal = normalize(normalMatrix * normal);
          vec4 worldPos = modelMatrix * vec4(position, 1.0);
          vWorldPos = worldPos.xyz;
          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uLightPos;

        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 N = normalize(vNormal);
          vec3 L = normalize(uLightPos - vWorldPos);

          // Basic diffuse lighting
          float diff = max(dot(N, L), 0.0);

          // Animated Fresnel-like rim effect
          vec3 V = normalize(cameraPosition - vWorldPos);
          float fresnel = pow(1.0 - max(dot(N, V), 0.0), 2.5);

          // Simple animated color shift
          vec3 baseColor = mix(
            vec3(0.15, 0.4, 1.0),
            vec3(1.0, 0.25, 0.6),
            0.5 + 0.5 * sin(uTime * 1.5)
          );

          vec3 lighting = baseColor * (0.2 + diff * 1.2);
          lighting += fresnel * vec3(1.0, 1.0, 1.0) * 0.8;

          gl_FragColor = vec4(lighting, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
