```cpp
// CustomPhysicsPlugin.h
#pragma once
#include <vector>
#include <cmath>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float X, float Y, float Z) : x(X), y(Y), z(Z) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
};

inline Vec3 operator*(float s, const Vec3& v) { return v * s; }

inline float Dot(const Vec3& a, const Vec3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

inline float Length(const Vec3& v) {
    return std::sqrt(Dot(v, v));
}

inline Vec3 Normalize(const Vec3& v) {
    float len = Length(v);
    if (len <= 1e-6f) return Vec3(0, 0, 0);
    return v * (1.0f / len);
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass;
    float restitution;
    bool isStatic;

    RigidBody()
        : position(), velocity(), forceAccum(), mass(1.0f),
          restitution(0.5f), isStatic(false) {}

    void AddForce(const Vec3& force) {
        if (!isStatic) forceAccum += force;
    }

    void ClearForces() {
        forceAccum = Vec3(0, 0, 0);
    }
};

class PhysicsWorld {
public:
    void AddBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    std::vector<RigidBody>& GetBodies() {
        return bodies;
    }

    void SetGravity(const Vec3& g) {
        gravity = g;
    }

    void Step(float dt) {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // Gravity
            body.AddForce(gravity * body.mass);

            // Semi-implicit Euler integration
            Vec3 acceleration = body.forceAccum * (1.0f / body.mass);
            body.velocity += acceleration * dt;
            body.position += body.velocity * dt;

            body.ClearForces();
        }

        ResolveGroundCollisions();
    }

private:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);

    void ResolveGroundCollisions() {
        // Simple infinite ground plane at y = 0
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            if (body.position.y < 0.0f) {
                body.position.y = 0.0f;

                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }
            }
        }
    }
};

// Example plugin interface
class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void Update(float dt) = 0;
    virtual PhysicsWorld& GetWorld() = 0;
};

class CustomPhysicsPlugin : public IPhysicsPlugin {
public:
    void Initialize() override {
        world.SetGravity(Vec3(0.0f, -9.81f, 0.0f));
    }

    void Shutdown() override {
        // Cleanup if needed
    }

    void Update(float dt) override {
        world.Step(dt);
    }

    PhysicsWorld& GetWorld() override {
        return world;
    }

private:
    PhysicsWorld world;
};
```

