# 2) Plugin implementation

```cpp
// CustomPhysicsPlugin.cpp
#include "CustomPhysicsPlugin.h"

#include <cmath>

namespace CustomPhysics {

PhysicsWorld::PhysicsWorld()
    : m_gravity(0.0f, -9.81f, 0.0f),
      m_nextId(1) {}

void PhysicsWorld::SetGravity(const Vec3& gravity) {
    m_gravity = gravity;
}

Vec3 PhysicsWorld::GetGravity() const {
    return m_gravity;
}

uint32_t PhysicsWorld::CreateBody(const Vec3& position, float mass, bool isStatic) {
    RigidBody body;
    body.id = m_nextId++;
    body.position = position;
    body.velocity = Vec3(0, 0, 0);
    body.forceAccum = Vec3(0, 0, 0);
    body.mass = (mass > 0.0f) ? mass : 1.0f;
    body.invMass = (isStatic || mass <= 0.0f) ? 0.0f : 1.0f / mass;
    body.isStatic = isStatic;

    m_bodies.push_back(body);
    return body.id;
}

RigidBody* PhysicsWorld::GetBody(uint32_t id) {
    for (auto& body : m_bodies) {
        if (body.id == id) {
            return &body;
        }
    }
    return nullptr;
}

void PhysicsWorld::ApplyForce(uint32_t id, const Vec3& force) {
    RigidBody* body = GetBody(id);
    if (!body || body->isStatic) {
        return;
    }
    body->forceAccum += force;
}

void PhysicsWorld::IntegrateBody(RigidBody& body, float dt) {
    if (body.isStatic || body.invMass <= 0.0f) {
        body.forceAccum = Vec3(0, 0, 0);
        return;
    }

    // Apply gravity
    Vec3 totalForce = body.forceAccum + (m_gravity * body.mass);

    // Acceleration
    Vec3 acceleration = totalForce * body.invMass;

    // Semi-implicit Euler
    body.velocity += acceleration * dt;
    body.position += body.velocity * dt;

    // Clear forces
    body.forceAccum = Vec3(0, 0, 0);
}

void PhysicsWorld::StepSimulation(float deltaTime) {
    // Basic safety clamp
    if (deltaTime <= 0.0f) {
        return;
    }

    // Fixed-ish integration target for stability
    const float maxDt = 1.0f / 30.0f;
    float dt = (deltaTime > maxDt) ? maxDt : deltaTime;

    for (auto& body : m_bodies) {
        IntegrateBody(body, dt);
    }
}

} // namespace CustomPhysics
