### `RigidBody.h`
```cpp
#pragma once

#include "PhysicsTypes.h"

enum class BodyType
{
    Static,
    Dynamic
};

struct RigidBodyDesc
{
    BodyType type = BodyType::Dynamic;
    float mass = 1.0f;
    float radius = 0.5f;     // sphere collider for now
    Vec3 position = Vec3(0, 0, 0);
    Vec3 velocity = Vec3(0, 0, 0);
    float restitution = 0.2f;
    float linearDamping = 0.01f;
};

class RigidBody
{
public:
    explicit RigidBody(const RigidBodyDesc& desc)
        : m_type(desc.type),
          m_mass(desc.mass),
          m_invMass((desc.type == BodyType::Dynamic && desc.mass > 0.0f) ? 1.0f / desc.mass : 0.0f),
          m_radius(desc.radius),
          m_position(desc.position),
          m_velocity(desc.velocity),
          m_force(0, 0, 0),
          m_restitution(desc.restitution),
          m_linearDamping(desc.linearDamping)
    {}

    void ApplyForce(const Vec3& force)
    {
        if (m_type == BodyType::Dynamic)
            m_force += force;
    }

    void ApplyImpulse(const Vec3& impulse)
    {
        if (m_type == BodyType::Dynamic && m_invMass > 0.0f)
            m_velocity += impulse * m_invMass;
    }

    void SetPosition(const Vec3& p) { m_position = p; }
    void SetVelocity(const Vec3& v) { m_velocity = v; }

    const Vec3& GetPosition() const { return m_position; }
    const Vec3& GetVelocity() const { return m_velocity; }
    float GetRadius() const { return m_radius; }
    float GetRestitution() const { return m_restitution; }
    BodyType GetType() const { return m_type; }

    void ClearForces() { m_force = Vec3(0, 0, 0); }

    void Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic)
            return;

        Vec3 acceleration = gravity + (m_force * m_invMass);
        m_velocity += acceleration * dt;

        // simple damping
        m_velocity *= (1.0f - m_linearDamping);

        m_position += m_velocity * dt;

        ClearForces();
    }

private:
    BodyType m_type;
    float m_mass;
    float m_invMass;
    float m_radius;

    Vec3 m_position;
    Vec3 m_velocity;
    Vec3 m_force;

    float m_restitution;
    float m_linearDamping;
};
