### `PhysicsWorld.h`
```cpp
#pragma once

#include <vector>
#include <memory>
#include "RigidBody.h"

class PhysicsWorld
{
public:
    PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f),
          m_groundHeight(0.0f)
    {}

    void SetGravity(const Vec3& g) { m_gravity = g; }
    void SetGroundHeight(float h) { m_groundHeight = h; }

    RigidBody* CreateBody(const RigidBodyDesc& desc)
    {
        m_bodies.emplace_back(std::make_unique<RigidBody>(desc));
        return m_bodies.back().get();
    }

    void DestroyBody(RigidBody* body)
    {
        for (auto it = m_bodies.begin(); it != m_bodies.end(); ++it)
        {
            if (it->get() == body)
            {
                m_bodies.erase(it);
                return;
            }
        }
    }

    void Step(float dt)
    {
        // Integrate bodies
        for (auto& body : m_bodies)
        {
            body->Integrate(dt, m_gravity);
            ResolveGroundCollision(*body);
        }
    }

private:
    void ResolveGroundCollision(RigidBody& body)
    {
        if (body.GetType() != BodyType::Dynamic)
            return;

        Vec3 pos = body.GetPosition();
        Vec3 vel = body.GetVelocity();
        float radius = body.GetRadius();

        float minY = m_groundHeight + radius;
        if (pos.y < minY)
        {
            pos.y = minY;

            // reflect velocity on Y axis
            if (vel.y < 0.0f)
            {
                vel.y = -vel.y * body.GetRestitution();

                // basic friction approximation
                vel.x *= 0.98f;
                vel.z *= 0.98f;
            }

            body.SetPosition(pos);
            body.SetVelocity(vel);
        }
    }

private:
    std::vector<std::unique_ptr<RigidBody>> m_bodies;
    Vec3 m_gravity;
    float m_groundHeight;
};
