## 4) `CustomPhysicsPlugin.cpp`

```cpp
#include "CustomPhysicsPlugin.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f)
    {
    }

    void PhysicsWorld::SetGravity(const Vector3& gravity)
    {
        m_gravity = gravity;
    }

    const Vector3& PhysicsWorld::GetGravity() const
    {
        return m_gravity;
    }

    std::size_t PhysicsWorld::CreateBody(const Rigidbody& body)
    {
        m_bodies.push_back(body);
        return m_bodies.size() - 1;
    }

    Rigidbody& PhysicsWorld::GetBody(std::size_t index)
    {
        return m_bodies.at(index);
    }

    const Rigidbody& PhysicsWorld::GetBody(std::size_t index) const
    {
        return m_bodies.at(index);
    }

    void PhysicsWorld::RemoveBody(std::size_t index)
    {
        if (index < m_bodies.size())
        {
            m_bodies.erase(m_bodies.begin() + static_cast<long>(index));
        }
    }

    void PhysicsWorld::StepSimulation(float deltaTime)
    {
        if (deltaTime <= 0.0f)
            return;

        for (auto& body : m_bodies)
        {
            IntegrateBody(body, deltaTime);
            ResolveGroundPlane(body);
            body.ClearForces();
        }
    }

    void PhysicsWorld::Clear()
    {
        m_bodies.clear();
    }

    std::size_t PhysicsWorld::GetBodyCount() const
    {
        return m_bodies.size();
    }

    void PhysicsWorld::IntegrateBody(Rigidbody& body, float dt)
    {
        if (body.isStatic || body.inverseMass <= 0.0f)
            return;

        // Semi-implicit Euler integration
        const Vector3 acceleration = m_gravity + (body.accumulatedForce * body.inverseMass);
        body.velocity += acceleration * dt;
        body.position += body.velocity * dt;
    }

    void PhysicsWorld::ResolveGroundPlane(Rigidbody& body)
    {
        // Simple collision with Y=0 plane
        if (body.position.y < 0.0f)
        {
            body.position.y = 0.0f;

            if (body.velocity.y < 0.0f)
                body.velocity.y = -body.velocity.y * 0.4f; // restitution
        }
    }

    bool CustomPhysicsPlugin::Startup()
    {
        if (m_initialized)
            return true;

        m_world = std::make_unique<PhysicsWorld>();
        m_initialized = (m_world != nullptr);
        return m_initialized;
    }

    void CustomPhysicsPlugin::Shutdown()
    {
        m_world.reset();
        m_initialized = false;
    }

    PhysicsWorld& CustomPhysicsPlugin::GetWorld()
    {
        return *m_world;
    }
}
