#include "RigidBody.h"

void RigidBody::SetMass(float m)
{
    mass = (m <= 0.0f) ? 1.0f : m;
    invMass = 1.0f / mass;
    if (isStatic)
        invMass = 0.0f;
}

void RigidBody::AddForce(const Vec3& force)
{
    accumulatedForce += force;
}

void RigidBody::Integrate(float dt)
{
    if (isStatic || invMass <= 0.0f)
    {
        accumulatedForce = {};
        velocity = {};
        return;
    }

    // Basic semi-implicit Euler integration
    Vec3 acceleration = accumulatedForce * invMass;
    velocity += acceleration * dt;
    position += velocity * dt;

    accumulatedForce = {};
}
