#include "PhysicsWorld.h"
#include <stdexcept>

void PhysicsWorld::SetGravity(const Vec3& gravity)
{
    gravity_ = gravity;
}

int PhysicsWorld::CreateBody(const RigidBody& body)
{
    bodies_.push_back(body);
    return static_cast<int>(bodies_.size() - 1);
}

RigidBody& PhysicsWorld::GetBody(int id)
{
    return bodies_.at(id);
}

const RigidBody& PhysicsWorld::GetBody(int id) const
{
    return bodies_.at(id);
}

void PhysicsWorld::ApplyGravity()
{
    for (auto& body : bodies_)
    {
        if (!body.isStatic && body.invMass > 0.0f)
        {
            body.AddForce(gravity_ * body.mass);
        }
    }
}

void PhysicsWorld::ResolveGroundPlaneCollision(RigidBody& body)
{
    // Placeholder collision: infinite ground plane at y=0
    if (body.position.y < 0.0f)
    {
        body.position.y = 0.0f;

        if (body.velocity.y < 0.0f)
        {
            body.velocity.y = -body.velocity.y * body.restitution;
        }
    }
}

void PhysicsWorld::Step(float dt)
{
    ApplyGravity();

    for (auto& body : bodies_)
    {
        body.Integrate(dt);
        ResolveGroundPlaneCollision(body);
    }
}
