```cpp
#include "CustomPhysicsAPI.h"
#include "PhysicsWorld.h"
#include <memory>

struct PhysicsHandle
{
    PhysicsWorld world;
};

PhysicsHandle* Physics_Create()
{
    return new PhysicsHandle{};
}

void Physics_Destroy(PhysicsHandle* handle)
{
    delete handle;
}

void Physics_SetGravity(PhysicsHandle* handle, float x, float y, float z)
{
    if (!handle) return;
    handle->world.SetGravity({x, y, z});
}

int Physics_CreateRigidBody(PhysicsHandle* handle,
                            float px, float py, float pz,
                            float vx, float vy, float vz,
                            float mass,
                            bool isStatic)
{
    if (!handle) return -1;

    RigidBody body;
    body.position = {px, py, pz};
    body.velocity = {vx, vy, vz};
    body.isStatic = isStatic;
    body.SetMass(mass);

    return handle->world.CreateBody(body);
}

void Physics_Step(PhysicsHandle* handle, float dt)
{
    if (!handle) return;
    handle->world.Step(dt);
}

void Physics_GetBodyPosition(PhysicsHandle* handle, int id, float* x, float* y, float* z)
{
    if (!handle || !x || !y || !z) return;

    const auto& pos = handle->world.GetBody(id).position;
    *x = pos.x;
    *y = pos.y;
    *z = pos.z;
}
```

