#include "CustomPhysicsComponent.h"
#include "GameFramework/Actor.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    PhysicsState.Position = FVector::ZeroVector;
    PhysicsState.Velocity = FVector::ZeroVector;
    PhysicsState.Mass = 1.0f;
    PhysicsState.bSimulate = true;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (AActor* Owner = GetOwner())
    {
        PhysicsState.Position = Owner->GetActorLocation();

        // Optional: sync initial velocity if needed
    }
}

void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!PhysicsState.bSimulate || DeltaTime <= 0.0f)
    {
        return;
    }

    Integrate(DeltaTime);

    if (AActor* Owner = GetOwner())
    {
        Owner->SetActorLocation(PhysicsState.Position);
    }

    ClearForces();
}

void UCustomPhysicsComponent::AddForce(const FVector& Force)
{
    PhysicsState.AccumulatedForce += Force;
}

void UCustomPhysicsComponent::SetVelocity(const FVector& NewVelocity)
{
    PhysicsState.Velocity = NewVelocity;
}

FVector UCustomPhysicsComponent::GetVelocity() const
{
    return PhysicsState.Velocity;
}

void UCustomPhysicsComponent::SetMass(float NewMass)
{
    PhysicsState.Mass = FMath::Max(NewMass, KINDA_SMALL_NUMBER);
}

void UCustomPhysicsComponent::SetSimulate(bool bEnabled)
{
    PhysicsState.bSimulate = bEnabled;
}

FCustomPhysicsState UCustomPhysicsComponent::GetPhysicsState() const
{
    return PhysicsState;
}

void UCustomPhysicsComponent::SetPhysicsState(const FCustomPhysicsState& NewState)
{
    PhysicsState = NewState;
    PhysicsState.Mass = FMath::Max(PhysicsState.Mass, KINDA_SMALL_NUMBER);
}

void UCustomPhysicsComponent::Integrate(float DeltaTime)
{
    const float SafeMass = FMath::Max(PhysicsState.Mass, KINDA_SMALL_NUMBER);

    // Apply gravity as force: F = m * g
    const FVector GravityForce = Gravity * SafeMass;
    const FVector TotalForce = PhysicsState.AccumulatedForce + GravityForce;

    // a = F / m
    const FVector Acceleration = TotalForce / SafeMass;

    // Semi-implicit Euler integration
    PhysicsState.Velocity += Acceleration * DeltaTime;

    // Damping
    const float DampingFactor = FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);
    PhysicsState.Velocity *= DampingFactor;

    PhysicsState.Position += PhysicsState.Velocity * DeltaTime;
}

void UCustomPhysicsComponent::ClearForces()
{
    PhysicsState.AccumulatedForce = FVector::ZeroVector;
}
