## 2) Plugin implementation: `<language>physics_plugin.cpp</language>`

```cpp
#include "physics_plugin.h"

static const float GRAVITY = -9.81f;

void Physics_Init()
{
    // Minimal init: nothing needed
}

void Physics_Shutdown()
{
    // Minimal shutdown: nothing needed
}

void Physics_Step(PhysicsBody* bodies, int count, float dt)
{
    if (!bodies || count <= 0 || dt <= 0.0f)
        return;

    for (int i = 0; i < count; ++i)
    {
        PhysicsBody& b = bodies[i];

        // Apply gravity if mass is positive
        if (b.mass > 0.0f)
        {
            b.vy += GRAVITY * dt;
        }

        // Integrate velocity
        b.x += b.vx * dt;
        b.y += b.vy * dt;
        b.z += b.vz * dt;

        // Very simple ground plane collision at y = 0
        if (b.y < 0.0f)
        {
            b.y = 0.0f;
            if (b.vy < 0.0f)
                b.vy = -b.vy * 0.5f; // bounce damping
        }
    }
}
```

