## 3. Source: `src/CustomPhysics.cpp`

```cpp
#include "CustomPhysics.h"
#include <stdexcept>

static Vec3 operator+(const Vec3& a, const Vec3& b)
{
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 operator-(const Vec3& a, const Vec3& b)
{
    return {a.x - b.x, a.y - b.y, a.z - b.z};
}

static Vec3 operator*(const Vec3& v, float s)
{
    return {v.x * s, v.y * s, v.z * s};
}

PhysicsWorld::PhysicsWorld()
    : gravity{0.0f, -9.81f, 0.0f}
{
}

int PhysicsWorld::addRigidBody(const RigidBody& body)
{
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void PhysicsWorld::applyForce(int bodyId, const Vec3& force)
{
    if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
        throw std::out_of_range("Invalid bodyId");

    bodies[bodyId].force = bodies[bodyId].force + force;
}

void PhysicsWorld::setGravity(const Vec3& g)
{
    gravity = g;
}

void PhysicsWorld::step(float deltaTime)
{
    for (auto& body : bodies)
    {
        if (body.isStatic || body.mass <= 0.0f)
            continue;

        // Add gravity
        Vec3 totalForce = body.force + (gravity * body.mass);

        // a = F / m
        Vec3 acceleration = totalForce * (1.0f / body.mass);

        // Euler integration
        body.velocity = body.velocity + (acceleration * deltaTime);
        body.position = body.position + (body.velocity * deltaTime);

        // Clear per-frame force
        body.force = {0.0f, 0.0f, 0.0f};
    }
}

const RigidBody& PhysicsWorld::getRigidBody(int bodyId) const
{
    if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
        throw std::out_of_range("Invalid bodyId");

    return bodies[bodyId];
}
```

