#include "Components/PrimitiveComponent.h"

UMiniPhysicsComponent::UMiniPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UMiniPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UMiniPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bUseCustomPhysics)
    {
        return;
    }

    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return;
    }

    UPrimitiveComponent* RootPrim = Cast<UPrimitiveComponent>(Owner->GetRootComponent());
    if (!RootPrim)
    {
        return;
    }

    if (!RootPrim->IsSimulatingPhysics())
    {
        return;
    }

    // Apply a simple force every tick.
    RootPrim->AddForce(ConstantForce * RootPrim->GetMass());
}
