# 1) Core physics plugin code

## `PhysicsPlugin.h`
```cpp
#pragma once

#include <vector>

namespace CustomPhysics
{
    struct Vec3
    {
        float x, y, z;

        Vec3() : x(0), y(0), z(0) {}
        Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

        Vec3 operator+(const Vec3& other) const
        {
            return Vec3(x + other.x, y + other.y, z + other.z);
        }

        Vec3 operator-(const Vec3& other) const
        {
            return Vec3(x - other.x, y - other.y, z - other.z);
        }

        Vec3 operator*(float s) const
        {
            return Vec3(x * s, y * s, z * s);
        }

        Vec3& operator+=(const Vec3& other)
        {
            x += other.x; y += other.y; z += other.z;
            return *this;
        }
    };

    struct RigidBody
    {
        Vec3 position;
        Vec3 velocity;
        Vec3 forceAccum;
        float mass;
        bool isStatic;

        RigidBody()
            : position(), velocity(), forceAccum(), mass(1.0f), isStatic(false)
        {}
    };

    class PhysicsWorld
    {
    public:
        PhysicsWorld();

        int AddBody(const RigidBody& body);
        void ApplyForce(int bodyId, const Vec3& force);
        void Step(float deltaTime);

        const RigidBody& GetBody(int bodyId) const;
        RigidBody& GetBody(int bodyId);

        void SetGravity(const Vec3& gravity);

    private:
        std::vector<RigidBody> bodies;
        Vec3 gravity;
    };
}
```

