## `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"
#include <stdexcept>

namespace CustomPhysics
{
    PhysicsWorld::PhysicsWorld()
        : gravity(0.0f, -9.81f, 0.0f)
    {
    }

    int PhysicsWorld::AddBody(const RigidBody& body)
    {
        bodies.push_back(body);
        return static_cast<int>(bodies.size() - 1);
    }

    void PhysicsWorld::ApplyForce(int bodyId, const Vec3& force)
    {
        if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
            throw std::out_of_range("Invalid bodyId");

        if (!bodies[bodyId].isStatic)
            bodies[bodyId].forceAccum += force;
    }

    void PhysicsWorld::Step(float deltaTime)
    {
        for (auto& body : bodies)
        {
            if (body.isStatic)
                continue;

            // Gravity force
            Vec3 totalForce = body.forceAccum + gravity * body.mass;

            // a = F / m
            Vec3 acceleration = totalForce * (1.0f / body.mass);

            // Semi-explicit Euler integration
            body.velocity += acceleration * deltaTime;
            body.position += body.velocity * deltaTime;

            // Clear forces
            body.forceAccum = Vec3(0.0f, 0.0f, 0.0f);
        }
    }

    const RigidBody& PhysicsWorld::GetBody(int bodyId) const
    {
        if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
            throw std::out_of_range("Invalid bodyId");

        return bodies[bodyId];
    }

    RigidBody& PhysicsWorld::GetBody(int bodyId)
    {
        if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
            throw std::out_of_range("Invalid bodyId");

        return bodies[bodyId];
    }

    void PhysicsWorld::SetGravity(const Vec3& g)
    {
        gravity = g;
    }
}
