## `PhysicsPluginAPI.cpp`
```cpp
#define PHYSICS_PLUGIN_EXPORTS
#include "PhysicsPluginAPI.h"
#include "PhysicsPlugin.h"

using namespace CustomPhysics;

extern "C"
{
    PhysicsWorldHandle Physics_CreateWorld()
    {
        return new PhysicsWorld();
    }

    void Physics_DestroyWorld(PhysicsWorldHandle world)
    {
        delete static_cast<PhysicsWorld*>(world);
    }

    int Physics_AddBody(
        PhysicsWorldHandle world,
        PhysicsVec3 position,
        PhysicsVec3 velocity,
        float mass,
        int isStatic)
    {
        PhysicsWorld* w = static_cast<PhysicsWorld*>(world);

        RigidBody body;
        body.position = Vec3(position.x, position.y, position.z);
        body.velocity = Vec3(velocity.x, velocity.y, velocity.z);
        body.mass = mass;
        body.isStatic = (isStatic != 0);

        return w->AddBody(body);
    }

    void Physics_Step(PhysicsWorldHandle world, float deltaTime)
    {
        static_cast<PhysicsWorld*>(world)->Step(deltaTime);
    }

    PhysicsVec3 Physics_GetBodyPosition(PhysicsWorldHandle world, int bodyId)
    {
        const RigidBody& body = static_cast<PhysicsWorld*>(world)->GetBody(bodyId);
        return PhysicsVec3{ body.position.x, body.position.y, body.position.z };
    }

    void Physics_SetGravity(PhysicsWorldHandle world, PhysicsVec3 gravity)
    {
        static_cast<PhysicsWorld*>(world)->SetGravity(Vec3(gravity.x, gravity.y, gravity.z));
    }
}
