## 2. Plugin implementation (`PhysicsPlugin.cpp`)
```cpp
#define PHYSICSPLUGIN_EXPORTS
#include "PhysicsPlugin.h"

#include <vector>
#include <mutex>

static std::vector<PhysicsBody> g_bodies;
static std::mutex g_mutex;
static bool g_initialized = false;

void PhysicsPlugin_Init() {
    std::lock_guard<std::mutex> lock(g_mutex);
    g_bodies.clear();
    g_initialized = true;
}

void PhysicsPlugin_Shutdown() {
    std::lock_guard<std::mutex> lock(g_mutex);
    g_bodies.clear();
    g_initialized = false;
}

int PhysicsPlugin_CreateBody(PhysicsVec3 position, PhysicsVec3 velocity, float mass, int isStatic) {
    std::lock_guard<std::mutex> lock(g_mutex);
    if (!g_initialized) return -1;

    PhysicsBody body;
    body.position = position;
    body.velocity = velocity;
    body.mass = mass;
    body.isStatic = isStatic;

    g_bodies.push_back(body);
    return static_cast<int>(g_bodies.size() - 1);
}

void PhysicsPlugin_DestroyBody(int bodyId) {
    std::lock_guard<std::mutex> lock(g_mutex);
    if (bodyId < 0 || bodyId >= static_cast<int>(g_bodies.size())) return;

    g_bodies[bodyId].isStatic = 1;
    g_bodies[bodyId].mass = 0.0f;
    g_bodies[bodyId].velocity = {0.0f, 0.0f, 0.0f};
}

void PhysicsPlugin_StepSimulation(float deltaTime) {
    std::lock_guard<std::mutex> lock(g_mutex);
    if (!g_initialized) return;

    const PhysicsVec3 gravity = {0.0f, -9.81f, 0.0f};

    for (auto& body : g_bodies) {
        if (body.isStatic) continue;

        // a = F / m, with gravity as acceleration here
        body.velocity.x += gravity.x * deltaTime;
        body.velocity.y += gravity.y * deltaTime;
        body.velocity.z += gravity.z * deltaTime;

        body.position.x += body.velocity.x * deltaTime;
        body.position.y += body.velocity.y * deltaTime;
        body.position.z += body.velocity.z * deltaTime;
    }
}

PhysicsBody PhysicsPlugin_GetBody(int bodyId) {
    std::lock_guard<std::mutex> lock(g_mutex);
    PhysicsBody empty = {{0,0,0}, {0,0,0}, 0.0f, 1};

    if (bodyId < 0 || bodyId >= static_cast<int>(g_bodies.size())) return empty;
    return g_bodies[bodyId];
}
```

