#include "PhysicsPlugin.h"
#include <iostream>

int main() {
    PhysicsPlugin_Init();

    PhysicsVec3 pos = {0.0f, 10.0f, 0.0f};
    PhysicsVec3 vel = {0.0f, 0.0f, 0.0f};

    int bodyId = PhysicsPlugin_CreateBody(pos, vel, 1.0f, 0);

    for (int i = 0; i < 60; ++i) {
