Below is a compact **C++ example** of a real-time rigid-body physics loop with **fixed timestep integration** and a **frame-rate cap**. It includes:

- gravity
- simple rigid-body state
- ground collision
- time accumulator for stable simulation
- frame-rate limiting
- interpolated rendering state

This is not a full rigid-body engine, but it is a solid foundation for one.

```cpp
#include <chrono>
#include <cmath>
#include <iostream>
#include <thread>
#include <vector>
#include <algorithm>

using Clock = std::chrono::high_resolution_clock;
using Duration = std::chrono::duration<double>;

struct Vec3 {
    double x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const { return {x + other.x, y + other.y, z + other.z}; }
    Vec3 operator-(const Vec3& other) const { return {x - other.x, y - other.y, z - other.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(double s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
    Vec3& operator-=(const Vec3& other) { x -= other.x; y -= other.y; z -= other.z; return *this; }
    Vec3& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }
};

static Vec3 operator*(double s, const Vec3& v) { return v * s; }

double dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

double length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

Vec3 normalize(const Vec3& v) {
    double len = length(v);
    if (len <= 1e-9) return {0, 0, 0};
    return v / len;
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    double mass;
    double invMass;
    double radius; // simple sphere collision shape

    RigidBody(const Vec3& pos, double m, double r)
        : position(pos), velocity(0,0,0), forceAccum(0,0,0), mass(m), radius(r) {
        invMass = (mass > 0.0) ? 1.0 / mass : 0.0;
    }

    void addForce(const Vec3& f) {
        forceAccum += f;
    }

    void clearForces() {
        forceAccum = {0,0,0};
    }

    void integrate(double dt) {
        if (invMass <= 0.0) return;

        // Semi-implicit Euler integration
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        clearForces();
    }
};

struct PhysicsWorld {
    Vec3 gravity = {0.0, -9.81, 0.0};
    double restitution = 0.6; // bounciness
    std::vector<RigidBody> bodies;

    void step(double dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (body.invMass > 0.0) {
                body.addForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Very simple sphere-ground collision at y = 0
        for (auto& body : bodies) {
            if (body.position.y - body.radius < 0.0) {
                body.position.y = body.radius;

                if (body.velocity.y < 0.0) {
                    body.velocity.y = -body.velocity.y * restitution;

                    // Optional friction/damping on contact
                    body.velocity.x *= 0.98;
                    body.velocity.z *= 0.98;

                    // Sleep small motion to reduce jitter
                    if (std::abs(body.velocity.y) < 0.05) body.velocity.y = 0.0;
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec3{0.0, 10.0, 0.0}, 1.0, 0.5);
    world.bodies.emplace_back(Vec3{2.0, 15.0, 0.0}, 2.0, 0.75);

    // Fixed simulation timestep for stability
    const double fixedDt = 1.0 / 120.0; // 120 Hz physics
    const double maxFrameTime = 0.25;    // clamp to avoid spiral of death
    const double targetFrameTime = 1.0 / 60.0; // frame-rate cap at ~60 FPS

    double accumulator = 0.0;
    auto previousTime = Clock::now();

    for (int frame = 0; frame < 600; ++frame) { // run for a while
        auto frameStart = Clock::now();
        Duration elapsed = frameStart - previousTime;
        previousTime = frameStart;

        double frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        // Multiple fixed physics updates if needed
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Alpha for interpolation if you were rendering between states
        double alpha = accumulator / fixedDt;

        // "Render" output to console
        std::cout << "Frame " << frame
                  << " | alpha=" << alpha
                  << " | body0 pos=(" << world.bodies[0].position.x << ", "
                                      << world.bodies[0].position.y << ", "
                                      << world.bodies[0].position.z << ")"
                  << " vel=(" << world.bodies[0].velocity.x << ", "
                                  << world.bodies[0].velocity.y << ", "
                                  << world.bodies[0].velocity.z << ")\n";

        // Frame-rate cap
        auto frameEnd = Clock::now();
        Duration frameDuration = frameEnd - frameStart;
        double sleepTime = targetFrameTime - frameDuration.count();
        if (sleepTime > 0.0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleepTime));
        }
    }

    return 0;
}
```

### Notes
- Uses a **fixed physics timestep** (`1/120 s`) for stable simulation.
- Uses a **frame-time accumulator** so rendering and physics can run at different rates.
- Clamps very large frame times to prevent instability.
- The collision model here is just **sphere vs. ground plane** for simplicity.

