Below is a **minimal C++ example** of a real-time rigid-body physics simulation loop with **fixed timestep / frame-rate constraints**. It includes:

- basic rigid body state
- gravity
- Euler integration
- simple ground collision
- fixed-update simulation independent of render frame rate

This is **not a full physics engine**—it’s a compact starting point.

```cpp
#include <chrono>
#include <iostream>
#include <thread>
#include <vector>
#include <cmath>

using Clock = std::chrono::high_resolution_clock;
using Duration = std::chrono::duration<double>;

struct Vec3 {
    double x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const { return {x + other.x, y + other.y, z + other.z}; }
    Vec3 operator-(const Vec3& other) const { return {x - other.x, y - other.y, z - other.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }

    Vec3& operator*=(double s) {
        x *= s; y *= s; z *= s;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    double mass;
    double radius;
    bool isStatic = false;

    RigidBody(Vec3 pos, double m, double r)
        : position(pos), velocity(0,0,0), force(0,0,0), mass(m), radius(r) {}

    void applyForce(const Vec3& f) {
        if (!isStatic) force += f;
    }

    void integrate(double dt) {
        if (isStatic) return;

        // a = F / m
        Vec3 acceleration = force * (1.0 / mass);

        // Semi-implicit Euler
        velocity += acceleration * dt;
        position += velocity * dt;

        // Clear accumulated force
        force = Vec3(0, 0, 0);
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0, -9.81, 0.0);
    double groundY = 0.0;
    double restitution = 0.5; // bounce

    void step(double dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (!body.isStatic)
                body.applyForce(gravity * body.mass);
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Very simple collision with ground plane y = groundY
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            double minY = body.position.y - body.radius;
            if (minY < groundY) {
                body.position.y = groundY + body.radius;

                if (body.velocity.y < 0.0) {
                    body.velocity.y = -body.velocity.y * restitution;
                }

                // simple friction damping
                body.velocity.x *= 0.98;
                body.velocity.z *= 0.98;
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    // Dynamic body
    world.bodies.emplace_back(Vec3(0.0, 10.0, 0.0), 1.0, 0.5);

    // Static "ground body" could exist too, but here we use a plane
    double fixedDt = 1.0 / 120.0; // 120 Hz physics update
    double maxFrameTime = 0.25;    // clamp to avoid spiral of death
    double accumulator = 0.0;

    auto previousTime = Clock::now();

    while (true) {
        auto currentTime = Clock::now();
        Duration elapsed = currentTime - previousTime;
        previousTime = currentTime;

        double frameTime = elapsed.count();
        if (frameTime > maxFrameTime) frameTime = maxFrameTime;
        accumulator += frameTime;

        // Fixed timestep simulation
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // "Render" / output state
        const auto& body = world.bodies[0];
        std::cout << "Position: ("
                  << body.position.x << ", "
                  << body.position.y << ", "
                  << body.position.z << ")  "
                  << "Velocity: ("
                  << body.velocity.x << ", "
                  << body.velocity.y << ", "
                  << body.velocity.z << ")\n";

        // Simulate ~60 FPS frame cap
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
```

### Notes
- Uses a **fixed physics timestep** (`1/120`) to keep simulation stable.
- The render/update loop can run at any frame rate.
- This example only handles:
  - gravity
  - ground-plane collision
  - simple bounce
- For real rigid-body dynamics, you’d typically also need:
  - orientation/quaternions
  - angular velocity
  - inertia tensors
  - collision detection between arbitrary shapes
  - constraint solving / impulse resolution

