Below is a compact **C++** example of a simple real-time rigid-body physics loop with **fixed timestep** integration, **gravity**, **collision with the ground**, and **frame-rate independence** via an accumulator. It’s a minimal starting point rather than a full engine.

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}

    Vec3 operator+(const Vec3& other) const { return Vec3{x + other.x, y + other.y, z + other.z}; }
    Vec3 operator-(const Vec3& other) const { return Vec3{x - other.x, y - other.y, z - other.z}; }
    Vec3 operator*(float s) const { return Vec3{x * s, y * s, z * s}; }
    Vec3 operator/(float s) const { return Vec3{x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
    Vec3& operator-=(const Vec3& other) { x -= other.x; y -= other.y; z -= other.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-6f) return Vec3{0, 0, 0};
    return v / len;
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass;
    float invMass;
    float restitution; // bounciness
    float radius;      // simple sphere collider

    RigidBody(Vec3 pos, float m, float r)
        : position(pos), velocity(0,0,0), forceAccum(0,0,0),
          mass(m), restitution(0.5f), radius(r)
    {
        invMass = (mass > 0.0f) ? (1.0f / mass) : 0.0f;
    }

    void addForce(const Vec3& f) {
        forceAccum += f;
    }

    void integrate(float dt) {
        if (invMass <= 0.0f) return; // static body

        // Semi-implicit Euler integration
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        forceAccum = Vec3{0, 0, 0};
    }
};

class PhysicsWorld {
public:
    PhysicsWorld() : gravity(0.0f, -9.81f, 0.0f) {}

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.addForce(gravity * body.mass);
            }
        }

        // Integrate motion
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Handle simple ground collision at y = 0
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }
    }

    std::vector<RigidBody>& getBodies() { return bodies; }

private:
    Vec3 gravity;
    std::vector<RigidBody> bodies;

    void resolveGroundCollision(RigidBody& body) {
        float groundY = 0.0f;
        float minY = groundY + body.radius;

        if (body.position.y < minY) {
            body.position.y = minY;

            // Reflect velocity on collision normal
            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;
            }

            // Very small velocities can cause jitter, so zero them out
            if (std::fabs(body.velocity.y) < 0.05f) {
                body.velocity.y = 0.0f;
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.addBody(RigidBody(Vec3{0.0f, 10.0f, 0.0f}, 1.0f, 0.5f));

    const float fixedDeltaTime = 1.0f / 120.0f; // physics at 120 Hz
    const float maxFrameTime = 0.25f;            // avoid spiral of death
    float accumulator = 0.0f;

    auto previousTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> frameDuration = currentTime - previousTime;
        previousTime = currentTime;

        float frameTime = frameDuration.count();
        if (frameTime > maxFrameTime) frameTime = maxFrameTime;

        accumulator += frameTime;

        while (accumulator >= fixedDeltaTime) {
            world.step(fixedDeltaTime);
            accumulator -= fixedDeltaTime;
        }

        // Render/interpolate placeholder
        const auto& bodies = world.getBodies();
        const auto& b = bodies[0];

        std::cout << "Body position: ("
                  << b.position.x << ", "
                  << b.position.y << ", "
                  << b.position.z << ")\n";

        // Limit output rate a bit for this demo
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
```

