Here’s a compact but reasonably structured **C++** example for a real-time rigid-body simulation loop with frame-rate constraints. It includes:

- fixed-timestep physics
- simple rigid bodies
- gravity
- basic ground collision
- iterative update loop with frame budget awareness

```cpp
#include <chrono>
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using Clock = std::chrono::high_resolution_clock;
using Seconds = std::chrono::duration<double>;

struct Vec3 {
    double x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const { return {x + other.x, y + other.y, z + other.z}; }
    Vec3 operator-(const Vec3& other) const { return {x - other.x, y - other.y, z - other.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(double s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
    Vec3& operator-=(const Vec3& other) { x -= other.x; y -= other.y; z -= other.z; return *this; }
    Vec3& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }
};

static double dot(const Vec3& a, const Vec3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static double length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static Vec3 normalize(const Vec3& v) {
    double len = length(v);
    return (len > 1e-9) ? (v / len) : Vec3{};
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    double mass;
    double invMass;
    double restitution;
    bool isStatic;
    double radius; // simple sphere collider

    RigidBody(const Vec3& pos, double m, double r, bool stat = false)
        : position(pos), velocity{}, forceAccum{},
          mass(m), invMass((stat || m <= 0.0) ? 0.0 : 1.0 / m),
          restitution(0.4), isStatic(stat), radius(r) {}

    void applyForce(const Vec3& f) {
        if (!isStatic) forceAccum += f;
    }

    void integrate(double dt) {
        if (isStatic) return;

        // semi-implicit Euler
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        forceAccum = Vec3{};
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = {0.0, -9.81, 0.0};

    void step(double dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Very simple ground collision: y = 0 plane
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            double bottom = body.position.y - body.radius;
            if (bottom < 0.0) {
                body.position.y = body.radius;

                if (body.velocity.y < 0.0) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // crude friction/damping on impact
                    body.velocity.x *= 0.98;
                    body.velocity.z *= 0.98;

                    // eliminate tiny bounces
                    if (std::abs(body.velocity.y) < 0.2) {
                        body.velocity.y = 0.0;
                    }
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    // A few dynamic rigid bodies
    world.bodies.emplace_back(Vec3{0.0, 8.0, 0.0}, 2.0, 0.5);
    world.bodies.emplace_back(Vec3{1.5, 12.0, 0.0}, 1.0, 0.4);
    world.bodies.emplace_back(Vec3{-2.0, 20.0, 0.0}, 3.0, 0.6);

    // Simulation settings
    const double fixedDt = 1.0 / 120.0;   // 120 Hz physics
    const double targetFrameDt = 1.0 / 60.0; // 60 FPS render/update budget
    const int maxSubsteps = 4;

    double accumulator = 0.0;
    auto prevTime = Clock::now();

    for (int frame = 0; frame < 600; ++frame) { // run ~10 seconds at 60 FPS
        auto now = Clock::now();
        Seconds elapsed = now - prevTime;
        prevTime = now;

        accumulator += elapsed.count();

        // Clamp to avoid spiral of death if frame stalls
        accumulator = std::min(accumulator, targetFrameDt * maxSubsteps);

        int substeps = 0;
        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            ++substeps;
        }

        // Simple "render" output
        std::cout << "Frame " << frame << ":\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " pos=(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " vel=(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }

        // Frame-rate pacing (optional)
        auto frameEnd = Clock::now();
        Seconds frameTime = frameEnd - now;
        double sleepTime = targetFrameDt - frameTime.count();
        if (sleepTime > 0.0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleepTime));
        }
    }

    return 0;
}
