#include <chrono>
#include <cmath>
#include <iostream>
#include <thread>
#include <vector>

using Clock = std::chrono::high_resolution_clock;
using Duration = std::chrono::duration<double>;

struct Vec2 {
    double x = 0.0;
    double y = 0.0;

    Vec2() = default;
    Vec2(double x_, double y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(double s) const { return {x * s, y * s}; }
    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator*=(double s) { x *= s; y *= s; return *this; }
};

double dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

double length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

Vec2 normalize(const Vec2& v) {
    double len = length(v);
    if (len <= 1e-9) return {0.0, 0.0};
    return {v.x / len, v.y / len};
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;
    double mass = 1.0;
    double restitution = 0.5;
    bool isStatic = false;

    void applyForce(const Vec2& f) {
        if (!isStatic) force += f;
    }

    void integrate(double dt) {
        if (isStatic) return;

        Vec2 acceleration = force * (1.0 / mass);
        velocity += acceleration * dt;
        position += velocity * dt;

        force = {0.0, 0.0};
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0, -9.81};
    double groundY = 0.0;

    void step(double dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate motion
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Very simple ground collision
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            if (body.position.y < groundY) {
                body.position.y = groundY;

                if (body.velocity.y < 0.0) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }

                // Small friction-like damping on contact
                body.velocity.x *= 0.98;
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    RigidBody ball;
    ball.position = {0.0, 10.0};
    ball.velocity = {2.0, 0.0};
    ball.mass = 1.0;
    ball.restitution = 0.7;

    world.bodies.push_back(ball);

    // Fixed timestep physics
    const double fixedDt = 1.0 / 120.0;   // 120 Hz physics
    const double maxFrameDt = 0.25;       // clamp large pauses
    const int maxSubSteps = 8;            // prevent runaway catch-up

    auto previousTime = Clock::now();
    double accumulator = 0.0;

    const double targetFrameTime = 1.0 / 60.0; // render target ~60 FPS

    while (true) {
        auto currentTime = Clock::now();
        Duration frameDuration = currentTime - previousTime;
        previousTime = currentTime;

        double frameDt = frameDuration.count();
        if (frameDt > maxFrameDt) frameDt = maxFrameDt;

        accumulator += frameDt;

        int subSteps = 0;
        while (accumulator >= fixedDt && subSteps < maxSubSteps) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            ++subSteps;
        }

        // Interpolation alpha for rendering between physics steps
        double alpha = accumulator / fixedDt;

        // "Render" output to console
        const auto& body = world.bodies[0];
        std::cout << "Ball position: (" << body.position.x << ", " << body.position.y
                  << ")  velocity: (" << body.velocity.x << ", " << body.velocity.y
                  << ")  alpha: " << alpha << "\n";

        // Frame pacing to roughly target 60 FPS
        auto frameEnd = Clock::now();
        Duration elapsed = frameEnd - currentTime;
        double sleepTime = targetFrameTime - elapsed.count();
        if (sleepTime > 0.0) {
            std::this_thread::sleep_for(Duration(sleepTime));
        }
    }

    return 0;
}
