```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <iostream>
#include <chrono>
#include <thread>

struct Vec2 {
    float x, y;

    Vec2() : x(0), y(0) {}
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator-=(const Vec2& other) { x -= other.x; y -= other.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static inline float Dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline float Length(const Vec2& v) {
    return std::sqrt(Dot(v, v));
}

static inline Vec2 Normalize(const Vec2& v) {
    float len = Length(v);
    if (len <= 1e-8f) return {0.0f, 0.0f};
    return v / len;
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float angle = 0.0f;
    float angularVelocity = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float restitution = 0.2f;
    float friction = 0.5f;

    Vec2 halfExtents; // Box shape
    bool isStatic = false;

    void SetMass(float m) {
        mass = m;
        if (m <= 0.0f || isStatic) {
            invMass = 0.0f;
        } else {
            invMass = 1.0f / m;
        }
    }

    void SetBoxInertia(float width, float height) {
        // Box inertia about center: I = m*(w^2 + h^2)/12
        if (isStatic || mass <= 0.0f) {
            inertia = 0.0f;
            invInertia = 0.0f;
            return;
        }
        float w = width;
        float h = height;
        inertia = mass * (w * w + h * h) / 12.0f;
        invInertia = (inertia > 0.0f) ? 1.0f / inertia : 0.0f;
    }
};

struct PhysicsWorld {
    Vec2 gravity = {0.0f, -9.81f};
    std::vector<RigidBody> bodies;

    void Step(float dt) {
        // Semi-implicit Euler integration
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            body.velocity += gravity * dt;
            body.position += body.velocity * dt;
            body.angle += body.angularVelocity * dt;

            ResolveGroundCollision(body);
        }
    }

    void ResolveGroundCollision(RigidBody& body) {
        // Simple ground plane at y = 0
        float bottom = body.position.y - body.halfExtents.y;
        if (bottom >= 0.0f) return;

        float penetration = -bottom;
        body.position.y += penetration;

        // Velocity at contact
        Vec2 normal = {0.0f, 1.0f};
        float vn = Dot(body.velocity, normal);

        if (vn < 0.0f) {
            // Normal impulse (1D against ground)
            float e = body.restitution;
            float j = -(1.0f + e) * vn;
            j *= body.invMass;

            body.velocity += normal * j;

            // Friction impulse
            Vec2 tangent = {1.0f, 0.0f};
            float vt = Dot(body.velocity, tangent);

            float mu = body.friction;
            float frictionImpulse = -vt * body.invMass;
            float maxFriction = mu * j;
            frictionImpulse = std::clamp(frictionImpulse, -maxFriction, maxFriction);

            body.velocity += tangent * frictionImpulse;

            // Simple angular damping on contact
            body.angularVelocity *= 0.98f;
        }

        // Sleep-ish clamp for numerical stability
        if (std::fabs(body.velocity.y) < 0.01f) body.velocity.y = 0.0f;
        if (std::fabs(body.angularVelocity) < 0.001f) body.angularVelocity = 0.0f;
    }
};

// Example fixed timestep loop with frame-rate constraints
int main() {
    PhysicsWorld world;

    RigidBody box;
    box.position = {0.0f, 5.0f};
    box.velocity = {2.0f, 0.0f};
    box.angle = 0.0f;
    box.angularVelocity = 1.0f;
    box.halfExtents = {0.5f, 0.5f};
    box.restitution = 0.4f;
    box.friction = 0.6f;
    box.mass = 1.0f;
    box.SetMass(1.0f);
    box.SetBoxInertia(1.0f, 1.0f);

    world.bodies.push_back(box);

    const float fixedDt = 1.0f / 60.0f;   // simulation step
    const float maxFrameTime = 0.25f;     // avoid spiral of death
    const int maxSubSteps = 5;

    using clock = std::chrono::high_resolution_clock;
    auto lastTime = clock::now();

    for (int frame = 0; frame < 600; ++frame) {
        auto now = clock::now();
        std::chrono::duration<float> elapsed = now - lastTime;
        lastTime = now;

        float frameTime = std::min(elapsed.count(), maxFrameTime);

        static float accumulator = 0.0f;
        accumulator += frameTime;

        int subSteps = 0;
        while (accumulator >= fixedDt && subSteps < maxSubSteps) {
            world.Step(fixedDt);
            accumulator -= fixedDt;
            ++subSteps;
        }

        const RigidBody& b = world.bodies[0];
        std::cout << "pos=(" << b.position.x << ", " << b.position.y
                  << ") vel=(" << b.velocity.x << ", " << b.velocity.y
                  << ") angle=" << b.angle << "\n";

        // Simulate frame pacing (~60 FPS)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
