## C++ implementation

```cpp
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

constexpr float PI = 3.14159265358979323846f;
constexpr float EPSILON = 1e-6f;

// -----------------------------
// Vec2
// -----------------------------
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& rhs) const { return {x + rhs.x, y + rhs.y}; }
    Vec2 operator-(const Vec2& rhs) const { return {x - rhs.x, y - rhs.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }

    Vec2& operator+=(const Vec2& rhs) { x += rhs.x; y += rhs.y; return *this; }
    Vec2& operator-=(const Vec2& rhs) { x -= rhs.x; y -= rhs.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

inline float Dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

inline float LengthSq(const Vec2& v) {
    return Dot(v, v);
}

inline float Length(const Vec2& v) {
    return std::sqrt(LengthSq(v));
}

inline Vec2 Normalize(const Vec2& v) {
    float len = Length(v);
    if (len < EPSILON) return {0.0f, 0.0f};
    return v / len;
}

inline Vec2 Perp(const Vec2& v) {
    return {-v.y, v.x};
}

// 2D scalar cross product
inline float Cross(const Vec2& a, const Vec2& b) {
    return a.x * b.y - a.y * b.x;
}

inline Vec2 Cross(float s, const Vec2& v) {
    return {-s * v.y, s * v.x};
}

inline Vec2 Cross(const Vec2& v, float s) {
    return {s * v.y, -s * v.x};
}

// -----------------------------
// Shapes
// -----------------------------
enum class ShapeType {
    Circle,
    Box
};

struct CircleShape {
    float radius = 1.0f;
};

struct BoxShape {
    float halfWidth = 1.0f;
    float halfHeight = 1.0f;
};

struct Shape {
    ShapeType type;
    CircleShape circle;
    BoxShape box;

    static Shape MakeCircle(float radius) {
        Shape s;
        s.type = ShapeType::Circle;
        s.circle.radius = radius;
        return s;
    }

    static Shape MakeBox(float halfWidth, float halfHeight) {
        Shape s;
        s.type = ShapeType::Box;
        s.box.halfWidth = halfWidth;
        s.box.halfHeight = halfHeight;
        return s;
    }
};

// -----------------------------
// Rigid body
// -----------------------------
struct RigidBody {
    Vec2 position{0.0f, 0.0f};
    float rotation = 0.0f; // radians

    Vec2 velocity{0.0f, 0.0f};
    float angularVelocity = 0.0f;

    Vec2 force{0.0f, 0.0f};
    float torque = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;

    float inertia = 1.0f;
    float invInertia = 1.0f;

    float restitution = 0.2f;
    float friction = 0.5f;

    bool isStatic = false;
    Shape shape;

    void SetMass(float m) {
        mass = m;
        if (isStatic || m <= 0.0f) {
            invMass = 0.0f;
        } else {
            invMass = 1.0f / m;
        }
    }

    void SetInertia(float i) {
        inertia = i;
        if (isStatic || i <= 0.0f) {
            invInertia = 0.0f;
        } else {
            invInertia = 1.0f / i;
        }
    }

    void SetStatic(bool value) {
        isStatic = value;
        if (isStatic) {
            invMass = 0.0f;
            invInertia = 0.0f;
            velocity = {0.0f, 0.0f};
            angularVelocity = 0.0f;
        }
    }

    void ApplyForce(const Vec2& f) {
        force += f;
    }

    void ApplyImpulse(const Vec2& impulse, const Vec2& contactVector) {
        if (invMass == 0.0f) return;
        velocity += impulse * invMass;
        angularVelocity += Cross(contactVector, impulse) * invInertia;
    }

    void IntegrateForces(float dt, const Vec2& gravity) {
        if (invMass == 0.0f) return;
        velocity += (gravity + force * invMass) * (dt * 0.5f);
        angularVelocity += torque * invInertia * (dt * 0.5f);
    }

    void IntegrateVelocity(float dt) {
        if (invMass == 0.0f) return;
        position += velocity * dt;
        rotation += angularVelocity * dt;
    }

    void ClearForces() {
        force = {0.0f, 0.0f};
        torque = 0.0f;
    }
};

// -----------------------------
// Collision data
// -----------------------------
struct Manifold {
    RigidBody* A = nullptr;
    RigidBody* B = nullptr;
    Vec2 normal{0.0f, 0.0f};
    float penetration = 0.0f;
    Vec2 contactPoint{0.0f, 0.0f};
};

static Vec2 Rotate(const Vec2& v, float angle) {
    float c = std::cos(angle);
    float s = std::sin(angle);
    return {v.x * c - v.y * s, v.x * s + v.y * c};
}

static Vec2 GetBoxAxisX(float angle) {
    return Rotate({1.0f, 0.0f}, angle);
}

static Vec2 GetBoxAxisY(float angle) {
    return Rotate({0.0f, 1.0f}, angle);
}

static Vec2 ClampVec2(const Vec2& v, const Vec2& minV, const Vec2& maxV) {
    return {
        std::max(minV.x, std::min(v.x, maxV.x)),
        std::max(minV.y, std::min(v.y, maxV.y))
    };
}

// -----------------------------
// Collision helpers
// -----------------------------
static bool CircleVsCircle(RigidBody& A, RigidBody& B, Manifold& m) {
    Vec2 delta = B.position - A.position;
    float distSq = LengthSq(delta);
    float radius = A.shape.circle.radius + B.shape.circle.radius;

    if (distSq > radius * radius) return false;

    float dist = std::sqrt(std::max(distSq, EPSILON));
    m.A = &A;
    m.B = &B;
    m.normal = (dist > EPSILON) ? (delta / dist) : Vec2{1.0f, 0.0f};
    m.penetration = radius - dist;
    m.contactPoint = A.position + m.normal * (A.shape.circle.radius - m.penetration * 0.5f);
    return true;
}

// Assumes axis-aligned boxes only for this initial implementation.
static bool BoxVsBox(RigidBody& A, RigidBody& B, Manifold& m) {
    const auto& a = A.shape.box;
    const auto& b = B.shape.box;

    float dx = B.position.x - A.position.x;
    float px = (a.halfWidth + b.halfWidth) - std::abs(dx);
    if (px <= 0.0f) return false;

    float dy = B.position.y - A.position.y;
    float py = (a.halfHeight + b.halfHeight) - std::abs(dy);
    if (py <= 0.0f) return false;

    m.A = &A;
    m.B = &B;

    if (px < py) {
        m.normal = (dx < 0.0f) ? Vec2{-1.0f, 0.0f} : Vec2{1.0f, 0.0f};
        m.penetration = px;
    } else {
        m.normal = (dy < 0.0f) ? Vec2{0.0f, -1.0f} : Vec2{0.0f, 1.0f};
        m.penetration = py;
    }

    m.contactPoint = {(A.position.x + B.position.x) * 0.5f,
                      (A.position.y + B.position.y) * 0.5f};
    return true;
}

static bool CircleVsBox(RigidBody& circleBody, RigidBody& boxBody, Manifold& m) {
    const auto& c = circleBody.shape.circle;
    const auto& b = boxBody.shape.box;

    Vec2 boxMin = {boxBody.position.x - b.halfWidth, boxBody.position.y - b.halfHeight};
    Vec2 boxMax = {boxBody.position.x + b.halfWidth, boxBody.position.y + b.halfHeight};

    Vec2 closest = ClampVec2(circleBody.position, boxMin, boxMax);
    Vec2 delta = circleBody.position - closest;

    float distSq = LengthSq(delta);
    if (distSq > c.radius * c.radius) return false;

    float dist = std::sqrt(std::max(distSq, EPSILON));

    m.A = &circleBody;
    m.B = &boxBody;
    m.normal = (dist > EPSILON) ? Normalize(delta) : Vec2{0.0f, 1.0f};
    m.penetration = c.radius - dist;
    m.contactPoint = closest;
    return true;
}

static bool GenerateManifold(RigidBody& A, RigidBody& B, Manifold& m) {
    if (A.shape.type == ShapeType::Circle && B.shape.type == ShapeType::Circle) {
        return CircleVsCircle(A, B, m);
    }
    if (A.shape.type == ShapeType::Box && B.shape.type == ShapeType::Box) {
        return BoxVsBox(A, B, m);
    }
    if (A.shape.type == ShapeType::Circle && B.shape.type == ShapeType::Box) {
        return CircleVsBox(A, B, m);
    }
    if (A.shape.type == ShapeType::Box && B.shape.type == ShapeType::Circle) {
        bool hit = CircleVsBox(B, A, m);
        if (hit) {
            std::swap(m.A, m.B);
            m.normal *= -1.0f;
        }
        return hit;
    }
    return false;
}

// -----------------------------
// Collision resolution
// -----------------------------
static void PositionalCorrection(Manifold& m) {
    const float percent = 0.8f;
    const float slop = 0.01f;

    float invMassSum = m.A->invMass + m.B->invMass;
    if (invMassSum <= 0.0f) return;

    float correctionMag = std::max(m.penetration - slop, 0.0f) / invMassSum * percent;
    Vec2 correction = m.normal * correctionMag;

    if (m.A->invMass > 0.0f) m.A->position -= correction * m.A->invMass;
    if (m.B->invMass > 0.0f) m.B->position += correction * m.B->invMass;
}

static void ResolveCollision(Manifold& m) {
    RigidBody& A = *m.A;
    RigidBody& B = *m.B;

    Vec2 ra = m.contactPoint - A.position;
    Vec2 rb = m.contactPoint - B.position;

    Vec2 rv = (B.velocity + Cross(B.angularVelocity, rb)) -
              (A.velocity + Cross(A.angularVelocity, ra));

    float contactVel = Dot(rv, m.normal);
    if (contactVel > 0.0f) return;

    float e = std::min(A.restitution, B.restitution);

    float raCrossN = Cross(ra, m.normal);
    float rbCrossN = Cross(rb, m.normal);
    float invMassSum =
        A.invMass + B.invMass +
        (raCrossN * raCrossN) * A.invInertia +
        (rbCrossN * rbCrossN) * B.invInertia;

    if (invMassSum <= 0.0f) return;

    float j = -(1.0f + e) * contactVel;
    j /= invMassSum;

    Vec2 impulse = m.normal * j;
    A.velocity -= impulse * A.invMass;
    A.angularVelocity -= Cross(ra, impulse) * A.invInertia;
    B.velocity += impulse * B.invMass;
    B.angularVelocity += Cross(rb, impulse) * B.invInertia;

    // Friction
    rv = (B.velocity + Cross(B.angularVelocity, rb)) -
         (A.velocity + Cross(A.angularVelocity, ra));

    Vec2 tangent = rv - m.normal * Dot(rv, m.normal);
    tangent = Normalize(tangent);

    float jt = -Dot(rv, tangent);
    jt /= invMassSum;

    float mu = std::sqrt(A.friction * B.friction);

    Vec2 frictionImpulse;
    if (std::abs(jt) < j * mu) {
        frictionImpulse = tangent * jt;
    } else {
        frictionImpulse = tangent * (-j * mu);
    }

    A.velocity -= frictionImpulse * A.invMass;
    A.angularVelocity -= Cross(ra, frictionImpulse) * A.invInertia;
    B.velocity += frictionImpulse * B.invMass;
    B.angularVelocity += Cross(rb, frictionImpulse) * B.invInertia;

    PositionalCorrection(m);
}

// -----------------------------
// Physics world
// -----------------------------
class PhysicsWorld {
public:
    explicit PhysicsWorld(Vec2 gravity = {0.0f, -9.81f})
        : gravity_(gravity) {}

    RigidBody& CreateBody(const Shape& shape, const Vec2& position, float mass, bool isStatic = false) {
        bodies_.push_back(RigidBody{});
        RigidBody& body = bodies_.back();
        body.shape = shape;
        body.position = position;
        body.SetStatic(isStatic);
        body.SetMass(mass);

        // Approximate inertia for initial setup
        if (shape.type == ShapeType::Circle) {
            float r = shape.circle.radius;
            body.SetInertia(0.5f * mass * r * r);
        } else if (shape.type == ShapeType::Box) {
            float w = shape.box.halfWidth * 2.0f;
            float h = shape.box.halfHeight * 2.0f;
            body.SetInertia((mass * (w * w + h * h)) / 12.0f);
        }

        if (isStatic) {
            body.SetStatic(true);
        }
        return body;
    }

    void Step(float dt) {
        if (dt <= 0.0f) return;

        // Integrate forces
        for (auto& body : bodies_) {
            body.IntegrateForces(dt, gravity_);
        }

        // Broad/narrow phase collision detection
        std::vector<Manifold> manifolds;
        for (size_t i = 0; i < bodies_.size(); ++i) {
            for (size_t j = i + 1; j < bodies_.size(); ++j) {
                Manifold m;
                if (GenerateManifold(bodies_[i], bodies_[j], m)) {
                    manifolds.push_back(m);
                }
            }
        }

        // Resolve collisions
        for (auto& m : manifolds) {
            ResolveCollision(m);
        }

        // Integrate velocities
        for (auto& body : bodies_) {
            body.IntegrateVelocity(dt);
            body.IntegrateForces(dt, gravity_); // second half-step for semi-implicit-ish behavior
            body.ClearForces();
        }
    }

    const std::vector<RigidBody>& Bodies() const { return bodies_; }
    std::vector<RigidBody>& Bodies() { return bodies_; }

private:
    Vec2 gravity_;
    std::vector<RigidBody> bodies_;
};

// -----------------------------
// Frame-rate constrained loop
// -----------------------------
int main() {
    PhysicsWorld world({0.0f, -9.81f});

    // Ground
    auto& ground = world.CreateBody(Shape::MakeBox(20.0f, 1.0f), {0.0f, -10.0f}, 0.0f, true);

    // Falling bodies
    auto& circle = world.CreateBody(Shape::MakeCircle(1.0f), {0.0f, 5.0f}, 2.0f, false);
    circle.restitution = 0.6f;
    circle.friction = 0.4f;

    auto& box = world.CreateBody(Shape::MakeBox(1.0f, 1.0f), {2.0f, 8.0f}, 3.0f, false);
    box.restitution = 0.3f;
    box.friction = 0.8f;

    // Fixed timestep setup
    const float fixedDt = 1.0f / 120.0f; // physics at 120 Hz
    const float maxFrameTime = 0.25f;    // clamp large spikes
    float accumulator = 0.0f;

    // Simulated "game loop" example
    // Replace this with your platform's timing system
    for (int frame = 0; frame < 600; ++frame) {
        float frameTime = 1.0f / 60.0f; // pretend actual frame time
        frameTime = std::min(frameTime, maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.Step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render/interpolate here in a real application
        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.Bodies().size(); ++i) {
            const auto& b = world.Bodies()[i];
            std::cout << " Body " << i
                      << " pos=(" << b.position.x << ", " << b.position.y << ")"
                      << " vel=(" << b.velocity.x << ", " << b.velocity.y << ")\n";
        }
        std::cout << "----\n";
    }

    return 0;
}
