struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const { return Vec3(x + other.x, y + other.y, z + other.z); }
    Vec3 operator-(const Vec3& other) const { return Vec3(x - other.x, y - other.y, z - other.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
    Vec3& operator-=(const Vec3& other) { x -= other.x; y -= other.y; z -= other.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-8f) return Vec3(0, 0, 0);
    return v / len;
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass;
    float invMass;
    float radius;   // simple spherical collider
    float restitution;
    bool hasGravity;

    RigidBody(const Vec3& pos, float m, float r, float rest = 0.5f)
        : position(pos), velocity(0, 0, 0), forceAccum(0, 0, 0),
          mass(m), radius(r), restitution(rest), hasGravity(true) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f;
    }

    void addForce(const Vec3& f) {
        forceAccum += f;
    }

    void clearForces() {
        forceAccum = Vec3(0, 0, 0);
    }

    void integrate(float dt) {
        if (invMass <= 0.0f) return;

        // Linear acceleration
        Vec3 acceleration = forceAccum * invMass;

        // Velocity update
        velocity += acceleration * dt;

        // Position update
        position += velocity * dt;

        clearForces();
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (body.hasGravity && body.invMass > 0.0f) {
                body.addForce(gravity * body.mass);
            }
        }

        // Integrate bodies
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Simple collision with ground plane at y = 0
        for (auto& body : bodies) {
            if (body.position.y - body.radius < 0.0f) {
                body.position.y = body.radius;

                // Reflect velocity if moving downward
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // Dampen small bounces
                    if (std::fabs(body.velocity.y) < 0.05f) {
                        body.velocity.y = 0.0f;
                    }
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;

    // Add a few test bodies
    world.addBody(RigidBody(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f, 0.6f));
    world.addBody(RigidBody(Vec3(2.0f, 15.0f, 0.0f), 2.0f, 0.75f, 0.4f));
    world.addBody(RigidBody(Vec3(-2.0f, 20.0f, 0.0f), 0.5f, 0.4f, 0.8f));

    // Fixed timestep simulation settings
    const float fixedDt = 1.0f / 120.0f; // 120 Hz physics
    const float maxFrameTime = 0.25f;     // avoid spiral of death
    const int maxSubsteps = 8;

    using clock = std::chrono::high_resolution_clock;
    auto prevTime = clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto currentTime = clock::now();
        std::chrono::duration<float> frameDuration = currentTime - prevTime;
        prevTime = currentTime;

        float frameTime = std::min(frameDuration.count(), maxFrameTime);
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            substeps++;
        }

        // Output simulation state
        std::cout << "Bodies:\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << "  Body " << i
                      << " Pos(" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                      << " Vel(" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")\n";
        }
        std::cout << "----\n";

        // Simulate ~60 FPS render/update pacing
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
