#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <chrono>
#include <thread>

constexpr float FIXED_DT = 1.0f / 60.0f;   // physics step
constexpr float GRAVITY_Y = -9.81f;
constexpr float RESTITUTION = 0.4f;
constexpr float GROUND_Y = 0.0f;

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    Vec3& operator-=(const Vec3& rhs) { x -= rhs.x; y -= rhs.y; z -= rhs.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-6f) return Vec3(0, 0, 0);
    return v / len;
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;

    float mass;
    float invMass;
    float radius;   // sphere collider for simplicity
    bool isStatic;

    RigidBody(const Vec3& pos, float m, float r, bool stat = false)
        : position(pos), velocity(0, 0, 0), force(0, 0, 0),
          mass(m), radius(r), isStatic(stat)
    {
        invMass = (isStatic || mass <= 0.0f) ? 0.0f : 1.0f / mass;
    }

    void addForce(const Vec3& f) {
        if (!isStatic) force += f;
    }

    void clearForces() {
        force = Vec3(0, 0, 0);
    }

    void integrate(float dt) {
        if (isStatic) return;

        // Semi-implicit Euler integration
        Vec3 acceleration = force * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;
    }
};

// Resolve collision with a horizontal ground plane at y = GROUND_Y
void resolveGroundCollision(RigidBody& body) {
    if (body.isStatic) return;

    float bottom = body.position.y - body.radius;
    if (bottom < GROUND_Y) {
        float penetration = GROUND_Y - bottom;
        body.position.y += penetration;

        // Reflect velocity if falling into the ground
        if (body.velocity.y < 0.0f) {
            body.velocity.y = -body.velocity.y * RESTITUTION;

            // simple friction approximation on horizontal movement
            body.velocity.x *= 0.98f;
            body.velocity.z *= 0.98f;

            // kill tiny bounces
            if (std::fabs(body.velocity.y) < 0.1f) {
                body.velocity.y = 0.0f;
            }
        }
    }
}

// Resolve sphere-sphere collision between two dynamic bodies
void resolveSphereCollision(RigidBody& a, RigidBody& b) {
    if (a.isStatic && b.isStatic) return;

    Vec3 delta = b.position - a.position;
    float dist = length(delta);
    float radii = a.radius + b.radius;

    if (dist >= radii || dist <= 1e-6f) return;

    Vec3 normal = delta / dist;
    float penetration = radii - dist;

    // Positional correction
    float totalInvMass = a.invMass + b.invMass;
    if (totalInvMass > 0.0f) {
        Vec3 correction = normal * (penetration / totalInvMass);
        if (!a.isStatic) a.position -= correction * a.invMass;
        if (!b.isStatic) b.position += correction * b.invMass;
    }

    // Relative velocity
    Vec3 rv = b.velocity - a.velocity;
    float velAlongNormal = dot(rv, normal);

    // If separating, skip impulse
    if (velAlongNormal > 0.0f) return;

    float e = RESTITUTION;
    float j = -(1.0f + e) * velAlongNormal;
    j /= totalInvMass;

    Vec3 impulse = normal * j;
    if (!a.isStatic) a.velocity -= impulse * a.invMass;
    if (!b.isStatic) b.velocity += impulse * b.invMass;
}

struct World {
    std::vector<RigidBody> bodies;
    float accumulator = 0.0f;

    void step(float dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (!body.isStatic) {
                body.addForce(Vec3(0.0f, GRAVITY_Y * body.mass, 0.0f));
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Collisions
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }

        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveSphereCollision(bodies[i], bodies[j]);
            }
        }

        // Clear forces
        for (auto& body : bodies) {
            body.clearForces();
        }
    }
};

int main() {
    World world;

    // Dynamic bodies
    world.bodies.emplace_back(Vec3(0.0f, 5.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(1.0f, 8.0f, 0.0f), 2.0f, 0.5f);

    // Static "floor object" example if needed
    // world.bodies.emplace_back(Vec3(0.0f, -1000.0f, 0.0f), 1.0f, 1000.0f, true);

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();

    float accumulator = 0.0f;
    const float maxFrameTime = 0.25f; // avoid spiral of death

    while (true) {
        auto current = clock::now();
        std::chrono::duration<float> elapsed = current - previous;
        previous = current;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= FIXED_DT) {
            world.step(FIXED_DT);
            accumulator -= FIXED_DT;
        }

        // Render / debug output (placeholder)
        std::cout << "Body 0: y=" << world.bodies[0].position.y
                  << " vy=" << world.bodies[0].velocity.y << "\n";
        std::cout << "Body 1: y=" << world.bodies[1].position.y
