#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec2 {
    float x, y;

    Vec2() : x(0), y(0) {}
    Vec2(float x_, float y_) : x(x_), y(y_) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float s) const { return Vec2(x * s, y * s); }
    Vec2 operator/(float s) const { return Vec2(x / s, y / s); }

    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
    Vec2& operator-=(const Vec2& other) { x -= other.x; y -= other.y; return *this; }
    Vec2& operator*=(float s) { x *= s; y *= s; return *this; }
};

static inline float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

static inline float length(const Vec2& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len > 1e-6f) return v / len;
    return Vec2(0, 0);
}

struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float mass;
    float invMass;
    float restitution;
    float radius; // using circles for simple collision

    RigidBody(const Vec2& pos, float m, float r, float rest = 0.5f)
        : position(pos), velocity(0, 0), force(0, 0),
          mass(m), restitution(rest), radius(r)
    {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;
    }

    void applyForce(const Vec2& f) {
        force += f;
    }

    void integrate(float dt) {
        if (invMass == 0.0f) return; // static body

        Vec2 acceleration = force * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;
        force = Vec2(0, 0);
    }
};

struct PhysicsWorld {
    Vec2 gravity = Vec2(0.0f, -9.81f);
    float groundY = 0.0f;
    std::vector<RigidBody> bodies;

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate motion
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Resolve ground collisions
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }

        // Resolve body-body collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCircleCollision(bodies[i], bodies[j]);
            }
        }
    }

    void resolveGroundCollision(RigidBody& body) {
        float minY = groundY + body.radius;
        if (body.position.y < minY) {
            body.position.y = minY;

            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;
                if (std::fabs(body.velocity.y) < 0.01f) {
                    body.velocity.y = 0.0f;
                }
            }
        }
    }

    void resolveCircleCollision(RigidBody& a, RigidBody& b) {
        Vec2 delta = b.position - a.position;
        float dist = length(delta);
        float minDist = a.radius + b.radius;

        if (dist <= 0.0001f || dist >= minDist) return;

        Vec2 normal = delta / dist;
        float penetration = minDist - dist;

        float invMassSum = a.invMass + b.invMass;
        if (invMassSum <= 0.0f) return;

        // Positional correction to prevent sinking
        const float percent = 0.8f;
        const float slop = 0.001f;
        float correctionMag = std::max(penetration - slop, 0.0f) / invMassSum * percent;
        Vec2 correction = normal * correctionMag;

        a.position -= correction * a.invMass;
        b.position += correction * b.invMass;

        // Relative velocity along normal
        Vec2 relativeVel = b.velocity - a.velocity;
        float velAlongNormal = dot(relativeVel, normal);

        // If separating, skip impulse
        if (velAlongNormal > 0.0f) return;

        float e = std::min(a.restitution, b.restitution);
        float j = -(1.0f + e) * velAlongNormal;
        j /= invMassSum;

        Vec2 impulse = normal * j;
        a.velocity -= impulse * a.invMass;
        b.velocity += impulse * b.invMass;
    }
};

int main() {
    PhysicsWorld world;

    // Add a few dynamic bodies
    world.addBody(RigidBody(Vec2(0.0f, 10.0f), 1.0f, 0.5f, 0.6f));
    world.addBody(RigidBody(Vec2(1.2f, 14.0f), 2.0f, 0.6f, 0.4f));
    world.addBody(RigidBody(Vec2(-1.0f, 18.0f), 1.5f, 0.4f, 0.3f));

    // Fixed timestep loop
    constexpr float fixedDt = 1.0f / 60.0f;
    constexpr float maxFrameTime = 0.25f; // prevent spiral of death
    float accumulator = 0.0f;

    auto lastTime = std::chrono::high_resolution_clock::now();

    for (int frame = 0; frame < 600; ++frame) { // run for ~10 seconds at 60 FPS
        auto currentTime = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> deltaTime = currentTime - lastTime;
        lastTime = currentTime;

        float frameTime = std::min(deltaTime.count(), maxFrameTime);
        accumulator += frameTime;

        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Simple console output
        std::cout << "Frame " << frame << "\n";
        for (size_t i = 0; i < world.bodies.size(); ++i) {
            const auto& b = world.bodies[i];
            std::cout << " Body " << i
                      << " pos=(" << b.position.x << ", " << b.position.y << ")"
                      << " vel=(" << b.velocity.x << ", " << b.velocity.y << ")\n";
        }

        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // simulate frame pacing
    }

    return 0;
}
