Below is a **minimal working C++ example** of a real-time rigid-body-like physics simulation with a **fixed timestep** to respect frame-rate constraints. It simulates simple bodies under gravity, with ground collision and bounce.

It’s not a full physics engine, but it demonstrates the core structure used in real-time simulations:
- fixed update rate
- integration of velocity and position
- collision response
- frame-time accumulation to stay stable under varying render frame rates

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <algorithm>

struct Vec2 {
    float x, y;

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2& operator+=(const Vec2& other) { x += other.x; y += other.y; return *this; }
};

struct Body {
    Vec2 position;
    Vec2 velocity;
    float radius;
    float restitution; // bounciness
};

void integrate(Body& b, float dt) {
    // Gravity
    const Vec2 gravity = {0.0f, -9.81f};

    b.velocity += gravity * dt;
    b.position += b.velocity * dt;
}

void solveGroundCollision(Body& b) {
    const float groundY = 0.0f;

    if (b.position.y - b.radius < groundY) {
        b.position.y = groundY + b.radius;

        if (b.velocity.y < 0.0f) {
            b.velocity.y = -b.velocity.y * b.restitution;
        }
    }
}

int main() {
    std::vector<Body> bodies = {
        {{0.0f, 10.0f}, {2.0f, 0.0f}, 0.5f, 0.8f},
        {{-2.0f, 15.0f}, {1.0f, 0.0f}, 0.75f, 0.6f}
    };

    const float fixedDt = 1.0f / 120.0f; // physics at 120 Hz
    const int maxSubsteps = 5;

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto current = clock::now();
        std::chrono::duration<float> elapsed = current - previous;
        previous = current;

        float frameTime = elapsed.count();
        frameTime = std::min(frameTime, 0.25f); // avoid spiral of death
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            for (auto& b : bodies) {
                integrate(b, fixedDt);
                solveGroundCollision(b);
            }

            accumulator -= fixedDt;
            ++substeps;
        }

        // "Render" / print state
        std::cout << "\r";
        for (size_t i = 0; i < bodies.size(); ++i) {
            std::cout << "Body " << i
                      << " pos=(" << bodies[i].position.x << ", " << bodies[i].position.y << ") "
                      << "vel=(" << bodies[i].velocity.x << ", " << bodies[i].velocity.y << ")   ";
        }
        std::cout.flush();

        // Simulate frame-rate constraint / render loop pacing
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    return 0;
}
```

## How it works
- **Physics runs at a fixed timestep** (`120 Hz`) for stability.
- The main loop may run at ~60 FPS, but physics can do multiple substeps if needed.
- `accumulator` stores leftover time between frames.
- `maxSubsteps` prevents the sim from spending too long trying to catch up.
- Ground collision is handled by clamping position and inverting vertical velocity with restitution.

