#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }
};

static Vec3 operator*(float s, const Vec3& v) { return v * s; }

static float dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static Vec3 cross(const Vec3& a, const Vec3& b) {
    return {
        a.y*b.z - a.z*b.y,
        a.z*b.x - a.x*b.z,
        a.x*b.y - a.y*b.x
    };
}

static float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-8f) return {0, 0, 0};
    return v * (1.0f / len);
}

// Very small quaternion helper for orientation integration
struct Quaternion {
    float w, x, y, z;

    Quaternion operator+(const Quaternion& o) const { return {w + o.w, x + o.x, y + o.y, z + o.z}; }
    Quaternion operator*(float s) const { return {w * s, x * s, y * s, z * s}; }
};

static Quaternion quatMul(const Quaternion& a, const Quaternion& b) {
    return {
        a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z,
        a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
        a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
        a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w
    };
}

static Quaternion normalize(const Quaternion& q) {
    float len = std::sqrt(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
    if (len <= 1e-8f) return {1, 0, 0, 0};
    float inv = 1.0f / len;
    return {q.w * inv, q.x * inv, q.y * inv, q.z * inv};
}

struct RigidBody {
    Vec3 position {0, 5, 0};
    Vec3 velocity {0, 0, 0};

    Quaternion orientation {1, 0, 0, 0};
    Vec3 angularVelocity {0, 0, 0};

    float mass = 1.0f;
    float restitution = 0.6f; // bounciness

    // Simplified inertia for a unit cube-like body
    float inertia = 1.0f;
};

void integrate(RigidBody& body, float dt) {
    // Linear motion
    const Vec3 gravity {0.0f, -9.81f, 0.0f};
    body.velocity += gravity * dt;
    body.position += body.velocity * dt;

    // Angular motion (very simplified)
    Quaternion omega {0, body.angularVelocity.x, body.angularVelocity.y, body.angularVelocity.z};
    Quaternion qdot = quatMul(body.orientation, omega) * 0.5f;
    body.orientation = normalize(body.orientation + qdot * dt);

    // Ground collision at y = 0
    if (body.position.y < 0.0f) {
        body.position.y = 0.0f;
        if (body.velocity.y < 0.0f) {
            body.velocity.y = -body.velocity.y * body.restitution;

            // Simple friction-like damping on bounce
            body.velocity.x *= 0.85f;
            body.velocity.z *= 0.85f;

            // Angular damping on contact
            body.angularVelocity.x *= 0.9f;
            body.angularVelocity.z *= 0.9f;
        }

        // Stop tiny jitter
        if (std::abs(body.velocity.y) < 0.1f) body.velocity.y = 0.0f;
    }
}

int main() {
    RigidBody body;
    body.position = {0, 10, 0};
    body.velocity = {2, 0, 0};
    body.angularVelocity = {0.0f, 1.5f, 0.0f};

    const float fixedDt = 1.0f / 60.0f; // 60 Hz simulation
    const int maxSubSteps = 5;

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();
    float accumulator = 0.0f;

    for (int frame = 0; frame < 600; ++frame) { // run for ~10 seconds at 60 FPS
        auto now = clock::now();
        std::chrono::duration<float> elapsed = now - previous;
        previous = now;

        // Clamp large frame gaps to avoid spiral of death
        float frameTime = std::min(elapsed.count(), 0.25f);
        accumulator += frameTime;

        int steps = 0;
        while (accumulator >= fixedDt && steps < maxSubSteps) {
            integrate(body, fixedDt);
            accumulator -= fixedDt;
            ++steps;
        }

        // Minimal "render" output
        std::cout
            << "pos=(" << body.position.x << ", "
                      << body.position.y << ", "
                      << body.position.z << ") "
            << "vel=(" << body.velocity.x << ", "
                      << body.velocity.y << ", "
                      << body.velocity.z << ")\n";

        // Frame-rate constraint: simulate ~60 FPS output
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

