## C++ example

```cpp
#include <chrono>
#include <cmath>
#include <iostream>
#include <thread>
#include <vector>

struct Vec3 {
    float x, y, z;

    Vec3 operator+(const Vec3& other) const {
        return {x + other.x, y + other.y, z + other.z};
    }

    Vec3 operator-(const Vec3& other) const {
        return {x - other.x, y - other.y, z - other.z};
    }

    Vec3 operator*(float s) const {
        return {x * s, y * s, z * s};
    }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    float restitution; // bounciness
    float radius;      // treat as sphere for collision
};

static const Vec3 GRAVITY = {0.0f, -9.81f, 0.0f};
static const float FIXED_DT = 1.0f / 120.0f;   // physics at 120 Hz
static const float FRAME_DT  = 1.0f / 60.0f;   // target frame rate 60 FPS

void integrate(RigidBody& body, float dt) {
    // Accumulate gravity
    body.force += GRAVITY * body.mass;

    // Semi-implicit Euler integration
    Vec3 acceleration = body.force * (1.0f / body.mass);
    body.velocity += acceleration * dt;
    body.position += body.velocity * dt;

    // Clear force
    body.force = {0.0f, 0.0f, 0.0f};
}

void resolveGroundCollision(RigidBody& body) {
    float groundY = 0.0f;

    if (body.position.y - body.radius < groundY) {
        // Push body out of the ground
        body.position.y = groundY + body.radius;

        // Bounce if moving downward
        if (body.velocity.y < 0.0f) {
            body.velocity.y = -body.velocity.y * body.restitution;
        }

        // Simple damping to reduce endless jitter
        if (std::fabs(body.velocity.y) < 0.05f) {
            body.velocity.y = 0.0f;
        }
    }
}

int main() {
    RigidBody ball;
    ball.position = {0.0f, 5.0f, 0.0f};
    ball.velocity = {2.0f, 0.0f, 0.0f};
    ball.force = {0.0f, 0.0f, 0.0f};
    ball.mass = 1.0f;
    ball.restitution = 0.8f;
    ball.radius = 0.5f;

    using clock = std::chrono::steady_clock;
    auto previousTime = clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto frameStart = clock::now();
        std::chrono::duration<float> deltaTime = frameStart - previousTime;
        previousTime = frameStart;

        accumulator += deltaTime.count();

        // Fixed timestep simulation
        while (accumulator >= FIXED_DT) {
            integrate(ball, FIXED_DT);
            resolveGroundCollision(ball);
            accumulator -= FIXED_DT;
        }

        // Output current state
        std::cout << "Pos: (" 
                  << ball.position.x << ", "
                  << ball.position.y << ", "
                  << ball.position.z << ")  Vel: ("
                  << ball.velocity.x << ", "
                  << ball.velocity.y << ", "
                  << ball.velocity.z << ")\n";

        // Frame-rate cap
        auto frameEnd = clock::now();
        std::chrono::duration<float> elapsed = frameEnd - frameStart;
        float sleepTime = FRAME_DT - elapsed.count();

        if (sleepTime > 0.0f) {
            std::this_thread::sleep_for(std::chrono::duration<float>(sleepTime));
        }
    }

    return 0;
}
```

---

## How it works

### 1. Fixed timestep
Physics is advanced in small fixed steps:
```cpp
while (accumulator >= FIXED_DT)
```
This gives more stable simulation than using variable delta time directly.

### 2. Gravity and integration
Each step:
- gravity is applied
- velocity is updated
- position is updated

This uses **semi-implicit Euler**, which is simple and commonly used in basic real-time simulation.

### 3. Ground collision
The ball is treated like a sphere:
- if it goes below the ground plane
- it is moved back up
- vertical velocity is reflected and reduced by restitution

### 4. Frame-rate constraint
The loop sleeps if it finishes early enough to maintain roughly 60 FPS.

