// PaymentProcessor.java
import java.time.Instant;

public class PaymentProcessor {
    private final PaymentRepository repository;
    private final LedgerService ledgerService;
    private final AuditService auditService;

    public PaymentProcessor(PaymentRepository repository,
                            LedgerService ledgerService,
                            AuditService auditService) {
        this.repository = repository;
        this.ledgerService = ledgerService;
        this.auditService = auditService;
    }

    public PaymentRecord process(PaymentRequest request) {
        request.validate();

        if (repository.existsByIdempotencyKey(request.getIdempotencyKey())) {
            auditService.record("PAYMENT_DUPLICATE", request.getPaymentId(),
                    "Duplicate request ignored due to idempotency key");
            return repository.findByPaymentId(request.getPaymentId())
                    .orElseThrow(() -> new IllegalStateException("Idempotent record missing"));
        }

        auditService.record("PAYMENT_RECEIVED", request.getPaymentId(), "Request received");

        try {
            PaymentRecord record = new PaymentRecord(
                    request.getPaymentId(),
                    request.getAccountId(),
                    request.getMerchantId(),
                    request.getAmount(),
                    request.getCurrency(),
                    PaymentStatus.VALIDATED,
                    Instant.now()
            );

            repository.save(record);
            auditService.record("PAYMENT_VALIDATED", request.getPaymentId(), "Validation complete");

            ledgerService.postDebit(request.getAccountId(), request.getAmount(), request.getCurrency(), request.getPaymentId());
            auditService.record("PAYMENT_DEBIT_POSTED", request.getPaymentId(), "Debit posted");

            ledgerService.postCredit(request.getMerchantId(), request.getAmount(), request.getCurrency(), request.getPaymentId());
            auditService.record("PAYMENT_CREDIT_POSTED", request.getPaymentId(), "Credit posted");

            PaymentRecord settled = new PaymentRecord(
                    request.getPaymentId(),
                    request.getAccountId(),
                    request.getMerchantId(),
                    request.getAmount(),
                    request.getCurrency(),
                    PaymentStatus.SETTLED,
                    Instant.now()
            );

            repository.save(settled);
            auditService.record("PAYMENT_SETTLED", request.getPaymentId(), "Payment settled");

            return settled;
        } catch (Exception e) {
            auditService.record("PAYMENT_FAILED", request.getPaymentId(), e.getMessage());
            throw new RuntimeException("Payment processing failed", e);
        }
    }
}
```

