```java
package com.example.payments;

import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;
    private final PaymentGateway paymentGateway;

    public PaymentService(PaymentRepository paymentRepository, PaymentGateway paymentGateway) {
        this.paymentRepository = paymentRepository;
        this.paymentGateway = paymentGateway;
    }

    public PaymentResponse process(PaymentRequest request) {
        validate(request);

        // Idempotency: return the original result if we've already processed this key.
        var existing = paymentRepository.findByIdempotencyKey(request.idempotencyKey());
        if (existing.isPresent()) {
            Payment payment = existing.get();
            return new PaymentResponse(
                    payment.getPaymentId(),
                    payment.getStatus(),
                    payment.getAmount(),
                    payment.getCurrency(),
                    "Idempotent replay"
            );
        }

        Payment payment = new Payment(
                UUID.randomUUID().toString(),
                request.idempotencyKey(),
                request.accountId(),
                request.amount(),
                request.currency().toUpperCase(),
                PaymentStatus.PENDING,
                Instant.now()
        );

        paymentRepository.save(payment);

        GatewayResult result = paymentGateway.authorize(
                request.paymentMethodToken(),
                request.currency(),
                request.amount()
        );

        if (result.approved()) {
            payment.setStatus(PaymentStatus.AUTHORIZED);
            paymentRepository.save(payment);
            return new PaymentResponse(
                    payment.getPaymentId(),
                    payment.getStatus(),
                    payment.getAmount(),
                    payment.getCurrency(),
                    "Authorized: " + result.referenceId()
            );
        } else {
            payment.setStatus(PaymentStatus.DECLINED);
            paymentRepository.save(payment);
            return new PaymentResponse(
                    payment.getPaymentId(),
                    payment.getStatus(),
                    payment.getAmount(),
                    payment.getCurrency(),
                    "Declined: " + result.reason()
            );
        }
    }

    private void validate(PaymentRequest request) {
        if (request == null) throw new IllegalArgumentException("Request is required");
        if (isBlank(request.idempotencyKey())) throw new IllegalArgumentException("Idempotency key is required");
        if (isBlank(request.accountId())) throw new IllegalArgumentException("Account ID is required");
        if (request.amount() == null || request.amount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be greater than zero");
        }
        if (isBlank(request.currency()) || request.currency().length() != 3) {
            throw new IllegalArgumentException("Currency must be a 3-letter code");
        }
        if (isBlank(request.paymentMethodToken())) throw new IllegalArgumentException("Payment method token is required");
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}
```

