```java
package com.example.payments;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/payments")
public class PaymentController {

    private static final Logger log = LoggerFactory.getLogger(PaymentController.class);
    private final PaymentService paymentService = new PaymentService();

    @PostMapping
    public ResponseEntity<PaymentResponse> createPayment(
            @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
            @Valid @RequestBody PaymentRequest request) {

        if (idempotencyKey == null || idempotencyKey.isBlank()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(PaymentResponse.failed("Missing Idempotency-Key"));
        }

        try {
            PaymentResponse response = paymentService.processPayment(idempotencyKey, request);
            return ResponseEntity.ok(response);
        } catch (PaymentValidationException e) {
            log.warn("Validation failed: {}", e.getMessage());
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(PaymentResponse.failed(e.getMessage()));
        } catch (PaymentRiskException e) {
            log.warn("Risk check failed: {}", e.getMessage());
            return ResponseEntity.status(HttpStatus.FORBIDDEN)
                    .body(PaymentResponse.failed("Payment declined"));
        } catch (Exception e) {
            log.error("Unexpected error processing payment", e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body(PaymentResponse.failed("Internal error"));
        }
    }
}

class PaymentService {
    private static final Logger log = LoggerFactory.getLogger(PaymentService.class);

    // Simple in-memory idempotency store for demo purposes only
    private final Map<String, PaymentResponse> idempotencyStore = new ConcurrentHashMap<>();

    public PaymentResponse processPayment(String idempotencyKey, PaymentRequest request) {
        if (idempotencyStore.containsKey(idempotencyKey)) {
            return idempotencyStore.get(idempotencyKey);
        }

        validateRequest(request);
        runRiskChecks(request);

        // In a real system:
        // 1) persist payment intent
        // 2) create ledger entry
        // 3) call external PSP/gateway
        // 4) handle async confirmation/webhooks
        // 5) reconcile and emit audit events

        String paymentId = UUID.randomUUID().toString();
        PaymentResponse response = PaymentResponse.succeeded(paymentId, "Payment accepted for processing");

        audit("PAYMENT_CREATED", paymentId, request);
        idempotencyStore.put(idempotencyKey, response);

        return response;
    }

    private void validateRequest(PaymentRequest request) {
        if (request.amount == null || request.amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new PaymentValidationException("Amount must be greater than zero");
        }
        if (request.currency == null || request.currency.isBlank()) {
            throw new PaymentValidationException("Currency is required");
        }
        if (request.sourceAccountId == null || request.sourceAccountId.isBlank()) {
            throw new PaymentValidationException("Source account is required");
        }
        if (request.destinationAccountId == null || request.destinationAccountId.isBlank()) {
            throw new PaymentValidationException("Destination account is required");
        }
        if (request.sourceAccountId.equals(request.destinationAccountId)) {
            throw new PaymentValidationException("Source and destination accounts must differ");
        }
    }

    private void runRiskChecks(PaymentRequest request) {
        // Placeholder for fraud/AML/limits screening
        // Example: velocity checks, sanctions screening, balance checks, geolocation anomaly detection
        if (request.amount.compareTo(new BigDecimal("1000000.00")) > 0) {
            throw new PaymentRiskException("Amount exceeds risk threshold");
        }
    }

    private void audit(String eventType, String paymentId, PaymentRequest request) {
        log.info("AUDIT event={} paymentId={} source={} dest={} amount={} currency={} ts={}",
                eventType,
                paymentId,
                request.sourceAccountId,
                request.destinationAccountId,
                request.amount,
                request.currency,
                Instant.now());
    }
}

class PaymentRequest {
    @NotBlank
    public String sourceAccountId;

    @NotBlank
    public String destinationAccountId;

    @NotNull
    @DecimalMin(value = "0.01", inclusive = true)
    public BigDecimal amount;

    @NotBlank
    public String currency;

    public String reference;
}

class PaymentResponse {
    public String paymentId;
    public String status;
    public String message;

    public static PaymentResponse succeeded(String paymentId, String message) {
        PaymentResponse r = new PaymentResponse();
        r.paymentId = paymentId;
        r.status = "ACCEPTED";
        r.message = message;
        return r;
    }

    public static PaymentResponse failed(String message) {
        PaymentResponse r = new PaymentResponse();
        r.paymentId = null;
        r.status = "FAILED";
        r.message = message;
        return r;
    }
}

class PaymentValidationException extends RuntimeException {
    public PaymentValidationException(String message) { super(message); }
}

class PaymentRiskException extends RuntimeException {
    public PaymentRiskException(String message) { super(message); }
}
