## `PaymentService.java`

```java
package com.acme.payments.service;

import com.acme.payments.api.PaymentRequest;
import com.acme.payments.api.PaymentResponse;
import com.acme.payments.domain.Payment;
import com.acme.payments.domain.PaymentStatus;
import com.acme.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.kafka.core.KafkaTemplate;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final KafkaTemplate<String, Object> kafkaTemplate;

    public PaymentService(
            PaymentRepository paymentRepository,
            IdempotencyService idempotencyService,
            KafkaTemplate<String, Object> kafkaTemplate
    ) {
        this.paymentRepository = paymentRepository;
        this.idempotencyService = idempotencyService;
        this.kafkaTemplate = kafkaTemplate;
    }

    @Transactional
    public PaymentResponse createPayment(String idempotencyKey, PaymentRequest request) {
        return idempotencyService.findExisting(idempotencyKey)
                .map(this::toResponse)
                .orElseGet(() -> {
                    Payment payment = new Payment();
                    payment.setIdempotencyKey(idempotencyKey);
                    payment.setExternalReference(request.externalReference());
                    payment.setCurrency(request.currency());
                    payment.setAmount(request.amount());
                    payment.setPayerAccount(request.payerAccount());
                    payment.setPayeeAccount(request.payeeAccount());
                    payment.setStatus(PaymentStatus.PENDING);

                    Payment saved = paymentRepository.save(payment);

                    kafkaTemplate.send("payments.created", saved.getId().toString(), saved.getId().toString());

                    return toResponse(saved);
                });
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPayment(java.util.UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId.toString()));
        return toResponse(payment);
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getExternalReference(),
                payment.getStatus(),
                payment.getCurrency(),
                payment.getAmount(),
                payment.getPayerAccount(),
                payment.getPayeeAccount(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }
}
```

