### `service/PaymentService.java`
```java
package com.acme.payments.service;

import com.acme.payments.api.dto.CreatePaymentRequest;
import com.acme.payments.audit.AuditLogger;
import com.acme.payments.domain.Payment;
import com.acme.payments.domain.PaymentStatus;
import com.acme.payments.repo.PaymentRepository;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository repository;
    private final IdempotencyService idempotencyService;
    private final RiskService riskService;
    private final LedgerService ledgerService;
    private final PaymentProviderClient providerClient;
    private final AuditLogger auditLogger;

    public PaymentService(
            PaymentRepository repository,
            IdempotencyService idempotencyService,
            RiskService riskService,
            LedgerService ledgerService,
            PaymentProviderClient providerClient,
            AuditLogger auditLogger
    ) {
        this.repository = repository;
        this.idempotencyService = idempotencyService;
        this.riskService = riskService;
        this.ledgerService = ledgerService;
        this.providerClient = providerClient;
        this.auditLogger = auditLogger;
    }

    public Payment createPayment(CreatePaymentRequest request) {
        return idempotencyService.findExisting(request.getIdempotencyKey())
                .orElseGet(() -> {
                    Payment payment = new Payment(
                            UUID.randomUUID(),
                            request.getIdempotencyKey(),
                            request.getAccountId(),
                            request.getAmount(),
                            request.getCurrency()
                    );

                    auditLogger.record("PAYMENT_RECEIVED", "paymentId=" + payment.getId());

                    try {
                        payment.markStatus(PaymentStatus.VALIDATED);

                        payment.markStatus(PaymentStatus.PENDING_RISK_CHECK);
                        boolean approved = riskService.approve(payment);
                        if (!approved) {
                            payment.fail("RISK_REJECTED");
                            repository.save(payment);
                            auditLogger.record("PAYMENT_FAILED", "paymentId=" + payment.getId() + " reason=RISK_REJECTED");
                            return payment;
                        }

                        payment.markStatus(PaymentStatus.APPROVED);

                        ledgerService.postReserve(payment);

                        payment.markStatus(PaymentStatus.SUBMITTED);
                        boolean submitted = providerClient.submit(payment);
                        if (!submitted) {
                            payment.fail("SUBMISSION_FAILED");
                            repository.save(payment);
                            auditLogger.record("PAYMENT_FAILED", "paymentId=" + payment.getId() + " reason=SUBMISSION_FAILED");
                            return payment;
                        }

                        payment.markStatus(PaymentStatus.SETTLED);

                        repository.save(payment);
                        auditLogger.record("PAYMENT_SETTLED", "paymentId=" + payment.getId());
                        return payment;

                    } catch (Exception e) {
                        payment.fail("INTERNAL_ERROR");
                        repository.save(payment);
                        auditLogger.record("PAYMENT_FAILED", "paymentId=" + payment.getId() + " reason=INTERNAL_ERROR");
                        return payment;
                    }
                });
    }
}
```

