package com.example.payments.repo;

import com.example.payments.domain.Payment;

import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

public class PaymentRepository {

    private final ConcurrentHashMap<UUID, Payment> store = new ConcurrentHashMap<>();

    public Payment save(Payment payment) {
        store.put(payment.getPaymentId(), payment);
        return payment;
    }

    public Optional<Payment> findById(UUID paymentId) {
        return Optional.ofNullable(store.get(paymentId));
    }

    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        return store.values().stream()
                .filter(p -> idempotencyKey.equals(p.getIdempotencyKey()))
                .findFirst();
    }
}
