package com.example.payments.service;

import com.example.payments.api.dto.CreatePaymentRequest;
import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.repo.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyService idempotencyService;
    private final PaymentProcessor paymentProcessor;
    private final AuditService auditService;

    public PaymentService() {
        this.paymentRepository = new PaymentRepository();
        this.idempotencyService = new InMemoryIdempotencyService(paymentRepository);
        this.paymentProcessor = new InMemoryPaymentProcessor();
        this.auditService = new ConsoleAuditService();
    }

    public Payment createPayment(CreatePaymentRequest request) {
        return idempotencyService.getExistingPayment(request.getIdempotencyKey())
                .orElseGet(() -> {
                    Payment payment = new Payment(
                            UUID.randomUUID(),
                            request.getIdempotencyKey(),
                            request.getCustomerId(),
                            request.getAmount(),
                            request.getCurrency().toUpperCase(),
                            request.getMethod(),
                            PaymentStatus.RECEIVED,
                            Instant.now(),
                            Instant.now()
                    );

                    auditService.recordEvent("PAYMENT_RECEIVED", "paymentId=" + payment.getPaymentId());
                    paymentRepository.save(payment);

                    payment.setStatus(PaymentStatus.VALIDATED);
                    paymentRepository.save(payment);

                    Payment processed = paymentProcessor.process(payment);
                    processed.setUpdatedAt(Instant.now());
                    paymentRepository.save(processed);

                    auditService.recordEvent("PAYMENT_COMPLETED", "paymentId=" + processed.getPaymentId() + ", status=" + processed.getStatus());
                    return processed;
                });
    }
}
```

