# 3) Repository layer

```java
package com.bank.payments.repository;

import com.bank.payments.domain.Payment;
import org.springframework.stereotype.Repository;

import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class PaymentRepository {

    private final ConcurrentHashMap<UUID, Payment> store = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, UUID> idempotencyIndex = new ConcurrentHashMap<>();

    public Optional<Payment> findById(UUID id) {
        return Optional.ofNullable(store.get(id));
    }

    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        UUID id = idempotencyIndex.get(idempotencyKey);
        if (id == null) return Optional.empty();
        return Optional.ofNullable(store.get(id));
    }

    public Payment save(Payment payment) {
        store.put(payment.getId(), payment);
        if (payment.getIdempotencyKey() != null) {
            idempotencyIndex.put(payment.getIdempotencyKey(), payment.getId());
        }
        return payment;
    }
}
```

> Note: This uses in-memory storage for the initial implementation. In production, replace it with a real database and unique constraints on idempotency keys.

