# 4) Service layer

```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;

    public PaymentService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    public Payment createPayment(CreatePaymentRequest request) {
        paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
                .ifPresent(existing -> {
                    throw new DuplicatePaymentException(
                            "Payment with idempotency key already exists: " + request.getIdempotencyKey(),
                            existing
                    );
                });

        Payment payment = new Payment(
                UUID.randomUUID(),
                request.getIdempotencyKey(),
                request.getFromAccount(),
                request.getToAccount(),
                request.getAmount(),
                request.getCurrency().toUpperCase(),
                PaymentStatus.PENDING,
                null,
                Instant.now(),
                Instant.now()
        );

        validateBusinessRules(payment);
        paymentRepository.save(payment);

        // In a real system, you'd publish an event or enqueue for async processing here.
        processPayment(payment);

        return payment;
    }

    public Payment getPayment(UUID id) {
        return paymentRepository.findById(id)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found: " + id));
    }

    private void validateBusinessRules(Payment payment) {
        if (payment.getFromAccount().equals(payment.getToAccount())) {
            throw new InvalidPaymentException("fromAccount and toAccount cannot be the same");
        }
        if (payment.getAmount().signum() <= 0) {
            throw new InvalidPaymentException("amount must be greater than zero");
        }
        if (payment.getCurrency() == null || payment.getCurrency().isBlank()) {
            throw new InvalidPaymentException("currency is required");
        }
    }

    private void processPayment(Payment payment) {
        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setUpdatedAt(Instant.now());
        paymentRepository.save(payment);

        // Placeholder for core banking / ledger / debit-credit logic
        boolean approved = externalRiskAndFundsCheck(payment);

        if (approved) {
            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setUpdatedAt(Instant.now());
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason("Risk/funds check failed");
            payment.setUpdatedAt(Instant.now());
        }

        paymentRepository.save(payment);
    }

    private boolean externalRiskAndFundsCheck(Payment payment) {
        // Stubbed logic: replace with calls to ledger, fraud, AML, sanctions screening, etc.
        return true;
    }
}
