## 6) Service logic

### `service/PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.model.Payment;
import com.example.payments.model.PaymentRequest;
import com.example.payments.model.PaymentStatus;
import com.example.payments.store.PaymentStore;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentStore store;

    public PaymentService(PaymentStore store) {
        this.store = store;
    }

    public Payment submit(PaymentRequest request) {
        // Idempotency: return existing payment if key already seen
        return store.findByIdempotencyKey(request.idempotencyKey())
                .orElseGet(() -> {
                    Instant now = Instant.now();

                    Payment received = new Payment(
                            UUID.randomUUID(),
                            request.idempotencyKey(),
                            request.fromAccount(),
                            request.toAccount(),
                            request.amount(),
                            request.currency().toUpperCase(),
                            PaymentStatus.RECEIVED,
                            now,
                            now
                    );

                    store.save(received);

                    // Minimal simulated processing
                    Payment completed = new Payment(
                            received.paymentId(),
                            received.idempotencyKey(),
                            received.fromAccount(),
                            received.toAccount(),
                            received.amount(),
                            received.currency(),
                            PaymentStatus.COMPLETED,
                            received.createdAt(),
                            Instant.now()
                    );

                    store.save(completed);
                    return completed;
                });
    }

    public Payment getPayment(String paymentId) {
        return store.findByPaymentId(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
    }
}
```

