## 6. Service layer

### `PaymentService.java`

```java
package com.example.payments.service;

import com.example.payments.domain.Payment;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.dto.PaymentRequest;
import com.example.payments.dto.PaymentResponse;
import com.example.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository repository;

    public PaymentService(PaymentRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public PaymentResponse process(PaymentRequest request) {
        return repository.findByIdempotencyKey(request.getIdempotencyKey())
                .map(this::toResponse)
                .orElseGet(() -> {
                    PaymentStatus status = authorize(request);
                    Payment payment = new Payment(
                            UUID.randomUUID(),
                            request.getIdempotencyKey(),
                            request.getFromAccount(),
                            request.getToAccount(),
                            request.getAmount(),
                            request.getCurrency(),
                            Instant.now(),
                            status
                    );
                    repository.save(payment);
                    return toResponse(payment);
                });
    }

    private PaymentStatus authorize(PaymentRequest request) {
        // Minimal placeholder logic:
        // Reject if sender/receiver are the same, otherwise approve.
        if (request.getFromAccount().equals(request.getToAccount())) {
            return PaymentStatus.REJECTED;
        }
        return PaymentStatus.APPROVED;
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getIdempotencyKey(),
                payment.getFromAccount(),
                payment.getToAccount(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getStatus(),
                payment.getCreatedAt()
        );
    }
}
```

