package com.example.payments.service;

import com.example.payments.domain.PaymentRequest;
import com.example.payments.domain.PaymentResponse;
import com.example.payments.domain.PaymentStatus;
import com.example.payments.repo.InMemoryPaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final InMemoryPaymentRepository repository;
    private final PaymentGateway gateway;

    public PaymentService(InMemoryPaymentRepository repository, PaymentGateway gateway) {
        this.repository = repository;
        this.gateway = gateway;
    }

    public PaymentResponse process(String idempotencyKey, PaymentRequest request) {
        return repository.findByIdempotencyKey(idempotencyKey)
                .orElseGet(() -> {
                    PaymentStatus status = gateway.authorize(request);
                    PaymentResponse response = new PaymentResponse(
                            UUID.randomUUID().toString(),
                            status,
                            status == PaymentStatus.APPROVED ? "Payment approved" : "Payment declined",
                            Instant.now()
                    );
                    repository.save(idempotencyKey, response);
                    return response;
                });
    }
}
