package com.example.payments.service;

import com.example.payments.model.PaymentRequest;
import com.example.payments.model.PaymentResponse;
import com.example.payments.model.PaymentStatus;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final InMemoryPaymentStore paymentStore;
    private final IdempotencyStore idempotencyStore;
    private final AuditLogger auditLogger;

    public PaymentService(InMemoryPaymentStore paymentStore,
                          IdempotencyStore idempotencyStore,
                          AuditLogger auditLogger) {
        this.paymentStore = paymentStore;
        this.idempotencyStore = idempotencyStore;
        this.auditLogger = auditLogger;
    }

    public PaymentResponse process(PaymentRequest request) {
        PaymentResponse existing = idempotencyStore.get(request.idempotencyKey());
        if (existing != null) {
            auditLogger.log("payment_idempotent_replay", "idempotencyKey=" + request.idempotencyKey());
            return existing;
        }

        UUID paymentId = UUID.randomUUID();

        // Minimal business rule: reject self-transfer
        if (request.fromAccount().equals(request.toAccount())) {
            PaymentResponse failed = new PaymentResponse(
                    paymentId,
                    PaymentStatus.FAILED,
                    "fromAccount and toAccount cannot be the same",
                    Instant.now()
            );
            paymentStore.save(paymentId, failed);
            idempotencyStore.putIfAbsent(request.idempotencyKey(), failed);
            auditLogger.log("payment_failed", "paymentId=" + paymentId + " reason=self_transfer");
            return failed;
        }

        // For demo purposes, accept and complete immediately
        PaymentResponse completed = new PaymentResponse(
                paymentId,
                PaymentStatus.COMPLETED,
                "Payment processed successfully",
                Instant.now()
        );

        paymentStore.save(paymentId, completed);
        idempotencyStore.putIfAbsent(request.idempotencyKey(), completed);

        auditLogger.log(
                "payment_completed",
                "paymentId=" + paymentId +
                " fromAccount=" + request.fromAccount() +
                " toAccount=" + request.toAccount() +
                " amount=" + request.amount() +
                " currency=" + request.currency()
        );

        return completed;
    }

    public PaymentResponse getPayment(UUID id) {
        return paymentStore.get(id);
    }
}
```

