## 6) Service layer

### `CustomerService.java`

```java
package com.enterprise.customerservice.service;

import com.enterprise.customerservice.dto.CreateCustomerRequest;
import com.enterprise.customerservice.dto.CustomerResponse;
import com.enterprise.customerservice.exception.CustomerNotFoundException;
import com.enterprise.customerservice.model.Customer;
import com.enterprise.customerservice.repository.CustomerRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class CustomerService {

    private final CustomerRepository customerRepository;
    private final CorporateSystemClient corporateSystemClient;

    public CustomerService(CustomerRepository customerRepository,
                           CorporateSystemClient corporateSystemClient) {
        this.customerRepository = customerRepository;
        this.corporateSystemClient = corporateSystemClient;
    }

    @Transactional
    public CustomerResponse createCustomer(CreateCustomerRequest request) {
        var corporateData = corporateSystemClient.fetchCorporateCustomer(request.externalCorporateId());

        Customer customer = new Customer(
                corporateData.externalCorporateId(),
                request.name(),
                corporateData.status()
        );

        Customer saved = customerRepository.save(customer);
        return toResponse(saved);
    }

    @Transactional(readOnly = true)
    public CustomerResponse getCustomer(UUID id) {
        Customer customer = customerRepository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException(id));
        return toResponse(customer);
    }

    private CustomerResponse toResponse(Customer customer) {
        return new CustomerResponse(
                customer.getId(),
                customer.getExternalCorporateId(),
                customer.getName(),
                customer.getStatus()
        );
    }
}
```

