### `CustomerService.java`

```java
package com.example.customerservice.service;

import com.example.customerservice.domain.Customer;
import com.example.customerservice.domain.CustomerStatus;
import com.example.customerservice.dto.CreateCustomerRequest;
import com.example.customerservice.dto.UpdateCustomerRequest;
import com.example.customerservice.exception.CustomerNotFoundException;
import com.example.customerservice.integration.CorporateProfileClient;
import com.example.customerservice.repository.CustomerRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

@Service
public class CustomerService {

    private final CustomerRepository repository;
    private final CorporateProfileClient corporateProfileClient;

    public CustomerService(CustomerRepository repository, CorporateProfileClient corporateProfileClient) {
        this.repository = repository;
        this.corporateProfileClient = corporateProfileClient;
    }

    public Customer create(CreateCustomerRequest request) {
        if (!corporateProfileClient.customerExistsInMaster(request.corporateId())) {
            throw new IllegalArgumentException("Customer not found in corporate master system");
        }

        var now = Instant.now();
        var customer = new Customer(
                UUID.randomUUID(),
                request.corporateId(),
                request.firstName(),
                request.lastName(),
                request.email(),
                CustomerStatus.ACTIVE,
                now,
                now
        );

        return repository.save(customer);
    }

    public Customer getById(UUID id) {
        return repository.findById(id)
                .orElseThrow(() -> new CustomerNotFoundException(id));
    }

    public List<Customer> getAll() {
        return repository.findAll();
    }

    public Customer update(UUID id, UpdateCustomerRequest request) {
        var existing = getById(id);

        var updated = new Customer(
                existing.id(),
                existing.corporateId(),
                request.firstName(),
                request.lastName(),
                request.email(),
                existing.status(),
                existing.createdAt(),
                Instant.now()
        );

        return repository.save(updated);
    }

    public void suspend(UUID id) {
        var existing = getById(id);

        var updated = new Customer(
                existing.id(),
                existing.corporateId(),
                existing.firstName(),
                existing.lastName(),
                existing.email(),
                CustomerStatus.SUSPENDED,
                existing.createdAt(),
                Instant.now()
        );

        repository.save(updated);
    }
}
```

