## Service implementation

```java
package com.enterprise.orderservice.service.impl;

import com.enterprise.orderservice.dto.CreateOrderRequest;
import com.enterprise.orderservice.dto.OrderResponse;
import com.enterprise.orderservice.entity.Order;
import com.enterprise.orderservice.exception.OrderNotFoundException;
import com.enterprise.orderservice.repository.OrderRepository;
import com.enterprise.orderservice.service.CorporateSystemClient;
import com.enterprise.orderservice.service.OrderService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class OrderServiceImpl implements OrderService {

    private final OrderRepository orderRepository;
    private final CorporateSystemClient corporateSystemClient;

    public OrderServiceImpl(OrderRepository orderRepository,
                            CorporateSystemClient corporateSystemClient) {
        this.orderRepository = orderRepository;
        this.corporateSystemClient = corporateSystemClient;
    }

    @Override
    @Transactional
    public OrderResponse createOrder(CreateOrderRequest request) {
        Order order = new Order(request.customerId(), request.amount(), "CREATED");
        Order saved = orderRepository.save(order);

        corporateSystemClient.notifyOrderCreated(saved);

        return toResponse(saved);
    }

    @Override
    @Transactional(readOnly = true)
    public OrderResponse getOrder(UUID id) {
        Order order = orderRepository.findById(id)
                .orElseThrow(() -> new OrderNotFoundException(id));
        return toResponse(order);
    }

    private OrderResponse toResponse(Order order) {
        return new OrderResponse(
                order.getId(),
                order.getCustomerId(),
                order.getAmount(),
                order.getStatus(),
                order.getCreatedAt()
        );
    }
}
```

