using EnterpriseMicroservice.Application.Interfaces;
using EnterpriseMicroservice.Application.Models;
using EnterpriseMicroservice.Domain.Entities;
using EnterpriseMicroservice.Domain.Exceptions;
using EnterpriseMicroservice.Infrastructure.Persistence;

namespace EnterpriseMicroservice.Application.Services;

public sealed class CustomerService : ICustomerService
{
    private readonly ICustomerRepository _repository;
    private readonly ICorporateSystemClient _corporateSystemClient;

    public CustomerService(
        ICustomerRepository repository,
        ICorporateSystemClient corporateSystemClient)
    {
        _repository = repository;
        _corporateSystemClient = corporateSystemClient;
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(request);

        if (string.IsNullOrWhiteSpace(request.ExternalReference))
            throw new ArgumentException("ExternalReference is required.");
        if (string.IsNullOrWhiteSpace(request.FirstName))
            throw new ArgumentException("FirstName is required.");
        if (string.IsNullOrWhiteSpace(request.LastName))
            throw new ArgumentException("LastName is required.");
        if (string.IsNullOrWhiteSpace(request.Email))
            throw new ArgumentException("Email is required.");

        var corporateRecordId = await _corporateSystemClient.CreateExternalCustomerRecordAsync(
            request.ExternalReference,
            request.FirstName,
            request.LastName,
            request.Email,
            cancellationToken);

        var customer = new Customer(
            Guid.NewGuid(),
            corporateRecordId,
            request.FirstName,
            request.LastName,
            request.Email,
            DateTimeOffset.UtcNow);

        await _repository.AddAsync(customer, cancellationToken);

        return new CustomerDto(
            customer.Id,
            customer.ExternalReference,
            customer.FirstName,
            customer.LastName,
            customer.Email,
            customer.CreatedAtUtc);
    }

    public async Task<CustomerDto> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var customer = await _repository.GetByIdAsync(id, cancellationToken);

        if (customer is null)
            throw new NotFoundException($"Customer '{id}' was not found.");

        return new CustomerDto(
            customer.Id,
            customer.ExternalReference,
            customer.FirstName,
            customer.LastName,
            customer.Email,
            customer.CreatedAtUtc);
    }
}
