## 8) Service layer

### `OrderService.java`

```java
package com.enterprise.orders.service;

import com.enterprise.orders.api.OrderCreateRequest;
import com.enterprise.orders.domain.Order;
import com.enterprise.orders.integration.CorporateSystemClient;
import com.enterprise.orders.repository.OrderRepository;
import com.enterprise.orders.exception.OrderNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final CorporateSystemClient corporateSystemClient;

    public OrderService(OrderRepository orderRepository, CorporateSystemClient corporateSystemClient) {
        this.orderRepository = orderRepository;
        this.corporateSystemClient = corporateSystemClient;
    }

    @Transactional
    public Order createOrder(OrderCreateRequest request) {
        Order order = new Order(
                request.customerId(),
                request.productCode(),
                request.quantity()
        );

        Order saved = orderRepository.save(order);

        corporateSystemClient.notifyOrderCreated(saved);

        saved.confirm();
        return saved;
    }

    @Transactional(readOnly = true)
    public Order getOrder(UUID id) {
        return orderRepository.findById(id)
                .orElseThrow(() -> new OrderNotFoundException(id));
    }
}
```

