## 8) Service layer

```java
package com.example.enterprise.service;

import com.example.enterprise.dto.CustomerCreateRequest;
import com.example.enterprise.dto.CustomerResponse;
import com.example.enterprise.entity.Customer;
import com.example.enterprise.repository.CustomerRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;

@Service
public class CustomerService {

    private final CustomerRepository customerRepository;
    private final CorporateSystemClient corporateSystemClient;

    public CustomerService(CustomerRepository customerRepository,
                           CorporateSystemClient corporateSystemClient) {
        this.customerRepository = customerRepository;
        this.corporateSystemClient = corporateSystemClient;
    }

    @Transactional
    public CustomerResponse createCustomer(CustomerCreateRequest request) {
        customerRepository.findByEmail(request.email())
                .ifPresent(existing -> {
                    throw new IllegalArgumentException("Customer with this email already exists");
                });

        Customer customer = new Customer(
                request.firstName().trim(),
                request.lastName().trim(),
                request.email().trim().toLowerCase(),
                Instant.now()
        );

        Customer saved = customerRepository.save(customer);

        corporateSystemClient.notifyCustomerCreated(saved);

        return new CustomerResponse(
                saved.getId(),
                saved.getFirstName(),
                saved.getLastName(),
                saved.getEmail(),
                saved.getCreatedAt()
        );
    }
}
```

