```java
package com.acme.customer.service;

import com.acme.customer.api.exception.NotFoundException;
import com.acme.customer.domain.Customer;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class InMemoryCustomerService implements CustomerService {

    private final ConcurrentHashMap<UUID, Customer> store = new ConcurrentHashMap<>();

    @Override
    public Customer createCustomer(String firstName, String lastName, String email) {
        UUID id = UUID.randomUUID();
        Customer customer = new Customer(id, firstName, lastName, email, Instant.now());
        store.put(id, customer);
        return customer;
    }

    @Override
    public Customer getCustomer(UUID id) {
        Customer customer = store.get(id);
        if (customer == null) {
            throw new NotFoundException("Customer not found: " + id);
        }
        return customer;
    }

    @Override
    public List<Customer> listCustomers() {
        return new ArrayList<>(store.values());
    }
}
```

