        CorporateSystemResult result = corporateSystemClient.syncCustomer(
                request.customerId(),
                request.fullName(),
                request.email()
        );

        if (result.success()) {
            return new CustomerResponse(
                    request.customerId(),
                    "ONBOARDED",
                    "Customer synced successfully. Reference: " + result.referenceId()
            );
        }

        return new CustomerResponse(
                request.customerId(),
                "FAILED",
                "Customer sync failed"
        );
    }
}
