## 7) `Services/CustomerService.cs`

```csharp
using EnterpriseMicroservice.Contracts;
using EnterpriseMicroservice.Domain;
using EnterpriseMicroservice.Integrations;

namespace EnterpriseMicroservice.Services;

public sealed class CustomerService : ICustomerService
{
    private readonly ICorporateSystemClient _corporateSystemClient;

    public CustomerService(ICorporateSystemClient corporateSystemClient)
    {
        _corporateSystemClient = corporateSystemClient;
    }

    public async Task<CustomerResult> ValidateAsync(CustomerRequest request, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerId))
            return new CustomerResult(request.CustomerId, false, "CustomerId is required.");

        if (string.IsNullOrWhiteSpace(request.FullName))
            return new CustomerResult(request.CustomerId, false, "FullName is required.");

        if (string.IsNullOrWhiteSpace(request.Email) || !request.Email.Contains('@'))
            return new CustomerResult(request.CustomerId, false, "A valid email is required.");

        var corporateStatus = await _corporateSystemClient.GetCustomerStatusAsync(request.CustomerId, cancellationToken);

        if (!corporateStatus.Exists)
            return new CustomerResult(request.CustomerId, false, "Customer not found in corporate system.");

        if (!corporateStatus.IsActive)
            return new CustomerResult(request.CustomerId, false, "Customer is inactive in corporate system.");

        return new CustomerResult(request.CustomerId, true, "Customer validation succeeded.");
    }
}
```

