using EnterpriseBackend.Models;
using EnterpriseBackend.Services;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Controllers;

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly IOrderService _orderService;
    private readonly ILogger<OrdersController> _logger;

    public OrdersController(IOrderService orderService, ILogger<OrdersController> logger)
    {
        _orderService = orderService;
        _logger = logger;
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<Order>>> GetAll()
    {
        var orders = await _orderService.GetAllAsync();
        return Ok(orders);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<Order>> GetById(Guid id)
    {
        var order = await _orderService.GetByIdAsync(id);
        if (order is null)
        {
            return NotFound();
        }

        return Ok(order);
    }

    [HttpPost]
    public async Task<ActionResult<Order>> Create([FromBody] Order order)
    {
        if (string.IsNullOrWhiteSpace(order.CustomerName))
        {
            return BadRequest("CustomerName is required.");
        }

        if (order.TotalAmount <= 0)
        {
            return BadRequest("TotalAmount must be greater than zero.");
        }

        var created = await _orderService.CreateAsync(order);

        _logger.LogInformation("Created order {OrderId} for {Customer}", created.Id, created.CustomerName);

        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
}
