```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using System.Collections.Concurrent;

var builder = WebApplication.CreateBuilder(args);

// Services
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();
builder.Services.AddSingleton<IOrderRepository, InMemoryOrderRepository>();
builder.Services.AddScoped<OrderService>();

var app = builder.Build();

// Middleware
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();

// Routes
app.MapGet("/health", () => Results.Ok(new { status = "healthy", utc = DateTime.UtcNow }));

app.MapGet("/orders/{id:guid}", async (Guid id, OrderService service) =>
{
    var order = await service.GetOrderAsync(id);
    return order is null ? Results.NotFound() : Results.Ok(order);
});

app.MapPost("/orders", async ([FromBody] CreateOrderRequest request, OrderService service) =>
{
    var created = await service.CreateOrderAsync(request);
    return Results.Created($"/orders/{created.Id}", created);
});

app.MapPut("/orders/{id:guid}/status", async (Guid id, [FromBody] UpdateOrderStatusRequest request, OrderService service) =>
{
    var updated = await service.UpdateStatusAsync(id, request.Status);
    return updated ? Results.NoContent() : Results.NotFound();
});

app.Run();

// Models
public record CreateOrderRequest(string CustomerId, decimal Amount);
public record UpdateOrderStatusRequest(string Status);

public record Order(Guid Id, string CustomerId, decimal Amount, string Status, DateTime CreatedUtc);

// Repository
public interface IOrderRepository
{
    Task<Order?> GetAsync(Guid id);
    Task AddAsync(Order order);
    Task<bool> UpdateStatusAsync(Guid id, string status);
}

public class InMemoryOrderRepository : IOrderRepository
{
    private readonly ConcurrentDictionary<Guid, Order> _orders = new();

    public Task<Order?> GetAsync(Guid id)
        => Task.FromResult(_orders.TryGetValue(id, out var order) ? order : null);

    public Task AddAsync(Order order)
    {
        _orders[order.Id] = order;
        return Task.CompletedTask;
    }

    public Task<bool> UpdateStatusAsync(Guid id, string status)
    {
        if (!_orders.TryGetValue(id, out var existing))
            return Task.FromResult(false);

        _orders[id] = existing with { Status = status };
        return Task.FromResult(true);
    }
}

// Service
public class OrderService
{
    private readonly IOrderRepository _repository;

    public OrderService(IOrderRepository repository)
    {
        _repository = repository;
    }

    public Task<Order?> GetOrderAsync(Guid id)
        => _repository.GetAsync(id);

    public async Task<Order> CreateOrderAsync(CreateOrderRequest request)
    {
        var order = new Order(
            Guid.NewGuid(),
            request.CustomerId,
            request.Amount,
            "Created",
            DateTime.UtcNow);

        await _repository.AddAsync(order);
        return order;
    }

    public Task<bool> UpdateStatusAsync(Guid id, string status)
        => _repository.UpdateStatusAsync(id, status);
}
```

