## 5. In-memory service implementation: `Services/CustomerService.cs`

This is intentionally simple for an initial implementation. You can later replace it with SQL Server / Cosmos DB / PostgreSQL.

```csharp
using System.Collections.Concurrent;
using EnterpriseBackend.Api.Domain;

namespace EnterpriseBackend.Api.Services;

public sealed class CustomerService : ICustomerService
{
    private readonly ConcurrentDictionary<Guid, Customer> _customers = new();

    public Task<Customer?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        _customers.TryGetValue(id, out var customer);
        return Task.FromResult(customer);
    }

    public Task<IReadOnlyList<Customer>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        IReadOnlyList<Customer> customers = _customers.Values
            .OrderBy(c => c.LastName)
            .ThenBy(c => c.FirstName)
            .ToList();

        return Task.FromResult(customers);
    }

    public Task<Customer> CreateAsync(string firstName, string lastName, string email, CancellationToken cancellationToken = default)
    {
        var customer = new Customer(
            Id: Guid.NewGuid(),
            FirstName: firstName.Trim(),
            LastName: lastName.Trim(),
            Email: email.Trim(),
            CreatedUtc: DateTimeOffset.UtcNow
        );

        if (!_customers.TryAdd(customer.Id, customer))
        {
            throw new InvalidOperationException("Failed to create customer.");
        }

        return Task.FromResult(customer);
    }
}
```

