## 6. Controller: `Controllers/CustomersController.cs`

```csharp
using EnterpriseBackend.Api.Services;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/customers")]
public sealed class CustomersController : ControllerBase
{
    private readonly ICustomerService _customerService;
    private readonly ILogger<CustomersController> _logger;

    public CustomersController(ICustomerService customerService, ILogger<CustomersController> logger)
    {
        _customerService = customerService;
        _logger = logger;
    }

    [HttpGet]
    public async Task<IActionResult> GetAll(CancellationToken cancellationToken)
    {
        var customers = await _customerService.GetAllAsync(cancellationToken);
        return Ok(customers);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken cancellationToken)
    {
        var customer = await _customerService.GetByIdAsync(id, cancellationToken);

        if (customer is null)
            return NotFound();

        return Ok(customer);
    }

    public sealed record CreateCustomerRequest(string FirstName, string LastName, string Email);

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateCustomerRequest request, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.FirstName) ||
            string.IsNullOrWhiteSpace(request.LastName) ||
            string.IsNullOrWhiteSpace(request.Email))
        {
            return BadRequest(new { message = "FirstName, LastName, and Email are required." });
        }

        var customer = await _customerService.CreateAsync(
            request.FirstName,
            request.LastName,
            request.Email,
            cancellationToken);

        _logger.LogInformation("Created customer {CustomerId}", customer.Id);

        return CreatedAtAction(nameof(GetById), new { id = customer.Id }, customer);
    }
}
