using EnterpriseBackendService.Api.Models;

namespace EnterpriseBackendService.Api.Services;

public class OrderService : IOrderService
{
    private static readonly Dictionary<Guid, Order> Orders = new();

    public Task<Order> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken = default)
    {
        var order = new Order
        {
            Id = Guid.NewGuid(),
            CustomerId = request.CustomerId,
            Amount = request.Amount,
            CreatedAt = DateTimeOffset.UtcNow,
            Status = "Created"
        };

        Orders[order.Id] = order;
        return Task.FromResult(order);
    }

    public Task<Order?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        Orders.TryGetValue(id, out var order);
        return Task.FromResult(order);
    }
}
