## 6. Controller

### `Controllers/OrdersController.cs`

```csharp
using EnterpriseBackendService.Api.Models;
using EnterpriseBackendService.Api.Services;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackendService.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly IOrderService _orderService;
    private readonly ILogger<OrdersController> _logger;

    public OrdersController(IOrderService orderService, ILogger<OrdersController> logger)
    {
        _orderService = orderService;
        _logger = logger;
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<Order>> GetById(Guid id, CancellationToken cancellationToken)
    {
        var order = await _orderService.GetByIdAsync(id, cancellationToken);

        if (order is null)
        {
            return NotFound();
        }

        return Ok(order);
    }

    [HttpPost]
    public async Task<ActionResult<Order>> Create([FromBody] CreateOrderRequest request, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerId))
        {
            return BadRequest("CustomerId is required.");
        }

        if (request.Amount <= 0)
        {
            return BadRequest("Amount must be greater than zero.");
        }

        var order = await _orderService.CreateAsync(request, cancellationToken);

        _logger.LogInformation("Created order {OrderId} for customer {CustomerId}", order.Id, order.CustomerId);

        return CreatedAtAction(nameof(GetById), new { id = order.Id }, order);
    }
}
```

